class TestBase(unittest.TestCase):
    def setUp(self):
        self.base, self.client_id, self.rdv_id = base_de_test()

    def tearDown(self):
        self.base.fermer()

    def test_rendezvous_manques_sans_numero_en_clair(self):
        manques = self.base.rendezvous_manques()
        self.assertEqual(len(manques), 1)
        rdv = manques[0]
        self.assertEqual(rdv["telephone_masque"], "+33 6 •• •• •• 42")
        self.assertNotIn("telephone", rdv)  # le numéro brut ne sort pas d'ici

    def test_cycle_de_vie_appel(self):
        appel_id = self.base.creer_appel(self.rdv_id)
        self.assertEqual(self.base.obtenir_appel(appel_id)["statut"], "en file")
        resultat = {"appointment_status": "confirmed", "new_datetime": DEMAIN,
                    "notes": "ok", "duration_seconds": 60}
        self.base.terminer_appel(appel_id, "terminé", resultat, "Agent : Bonjour…")
        appel = self.base.obtenir_appel(appel_id)
        self.assertEqual(appel["statut"], "terminé")
        self.assertEqual(appel["resultat"]["appointment_status"], "confirmed")
        self.assertIn("Bonjour", appel["transcription"])

    def test_mise_a_jour_rendezvous(self):
        self.base.mettre_a_jour_rendezvous(self.rdv_id, statut="reprogrammé",
                                           horaire="2026-08-03T10:00")
        rdv = self.base.obtenir_rendezvous(self.rdv_id)
        self.assertEqual(rdv["statut"], "reprogrammé")
        self.assertEqual(rdv["horaire"], "2026-08-03T10:00")

    def test_a_venir_tous_et_detection_doublon(self):
        prevu = self.base.ajouter_rendezvous(self.client_id, DEMAIN, "Futur proche")
        lointain = self.base.ajouter_rendezvous(
            self.client_id, "2027-01-01T09:00", "Futur lointain")
        a_venir = self.base.rendezvous_a_venir()
        self.assertEqual([r["id"] for r in a_venir],
                         [prevu, lointain])            # « prévu » seulement, chronologique
        self.assertEqual(a_venir[0]["telephone_masque"], "+33 6 •• •• •• 42")
        tous = self.base.tous_les_rendezvous()
        self.assertEqual(len(tous), 3)                 # manqué compris : rien ne se perd
        self.assertEqual(tous[0]["id"], lointain)      # le plus récent d'abord
        identique = self.base.rendezvous_identique(
            "Mme Test Exemple", "+33 6 00 00 00 42", DEMAIN)
        self.assertEqual(identique["id"], self.rdv_id)  # même client + même horaire
        self.assertIsNone(self.base.rendezvous_identique(
            "Mme Test Exemple", "+33 6 00 00 00 42", "2030-01-01T08:00"))


class TestPersistance(unittest.TestCase):
    def setUp(self):
        self.dossier = tempfile.mkdtemp(prefix="ringback-test-")
        self.addCleanup(shutil.rmtree, self.dossier, ignore_errors=True)

    def test_reouverture_retrouve_les_donnees(self):
        # Le chemin traverse un sous-dossier inexistant : il doit être créé.
        chemin = os.path.join(self.dossier, "donnees", "ringback.db")
        base = db.Base(chemin)
        client_id = base.ajouter_client("Mme Persistance Durand", "+33 6 00 00 00 42")
        rdv_id = base.ajouter_rendezvous(client_id, DEMAIN, "Séance d'essai", statut="manqué")
        base.fermer()
        rouverte = db.Base(chemin)  # nouvelle connexion sur le même fichier
        manques = rouverte.rendezvous_manques()
        self.assertEqual(len(manques), 1)
        self.assertEqual(manques[0]["id"], rdv_id)
        self.assertEqual(manques[0]["nom"], "Mme Persistance Durand")
        self.assertEqual(manques[0]["telephone_masque"], "+33 6 •• •• •• 42")
        rouverte.fermer()

    def test_demo_inseree_seulement_si_base_vide(self):
        chemin = os.path.join(self.dossier, "ringback.db")
        premier = serveur.creer_serveur(port=0, chemin_base=chemin)
        base = premier.RequestHandlerClass.application.base
        nombre_demo = base.compter_clients()
        self.assertGreater(nombre_demo, 0)  # base neuve : démo insérée
        base.fermer()
        premier.server_close()
        second = serveur.creer_serveur(port=0, chemin_base=chemin)
        base = second.RequestHandlerClass.application.base
        self.assertEqual(base.compter_clients(), nombre_demo)  # pas de doublon
        base.fermer()
        second.server_close()


class TestDetectionManques(unittest.TestCase):
    def test_prevu_ou_confirme_passe_devient_manque(self):
        """Décision du propriétaire (Q6) : « Si c'est des dates dans le passé
        on peut donc marquer manqué » — le CONFIRMÉ passé bascule lui aussi,
        pour que plus personne ne se volatilise entre les deux listes."""
        base = db.Base(":memory:")
        client_id = base.ajouter_client("Mme Test Exemple", "+33 6 00 00 00 42")
        rdv_passe = base.ajouter_rendezvous(client_id, HIER, "Déjà passé")
        rdv_futur = base.ajouter_rendezvous(client_id, DEMAIN, "À venir")
        rdv_confirme = base.ajouter_rendezvous(client_id, HIER, "Honoré", statut="confirmé")
        rdv_confirme_futur = base.ajouter_rendezvous(
            client_id, DEMAIN, "Confirmé à venir", statut="confirmé")
        rdv_annule = base.ajouter_rendezvous(client_id, HIER, "Annulé", statut="annulé")
        # Le prévu passé ET le confirmé passé basculent ; ce qui est devant
        # nous ne bouge pas, et un annulé reste annulé (il ne prend plus de place).
        self.assertEqual(base.marquer_manques_echus(), 2)
        self.assertEqual(base.obtenir_rendezvous(rdv_passe)["statut"], "manqué")
        self.assertEqual(base.obtenir_rendezvous(rdv_confirme)["statut"], "manqué")
        self.assertEqual(base.obtenir_rendezvous(rdv_futur)["statut"], "prévu")
        self.assertEqual(base.obtenir_rendezvous(rdv_confirme_futur)["statut"],
                         "confirmé")
        self.assertEqual(base.obtenir_rendezvous(rdv_annule)["statut"], "annulé")
        self.assertEqual(base.marquer_manques_echus(), 0)  # rien de neuf au 2ᵉ passage
        base.fermer()

    def test_a_venir_garde_les_confirmes_avec_leur_pastille(self):
        """Décision du propriétaire (Q5) : « ce n'est pas un contact qui
        disparaît, mais une ligne qui évolue » — un rendez-vous confirmé
        RESTE dans « à venir », avec son statut."""
        base = db.Base(":memory:")
        client_id = base.ajouter_client("Mme Test Exemple", "+33 6 00 00 00 42")
        prevu = base.ajouter_rendezvous(client_id, DEMAIN, "À venir")
        confirme = base.ajouter_rendezvous(client_id, DEMAIN, "Confirmé",
                                           statut="confirmé")
        base.ajouter_rendezvous(client_id, HIER, "Déjà passé")
        base.marquer_manques_echus()
        vus = {rdv["id"]: rdv["statut"]
               for rdv in base.rendezvous_a_venir_tous()}
        self.assertEqual(vus, {prevu: "prévu", confirme: "confirmé"})
        # L'ancienne liste, elle, sert à COMPOSER une liste d'appel : elle
        # ne retient toujours que ce qui n'est pas encore confirmé.
        self.assertEqual([rdv["id"] for rdv in base.rendezvous_a_venir()],
                         [prevu])
        base.fermer()


class TestSaisie(unittest.TestCase):
    def test_telephone_normalise(self):
        self.assertEqual(saisie.valider_telephone("+33600000042"), "+33 6 00 00 00 42")
        self.assertEqual(saisie.valider_telephone("06.00-00 00.42"), "06 00 00 00 42")

    def test_telephone_invalide(self):
        for mauvais in ("", "abc", "12345", "+34 600 000 042", "06 00 00 00 4"):
            with self.assertRaises(saisie.SaisieInvalide):
                saisie.valider_telephone(mauvais)

    def test_horaire_formats_acceptes(self):
        self.assertEqual(saisie.valider_horaire("2026-08-01T14:30"), "2026-08-01T14:30")
        self.assertEqual(saisie.valider_horaire("2026-08-01 14:30"), "2026-08-01T14:30")
        self.assertEqual(saisie.valider_horaire("01/08/2026 14:30"), "2026-08-01T14:30")

    def test_horaire_illisible(self):
        with self.assertRaises(saisie.SaisieInvalide) as contexte:
            saisie.valider_horaire("bientôt")
        self.assertIn("Date illisible", str(contexte.exception))

    def test_erreurs_collectees_ensemble(self):
        _, erreurs = saisie.valider_entree("", "abc", "hier", "")
        self.assertEqual(len(erreurs), 4)  # les quatre champs sont signalés d'un coup


class TestImportCSV(unittest.TestCase):
    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)

    def test_import_valide(self):
        contenu = ("nom;telephone;date_heure;motif\n"
                   f"Mme Awa Diallo;+33 6 00 00 00 45;{HIER};Consultation\n"
                   f"M. Louis Bréval;0600000046;{DEMAIN};Contrôle vélo\n")
        importes, erreurs = saisie.importer_csv(self.base, contenu)
        self.assertEqual((importes, erreurs), (2, []))
        self.assertEqual(self.base.compter_clients(), 2)
        self.base.marquer_manques_echus()
        manques = self.base.rendezvous_manques()
        self.assertEqual(len(manques), 1)  # seule la ligne d'hier est manquée
        self.assertEqual(manques[0]["nom"], "Mme Awa Diallo")

    def test_import_reutilise_le_client_existant(self):
        contenu = ("nom;telephone;date_heure;motif\n"
                   f"Mme Awa Diallo;+33 6 00 00 00 45;{DEMAIN};Consultation\n")
        saisie.importer_csv(self.base, contenu)
        saisie.importer_csv(self.base, contenu)  # même fichier importé deux fois
        self.assertEqual(self.base.compter_clients(), 1)

    def test_lignes_fautives_rejetees_les_bonnes_importees(self):
        contenu = ("nom;telephone;date_heure;motif\n"
                   f"Mme Bonne Ligne;+33 6 00 00 00 45;{DEMAIN};Consultation\n"
                   f"M. Numero Faux;12345;{DEMAIN};Consultation\n"
                   "Mme Date Fausse;+33 6 00 00 00 46;bientôt;Consultation\n"
                   "M. Colonnes Manquantes;+33 6 00 00 00 47\n")
        importes, erreurs = saisie.importer_csv(self.base, contenu)
        self.assertEqual(importes, 1)
        self.assertEqual(len(erreurs), 3)
        self.assertIn("Ligne 3", erreurs[0])
        self.assertIn("Numéro de téléphone invalide", erreurs[0])
        self.assertIn("Ligne 4", erreurs[1])
        self.assertIn("Date illisible", erreurs[1])
        self.assertIn("Ligne 5", erreurs[2])
        self.assertIn("colonne(s)", erreurs[2])

    def test_entete_invalide_refuse(self):
        with self.assertRaises(saisie.SaisieInvalide) as contexte:
            saisie.importer_csv(self.base, "prenom;tel\nA;B\n")
        self.assertIn("En-tête invalide", str(contexte.exception))

    def test_fichier_vide_refuse(self):
        with self.assertRaises(saisie.SaisieInvalide):
            saisie.importer_csv(self.base, "\n\n")

    def test_fichier_exemple_fourni_est_importable(self):
        chemin = os.path.join(RACINE, "exemple_import.csv")
        with open(chemin, encoding="utf-8") as fichier:
            importes, erreurs = saisie.importer_csv(self.base, fichier.read())
        self.assertEqual(erreurs, [])
        self.assertEqual(importes, 4)


class TestAppelSimule(unittest.TestCase):
    def test_resultat_toujours_conforme_au_schema(self):
        simulateur = calle_client.AppelSimule(graine=7, latence=0)
        rdv = {"horaire": DEMAIN, "motif": "Essai"}
        vus = 0
        for _ in range(20):
            try:
                issue = simulateur.appeler("Mme Test", "+33 6 00 00 00 42", rdv)
            except calle_client.PasDeReponse:
                # « Ne décroche pas » n'a pas de résultat à valider : c'est une
                # issue de la suite depuis le 10/08/2026 (voir SUITE_RAPPEL).
                continue
            vus += 1
            calle_client.valider_resultat(issue.resultat)  # ne doit pas lever
            self.assertIn(issue.resultat["appointment_status"], calle_client.STATUTS_VALIDES)
            self.assertTrue(issue.transcription.startswith("Agent :"))
            self.assertNotIn("+33 6 00 00 00 42", issue.transcription)  # jamais en clair
        self.assertGreater(vus, 15)   # la plupart des appels aboutissent

    def test_toutes_les_issues_apparaissent_l_attendue_en_tete(self):
        """⚠ LA DEMANDE DU 10/08/2026, mot pour mot : « surtout des réponses
        attendues selon les campagnes, mais aussi un peu de chaque autre
        réponse que l'on peut produire. C'est important pour les tests. »

        Avant, le tirage ne portait que sur TROIS issues sur quatre :
        « to_reschedule » ne sortait jamais et « ne décroche pas » non plus —
        une campagne simulée ne montrait donc pas deux des chemins que le
        produit sait traiter.
        """
        simulateur = calle_client.AppelSimule(graine=1, latence=0)
        rdv = {"horaire": DEMAIN, "motif": "Essai"}
        compte = {}
        for _ in range(len(calle_client.SUITE_RAPPEL)):
            try:
                resultat = simulateur.appeler(
                    "Mme Test", "+33 6 00 00 00 42", rdv).resultat
            except calle_client.PasDeReponse:
                compte["pas de réponse"] = compte.get("pas de réponse", 0) + 1
                continue
            statut = resultat["appointment_status"]
            compte[statut] = compte.get(statut, 0) + 1
            if statut in ("canceled", "to_reschedule"):
                # « Rien n'est convenu » n'a pas de date, par définition.
                self.assertIsNone(resultat["new_datetime"])
            else:
                datetime.datetime.fromisoformat(resultat["new_datetime"])
        # LES QUATRE STATUTS, plus le « ne décroche pas ».
        self.assertEqual(set(compte),
                         set(calle_client.STATUTS_VALIDES) | {"pas de réponse"})
        # L'ATTENDUE DOMINE : plus de la moitié, mais pas tout.
        total = sum(compte.values())
        self.assertGreater(compte["confirmed"], total / 2)
        self.assertLess(compte["confirmed"], total)

    def test_la_suite_des_issues_est_reproductible(self):
        """⚠ C'EST LE POINT DE LA DEMANDE (« important pour les tests ») : un
        tirage au sort donnerait un nombre d'échecs qui change d'une exécution à
        l'autre, et un contrôle qui les compte deviendrait instable sans que
        rien n'ait bougé dans le produit."""
        rdv = {"horaire": DEMAIN, "motif": "Essai"}

        def vingt():
            simulateur = calle_client.AppelSimule(graine=None, latence=0)
            issues = []
            for _ in range(20):
                try:
                    issues.append(simulateur.appeler(
                        "X", "+33 6 00 00 00 42", rdv
                    ).resultat["appointment_status"])
                except calle_client.PasDeReponse:
                    issues.append("pas de réponse")
            return issues

        # ⚠ MÊME SANS GRAINE : la suite ne dépend pas du hasard.
        self.assertEqual(vingt(), vingt())
        # Une autre issue arrive TÔT : une campagne de cinq personnes doit déjà
        # montrer autre chose qu'une rangée de oui.
        self.assertGreater(len(set(vingt()[:5])), 1)

    def test_les_terminaisons_forcees_priment_toujours(self):
        """La suite écrite ne doit pas voler la place des terminaisons : elles
        sont le seul moyen d'exiger UNE issue précise dans un contrôle."""
        simulateur = calle_client.AppelSimule(graine=1, latence=0)
        rdv = {"horaire": DEMAIN, "motif": "Essai"}
        for fin, attendu in (("51", "confirmed"), ("52", "canceled"),
                             ("54", "rescheduled"), ("55", "to_reschedule")):
            with self.subTest(terminaison=fin):
                resultat = simulateur.appeler(
                    "X", f"+33 6 00 00 00 {fin}", rdv).resultat
                self.assertEqual(resultat["appointment_status"], attendu)
        with self.assertRaises(calle_client.PasDeReponse):
            simulateur.appeler("X", "+33 6 00 00 00 53", rdv)

    def test_la_cascade_montre_ses_quatre_issues_aussi(self):
        simulateur = calle_client.AppelSimule(graine=1, latence=0)
        compte = {}
        for _ in range(len(calle_client.SUITE_CASCADE)):
            try:
                issue = simulateur.appeler_cascade(
                    "X", "+33 6 00 00 00 42", "Une place se libère",
                    DEMAIN).resultat["outcome"]
            except calle_client.PasDeReponse:
                issue = "pas de réponse"
            compte[issue] = compte.get(issue, 0) + 1
        self.assertEqual(set(compte),
                         set(calle_client.ISSUES_CASCADE) | {"pas de réponse"})
        self.assertGreater(compte["accepted"], sum(compte.values()) / 2)

    def test_validation_refuse_statut_inconnu(self):
        with self.assertRaises(calle_client.ResultatInvalide):
            calle_client.valider_resultat({"appointment_status": "maybe", "new_datetime": None,
                                           "notes": "", "duration_seconds": 10})

    def test_validation_refuse_champ_manquant(self):
        with self.assertRaises(calle_client.ResultatInvalide):
            calle_client.valider_resultat({"appointment_status": "confirmed"})

    def test_la_terminaison_59_rend_une_reponse_illisible_avec_sa_conversation(self):
        """« 59 » : la conversation a eu lieu, la réponse est illisible.

        Le seul cas de figure qu'une campagne simulée ne joue pas d'elle-même
        (il la met en pause). Il doit donc s'obtenir par un numéro — et garder
        la conversation, sans quoi on perdrait une seconde fois ce que la
        personne a dit.
        """
        simulateur = calle_client.AppelSimule(graine=1, latence=0)
        rdv = {"horaire": DEMAIN, "motif": "Essai"}
        for geste in (lambda: simulateur.appeler("Mme X", "+33 6 00 00 00 59",
                                                 rdv),
                      lambda: simulateur.appeler_cascade(
                          "Mme X", "+33 6 00 00 00 59", "Une place", DEMAIN)):
            with self.subTest(geste=geste):
                with self.assertRaises(calle_client.ResultatInvalide) as refus:
                    geste()
                self.assertTrue(refus.exception.transcription.startswith(
                    "Agent :"))
                self.assertIn("aucune issue", str(refus.exception))


class TestCasDeFigureParNature(unittest.TestCase):
    """⚠ LA DEMANDE DU 11/08/2026, mot pour mot : « en mode simulation, selon le
    type de campagne, on génère tout les cas de figure possible pour que je
    puisse tester en théorie le comportement de tout ces résultats. Fait le pour
    toutes les campagnes. »

    LE DÉFAUT QUE CES ESSAIS INTERDISENT : SUITE_CASCADE commençait par
    « accepted ». Sur une campagne « premier oui », le premier appel pourvoyait
    donc la place et la campagne s'arrêtait — les autres cas de figure ne
    partaient JAMAIS. Le propriétaire l'a constaté : « il n'a engendré que les
    cas de figure accepté et refusé au lieu de tout les cas de figure ». Ce
    n'était pas une affaire de proportions, mais d'ORDRE.
    """

    # Ce qui ARRÊTE une campagne « premier oui », par chemin — la liste vient de
    # assistant._appliquer_issue (les branches qui rendent « pourvu »).
    CONCLUANTS = {"cascade": {"accepted"},
                  "rappel": {"confirmed", "rescheduled"}}
    PREMIER_OUI = ("creneau_libere", "deplacement")

    def _marqueur(self, resultat, cascade):
        """Le cas de figure tel qu'on le LIT sur le résultat rendu."""
        issue = resultat["outcome"] if cascade else resultat["appointment_status"]
        if resultat.get(calle_client.CHAMP_NE_PLUS_APPELER) == "yes":
            issue += calle_client.SUFFIXE_STOP
        if resultat.get(calle_client.CHAMP_AUTRES_PLACES) == "no":
            issue += calle_client.SUFFIXE_SANS_PROPOSITION
        return issue

    def _campagne(self, simulateur, nature, contacts,
                  arret_au_premier_oui=None):
        """Joue une campagne de cette nature ; rend les cas de figure vus.

        Elle s'arrête comme la vraie : sur « premier oui », au premier appel
        qui aboutit.

        `arret_au_premier_oui` : pour jouer la MÊME nature sous son autre
        réglage, « appeler toute la liste ». C'est un vrai réglage du produit,
        pas une commodité d'essai — et depuis le 16/08/2026 c'est le seul sous
        lequel un déplacement montre tous ses cas (voir PREMIER_IMPOSE).
        """
        cas = calle_client.SUITES_PAR_NATURE[nature]
        cascade = cas["chemin"] == "cascade"
        simulateur.recommencer_les_cas(nature, contacts)
        vus = []
        # ⚠ LE MÊME NUMÉRO POUR TOUT LE MONDE, et c'est voulu. La série
        # documentée n'autorise que ses DEUX DERNIERS chiffres à varier
        # (+33 6 00 00 00 XX) — vingt numéros distincts hors de la plage
        # réservée 51-59 n'existent donc pas dans cette série, et le contrôle de
        # publication refuse tout autre numéro en clair. Ce n'est pas une
        # concession : ici on mesure la LISTE de la nature, pas la terminaison.
        telephone = "+33 6 00 00 00 42"
        for rang in range(contacts):
            try:
                if cascade:
                    issue = simulateur.appeler_cascade(
                        f"Personne {rang}", telephone, "Une place se libère",
                        DEMAIN, nature=nature)
                else:
                    issue = simulateur.appeler(
                        f"Personne {rang}", telephone,
                        {"horaire": DEMAIN, "motif": "Essai"}, nature=nature)
            except calle_client.PasDeReponse:
                vus.append(calle_client.PAS_DE_REPONSE)
                continue
            vu = self._marqueur(issue.resultat, cascade)
            vus.append(vu)
            arrete = (nature in self.PREMIER_OUI
                      if arret_au_premier_oui is None else arret_au_premier_oui)
            if arrete and vu.split("+")[0] in self.CONCLUANTS[cas["chemin"]]:
                break
        return vus

    # ⚠ LE PRIX DE SA DÉCISION DU 16/08/2026, ÉCRIT PLUTÔT QUE TU.
    # Il a demandé que le premier appel simulé d'un DÉPLACEMENT et d'une PRISE
    # DE RENDEZ-VOUS aboutisse (voir TestPremierAppelSimuleAboutit). Sur une
    # prise de rendez-vous, tout le monde est appelé : la campagne continue et
    # montre ensuite tous ses cas — rien n'est perdu.
    #
    # Sur un DÉPLACEMENT réglé « arrêt au premier OUI » — son réglage par
    # défaut — un premier appel qui aboutit TERMINE la campagne. Les autres cas
    # simulés n'y paraissent donc plus jamais. Choix assumé, posé après lui
    # avoir montré la mesure : « toujours positif au 1er appel ».
    #
    # Ils restent atteignables en réglant « appeler toute la liste » à l'étape
    # 2 — et c'est sous ce réglage que ce contrôle les vérifie, sans quoi il ne
    # vérifierait plus rien du tout.
    PREMIER_IMPOSE = ("deplacement", "prise_rdv")

    def test_chaque_nature_montre_tous_ses_cas_de_figure(self):
        """Vingt contacts : tout ce que la nature déclare doit être passé."""
        for nature in calle_client.SUITES_PAR_NATURE:
            with self.subTest(nature=nature):
                simulateur = calle_client.AppelSimule(graine=1, latence=0)
                # Une nature dont le premier appel aboutit se juge « toute la
                # liste » : au premier oui, il n'y aurait qu'UN appel.
                premier_oui = (nature in self.PREMIER_OUI
                               and nature not in self.PREMIER_IMPOSE)
                vus = self._campagne(simulateur, nature, 20,
                                     arret_au_premier_oui=premier_oui)
                manquants = [cas for cas in calle_client.issues_simulees(nature)
                             if cas not in vus]
                # « Premier oui » : une seule issue concluante peut partir par
                # campagne, la seconde vient à la campagne suivante (rotation).
                if premier_oui:
                    vus += self._campagne(simulateur, nature, 20)
                    manquants = [cas
                                 for cas in calle_client.issues_simulees(nature)
                                 if cas not in vus]
                self.assertEqual(manquants, [])

    def test_un_deplacement_au_premier_oui_s_arrete_au_premier_appel(self):
        """⚠ LA CONSÉQUENCE, CONTRÔLÉE PLUTÔT QUE SUBIE. C'est ce qu'il a
        choisi en connaissance de cause : un seul appel, et il aboutit."""
        simulateur = calle_client.AppelSimule(graine=1, latence=0)
        vus = self._campagne(simulateur, "deplacement", 20,
                             arret_au_premier_oui=True)
        self.assertEqual(len(vus), 1, vus)
        self.assertIn(vus[0].split("+")[0], self.CONCLUANTS["rappel"])

    def test_une_petite_campagne_montre_quand_meme_sa_place_pourvue(self):
        """⚠ CINQ CONTACTS ET SEPT CAS. Le tour est taillé à la campagne : il
        s'arrête assez tôt pour que le cas CONCLUANT parte — sans quoi une
        campagne de cinq personnes ne pourvoyait jamais sa place — et la
        campagne suivante reprend le tour là où celle-ci l'a laissé.
        """
        simulateur = calle_client.AppelSimule(graine=1, latence=0)
        premiere = self._campagne(simulateur, "creneau_libere", 5)
        self.assertEqual(premiere[-1], "accepted")
        seconde = self._campagne(simulateur, "creneau_libere", 5)
        self.assertEqual(seconde[-1], "accepted")
        # Les cas que la première n'a pas eu la place de jouer sont passés à la
        # seconde : en deux campagnes de cinq, les sept cas sont vus.
        manquants = [cas for cas in calle_client.issues_simulees("creneau_libere")
                     if cas not in premiere + seconde]
        self.assertEqual(manquants, [])

    def test_les_cas_declares_couvrent_les_enum_du_schema(self):
        """CLIQUET. Une issue ajoutée à un schéma sans être jouée par aucune
        nature passerait inaperçue : ce contrôle la nomme.
        """
        enums = {
            "cascade": calle_client.SCHEMA_RESULTAT_CASCADE[
                "properties"]["outcome"]["enum"],
            "rappel": calle_client.SCHEMA_RESULTAT[
                "properties"]["appointment_status"]["enum"]}
        for nature, cas in calle_client.SUITES_PAR_NATURE.items():
            with self.subTest(nature=nature):
                joues = {marqueur.split("+")[0]
                         for marqueur in calle_client.issues_simulees(nature)}
                attendus = set(enums[cas["chemin"]]) | {
                    calle_client.PAS_DE_REPONSE}
                self.assertEqual(joues, attendus)
                # Et le 🚫 est joué partout : c'est un fait sur la personne,
                # pas une particularité de nature.
                self.assertTrue(any(calle_client.SUFFIXE_STOP in marqueur
                                    for marqueur
                                    in calle_client.issues_simulees(nature)))

    def test_le_muet_n_est_joue_que_sur_la_cascade(self):
        """🔇 « ne me proposez plus de place » n'existe QUE dans le schéma de
        cascade : le jouer ailleurs produirait un champ hors schéma."""
        for nature, cas in calle_client.SUITES_PAR_NATURE.items():
            with self.subTest(nature=nature):
                muet = any(calle_client.SUFFIXE_SANS_PROPOSITION in marqueur
                           for marqueur in calle_client.issues_simulees(nature))
                self.assertEqual(muet, cas["chemin"] == "cascade")

    def test_sans_nature_la_suite_generique_reste_en_place(self):
        """File d'appels, rappel individuel, essai réel : pas de nature, donc la
        suite d'avant — l'attendu en tête. Rien de ce qui marchait ne change."""
        simulateur = calle_client.AppelSimule(graine=1, latence=0)
        rdv = {"horaire": DEMAIN, "motif": "Essai"}
        premier = simulateur.appeler("X", "+33 6 00 00 00 42", rdv)
        self.assertEqual(premier.resultat["appointment_status"],
                         calle_client.SUITE_RAPPEL[0])

    def test_le_client_reel_accepte_la_nature_sans_s_en_servir(self):
        """La nature ne part JAMAIS chez CALL-E : elle ne sert qu'à scénariser.

        Le contrôle porte sur le contrat, pas sur un appel : le client réel doit
        accepter l'argument (sinon toute campagne tombe) et l'interface doit
        porter recommencer_les_cas (sinon c'est la campagne qui tombe).
        """
        signature = inspect.signature(calle_client.AppelReel.appeler)
        self.assertIn("nature", signature.parameters)
        signature = inspect.signature(calle_client.AppelReel.appeler_cascade)
        self.assertIn("nature", signature.parameters)
        # Le geste ne fait rien sur l'interface, et surtout il ne lève pas.
        self.assertIsNone(
            calle_client.ClientAppels().recommencer_les_cas("creneau_libere", 5))



class TestCleCalleProtegee(unittest.TestCase):
    """La clé CALL-E : elle ne sort nulle part, et on dit laquelle sert.

    ⚠ NÉ DU 03/09/2026. Sa campagne s'arrête sur un refus de CALL-E ; il colle
    sa clé dans les Réglages, relance, obtient le même refus. Ici les deux
    sources portaient la même clé, donc ce n'était pas la cause — mais le
    piège, lui, était à un cheveu : la variable d'environnement gagne toujours
    contre le fichier, SANS LE DIRE.
    """

    MARQUE = "iams_MARQUE_DE_FUITE_0123456789abcdefghij"

    def test_la_cle_n_apparait_dans_AUCUN_texte_montre(self):
        """⚠ MESURÉ, PAS PROMIS : on cherche la clé dans ce qui sort.

        `decrire_cle` promet de ne jamais la montrer. Une promesse ne tient
        que si on la vérifie sur ce que le produit produit RÉELLEMENT : la
        description, l'état d'écran, et les messages de refus — ceux-là mêmes
        qu'on recopie dans un mail au support.
        """
        with sans_aucune_cle_calle():
            with open(calle_client.CHEMIN_CLE, "w", encoding="utf-8") as f:
                f.write(self.MARQUE)
            sorties = [
                calle_client.decrire_cle(self.MARQUE),
                repr(calle_client.etat_de_la_cle()),
            ]
            for mauvaise in ("http://dashboard.heycall-e.com", "court"):
                try:
                    calle_client.valider_forme_cle(mauvaise)
                except calle_client.CleApiAbsente as refus:
                    sorties.append(str(refus))
            try:
                calle_client.ranger_cle("http://dashboard.heycall-e.com")
            except calle_client.CleApiAbsente as refus:
                sorties.append(str(refus))
            for texte in sorties:
                self.assertNotIn(self.MARQUE, texte, texte[:120])
            # ⚠ ET LA DESCRIPTION DOIT QUAND MÊME ÊTRE UTILE : « 41
            # caractère(s) » permet de reconnaître SA clé sans la lire.
            self.assertIn(str(len(self.MARQUE)),
                          calle_client.decrire_cle(self.MARQUE))

    def test_une_cle_rangee_qui_ne_SERT_pas_est_annoncee(self):
        """⚠ LE PIÈGE : coller une clé, et qu'une autre continue de servir.

        On ne change pas qui gagne — un essai ponctuel par variable DOIT
        primer. On exige seulement que le produit le dise.
        """
        with sans_aucune_cle_calle():
            calle_client.ranger_cle(self.MARQUE)
            # Sans variable : c'est bien la clé rangée qui sert, rien à dire.
            self.assertEqual(calle_client.cle_ignoree(), "")
            self.assertEqual(calle_client.etat_de_la_cle()["ignoree"], "")

            autre = "iams_UNE_TOUTE_AUTRE_CLE_9876543210"
            os.environ["CALLE_API_KEY"] = autre
            try:
                # La variable gagne — ça, c'est inchangé et voulu.
                cle, source = calle_client.cle_disponible()
                self.assertEqual(cle, autre)
                self.assertEqual(source, calle_client.SOURCE_VARIABLE)
                # ⚠ ET LA CLÉ MISE DE CÔTÉ EST NOMMÉE, sans être montrée.
                self.assertEqual(calle_client.cle_ignoree(), self.MARQUE)
                decrite = calle_client.etat_de_la_cle()["ignoree"]
                self.assertTrue(decrite)
                self.assertNotIn(self.MARQUE, decrite)

                # ⚠ MÊME CLÉ DES DEUX CÔTÉS = AUCUN CONFLIT. C'était son cas
                # réel du 03/09 : le dire aurait été un faux signal.
                os.environ["CALLE_API_KEY"] = self.MARQUE
                self.assertEqual(calle_client.cle_ignoree(), "")
            finally:
                os.environ.pop("CALLE_API_KEY", None)


class TestGardeFous(unittest.TestCase):
    def setUp(self):
        self.base, self.client_id, self.rdv_id = base_de_test()
        self._cle_sauvee = os.environ.pop("CALLE_API_KEY", None)

    def tearDown(self):
        self.base.fermer()
        if self._cle_sauvee is not None:
            os.environ["CALLE_API_KEY"] = self._cle_sauvee

    def test_client_reel_sans_cle_refuse(self):
        # ⚠ LES DEUX SOURCES : la variable ET le fichier. Voir
        # `sans_aucune_cle_calle` — retirer la variable seule ne suffisait
        # pas, et l'essai dépendait du dossier `donnees/` de la machine.
        with sans_aucune_cle_calle():
            with self.assertRaises(calle_client.CleApiAbsente) as contexte:
                calle_client.AppelReel()
        self.assertIn("mode simulation actif", str(contexte.exception))

    def test_la_cle_RANGEE_DANS_LE_FICHIER_suffit(self):
        """L'autre moitié de la règle : le fichier vaut la variable.

        ⚠ SANS CET ESSAI, LE PRÉCÉDENT PASSE POUR UNE MAUVAISE RAISON. Un
        montage qui coupe tout ne prouve pas que le fichier est lu ; il
        prouve seulement qu'il n'y a rien. On vérifie donc les deux sens.
        """
        with sans_aucune_cle_calle():
            with self.assertRaises(calle_client.CleApiAbsente):
                calle_client.AppelReel()
            with open(calle_client.CHEMIN_CLE, "w", encoding="utf-8") as f:
                f.write("cle-de-test-0123456789\n")
            client = calle_client.AppelReel()
            self.assertEqual(client.cle_api, "cle-de-test-0123456789")
            _, source = calle_client.cle_disponible()
            self.assertEqual(source, calle_client.SOURCE_FICHIER)

    def test_dry_run_bloque_les_appels_reels(self):
        reel = calle_client.AppelReel(cle_api="cle-de-test-0123456789")  # clé factice, jamais utilisée
        planif = planificateur.Planificateur(self.base, reel)  # dry_run=True par défaut
        planif.programmer(self.rdv_id)
        with self.assertRaises(planificateur.GardeFou):
            planif.executer()

    def test_confirmation_explicite_obligatoire(self):
        reel = calle_client.AppelReel(cle_api="cle-de-test-0123456789")
        planif = planificateur.Planificateur(self.base, reel, dry_run=False)
        planif.programmer(self.rdv_id)
        with self.assertRaises(planificateur.GardeFou):
            planif.executer()  # dry_run levé mais pas de confirmation → refus

    def test_annulation_avant_execution(self):
        planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=3, latence=0))
        appel_id = planif.programmer(self.rdv_id)
        self.assertTrue(planif.annuler(appel_id))
        self.assertEqual(planif.executer(), [])  # plus rien à traiter
        self.assertEqual(self.base.obtenir_appel(appel_id)["statut"], "annulé")


class TestPlanificateurSimule(unittest.TestCase):
    def test_appel_simule_de_bout_en_bout(self):
        base, _, rdv_id = base_de_test()
        planif = planificateur.Planificateur(
            base, calle_client.AppelSimule(graine=5, latence=0))
        appel_id = planif.programmer(rdv_id)
        self.assertEqual(planif.executer(), [appel_id])
        appel = base.obtenir_appel(appel_id)
        self.assertEqual(appel["statut"], "terminé")
        calle_client.valider_resultat(appel["resultat"])  # résultat stocké conforme
        self.assertTrue(appel["transcription"])
        rdv = base.obtenir_rendezvous(rdv_id)
        # « déplacé » : décalage intelligent — l'ancien garde ce statut,
        # un nouveau rendez-vous est créé à la date convenue.
        self.assertIn(rdv["statut"], ("confirmé", "déplacé", "annulé"))
        base.fermer()

    def test_programmer_tous_les_manques_sans_doublon(self):
        base, client_id, _ = base_de_test()   # un premier manqué
        base.ajouter_rendezvous(client_id, HIER, "Deuxième manqué", statut="manqué")
        planif = planificateur.Planificateur(
            base, calle_client.AppelSimule(graine=2, latence=0))
        crees = planif.programmer_tous_les_manques()
        self.assertEqual(len(crees), 2)                          # les deux manqués
        self.assertEqual(planif.programmer_tous_les_manques(), [])  # déjà en file
        self.assertEqual(len(planif.file_detaillee()), 2)
        base.fermer()

    def test_executer_seulement_un_appel_laisse_la_file_intacte(self):
        base, client_id, rdv_id = base_de_test()
        autre_rdv = base.ajouter_rendezvous(client_id, HIER, "Autre manqué", statut="manqué")
        planif = planificateur.Planificateur(
            base, calle_client.AppelSimule(graine=4, latence=0))
        premier = planif.programmer(rdv_id)
        second = planif.programmer(autre_rdv)
        self.assertEqual(planif.executer(seulement=premier), [premier])
        restants = [entree["appel_id"] for entree in planif.file]
        self.assertEqual(restants, [second])  # le second attend toujours
        self.assertEqual(base.obtenir_appel(second)["statut"], "en file")
        base.fermer()

    def test_bilan_issues_compte_juste(self):
        base, _, rdv_id = base_de_test()
        # Un appel abouti (confirmé), un échec, un annulé avant exécution.
        abouti = base.creer_appel(rdv_id)
        base.terminer_appel(abouti, "terminé",
                            {"appointment_status": "confirmed", "new_datetime": DEMAIN,
                             "notes": "ok", "duration_seconds": 60}, "…")
        rate = base.creer_appel(rdv_id)
        base.terminer_appel(rate, "échec")
        annule = base.creer_appel(rdv_id)
        base.changer_statut_appel(annule, "annulé")
        bilan = base.bilan_issues()
        self.assertEqual(bilan, {"confirmed": 1, "rescheduled": 0,
                                 "canceled": 0, "to_reschedule": 0,
                                 "echec": 1})  # l'annulé ne compte pas
        base.fermer()


class TestSimulateurDeterministe(unittest.TestCase):
    """Convention : les numéros finissant par 51-54 forcent l'issue."""

    def setUp(self):
        self.simulateur = calle_client.AppelSimule(graine=9, latence=0)
        self.rdv = {"horaire": DEMAIN, "motif": "Essai"}
        self.horaire = datetime.datetime.fromisoformat(DEMAIN)

    def test_51_confirme_toujours(self):
        for _ in range(3):
            resultat = self.simulateur.appeler(
                "Mme Accord", "+33 6 00 00 00 51", self.rdv).resultat
            self.assertEqual(resultat["appointment_status"], "confirmed")

    def test_52_annule_toujours(self):
        resultat = self.simulateur.appeler(
            "M. Refus", "+33 6 00 00 00 52", self.rdv).resultat
        self.assertEqual(resultat["appointment_status"], "canceled")
        self.assertIsNone(resultat["new_datetime"])

    def test_53_ne_decroche_jamais(self):
        with self.assertRaises(calle_client.PasDeReponse):
            self.simulateur.appeler("Mme Silence", "+33 6 00 00 00 53", self.rdv)

    def test_54_deplace_avec_date_deterministe(self):
        attendu = (self.horaire + datetime.timedelta(days=2)).replace(
            hour=9, minute=30).isoformat(timespec="minutes")
        for _ in range(2):  # même issue ET même date à chaque appel
            resultat = self.simulateur.appeler(
                "M. Report", "+33 6 00 00 00 54", self.rdv).resultat
            self.assertEqual(resultat["appointment_status"], "rescheduled")
            self.assertEqual(resultat["new_datetime"], attendu)

    def test_cascade_51_accepte_et_53_sans_reponse(self):
        issue = self.simulateur.appeler_cascade(
            "Mme Accord", "+33 6 00 00 00 51", "Un créneau s'est libéré.", DEMAIN)
        calle_client.valider_resultat_cascade(issue.resultat)
        self.assertEqual(issue.resultat["outcome"], "accepted")
        self.assertIsNone(issue.resultat["new_datetime"])
        self.assertNotIn("+33 6 00 00 00 51", issue.transcription)  # jamais en clair
        with self.assertRaises(calle_client.PasDeReponse):
            self.simulateur.appeler_cascade(
                "Mme Silence", "+33 6 00 00 00 53", "Un créneau s'est libéré.", DEMAIN)

    def test_cascade_54_autre_date_deterministe(self):
        attendu = (self.horaire + datetime.timedelta(days=2)).replace(
            hour=9, minute=30).isoformat(timespec="minutes")
        issue = self.simulateur.appeler_cascade(
            "M. Report", "+33 6 00 00 00 54", "Un créneau s'est libéré.", DEMAIN)
        self.assertEqual(issue.resultat["outcome"], "moved")
        self.assertEqual(issue.resultat["new_datetime"], attendu)

    def test_55_veut_deplacer_sans_conclure(self):
        """« 55 » : le client veut déplacer mais AUCUNE date n'est convenue."""
        for _ in range(2):
            resultat = self.simulateur.appeler(
                "Mme Indecise", "+33 6 00 00 00 55", self.rdv).resultat
            self.assertEqual(resultat["appointment_status"], "to_reschedule")
            self.assertIsNone(resultat["new_datetime"])  # rien n'est conclu

    def test_56_pas_de_reponse_puis_accepte(self):
        """« 56 » : premier appel sans réponse, le suivant aboutit (relance)."""
        with self.assertRaises(calle_client.PasDeReponse):
            self.simulateur.appeler("M. Occupe", "+33 6 00 00 00 56", self.rdv)
        resultat = self.simulateur.appeler(
            "M. Occupe", "+33 6 00 00 00 56", self.rdv).resultat
        self.assertEqual(resultat["appointment_status"], "confirmed")

    def test_to_reschedule_refuse_avec_date(self):
        with self.assertRaises(calle_client.ResultatInvalide):
            calle_client.valider_resultat(
                {"appointment_status": "to_reschedule", "new_datetime": DEMAIN,
                 "notes": "", "duration_seconds": 10})

    def test_validation_cascade_refuse_hors_schema(self):
        with self.assertRaises(calle_client.ResultatInvalide):
            calle_client.valider_resultat_cascade(
                {"outcome": "maybe", "new_datetime": None,
                 "notes": "", "duration_seconds": 10})
        # ⚠ CET ESSAI VERROUILLAIT LE DÉFAUT : il exigeait qu'un « moved »
        # sans date soit REFUSÉ, et c'est ce refus qui a fait échouer le 8ᵉ
        # essai réel du 02/08/2026 — la personne avait juste demandé qu'on
        # lui répète la date. « Veut autre chose, rien n'est convenu » se lit
        # très bien : c'est to_reschedule, la 4ᵉ issue de cascade.
        lu = calle_client.valider_resultat_cascade(
            {"outcome": "moved", "new_datetime": None, "notes": ""})
        self.assertEqual(lu["outcome"], "to_reschedule")


class TestDecalageIntelligent(unittest.TestCase):
    """Une date convenue au téléphone DÉPLACE la ligne — elle n'en crée pas
    une seconde.

    ⚠ CET ESSAI DISAIT L'INVERSE, et il verrouillait le défaut n° 4 du 18/08.
    Il exigeait que l'ancienne ligne reste « déplacé » à sa date et qu'une
    SECONDE naisse à la date convenue. Son constat du 17/08/2026 : « le premier
    rendez-vous n'a pas été annulé, mais on l'a bien ajouté pour le
    lendemain » — sa journée ne se vidait qu'à moitié.

    La règle, c'est la sienne, du 14/08/2026 : « tu déplaces un rendez-vous
    d'une date à une autre, c'est ultra simple ». Elle était déjà écrite dans
    deux chemins sur quatre.
    """

    def test_une_date_convenue_deplace_la_ligne_sans_en_creer_une_seconde(self):
        base = db.Base(":memory:")
        client_id = base.ajouter_client("M. Report Exemple", "+33 6 00 00 00 54")
        rdv_id = base.ajouter_rendezvous(client_id, DEMAIN, "Séance à déplacer",
                                         statut="manqué")
        planif = planificateur.Planificateur(
            base, calle_client.AppelSimule(graine=1, latence=0))
        appel_id = planif.programmer(rdv_id)
        self.assertEqual(planif.executer(), [appel_id])
        # UNE SEULE LIGNE pour ce client, et c'est la même qu'avant.
        lignes = base.conn.execute(
            "SELECT * FROM rendezvous WHERE client_id = ?",
            (client_id,)).fetchall()
        self.assertEqual(len(lignes), 1, "une seconde ligne a été créée")
        self.assertEqual(lignes[0]["id"], rdv_id)
        # Elle a changé d'heure, et elle porte l'accord obtenu.
        attendu = (datetime.datetime.fromisoformat(DEMAIN)
                   + datetime.timedelta(days=2)).replace(hour=9, minute=30)
        self.assertEqual(lignes[0]["horaire"],
                         attendu.isoformat(timespec="minutes"))
        self.assertEqual(lignes[0]["statut"], "confirmé")
        self.assertEqual(lignes[0]["motif"], "Séance à déplacer")
        # ⚠ ET PLUS PERSONNE N'EST « déplacé » : ce mot désigne, partout
        # ailleurs, quelqu'un dont le rendez-vous a bougé SANS nouvelle date —
        # donc qui ATTEND (db.STATUTS_A_RECASER, etats_clients « déplacement en
        # attente : lui trouver la nouvelle date »). L'écrire sur quelqu'un qui
        # VIENT d'obtenir une date le rangeait parmi ceux à qui il faut en
        # trouver une.
        self.assertEqual(
            [r for r in base.tous_les_rendezvous() if r["statut"] == "déplacé"],
            [])
        self.assertEqual(base.bilan_issues()["rescheduled"], 1)  # le bilan l'affiche
        base.fermer()

    def test_rappel_sans_reponse_echoue_proprement(self):
        base = db.Base(":memory:")
        client_id = base.ajouter_client("Mme Silence Exemple", "+33 6 00 00 00 53")
        rdv_id = base.ajouter_rendezvous(client_id, DEMAIN, "Essai", statut="manqué")
        planif = planificateur.Planificateur(
            base, calle_client.AppelSimule(graine=1, latence=0))
        appel_id = planif.programmer(rdv_id)
        self.assertEqual(planif.executer(), [])           # pas d'appel abouti
        self.assertEqual(base.obtenir_appel(appel_id)["statut"], "échec")
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"], "manqué")
        base.fermer()


class TestListeCascade(unittest.TestCase):
    """Analyse de la liste collée « Nom;Téléphone » pour la cascade."""

    def test_separateurs_acceptes(self):
        personnes, erreurs = saisie.analyser_liste_cascade(
            "Mme Un Exemple;+33 6 00 00 00 51\n"
            "M. Deux Exemple, 06 00 00 00 52\n"
            "\n"
            "Mme Trois Exemple\t0600000053\n")
        self.assertEqual(erreurs, [])
        self.assertEqual([p["nom"] for p in personnes],
                         ["Mme Un Exemple", "M. Deux Exemple", "Mme Trois Exemple"])
        self.assertEqual(personnes[0]["telephone"], "+33 6 00 00 00 51")
        self.assertEqual(personnes[1]["telephone"], "06 00 00 00 52")  # normalisé

    def test_erreurs_francaises_ligne_par_ligne(self):
        personnes, erreurs = saisie.analyser_liste_cascade(
            "Mme Bonne Ligne;+33 6 00 00 00 51\n"
            "sans séparateur du tout\n"
            "M. Numero Faux;12345\n"
            "X;+33 6 00 00 00 55\n"
            "Mme Doublon;+33 6 00 00 00 51\n")
        self.assertEqual(len(personnes), 1)  # seule la première passe
        self.assertEqual(len(erreurs), 4)
        self.assertIn("Ligne 2", erreurs[0])
        self.assertIn("séparateur introuvable", erreurs[0])
        self.assertIn("Ligne 3", erreurs[1])
        self.assertIn("Numéro de téléphone invalide", erreurs[1])
        self.assertIn("Ligne 4", erreurs[2])
        self.assertIn("nom du client", erreurs[2])
        self.assertIn("Ligne 5", erreurs[3])
        self.assertIn("doublon", erreurs[3])

    def test_liste_vide_signale(self):
        personnes, erreurs = saisie.analyser_liste_cascade("  \n \n")
        self.assertEqual(personnes, [])
        self.assertIn("Liste vide", erreurs[0])


class ClientCompteur(calle_client.AppelSimule):
    """Simulateur qui NOTE chaque numéro composé (masqué) — preuve d'appel."""

    def __init__(self, **options):
        super().__init__(**options)
        self.numeros_composes = []

    def appeler_cascade(self, nom_client, telephone, mission, creneau,
                        consigne=None, nature=None):
        self.numeros_composes.append(db.masquer_telephone(telephone))
        return super().appeler_cascade(nom_client, telephone, mission, creneau,
                                       consigne, nature)


class TestCascadePremierOui(unittest.TestCase):
    """La fonction signature : un appel à la fois, arrêt au premier oui."""

    QUATRE = [  # refuse, ne décroche pas, accepte, (jamais appelée)
        {"nom": "Mme Refus Un", "telephone": "+33 6 00 00 00 52"},
        {"nom": "M. Silence Deux", "telephone": "+33 6 00 00 00 53"},
        {"nom": "Mme Accord Trois", "telephone": "+33 6 00 00 00 51"},
        {"nom": "M. Épargné Quatre", "telephone": "+33 6 00 00 00 49"},
    ]

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.compteur = ClientCompteur(graine=6, latence=0)
        self.planif = planificateur.Planificateur(self.base, self.compteur)

    def test_arret_au_premier_oui_et_epargnes_jamais_appeles(self):
        cascade_id = self.planif.executer_cascade(
            self.QUATRE, "Un créneau s'est libéré [créneau].", DEMAIN)
        cascade = self.base.obtenir_cascade(cascade_id)
        self.assertEqual(cascade["statut"], "pourvue")
        # La mission stockée a remplacé [créneau] par la date lisible.
        self.assertNotIn("[créneau]", cascade["mission"])
        self.assertIn("le ", cascade["mission"])
        # Le rendez-vous est créé pour la personne qui a dit oui, au créneau.
        rdv = self.base.obtenir_rendezvous(cascade["rendezvous_id"])
        self.assertEqual(rdv["nom"], "Mme Accord Trois")
        self.assertEqual(rdv["horaire"], DEMAIN)
        self.assertEqual(rdv["statut"], "confirmé")
        # PREUVE par compteur : exactement 3 numéros composés, DANS L'ORDRE,
        # et le numéro de la personne épargnée n'a JAMAIS été composé.
        self.assertEqual(self.compteur.numeros_composes,
                         ["+33 6 •• •• •• 52", "+33 6 •• •• •• 53", "+33 6 •• •• •• 51"])
        self.assertNotIn("+33 6 •• •• •• 49", self.compteur.numeros_composes)
        # Trace en base : 3 appelés (avec issue), 1 épargné (sans issue).
        appels = self.base.appels_de_cascade(cascade_id)
        self.assertEqual([a["etat"] for a in appels],
                         ["appelé", "appelé", "appelé", "épargné"])
        self.assertEqual([a["issue"] for a in appels],
                         ["refused", "no_answer", "accepted", None])
        self.assertNotIn("telephone", appels[0])  # le brut ne sort pas de db
        self.assertTrue(appels[0]["transcription"])          # refusée : dialogue
        self.assertIsNone(appels[1]["transcription"])        # pas décroché : rien
        self.assertIn("je le prends", appels[2]["transcription"])

    def test_liste_epuisee_sans_oui_bilan_honnete(self):
        rdv_avant = self.base.conn.execute(
            "SELECT COUNT(*) FROM rendezvous").fetchone()[0]
        cascade_id = self.planif.executer_cascade(
            self.QUATRE[:2], "Un créneau s'est libéré.", DEMAIN)  # refus + silence
        cascade = self.base.obtenir_cascade(cascade_id)
        self.assertEqual(cascade["statut"], "épuisée")
        self.assertIsNone(cascade["rendezvous_id"])
        self.assertEqual(self.base.conn.execute(
            "SELECT COUNT(*) FROM rendezvous").fetchone()[0], rdv_avant)  # rien créé
        self.assertEqual(len(self.compteur.numeros_composes), 2)  # tout le monde tenté

    def test_deplace_obtient_sa_date_et_la_cascade_continue(self):
        personnes = [
            {"nom": "M. Report Un", "telephone": "+33 6 00 00 00 54"},   # autre date
            {"nom": "Mme Accord Deux", "telephone": "+33 6 00 00 00 51"},  # oui
        ]
        cascade_id = self.planif.executer_cascade(
            personnes, "Un créneau s'est libéré.", DEMAIN)
        self.assertEqual(len(self.compteur.numeros_composes), 2)  # la cascade a continué
        cascade = self.base.obtenir_cascade(cascade_id)
        self.assertEqual(cascade["statut"], "pourvue")
        # Le créneau va à Mme Accord Deux…
        rdv = self.base.obtenir_rendezvous(cascade["rendezvous_id"])
        self.assertEqual(rdv["nom"], "Mme Accord Deux")
        # …et M. Report Un a obtenu un rendez-vous à SA date (déterministe).
        attendu = (datetime.datetime.fromisoformat(DEMAIN)
                   + datetime.timedelta(days=2)).replace(hour=9, minute=30)
        autre = self.base.conn.execute(
            "SELECT r.horaire, r.statut FROM rendezvous r JOIN clients c "
            "ON c.id = r.client_id WHERE c.nom = 'M. Report Un'").fetchone()
        self.assertEqual(autre["horaire"], attendu.isoformat(timespec="minutes"))
        # ⚠ « confirmé », COMME CELUI QUI A PRIS LE CRÉNEAU (17/08/2026). Les
        # deux façons de dire oui écrivaient deux états — « confirmé » pour qui
        # prenait la place offerte, « prévu » pour qui convenait d'une autre
        # date. Même oui au téléphone, deux pastilles de couleurs différentes
        # au planning et deux phrases différentes sur la fiche du client.
        self.assertEqual(autre["statut"], "confirmé")
        self.assertEqual(rdv["statut"], "confirmé")   # les deux se disent pareil
        appels = self.base.appels_de_cascade(cascade_id)
        self.assertEqual([a["issue"] for a in appels], ["moved", "accepted"])

    def test_garde_fous_bloquent_la_cascade_reelle(self):
        reel = calle_client.AppelReel(cle_api="cle-de-test-0123456789")  # jamais utilisée
        planif = planificateur.Planificateur(self.base, reel)  # dry_run par défaut
        with self.assertRaises(planificateur.GardeFou):
            planif.executer_cascade(self.QUATRE, "Mission.", DEMAIN)
        self.assertEqual(self.base.lister_cascades(), [])  # rien n'a même commencé


class TestGenerationListe(unittest.TestCase):
    """Génération de la liste de cascade depuis la base : sources et ordres."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        charlie = self.base.ajouter_client("M. Charlie Un", "+33 6 00 00 00 41")
        self.base.ajouter_rendezvous(charlie, "2026-01-05T10:00", "Essai", statut="annulé")
        alice = self.base.ajouter_client("Mme Alice Deux", "+33 6 00 00 00 42")
        self.base.ajouter_rendezvous(alice, "2026-03-01T10:00", "Essai", statut="annulé")
        self.base.ajouter_rendezvous(alice, "2026-03-15T10:00", "Essai", statut="annulé")
        bob = self.base.ajouter_client("M. Bob Trois", "+33 6 00 00 00 43")
        self.base.ajouter_rendezvous(bob, "2026-02-01T10:00", "Essai", statut="annulé")
        sans = self.base.ajouter_client("Mme Sans Fil", "")   # import ICS non complété
        self.base.ajouter_rendezvous(sans, "2026-01-02T10:00", "Essai", statut="annulé")
        prevu = self.base.ajouter_client("M. Horscadre Cinq", "+33 6 00 00 00 44")
        self.base.ajouter_rendezvous(prevu, DEMAIN, "Essai")  # prévu : hors « annulés »

    def _noms(self, ordre, creneau=None, source="annules"):
        personnes, exclus = generation.generer(self.base, source, ordre, creneau)
        return [p["nom"] for p in personnes], exclus

    def test_source_annules_et_exclusion_sans_numero(self):
        noms, exclus = self._noms("alphabetique")
        # Trois clients annulés avec numéro — Alice une seule fois malgré ses
        # deux annulations — ni le « prévu », ni la cliente sans numéro.
        self.assertEqual(len(noms), 3)
        self.assertNotIn("M. Horscadre Cinq", noms)
        self.assertNotIn("Mme Sans Fil", noms)
        self.assertEqual(exclus, 1)  # la cliente sans numéro, comptée et signalée

    def test_source_deplaces_en_attente(self):
        attente = self.base.ajouter_client("M. Attente Un", "+33 6 00 00 00 45")
        self.base.ajouter_rendezvous(attente, HIER, "Essai", statut="déplacé")
        case = self.base.ajouter_client("Mme Casee Deux", "+33 6 00 00 00 46")
        self.base.ajouter_rendezvous(case, HIER, "Essai", statut="déplacé")
        self.base.ajouter_rendezvous(case, DEMAIN, "Essai")  # a déjà son rendez-vous
        noms, _ = self._noms("alphabetique", source="deplaces")
        self.assertEqual(noms, ["M. Attente Un"])  # « en attente » seulement

    def test_source_tous(self):
        noms, exclus = self._noms("alphabetique", source="tous")
        self.assertEqual(len(noms), 4)             # tous les clients avec numéro
        self.assertEqual(exclus, 1)

    def test_ordre_anciennete(self):
        noms, _ = self._noms("anciennete")
        self.assertEqual(noms, ["M. Charlie Un", "M. Bob Trois", "Mme Alice Deux"])

    def test_ordre_proximite_du_creneau(self):
        noms, _ = self._noms("proximite", creneau="2026-02-05T10:00")
        # Écarts au créneau : Bob 4 jours, Alice 24 jours, Charlie 31 jours.
        self.assertEqual(noms, ["M. Bob Trois", "Mme Alice Deux", "M. Charlie Un"])

    def test_ordre_alphabetique_ignore_la_civilite(self):
        noms, _ = self._noms("alphabetique")
        self.assertEqual(noms, ["Mme Alice Deux", "M. Bob Trois", "M. Charlie Un"])

    def test_ordre_obligatoire_aucun_defaut(self):
        with self.assertRaises(saisie.SaisieInvalide) as contexte:
            generation.generer(self.base, "annules", "")
        self.assertIn("aucun ordre n'est imposé par défaut", str(contexte.exception))

    def test_proximite_exige_le_creneau(self):
        with self.assertRaises(saisie.SaisieInvalide) as contexte:
            generation.generer(self.base, "annules", "proximite")
        self.assertIn("créneau proposé", str(contexte.exception))

    def test_source_inconnue_refusee(self):
        with self.assertRaises(saisie.SaisieInvalide):
            generation.generer(self.base, "martiens", "anciennete")

    def test_liste_collable_reimportable_telle_quelle(self):
        personnes, _ = generation.generer(self.base, "annules", "anciennete")
        texte = generation.en_liste_collable(personnes)
        relues, erreurs = saisie.analyser_liste_cascade(texte)
        self.assertEqual(erreurs, [])
        self.assertEqual(relues, personnes)  # aller-retour parfait

    def test_csv_en_clair_avec_entete(self):
        personnes, _ = generation.generer(self.base, "annules", "anciennete")
        contenu = generation.en_csv(personnes)
        lignes = contenu.split("\r\n")
        self.assertEqual(lignes[0], "nom;telephone")
        self.assertEqual(lignes[1], "M. Charlie Un;+33 6 00 00 00 41")  # EN CLAIR : voulu
        self.assertEqual(lignes[-1], "")  # fin de ligne finale (Excel)


class TestPreferences(unittest.TestCase):
    """Le petit fichier de préférences (dernier ordre choisi, etc.)."""

