class TestImportICS(unittest.TestCase):
    """Lecture d'agenda ICS : lignes pliées, fuseaux, sans-numéro."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)

    @staticmethod
    def _ics(*evenements):
        corps = "".join(f"BEGIN:VEVENT\n{e}\nEND:VEVENT\n" for e in evenements)
        return f"BEGIN:VCALENDAR\nVERSION:2.0\n{corps}END:VCALENDAR\n"

    def test_ligne_pliee_recollee(self):
        # Le dépliage RFC 5545 retire le retour à la ligne et UNE espace :
        # la continuation porte donc deux espaces pour en préserver une.
        texte = self._ics("SUMMARY:Mme Pliure Exemple — Bilan complet avec\n"
                          "  compte rendu détaillé\nDTSTART:20270401T100000")
        evenements, erreurs = ics.analyser_ics(texte)
        self.assertEqual(erreurs, [])
        self.assertEqual(evenements[0]["motif"],
                         "Bilan complet avec compte rendu détaillé")

    def test_date_utc_convertie_en_heure_locale(self):
        texte = self._ics("SUMMARY:Mme Utc Exemple — Essai\nDTSTART:20270312T100000Z")
        evenements, _ = ics.analyser_ics(texte)
        attendu = (datetime.datetime(2027, 3, 12, 10, 0,
                                     tzinfo=datetime.timezone.utc)
                   .astimezone().replace(tzinfo=None).isoformat(timespec="minutes"))
        self.assertEqual(evenements[0]["horaire"], attendu)

    def test_date_sans_fuseau_prise_telle_quelle(self):
        texte = self._ics("SUMMARY:M. Local Exemple — Essai\nDTSTART:20260801T143000")
        evenements, _ = ics.analyser_ics(texte)
        self.assertEqual(evenements[0]["horaire"], "2026-08-01T14:30")

    def test_journee_entiere_rejetee_en_francais(self):
        texte = self._ics("SUMMARY:Atelier collectif\nDTSTART;VALUE=DATE:20270320")
        evenements, erreurs = ics.analyser_ics(texte)
        self.assertEqual(evenements, [])
        self.assertIn("journée entière", erreurs[0])
        self.assertIn("Atelier collectif", erreurs[0])

    def test_fichier_sans_evenement_refuse(self):
        with self.assertRaises(saisie.SaisieInvalide):
            ics.analyser_ics("BEGIN:VCALENDAR\nEND:VCALENDAR\n")

    def test_fichier_exemple_fourni_est_importable(self):
        chemin = os.path.join(RACINE, "exemple_agenda.ics")
        with open(chemin, encoding="utf-8") as fichier:
            importes, erreurs = ics.importer_ics(self.base, fichier.read())
        self.assertEqual(importes, 3)              # 3 événements horodatés
        self.assertEqual(len(erreurs), 1)          # la « journée entière » rejetée
        self.assertIn("journée entière", erreurs[0])
        sans_numero = self.base.rendezvous_sans_numero()
        self.assertEqual(len(sans_numero), 3)      # tous signalés « sans numéro »
        self.assertEqual({rdv["telephone_masque"] for rdv in sans_numero}, {""})
        noms = [rdv["nom"] for rdv in sans_numero]
        self.assertIn("Mme Inès Fabre", noms)
        motifs = " / ".join(rdv["motif"] for rdv in sans_numero)
        self.assertIn("compte rendu détaillé", motifs)  # la ligne pliée, de bout en bout

    def test_sans_numero_complete_puis_rappelable(self):
        ics.importer_ics(self.base, self._ics(
            "SUMMARY:Mme Agenda Exemple — Séance\nDTSTART:20260101T100000"))
        self.base.marquer_manques_echus()           # horaire passé -> manqué
        planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=2, latence=0))
        self.assertEqual(planif.programmer_tous_les_manques(), [])  # pas de numéro :
        rdv = self.base.rendezvous_sans_numero()[0]                 # pas mis en file
        self.base.mettre_a_jour_telephone(rdv["client_id"], "+33 6 00 00 00 51")
        self.assertEqual(self.base.rendezvous_sans_numero(), [])    # complété
        crees = planif.programmer_tous_les_manques()                # maintenant oui
        self.assertEqual(len(crees), 1)
        self.assertEqual(planif.executer(), crees)                  # et l'appel passe


# --------------------------------------------------------------------------
# Fausse API CALL-E locale : un http.server qui imite création + suivi
# d'appel. AUCUN test ne contacte la vraie API.
# --------------------------------------------------------------------------
RESULTAT_CONFORME = {"appointment_status": "confirmed", "new_datetime": DEMAIN,
                     "notes": "Le client confirme le créneau proposé.",
                     "duration_seconds": 42}

# --------------------------------------------------------------------------
# LA FORME RÉELLE D'UNE RÉPONSE CALL-E — recopiée de la documentation du
# sponsor (github.com/CALLE-AI/call-e-integrations), pas de ce que RingBack
# croit comprendre.
#
# POURQUOI CE BLOC EXISTE. Jusqu'au 01/08/2026, la fausse API répondait
# {"status": "completed", "result": {...}, "transcript": "..."} — c'est-à-dire
# EXACTEMENT ce que le produit allait chercher. Les 451 essais passaient donc
# tous, alors que le vrai chemin était faux depuis toujours : la vraie API
# range le résultat d'UNE personne dans recipients[].structured_result et la
# conversation dans recipients[].attempts[].transcript_turns[]. Un essai qui
# imite le produit ne prouve rien ; celui-ci imite l'API.
TOURS_DOCUMENTES = [
    {"offset_seconds": 0, "speaker": "bot",
     "text": "Bonjour, ici l'assistant du cabinet. Je vous propose un "
             "nouveau créneau."},
    {"offset_seconds": 4, "speaker": "user",
     "text": "C'est parfait, je confirme."},
]


def reponse_calle_terminee(resultat_destinataire, tours=None, tentatives=None,
                           destinataires=None):
    """La réponse TERMINALE de GET /v1/calls/{id}, telle que documentée.

    `destinataires` permet d'imposer la liste « recipients » telle quelle
    (pour éprouver l'absence de destinataire) ; `tentatives` permet d'en
    donner plusieurs, pour éprouver le choix de la DERNIÈRE.
    """
    if destinataires is None:
        if tentatives is None:
            tentatives = [{"transcript_turns":
                           TOURS_DOCUMENTES if tours is None else tours}]
        destinataires = [{"structured_result": resultat_destinataire,
                          "attempts": tentatives}]
    return {
        "status": "completed",
        "task_completed": True,
        "completion_confidence": {"score": 0.92, "label": "high"},
        "evidence": ["The recipient confirmed the proposed slot."],
        # Bilan GLOBAL de la campagne : ce n'est PAS ce que RingBack lit.
        "structured_result": {"completed_count": 1},
        "recipients": destinataires,
    }


class _FauxApiCalle(BaseHTTPRequestHandler):
    """Imite l'API CALL-E : POST /v1/calls puis GET /v1/calls/{id}.

    `etats` est la liste des réponses successives aux GET ; la dernière
    « colle » (elle est resservie indéfiniment, utile pour le test du
    délai d'attente). `creations` garde chaque corps de POST reçu.

    Elle sait aussi être LENTE (`lenteur_post`, `lenteur_get`) : elle
    attend avant de répondre, ce qui fait vraiment expirer la lecture du
    client et lever le TimeoutError du 01/08/2026 — jamais une imitation
    d'exception, la vraie, levée par la vraie pile réseau.
    """

    creations = None   # rempli par la sous-classe de chaque test
    etats = None
    entetes = None     # en-têtes de la dernière requête reçue
    lectures = None    # les identifiants demandés en GET, dans l'ordre
    # Codes d'erreur à SERVIR au lieu d'une réponse normale. C'est ainsi
    # qu'un 401 (clé refusée), un 402/429 (quota) ou un 500 (panne du
    # service) sont éprouvés sans jamais toucher la vraie API.
    code_erreur_post = None    # échec à la CRÉATION : rien n'est parti
    code_erreur_get = None     # échec au SUIVI : l'appel avait été lancé
    # CE QUE L'API RÉPOND DANS LE CORPS quand elle refuse. La vraie nomme le
    # champ fautif — c'est cette phrase-là qu'il faut pouvoir relire, et le
    # 02/08/2026 elle était lue puis jetée en route (voir
    # test_la_reponse_de_l_api_est_citee_quand_elle_refuse).
    corps_erreur = {"error": "refus simulé"}
    # Lenteur SIMULÉE, en secondes : le temps que l'API met à répondre.
    # Au-delà du délai_requete du client, la lecture expire pour de bon.
    lenteur_post = 0
    lenteur_get = 0
    # Raccrocher au nez sans répondre : c'est ainsi qu'on obtient les VRAIES
    # http.client.RemoteDisconnected / ConnectionResetError, celles qui
    # traversaient elles aussi la traduction des erreurs.
    coupure_post = False
    coupure_get = False
    identifiant = "appel-essai-1"

    def do_POST(self):
        taille = int(self.headers.get("Content-Length", 0))
        type(self).entetes = dict(self.headers)
        type(self).creations.append(json.loads(self.rfile.read(taille)))
        if type(self).lenteur_post:
            time.sleep(type(self).lenteur_post)
        if type(self).coupure_post:
            return self._raccrocher()
        if type(self).code_erreur_post:
            return self._echec(type(self).code_erreur_post)
        self._json({"id": type(self).identifiant, "status": "queued"})

    def do_GET(self):
        if type(self).lectures is not None:
            type(self).lectures.append(self.path)
        if type(self).lenteur_get:
            time.sleep(type(self).lenteur_get)
        if type(self).coupure_get:
            return self._raccrocher()
        if type(self).code_erreur_get:
            return self._echec(type(self).code_erreur_get)
        etats = type(self).etats
        reponse = etats.pop(0) if len(etats) > 1 else etats[0]
        self._json(reponse)

    def _echec(self, code):
        """Une réponse d'ERREUR, comme en rendrait la vraie API."""
        octets = json.dumps(type(self).corps_erreur).encode("utf-8")
        self._ecrire(code, octets)

    def _raccrocher(self):
        """Coupe la connexion sans répondre : le serveur qui lâche en pleine
        conversation. Le client y verra un http.client.RemoteDisconnected."""
        self.close_connection = True
        try:
            self.connection.close()
        except OSError:
            pass

    def _json(self, contenu):
        octets = json.dumps(contenu, ensure_ascii=False).encode("utf-8")
        self._ecrire(200, octets)

    def _ecrire(self, code, octets):
        """Écrit la réponse ; un client qui a déjà renoncé ne fait pas de bruit.

        Quand la lecture du client a expiré, il a fermé la connexion : écrire
        dedans lève une erreur de tuyau. Ce n'est pas un défaut du produit,
        c'est le scénario lui-même — on l'avale sans polluer la sortie.
        """
        try:
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(octets)))
            self.end_headers()
            self.wfile.write(octets)
        except OSError:
            self.close_connection = True

    def handle_one_request(self):
        try:
            BaseHTTPRequestHandler.handle_one_request(self)
        except (OSError, ValueError):
            self.close_connection = True

    def log_message(self, *arguments):
        pass  # silence : pas de bruit dans la sortie des tests


class TestAppelReel(unittest.TestCase):
    """AppelReel exercé contre la fausse API locale, jamais la vraie."""

    def setUp(self):
        self.base, self.client_id, self.rdv_id = base_de_test()
        self.addCleanup(self.base.fermer)
        self._cle_sauvee = os.environ.pop("CALLE_API_KEY", None)
        if self._cle_sauvee is not None:
            self.addCleanup(os.environ.__setitem__, "CALLE_API_KEY", self._cle_sauvee)
        self.dossier = tempfile.mkdtemp(prefix="ringback-audit-")
        self.addCleanup(shutil.rmtree, self.dossier, ignore_errors=True)
        self.chemin_audit = os.path.join(self.dossier, "audit_appels_reels.jsonl")

        class Faux(_FauxApiCalle):
            creations = []
            etats = [{"status": "queued"}]
        self.faux = Faux
        self.serveur_api = HTTPServer(("127.0.0.1", 0), Faux)
        threading.Thread(target=self.serveur_api.serve_forever, daemon=True).start()
        self.url_api = f"http://127.0.0.1:{self.serveur_api.server_address[1]}"
        # C'est bien la variable d'environnement CALLE_API_URL qui aiguille
        # le client : preuve que l'URL de base est configurable sans code.
        os.environ["CALLE_API_URL"] = self.url_api
        self.addCleanup(os.environ.pop, "CALLE_API_URL", None)
        self.addCleanup(self.serveur_api.server_close)
        self.addCleanup(self.serveur_api.shutdown)

    def _client(self, **surcharge):
        options = dict(cle_api="cle-de-test-0123456789", delai_total=2.0, intervalle=0.01,
                       delai_requete=2.0, chemin_audit=self.chemin_audit)
        options.update(surcharge)
        return calle_client.AppelReel(**options)

    def test_le_POST_porte_la_langue_de_l_appel(self):
        """⚠ VERROU TROUVÉ SANS GARDIEN PAR LA CONTRE-ÉPREUVE (01/09/2026).
        `_region_et_locale` était éprouvée toute seule ; rien ne disait qu'elle
        était RÉELLEMENT employée dans l'envoi. On regarde donc ce que la
        fausse API a reçu."""
        for langue_code, attendu in (("fr", ("FR", "fr-FR")),
                                     ("en", ("GB", "en-GB"))):
            with self.subTest(langue=langue_code):
                self.faux.creations = []
                self.faux.etats = [{"status": "completed", "recipients": [
                    {"structured_result": {"appointment_status": "confirmed",
                                           "new_datetime": "", "notes": "",
                                           "do_not_call": "no"}}]}]
                client = self._client(langue_appel=langue_code)
                try:
                    client.appeler("Mme Essai", "+33 6 00 00 00 42",
                                   {"horaire": DEMAIN, "motif": "Bilan"},
                                   mission="Bonjour.")
                except Exception:                            # noqa: BLE001
                    pass
                self.assertTrue(self.faux.creations,
                                "aucune demande n'est arrivée à l'API")
                destinataire = self.faux.creations[-1]["recipients"][0]
                self.assertEqual(
                    (destinataire["region"], destinataire["locale"]), attendu)

    def _planificateur_deverrouille(self, client):
        planif = planificateur.Planificateur(self.base, client, dry_run=False)
        planif.confirmer_appels_reels()
        return planif

    def _lignes_audit(self):
        with open(self.chemin_audit, encoding="utf-8") as fichier:
            contenu = fichier.read()
        self.assertNotIn("+33 6 00 00 00 42", contenu)  # JAMAIS le numéro en clair
        return [json.loads(ligne) for ligne in contenu.splitlines() if ligne.strip()]

    def test_url_de_base_configurable_par_variable(self):
        self.assertEqual(self._client().url_base, self.url_api)
        del os.environ["CALLE_API_URL"]
        try:
            self.assertEqual(self._client().url_base, "https://api.heycall-e.com")
        finally:
            os.environ["CALLE_API_URL"] = self.url_api

    def test_verrous_bloquent_avant_toute_requete(self):
        # Verrou 1 : sans clé, le client réel ne se construit même pas.
        # ⚠ LA VARIABLE *ET* LE FICHIER (03/09/2026) : voir
        # `sans_aucune_cle_calle`.
        with sans_aucune_cle_calle():
            with self.assertRaises(calle_client.CleApiAbsente):
                calle_client.AppelReel(chemin_audit=self.chemin_audit)
        reel = self._client()
        # Verrou 2 : dry_run (défaut) bloque l'exécution.
        planif = planificateur.Planificateur(self.base, reel)
        planif.programmer(self.rdv_id)
        with self.assertRaises(planificateur.GardeFou):
            planif.executer()
        # Verrou 3 : sans confirmation explicite, refus aussi.
        planif2 = planificateur.Planificateur(self.base, reel, dry_run=False)
        planif2.programmer(self.rdv_id)
        with self.assertRaises(planificateur.GardeFou):
            planif2.executer()
        self.assertEqual(self.faux.creations, [])  # AUCUNE requête n'est partie
        self.assertFalse(os.path.exists(self.chemin_audit))  # et rien d'audité

    def test_appel_reel_complet_contre_fausse_api(self):
        self.faux.etats[:] = [
            {"status": "queued"}, {"status": "in_progress"},
            reponse_calle_terminee(dict(RESULTAT_CONFORME))]
        planif = self._planificateur_deverrouille(self._client())
        appel_id = planif.programmer(self.rdv_id)
        self.assertEqual(planif.executer(), [appel_id])
        appel = self.base.obtenir_appel(appel_id)
        self.assertEqual(appel["statut"], "terminé")
        self.assertEqual(appel["resultat"]["appointment_status"], "confirmed")
        self.assertIn("Bonjour", appel["transcription"])
        self.assertEqual(self.base.obtenir_rendezvous(self.rdv_id)["statut"], "confirmé")
        # La requête de création respecte l'API documentée du sponsor.
        # ⚠ Cet essai a longtemps verrouillé une ERREUR : il attendait
        # « phone » (un texte) et le numéro espacé, parce que c'est ce que le
        # produit envoyait. La vraie API répondait 422 — constaté le
        # 01/08/2026 au premier essai réel. La documentation dit « phones »,
        # une LISTE, au format international compact (E.164). Un essai ne
        # vérifie que ce qu'on a cru comprendre : il ne remplace jamais un
        # appel réel.
        self.assertEqual(len(self.faux.creations), 1)
        creation = self.faux.creations[0]
        self.assertEqual(creation["recipients"],
                         [{"phones": ["+33600000042"], "region": "FR",
                           "locale": "fr-FR"}])
        # ⚠ « Mme » N'EST PLUS ENVOYÉ TEL QUEL : le propriétaire a constaté à
        # l'oreille que l'agent ne lit pas les abréviations. Elles sont
        # développées au moment de construire la consigne — et là seulement :
        # la fiche du client, elle, garde son écriture (voir le module
        # consigne, et TestCivilitesDeveloppees).
        self.assertIn("madame Test Exemple", creation["task"])
        self.assertNotIn("Mme Test Exemple", creation["task"])
        self.assertNotIn("+33 6 00 00 00 42", creation["task"])  # pas de numéro dans la mission
        # ⚠ ET LA TÂCHE N'EST PLUS UN MONOLOGUE : trois parties, dont une
        # seule est imposée (la présentation). C'est ce qui a manqué au 5ᵉ
        # essai réel du propriétaire, où l'agent récitait puis concluait.
        for titre in (consigne.TITRE_PRESENTATION, consigne.TITRE_CONTEXTE,
                      consigne.TITRE_ISSUES):
            self.assertIn(titre, creation["task"])
        for etiquette in ("- OUI — ", "- NON — ", "- AUTRE — "):
            self.assertIn(etiquette, creation["task"])
        # ⚠ LE SCHÉMA PART DANS « recipient_result_schema ». Il décrit le
        # résultat d'UNE personne ; « result_schema » décrirait le bilan
        # global de la campagne. C'est la faute symétrique de celle du
        # retour, constatée le 01/08/2026 à 16h49.
        self.assertEqual(creation["recipient_result_schema"],
                         calle_client.SCHEMA_RESULTAT)
        # ⚠ ET LE BILAN GLOBAL PART AVEC, comme dans l'exemple « Create call »
        # de la référence d'API, qui montre les DEUX côte à côte. Le retirer
        # « puisqu'il est facultatif » a valu un 400 à la création le
        # 02/08/2026 : un raisonnement contre un exemple documenté, et c'est
        # l'exemple qui avait raison.
        self.assertEqual(creation["result_schema"],
                         calle_client.SCHEMA_BILAN_GLOBAL)
        # Aucun mot-clé hors de la liste admise par la référence (type,
        # properties, required, enum, objets imbriqués, array.items,
        # description, additionalProperties: false) — « minimum » en est
        # absent, et un schéma refusé fait échouer TOUS les appels.
        for schema in (calle_client.SCHEMA_RESULTAT,
                       calle_client.SCHEMA_RESULTAT_CASCADE,
                       calle_client.SCHEMA_BILAN_GLOBAL):
            for champ, regle in schema["properties"].items():
                interdits = set(regle) - {"type", "enum", "description",
                                          "properties", "required", "items",
                                          "additionalProperties"}
                self.assertEqual(interdits, set(),
                                 f"{champ} porte un mot-clé non admis")
        # ⚠ ET AUCUN NOM RÉSERVÉ : CALL-E remplit lui-même summary, status,
        # transcript, call_id et les champs de temps, et refuse la demande
        # ENTIÈRE si on les lui demande. Le 02/08/2026, « duration_seconds »
        # a fait échouer le 7ᵉ essai réel — un champ que RingBack exigeait de
        # l'agent et n'utilisait nulle part.
        for schema in (calle_client.SCHEMA_RESULTAT,
                       calle_client.SCHEMA_RESULTAT_CASCADE,
                       calle_client.SCHEMA_BILAN_GLOBAL):
            self.assertEqual(calle_client.champs_reserves_dans(schema), [])
        self.assertEqual(self.faux.entetes.get("Authorization"), "Bearer cle-de-test-0123456789")
        # La transcription est reconstituée depuis transcript_turns, avec les
        # MÊMES libellés que la simulation : l'écran reste homogène.
        self.assertEqual(
            appel["transcription"],
            "Agent : Bonjour, ici l'assistant du cabinet. Je vous propose un "
            "nouveau créneau.\nClient : C'est parfait, je confirme.")
        # Audit : une ligne, horodatée, numéro masqué.
        lignes = self._lignes_audit()
        self.assertEqual(len(lignes), 1)
        self.assertEqual(lignes[0]["statut"], "terminé")
        self.assertEqual(lignes[0]["telephone"], "+33 6 •• •• •• 42")
        datetime.datetime.fromisoformat(lignes[0]["horodatage"])  # lisible

    # ------------------------------- le renvoi vers MON numéro (essais réels)
    def test_le_renvoi_remplace_le_numero_compose_et_rien_d_autre(self):
        """⚠ LE POINT DE LA DEMANDE, mot pour mot : « on remplace les numéros
        de téléphone transmise à l'agent par ce numéro de téléphone.
        L'identité reste inchangé. » (propriétaire, 10/08/2026)

        Les deux moitiés comptent autant l'une que l'autre : si l'identité
        changeait, on n'entendrait plus la conversation que le contact aurait
        eue — et l'essai ne servirait plus à rien.
        """
        self.faux.etats[:] = [reponse_calle_terminee(dict(RESULTAT_CONFORME))]
        planif = self._planificateur_deverrouille(
            self._client(numero_impose="06 39 98 00 24"))
        planif.programmer(self.rdv_id)
        planif.executer()
        creation = self.faux.creations[-1]
        # Le numéro composé est le MIEN, au format compact attendu par l'API…
        self.assertEqual(creation["recipients"][0]["phones"], ["+33639980024"])
        # …et celui du contact n'est nulle part dans la demande.
        self.assertNotIn("600000042", json.dumps(creation))
        # L'IDENTITÉ, ELLE, NE BOUGE PAS D'UN MOT.
        self.assertIn("madame Test Exemple", creation["task"])
        self.assertIn(consigne.TITRE_PRESENTATION, creation["task"])

    def test_le_renvoi_est_relu_a_chaque_appel_jamais_figé(self):
        """⚠ SANS CELA, UNE CASE COCHÉE N'AURAIT AUCUN EFFET AVANT REDÉMARRAGE.
        Le client réel est construit UNE fois, au démarrage du serveur : le
        numéro imposé est donc une FONCTION, relue à chaque appel — et l'écran
        ne peut pas annoncer autre chose que ce qui part.
        """
        impose = [""]
        client = self._client(numero_impose=lambda: impose[0])
        self.faux.etats[:] = [reponse_calle_terminee(dict(RESULTAT_CONFORME))]
        rdv = self.base.obtenir_rendezvous(self.rdv_id)
        client.appeler("Mme Test Exemple", "+33 6 00 00 00 42", rdv)
        self.assertEqual(self.faux.creations[-1]["recipients"][0]["phones"],
                         ["+33600000042"])
        impose[0] = "06 39 98 00 24"       # la case est cochée EN COURS DE ROUTE
        client.appeler("Mme Test Exemple", "+33 6 00 00 00 42", rdv)
        self.assertEqual(self.faux.creations[-1]["recipients"][0]["phones"],
                         ["+33639980024"])

    def test_un_numero_impose_illisible_refuse_l_appel_et_ne_compose_rien(self):
        """⚠ IL NE SE RABAT JAMAIS SUR LE NUMÉRO DU CONTACT. Se rabattre ferait
        sonner un vrai téléphone au moment précis où l'écran promet qu'aucun ne
        sonnera : c'est le seul dénouement qu'on ne puisse pas rattraper. Le
        refus, lui, se lit et se corrige.
        """
        client = self._client(numero_impose="https://pas-un-numero")
        rdv = self.base.obtenir_rendezvous(self.rdv_id)
        with self.assertRaises(calle_client.DemandeRefusee) as refus:
            client.appeler("Mme Test Exemple", "+33 6 00 00 00 42", rdv)
        self.assertEqual(self.faux.creations, [])      # RIEN n'est parti
        self.assertIn("renvoi d'essai", str(refus.exception))
        lignes = self._lignes_audit()
        self.assertEqual(lignes[-1]["statut"], "aucun appel lancé")
        # La ligne d'audit ne montre pas une rangée de points sans sens : elle
        # dit ce qui s'est vraiment passé.
        self.assertEqual(lignes[-1]["numero_appele"],
                         "numéro d'essai illisible")

    def test_l_audit_dit_le_renvoi_et_garde_le_numero_du_contact_masque(self):
        """Relire le journal doit dire DEUX choses : qui l'on voulait joindre,
        et que ce n'est pas lui qui a sonné. Sans la seconde, une campagne
        entière se relirait comme si de vrais contacts avaient été appelés.
        """
        self.faux.etats[:] = [reponse_calle_terminee(dict(RESULTAT_CONFORME))]
        rdv = self.base.obtenir_rendezvous(self.rdv_id)
        self._client().appeler("Mme Test Exemple", "+33 6 00 00 00 42", rdv)
        ordinaire = self._lignes_audit()[-1]
        # SANS renvoi, la ligne ne change pas de forme : aucune clé en trop.
        self.assertNotIn("renvoi_essai", ordinaire)
        self.assertNotIn("numero_appele", ordinaire)
        self._client(numero_impose="06 39 98 00 24").appeler(
            "Mme Test Exemple", "+33 6 00 00 00 42", rdv)
        renvoye = self._lignes_audit()[-1]
        self.assertEqual(renvoye["telephone"], "+33 6 •• •• •• 42")  # LE CONTACT
        self.assertEqual(renvoye["numero_appele"], "06 39 •• •• 24")  # MOI
        self.assertIn("n'a PAS été appelé", renvoye["renvoi_essai"])

    def test_les_deux_portes_d_appel_passent_par_le_meme_entonnoir(self):
        """⚠ TOUT LE RENVOI TIENT À CELA. S'il existait un jour une troisième
        porte qui poste sans passer par _appel_complet, elle composerait le
        numéro du contact sans que rien ne le dise — et personne ne s'en
        apercevrait avant d'avoir appelé de vrais clients.
        """
        source = inspect.getsource(calle_client.AppelReel)
        self.assertEqual(source.count("_numero_a_composer(telephone)"), 1)
        self.assertEqual(source.count("numero_e164(telephone)"), 1)
        for methode in ("appeler", "appeler_cascade"):
            with self.subTest(methode=methode):
                self.assertIn("self._appel_complet(", inspect.getsource(
                    getattr(calle_client.AppelReel, methode)))

    def test_resultat_non_conforme_rejete_sans_ecriture(self):
        """Un résultat hors schéma n'est JAMAIS appliqué — et n'accuse personne.

        ⚠ Cet essai attendait « échec » et une lecture qui continue en
        silence. Les deux étaient faux : le POST avait abouti, la
        conversation avait eu lieu. Depuis le 01/08/2026 (16h49), un
        résultat que RingBack ne sait pas lire est une faute de RingBack —
        l'appel s'arrête, sa fiche garde la RÉPONSE BRUTE, et rien n'est
        écrit contre le client.
        """
        invalide = {"appointment_status": "maybe", "new_datetime": None,
                    "notes": "", "duration_seconds": 5}
        self.faux.etats[:] = [reponse_calle_terminee(invalide)]
        planif = self._planificateur_deverrouille(self._client())
        appel_id = planif.programmer(self.rdv_id)
        with self.assertRaises(calle_client.ResultatInvalide) as refus:
            planif.executer()
        appel = self.base.obtenir_appel(appel_id)
        self.assertEqual(appel["statut"], "réponse illisible")
        self.assertIsNone(appel["resultat"])         # AUCUNE écriture du résultat
        # La conversation, elle, est CONSERVÉE : elle a eu lieu.
        self.assertIn("C'est parfait, je confirme.", appel["transcription"])
        # ③ NE PLUS ÊTRE AVEUGLE : la réponse brute est sur la fiche.
        self.assertIn("structured_result", appel["note"])
        self.assertIn("maybe", appel["note"])
        self.assertEqual(appel["appel_externe_id"], "appel-essai-1")
        self.assertEqual(self.base.obtenir_rendezvous(self.rdv_id)["statut"],
                         "manqué")                   # rendez-vous intact
        self.assertEqual(planif.file, [])            # jamais rappelé tout seul
        # Le message dit ce qui a eu lieu, et de qui c'est la faute.
        self.assertIn("RingBack n'a pas su lire", str(refus.exception))
        self.assertIn("A BIEN EU LIEU", str(refus.exception))
        lignes = self._lignes_audit()
        self.assertEqual(lignes[0]["statut"], "réponse illisible")
        self.assertIn("appointment_status", lignes[0]["detail"])
        # ③ et dans le journal d'audit aussi — c'est ce qui manquait.
        self.assertIn("maybe", lignes[0]["reponse_brute"])

    def test_delai_attente_declenche_proprement(self):
        """L'attente expire : l'appel EST parti, il n'est PAS perdu.

        ⚠ Cet essai attendait « échec » et un appel remis en file. Les deux
        étaient faux : le POST de création avait abouti, donc le téléphone
        avait sonné. Remettre l'appel en file l'aurait fait sonner une
        seconde fois ; l'écrire « échec » effaçait la conversation. Depuis le
        01/08/2026, l'appel garde son identifiant CALL-E et son statut dit la
        vérité — « en attente ».
        """
        self.faux.etats[:] = [{"status": "in_progress"}]  # ne se termine jamais
        planif = self._planificateur_deverrouille(
            self._client(delai_total=0.15, intervalle=0.02))
        appel_id = planif.programmer(self.rdv_id)
        with self.assertRaises(calle_client.DelaiDepasse):
            planif.executer()
        appel = self.base.obtenir_appel(appel_id)
        self.assertEqual(appel["statut"], "en attente")
        self.assertEqual(appel["appel_externe_id"], "appel-essai-1")
        self.assertIn("EST BIEN PARTI", appel["note"])
        # Et il ne repart PAS en file : personne ne sera rappelé pour rien.
        self.assertEqual(planif.file, [])
        self.assertEqual(self.base.obtenir_rendezvous(self.rdv_id)["statut"], "manqué")
        lignes = self._lignes_audit()
        self.assertEqual(lignes[0]["statut"], "délai dépassé")

    def test_statut_api_en_echec_refuse_proprement(self):
        self.faux.etats[:] = [{"status": "queued"}, {"status": "no_answer"}]
        planif = self._planificateur_deverrouille(self._client())
        appel_id = planif.programmer(self.rdv_id)
        self.assertEqual(planif.executer(), [])
        self.assertEqual(self.base.obtenir_appel(appel_id)["statut"], "échec")
        lignes = self._lignes_audit()
        # Le journal DIT que c'est le contact qui n'a pas décroché — comme il
        # le faisait déjà pour la cascade. « échec » mêlait ce cas-là et les
        # pannes du logiciel, qui se lisaient donc pareil.
        self.assertEqual(lignes[0]["statut"], "pas de réponse")
        self.assertIn("no_answer", lignes[0]["detail"])

    def test_le_journal_distingue_le_contact_et_nous(self):
        """③ Deux lignes d'audit, deux statuts qui ne se confondent plus."""
        self.faux.etats[:] = [{"status": "no_answer"}]
        planif = self._planificateur_deverrouille(self._client())
        planif.executer(seulement=planif.programmer(self.rdv_id))
        self.faux.code_erreur_post = 401
        with self.assertRaises(calle_client.EchecDeNotreCote):
            planif.executer(seulement=planif.programmer(self.rdv_id))
        lignes = self._lignes_audit()
        self.assertEqual([ligne["statut"] for ligne in lignes],
                         ["pas de réponse", "aucun appel lancé"])

    def test_la_reponse_de_l_api_est_citee_quand_elle_refuse(self):
        """Le message PROMET une citation : elle doit y être.

        Constaté le 02/08/2026 chez le propriétaire : sur un 400, l'écran
        disait « Lisez la réponse de l'API citée ci-dessus : elle nomme le
        champ en cause » — et rien n'était cité. Le corps était bien lu, puis
        accroché à args[0], que cette famille d'erreurs n'affiche jamais
        (elle recompose son texte depuis constat + quoi_faire). Promettre
        une preuve qu'on n'apporte pas est pire que se taire : on cherche
        alors une citation inexistante au lieu de chercher la panne.
        """
        self.faux.code_erreur_post = 400
        self.faux.corps_erreur = {
            "error": {"code": "recipient_result_schema_invalid",
                      "message": "unsupported schema feature at "
                                 "$.properties.duration_seconds.minimum"}}
        planif = self._planificateur_deverrouille(self._client())
        with self.assertRaises(calle_client.EchecDeNotreCote) as refus:
            planif.executer(seulement=planif.programmer(self.rdv_id))
        panne = refus.exception
        # ① La réponse est CONSERVÉE, à son propre rang — pas dans args[0].
        self.assertIn("duration_seconds.minimum", panne.reponse_brute)
        # ② Elle est DITE dans le message affiché, celui qui promet la citation.
        self.assertIn("duration_seconds.minimum", panne.message())
        self.assertIn("mot pour mot", panne.message())
        # ③ Et elle est écrite au journal d'audit, dans sa colonne : relire une
        # ligne doit suffire à savoir quel champ l'API a refusé.
        ligne = self._lignes_audit()[0]
        self.assertEqual(ligne["statut"], "aucun appel lancé")
        self.assertIn("duration_seconds.minimum", ligne["reponse_brute"])
        self.assertIn("duration_seconds.minimum", ligne["detail"])

    def test_une_autre_date_sans_date_est_lue_et_non_declaree_illisible(self):
        """Le 8ᵉ essai réel, rejoué — et cette fois compris.

        Ce qui s'est passé le 02/08/2026 : la personne a demandé qu'on lui
        répète la date, l'agent a conclu « moved » sans date, et RingBack a
        déclaré la réponse ILLISIBLE (« new_datetime doit être une date ISO
        8601 »). Or « veut autre chose, rien n'est convenu » n'a rien
        d'illisible : c'est to_reschedule, que la consigne demande elle-même
        à l'agent — sauf en cascade, la seule nature qui n'avait pas ce repli.
        """
        for vide in ("", None):
            with self.subTest(new_datetime=vide):
                lu = calle_client.valider_resultat_cascade(
                    {"outcome": "moved", "new_datetime": vide,
                     "notes": "La personne a demandé qu'on lui répète la date."})
                self.assertEqual(lu["outcome"], "to_reschedule")
                self.assertIsNone(lu["new_datetime"])
        # Le même repli côté rappel classique.
        lu = calle_client.valider_resultat(
            {"appointment_status": "rescheduled", "new_datetime": "",
             "notes": "Rien n'a été convenu."})
        self.assertEqual(lu["appointment_status"], "to_reschedule")
        # Et une VRAIE date convenue reste un déplacement : le repli ne
        # s'applique qu'à l'absence de date, jamais à sa présence.
        lu = calle_client.valider_resultat_cascade(
            {"outcome": "moved", "new_datetime": "2026-09-15T14:30",
             "notes": "Le 15 septembre lui va."})
        self.assertEqual(lu["outcome"], "moved")

    def test_la_citation_commence_par_le_resultat_qui_a_echoue(self):
        """Une citation tronquée doit garder l'essentiel, pas l'alphabet.

        Le 02/08/2026, la citation partait de la réponse entière triée par
        nom de clé : « structured_result » arrivait en dernier et la
        troncature à 2000 caractères emportait le seul morceau qui disait
        pourquoi la lecture avait échoué.
        """
        etat = {
            "completed_at": "2026-08-02T10:47:33Z",
            "evidence": ["blabla " * 400],          # de quoi dépasser la limite
            "recipients": [{"structured_result": {
                "outcome": "chose_inconnue", "new_datetime": "",
                "notes": "…"}}],
        }
        with self.assertRaises(calle_client.ResultatInvalide) as refus:
            calle_client.lire_appel_termine(
                etat, calle_client.valider_resultat_cascade)
        cite = refus.exception.reponse_brute
        self.assertIn("chose_inconnue", cite)
        self.assertLess(cite.index("chose_inconnue"),
                        calle_client.LIMITE_REPONSE_BRUTE)

    def test_le_detecteur_de_champs_reserves_les_reconnait(self):
        """Le garde-fou attrape ce qui a fait échouer le 7ᵉ essai réel.

        Il ne suffit pas que les schémas d'aujourd'hui soient propres : il
        faut que le jour où quelqu'un rajoute « call_duration » ou
        « started_at », un essai le dise ICI — et pas CALL-E, à distance, au
        milieu d'une campagne, par un 400.
        """
        for nom in ("duration_seconds", "summary", "status", "transcript",
                    "call_id", "started_at", "completed_at", "call_duration"):
            with self.subTest(nom=nom):
                self.assertEqual(
                    calle_client.champs_reserves_dans(
                        {"properties": {nom: {"type": "string"}}}), [nom])
        # Et il ne se déclenche PAS sur les champs que l'API accepte : le
        # 02/08/2026 elle a validé appointment_status et new_datetime dans la
        # même demande où elle refusait duration_seconds.
        for nom in ("appointment_status", "new_datetime", "notes", "outcome"):
            with self.subTest(nom=nom):
                self.assertEqual(
                    calle_client.champs_reserves_dans(
                        {"properties": {nom: {"type": "string"}}}), [])

    def test_la_citation_masque_les_numeros_de_telephone(self):
        """Une citation reste une citation — mais jamais un numéro en clair."""
        self.faux.code_erreur_post = 400
        self.faux.corps_erreur = {"error": "invalid recipient +33600000042"}
        planif = self._planificateur_deverrouille(self._client())
        with self.assertRaises(calle_client.EchecDeNotreCote) as refus:
            planif.executer(seulement=planif.programmer(self.rdv_id))
        message = refus.exception.message()
        self.assertIn("invalid recipient", message)
        self.assertNotIn("+33600000042", message)
        self.assertNotIn("+33600000042", self._lignes_audit()[0]["reponse_brute"])


class _TestAvecServeurWeb(unittest.TestCase):
    """Montage commun : serveur web sur port libre, base en mémoire (sans trace).

    La plage horaire d'appel autorisée (garde-fou de politesse, 9h-19h par
    défaut) est OUVERTE en grand ici pour que les tests passent des appels à
    n'importe quelle heure ; le refus hors plage a ses tests dédiés
    (TestServeurPlageHoraire) qui règlent une plage fermée exprès.
    """

    appels_reels = False

    def setUp(self):
        self.serveur_http = serveur.creer_serveur(
            port=0, chemin_base=":memory:", appels_reels=self.appels_reels)
        fil = threading.Thread(target=self.serveur_http.serve_forever, daemon=True)
        fil.start()
        self.racine = f"http://127.0.0.1:{self.serveur_http.server_address[1]}"
        preferences = self.application.preferences
        preferences.definir(serveur.themes.CLE_PLAGE_DEBUT, "00:00")
        preferences.definir(serveur.themes.CLE_PLAGE_FIN, "23:59")

    def tearDown(self):
        self.serveur_http.shutdown()
        self.serveur_http.server_close()

    @property
    def application(self):
        return self.serveur_http.RequestHandlerClass.application

    # ⚠ `fenetre` DIT DE QUEL CÔTÉ ON FRAPPE. Le produit répond soit une
    # FENÊTRE (un morceau, quand la demande vient du mécanisme de modale), soit
    # une PAGE entière (envoi de formulaire ordinaire, navigateur sans
    # JavaScript, repli « Sans glisser »). Les essais qui ne le précisaient pas
    # éprouvaient donc la page en croyant éprouver la fenêtre — c'est ainsi que
    # le cul-de-sac du 17/08/2026 est passé au travers.
    ENTETE_FENETRE = {"X-RingBack-Fragment": "1"}

    def _obtenir(self, chemin, fenetre=False):
        demande = urllib.request.Request(
            self.racine + chemin,
            headers=self.ENTETE_FENETRE if fenetre else {})
        with urllib.request.urlopen(demande, timeout=5) as reponse:
            return reponse.status, reponse.read().decode("utf-8")

    def _poster(self, chemin, donnees=None, fenetre=False):
        # doseq : un champ répété (plusieurs valeurs de même nom, comme les
        # champs personnalisés portés par la page) s'envoie ligne par ligne.
        octets = urllib.parse.urlencode(donnees or {},
                                        doseq=True).encode("utf-8")
        demande = urllib.request.Request(
            self.racine + chemin, data=octets,
            headers=self.ENTETE_FENETRE if fenetre else {})
        with urllib.request.urlopen(demande, timeout=15) as reponse:
            return reponse.status, reponse.read().decode("utf-8")

    def _brouillon(self, page):
        """L'identifiant du brouillon d'assistant porté par la page."""
        return re.search(r'name="b" value="(\d+)"', page).group(1)

    @staticmethod
    def _valeur_affichee(page, ident):
        """La valeur qu'un champ PORTE DÉJÀ dans la page (None s'il n'y est pas).

        ⚠ CE QUE LE NAVIGATEUR RENVERRAIT, et c'est tout l'objet. Un essai qui
        poste une valeur inventée à la place du pré-remplissage n'éprouve plus
        le calcul : il l'écrase, et mesure ensuite sa propre invention. Deux
        essais de créneaux vivaient ainsi depuis le 17/08/2026 — ils passaient
        au vert avec un stock qui valait « mardi 9h00, mercredi 14h30 ».
        """
        zone = re.search(r'<textarea[^>]*id="%s"[^>]*>(.*?)</textarea>'
                         % re.escape(ident), page, re.S)
        if zone:
            return html.unescape(zone.group(1))
        balise = re.search(r'<input[^>]*id="%s"[^>]*>' % re.escape(ident), page)
        if not balise:
            return None
        valeur = re.search(r'value="([^"]*)"', balise.group(0))
        return html.unescape(valeur.group(1)) if valeur else ""

    def _menu_relances(self, page):
        """Le menu des types de rappel : {libellé: nombre}.

        Le nombre est dans son propre <span> (il se colore autrement) ; on
        le relit donc plutôt que d'écrire le balisage dans chaque essai.
        """
        return {libelle.strip(): int(nombre) for libelle, nombre in re.findall(
            r'data-vue="panneau-[a-z_]+">(.*?)'
            r'<span class="famille-nombre">\((\d+)\)</span>', page)}

    def _panneau_relance(self, page, code):
        """Le panneau d'un type de rappel : (visible, contenu HTML)."""
        ouverture = re.search(
            r'<section class="panneau-relance" id="panneau-%s"( hidden)?>'
            % code, page)
        self.assertIsNotNone(ouverture, f"panneau « {code} » absent de la page")
        fin = page.index("</section>", ouverture.end())
        return ouverture.group(1) is None, page[ouverture.end():fin]

    def _demarrer(self, campagne_id):
        """▶ Démarrer, le geste sur l'agenda compris.

        Le poste de pilotage demande une confirmation CONSCIENTE avant de
        lancer : les créneaux annoncés au téléphone sortent de l'agenda de
        RingBack, et un agenda périmé ferait proposer des places déjà prises
        ailleurs. Le clic sur le bouton du panneau envoie
        « agenda_verifie=1 » — c'est ce que ce raccourci reproduit. Le REFUS
        quand ce geste manque a ses tests dédiés
        (TestVerificationAgendaAvantDemarrage).
        """
        return self._poster("/campagne/demarrer",
                            {"campagne": campagne_id, "agenda_verifie": "1"})

    def _attendre_statut(self, campagne_id, statut, delai=30):
        """Attend qu'une campagne lancée en fil de fond atteigne CE statut."""
        fin = time.monotonic() + delai
        while time.monotonic() < fin:
            if (self.application.base.obtenir_campagne(campagne_id)["statut"]
                    == statut):
                return
            time.sleep(0.1)
        self.fail(f"La campagne n°{campagne_id} n'a pas atteint le statut "
                  f"« {statut} » (statut actuel : "
                  f"{self.application.base.obtenir_campagne(campagne_id)['statut']}).")


class TestServeur(_TestAvecServeurWeb):

    def test_demarrage_liste_et_rappel(self):
        statut, accueil = self._obtenir("/suivi")
        self.assertEqual(statut, 200)
        # ⚠ TROIS SECTIONS ONT ÉTÉ RETIRÉES de cet écran (10/08/2026) : « À
        # rappeler (manqués) », « ☎ À contacter à la main » et « 📅 Rendez-vous
        # à venir ». Il ne reste que le planning et le geste d'import — et le
        # lien vers 🗂 Tous les rendez-vous, sans quoi plus aucune liste ne
        # serait atteignable depuis ici.
        for retiree in ("À rappeler (manqués)", "À contacter à la main",
                        "Rendez-vous à venir"):
            with self.subTest(retiree=retiree):
                self.assertNotIn(retiree, accueil)
        self.assertIn("＋ Importer votre agenda", accueil)
        self.assertIn('href="/tous"', accueil)
        self.assertNotIn("+33 6 00 00 00 41", accueil)  # jamais en clair
        _, tous = self._obtenir("/tous")
        self.assertIn("••", tous)                       # numéros masqués
        self.assertNotIn("+33 6 00 00 00 41", tous)
        donnees = urllib.parse.urlencode({"rdv": 1}).encode("ascii")
        with urllib.request.urlopen(self.racine + "/rappeler", data=donnees,
                                    timeout=10) as reponse:
            fiche = reponse.read().decode("utf-8")  # 303 suivi automatiquement
        self.assertIn("Transcription", fiche)
        self.assertIn("appointment_status", fiche)

    def test_ajout_par_formulaire_puis_detection_manque(self):
        donnees = urllib.parse.urlencode({
            "nom": "Mme Ajoutée EnLigne", "telephone": "+33 6 00 00 00 49",
            "date_heure": HIER, "motif": "Séance ajoutée"}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            confirmation = reponse.read().decode("utf-8")
        self.assertIn("Rendez-vous enregistré", confirmation)
        self.assertIn("+33 6 •• •• •• 49", confirmation)   # masqué
        self.assertNotIn("+33 6 00 00 00 49", confirmation)  # jamais en clair
        # Un horaire passé devient « manqué » : il se lit dans 🗂 Tous les
        # rendez-vous depuis que « À rappeler » a été retirée (10/08/2026).
        _, tous = self._obtenir("/tous")
        self.assertIn("Mme Ajoutée EnLigne", tous)

    def test_ajout_futur_visible_immediatement(self):
        """Le défaut vécu : une saisie future doit se voir TOUT DE SUITE.

        ⚠ « 📅 Rendez-vous à venir » A ÉTÉ RETIRÉE le 10/08/2026 : ce qui
        compte reste le même — la saisie ne doit pas disparaître dans le vide.
        Elle se voit sur le PLANNING (sa tuile) et dans 🗂 Tous les rendez-vous,
        et la confirmation mène aux deux.
        """
        donnees = urllib.parse.urlencode({
            "nom": "Mme Danse Exemple", "telephone": "+33 6 00 00 00 45",
            "date_heure": DEMAIN, "motif": "Séance de danse"}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            confirmation = reponse.read().decode("utf-8")
        # La confirmation dit OÙ le rendez-vous est visible, avec ses liens.
        self.assertIn("visible dès maintenant sur le planning", confirmation)
        self.assertIn('href="/suivi"', confirmation)
        self.assertIn('href="/tous"', confirmation)
        # Le planning porte sa tuile, tout de suite.
        # ⚠ SUR LA SEMAINE DU RENDEZ-VOUS, PAS SUR « la semaine courante »
        # (16/08/2026). Le planning s'ouvre sur la semaine d'aujourd'hui : un
        # DIMANCHE, « demain » tombe la semaine SUIVANTE, et l'essai échouait —
        # en mesurant le calendrier, pas le produit. C'est la même famille de
        # piège que les jours ouvrés du banc (voir banc_essai._jour_ouvre).
        demain = datetime.date.fromisoformat(DEMAIN[:10])
        annee, semaine, _ = demain.isocalendar()
        _, accueil = self._obtenir(f"/suivi?annee={annee}&semaine={semaine}")
        self.assertIn("Mme Danse Exemple", accueil)
        self.assertNotIn("+33 6 00 00 00 45", accueil)   # jamais en clair
        # Et la liste complète le montre, numéro masqué comme partout.
        _, tous = self._obtenir("/tous")
        self.assertIn("Mme Danse Exemple", tous)
        self.assertIn("Séance de danse", tous)
        self.assertIn("+33 6 •• •• •• 45", tous)
        self.assertNotIn("+33 6 00 00 00 45", tous)

    def test_ajout_passe_pointe_vers_a_rappeler(self):
        donnees = urllib.parse.urlencode({
            "nom": "M. Manqué Hier", "telephone": "+33 6 00 00 00 46",
            "date_heure": HIER, "motif": "Essai"}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            confirmation = reponse.read().decode("utf-8")
        self.assertIn("Statut : manqué", confirmation)
        # Le renvoi ne pointe plus sur une ancre disparue.
        self.assertIn("Tous les rendez-vous", confirmation)
        self.assertNotIn("#a-rappeler", confirmation)

    def test_page_tous_les_rendezvous(self):
        # Un futur en plus des 4 manqués de la démo : il doit sortir en tête
        # (tri antichronologique) avec son statut visible.
        donnees = urllib.parse.urlencode({
            "nom": "Mme Complète Liste", "telephone": "+33 6 00 00 00 47",
            "date_heure": DEMAIN, "motif": "Essai complet"}).encode("utf-8")
        urllib.request.urlopen(self.racine + "/ajouter", data=donnees, timeout=5).read()
        statut, page = self._obtenir("/tous")
        self.assertEqual(statut, 200)
        self.assertIn("Tous les rendez-vous (5)", page)
        self.assertIn("prévu", page)                     # les statuts sont visibles
        self.assertIn("manqué", page)
        self.assertLess(page.index("Mme Complète Liste"),  # le plus récent d'abord
                        page.index("Mme Nadia Lefèvre"))
        self.assertNotIn("+33 6 00 00 00 4", page)       # jamais en clair

    def test_doublon_signale_puis_ajout_explicite(self):
        base = self.application.base
        donnees = urllib.parse.urlencode({
            "nom": "Mme Double Saisie", "telephone": "+33 6 00 00 00 48",
            "date_heure": DEMAIN, "motif": "Séance unique"}).encode("utf-8")
        urllib.request.urlopen(self.racine + "/ajouter", data=donnees, timeout=5).read()
        avant = base.conn.execute("SELECT COUNT(*) FROM rendezvous").fetchone()[0]
        # Même client + même horaire : SIGNALÉ, rien de créé.
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn("Ce rendez-vous existe déjà", page)
        self.assertIn("rien n'a été ajouté", page)
        self.assertIn("Ajouter quand même", page)
        self.assertIn("+33 6 •• •• •• 48", page)             # masqué
        self.assertNotIn("+33 6 00 00 00 48", page)          # jamais en clair
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM rendezvous").fetchone()[0], avant)  # pas de doublon
        # « Ajouter quand même » : l'ajout se fait, EXPLICITEMENT.
        client_id = re.search(r'name="forcer" value="(\d+)"', page).group(1)
        confirmation_donnees = urllib.parse.urlencode({
            "forcer": client_id, "date_heure": DEMAIN,
            "motif": "Séance unique"}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter",
                                    data=confirmation_donnees, timeout=5) as reponse:
            confirmation = reponse.read().decode("utf-8")
        self.assertIn("Rendez-vous enregistré", confirmation)
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM rendezvous").fetchone()[0], avant + 1)
        self.assertEqual(base.compter_clients(), 5)  # 4 démo + 1, pas de client double

    def test_ajout_invalide_affiche_les_erreurs_en_francais(self):
        donnees = urllib.parse.urlencode({
            "nom": "", "telephone": "12345",
            "date_heure": "bientôt", "motif": ""}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn("Saisie refusée", page)
        self.assertIn("Numéro de téléphone invalide", page)
        self.assertIn("Date illisible", page)

    def test_import_csv_par_le_serveur(self):
        contenu = ("nom;telephone;date_heure;motif\n"
                   f"Mme Import Réseau;+33 6 00 00 00 45;{HIER};Consultation\n"
                   "M. Numero Faux;12345;2026-08-01T10:00;Essai\n")
        frontiere = "----frontiereDeTest"
        corps = (f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="fichier"; filename="import.csv"\r\n'
                 "Content-Type: text/csv\r\n\r\n"
                 f"{contenu}\r\n--{frontiere}--\r\n").encode("utf-8")
        requete = urllib.request.Request(
            self.racine + "/importer", data=corps,
            headers={"Content-Type": f"multipart/form-data; boundary={frontiere}"})
        with urllib.request.urlopen(requete, timeout=5) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn("<strong>1</strong> rendez-vous importé", page)
        self.assertIn("Ligne 3", page)  # la ligne fautive est signalée
        _, tous = self._obtenir("/tous")
        self.assertIn("Mme Import Réseau", tous)
        self.assertNotIn("+33 6 00 00 00 45", tous)     # toujours masqué


class TestServeurFileAppels(_TestAvecServeurWeb):
    """La page « File d'appels » : tout rappeler, annuler, exécuter, bilan."""

    def test_page_file_vide_au_depart(self):
        statut, page = self._obtenir("/file")
        self.assertEqual(statut, 200)
        self.assertIn("File d'appels", page)
        self.assertIn("La file est vide", page)
        self.assertIn("Tout rappeler", page)
        self.assertIn("Bilan des issues", page)
        self.assertIn("Mode simulation", page)

    def test_tout_rappeler_annuler_puis_executer(self):
        # 1. « Tout rappeler » : les 4 manqués de la démonstration entrent en file.
        _, page = self._poster("/file/tout-rappeler")
        self.assertIn("4 appel(s) mis en file", page)
        self.assertIn("Mme Nadia Lefèvre", page)
        self.assertIn("Appels en attente (4)", page)
        self.assertIn("••", page)                       # numéros masqués
        self.assertNotIn("+33 6 00 00 00 41", page)     # jamais en clair
        # Re-cliquer ne double aucun appel.
        _, page = self._poster("/file/tout-rappeler")
        self.assertIn("Aucun nouvel appel", page)
        self.assertIn("Appels en attente (4)", page)
        # 2. Annuler le premier appel de la file AVANT exécution.
        premier = self.application.planif.file[0]["appel_id"]
        _, page = self._poster("/file/annuler", {"appel": premier})
        self.assertIn("Appel retiré de la file", page)
        self.assertIn("Appels en attente (3)", page)
        self.assertEqual(self.application.base.obtenir_appel(premier)["statut"],
                         "annulé")
        # L'annuler à nouveau : introuvable, sans casse.
        _, page = self._poster("/file/annuler", {"appel": premier})
        self.assertIn("introuvable", page)
        # 3. Exécuter la file : les 3 appels restants passent (simulés).
        _, page = self._poster("/file/executer")
        self.assertIn("Exécution terminée", page)
        self.assertIn("<strong>3</strong> appel(s) traité(s)", page)
        self.assertIn("Voir la fiche", page)
        self.assertIn("Bilan des issues", page)
        self.assertNotIn("+33 6 00 00 00 4", page)      # jamais en clair
        # 4. Le bilan compte exactement les 3 issues (l'annulé ne compte pas).
        bilan = self.application.base.bilan_issues()
        self.assertEqual(sum(bilan.values()), 3)
        _, page_file = self._obtenir("/file")
        self.assertIn("La file est vide", page_file)     # tout est parti


class TestServeurCascade(_TestAvecServeurWeb):
    """La page « Cascade premier oui », exercée en vraies requêtes HTTP."""

    LISTE = ("Mme Refus Un;+33 6 00 00 00 52\n"
             "M. Silence Deux, 06 00 00 00 53\n"
             "Mme Accord Trois;+33 6 00 00 00 51\n"
             "M. Épargné Quatre;+33 6 00 00 00 49\n")

    def test_formulaire_pre_rempli(self):
        statut, page = self._obtenir("/cascade")
        self.assertEqual(statut, 200)
        self.assertIn("Cascade « premier oui »", page)
        self.assertIn("j&#x27;appelle de la part de [entreprise]", page)
        self.assertIn("Créneau proposé", page)

    def test_cascade_de_bout_en_bout_par_http(self):
        _, page = self._poster("/cascade/executer", {
            "liste": self.LISTE, "mission": "Un créneau s'est libéré [créneau]. "
            "Intéressé ?", "creneau": DEMAIN})    # 303 suivi automatiquement
        self.assertIn("créneau pourvu", page)
        self.assertIn("Créneau attribué à <strong>Mme Accord Trois</strong>", page)
        self.assertIn("Personnes appelées (3)", page)
        self.assertIn("Pas de réponse", page)                # M. Silence Deux
        # ⚠ LE MOT AFFICHÉ VIENT DE `mot_etat` (14/08/2026, audit croisé) :
        # cette page écrivait encore « épargné » en clair, seule de tout le
        # produit, alors que le propriétaire a dit ne pas comprendre ce mot.
        self.assertIn("Personnes non appelées (1)", page)
        self.assertIn("M. Épargné Quatre", page)
        self.assertIn("pas appelé (créneau pris)", page)
        self.assertNotIn("épargné (créneau pris)", page)
        self.assertIn("jamais appelé", page)
        self.assertIn("Transcriptions", page)
        self.assertIn("••", page)                            # numéros masqués
        self.assertNotIn("+33 6 00 00 00 5", page)           # jamais en clair
        self.assertNotIn("+33 6 00 00 00 49", page)
        self.assertNotIn("[créneau]", page)                  # gabarit remplacé
        # Le rendez-vous créé est bien visible côté application.
        cascade = self.application.base.obtenir_cascade(1)
        rdv = self.application.base.obtenir_rendezvous(cascade["rendezvous_id"])
        self.assertEqual((rdv["nom"], rdv["horaire"], rdv["statut"]),
                         ("Mme Accord Trois", DEMAIN, "confirmé"))

    def test_liste_epuisee_message_honnete(self):
        _, page = self._poster("/cascade/executer", {
            "liste": "Mme Refus Un;+33 6 00 00 00 52\n",
            "mission": "Un créneau s'est libéré.", "creneau": DEMAIN})
        self.assertIn("liste épuisée, créneau non pourvu", page)
        self.assertIn("personne n'a pris le créneau", page)

    def test_saisie_refusee_en_francais_sans_reafficher_les_numeros(self):
        # Le 47 n'apparaît nulle part ailleurs dans la page (contrairement aux
        # exemples statiques du gabarit) : s'il ressortait, ce serait la liste.
        _, page = self._poster("/cascade/executer", {
            "liste": "pas de séparateur ici\nM. Bon;+33 6 00 00 00 47\n",
            "mission": "", "creneau": ""})
        self.assertIn("Saisie refusée", page)
        self.assertIn("séparateur introuvable", page)
        self.assertIn("La mission est obligatoire", page)
        self.assertIn("Créneau proposé", page)
        self.assertIn("la liste (qui contient des numéros", page)
        self.assertNotIn("+33 6 00 00 00 47", page)  # la liste n'est pas renvoyée
        self.assertNotIn("M. Bon", page)


class TestServeurGenerationCascade(_TestAvecServeurWeb):
    """Génération de la liste depuis la base + export CSV, par vraies requêtes."""

    def _poster_brut(self, chemin, donnees):
        """POST qui rend (statut, en-têtes, octets) — pour inspecter le CSV."""
        octets = urllib.parse.urlencode(donnees).encode("utf-8")
        with urllib.request.urlopen(self.racine + chemin, data=octets,
                                    timeout=15) as reponse:
            return reponse.status, dict(reponse.headers), reponse.read()

    def test_premiere_visite_aucun_ordre_preselectionne(self):
        _, page = self._obtenir("/cascade")
        self.assertIn("Remplir depuis les rendez-vous", page)
        self.assertIn("aucun ordre n'est imposé", page)
        for code in generation.ORDRES:
            self.assertNotIn(f'value="{code}" checked', page)  # AUCUN ordre coché
        self.assertIn('value="annules" checked', page)         # source, elle, l'est

    def test_generation_injecte_puis_memorise_l_ordre(self):
        _, page = self._poster("/cascade/generer", {
            "liste": "", "mission": "Mission.", "creneau": "",
            "source": "tous", "ordre": "alphabetique"})
        self.assertIn("4 personne(s) dans la liste", page)
        # La liste est INJECTÉE dans la zone de collage, en clair (c'est son
        # but), dans l'ordre alphabétique sans tenir compte de la civilité.
        zone = re.search(r"<textarea[^>]*>([^<]*)</textarea>", page).group(1)
        self.assertEqual(html.unescape(zone).splitlines(), [
            "Mme Élise Charpentier;+33 6 00 00 00 43",
            "M. Karim Osman;+33 6 00 00 00 42",
            "Mme Nadia Lefèvre;+33 6 00 00 00 41",
            "M. Paul Guillot;+33 6 00 00 00 44"])
        # Le choix est mémorisé : la page suivante présélectionne cet ordre.
        _, page = self._obtenir("/cascade")
        self.assertIn('value="alphabetique" checked', page)
        self.assertIn('value="tous" checked', page)

    def test_generation_sans_ordre_refusee_liste_conservee(self):
        _, page = self._poster("/cascade/generer", {
            "liste": "M. Garde Contenu;+33 6 00 00 00 47", "mission": "Mission.",
            "creneau": "", "source": "annules", "ordre": ""})
        self.assertIn("aucun ordre n&#x27;est imposé par défaut", page)
        self.assertIn("M. Garde Contenu;+33 6 00 00 00 47", page)  # zone conservée

    def test_proximite_sans_creneau_refusee(self):
        _, page = self._poster("/cascade/generer", {
            "liste": "", "mission": "Mission.", "creneau": "",
            "source": "tous", "ordre": "proximite"})
        self.assertIn("créneau proposé", page)

    def test_generation_signale_les_sans_numero(self):
        base = self.application.base
        client_id = base.obtenir_ou_creer_client("Mme Sans Fil", "")
        base.ajouter_rendezvous(client_id, DEMAIN, "Essai")
        _, page = self._poster("/cascade/generer", {
            "liste": "", "mission": "Mission.", "creneau": "",
            "source": "tous", "ordre": "alphabetique"})
        self.assertIn("1 client(s) sans numéro exclu(s)", page)
        self.assertIn("/sans-numero", page)

    def test_csv_telecharge_avec_bom_et_en_clair(self):
        statut, entetes, octets = self._poster_brut("/cascade/csv", {
            "liste": "", "mission": "Mission.", "creneau": "",
            "source": "tous", "ordre": "anciennete"})
        self.assertEqual(statut, 200)
        self.assertIn("text/csv", entetes["Content-Type"])
        self.assertRegex(entetes["Content-Disposition"],
                         r'attachment; filename="liste_rappel_\d{8}\.csv"')
        self.assertTrue(octets.startswith(b"\xef\xbb\xbf"))     # BOM pour Excel
        texte = octets.decode("utf-8-sig")
        self.assertTrue(texte.startswith("nom;telephone\r\n"))
        self.assertIn("+33 6 00 00 00 41", texte)  # EN CLAIR : c'est le but du fichier
        # Ancienneté : les deux rendez-vous d'avant-hier avant ceux d'hier.
        self.assertLess(texte.index("Mme Élise Charpentier"),
                        texte.index("Mme Nadia Lefèvre"))

    def test_csv_respecte_la_zone_de_collage_reordonnee(self):
        # L'utilisateur a réordonné sa liste à la main : le CSV la respecte.
        _, entetes, octets = self._poster_brut("/cascade/csv", {
            "liste": ("M. Zoulou Dernier;+33 6 00 00 00 49\n"
                      "Mme Alpha Premiere;+33 6 00 00 00 48\n"),
            "mission": "Mission.", "creneau": "", "source": "", "ordre": ""})
        texte = octets.decode("utf-8-sig")
        self.assertEqual(texte.splitlines(), [
            "nom;telephone",
            "M. Zoulou Dernier;+33 6 00 00 00 49",
            "Mme Alpha Premiere;+33 6 00 00 00 48"])

    def test_cascade_generee_puis_lancee(self):
        _, page = self._poster("/cascade/generer", {
            "liste": "", "mission": "Mission de test.", "creneau": DEMAIN,
            "source": "tous", "ordre": "anciennete"})
        zone = html.unescape(
            re.search(r"<textarea[^>]*>([^<]*)</textarea>", page).group(1))
        _, page = self._poster("/cascade/executer", {
            "liste": zone, "mission": "Un créneau s'est libéré [créneau].",
            "creneau": DEMAIN})
        self.assertIn("Cascade n°", page)             # la cascade générée a tourné
        cascade = self.application.base.lister_cascades()[0]
        appels = self.application.base.appels_de_cascade(cascade["id"])
        self.assertEqual(len(appels), 4)              # les 4 clients de la démo
        self.assertNotIn("+33 6 00 00 00 4", page)    # et toujours rien en clair


class TestServeurPreferencesDisque(unittest.TestCase):
    """Le dernier ordre choisi survit à un redémarrage (donnees/preferences.json)."""

    def test_preference_ecrite_puis_relue_apres_redemarrage(self):
        dossier = tempfile.mkdtemp(prefix="ringback-prefsrv-")
        self.addCleanup(shutil.rmtree, dossier, ignore_errors=True)
        chemin_base = os.path.join(dossier, "ringback.db")

        def demarrer():
            serveur_http = serveur.creer_serveur(port=0, chemin_base=chemin_base)
            threading.Thread(target=serveur_http.serve_forever, daemon=True).start()
            return serveur_http, f"http://127.0.0.1:{serveur_http.server_address[1]}"

        premier, racine = demarrer()
        octets = urllib.parse.urlencode({
            "liste": "", "mission": "Mission.", "creneau": "",
            "source": "annules", "ordre": "alphabetique",
        }).encode("utf-8")
        urllib.request.urlopen(racine + "/cascade/generer", data=octets,
                               timeout=15).read()
        chemin_prefs = os.path.join(dossier, "preferences.json")
        self.assertTrue(os.path.exists(chemin_prefs))  # écrit À CÔTÉ de la base
        with open(chemin_prefs, encoding="utf-8") as fichier:
            self.assertEqual(json.load(fichier)["cascade_ordre"], "alphabetique")
        premier.RequestHandlerClass.application.base.fermer()
        premier.shutdown()
        premier.server_close()
        second, racine = demarrer()                    # redémarrage : relu du disque
        with urllib.request.urlopen(racine + "/cascade", timeout=15) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn('value="alphabetique" checked', page)
        second.RequestHandlerClass.application.base.fermer()
        second.shutdown()
        second.server_close()


class TestServeurImportICS(_TestAvecServeurWeb):
    """Import d'agenda ICS + complétion des numéros, en vraies requêtes HTTP."""

    def _importer_ics(self, contenu):
        frontiere = "----frontiereDeTest"
        corps = (f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="fichier"; filename="agenda.ics"\r\n'
                 "Content-Type: text/calendar\r\n\r\n"
                 f"{contenu}\r\n--{frontiere}--\r\n").encode("utf-8")
        requete = urllib.request.Request(
            self.racine + "/importer-ics", data=corps,
            headers={"Content-Type": f"multipart/form-data; boundary={frontiere}"})
        with urllib.request.urlopen(requete, timeout=5) as reponse:
            return reponse.read().decode("utf-8")

    def test_import_exemple_puis_completion_du_numero(self):
        chemin = os.path.join(RACINE, "exemple_agenda.ics")
        with open(chemin, encoding="utf-8") as fichier:
            page = self._importer_ics(fichier.read())
        # ⚠ ON ARRIVE SUR L'AGENDA, compte rendu en tête (10/08/2026).
        self.assertIn('<section id="planning">', page)
        self.assertIn("📥 Import terminé", page)
        self.assertIn("<strong>3</strong> rendez-vous importé(s)", page)
        self.assertIn("journée entière", page)      # l'événement sans heure, signalé
        self.assertIn("rendez-vous sans numéro — à compléter", page)
        # L'écran « sans numéro » liste les trois rendez-vous importés.
        _, page_sans = self._obtenir("/sans-numero")
        self.assertIn("Rendez-vous sans numéro", page_sans)
        self.assertIn("Mme Léa Fontaine", page_sans)
        # Un numéro invalide est refusé en français…
        client_id = self.application.base.rendezvous_sans_numero()[0]["client_id"]
        _, page_refus = self._poster("/completer-numero",
                                     {"client": client_id, "telephone": "12345"})
        self.assertIn("Numéro refusé", page_refus)
        # …et un numéro valide complète le client (masqué partout ensuite).
        _, page_ok = self._poster("/completer-numero",
                                  {"client": client_id, "telephone": "+33600000049"})
        self.assertEqual(len(self.application.base.rendezvous_sans_numero()), 2)
        self.assertEqual(self.application.base.telephone_de(client_id),
                         "+33 6 00 00 00 49")
        _, accueil = self._obtenir("/suivi")
        self.assertNotIn("+33 6 00 00 00 49", accueil)  # toujours masqué à l'écran

    def test_fichier_non_ics_refuse(self):
        page_erreur = None
        try:
            self._importer_ics("Ceci n'est pas un agenda.")
        except urllib.error.HTTPError as erreur:
            page_erreur = erreur.read().decode("utf-8")
            self.assertEqual(erreur.code, 400)
        self.assertIn("Aucun événement (VEVENT) trouvé", page_erreur)


class TestServeurModeReel(_TestAvecServeurWeb):
    """Le jour J, zéro code : variables d'environnement + mode réel, exercé
    ici de bout en bout contre la fausse API locale (jamais la vraie)."""

    appels_reels = True

    def setUp(self):
        class Faux(_FauxApiCalle):
            creations = []
            etats = [reponse_calle_terminee(dict(RESULTAT_CONFORME))]
        self.faux = Faux
        self.serveur_api = HTTPServer(("127.0.0.1", 0), Faux)
        threading.Thread(target=self.serveur_api.serve_forever, daemon=True).start()
        self.addCleanup(self.serveur_api.server_close)
        self.addCleanup(self.serveur_api.shutdown)
        os.environ["CALLE_API_KEY"] = "cle-de-test-0123456789"      # verrou 1 (clé factice)
        os.environ["CALLE_API_URL"] = \
            f"http://127.0.0.1:{self.serveur_api.server_address[1]}"
        self.addCleanup(os.environ.pop, "CALLE_API_KEY", None)
        self.addCleanup(os.environ.pop, "CALLE_API_URL", None)
        # L'audit part dans un dossier jetable, pas dans donnees/.
        self.dossier = tempfile.mkdtemp(prefix="ringback-audit-")
        self.addCleanup(shutil.rmtree, self.dossier, ignore_errors=True)
        self.chemin_audit = os.path.join(self.dossier, "audit.jsonl")
        self._audit_sauve = calle_client.CHEMIN_AUDIT
        calle_client.CHEMIN_AUDIT = self.chemin_audit
        self.addCleanup(setattr, calle_client, "CHEMIN_AUDIT", self._audit_sauve)
        super().setUp()   # creer_serveur(appels_reels=True) lit ces variables

    def test_mode_reel_de_bout_en_bout_sur_fausse_api(self):
        _, accueil = self._obtenir("/")            # accueil = Campagnes
        self.assertIn("MODE RÉEL", accueil)
        # ⚠ PLUS AUCUN BOUTON NE MÈNE ICI depuis le 10/08/2026 : le lien
        # « Rappeler » vivait dans « À rappeler (manqués) », retirée à la
        # demande du propriétaire. La page existe toujours et dit bien
        # « RÉEL » — reste à décider où la reloger.
        _, prepare = self._obtenir("/rappel?rdv=1")
        self.assertIn("RÉEL", prepare)
        _, accueil = self._obtenir("/suivi")
        self.assertNotIn("+33 6 00 00 00 41", accueil)   # masquage inchangé
        _, page = self._poster("/file/tout-rappeler")
        self.assertIn("4 appel(s) mis en file", page)
        _, page = self._poster("/file/executer")
        self.assertIn("Exécution terminée", page)
        self.assertIn("<strong>4</strong> appel(s) traité(s)", page)
        self.assertNotIn("+33 6 00 00 00 4", page)
        # La fausse API a bien reçu les 4 créations d'appels.
        self.assertEqual(len(self.faux.creations), 4)
        self.assertEqual(self.faux.creations[0]["recipients"][0]["region"], "FR")
        # Chaque appel réel a laissé sa ligne d'audit, numéro masqué.
        with open(self.chemin_audit, encoding="utf-8") as fichier:
            contenu = fichier.read()
        lignes = [json.loads(ligne) for ligne in contenu.splitlines() if ligne.strip()]
        self.assertEqual(len(lignes), 4)
        self.assertNotIn("+33 6 00 00 00 4", contenu)    # jamais en clair
        self.assertTrue(all(l["statut"] == "terminé" for l in lignes))
        self.assertTrue(all("••" in l["telephone"] for l in lignes))


# --------------------------------------------------------------------------
# Lots d'améliorations : clients et listes, thèmes d'appel, réglages,
# interface (bascule clair/sombre). Tout est exercé pour de vrai : base en
# mémoire ou dossier jetable, jamais la base réelle donnees/ringback.db.
# --------------------------------------------------------------------------
class TestMigrationBase(unittest.TestCase):
    """Une base à l'ANCIEN schéma s'ouvre et reçoit les colonnes récentes."""

    def test_ancienne_base_migree_sans_perte(self):
        dossier = tempfile.mkdtemp(prefix="ringback-migration-")
        self.addCleanup(shutil.rmtree, dossier, ignore_errors=True)
        chemin = os.path.join(dossier, "ringback.db")
        import sqlite3
        brute = sqlite3.connect(chemin)
        brute.executescript("""
            CREATE TABLE clients (id INTEGER PRIMARY KEY AUTOINCREMENT,
                                  nom TEXT NOT NULL, telephone TEXT NOT NULL);
            CREATE TABLE rendezvous (id INTEGER PRIMARY KEY AUTOINCREMENT,
                                     client_id INTEGER NOT NULL,
                                     horaire TEXT NOT NULL, motif TEXT NOT NULL,
                                     statut TEXT NOT NULL DEFAULT 'prévu');
            INSERT INTO clients (nom, telephone)
                VALUES ('Mme Ancienne Base', '+33 6 00 00 00 42');
            INSERT INTO rendezvous (client_id, horaire, motif, statut)
                VALUES (1, '2026-01-01T10:00', 'Essai', 'manqué');
        """)
        brute.commit()
        brute.close()
        base = db.Base(chemin)          # la migration douce se joue ici
        self.addCleanup(base.fermer)
        clients = base.lister_clients()
        self.assertEqual(len(clients), 1)
        self.assertEqual(clients[0]["nom"], "Mme Ancienne Base")
        self.assertFalse(clients[0]["ne_plus_appeler"])   # défaut : appelable
        rdv = base.rendezvous_manques()[0]
        self.assertIsNone(rdv["rappel_souhaite"])         # colonne ajoutée, vide
        self.assertEqual(rdv["nom"], "Mme Ancienne Base")  # données intactes


class TestNePlusAppeler(unittest.TestCase):
    """Le drapeau « Ne plus appeler » : exclu de la file, des cascades et
    des listes générées — réversible, et visible dans les données."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.marquee = self.base.ajouter_client("Mme Stop Exemple",
                                                "+33 6 00 00 00 51")
        self.rdv_marquee = self.base.ajouter_rendezvous(
            self.marquee, HIER, "Essai", statut="manqué")
        self.autre = self.base.ajouter_client("M. Libre Exemple",
                                              "+33 6 00 00 00 52")
        self.rdv_autre = self.base.ajouter_rendezvous(
            self.autre, HIER, "Essai", statut="manqué")
        self.base.definir_ne_plus_appeler(self.marquee, True)

    def test_drapeau_pose_visible_et_reversible(self):
        client = self.base.obtenir_client(self.marquee)
        self.assertTrue(client["ne_plus_appeler"])
        self.assertEqual(client["telephone_masque"], "+33 6 •• •• •• 51")
        rdv = self.base.obtenir_rendezvous(self.rdv_marquee)
        self.assertTrue(rdv["ne_plus_appeler"])           # porté par les listes
        self.base.definir_ne_plus_appeler(self.marquee, False)   # réversible
        self.assertFalse(self.base.obtenir_client(self.marquee)["ne_plus_appeler"])

    def test_exclu_de_la_mise_en_file_groupee(self):
        planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=1, latence=0))
        crees = planif.programmer_tous_les_manques()
        self.assertEqual(len(crees), 1)                   # seulement M. Libre
        rdv = self.base.obtenir_rendezvous(planif.file[0]["rendezvous_id"])
        self.assertEqual(rdv["nom"], "M. Libre Exemple")

    def test_rappel_individuel_refuse(self):
        planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=1, latence=0))
        with self.assertRaises(planificateur.ClientExclu) as contexte:
            planif.programmer(self.rdv_marquee)
        self.assertIn("Ne plus appeler", str(contexte.exception))
        self.assertEqual(planif.file, [])                 # rien en file

    def test_exclu_de_la_generation_de_liste(self):
        personnes, _ = generation.generer(self.base, "tous", "alphabetique")
        noms = [p["nom"] for p in personnes]
        self.assertEqual(noms, ["M. Libre Exemple"])      # la marquée est écartée

    def test_cascade_ne_compose_jamais_son_numero(self):
        compteur = ClientCompteur(graine=6, latence=0)
        planif = planificateur.Planificateur(self.base, compteur)
        cascade_id = planif.executer_cascade(
            [{"nom": "Mme Stop Exemple", "telephone": "+33 6 00 00 00 51"},
             {"nom": "M. Libre Exemple", "telephone": "+33 6 00 00 00 52"}],
            "Un créneau s'est libéré.", DEMAIN)
        # PREUVE par compteur : le numéro marqué n'a JAMAIS été composé,
        # même collé à la main dans la liste.
        self.assertEqual(compteur.numeros_composes, ["+33 6 •• •• •• 52"])
        appels = self.base.appels_de_cascade(cascade_id)
        self.assertEqual([a["etat"] for a in appels], ["exclu", "appelé"])
        self.assertIsNone(appels[0]["issue"])             # exclu : pas d'issue


class TestViderLesListes(unittest.TestCase):
    """« Vider la liste » (manqués -> ignorés, réversible) et « Vider la file »."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        client_id = self.base.ajouter_client("Mme Vide Exemple", "+33 6 00 00 00 42")
        self.rdv_un = self.base.ajouter_rendezvous(client_id, HIER, "Un", statut="manqué")
        self.rdv_deux = self.base.ajouter_rendezvous(client_id, HIER, "Deux", statut="manqué")
        self.rdv_prevu = self.base.ajouter_rendezvous(client_id, DEMAIN, "Futur")

    def test_ignorer_tous_reversible_par_rendezvous(self):
        self.assertEqual(self.base.ignorer_tous_les_manques(), 2)
        self.assertEqual(self.base.rendezvous_manques(), [])       # liste vidée
        self.assertEqual(self.base.obtenir_rendezvous(self.rdv_prevu)["statut"],
                         "prévu")                                  # intact
        # La règle du manqué ne ré-avale PAS les ignorés.
        self.base.marquer_manques_echus()
        self.assertEqual(self.base.obtenir_rendezvous(self.rdv_un)["statut"],
                         "ignoré")
        # Réversible, un par un, depuis « Tous les rendez-vous ».
        self.assertTrue(self.base.retablir_manque(self.rdv_un))
        self.assertEqual(self.base.obtenir_rendezvous(self.rdv_un)["statut"],
                         "manqué")
        self.assertFalse(self.base.retablir_manque(self.rdv_prevu))  # pas ignoré
        self.assertEqual(self.base.ignorer_tous_les_manques(), 1)  # re-vidable

    def test_vider_la_file_avant_execution(self):
        planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=2, latence=0))
        premier = planif.programmer(self.rdv_un)
        second = planif.programmer(self.rdv_deux)
        self.assertEqual(planif.annuler_tout(), 2)
        self.assertEqual(planif.file, [])
        for appel_id in (premier, second):
            self.assertEqual(self.base.obtenir_appel(appel_id)["statut"], "annulé")
        self.assertEqual(planif.executer(), [])            # plus rien à passer
        self.assertEqual(planif.annuler_tout(), 0)         # file déjà vide


class TestSuppressionClient(unittest.TestCase):
    """Supprimer un client emporte ses rendez-vous ET leurs appels."""

    def test_suppression_en_cascade(self):
        base = db.Base(":memory:")
        self.addCleanup(base.fermer)
        vise = base.ajouter_client("Mme Partira Exemple", "+33 6 00 00 00 42")
        rdv_id = base.ajouter_rendezvous(vise, HIER, "Essai", statut="manqué")
        appel_id = base.creer_appel(rdv_id)
        temoin = base.ajouter_client("M. Restera Exemple", "+33 6 00 00 00 43")
        rdv_temoin = base.ajouter_rendezvous(temoin, DEMAIN, "Essai")
        self.assertEqual(base.supprimer_client(vise), 1)   # 1 rendez-vous emporté
        self.assertIsNone(base.obtenir_client(vise))
        self.assertIsNone(base.obtenir_rendezvous(rdv_id))
        self.assertIsNone(base.obtenir_appel(appel_id))
        # Le voisin n'a rien perdu.
        self.assertIsNotNone(base.obtenir_client(temoin))
        self.assertIsNotNone(base.obtenir_rendezvous(rdv_temoin))

    def test_purge_de_la_file_du_planificateur(self):
        base = db.Base(":memory:")
        self.addCleanup(base.fermer)
        client_id = base.ajouter_client("Mme File Exemple", "+33 6 00 00 00 42")
        rdv_id = base.ajouter_rendezvous(client_id, HIER, "Essai", statut="manqué")
        planif = planificateur.Planificateur(
            base, calle_client.AppelSimule(graine=3, latence=0))
        planif.programmer(rdv_id)
        self.assertEqual(planif.purger_rendezvous(base.rendezvous_du_client(client_id)), 1)
        self.assertEqual(planif.file, [])


class TestThemesAppel(unittest.TestCase):
    """Les gabarits de mission par thème et leurs variables substituées."""

    def setUp(self):
        self.prefs = generation.Preferences()   # en mémoire

    def test_quatre_themes_et_gabarits_francais(self):
        # Quatre depuis le 03/08/2026 : « ⑤ Personnalisé » est parti avec la
        # nature du même nom. Son gabarit était vide — un thème qui ne dit
        # rien fait écrire le message deux fois.
        self.assertEqual(list(themes.THEMES),
                         ["manque", "confirmation", "deplacement",
                          "creneau_libere"])
        self.assertEqual(list(themes.GABARITS), list(themes.THEMES))
        for code in themes.THEMES:
            self.assertIn("Bonjour", themes.GABARITS[code])
            self.assertIn("[entreprise]", themes.GABARITS[code])
            # JAMAIS de numéro de téléphone dans un gabarit (convention).
            self.assertNotRegex(themes.GABARITS[code], r"\d{4}")
        # ⚠ Le libellé du premier thème ne parle plus d'un APPEL manqué mais
        # d'un RENDEZ-VOUS manqué : c'est ce qu'il fait, et l'ancien nom se
        # confondait avec une nature retirée qui, elle, parlait d'un appel.
        self.assertEqual(themes.THEMES["manque"],
                         "① Rappel d'un rendez-vous manqué")

    def test_variables_laissees_telles_quelles_sans_reglage(self):
        texte = themes.preremplir("manque", self.prefs)
        self.assertIn("[entreprise]", texte)              # pas réglé : visible
        self.assertIn("[créneaux_disponibles]", texte)
        self.assertIn("entre 9h00 et 19h00", texte)       # plage : défaut réel
        self.assertNotIn("[plage_rappel]", texte)

    def test_variables_substituees_depuis_les_reglages(self):
        self.prefs.definir(themes.CLE_ENTREPRISE, "Cabinet Essai Santé")
        self.prefs.definir(themes.CLE_CRENEAUX,
                           ["2026-08-01T14:00", "2026-08-02T09:30"])
        self.prefs.definir(themes.CLE_PLAGE_DEBUT, "08:30")
        self.prefs.definir(themes.CLE_PLAGE_FIN, "18:00")
        texte = themes.preremplir("deplacement", self.prefs,
                                  nom_client="Mme Cliente Exemple",
                                  date_rdv="2026-08-05T11:00")
        self.assertIn("Cabinet Essai Santé", texte)
        # ⚠ CE TEXTE EST DIT AU TÉLÉPHONE : les dates y sont en toutes
        # lettres depuis le 24/08/2026. « le 01/08/2026 à 14h00 » ne se
        # prononce pas — un agent vocal y lit des barres obliques.
        self.assertIn("le samedi 1 août 2026 à 14 heures, "
                      "le dimanche 2 août 2026 à 9 heures 30", texte)
        self.assertIn("entre 8h30 et 18h00", texte)
        self.assertIn("Mme Cliente Exemple", texte)
        self.assertIn("le mercredi 5 août 2026 à 11 heures", texte)
        for variable in ("[entreprise]", "[créneaux_disponibles]",
                         "[plage_rappel]", "[client]", "[date_rdv]"):
            self.assertNotIn(variable, texte)

    def test_finaliser_par_appel(self):
        texte = themes.finaliser("Bonjour [client], au sujet de [date_rdv].",
                                 "M. Untel Exemple", "2026-08-01T14:30")
        self.assertEqual(texte, "Bonjour M. Untel Exemple, au sujet de "
                                "le samedi 1 août 2026 à 14 heures 30.")

    def test_theme_inconnu_refuse(self):
        with self.assertRaises(ValueError):
            themes.preremplir("martien", self.prefs)

    def test_hors_plage_borne_et_message(self):
        jour = datetime.datetime(2026, 7, 27)
        dans = [jour.replace(hour=9, minute=0), jour.replace(hour=12),
                jour.replace(hour=19, minute=0)]
        for moment in dans:
            self.assertIsNone(themes.hors_plage(self.prefs, moment))
        message = themes.hors_plage(self.prefs, jour.replace(hour=20, minute=15))
        self.assertIn("20h15", message)
        self.assertIn("entre 9h00 et 19h00", message)
        self.assertIn("garde-fou de politesse", message)
        self.assertIsNotNone(themes.hors_plage(self.prefs,
                                               jour.replace(hour=8, minute=59)))

    def test_planificateur_substitue_client_et_date_par_appel(self):
        base = db.Base(":memory:")
        self.addCleanup(base.fermer)
        client_id = base.ajouter_client("Mme Mission Exemple", "+33 6 00 00 00 51")
        rdv_id = base.ajouter_rendezvous(client_id, HIER, "Essai", statut="manqué")
        planif = planificateur.Planificateur(
            base, calle_client.AppelSimule(graine=4, latence=0))
        appel_id = planif.programmer(rdv_id)
        planif.executer(mission="Bonjour [client], votre rendez-vous [date_rdv] "
                                "est à reprogrammer.")
        appel = base.obtenir_appel(appel_id)
        self.assertIn("Agent : Bonjour Mme Mission Exemple", appel["transcription"])
        self.assertNotIn("[client]", appel["transcription"])
        self.assertNotIn("[date_rdv]", appel["transcription"])
        self.assertNotIn("+33 6 00 00 00 51", appel["transcription"])  # jamais


class TestServeurClients(_TestAvecServeurWeb):
    """La page « Clients » : drapeau 🚫 partout, suppression confirmée."""

    def test_liste_masquee_et_bascule_ne_plus_appeler(self):
        statut, page = self._obtenir("/clients")
        self.assertEqual(statut, 200)
        self.assertIn("Contacts (4)", page)                 # la démo
        self.assertIn("Mme Nadia Lefèvre", page)
        self.assertIn("••", page)
        self.assertNotIn("+33 6 00 00 00 41", page)         # jamais en clair
        self.assertIn("Ne plus appeler", page)
        self.assertIn("Supprimer…", page)
        # Marquer Mme Nadia Lefèvre (client n°1 de la démo).
        _, page = self._poster("/clients/ne-plus-appeler",
                               {"client": 1, "valeur": 1})
        self.assertIn("🚫 ne plus appeler", page)           # badge sur la page
        self.assertIn("Appeler de nouveau", page)           # bascule inversée
        # Le badge est visible PARTOUT : page Rendez-vous comprise, sans bouton.
        # ⚠ SUR 🗂 TOUS LES RENDEZ-VOUS : le rendez-vous de Mme Nadia est
        # PASSÉ, donc absent de « à venir », et la liste des manqués de la page
        # 📅 Rendez-vous a été retirée le 10/08/2026. Le badge doit se voir
        # partout où la personne apparaît — c'est ce que cet essai garde.
        _, tous = self._obtenir("/tous")
        ligne_nadia = tous.split("Mme Nadia Lefèvre")[1].split("</tr>")[0]
        self.assertIn("🚫 ne plus appeler", ligne_nadia)
        self.assertNotIn("/rappel?", ligne_nadia)           # pas de bouton
        # Exclu de la mise en file groupée : 3 appels au lieu de 4.
        _, page_file = self._poster("/file/tout-rappeler")
        self.assertIn("3 appel(s) mis en file", page_file)
        # Exclu de la génération de liste de cascade.
        _, page_cascade = self._poster("/cascade/generer", {
            "liste": "", "mission": "Mission.", "creneau": "",
            "source": "tous", "ordre": "alphabetique"})
        self.assertIn("3 personne(s) dans la liste", page_cascade)
        zone = re.search(r"<textarea[^>]*name=\"liste\"[^>]*>([^<]*)</textarea>",
                         page_cascade).group(1)
        self.assertNotIn("Nadia", zone)
        # Le rappel individuel direct est refusé net (403).
        with self.assertRaises(urllib.error.HTTPError) as contexte:
            self._poster("/rappeler", {"rdv": 1})
        self.assertEqual(contexte.exception.code, 403)
        self.assertIn("Ne plus appeler",
                      contexte.exception.read().decode("utf-8"))
        # Réversible : on lève le drapeau, tout revient.
        _, page = self._poster("/clients/ne-plus-appeler",
                               {"client": 1, "valeur": 0})
        self.assertIn("peut de nouveau être appelé", page)
        _, page_file = self._poster("/file/tout-rappeler")
        self.assertIn("1 appel(s) mis en file", page_file)  # le manquant arrive

    def test_marquer_retire_aussi_de_la_file_en_attente(self):
        self._poster("/file/tout-rappeler")                 # 4 appels en file
        _, _ = self._poster("/clients/ne-plus-appeler", {"client": 1, "valeur": 1})
        _, page_file = self._obtenir("/file")
        self.assertIn("Appels en attente (3)", page_file)   # retiré de la file
        self.assertNotIn("Mme Nadia Lefèvre", page_file)

    def test_suppression_confirmee_jamais_en_un_clic(self):
        base = self.application.base
        avant_rdv = base.conn.execute("SELECT COUNT(*) FROM rendezvous").fetchone()[0]
        # 1. La page de confirmation ne supprime RIEN.
        statut, page = self._obtenir("/clients/supprimer?id=2")
        self.assertEqual(statut, 200)
        self.assertIn("Supprimer ce contact ?", page)
        self.assertIn("Action définitive", page)
        self.assertIn("M. Karim Osman", page)
        self.assertIn("Supprimer définitivement", page)
        self.assertIsNotNone(base.obtenir_client(2))        # toujours là
        # 2. Un POST SANS le champ de confirmation est refusé.
        with self.assertRaises(urllib.error.HTTPError) as contexte:
            self._poster("/clients/supprimer", {"client": 2})
        self.assertEqual(contexte.exception.code, 400)
        self.assertIsNotNone(base.obtenir_client(2))
        # 3. Le POST de la page de confirmation supprime client + rendez-vous.
        _, page = self._poster("/clients/supprimer",
                               {"client": 2, "confirmer": "oui"})
        self.assertIn("Client supprimé", page)
        self.assertIn("1 de ses", page)                     # 1 rendez-vous emporté
        self.assertIsNone(base.obtenir_client(2))
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM rendezvous").fetchone()[0], avant_rdv - 1)
        _, page = self._obtenir("/clients")
        self.assertIn("Contacts (3)", page)
        self.assertNotIn("Karim", page)

    def test_suppression_purge_la_file(self):
        self._poster("/file/tout-rappeler")
        _, _ = self._poster("/clients/supprimer", {"client": 3, "confirmer": "oui"})
        _, page_file = self._obtenir("/file")
        self.assertIn("Appels en attente (3)", page_file)
        self.assertNotIn("Élise", page_file)


class TestServeurViderLesListes(_TestAvecServeurWeb):
    """Les deux boutons « Vider » : liste À rappeler, et file d'appels."""

    def test_vider_a_rappeler_puis_retablir(self):
        """⚠ LE BOUTON N'EXISTE PLUS, NI SON MESSAGE (10/08/2026). Les deux
        vivaient dans « À rappeler (manqués) », retirée à la demande du
        propriétaire. Le geste, lui, marche encore : cet essai éprouve
        désormais son EFFET — quatre manqués passent « ignoré » — au lieu
        d'une phrase de confirmation qui ne s'affiche plus nulle part. Il
        attend un nouvel endroit, et ce commentaire est là pour qu'on ne
        l'oublie pas.
        """
        base = self.application.base
        avant = len([r for r in base.tous_les_rendezvous()
                     if r["statut"] == "manqué"])
        self.assertEqual(avant, 4)
        self._poster("/ignorer-tout")
        self.assertEqual([r for r in base.tous_les_rendezvous()
                          if r["statut"] == "manqué"], [])
        # « Tous les rendez-vous » les montre « ignoré », gris, réversibles.
        _, tous = self._obtenir("/tous")
        self.assertIn("st-ignore", tous)
        self.assertIn("Remettre à rappeler", tous)
        # On rétablit le rendez-vous n°1 : il redevient manqué.
        _, tous = self._poster("/retablir", {"rdv": 1})
        self.assertIn("Rendez-vous rétabli", tous)
        self.assertEqual(len([r for r in base.tous_les_rendezvous()
                              if r["statut"] == "manqué"]), 1)
        # Revider : un seul cette fois.
        self._poster("/ignorer-tout")
        self.assertEqual([r for r in base.tous_les_rendezvous()
                          if r["statut"] == "manqué"], [])

    def test_vider_la_file_d_appels(self):
        _, page = self._poster("/file/tout-rappeler")
        self.assertIn("Appels en attente (4)", page)
        self.assertIn("Vider la file", page)
        _, page = self._poster("/file/annuler-tout")        # 303 suivi -> /file
        self.assertIn("File vidée : 4 appel(s) annulé(s)", page)
        self.assertIn("La file est vide", page)
        # Les appels sont bien « annulé » en base (réversible en re-remplissant).
        base = self.application.base
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM appels WHERE statut = 'annulé'").fetchone()[0], 4)
        # Vider une file vide : message honnête, pas d'erreur.
        _, page = self._poster("/file/annuler-tout")
        self.assertIn("La file était déjà vide", page)


class TestServeurThemesAppel(_TestAvecServeurWeb):
    """Le sélecteur « Thème de l'appel » : rappel individuel, file, cascade."""

    def test_page_preparation_rappel_individuel(self):
        statut, page = self._obtenir("/rappel?rdv=1")
        self.assertEqual(statut, 200)
        self.assertIn("Préparer le rappel", page)
        self.assertIn("Thème de l'appel", page)
        for libelle in ("① Rappel d&#x27;un rendez-vous manqué",
                        "② Confirmation de rendez-vous",
                        "③ Déplacement de rendez-vous",
                        "④ Créneau libéré (cascade)"):
            self.assertIn(libelle, page)
        # ⑤ « Personnalisé » a été retiré le 03/08/2026 : son gabarit était
        # vide, et la nature du même nom est partie. Un thème qui ne dit rien
        # faisait écrire le message deux fois.
        self.assertNotIn("Personnalisé", page)
        self.assertIn("modifiable", page)                  # la mission s'édite
        # Gabarit du thème ① pré-rempli, [client] et [date_rdv] déjà résolus.
        self.assertIn("Mme Nadia Lefèvre", page)
        self.assertNotIn("[client]", page.split("zone-mission")[1].split("</textarea>")[0])
        self.assertIn("••", page)
        self.assertNotIn("+33 6 00 00 00 41", page)        # jamais en clair
        # ⚠ PLUS RIEN N'Y POINTE depuis le 10/08/2026 : le lien vivait dans
        # « À rappeler (manqués) ». La page répond, et c'est tout ce que cet
        # essai peut encore prouver.
        _, accueil = self._obtenir("/suivi")
        self.assertNotIn('href="/rappel?rdv=', accueil)

    def test_rappel_avec_mission_personnalisee(self):
        _, fiche = self._poster("/rappeler", {
            "rdv": 1, "theme": "personnalise",
            "mission": "Bonjour [client], c'est au sujet de votre rendez-vous "
                       "[date_rdv] : rappelez-nous."})
        self.assertIn("Transcription", fiche)
        # La transcription montre la mission LUE, variables substituées.
        self.assertIn("Agent : Bonjour Mme Nadia Lefèvre", fiche)
        self.assertNotIn("[client]", fiche)
        self.assertNotIn("[date_rdv]", fiche)
        self.assertNotIn("+33 6 00 00 00 41", fiche)       # jamais le numéro

    def test_rappel_theme_seul_sans_mission(self):
        # Sans texte de mission, le serveur applique le gabarit du thème.
        _, fiche = self._poster("/rappeler", {"rdv": 1, "theme": "confirmation",
                                              "mission": ""})
        self.assertIn("Agent : Bonjour Mme Nadia Lefèvre, je vous appelle de la part de", fiche)
        self.assertIn("pour confirmer votre rendez-vous", fiche)

    def test_file_execution_avec_theme(self):
        _, page = self._poster("/file/tout-rappeler")
        self.assertIn("Thème de l'appel", page)        # sélecteur sur la file
        self.assertIn("zone-mission", page)
        self.assertIn("[client] et [date_rdv] sont remplacés", page)
        _, resultat = self._poster("/file/executer", {
            "theme": "manque",
            "mission": "Bonjour [client], nous vous avons manqué [date_rdv]."})
        self.assertIn("Exécution terminée", resultat)
        self.assertIn("Exécution terminée", resultat)
        self.assertIn("<strong>4</strong> appel(s) traité(s)", resultat)
        # Chaque fiche porte la mission substituée PAR client.
        _, fiche = self._obtenir("/rendezvous?id=2")
        self.assertIn("Agent : Bonjour M. Karim Osman, nous vous avons manqué",
                      fiche)
        self.assertNotIn("+33 6 00 00 00 42", fiche)

    def test_cascade_theme_pre_rempli_et_reglages(self):
        # Les réglages nourrissent le gabarit affiché sur la page cascade.
        self.application.preferences.definir(
            serveur.themes.CLE_ENTREPRISE, "Salon Essai Coiffure")
        _, page = self._obtenir("/cascade")
        self.assertIn("Thème de l'appel", page)
        zone = page.split("zone-mission")[1].split("</textarea>")[0]
        self.assertIn("Salon Essai Coiffure", zone)         # [entreprise] résolu
        self.assertIn("[créneau]", zone)                    # résolu au lancement
        self.assertIn("sel-theme", page)                    # le sélecteur est là


class TestServeurPlageHoraire(_TestAvecServeurWeb):
    """Hors de la plage d'appel autorisée, TOUT lancement est refusé."""

    def _fermer_la_plage(self):
        """Règle une plage d'une heure qui exclut sûrement « maintenant »."""
        if datetime.datetime.now().hour < 12:
            debut, fin = "22:00", "23:00"
        else:
            debut, fin = "01:00", "02:00"
        preferences = self.application.preferences
        preferences.definir(serveur.themes.CLE_PLAGE_DEBUT, debut)
        preferences.definir(serveur.themes.CLE_PLAGE_FIN, fin)

    def test_rappel_file_et_cascade_refuses_hors_plage(self):
        self._poster("/file/tout-rappeler")                # 4 appels en attente
        self._fermer_la_plage()
        base = self.application.base
        for chemin, donnees in (
                ("/rappeler", {"rdv": 1}),
                ("/file/executer", {}),
                ("/cascade/executer",
                 {"liste": "Mme Un Exemple;+33 6 00 00 00 51",
                  "mission": "Mission.", "creneau": DEMAIN})):
            with self.assertRaises(urllib.error.HTTPError) as contexte:
                self._poster(chemin, donnees)
            self.assertEqual(contexte.exception.code, 403)
            page = contexte.exception.read().decode("utf-8")
            self.assertIn("hors de la plage", page)          # message clair
            self.assertIn("garde-fou de politesse", page)
            self.assertIn("Réglages", page)
        # AUCUN appel n'est parti : la file est intacte, rien de terminé.
        self.assertEqual(len(self.application.planif.file), 4)
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM appels WHERE statut != 'en file'").fetchone()[0], 0)
        self.assertEqual(base.lister_cascades(), [])
        # La plage rouverte, le lancement passe de nouveau.
        preferences = self.application.preferences
        preferences.definir(serveur.themes.CLE_PLAGE_DEBUT, "00:00")
        preferences.definir(serveur.themes.CLE_PLAGE_FIN, "23:59")
        _, resultat = self._poster("/file/executer")
        self.assertIn("Exécution terminée", resultat)

    def test_les_quatre_autres_portes_ne_proposent_pas_de_forcer(self):
        """⚠ LE BOUTON N'EXISTE QUE SUR LA CAMPAGNE. Ailleurs, le refus est
        celui d'avant, à la lettre : un geste individuel, une file, une
        cascade ne se forcent pas — la demande du propriétaire portait sur
        l'exécution d'une CAMPAGNE, et l'élargir sans qu'il l'ait demandé
        aurait ouvert trois portes de plus."""
        self._poster("/file/tout-rappeler")
        self._fermer_la_plage()
        for chemin, donnees in (
                ("/rappeler", {"rdv": 1, "forcer_horaire": "1"}),
                ("/file/executer", {"forcer_horaire": "1"}),
                ("/cascade/executer",
                 {"liste": "Mme Un Exemple;+33 6 00 00 00 51",
                  "mission": "Mission.", "creneau": DEMAIN,
                  "forcer_horaire": "1"})):
            with self.assertRaises(urllib.error.HTTPError) as contexte:
                self._poster(chemin, donnees)
            self.assertEqual(contexte.exception.code, 403)
            page = contexte.exception.read().decode("utf-8")
            self.assertIn("hors de la plage", page)
            self.assertNotIn("Forcer la simulation", page)


class TestForcerLHeureEnSimulation(_TestAvecServeurWeb):
    """▶ Démarrer hors des heures permises : le bouton qui force, ou rien.

    Demande du propriétaire du 13/08/2026, mot pour mot : « lorsqu'il y a
    l'erreur qui nous indique qu'on est en dehors du créneau autorisé lors de
    l'exécution d'une campagne, il faut afficher un bouton pour forcer la
    simulation malgré l'heure (uniquement pour la version en simulation c'est
    très important) ».

    ⚠ « UNIQUEMENT POUR LA VERSION EN SIMULATION » est la moitié qui compte.
    En simulation, aucun téléphone ne sonne : le garde-fou de politesse ne
    protège personne et n'empêche que d'essayer. En appels réels il protège
    quelqu'un — il ne se force donc jamais, et pas seulement « parce que le
    bouton n'est pas affiché » : les essais ci-dessous envoient le champ à la
    main, sans passer par aucun écran.
    """

    def _fermer_la_plage(self):
        """Une plage d'une heure qui exclut sûrement « maintenant »."""
        if datetime.datetime.now().hour < 12:
            debut, fin = "22:00", "23:00"
        else:
            debut, fin = "01:00", "02:00"
        preferences = self.application.preferences
        preferences.definir(serveur.themes.CLE_PLAGE_DEBUT, debut)
        preferences.definir(serveur.themes.CLE_PLAGE_FIN, fin)

    def _campagne_prete(self, contacts="Mme Essai Une;+33 6 00 00 00 51"):
        _, page = self._poster("/assistant/nature", {"nature": "prise_rdv"})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "ordre": "liste",
            "info_entreprise": "Cabinet Essai",
            "info_origine": "vous avez demandé un rendez-vous",
            "info_creneaux_proposes": "lundi 10h",
            "mission": "Bonjour [identite], essai.", "mission_editee": "1"})
        self._poster("/assistant/importer",
                     {"b": b, "mode": "collage", "liste": contacts})
        self._poster("/assistant/liste", {"b": b, "action": "valider"})
        return self.application.base.lister_campagnes()[0]["id"]

    def _demarrer(self, campagne_id, forcer=False):
        donnees = {"campagne": campagne_id, "agenda_verifie": "1"}
        if forcer:
            donnees["forcer_horaire"] = "1"
        try:
            return self._poster("/campagne/demarrer", donnees)
        except urllib.error.HTTPError as erreur:
            return erreur.code, erreur.read().decode("utf-8")

    def test_le_refus_porte_le_bouton_et_ne_lance_rien(self):
        campagne_id = self._campagne_prete()
        self._fermer_la_plage()
        code, page = self._demarrer(campagne_id)
        self.assertEqual(code, 403)
        self.assertIn("hors de la plage", page)
        # Le bouton, en MOTS — et ce qu'il fait, dit avant de le cliquer.
        self.assertIn("Forcer la simulation malgré l'heure", page)
        self.assertIn("aucun téléphone ne sonnera", page)
        # Le geste refusé est rejoué À L'IDENTIQUE : rien n'est reconstruit.
        self.assertIn('name="campagne" value="%d"' % campagne_id, page)
        self.assertIn('name="agenda_verifie" value="1"', page)
        self.assertIn('name="forcer_horaire" value="1"', page)
        # Et RIEN n'est parti tant qu'on n'a pas cliqué.
        campagne = self.application.base.obtenir_campagne(campagne_id)
        self.assertEqual(campagne["statut"], "prête")
        self.assertEqual(
            [c["etat"] for c in
             self.application.base.contacts_de_campagne(campagne_id)],
            ["à appeler"])

    def test_forcer_lance_la_campagne_et_la_fiche_le_dit(self):
        campagne_id = self._campagne_prete(
            "Mme Essai Une;+33 6 00 00 00 51\nM. Essai Deux;+33 6 00 00 00 52")
        self._fermer_la_plage()
        code, page = self._demarrer(campagne_id, forcer=True)
        self.assertEqual(code, 200)
        self.assertIn("Campagne démarrée", page)
        self._attendre_statut(campagne_id, "terminée")
        # ⚠ LES DEUX CONTACTS, pas seulement le premier : le fil revérifie la
        # plage ENTRE CHAQUE appel. Sans la trace écrite sur la campagne, il
        # se serait mis en pause au second — et l'écran aurait menti.
        etats = [c["etat"] for c in
                 self.application.base.contacts_de_campagne(campagne_id)]
        self.assertNotIn("à appeler", etats)
        # La fiche DIT que l'heure a été forcée — cela ne se devine pas.
        _, fiche = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn("Heure forcée", fiche)
        self.assertIn("simulée", fiche)

    def test_reprendre_ne_redemande_pas_l_autorisation(self):
        """Le geste vaut pour la campagne, pas pour un clic : une pause suivie
        d'une reprise ne repose pas la même question."""
        campagne_id = self._campagne_prete()
        self._fermer_la_plage()
        self._demarrer(campagne_id, forcer=True)
        self._attendre_statut(campagne_id, "terminée")
        self.application.base.changer_statut_campagne(campagne_id, "en pause")
        code, page = self._demarrer(campagne_id)          # SANS forcer_horaire
        self.assertEqual(code, 200)
        self.assertNotIn("Erreur 403", page)
        self.assertIn("Campagne démarrée", page)

    def test_en_appels_reels_le_champ_est_ignore(self):
        """⚠ L'ESSAI QUI COMPTE VRAIMENT. On envoie « forcer_horaire=1 » à la
        main, sans écran : la décision ne tient pas à l'affichage d'un bouton
        mais au mode, vérifié à chaque couche."""
        campagne_id = self._campagne_prete()
        self._fermer_la_plage()
        self.application.mode_reel = True
        try:
            code, page = self._demarrer(campagne_id, forcer=True)
        finally:
            self.application.mode_reel = False
        self.assertEqual(code, 403)
        self.assertIn("hors de la plage", page)
        self.assertNotIn("Forcer la simulation", page)
        campagne = self.application.base.obtenir_campagne(campagne_id)
        self.assertEqual(campagne["statut"], "prête")

    def test_une_campagne_forcee_reprise_en_reel_retrouve_le_garde_fou(self):
        """⚠ LE DRAPEAU ÉCRIT EN BASE NE VAUT JAMAIS SEUL. Une campagne forcée
        en simulation, puis reprise en appels réels, retrouve le garde-fou
        intact — sans qu'aucun ménage n'ait eu à passer derrière."""
        campagne_id = self._campagne_prete()
        self._fermer_la_plage()
        self._demarrer(campagne_id, forcer=True)
        self._attendre_statut(campagne_id, "terminée")
        base = self.application.base
        configuration = assistant.configuration_campagne(
            base.obtenir_campagne(campagne_id))
        self.assertTrue(configuration[assistant.CLE_HORAIRE_FORCE])
        # Le MÊME drapeau, relu dans l'autre mode, ne vaut plus rien.
        self.assertTrue(assistant.heure_forcee(configuration, mode_reel=False))
        self.assertFalse(assistant.heure_forcee(configuration, mode_reel=True))
        base.changer_statut_campagne(campagne_id, "en pause")
        self.application.mode_reel = True
        try:
            code, page = self._demarrer(campagne_id)
        finally:
            self.application.mode_reel = False
        self.assertEqual(code, 403)
        self.assertIn("hors de la plage", page)
        self.assertEqual(base.obtenir_campagne(campagne_id)["statut"],
                         "en pause")

    def test_la_periode_interdite_ne_se_force_jamais(self):
        """Décision du propriétaire : elle vaut pour tout, sans dérogation.
        Le bouton ne paraît donc pas, et le champ envoyé à la main ne fait
        rien — proposer de forcer ce qui ne se lève pas serait un mensonge."""
        campagne_id = self._campagne_prete()
        # Une période interdite de deux heures qui entoure sûrement l'instant
        # (la fonction sait traverser minuit toute seule).
        maintenant = datetime.datetime.now()
        preferences = self.application.preferences
        preferences.definir(
            assistant.CLE_INTERDIT_DEBUT,
            (maintenant - datetime.timedelta(hours=1)).strftime("%H:%M"))
        preferences.definir(
            assistant.CLE_INTERDIT_FIN,
            (maintenant + datetime.timedelta(hours=1)).strftime("%H:%M"))
        code, page = self._demarrer(campagne_id, forcer=True)
        self.assertEqual(code, 403)
        self.assertNotIn("Forcer la simulation", page)
        self.assertEqual(
            self.application.base.obtenir_campagne(campagne_id)["statut"],
            "prête")


class TestServeurReglages(_TestAvecServeurWeb):
    """La page « ⚙ Réglages » : entreprise, créneaux, plage — persistants."""

    def test_enregistrer_et_relire(self):
        statut, page = self._obtenir("/reglages")
        self.assertEqual(statut, 200)
        self.assertIn("Réglages", page)
        self.assertIn("Nom de l'entreprise", page)
        # Le montage de test a ouvert la plage : ce sont CES valeurs réglées
        # qui s'affichent (le défaut 9h-19h est testé unitairement).
        self.assertIn('value="00:00"', page)
        self.assertIn('value="23:59"', page)
        _, page = self._poster("/reglages/enregistrer", {
            "entreprise": "Cabinet Essai Kiné",
            "plage_debut": "08:30", "plage_fin": "18:30"})
        self.assertIn("Réglages enregistrés", page)
        self.assertIn('value="Cabinet Essai Kiné"', page)
        self.assertIn('value="08:30"', page)
        self.assertIn("entre 8h30 et 18h30", page)
        preferences = self.application.preferences
        self.assertEqual(preferences.obtenir("entreprise"), "Cabinet Essai Kiné")

    def test_plage_incoherente_refusee(self):
        _, page = self._poster("/reglages/enregistrer", {
            "entreprise": "", "plage_debut": "19:00", "plage_fin": "09:00"})
        self.assertIn("doit précéder", page)
        _, page = self._poster("/reglages/enregistrer", {
            "entreprise": "", "plage_debut": "n'importe", "plage_fin": "18:00"})
        self.assertIn("illisible", page)

    def test_creneaux_ajout_retrait_et_gabarits(self):
        """Les créneaux saisis à la main : stockés, triés, repris en mission.

        ⚠ Ils ne s'affichent PLUS sur la page ⚙ Réglages : le propriétaire a
        fait retirer la sous-partie « Créneaux à proposer » le 03/08/2026 —
        ils se calculent désormais depuis l'agenda. On lit donc la LISTE
        elle-même, servie en fragment, plutôt qu'une page qui ne la montre
        plus. Le réglage et son effet sur les missions restent vérifiés.

        ⚠ DEUX DATES RELATIVES, PLUS DEUX DATES FIXES (17/08/2026). Elles
        étaient écrites « 2026-08-01 » et « 2026-08-02 » : à venir le jour où
        cet essai a été écrit, passées seize jours plus tard. Le produit a
        depuis appris à ne plus PROPOSER un créneau dont l'heure est révolue,
        et l'essai est tombé — en accusant le produit d'un défaut qui était
        dans son propre montage. Un essai qui dépend du calendrier finit
        toujours par mentir : c'est le troisième de cette famille.
        Le cas du créneau PASSÉ, lui, est éprouvé à part (voir
        `test_un_creneau_manuel_passe_nest_plus_propose_mais_reste_a_lecran`).
        """
        def liste():
            return self._obtenir("/reglages/creneaux")[1]

        demain = datetime.datetime.now() + datetime.timedelta(days=3)
        tot = demain.replace(hour=14, minute=0, second=0, microsecond=0)
        tard = (tot + datetime.timedelta(days=1)).replace(hour=9, minute=30)
        lu_tot, lu_tard = themes.date_lisible(tot.isoformat(
            timespec="minutes")), themes.date_lisible(tard.isoformat(
                timespec="minutes"))

        self._poster("/reglages/creneau-ajouter",
                     {"creneau": tard.isoformat(timespec="minutes")})
        self._poster("/reglages/creneau-ajouter",
                     {"creneau": tot.isoformat(timespec="minutes")})
        page = liste()
        self.assertIn(lu_tot, page)                        # trié : le plus tôt
        self.assertIn(lu_tard, page)
        self.assertLess(page.index(lu_tot), page.index(lu_tard))
        # Doublon ignoré sans casse.
        self._poster("/reglages/creneau-ajouter",
                     {"creneau": tot.isoformat(timespec="minutes")})
        self.assertEqual(liste().count(lu_tot), 1)
        # ⚠ LES CRÉNEAUX NOURRISSENT LES GABARITS, ET UN GABARIT SE DIT.
        # L'écran des réglages garde le format court (compact, alignable
        # d'une ligne à l'autre) ; le texte que l'agent lira prend le format
        # PARLÉ. Deux besoins, deux formats — et cet essai tient les deux.
        _, prep = self._obtenir("/rappel?rdv=1")
        self.assertIn(f"{date_parlee_de(tot.isoformat(timespec='minutes'))}, "
                      f"{date_parlee_de(tard.isoformat(timespec='minutes'))}",
                      prep)
        self.assertNotIn(f"{lu_tot}, {lu_tard}", prep)
        # Retrait.
        self._poster("/reglages/creneau-retirer",
                     {"creneau": tot.isoformat(timespec="minutes")})
        page = liste()
        self.assertNotIn(lu_tot, page)
        self.assertIn(lu_tard, page)
        # Créneau illisible refusé en français.
        _, page = self._poster("/reglages/creneau-ajouter", {"creneau": "bientôt"})
        self.assertIn("Date illisible", page)


class TestPlusieursPlacesDansUnAppel(unittest.TestCase):
    """Un même appel peut proposer plusieurs places (03/08/2026).

    La question du propriétaire : « est-ce que l'IA pourrait proposer
    plusieurs dates lors d'un même appel ? » Oui, et rien de neuf n'était
    nécessaire côté API : le briefing est du TEXTE LIBRE, et
    « new_datetime » est le seul canal par lequel une date revient.

    Deux choses manquaient, elles :
     · le contrôle de forme DÉCLARAIT ILLISIBLE une date sur « accepted » —
       un agent qui disait « elle prend la place du 5 » mettait la campagne
       en pause ;
     · RIEN ne vérifiait qu'une date rendue faisait partie de celles qu'on
       avait fait annoncer. Sans ce contrôle, une date inventée ou mal
       comprise au téléphone aurait été réservée telle quelle.
    """

    def _monter(self, nb_places, rendue=None, contacts=1, cascade=True):
        """Une campagne à `nb_places`, dont l'agent retient `rendue`.

        `rendue` : le rang (0, 1, 2…) de la place que la personne prend, ou
        une chaîne pour une date que personne n'a proposée, ou None pour
        l'ancien comportement (aucune date rendue).
        """
        base = db.Base(":memory:")
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        depart = (datetime.datetime.now() + datetime.timedelta(days=1)).replace(
            hour=9, minute=0, second=0, microsecond=0)
        places = [depart + datetime.timedelta(hours=2 * rang)
                  for rang in range(nb_places)]
        horaires_places = [p.isoformat(timespec="minutes") for p in places]
        lignes = []
        for rang in range(contacts):
            telephone = "+33 6 00 00 00 51"
            client = base.ajouter_client(f"Mme B{rang + 1}", telephone)
            rdv = base.ajouter_rendezvous(
                client, (depart + datetime.timedelta(days=20 + rang * 3))
                .isoformat(timespec="minutes"), "Bilan", statut="confirmé")
            lignes.append((f"Mme B{rang + 1}", telephone, rdv))
        brouillon = {
            "nature": "creneau_libere",
            "infos": {"creneau_libere": horaires_places[0],
                      "entreprise": "Cabinet Essai"},
            "infos_auto": {}, "politique": "premier_oui",
            "ordre": "eloignement",
            "options": {"liberer_creneau": True, "cascade": cascade},
            "champs": [dict(c)
                       for c in assistant.NATURES["creneau_libere"]["champs"]],
            "mission": "Bonjour, une place s'est libérée.",
            "mission_editee": False,
            "recette": {"apports": [{"quoi": "base"}], "a_la_main": False},
            "creneaux": assistant.normaliser_creneaux(horaires_places),
            "contacts": [
                {"nom": nom, "telephone": tel, "rendezvous_id": rdv,
                 "champs": {"rdv_existant":
                            base.obtenir_rendezvous(rdv)["horaire"],
                            "motif": "Bilan"}}
                for nom, tel, rdv in lignes]}
        campagne = assistant.creer_campagne_prete(base, brouillon, prefs)

        date_rendue = (horaires_places[rendue] if isinstance(rendue, int)
                       else rendue)

        recus = []

        class AgentQuiRetientUnePlace(calle_client.ClientAppels):
            """Il accepte, et il DIT laquelle des places a été retenue.

            ⚠ IL HÉRITE DE ClientAppels, comme tous les faux clients de ces
            essais. Le 11/08/2026, l'assistant a gagné deux pièces d'interface
            (le paramètre `nature` et recommencer_les_cas) et douze essais sont
            tombés d'un coup : le faux client refusait l'argument, la campagne
            attrapait l'erreur et se mettait en pause — donc l'essai racontait
            « le contact n'a pas bougé » là où la vraie cause était une
            signature. Hériter de l'interface fait porter ces ajouts par la
            classe de base une fois pour toutes.
            """

            class _Issue:
                def __init__(self, resultat):
                    self.resultat = resultat
                    self.transcription = ""
                    self.identifiant = "appel-essai-1"

                def __getattr__(self, nom):
                    return None

            def appeler_cascade(self, nom, telephone, mission, creneau,
                                consigne=None, nature=None):
                recus.append((creneau, consigne))
                return self._Issue({"outcome": "accepted",
                                    "new_datetime": date_rendue, "notes": ""})

            def appeler(self, nom, telephone, rendezvous, mission=None,
                        consigne=None, nature=None):
                return self._Issue({"appointment_status": "confirmed",
                                    "new_datetime": None, "notes": ""})

        agent = AgentQuiRetientUnePlace()

        class Appli:
            def __init__(self):
                self.base, self.preferences = base, prefs
                self.executions, self.mode_reel = {}, False
                self.planif = planificateur.Planificateur(
                    base, agent, preferences=prefs)

            def commande_execution(self, identifiant):
                return None

            def terminer_execution(self, identifiant):
                pass

        return base, campagne, Appli(), horaires_places, recus

    # ------------------------------------------------ ce qu'on fait annoncer
    def test_la_consigne_numerote_les_places_et_dicte_le_retour(self):
        base, campagne, appli, horaires_places, _ = self._monter(3)
        fiche = base.obtenir_campagne(campagne)
        configuration = assistant.configuration_campagne(fiche)
        contact = base.contacts_de_campagne(campagne)[0]
        finale = assistant.consigne_de_l_appel(
            base, appli.preferences, fiche, configuration, contact,
            fiche["mission"], en_cascade=True)
        annonce = [f for f in finale.faits if "Plusieurs places" in f]
        self.assertEqual(len(annonce), 1, "une seule ligne d'annonce")
        for rang in (1, 2, 3):
            self.assertIn(f"place {rang} —", annonce[0])
        # ⚠ SANS LA DICTÉE, L'AGENT N'A AUCUN MOYEN DE NOUS LE DIRE :
        # « new_datetime » est le seul canal par lequel une date revient.
        self.assertEqual(finale.issues["oui"]["date"], "obligatoire")
        self.assertIn("new_datetime", finale.texte())

    def test_la_place_numero_un_est_celle_que_l_ouverture_nomme(self):
        """⚠ ① ET ② DOIVENT S'ACCORDER. L'ouverture est dite MOT POUR MOT et
        nomme une seule date ; l'énumération des faits commence par elle.
        Deux ordres différents feraient ouvrir sur le 12 puis énumérer à
        partir du 14 — la personne entendrait deux versions du même appel.

        On vérifie sur ce que l'agent a REÇU, appel par appel, y compris
        après que le curseur a changé de place : c'est là que les deux
        pourraient se désaccorder sans qu'on le voie.
        """
        base, campagne, appli, horaires_places, recus = self._monter(
            3, rendue=0, contacts=3)
        assistant.executer_campagne(appli, campagne)
        self.assertTrue(recus, "aucun appel n'est parti")
        vus = 0
        for creneau, consigne_recue in recus:
            annonce = [f for f in consigne_recue.faits
                       if "Plusieurs places" in f]
            if not annonce:
                continue
            vus += 1
            premiere = re.search(r"place 1 — (.+?) ;", annonce[0])
            self.assertIsNotNone(premiere, annonce[0])
            self.assertEqual(premiere.group(1),
                             themes.date_parlee(creneau))
        self.assertGreater(vus, 1, "un seul appel a énuméré des places")

    def test_au_plus_trois_places_dans_un_appel(self):
        """Énumérer, faire choisir puis reformuler est plus dur que répéter :
        au 8e essai réel, à qui lui demandait de RÉPÉTER une date, l'agent a
        répondu qu'il préférait ne pas dire de bêtise et a raccroché."""
        base, campagne, _, horaires_places, _ = self._monter(5)
        fiche = base.obtenir_campagne(campagne)
        annoncees = assistant.places_annoncees(fiche)
        self.assertEqual(annoncees, horaires_places[:3])
        self.assertEqual(assistant.PLACES_ANNONCEES_MAX, 3)

    def test_une_seule_place_la_consigne_ne_change_pas(self):
        """⚠ LE CONTRAT DU PROPRIÉTAIRE : « le décalage en cascade reste tel
        quel pour les campagnes à un seul créneau »."""
        base, campagne, appli, _, _ = self._monter(1)
        fiche = base.obtenir_campagne(campagne)
        configuration = assistant.configuration_campagne(fiche)
        contact = base.contacts_de_campagne(campagne)[0]
        finale = assistant.consigne_de_l_appel(
            base, appli.preferences, fiche, configuration, contact,
            fiche["mission"], en_cascade=True)
        self.assertEqual([f for f in finale.faits if "Plusieurs places" in f],
                         [])
        self.assertNotEqual(finale.issues["oui"]["date"], "obligatoire")

    # ------------------------------------------------ ce qu'on écrit ensuite
    def test_la_place_retenue_est_celle_qui_est_reservee(self):
        """⚠ LE DÉFAUT QUE CET ESSAI INTERDIT : la branche écrivait le
        rendez-vous sur la place EN COURS quoi que l'agent ait rapporté. Elle
        aurait donc donné la première place à quelqu'un qui a dit oui pour
        la deuxième — un rendez-vous à une heure jamais convenue."""
        base, campagne, appli, horaires_places, _ = self._monter(
            3, rendue=1)
        assistant.executer_campagne(appli, campagne)
        confirmes = [r["horaire"] for r in base.tous_les_rendezvous()
                     if r["statut"] == "confirmé"
                     and r["horaire"] in horaires_places]
        self.assertEqual(confirmes, [horaires_places[1]])
        etats = {f["horaire"]: f["statut"]
                 for f in assistant.creneaux_de(base.obtenir_campagne(campagne))}
        self.assertEqual(etats[horaires_places[1]], assistant.CRENEAU_POURVU)
        self.assertEqual(etats[horaires_places[0]],
                         assistant.CRENEAU_A_POURVOIR)
        self.assertEqual(etats[horaires_places[2]],
                         assistant.CRENEAU_A_POURVOIR)

    def test_le_detail_et_le_cahier_racontent_la_place_retenue(self):
        """Ce qu'un opérateur relit ne doit pas nommer une AUTRE date que
        celle qui est en agenda."""
        base, campagne, appli, horaires_places, _ = self._monter(
            3, rendue=2)
        assistant.executer_campagne(appli, campagne)
        detail = base.contacts_de_campagne(campagne)[0]["detail"] or ""
        self.assertIn(assistant.date_courte(horaires_places[2]), detail)
        self.assertNotIn(assistant.date_courte(horaires_places[0]), detail)
        dates = [c["nouvelle_date"]
                 for c in base.changements_de_campagne(campagne)]
        self.assertIn(horaires_places[2], dates)
        self.assertNotIn(horaires_places[0], dates)

    def test_une_date_hors_des_places_annoncees_n_est_jamais_reservee(self):
        """⚠ LE GARDE-FOU QUI N'EXISTAIT NULLE PART. Une date inventée ou mal
        comprise au téléphone aurait été écrite en agenda telle quelle. On ne
        devine pas : rien n'est réservé.

        ⚠ L'ÉTAT A CHANGÉ LE 15/08/2026 : « refusé », plus « à rappeler par un
        humain ». Sur un créneau libéré il n'y a plus de rappel manuel — il
        l'avait fait retirer, et ce chemin-ci l'ignorait encore. Ce que l'essai
        garde intact, c'est ce qui compte vraiment : RIEN n'est écrit en
        agenda, et la date obtenue au téléphone reste lisible sur la fiche.
        """
        inventee = (datetime.datetime.now()
                    + datetime.timedelta(days=45)).replace(
                        hour=15, minute=0, second=0,
                        microsecond=0).isoformat(timespec="minutes")
        base, campagne, appli, horaires_places, _ = self._monter(
            3, rendue=inventee)
        assistant.executer_campagne(appli, campagne)
        # Rien en agenda, ni sur la date inventée, ni sur une place.
        poses = [r["horaire"] for r in base.tous_les_rendezvous()
                 if r["statut"] == "confirmé"]
        self.assertNotIn(inventee, poses)
        for place in horaires_places:
            self.assertNotIn(place, poses)
        # Aucune place n'a été consommée.
        statuts = {f["statut"]
                   for f in assistant.creneaux_de(base.obtenir_campagne(campagne))
                   if f["horaire"] in horaires_places}
        self.assertEqual(statuts, {assistant.CRENEAU_A_POURVOIR})
        # Et ce qui a été obtenu au téléphone n'est pas perdu.
        contact = base.contacts_de_campagne(campagne)[0]
        self.assertEqual(contact["etat"], "refusé")
        self.assertIn("AUCUNE", contact["detail"])
        self.assertIn(inventee, contact["detail"])

    def test_sans_date_rendue_c_est_la_place_en_cours(self):
        """L'ancien comportement, mot pour mot : un agent qui ne rend pas de
        date parle de la place qu'on lui a fait annoncer."""
        self.assertEqual(
            assistant.place_retenue({"new_datetime": None},
                                    ["2026-09-01T09:00"], "2026-09-01T09:00"),
            "2026-09-01T09:00")
        self.assertEqual(
            assistant.place_retenue({}, [], "2026-09-01T09:00"),
            "2026-09-01T09:00")
        self.assertIsNone(
            assistant.place_retenue({"new_datetime": "2026-09-30T09:00"},
                                    ["2026-09-01T09:00"], "2026-09-01T09:00"))

    # ------------------------------------------------ le contrôle de forme
    def test_accepted_a_le_droit_de_porter_la_place_retenue(self):
        """⚠ C'ÉTAIT LE VERROU. « new_datetime » devait être NUL partout sauf
        sur « moved » : un agent qui disait laquelle des places avait été
        prise était déclaré illisible, et la campagne se mettait en pause."""
        resultat = calle_client.valider_resultat_cascade(
            {"outcome": "accepted", "new_datetime": "2026-09-01T11:00",
             "notes": ""})
        self.assertEqual(resultat["new_datetime"], "2026-09-01T11:00")

    def test_une_date_illisible_reste_refusee(self):
        with self.assertRaises(calle_client.ResultatInvalide):
            calle_client.valider_resultat_cascade(
                {"outcome": "accepted", "new_datetime": "mardi prochain",
                 "notes": ""})

    def test_les_autres_issues_gardent_leur_date_vide(self):
        """On n'a ouvert QUE « accepted » : « refused » avec une date reste
        une réponse qu'on ne sait pas lire."""
        with self.assertRaises(calle_client.ResultatInvalide):
            calle_client.valider_resultat_cascade(
                {"outcome": "refused", "new_datetime": "2026-09-01T11:00",
                 "notes": ""})


class TestApercuAnnonceLesPlaces(_TestAvecServeurWeb):
    """« Ce qui est montré est ce qui part » — y compris l'annonce du lot 9.

    ⚠ L'INVARIANT TIENT PAR UN SEUL CODE. La consigne est fabriquée par
    `construire_consigne`, et l'aperçu de l'étape ② comme l'appel réel y
    passent. Poser la ligne un cran plus haut — dans `consigne_de_l_appel`,
    que seul l'appel réel emprunte — l'aurait rendue invisible : l'opérateur
    n'aurait pas vu que son appel énumère trois places.
    """

    def _brouillon_avec(self, places):
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        identifiant = re.search(r'name="b" value="(\d+)"', page).group(1)
        self._poster("/assistant/message", {
            "b": identifiant, "info_entreprise": "Cabinet Essai",
            "ordre": "eloignement", "info_creneau_libere": list(places)})
        return self._obtenir(f"/assistant/message?b={identifiant}")[1]

    def test_l_apercu_de_l_etape_2_annonce_les_places_numerotees(self):
        page = html.unescape(self._brouillon_avec(
            ["2026-08-13T10:00", "2026-08-14T11:00", "2026-08-17T09:00"]))
        self.assertIn("Plusieurs places sont libres", page)
        for rang in (1, 2, 3):
            self.assertIn(f"place {rang} —", page)
        self.assertIn("Une seule sera retenue", page)
        # ③ dicte le retour : sans lui, l'agent n'a aucun moyen de dire
        # laquelle a été prise.
        self.assertIn("la personne retient UNE des places proposées", page)

    def test_une_seule_place_l_apercu_ne_change_pas(self):
        page = html.unescape(self._brouillon_avec(["2026-08-13T10:00"]))
        self.assertNotIn("Plusieurs places sont libres", page)
        self.assertNotIn("Une seule sera retenue", page)

    def test_l_apercu_s_arrete_a_trois_comme_l_appel(self):
        """Montrer quatre places quand l'appel n'en dira que trois serait le
        mensonge exact que cet invariant existe pour empêcher."""
        page = html.unescape(self._brouillon_avec(
            ["2026-08-13T10:00", "2026-08-14T11:00", "2026-08-17T09:00",
             "2026-08-18T15:00"]))
        self.assertIn("place 3 —", page)
        self.assertNotIn("place 4 —", page)

    def test_le_genre_classique_ne_recoit_jamais_cette_dictee(self):
        """⚠ « accepted » a le droit de porter une date ; « confirmed », non.
        Dicter cela sur le genre classique demanderait à l'agent une réponse
        que le contrôle de la réponse rejetterait."""
        prefs = generation.Preferences()
        cadre = assistant.construire_consigne(
            "rappel_rdv", {"entreprise": "Cabinet Essai"}, prefs,
            places=["2026-08-13T10:00", "2026-08-14T11:00"])
        self.assertNotIn("Plusieurs places sont libres",
                         " ".join(cadre.faits))
        self.assertNotEqual(cadre.issues["oui"]["date"], "obligatoire")


class TestPlanningSurvolEtSelection(unittest.TestCase):
    """Le survol ne blanchit plus la ligne ; la sélection est celle des Réglages.

    ⚠ MESURÉ AU NAVIGATEUR avant d'écrire ces essais. Avec l'ancienne règle,
    survoler une ligne rendait ses huit cases « rgba(0, 0, 0, 0) » — le vert
    des places libres compris : la page apparaissait dessous, donc une bande
    blanche en thème clair. Après correction, chaque case garde sa couleur
    (#12161b fermée, #166534 libre) au repos comme sous le survol.
    """

    def test_le_survol_ne_rend_plus_les_cases_transparentes(self):
        """⚠ CLIQUET : « background: inherit » ne doit jamais revenir.

        Il paraît inoffensif — « n'y touche pas » — mais « inherit » prend le
        fond du <tr>, qui n'en a aucun : la case devient transparente. C'est
        exactement le défaut signalé, et la formulation est trop tentante pour
        qu'on la laisse sans garde-fou.
        """
        corps = _corps_de_regle(serveur.STYLE, "table.planning tr:hover td")
        self.assertIn("background: var(--fond)", corps)
        self.assertNotIn("inherit", corps)
        # Et la place libre garde SON vert : sans cette seconde règle, le
        # survol l'aurait repeinte du fond de la page.
        self.assertIn("background: var(--creneau-libre)",
                      _corps_de_regle(serveur.STYLE,
                                      "table.planning tr:hover td.libre"))

    def test_la_selection_est_peinte_comme_aux_reglages(self):
        """La MÊME déclaration que « td.tranche.en-cours » du calendrier des
        Réglages : un fond accent, sans liséré, sans distinguer l'état de la
        case. Mesuré identique aux deux endroits : rgb(77, 155, 239)."""
        reference = _corps_de_regle(serveur.STYLE,
                                    "table.calendrier td.tranche.en-cours")
        choisie = _corps_de_regle(serveur.STYLE, "table.planning td.choisie")
        self.assertIn("background: var(--accent)", reference)
        self.assertIn("background: var(--accent)", choisie)
        # ⚠ PLUS DE LISÉRÉ, et plus de « .libre » : une case fermée ou occupée
        # dans la même plage restait sur son fond — une sélection de dix cases
        # n'en montrait que six.
        self.assertNotIn("outline", choisie)
        self.assertNotIn("table.planning td.choisie.libre", serveur.STYLE)
        # Et le survol de ligne ne reprend pas le dessus sur une case choisie.
        self.assertIn("background: var(--accent)",
                      _corps_de_regle(serveur.STYLE,
                                      "table.planning tr:hover td.choisie"))


class TestMenuDePlageAncre(unittest.TestCase):
    """Le menu de plage se colle aux cases choisies (demande du 09/08/2026).

    ⚠ EXERCÉ AU NAVIGATEUR : geste de glissement dispatché sur la grille,
    puis mesure. Une plage courte à gauche → panneau posé à 8 px à DROITE de
    son bord. Une plage large → panneau basculé à GAUCHE, entièrement dans la
    fenêtre. Fond de la fenêtre modale : rgba(0, 0, 0, 0).
    """

    def test_la_fenetre_accepte_une_ancre_et_s_y_pose(self):
        script = _sans_espaces_superflus(serveur.SCRIPT_MODALE)
        self.assertIn("window.rbModale=function(url,ancre)", script)
        self.assertIn("function ancrer(ancre)", script)
        # Elle se pose en COORDONNÉES D'ÉCRAN, pas par une marge automatique.
        self.assertIn("panneau.style.position='fixed'", script)
        self.assertIn("panneau.style.left=gauche+'px'", script)
        self.assertIn("panneau.style.top=haut+'px'", script)

    def test_elle_reste_dans_la_fenetre(self):
        """Pas la place à droite : elle passe à gauche. Trop bas : elle
        remonte. Un panneau à moitié hors de l'écran serait pire que loin."""
        script = _sans_espaces_superflus(serveur.SCRIPT_MODALE)
        self.assertIn("gauche+largeur>window.innerWidth-MARGE_ANCRE", script)
        self.assertIn("gauche=ancre.left-MARGE_ANCRE-largeur", script)
        self.assertIn("haut+hauteur>window.innerHeight-MARGE_ANCRE", script)

    def test_le_fond_s_efface_pour_qu_on_voie_la_plage(self):
        self.assertIn("background: transparent",
                      _corps_de_regle(serveur.STYLE, "#fond-modale.fond-ancre"))
        script = _sans_espaces_superflus(serveur.SCRIPT_MODALE)
        self.assertIn("fond.classList.add('fond-ancre')", script)
        # Le fond RESTE dans la page : le clic à l'extérieur ferme toujours.
        self.assertIn("fond.classList.remove('fond-ancre')", script)

    def test_le_planning_mesure_sa_plage_et_emporte_son_surlignage(self):
        script = _sans_espaces_superflus(serveur.SCRIPT_PLANNING)
        # ⚠ MESURÉE, PAS CALCULÉE : la grille change de largeur avec la
        # fenêtre, et une position déduite du jour et de l'heure se
        # décalerait au premier redimensionnement.
        self.assertIn("function boiteChoisie()", script)
        self.assertIn("c.getBoundingClientRect()", script)
        self.assertIn("boiteChoisie());", script)
        # La fenêtre fermée emporte la sélection : un surlignage sans panneau
        # collé à lui ne veut plus rien dire.
        self.assertIn("window.rbApresFermeture=effacer;", script)
        self.assertIn("window.rbApresFermeture", _sans_espaces_superflus(
            serveur.SCRIPT_MODALE))


class TestLaPlaceProposeeEstUneVraiePlace(unittest.TestCase):
    """⚠ SA CAPTURE DU 16/08/2026 : trois contacts d'une campagne de
    déplacement, trois « Confirmé » au téléphone… et trois « 🙋 à rappeler par
    un humain », avec « Rendez-vous NON CRÉÉ : cette place est déjà prise, ou
    elle est hors des horaires d'ouverture ».

    LA CAUSE, mesurée : la place libre était bien CALCULÉE à l'instant de
    l'appel, sur l'agenda vrai — mais elle n'était pas TRANSMISE au simulateur.
    Faute de place, celui-ci appliquait sa formule de dernier recours :
    « rendez-vous + 7 jours, même heure ». Son rendez-vous du 22/08 à 10h00
    donnait 29/08 à 10h00 — une place occupée. Le premier appel positif qu'il
    venait de demander se retournait donc en échec au moment d'écrire.

    ⚠ ET C'EST LA MÊME FAMILLE DE DÉFAUT QUE TOUT CE CHANTIER : une valeur
    juste, calculée au bon endroit, qui n'arrive pas jusqu'à celui qui s'en
    sert. Le contrôle porte donc sur le RÉSULTAT — le rendez-vous a-t-il
    bougé ? — jamais sur l'issue rendue par l'agent.
    """

    def _campagne(self, combien=3):
        base = db.Base(":memory:")
        prefs = generation.Preferences()
        for jour in range(5):
            horaires.basculer_periode(prefs, jour, 9 * 60, 12 * 60 + 30,
                                      "ouvrir")
            horaires.basculer_periode(prefs, jour, 14 * 60, 18 * 60 + 30,
                                      "ouvrir")
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        jour = (datetime.datetime.now() + datetime.timedelta(days=6)).replace(
            hour=0, minute=0, second=0, microsecond=0)
        while jour.weekday() >= 5:            # jamais un week-end : fermé
            jour += datetime.timedelta(days=1)
        contacts = []
        occupant = base.ajouter_client("M. Déjà Là", "03 53 10 10 99")
        for rang in range(combien):
            depart = jour.replace(hour=10, minute=rang * 20)
            quand = depart.isoformat(timespec="minutes")
            client = base.ajouter_client(f"Mme Essai {rang:02d}",
                                         f"03 53 10 10 {60 + rang:02d}")
            base.ajouter_rendezvous(client, quand, "Séance", statut="prévu")
            # ⚠ LA PLACE QUE LA FORMULE VISERAIT EST OCCUPÉE, ET C'EST TOUT
            # L'ESSAI. Sans cela, « rendez-vous + 7 jours, même heure » tombe
            # par chance sur un trou : les contrôles passaient AUSSI sans le
            # correctif — ils ne prouvaient rien. C'est la situation réelle de
            # sa base, où l'agenda d'exemple remplit les semaines.
            formule = depart + datetime.timedelta(
                days=calle_client.RATTRAPAGE_JOURS)
            base.ajouter_rendezvous(occupant,
                                    formule.isoformat(timespec="minutes"),
                                    "Déjà pris", statut="confirmé")
            contacts.append({"nom": f"Mme Essai {rang:02d}",
                             "telephone": f"03 53 10 10 {60 + rang:02d}",
                             "champs": {"rdv_existant": quand,
                                        "motif": "Séance"}})

        class Appli:
            def __init__(self):
                self.base, self.preferences = base, prefs
                self.executions, self.mode_reel = {}, False
                self.planif = planificateur.Planificateur(
                    base, calle_client.AppelSimule(graine=1, latence=0),
                    preferences=prefs)

            def commande_execution(self, identifiant):
                return None

            def terminer_execution(self, identifiant):
                pass

        campagne = assistant.creer_campagne_prete(base, {
            "nature": "deplacement",
            "infos": {"entreprise": "Cabinet Essai",
                      "creneau_le_plus_proche":
                          horaires.creneau_le_plus_proche(base, prefs),
                      "creneaux_remplacement":
                          assistant.creneaux_annonces(base, prefs,
                                                      "deplacement")},
            # ⚠ LA POLITIQUE DE LA NATURE, PAS UNE FORCÉE À LA MAIN. L'essai
            # forçait « tous » : il n'aurait donc PAS vu la campagne s'arrêter
            # au premier oui — le défaut même qu'il a constaté à l'écran.
            "infos_auto": {},
            "politique": assistant.NATURES["deplacement"]["politique"],
            "ordre": "liste",
            "options": {}, "mode_liste": "manuel",
            "champs": [dict(c)
                       for c in assistant.NATURES["deplacement"]["champs"]],
            "mission": "",
            "recette": {"apports": [{"mode": "collage"}], "a_la_main": False,
                        "mission_editee": False},
            "creneaux": [], "contacts": contacts}, prefs)
        assistant.executer_campagne(Appli(), campagne)
        return base, campagne

    def test_un_deplacement_appelle_TOUT_LE_MONDE(self):
        """⚠ LA RÈGLE CORRIGÉE LE 16/08/2026, et c'est une règle ÉCRITE qui
        était fausse — §8.2 de CAS_DE_FIGURE_CAMPAGNES.md, « un déplacement
        accepté ARRÊTE la campagne », marquée « ma proposition, à confirmer ».
        Proposée par l'assistant, jamais confirmée, et construite dessus.

        Sa phrase la renverse en une ligne : « on sélectionne une après-midi et
        l'on dit : pour cette après-midi, on déplace les rendez-vous. C'est
        évident que l'on ne doit pas seulement déplacer la première personne
        qui accepte, mais TOUS les rendez-vous que nous avions sélectionnés. »

        D'où venait l'erreur : la confusion avec 📞 créneau libéré, où il n'y a
        qu'UN trou à combler. Ici il y a N rendez-vous à SORTIR d'une plage :
        chaque personne non appelée est un rendez-vous qui reste en place.

        Constaté à l'écran : 1 accepté, 2 « pas appelé ».
        """
        self.assertEqual(assistant.NATURES["deplacement"]["politique"],
                         "tous")
        # ⚠ ET L'ARRÊT AU PREMIER OUI RESTE OFFERT : c'est un réglage, pas le
        # défaut. Le retirer priverait du cas « une seule personne suffit ».
        self.assertTrue(
            assistant.NATURES["deplacement"]["politique_modifiable"])
        base, campagne = self._campagne()
        appelees = base.compter_personnes_appelees(campagne)
        self.assertEqual(appelees, 3, "les TROIS doivent être appelées")
        etats = [c["etat"] for c in base.contacts_de_campagne(campagne)]
        self.assertNotIn("épargné", etats, etats)
        self.assertNotIn("pas appelé", etats, etats)

    def test_personne_ne_part_a_rappeler_par_un_humain(self):
        """⚠ LE CŒUR, et c'est ce qu'il a vu à l'écran."""
        base, campagne = self._campagne()
        etats = [c["etat"] for c in base.contacts_de_campagne(campagne)]
        self.assertNotIn("à rappeler par un humain", etats,
                         [(c["nom"], c["etat"], c["detail"])
                          for c in base.contacts_de_campagne(campagne)])
        self.assertEqual(etats, ["accepté"] * 3, etats)

    def test_chaque_rendez_vous_a_VRAIMENT_bouge(self):
        """Une issue « confirmé » ne prouve rien : c'est l'AGENDA qui parle."""
        base, campagne = self._campagne()
        lignes = [ligne for ligne in base.changements_de_campagne(campagne)
                  if ligne["genre"] == "deplacement"]
        self.assertEqual(len(lignes), 3, lignes)
        for ligne in lignes:
            with self.subTest(qui=ligne["nom"]):
                self.assertTrue(ligne["ancienne_date"])
                self.assertTrue(ligne["nouvelle_date"])
                self.assertNotEqual(ligne["ancienne_date"],
                                    ligne["nouvelle_date"])

    def test_deux_contacts_ne_recoivent_jamais_la_meme_place(self):
        """⚠ LA PLACE PRISE QUITTE LES LIBRES DU SUIVANT. Elle est recalculée
        à CHAQUE appel : sans cela, trois personnes se verraient proposer la
        même heure, et les deux dernières seraient refusées."""
        base, campagne = self._campagne()
        posees = [ligne["nouvelle_date"]
                  for ligne in base.changements_de_campagne(campagne)
                  if ligne["genre"] == "deplacement"]
        self.assertEqual(len(set(posees)), len(posees), posees)

    def test_la_place_proposee_est_transmise_au_simulateur(self):
        """La cause exacte, contrôlée à sa source : le support d'appel porte
        une place RÉELLE, et une seconde pour « une autre date »."""
        support = assistant._support_de_l_appel(
            {"nature": "deplacement", "creneau": None},
            {"champs": json.dumps({"rdv_existant": "2026-08-24T10:00",
                                   "motif": "Séance"})},
            "deplacement", "2026-08-17T09:00", "2026-08-17T09:15")
        self.assertEqual(support["place_proposee"], "2026-08-17T09:00")
        self.assertEqual(support["place_alternative"], "2026-08-17T09:15")
        # ⚠ ET LA FORMULE DE DERNIER RECOURS NE SERT PLUS ICI : sans place
        # transmise, le simulateur ferait « rendez-vous + 7 jours ».
        self.assertNotEqual(support["place_proposee"], "2026-08-31T10:00")


class TestPremierAppelSimuleAboutit(unittest.TestCase):
    """⚠ SA DEMANDE DU 16/08/2026 : « spécifiquement pour les campagnes de
    déplacement de rendez-vous et de prise de rendez-vous, j'aimerais que le
    premier élément EN SIMULATION UNIQUEMENT soit positif (rendez-vous
    accepté) ».

    Le tour commence par les cas qui n'aboutissent PAS — c'est ce qui permet de
    tous les voir. Mais en montrant le produit, le premier appel donnait
    « annulé » : on découvrait la mécanique par un échec, et il fallait
    atteindre le cinquième appel pour voir un rendez-vous se poser. Ces deux
    natures-là POSENT une date : c'est leur but, et c'est ce que le premier
    appel doit montrer.
    """

    ABOUTIT = ("confirmed", "accepted")
    CONCERNEES = ("deplacement", "prise_rdv")
    AUTRES = ("creneau_libere", "rappel_rdv", "confirmation")

    def _plan(self, nature, contacts=6):
        simule = calle_client.AppelSimule()
        simule.recommencer_les_cas(nature, nombre_de_contacts=contacts)
        return [cas.split("|")[0] for cas in simule._plans[nature]]

    def test_le_premier_appel_pose_un_rendez_vous(self):
        for nature in self.CONCERNEES:
            with self.subTest(nature=nature):
                self.assertIn(self._plan(nature)[0], self.ABOUTIT)

    def test_les_autres_natures_ne_changent_pas(self):
        """⚠ « SPÉCIFIQUEMENT » VEUT DIRE CES DEUX-LÀ. Un créneau libéré doit
        continuer de montrer ses refus d'abord : sa place n'est pourvue qu'une
        fois, et l'ouvrir sur un oui masquerait tout le reste."""
        for nature in self.AUTRES:
            with self.subTest(nature=nature):
                self.assertNotIn(self._plan(nature)[0], self.ABOUTIT)

    def test_la_suite_porte_d_autres_succes_meles_aux_refus(self):
        """⚠ LA MOITIÉ « en intégrant également d'autres succès potentiels » de
        sa demande du 16/08/2026. L'AUTRE moitié — « dans un ordre aléatoire »
        — est gardée par `test_le_melange_reste_reproductible`, qui compare
        deux graines : c'est le seul contrôle qui tombe si le mélange
        disparaît.

        ⚠ ET CE NOM DIT CE QU'IL VÉRIFIE. Écrit d'abord
        « …_est_melange_et_porte_d_autres_succes », il passait AUSSI sans le
        mélange — les réussites de la queue « ensuite » suffisaient à le
        satisfaire. Un essai dont le nom promet plus que ce qu'il mesure est
        pire qu'un essai absent : on le croit.
        """
        for nature in self.CONCERNEES:
            with self.subTest(nature=nature):
                plan = self._plan(nature, contacts=20)
                self.assertIn(plan[0], self.ABOUTIT)
                suite = plan[1:]
                # D'AUTRES succès parmi la suite, et pas seulement à la fin.
                reussites = [rang for rang, cas in enumerate(suite)
                             if cas in self.ABOUTIT]
                self.assertTrue(reussites, suite)
                self.assertLess(min(reussites), len(suite) - 1, suite)
                # Et des cas qui n'aboutissent pas, mêlés à eux.
                self.assertTrue([cas for cas in suite
                                 if cas not in self.ABOUTIT], suite)

    def test_le_melange_reste_reproductible(self):
        """⚠ SANS CELA, LE RAPPORT DU BANC NE SERAIT PLUS COMPARABLE. Le
        hasard est SEMÉ : même graine, même ordre. C'est ce qui permet de dire
        « le rapport est identique à l'octet d'une exécution à l'autre »."""
        for nature in self.CONCERNEES:
            with self.subTest(nature=nature):
                def plan(graine):
                    simule = calle_client.AppelSimule(graine=graine)
                    simule.recommencer_les_cas(nature, nombre_de_contacts=20)
                    return list(simule._plans[nature])
                self.assertEqual(plan(1), plan(1))
                self.assertNotEqual(plan(1), plan(7))

    def test_les_autres_natures_gardent_leur_ordre_fixe(self):
        """⚠ ON NE MÉLANGE PAS UN CRÉNEAU LIBÉRÉ. Un oui y pourvoit la place et
        arrête la campagne : mêler les réussites masquerait tous les autres cas
        dès le premier appel — le défaut corrigé le 11/08."""
        for nature in self.AUTRES:
            with self.subTest(nature=nature):
                def plan(graine):
                    simule = calle_client.AppelSimule(graine=graine)
                    simule.recommencer_les_cas(nature, nombre_de_contacts=20)
                    return list(simule._plans[nature])
                self.assertEqual(plan(1), plan(7))

    def test_le_tour_continue_apres_le_premier(self):
        """Rien n'est perdu : les cas qui n'aboutissent pas suivent, et la
        campagne SUIVANTE reprend le tour là où celle-ci l'a laissé."""
        simule = calle_client.AppelSimule()
        simule.recommencer_les_cas("deplacement", nombre_de_contacts=6)
        premier = [c.split("|")[0] for c in simule._plans["deplacement"][:5]]
        simule.recommencer_les_cas("deplacement", nombre_de_contacts=6)
        second = [c.split("|")[0] for c in simule._plans["deplacement"][:5]]
        self.assertEqual(premier[0], second[0])       # toujours un oui
        self.assertNotEqual(premier[1:], second[1:])  # mais la suite avance

    def test_une_petite_campagne_garde_son_cas_concluant(self):
        """⚠ LE PREMIER IMPOSÉ COMPTE DANS LE BUDGET. Sans cela, une campagne
        de trois contacts préparait un plan de quatre : le cas concluant
        tombait hors liste, et la place n'était jamais pourvue."""
        for nature in self.CONCERNEES:
            with self.subTest(nature=nature):
                plan = self._plan(nature, contacts=3)[:3]
                self.assertTrue(
                    [cas for cas in plan if cas in self.ABOUTIT], plan)

    def test_le_client_REEL_ignore_tout_cela(self):
        """⚠ « EN SIMULATION UNIQUEMENT ». Le client réel reçoit la nature et
        n'en fait rien : aucun plan, aucune issue décidée d'avance. C'est le
        téléphone qui décide, et lui seul."""
        interface = calle_client.ClientAppels()
        self.assertIsNone(interface.recommencer_les_cas("deplacement", 6))
        self.assertFalse(hasattr(interface, "_plans"))
        # ⚠ ET SEUL LE SIMULATEUR SAIT PRÉPARER UN PLAN. On le vérifie sur
        # l'OBJET, pas en cherchant un nom dans du texte : `SUITES_PAR_NATURE`
        # est cité dans un commentaire d'assistant.py, et un contrôle qui lit
        # les sources tombait dessus — un commentaire ne prouve rien.
        self.assertTrue(hasattr(calle_client.AppelSimule(), "_plans"))
        for classe in (calle_client.ClientAppels,):
            with self.subTest(classe=classe.__name__):
                simule = calle_client.AppelSimule
                self.assertIsNot(classe.recommencer_les_cas,
                                 simule.recommencer_les_cas)


class TestDeplacementNegocie(unittest.TestCase):
    """⚠ SES DEUX DEMANDES DU 16/08/2026 sur « Déplacement de rendez-vous ».

    ① « choisir par défaut dans ordre de rappel "Ordre de la liste" » ;
    ② « choisir automatiquement des dates avec des créneaux libres le plus
      proche possible, puis compléter avec des dates tous les jours ouvrés +
      matin et après-midi, plusieurs de chaque », puis le déroulé de l'échange.

    CE QUI CLOCHAIT, mesuré : les créneaux pré-remplis étaient les SIX
    premières places libres — donc six fois le même lundi matin, à quinze
    minutes d'intervalle. L'agent n'avait rien à négocier : un « non » sur la
    première valait « non » sur les six.
    """

    def _prefs(self):
        prefs = generation.Preferences()
        # Lundi-vendredi, 9 h-12 h 30 et 14 h-18 h 30. Week-end fermé.
        for jour in range(5):
            horaires.basculer_periode(prefs, jour, 9 * 60, 12 * 60 + 30,
                                      "ouvrir")
            horaires.basculer_periode(prefs, jour, 14 * 60, 18 * 60 + 30,
                                      "ouvrir")
        return prefs

    LUNDI = datetime.datetime(2026, 8, 17, 8, 0)

    def test_l_ordre_par_defaut_est_celui_de_la_liste(self):
        prefs = self._prefs()
        _, _, ordre = assistant.comportement_regle("deplacement", prefs)
        self.assertEqual(ordre, "liste")

    def test_le_stock_couvre_plusieurs_jours_matin_ET_apres_midi(self):
        """⚠ LE CŒUR. Avant : un seul jour, une seule demi-journée."""
        base, prefs = db.Base(":memory:"), self._prefs()
        places = horaires.places_negociables(base, prefs, depuis=self.LUNDI)
        self.assertTrue(places)
        jours, demies = set(), set()
        for horaire in places:
            quand = datetime.datetime.fromisoformat(horaire)
            jours.add(quand.date())
            demies.add((quand.date(),
                        "matin" if quand.hour < 13 else "apres"))
        self.assertGreaterEqual(len(jours), 5, places)
        # Chaque jour retenu porte SES DEUX demi-journées.
        for jour in jours:
            with self.subTest(jour=jour):
                self.assertIn((jour, "matin"), demies)
                self.assertIn((jour, "apres"), demies)
        # ⚠ ET AUCUN WEEK-END : la semaine type est respectée, on n'invente
        # pas des places un samedi pour remplir le quota.
        for jour in jours:
            self.assertLess(jour.weekday(), 5, jour)

    def test_les_places_les_plus_proches_viennent_en_premier(self):
        """« le plus proche possible » : le début du stock, ce sont elles."""
        base, prefs = db.Base(":memory:"), self._prefs()
        places = horaires.places_negociables(base, prefs, depuis=self.LUNDI)
        toutes = [e["horaire"] for e in horaires.creneaux_proposables(
            base, prefs, depuis=self.LUNDI) if not e["occupe"]]
        self.assertEqual(places[:horaires.PROCHES_DABORD],
                         toutes[:horaires.PROCHES_DABORD])
        # Et la date nommée dans le message est bien la première de toutes.
        self.assertEqual(
            horaires.creneau_le_plus_proche(base, prefs, depuis=self.LUNDI),
            date_parlee_de(toutes[0]))

    def test_les_creneaux_DITS_suivent_la_langue(self):
        """⚠ CE N'EST PAS UN ÉCRAN : C'EST CE QUI SE DIT AU TÉLÉPHONE.

        Trouvé le 03/09/2026 sur l'écran /cascade, mais la portée est bien plus
        large : ces listes entrent dans la CONSIGNE — « créneaux disponibles à
        proposer », « créneaux de remplacement ». Une consigne anglaise
        annonçait donc ses dates en français, prononcées par une voix anglaise
        à un patient anglophone.

        ⚠ ET LA COUCHE DE TRADUCTION NE POUVAIT RIEN : elle traduit les PAGES,
        au moment de les rendre. Une consigne, elle, part chez CALL-E sans
        passer par une page. C'est pourquoi la langue doit descendre jusqu'ici,
        dans le calcul lui-même.
        """
        base = db.Base(":memory:")
        en_fr, en_en = self._prefs(), self._prefs()
        en_en.definir(langue.CLE_LANGUE, "en")
        jours = ("lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi",
                 "dimanche", "heures", "heure")
        for calcul in (horaires.creneaux_negociables,
                       horaires.creneaux_de_remplacement,
                       horaires.creneau_le_plus_proche):
            with self.subTest(calcul=calcul.__name__):
                francais = calcul(base, en_fr, depuis=self.LUNDI)
                anglais = calcul(base, en_en, depuis=self.LUNDI)
                self.assertTrue(francais)
                self.assertTrue(anglais)
                self.assertNotEqual(francais, anglais)
                # ⚠ ET L'ARTICLE CHANGE AVEC : on dit « on Monday 24 August »,
                # jamais « le Monday » ni « the Monday ».
                self.assertTrue(anglais.startswith("on "), anglais)
                self.assertFalse(francais.startswith("on "), francais)
                for mot in jours:
                    self.assertNotIn(mot, anglais.lower(), anglais)

        # `places_a_proposer` rend un couple : c'est son texte qui parle.
        texte, _ = horaires.places_a_proposer(base, en_en, depuis=self.LUNDI)
        self.assertTrue(texte.startswith("on "), texte)
        for mot in jours:
            self.assertNotIn(mot, texte.lower(), texte)

    def test_seul_le_deplacement_recoit_le_STOCK_varie(self):
        """⚠ TROIS CALCULS, ET IL NE FAUT PAS LES CONFONDRE (31/08/2026).

        Le déplacement NÉGOCIE : son stock vise des dizaines de places et
        s'étale sur des semaines. Le rappel et la confirmation CITENT quelques
        dates à voix haute quand la personne ne peut pas venir : elles sont
        étalées elles aussi — sa demande du 31/08 — mais bornées à sept jours
        et à une poignée. La prise de rendez-vous, elle, n'a pas bougé.
        """
        base, prefs = db.Base(":memory:"), self._prefs()
        varie = assistant.creneaux_annonces(base, prefs, "deplacement",
                                            depuis=self.LUNDI)
        remplacement = assistant.creneaux_annonces(base, prefs, "rappel_rdv",
                                                   depuis=self.LUNDI)
        simple = assistant.creneaux_annonces(base, prefs, "prise_rdv",
                                             depuis=self.LUNDI)
        self.assertEqual(simple, horaires.creneaux_lisibles(base, prefs,
                                                            depuis=self.LUNDI))
        self.assertEqual(remplacement,
                         horaires.creneaux_de_remplacement(base, prefs,
                                                           depuis=self.LUNDI))
        # ⚠ LE STOCK RESTE LE PLUS GROS : c'est ce qui distingue négocier de
        # citer. Trois calculs, trois tailles.
        self.assertGreater(varie.count(","), remplacement.count(","))
        self.assertNotEqual(varie, remplacement)
        self.assertNotEqual(remplacement, simple)

    def test_le_message_d_ouverture_ne_recite_plus_la_liste(self):
        """⚠ PERSONNE N'ÉCOUTE VINGT DATES. L'ouverture nomme UNE date ; le
        stock, lui, reste dans « ce que tu sais »."""
        gabarit = " ".join(
            segment if isinstance(segment, str) else segment["texte"]
            for segment in assistant.NATURES["deplacement"]["gabarit"])
        self.assertIn("[creneau_le_plus_proche]", gabarit)
        self.assertNotIn("[creneaux_remplacement]", gabarit)
        # ⚠ PAS D'ARTICLE DEVANT LA DATE : `date_lisible` porte déjà « le ».
        # Écrit « proposer le [créneau] », l'agent disait « proposer le le
        # 17/08/2026 ». Trouvé en LISANT la consigne produite, pas le gabarit.
        self.assertNotIn("le [creneau_le_plus_proche]", gabarit)

    def test_la_phrase_dite_au_telephone_ne_double_pas_l_article(self):
        """Le contrôle qui aurait dû exister d'emblée : on lit ce qui SORT."""
        prefs = self._prefs()
        dit = assistant.construire_mission(
            "deplacement",
            {"entreprise": "Cabinet Essai",
             "creneau_le_plus_proche": "le 17/08/2026 à 09h00",
             "creneaux_remplacement": "le 17/08/2026 à 09h00"},
            prefs, {})
        self.assertIn("proposer le 17/08/2026 à 09h00", dit)
        self.assertNotIn("le le ", dit)

    def test_la_conduite_deroule_les_sept_temps_puis_passe_la_main(self):
        """⚠ SA MÉCANIQUE, dans l'ordre — et la borne des TROIS refus.

        ⚠ SIX TEMPS DEPUIS LE 31/08/2026, cinq auparavant. Le temps ajouté est
        la REPRISE DU FILTRE : « à chaque refus, redemande quels jours, puis
        matin ou après-midi, puis propose une heure ». Sans elle, la conduite
        ne disait quoi faire QUE lorsque l'agent n'a aucune heure qui
        corresponde — et rien du cas le plus fréquent, où la personne refuse
        l'heure proposée. L'agent enchaînait alors les heures d'affilée.

        ⚠ CET ESSAI A FAIT SON TRAVAIL : c'est lui qui a signalé le passage de
        cinq à six. Le chiffre est ÉCRIT, pas déduit de la constante — un essai
        qui compte `len(_ENTONNOIR) + 2` ne peut pas échouer.
        """
        conduite = assistant.NATURES["deplacement"]["conduite"]
        # ⚠ SEPT TEMPS DEPUIS LE 04/09/2026, six auparavant. Le temps ajouté
        # est la DEMANDE DE LISTE : « avez-vous d'autres dates ? » n'est pas un
        # refus, donc l'entonnoir ne se déclenchait pas — et l'agent récitait
        # les dix créneaux, alors que le champ qui les porte s'appelle « stock,
        # NON RÉCITÉ ». Constaté sur un appel réel du propriétaire.
        self.assertEqual(len(conduite), 7)
        attendus = ("LA date la plus proche", "NE RÉCITE PAS la liste",
                    "JOURS de la semaine",
                    "MATIN ou l'APRÈS-MIDI", "propose alors UNE SEULE heure",
                    "REPRENDS LE FILTRE", "TROIS propositions refusées")
        for rang, marque in enumerate(attendus):
            with self.subTest(temps=rang + 1):
                self.assertIn(marque, conduite[rang])
        # Le dernier temps passe la main, et conclut sur AUTRE (donc « à
        # rappeler par un humain » — c'est une des deux natures qui l'ont).
        self.assertIn("va vous rappeler", conduite[-1])
        self.assertIn("AUTRE", conduite[-1])
        self.assertIn("deplacement", assistant.NATURES_RAPPEL_HUMAIN)
        # ⚠ ET LE MILIEU EST LE TRONC PARTAGÉ, pas une copie : c'est ce qui
        # empêche les trois natures de diverger à la première retouche.
        self.assertEqual(tuple(conduite[1:-1]), assistant._ENTONNOIR)

    def test_la_conduite_part_VRAIMENT_dans_la_consigne(self):
        """⚠ ÉCRITE N'EST PAS ENVOYÉE. Ce qui compte est ce que CALL-E reçoit :
        le bloc doit paraître dans le texte de la consigne, numéroté, et
        [entreprise] doit y être remplacé — sinon le client entend le mot
        « entreprise »."""
        prefs = self._prefs()
        cadre = assistant.construire_consigne(
            "deplacement", {"entreprise": "Cabinet Val Fleuri",
                            "creneau_le_plus_proche": "le 17/08/2026 à 09h00",
                            "creneaux_remplacement": "le 17/08/2026 à 09h00"},
            prefs)
        texte = cadre.texte_contexte()
        self.assertIn(consigne.TITRE_CONDUITE, texte)
        self.assertIn("1. commence par proposer LA date la plus proche",
                      texte)
        self.assertIn("6. ⚠ à chaque refus, REPRENDS LE FILTRE", texte)
        # ⚠ ET LA MARCHE AJOUTÉE LE 04/09 EST BIEN NUMÉROTÉE, elle aussi.
        self.assertIn("2. si elle demande ce que tu as d'autre", texte)
        self.assertIn("7. au bout de TROIS propositions refusées", texte)
        self.assertIn("une personne de Cabinet Val Fleuri va vous rappeler",
                      texte)
        self.assertNotIn("[entreprise]", texte)
        # ⚠ LA CONDUITE EST AVANT LES RÈGLES : c'est un déroulé, l'ordre EST
        # l'information. Sous les règles, elle se lirait comme un interdit.
        self.assertLess(texte.index(consigne.TITRE_CONDUITE),
                        texte.index(consigne.TITRE_CONTRAINTES))

    def test_une_nature_sans_conduite_n_affiche_aucun_bloc(self):
        """Le bloc disparaît quand il est vide — pas de titre orphelin.

        ⚠ « rappel_rdv » NE SERT PLUS D'EXEMPLE : elle a reçu sa conduite le
        31/08 (« ne cite aucune date tant qu'elle n'a pas répondu »). On prend
        celles qui n'en ont toujours pas — et on vérifie qu'il en reste, plutôt
        que de le supposer : le jour où toutes en auront une, cet essai le dira
        au lieu de passer au vert sur une liste vide.
        """
        sans = [nature for nature, fiche in assistant.NATURES.items()
                if not fiche.get("conduite")]
        self.assertTrue(sans, "toutes les natures ont une conduite")
        for nature in sans:
            with self.subTest(nature=nature):
                cadre = assistant.construire_consigne(
                    nature, {"entreprise": "Cabinet Essai"}, self._prefs())
                self.assertNotIn(consigne.TITRE_CONDUITE,
                                 cadre.texte_contexte())


class TestCinqDemandesDInterface(_TestAvecServeurWeb):
    """Les cinq demandes du 16/08/2026, chacune contrôlée sur l'ÉCRAN SERVI.

    Ce sont des demandes d'interface : ce qui compte est ce que la page
    contient vraiment, pas ce qu'une fonction rend. Chaque contrôle lit donc
    le HTML que le serveur envoie.
    """

    def _etape2(self, nature="creneau_libere"):
        """Ouvre l'étape 2 d'une campagne de cette nature ; rend (b, page)."""
        _, page = self._poster("/assistant/nature", {"nature": nature})
        b = re.search(r'name="b" value="(\d+)"', page).group(1)
        _, page = self._obtenir(f"/assistant/message?b={b}")
        return b, page

    # ------------------------------------------------ ① l'icône de chargement
    def test_l_import_d_un_fichier_dit_qu_il_travaille(self):
        """⚠ SA DEMANDE : « lorsqu'on importe un fichier, nous avons une icône
        de chargement ». Un agenda de mille rendez-vous prend plusieurs
        secondes : sans un mot, on reclique, et l'on importe deux fois."""
        _, page = self._obtenir("/ajouter")
        # ⚠ L'AFFECTATION, PAS LE MOT. Écrit « ⏳ Import en cours… », l'essai
        # passait sur le COMMENTAIRE qui cite la phrase — il restait vert le
        # code retiré. Un contrôle qui peut se satisfaire d'un commentaire ne
        # contrôle rien.
        self.assertIn("bouton.textContent='⏳ Import en cours…'", page)
        # Les trois formulaires de fichier du produit sont couverts.
        for action in ("/importer", "/importer-ics", "/installation/agenda"):
            with self.subTest(action=action):
                self.assertIn(f"'{action}'", page)
        # ⚠ LE VERROU APRÈS L'ENVOI : un bouton passé `disabled` PENDANT le
        # « submit » empêche certains navigateurs d'envoyer quoi que ce soit.
        # On aurait ajouté une icône en cassant l'import.
        self.assertIn("bouton.disabled=true;", page)
        self.assertIn("},0);});", page)

    def test_dans_la_fenetre_l_import_devient_un_chargement_verrouille(self):
        """⚠ SA DEMANDE DU 16/08/2026, mot pour mot : « remplace carrément la
        modale par un "chargement…" avec un spinner animé. Cette modale ne peut
        pas être fermée, elle l'est lorsque le chargement est finalisé. »

        Pourquoi le verrou : fermer la fenêtre ne stoppe RIEN — l'envoi est
        déjà parti — mais laisse croire que si. On reclique « Importer », et le
        fichier passe deux fois.
        """
        _, page = self._obtenir("/suivi")
        # La fenêtre est REMPLACÉE : plus de formulaire, donc plus rien à
        # cliquer une seconde fois.
        self.assertIn("fond.innerHTML='<div class=\"modale modale-chargement\"",
                      page)
        self.assertIn("<p class=\"titre-chargement\">Chargement…</p>", page)
        self.assertIn('<div class="rondelle" aria-hidden="true"></div>', page)
        # ⚠ LE MOT À CÔTÉ DE LA ROUE : une animation ne se lit pas, et pour qui
        # ne la voit pas, aria-busy dit la même chose.
        self.assertIn('aria-busy="true"', page)
        # Le verrou, et les trois voies de fermeture qui doivent y buter.
        self.assertIn("var verrouillee=false;", page)
        self.assertIn("function fermer(){if(verrouillee){return}", page)
        self.assertIn("verrouillee=true;", page)
        # ⚠ SEULEMENT DANS LA FENÊTRE : la page « Ajouter » n'en a pas, elle
        # garde son bouton qui change de libellé.
        self.assertIn("var dans_fenetre=!fond.hidden&&fond.contains(f);", page)
        self.assertIn("if(!dans_fenetre){return}", page)

    def test_la_roue_tourne_vraiment_et_se_tait_si_on_le_demande(self):
        """La règle d'animation existe, et elle est bornée par le réglage
        « moins d'animation » du système — la roue s'arrête, le mot reste."""
        _, page = self._obtenir("/suivi")
        self.assertIn("@keyframes rb-tourne { to { transform: rotate(360deg); } }",
                      page)
        self.assertIn("animation: rb-tourne .8s linear infinite;", page)
        reduit = page[page.index("@media (prefers-reduced-motion: reduce)"):]
        reduit = reduit[:reduit.index("}", reduit.index(".rondelle"))]
        self.assertIn("animation: none", reduit)

    # --------------------------------------- ③ la source dynamique par défaut
    def test_la_regle_dynamique_ne_propose_plus_les_rendez_vous_poses(self):
        """⚠ SA DEMANDE : supprimer « Rendez-vous posés — prévus ET
        confirmés » de l'étape 3 dynamique, et choisir « à venir, pas encore
        confirmés » par défaut."""
        b, _ = self._etape2()
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "ordre": "liste",
            "info_entreprise": "Cabinet Essai",
            "info_creneau_libere": "2026-09-20T09:00"})
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        panneau = page[page.index('name="regle_source"'):]
        panneau = panneau[:panneau.index("</select>")]
        self.assertNotIn('value="poses"', panneau)
        self.assertIn('value="a_venir"', panneau)
        # Et c'est elle qui est retenue d'office.
        self.assertIn('value="a_venir" selected', panneau)

    def test_la_source_posee_reste_offerte_au_chargement_manuel(self):
        """⚠ RETIRÉE DE LA RÈGLE, PAS DU PRODUIT. Reprendre une journée entière
        du planning garde tout son sens à la main — et les recettes déjà
        enregistrées doivent continuer de se rejouer."""
        self.assertIn("poses", assistant.SOURCES_DATEES)
        self.assertNotIn("poses", assistant.SOURCES_REGLE)
        self.assertIn("poses", assistant.SOURCES_RENDEZVOUS)

    # ------------------------------------------- ④ le menu horizontal B / C
    def test_le_mode_avance_range_B_et_C_dans_un_menu_horizontal(self):
        """⚠ SA DEMANDE : « le mode avancé fait apparaître un menu horizontal
        avec l'option B. Options de comportement et l'option C. Aperçu du
        message. Cliquer fait apparaître l'un ou l'autre des formulaires. »"""
        _, page = self._etape2()
        self.assertIn('class="menu-etape2" role="tablist"', page)
        for code, libelle in assistant_web.ONGLETS_ETAPE2:
            with self.subTest(onglet=code):
                # ⚠ CHAQUE ENTRÉE PORTE SON MOT ENTIER, jamais une lettre seule.
                self.assertIn(f'data-panneau="panneau-{code}"', page)
                self.assertIn(f">{libelle}</button>", page)
                self.assertIn(f'id="panneau-{code}"', page)
        # ⚠ DES BOUTONS « type=button » : sans cela, un clic sur un onglet
        # enverrait le formulaire de l'étape 2.
        onglets = re.findall(r'<button([^>]*class="onglet-etape2"[^>]*)>', page)
        self.assertEqual(len(onglets), len(assistant_web.ONGLETS_ETAPE2))
        for balise in onglets:
            self.assertIn('type="button"', balise)

    def test_sans_javascript_les_deux_panneaux_restent_lisibles(self):
        """⚠ LE REPLI EST « TOUT MONTRER ». Les panneaux sont masqués par le
        script, jamais par le HTML servi : sans JavaScript, on retrouve
        exactement l'écran d'avant, et aucun réglage n'est hors d'atteinte."""
        _, page = self._etape2()
        panneaux = re.findall(r'<div class="panneau-etape2"[^>]*>', page)
        self.assertEqual(len(panneaux), 2)
        for balise in panneaux:
            self.assertNotIn("hidden", balise)

    # --------------------------------------- ⑤ le sélecteur de période
    def test_la_cascade_offre_une_periode_qui_remplit_la_date(self):
        """⚠ SA DEMANDE : « au lieu d'avoir uniquement un sélecteur de date, on
        a également un sélecteur pour définir une période ce qui remplit
        automatiquement le champ date »."""
        _, page = self._etape2()
        self.assertIn('name="cascade_periode"', page)
        for valeur, libelle in assistant.PERIODES_CASCADE:
            with self.subTest(periode=libelle):
                self.assertIn(f'value="{valeur}"', page)
                # L'apostrophe est échappée dans la page : on compare ce que le
                # navigateur reçoit, pas ce que le code écrit.
                self.assertIn(f">{html.escape(libelle)}</option>", page)
        # Le champ date reste, et il porte la dernière date de l'agenda —
        # « dernière date » ne s'invente pas côté navigateur.
        self.assertIn('id="cascade_jusqu_au"', page)
        self.assertIn("data-derniere=", page)

    def test_la_derniere_date_vient_de_l_agenda_reel(self):
        """Elle est LUE en base, jamais calculée : au-delà du dernier
        rendez-vous connu, la chaîne ne trouverait plus personne."""
        base = self.application.base
        client = base.ajouter_client("M. Loin Devant", "+33 6 00 00 00 71")
        base.ajouter_rendezvous(client, "2027-03-04T10:00", "Bilan",
                                statut="prévu")
        self.assertEqual(base.dernier_rendezvous_connu(), "2027-03-04")
        _, page = self._etape2()
        self.assertIn('data-derniere="2027-03-04"', page)

    def test_un_rendez_vous_supprime_ne_sert_pas_de_derniere_date(self):
        """Il n'occupe plus rien : viser sa date ferait courir la chaîne vers
        un vide."""
        base = self.application.base
        vivant = base.ajouter_client("Mme Encore Là", "+33 6 00 00 00 72")
        base.ajouter_rendezvous(vivant, "2026-12-01T10:00", "Bilan",
                                statut="prévu")
        parti = base.ajouter_client("M. Plus Là", "+33 6 00 00 00 73")
        base.ajouter_rendezvous(parti, "2027-06-01T10:00", "Bilan",
                                statut="supprimé")
        self.assertEqual(base.dernier_rendezvous_connu(), "2026-12-01")


class TestEtape3AutomatiqueParDefaut(_TestAvecServeurWeb):
    """Étape ③ : automatique d'office, « Valider » remonté, ordre en règle.

    Les quatre autres demandes du 09/08/2026. Elles tiennent ensemble : un
    mode par défaut sans règle aurait laissé créer une campagne qui n'appelle
    personne, et un bouton « Valider » toujours visible n'aurait su que
    refuser.
    """

    def _etape3(self, nature="creneau_libere"):
        _, page = self._poster("/assistant/nature", {"nature": nature})
        b = re.search(r'name="b" value="(\d+)"', page).group(1)
        formulaire = {"b": b, "action": "continuer",
                      "info_entreprise": "Cabinet Essai", "ordre": "eloignement",
                      "relance_mode": "delai", "relance_delai": "4",
                      "relance_max": "3", "opt_recontacter": "1"}
        if nature == "creneau_libere":
            formulaire["info_creneau_libere"] = "2026-08-20T09:00"
        self._poster("/assistant/message", formulaire)
        return b

    def test_une_campagne_de_places_s_ouvre_en_automatique_avec_sa_regle(self):
        """⚠ LE DÉFAUT PORTE SA VALEUR. Un mode automatique sans règle aurait
        laissé créer une campagne sans personne à appeler."""
        b = self._etape3()
        brouillon = self.application.obtenir_brouillon_assistant(b)
        self.assertEqual(brouillon["mode_liste"], "automatique")
        # ⚠ « à venir » DEPUIS LE 15/08/2026 (sa demande) : c'était
        # « à recaser ». La nature qui se sert le plus de la règle est
        # « créneau libéré », et elle cherche des gens qui ONT un rendez-vous
        # plus tard, qu'on peut avancer — pas ceux qui n'en ont plus.
        self.assertEqual(assistant.regle_de_liste(brouillon),
                         {"source": "a_venir", "jours": ""})
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        self.assertIn('class="bascule-mode actif" name="action" '
                      'value="liste:automatique"', page)
        self.assertIn("La liste se refait à chaque place", page)

    def test_une_nature_sans_place_reste_manuelle(self):
        """Il n'y a rien sur quoi rejouer une règle : un mode automatique y
        serait un mensonge d'interface."""
        b = self._etape3("rappel_rdv")
        brouillon = self.application.obtenir_brouillon_assistant(b)
        self.assertEqual(brouillon["mode_liste"], "manuel")
        self.assertEqual(brouillon["regle_liste"], {})
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        self.assertNotIn("liste:automatique", page)

    def test_valider_est_dans_la_rangee_du_mode_et_envoie_la_grille(self):
        """⚠ IL RESTE LE BOUTON D'ENVOI DE LA GRILLE. Sorti du formulaire, il
        aurait perdu les cellules corrigées à la main."""
        b = self._etape3()
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        visible = _zone_visible(page)
        rangee = visible.split('class="rangee-bascule"', 1)[1].split("</div>", 1)[0]
        self.assertIn("Valider — créer la campagne", rangee)
        self.assertIn('form="form-grille"', rangee)
        self.assertIn('id="form-grille"', visible)
        # Poussé à droite, et pas comme un troisième choix de mode.
        self.assertIn("margin-left: auto", _corps_de_regle(
            serveur.STYLE, ".rangee-bascule .valider-campagne"))

    def test_en_manuel_il_n_apparait_qu_avec_quelqu_un_dans_la_grille(self):
        """Un bouton qui ne peut que refuser vaut moins qu'un bouton absent."""
        b = self._etape3()
        self._poster("/assistant/liste", {"b": b, "action": "liste:manuel"})
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        self.assertNotIn("Valider — créer la campagne", _zone_visible(page))
        self.application.base.ajouter_client("Mme Une", "+33 6 00 00 00 62")
        self._poster("/assistant/importer",
                     {"b": b, "mode": "clients", "etat_client": ""})
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        self.assertIn("Valider — créer la campagne", _zone_visible(page))

    def test_valider_en_automatique_joue_la_regle_des_la_creation(self):
        """⚠ ELLE N'ÉTAIT JOUÉE QU'AU CHANGEMENT DE PLACE. Une campagne
        automatique naissait donc VIDE, et le ▶ Démarrer n'appelait personne
        avant de se déclarer terminée. Supportable tant que l'automatique
        était un choix ; c'est devenu le mode par défaut."""
        base = self.application.base
        # ⚠ UN RENDEZ-VOUS « PRÉVU », APRÈS LA PLACE (15/08/2026). Il était
        # « annulé », pour la source « à recaser » qui était le défaut d'alors.
        # Le défaut est maintenant « à venir, pas encore confirmés » : ce que
        # l'essai doit prouver — la règle est jouée DÈS LA CRÉATION — n'a pas
        # changé, seule la personne qu'elle doit trouver a changé de statut.
        client = base.ajouter_client("Mme Prévue Neuf", "+33 6 00 00 00 64")
        base.ajouter_rendezvous(client, "2026-09-10T09:00", "Bilan",
                                statut="prévu")
        b = self._etape3()
        self._poster("/assistant/liste", {"b": b, "action": "valider"})
        campagnes = base.lister_campagnes()
        self.assertEqual(len(campagnes), 1)
        configuration = assistant.configuration_campagne(campagnes[0])
        self.assertEqual(configuration["regle_liste"]["source"], "a_venir")
        self.assertEqual(campagnes[0]["statut"], "prête")
        # La règle a trouvé la cliente dont le rendez-vous est APRÈS la place.
        noms = [c["nom"] for c in base.contacts_de_campagne(campagnes[0]["id"])]
        self.assertIn("Mme Prévue Neuf", noms)
        # Et AUCUN appel n'est parti : la campagne attend le ▶ Démarrer.
        self.assertEqual(
            [c["etat"] for c in base.contacts_de_campagne(campagnes[0]["id"])],
            ["à appeler"] * len(noms))

    def test_le_panneau_automatique_prend_toute_la_largeur(self):
        """⚠ « .carte » PLAFONNE À 28 REM — parfait pour un formulaire isolé,
        faux ici. Mesuré au navigateur : le panneau faisait 448 px là où la
        grille du mode manuel en fait 992. Basculer d'un mode à l'autre
        donnait l'impression de changer de page."""
        b = self._etape3()
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        visible = _zone_visible(page)
        self.assertIn('class="carte panneau-automatique"', visible)
        # Plus de plafond en style incorporé, et celui des cartes est levé.
        self.assertNotIn('panneau-automatique" style="max-width', visible)
        self.assertIn("max-width: none",
                      _corps_de_regle(serveur.STYLE, ".panneau-automatique"))
        # Les trois choix partagent la ligne au lieu de s'empiler.
        self.assertIn('class="rangee-regle"', visible)
        corps = _corps_de_regle(
            serveur.STYLE, ".panneau-automatique .rangee-regle .champ-option")
        self.assertIn("flex: 1 1 15rem", corps)
        # ⚠ Sans « min-width: 0 » un élément de flex refuse de descendre sous
        # la largeur de son contenu : le premier sélecteur, dont la plus
        # longue option fait une phrase, poussait les autres à la ligne
        # (mesuré : 625 px pour lui seul sur 992 disponibles).
        self.assertIn("min-width: 0", corps)

    def test_une_liste_vide_batie_par_une_regle_dit_pourquoi(self):
        """⚠ « Aucun contact » TOUT SEUL LAISSAIT CROIRE À UN OUBLI. La règle
        peut légitimement ne trouver personne pour la place en cours ; sans
        explication, le ▶ Démarrer se serait terminé sans un seul appel et
        l'opérateur aurait cherché son erreur de saisie."""
        base = self.application.base
        # ⚠ ON VIDE LA SOURCE COMME LA VRAIE VIE LE FERAIT : ces gens ont
        # repris rendez-vous, donc ils n'attendent plus (c'est le « NOT
        # EXISTS » qui définit « en attente »). Repasser leur ancien
        # rendez-vous en « confirmé » ne suffisait PAS : il est dans le passé,
        # et `marquer_manques_echus` — appelée avant chaque lecture — le
        # remettait aussitôt « manqué ». Le montage se battait contre une
        # règle du produit, et le produit avait raison.
        demain = (datetime.datetime.now() + datetime.timedelta(days=1)).replace(
            hour=15, minute=0, second=0, microsecond=0).isoformat(
                timespec="minutes")
        for rdv in base.rendezvous_a_recaser():
            base.ajouter_rendezvous(rdv["client_id"], demain, "Repris",
                                    statut="confirmé")
        self.assertEqual(base.rendezvous_a_recaser(), [])
        b = self._etape3()
        self._poster("/assistant/liste", {"b": b, "action": "valider"})
        campagne = base.lister_campagnes()[0]
        self.assertEqual(base.contacts_de_campagne(campagne["id"]), [])
        _, page = self._obtenir(f"/campagne?id={campagne['id']}")
        visible = _zone_visible(page)
        self.assertIn("Aucun contact dans cette campagne.", visible)
        self.assertIn("faite par une <strong>règle</strong>", visible)
        self.assertIn("n'a trouvé personne pour la place en cours", visible)
        self.assertIn("rejouée à chaque place", visible)
        # Et elle dit par où passer pour choisir soi-même.
        self.assertIn("<strong>Manuel</strong>", visible)

    def test_sans_regle_la_validation_est_refusee(self):
        b = self._etape3()
        brouillon = self.application.obtenir_brouillon_assistant(b)
        brouillon["regle_liste"] = {}
        _, page = self._poster("/assistant/liste", {"b": b, "action": "valider"})
        self.assertIn("Choisissez la règle qui fabrique la liste", page)
        self.assertEqual(self.application.base.lister_campagnes(), [])

    def test_le_panneau_automatique_porte_l_ordre_d_appel(self):
        """⚠ IL MANQUAIT : l'ordre ne se réglait que dans la grille, invisible
        en automatique. La campagne appelait dans l'ordre de l'étape ② sans
        qu'on puisse le lire ni le changer."""
        b = self._etape3()
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        panneau = page.split('class="carte panneau-automatique"', 1)[1]
        panneau = panneau.split("</div>", 1)[0]
        self.assertIn("Qui est appelé en premier", panneau)
        self.assertIn('name="ordre"', panneau)
        # Et il est LU : la règle enregistrée emporte l'ordre choisi.
        self._poster("/assistant/liste", {
            "b": b, "action": "regle", "regle_source": "a_recaser",
            "regle_jours": "30", "ordre": "anciennete"})
        brouillon = self.application.obtenir_brouillon_assistant(b)
        self.assertEqual(brouillon["ordre"], "anciennete")
        self.assertEqual(brouillon["regle_liste"]["jours"], "30")

    def test_un_seul_selecteur_d_ordre_a_la_fois(self):
        """⚠ DEUX AURAIENT ÉCRASÉ L'UN L'AUTRE. Celui de la grille part avec
        le formulaire de la grille — que « Valider » envoie aussi. Les deux
        ensemble, la vieille valeur de la grille écrasait en silence celle
        qu'on venait de choisir dans le panneau."""
        b = self._etape3()
        _, auto = self._obtenir(f"/assistant/liste?b={b}")
        self.assertEqual(auto.count('name="ordre"'), 1)
        self.assertNotIn("ordre-grille", auto)
        self._poster("/assistant/liste", {"b": b, "action": "liste:manuel"})
        _, manuel = self._obtenir(f"/assistant/liste?b={b}")
        self.assertEqual(manuel.count('name="ordre"'), 1)
        self.assertIn("ordre-grille", manuel)

    def test_des_contacts_tapes_en_manuel_restent_controles_en_automatique(self):
        """⚠ LE TROU QUE CET ESSAI FERME. Le mode automatique sortait de la
        validation AVANT le refus de doublon et l'exclusion des « ne plus
        appeler ». Or la grille n'est pas forcément vide : on tape des gens en
        manuel, on bascule, ils restent — c'est voulu, une saisie ne se perd
        jamais. Ils partaient alors sans aucun contrôle."""
        b = self._etape3()
        self._poster("/assistant/liste", {"b": b, "action": "liste:manuel"})
        brouillon = self.application.obtenir_brouillon_assistant(b)
        brouillon["contacts"] = [
            {"nom": "Mme Deux Fois", "telephone": "+33 6 00 00 00 63",
             "champs": {"rdv_existant": "2026-09-01T09:00", "motif": "Bilan"}},
            {"nom": "Mme Deux Fois bis", "telephone": "+33 6 00 00 00 63",
             "champs": {"rdv_existant": "2026-09-02T09:00", "motif": "Bilan"}}]
        self._poster("/assistant/liste", {"b": b, "action": "liste:automatique"})
        _, page = self._poster("/assistant/liste", {"b": b, "action": "valider"})
        self.assertIn("même numéro que la ligne", page)
        self.assertEqual(self.application.base.lister_campagnes(), [])


class TestRegleDeLInteret(unittest.TestCase):
    """« Une place n'intéresse quelqu'un que si elle lui apporte quelque chose »
    (décision du propriétaire, 09/08/2026).

    ⚠ ELLE REMPLACE UNE BORNE QUI COMPARAIT LA MAUVAISE DATE. La fenêtre
    partait de la place et écartait les rendez-vous antérieurs — juste pour
    quelqu'un qui A un rendez-vous (l'avancer d'une place plus tardive ne lui
    apporte rien), FAUX pour quelqu'un qui n'en a plus : sa dernière date est
    passée par construction, et elle ne dit rien de ce qu'il veut maintenant.

    Deux défauts mesurés, un seul principe :
     ① la source « annulés, manqués et en attente » ne retenait qu'UNE
       personne sur quatre qui attendent toutes une place ;
     ② une personne dont le rendez-vous est le 30/08 s'entendait proposer le
       04/09 — un retard.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(self.prefs, jour, 8 * 60, 19 * 60,
                                      "ouvrir")
        self.champs = [dict(c)
                       for c in assistant.NATURES["creneau_libere"]["champs"]]

    def _quand(self, jours, heure=9):
        return (datetime.datetime.now()
                + datetime.timedelta(days=jours)).replace(
                    hour=heure, minute=0, second=0,
                    microsecond=0).isoformat(timespec="minutes")

    def _client(self, nom, statut, quand, rang=0):
        client = self.base.ajouter_client(nom, f"+33 6 00 00 00 {70 + rang}")
        self.base.ajouter_rendezvous(client, quand, "Bilan", statut=statut)
        return client

    # ------------------------------------------------ ① ceux qui attendent
    def test_ceux_qui_attendent_sont_tous_retenus(self):
        """⚠ LE DÉFAUT MESURÉ : une personne retenue sur quatre. Quand on
        annule, sa date est PASSÉE — la borne les écartait donc tous, sauf
        celui dont l'annulation portait par hasard sur une date à venir."""
        attendus = [("Mme Annulée la semaine passée", "annulé", -7),
                    ("M. Manqué hier", "manqué", -1),
                    ("Mme Déplacée le mois dernier", "déplacé", -30),
                    ("Mme Annulée le mois prochain", "annulé", 30)]
        for rang, (nom, statut, jours) in enumerate(attendus):
            self._client(nom, statut, self._quand(jours), rang)
        place = self._quand(1)
        for jours in ("", "7", "30", "90"):
            with self.subTest(fenetre=jours):
                contacts, _ = assistant.contacts_de_la_regle(
                    self.base, self.prefs,
                    {"source": "a_recaser", "jours": jours}, self.champs, place)
                self.assertEqual(len(contacts), 4,
                                 [c["nom"] for c in contacts])
        # ⚠ ET « JUSQU'OÙ APRÈS LA PLACE » NE CHANGE RIEN pour cette source :
        # « à 30 jours après » n'a pas de sens pour une date qui la précède.
        # Un sélecteur qui changerait quelque chose sans qu'on sache quoi
        # serait pire qu'un sélecteur sans effet — l'écran le dit.
        self.assertEqual(assistant.SOURCES_A_VENIR, ("poses", "a_venir"))
        self.assertNotIn("a_recaser", assistant.SOURCES_A_VENIR)

    def test_la_borne_tient_pour_ceux_qui_ont_un_rendez_vous(self):
        """L'autre moitié de la règle : elle n'a PAS été jetée. Proposer une
        place plus tardive à quelqu'un qui a déjà un rendez-vous, c'est lui
        proposer un retard.

        ⚠ ET « JOURS » EST UN GAIN MINIMUM DEPUIS LE 11/08/2026 (décision du
        propriétaire) : « au moins 30 jours » retient ceux dont le rendez-vous
        est au moins 30 jours APRÈS la place — donc « Mme Très loin », pas
        « Mme Juste après ». C'est l'inverse d'avant, et c'est voulu : une place
        libérée sert à faire gagner du temps, pas à en faire gagner un peu.
        """
        self._client("M. Avant la place", "confirmé", self._quand(-3), 0)
        self._client("Mme Juste après", "confirmé", self._quand(5), 1)
        self._client("Mme Très loin", "confirmé", self._quand(80), 2)
        place = self._quand(1)
        gagnent_beaucoup, _ = assistant.contacts_de_la_regle(
            self.base, self.prefs, {"source": "poses", "jours": "30"},
            self.champs, place)
        self.assertEqual([c["nom"] for c in gagnent_beaucoup], ["Mme Très loin"])
        sans_minimum, _ = assistant.contacts_de_la_regle(
            self.base, self.prefs, {"source": "poses", "jours": ""},
            self.champs, place)
        self.assertEqual(sorted(c["nom"] for c in sans_minimum),
                         ["Mme Juste après", "Mme Très loin"])
        # ⚠ CELUI DONT LE RENDEZ-VOUS EST AVANT LA PLACE N'ENTRE JAMAIS : le
        # gain minimum ne remplace pas la règle de l'intérêt, il s'y ajoute.
        self.assertNotIn("M. Avant la place",
                         [c["nom"] for c in sans_minimum])

    # ------------------------------------------------ la règle elle-même
    def test_une_place_plus_tot_ou_plus_de_rendez_vous_du_tout(self):
        attend = self._client("Mme Attend", "annulé", self._quand(-10), 0)
        pourvu = self._client("M. Pourvu", "confirmé", self._quand(20), 1)
        places = [self._quand(5), self._quand(30)]
        # Plus rien en agenda : n'importe quelle place l'intéresse.
        self.assertTrue(assistant.place_utile_au_contact(
            self.base, {"client_id": attend}, places))
        # Un rendez-vous le 20 : la place du 5 l'intéresse, celle du 30 non.
        self.assertTrue(assistant.place_utile_au_contact(
            self.base, {"client_id": pourvu}, places))
        self.assertFalse(assistant.place_utile_au_contact(
            self.base, {"client_id": pourvu}, [places[1]]))
        # Aucune place : rien à proposer, donc rien d'utile.
        self.assertFalse(assistant.place_utile_au_contact(
            self.base, {"client_id": pourvu}, []))
        # ⚠ ON NE DEVINE PAS SUR UN CONTACT SANS FICHE : on l'appelle. Le
        # taire aurait fait disparaître quelqu'un sans raison affichée.
        self.assertTrue(assistant.place_utile_au_contact(
            self.base, {"client_id": None}, places))

    def test_un_rendez_vous_annule_ne_compte_pas_comme_a_venir(self):
        """⚠ UNE SEULE DÉFINITION D'« AVOIR ENCORE UN RENDEZ-VOUS ». Celle de
        `rendezvous_a_venir_du_client` (STATUTS_A_VENIR) est exactement celle
        du « NOT EXISTS » qui définit « en attente ». Deux définitions
        auraient fini par se contredire : l'une aurait recruté qui l'autre
        écartait."""
        self.assertEqual(db.Base.STATUTS_A_VENIR, ("prévu", "confirmé"))
        for rang, statut in enumerate(db.Base.STATUTS_A_RECASER):
            with self.subTest(statut=statut):
                client = self._client(f"Client {statut}", statut,
                                      self._quand(10), rang)
                self.assertEqual(
                    self.base.rendezvous_a_venir_du_client(client), [])
        for rang, statut in enumerate(db.Base.STATUTS_A_VENIR, start=5):
            with self.subTest(statut=statut):
                client = self._client(f"Client {statut}", statut,
                                      self._quand(10), rang)
                self.assertEqual(
                    [r["horaire"]
                     for r in self.base.rendezvous_a_venir_du_client(client)],
                    [self._quand(10)])
        # Un rendez-vous PASSÉ n'est pas « à venir ».
        vieux = self._client("M. Passé", "confirmé", self._quand(-2), 9)
        self.assertEqual(self.base.rendezvous_a_venir_du_client(vieux), [])

    def test_aucune_methode_de_la_base_n_est_definie_deux_fois(self):
        """⚠ UN NOM EN DOUBLE NE FAIT AUCUN BRUIT. La seconde définition
        remplace la première, et le code qui appelait l'ancienne reçoit
        silencieusement autre chose. C'est arrivé le 09/08/2026 : une méthode
        `rendezvous_a_venir_du_client` écrite une seconde fois, plus simple,
        a remplacé celle qui rendait une LISTE — quatre essais de cascade
        cassés, sur un « TypeError » qui ne disait pas d'où il venait."""
        noms = re.findall(r"^    def (\w+)\(", inspect.getsource(db.Base),
                          re.M)
        doubles = sorted({nom for nom in noms if noms.count(nom) > 1})
        self.assertEqual(doubles, [])


class TestPlaceSansInteretEpargneAuLieuDAppeler(unittest.TestCase):
    """② Le défaut mesuré : on proposait une place PLUS TARDIVE que son
    rendez-vous.

    Le curseur avance vers une place plus lointaine, et les gens recrutés pour
    la première restent dans la file. « M. Proche », rendez-vous le 30/08,
    s'entendait proposer le 04/09.
    """

    def _monter(self):
        base = db.Base(":memory:")
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        depart = (datetime.datetime.now()
                  + datetime.timedelta(days=1)).replace(
                      hour=9, minute=0, second=0, microsecond=0)

        def quand(jours):
            return (depart + datetime.timedelta(days=jours)).isoformat(
                timespec="minutes")

        # Une place TÔT, une place TARD. Deux personnes : la première a le
        # rendez-vous le plus lointain (elle passe d'abord, ordre par
        # éloignement), la seconde en a un plus proche que la place tardive.
        places = [quand(1), quand(39)]
        gens = [("Mme Loin", quand(24)), ("M. Proche", quand(19))]
        lignes = []
        for nom, rdv in gens:
            client = base.ajouter_client(nom, "+33 6 00 00 00 51")
            identifiant = base.ajouter_rendezvous(client, rdv, "Bilan",
                                                  statut="confirmé")
            lignes.append((nom, identifiant, rdv))
        brouillon = {
            "nature": "creneau_libere",
            "infos": {"creneau_libere": places[0],
                      "entreprise": "Cabinet Essai"},
            "infos_auto": {}, "politique": "premier_oui",
            "ordre": "eloignement",
            "options": {"liberer_creneau": True, "cascade": True},
            "champs": [dict(c)
                       for c in assistant.NATURES["creneau_libere"]["champs"]],
            "mission": "Bonjour, une place s'est libérée.",
            "mission_editee": False,
            "recette": {"apports": [{"quoi": "base"}], "a_la_main": False},
            "creneaux": assistant.normaliser_creneaux(places),
            "contacts": [{"nom": nom, "telephone": "+33 6 00 00 00 51",
                          "rendezvous_id": identifiant,
                          "champs": {"rdv_existant": rdv, "motif": "Bilan"}}
                         for nom, identifiant, rdv in lignes]}
        campagne = assistant.creer_campagne_prete(base, brouillon, prefs)
        appeles = []

        class Agent(calle_client.ClientAppels):
            class _Issue:
                def __init__(self, resultat):
                    self.resultat, self.transcription = resultat, ""
                    self.identifiant = "appel-essai"

                def __getattr__(self, nom):
                    return None

            def appeler_cascade(self, nom, telephone, mission, creneau,
                                consigne=None, nature=None):
                appeles.append((nom, creneau))
                return self._Issue({"outcome": "accepted",
                                    "new_datetime": None, "notes": ""})

            def appeler(self, *args, **mots):
                return self._Issue({"appointment_status": "confirmed",
                                    "new_datetime": None, "notes": ""})

        class Appli:
            def __init__(self):
                self.base, self.preferences = base, prefs
                self.executions, self.mode_reel = {}, False
                self.planif = planificateur.Planificateur(base, Agent(),
                                                          preferences=prefs)

            def commande_execution(self, identifiant):
                return None

            def terminer_execution(self, identifiant):
                pass

        return base, campagne, Appli(), appeles, dict(
            (nom, rdv) for nom, _, rdv in lignes)

    def test_personne_ne_s_entend_proposer_un_retard(self):
        """⚠ L'ESSAI CENTRAL. Il DOIT échouer si la règle disparaît : sans
        elle, « M. Proche » est appelé pour une place postérieure à son propre
        rendez-vous."""
        base, campagne, appli, appeles, rdv_par_nom = self._monter()
        assistant.executer_campagne(appli, campagne)
        self.assertTrue(appeles, "aucun appel n'est parti")
        for nom, place in appeles:
            with self.subTest(nom=nom):
                self.assertLess(place, rdv_par_nom[nom],
                                "on lui propose plus tard que son rendez-vous")
        self.assertNotIn("M. Proche", [nom for nom, _ in appeles])

    def test_il_est_epargne_avec_la_raison_en_clair(self):
        """⚠ PAS LAISSÉ « À APPELER » sur une campagne terminée : cela aurait
        laissé croire à un travail en suspens."""
        base, campagne, appli, _, _ = self._monter()
        assistant.executer_campagne(appli, campagne)
        etats = {c["nom"]: (c["etat"], c["detail"] or "")
                 for c in base.contacts_de_campagne(campagne)}
        self.assertEqual(etats["Mme Loin"][0], "accepté")
        self.assertEqual(etats["M. Proche"][0], "épargné")
        self.assertIn("l'avancer ne lui apporterait rien",
                      etats["M. Proche"][1])
        self.assertEqual(base.obtenir_campagne(campagne)["statut"], "terminée")

    def test_le_filtre_ne_marque_rien_tant_qu_il_reste_une_place_utile(self):
        """⚠ IL EST REJOUÉ À CHAQUE TOUR. Une place RENDUE par quelqu'un qui
        accepte peut être plus TÔT que la place en cours : marquer d'office
        aurait exclu pour de bon quelqu'un qu'elle intéresse."""
        source = inspect.getsource(assistant.executer_campagne)
        self.assertIn("def file_utile():", source)
        self.assertIn("file = file_utile()", source)
        # Le filtre ne change AUCUN état : il ne fait que retirer de la file.
        utile = source[source.index("def file_utile():"):
                       source.index("def epargner_le_reste(")]
        self.assertNotIn("changer_etat_contact_campagne", utile)
        # Et il ne s'applique QU'aux campagnes à liste.
        self.assertIn('if not configuration.get("liste_de_places"):', utile)


# ⚠ « TestAContacterALaMain » A ÉTÉ RETIRÉE le 10/08/2026 avec le tableau
# « ☎ À contacter à la main » de la page Rendez-vous (demande du propriétaire).
# Ce que ces six essais gardaient n'est pas perdu pour autant :
#  · les contacts qu'une campagne n'a pas pu conclure restent éprouvés sur
#    🔁 Relances (§ humains), qui les portait déjà — voir TestRappelHumain ;
#  · le drapeau 🔔 « rappel souhaité » est éprouvé là où il s'affiche.
# La requête db.rendezvous_avec_rappel_souhaite est partie avec eux : elle
# n'avait plus d'appelant.


class TestContactsPaginationEtRecherche(unittest.TestCase):
    """Page Contacts : pagination, filtre 🚫, recherche nom OU numéro.

    ⚠ SOIXANTE CONTACTS, PAS QUATRE. Le jeu de démonstration tient sur une
    page : une pagination éprouvée dessus n'aurait rien prouvé.
    """

    def setUp(self):
        self.dossier = tempfile.mkdtemp(prefix="ringback-pagination-")
        self.addCleanup(shutil.rmtree, self.dossier, ignore_errors=True)
        chemin = os.path.join(self.dossier, "essai.db")
        base = db.Base(chemin)
        for rang in range(60):
            base.ajouter_client(f"Mme Essai {rang:02d}",
                                f"+33 6 00 00 00 {rang:02d}")
        base.definir_ne_plus_appeler(3, True)
        base.definir_ne_plus_appeler(7, True)
        base.fermer()
        self.serveur = serveur.creer_serveur(port=0, chemin_base=chemin)
        self.racine = f"http://127.0.0.1:{self.serveur.server_address[1]}"
        threading.Thread(target=self.serveur.serve_forever,
                         daemon=True).start()
        self.addCleanup(self.serveur.server_close)
        self.addCleanup(self.serveur.shutdown)

    def _liste(self, **parametres):
        adresse = (self.racine + "/clients/liste?"
                   + urllib.parse.urlencode(parametres))
        with urllib.request.urlopen(adresse, timeout=10) as reponse:
            return reponse.read().decode("utf-8")

    @staticmethod
    def _combien(fragment):
        return len(re.findall(r'<tr id="client-\d+"', fragment))

    @staticmethod
    def _identifiants(fragment):
        return re.findall(r'<tr id="client-(\d+)"', fragment)

    # -------------------------------------------------------- pagination
    def test_le_nombre_par_page_est_respecte(self):
        for taille, attendu in ((10, 10), (25, 25), (100, 60), (0, 60)):
            with self.subTest(par_page=taille):
                self.assertEqual(self._combien(self._liste(par_page=taille)),
                                 attendu)
        # « tous » n'affiche aucune navigation : il n'y a qu'une page.
        self.assertNotIn("pagination", self._liste(par_page=0))
        self.assertIn("pagination", self._liste(par_page=10))

    def test_chaque_page_montre_d_autres_contacts(self):
        page1 = self._identifiants(self._liste(par_page=10, page=1))
        page2 = self._identifiants(self._liste(par_page=10, page=2))
        self.assertEqual(len(page1), 10)
        self.assertEqual(len(page2), 10)
        self.assertEqual(set(page1) & set(page2), set())

    def test_une_page_hors_limites_est_ramenee_dans_le_resultat(self):
        """⚠ SINON ON MONTRE UNE LISTE VIDE, et l'on croit que le filtre ne
        trouve personne. Le cas arrive tout seul : on est page 6, on tape une
        recherche, il ne reste qu'une page."""
        derniere = self._identifiants(self._liste(par_page=10, page=6))
        for demandee in (99, 7, 0, -3):
            with self.subTest(page=demandee):
                obtenue = self._liste(par_page=10, page=demandee)
                self.assertTrue(self._identifiants(obtenue))
                if demandee > 6:
                    self.assertEqual(self._identifiants(obtenue), derniere)

    def test_les_quatre_fleches_et_le_repere(self):
        page2 = self._liste(par_page=10, page=2)
        for signe in ("≪", "‹", "›", "≫"):
            self.assertIn(f">{signe}</button>", page2)
        self.assertIn("page <strong>2</strong> sur 6", page2)
        self.assertIn("10 contact(s) affiché(s) sur 60", page2)
        # ⚠ DÉSACTIVÉES AUX EXTRÉMITÉS, jamais masquées : un bouton qui
        # disparaît fait douter de l'endroit où l'on est. Deux par bloc de
        # navigation, et il y a un bloc au-dessus et un en dessous.
        self.assertEqual(self._liste(par_page=10, page=1).count("disabled"), 4)
        self.assertEqual(self._liste(par_page=10, page=6).count("disabled"), 4)
        self.assertEqual(page2.count("disabled"), 0)

    def test_la_navigation_encadre_le_tableau(self):
        """Sur cent lignes, remonter chercher « page suivante » est une corvée."""
        fragment = self._liste(par_page=10, page=2)
        self.assertEqual(fragment.count('class="pagination"'), 2)
        avant, _, apres = fragment.partition("<table")
        self.assertIn('class="pagination"', avant)
        self.assertIn('class="pagination"', apres)

    def test_la_navigation_est_centree(self):
        """Demande du propriétaire (10/08/2026). Le tableau prend toute la
        largeur : une barre collée à gauche paraissait décrochée de lui.

        ⚠ ON LIT LE CORPS DE LA RÈGLE, pas la présence du texte quelque part
        dans la feuille : c'est la seule façon de savoir que le centrage
        s'applique BIEN à cette barre-là (et les deux copies sortent du même
        HTML, donc les deux le sont).
        """
        corps = _corps_de_regle(serveur.STYLE, ".pagination")
        self.assertIn("justify-content: center", corps)
        # Et elle reste une ligne souple : le centrage ne remplace pas le
        # reste, il s'y ajoute.
        self.assertIn("display: flex", corps)
        self.assertIn("flex-wrap: wrap", corps)

    def test_les_fleches_marchent_sans_javascript(self):
        """⚠ ELLES SONT HORS DU FORMULAIRE DES FILTRES : « form= » les y
        rattache, sinon un clic sans JavaScript n'enverrait rien."""
        fragment = self._liste(par_page=10, page=2)
        self.assertIn('form="filtres-clients"', fragment)
        self.assertIn('name="page"', fragment)

    # ------------------------------------------------- filtre et recherche
    def test_le_filtre_ne_garde_que_les_contacts_interdits(self):
        fragment = self._liste(interdit="interdits", par_page=0)
        self.assertEqual(self._combien(fragment), 2)
        self.assertIn("contact par agent interdit", fragment)
        # Et « tous » ne filtre rien.
        self.assertEqual(self._combien(self._liste(interdit="", par_page=0)), 60)

    def test_la_recherche_trouve_par_le_nom_ou_par_le_numero(self):
        """⚠ « OU », PAS « ET » : on tape ce dont on se souvient."""
        for saisie in ("Essai 42", "0600000042", "600000042", "42",
                       "+33600000042"):
            with self.subTest(saisie=saisie):
                fragment = self._liste(recherche=saisie, par_page=0)
                self.assertEqual(self._combien(fragment), 1, saisie)
        self.assertIn("ne correspond", self._liste(recherche="zzzz"))

    def test_le_numero_en_clair_ne_sort_jamais_de_la_base(self):
        """⚠ LA COMPARAISON A LIEU DANS db.py. Les fiches d'affichage ne
        portent que le masque : une recherche ne doit pas être l'occasion de
        faire entrer le vrai numéro dans la couche qui rend l'écran."""
        fragment = self._liste(recherche="0600000042", par_page=0)
        self.assertIn("••", fragment)
        self.assertNotIn("+33 6 00 00 00 42", fragment)
        # ⚠ LA SAISIE EST RÉPÉTÉE, et c'est voulu : l'entête doit dire quel
        # filtre s'applique. Ce qui ne doit pas sortir, c'est le numéro RANGÉ
        # EN BASE — on le cherche donc dans le TABLEAU, pas dans l'entête.
        tableau = fragment[fragment.index("<table"):]
        self.assertNotIn("0600000042", tableau)
        self.assertNotIn("00 00 00 42", tableau.replace("•• •• •• 42", ""))
        # La fiche d'affichage n'a pas de champ « telephone » du tout.
        base = db.Base(os.path.join(self.dossier, "essai.db"))
        self.addCleanup(base.fermer)
        fiches = etats_clients.tableau_clients(base, generation.Preferences())
        self.assertNotIn("telephone", fiches[0]["client"])
        self.assertIn("telephone_masque", fiches[0]["client"])

    def test_deux_formes_du_meme_numero_donnent_le_meme_contact(self):
        """Le numéro rangé est réduit à ses chiffres significatifs : un
        « 0600000042 » tapé en entier ne s'y trouvait pas, alors qu'un « 42 »
        y était."""
        base = db.Base(os.path.join(self.dossier, "essai.db"))
        self.addCleanup(base.fermer)
        entier = base.clients_par_chiffres("0600000042")
        court = base.clients_par_chiffres("600000042")
        self.assertTrue(entier)
        self.assertEqual(entier, court)
        self.assertEqual(base.clients_par_chiffres(""), set())
        self.assertEqual(base.clients_par_chiffres("Lefèvre"), set())

    def test_filtre_et_pagination_se_combinent(self):
        """Le tableau subit les deux, dans cet ordre : on filtre, PUIS on
        découpe. L'inverse aurait paginé la liste entière et montré des pages
        vides."""
        fragment = self._liste(interdit="interdits", par_page=10)
        self.assertEqual(self._combien(fragment), 2)
        self.assertNotIn("pagination", fragment)      # deux, donc une page
        entete = self._liste(recherche="Essai 4", par_page=10)
        self.assertIn("contact(s) sur 60", entete)


class TestTroisCampagnesDepuisUnePlage(_TestAvecServeurWeb):
    """Une plage qui contient des rendez-vous ouvre déplacement, rappel et
    confirmation (demande du propriétaire, 10/08/2026).

    ⚠ LE DÉPLACEMENT N'ANNULE RIEN, et le propriétaire s'en méfiait à juste
    titre. La nature existante annonce que le rendez-vous ne peut pas être
    tenu, propose des créneaux, et si la personne accepte, le rendez-vous est
    DÉPLACÉ : il garde son histoire, le cahier porte une seule ligne ↔.
    Annuler d'avance aurait perdu l'historique et laissé des trous si personne
    ne répond.
    """

    def setUp(self):
        super().setUp()
        base = self.application.base
        # On vide le jeu de démonstration : cet essai compte des rendez-vous.
        for rdv in base.tous_les_rendezvous():
            base.mettre_a_jour_rendezvous(rdv["id"], statut="ignoré")
        self.demain = datetime.date.today() + datetime.timedelta(days=1)
        self.attendus = []
        gens = (("Mme Une", "+33 6 00 00 00 61", 9),
                ("M. Deux", "+33 6 00 00 00 62", 10),
                ("Mme Sans Numéro", "", 11),
                ("M. Doublon", "+33 6 00 00 00 61", 12))
        for nom, telephone, heure in gens:
            client = base.ajouter_client(nom, telephone)
            rdv = base.ajouter_rendezvous(
                client, datetime.datetime.combine(
                    self.demain, datetime.time(heure)).isoformat(
                        timespec="minutes"), "Bilan", statut="prévu")
            self.attendus.append(rdv)

    def _menu(self, heure1="09:00", heure2="12:00"):
        jour = self.demain.isoformat()
        zone = urllib.parse.quote(f"{jour}|{jour}|{heure1}|{heure2}")
        # `fenetre` : ces essais mesurent la FENÊTRE du glissé. La même adresse
        # rend une page entière quand la demande n'en vient pas — c'est le
        # repli sans souris, éprouvé par ses propres essais plus bas.
        return self._obtenir(f"/suivi/plage?zone={zone}", fenetre=True)[1]

    def test_la_plage_ne_prend_que_ce_que_le_planning_montre(self):
        """⚠ SON DÉFAUT DU 17/08/2026 : « il sélectionne plein de contacts au
        lieu de seulement ceux sélectionnés ».

        MESURÉ DANS SA BASE : un rectangle d'une journée montrait 13 rendez-vous
        à l'écran et en chargeait 89 dans la campagne — dont 76 « supprimé ».
        Ces fantômes viennent de ses réimports d'agenda : chaque import remplace
        le rendez-vous du même créneau et laisse l'ancien en « supprimé ». Le
        planning ne les affiche pas ; l'inventaire de la plage, lui, appelait
        `rendezvous_de_periode` SANS filtre de statut.

        L'essai reproduit la couche de fantômes : autant de rendez-vous cachés
        que de visibles, à la même heure. Ce que la plage annonce ET ce qu'elle
        emporte doivent rester le nombre VISIBLE.
        """
        base = self.application.base
        # Une couche de fantômes sur les mêmes créneaux que les quatre visibles.
        for rang, heure in enumerate((9, 10, 11, 12)):
            client = base.ajouter_client(f"M. Fantôme {rang}",
                                         f"+33 6 00 00 00 7{rang}")
            for statut in ("supprimé", "annulé", "déplacé"):
                base.ajouter_rendezvous(
                    client, datetime.datetime.combine(
                        self.demain, datetime.time(heure)).isoformat(
                            timespec="minutes"), "Fantôme", statut=statut)
        menu = self._menu()
        # ⚠ ON COMPTE LES IDENTIFIANTS DISTINCTS : la fenêtre porte TROIS
        # formulaires (déplacement, rappel, confirmation) qui emportent la même
        # liste. Compter les occurrences donnerait le triple — mon premier
        # comptage s'y est trompé et accusait le produit à tort.
        emportes = set(re.findall(r'name="rdv" value="(\d+)"', menu))
        self.assertEqual(len(emportes), len(self.attendus),
                         "la plage emporte des rendez-vous invisibles à l'écran")
        self.assertEqual(emportes, {str(rdv) for rdv in self.attendus})
        # Et le nombre ANNONCÉ dit la même chose que ce qui est emporté.
        self.assertIn(f"<strong>{len(self.attendus)} rendez-vous</strong>", menu)
        for nom in ("Fantôme",):
            self.assertNotIn(nom, menu)

    def test_les_trois_campagnes_sont_proposees(self):
        menu = self._menu()
        for titre in ("Campagne pour déplacer les rendez-vous",
                      "Campagne pour rappeler les rendez-vous",
                      "Campagne pour confirmer les rendez-vous"):
            self.assertIn(titre, menu)
        for nature in ("deplacement", "rappel-rdv", "confirmation"):
            self.assertIn(f'action="/suivi/plage/{nature}"', menu)

    def test_la_fenetre_va_droit_au_but(self):
        """⚠ RECADRÉ LE 10/08/2026, sur demande du propriétaire : « enlève les
        descriptifs que tu mets après chaque bouton […] trop d'information perd
        les utilisateurs ».

        Ce qui reste : le compte, puis quatre libellés. Ce que fait chaque
        campagne, l'assistant le montre à l'étape suivante, en contexte — et
        c'est là que ça se lit vraiment.
        """
        menu = self._menu()
        # Les explications d'avant ne sont plus là.
        for disparu in ("Rien n'est annulé", "il garde son histoire",
                        "Personne n'est appelé", "ouvrent l'assistant",
                        "places-plage"):
            with self.subTest(disparu=disparu):
                self.assertNotIn(disparu, menu)
        # Et plus aucune trace du « pas encore disponible » d'avant.
        self.assertNotIn("Pas encore disponible", menu)
        # Le compte, lui, RESTE : on ne propose pas une campagne sans dire
        # sur quoi elle porte.
        self.assertIn("4 rendez-vous", menu)
        # Quatre boutons, pas un de plus.
        self.assertEqual(menu.count("<button>"), 3)   # + le bouton Fermer
        self.assertEqual(menu.count("</form>"), 3)    # aucune place libre ici

    def test_chaque_bouton_ouvre_l_assistant_a_l_etape_2_sans_appeler(self):
        menu = self._menu()
        identifiants = sorted(set(re.findall(r'name="rdv" value="(\d+)"', menu)))
        self.assertEqual(len(identifiants), 4)
        for nature, attendue in (("deplacement", "deplacement"),
                                 ("rappel-rdv", "rappel_rdv"),
                                 ("confirmation", "confirmation")):
            with self.subTest(nature=nature):
                avant = len(self.application.base.lister_campagnes())
                _, page = self._poster(f"/suivi/plage/{nature}",
                                       {"rdv": identifiants})
                self.assertIn("2. Le message", page)
                # ⚠ AUCUNE CAMPAGNE CRÉÉE : on ouvre l'assistant, l'opérateur
                # décide. C'est la règle « rien ne part sans geste humain ».
                self.assertEqual(
                    len(self.application.base.lister_campagnes()), avant)
                b = re.search(r'name="b" value="(\d+)"', page).group(1)
                brouillon = self.application.obtenir_brouillon_assistant(b)
                self.assertEqual(brouillon["nature"], attendue)

    def test_les_contacts_arrivent_avec_leur_rendez_vous_et_leur_motif(self):
        menu = self._menu()
        identifiants = sorted(set(re.findall(r'name="rdv" value="(\d+)"', menu)))
        _, page = self._poster("/suivi/plage/rappel-rdv",
                               {"rdv": identifiants})
        b = re.search(r'name="b" value="(\d+)"', page).group(1)
        brouillon = self.application.obtenir_brouillon_assistant(b)
        noms = [c["nom"] for c in brouillon["contacts"]]
        # ⚠ « Mme Sans Numéro » EN FAIT PARTIE (18/08/2026) : elle entre dans la
        # grille avec sa case Téléphone vide, à compléter. L'écarter avant la
        # grille lui retirait le seul geste qui règle le problème.
        self.assertEqual(noms, ["Mme Une", "M. Deux", "Mme Sans Numéro"])
        self.assertEqual(
            [c["telephone"] for c in brouillon["contacts"]][-1], "")
        for contact in brouillon["contacts"]:
            with self.subTest(nom=contact["nom"]):
                self.assertTrue(contact["champs"]["rdv_existant"])
                self.assertEqual(contact["champs"]["motif"], "Bilan")
                self.assertTrue(contact["rendezvous_id"])

    def test_les_ecartes_sont_comptes_et_dits(self):
        """⚠ LES TAIRE AURAIT FAIT CROIRE À UNE LISTE COMPLÈTE. Un contact sans
        numéro ne peut pas être appelé ; deux fois le même numéro, ce sont deux
        appels chez la même personne."""
        menu = self._menu()
        identifiants = sorted(set(re.findall(r'name="rdv" value="(\d+)"', menu)))
        _, page = self._poster("/suivi/plage/confirmation",
                               {"rdv": identifiants})
        # Trois personnes reprises : les deux joignables ET celle dont le
        # numéro manque, qui vient le faire compléter dans la grille.
        self.assertIn("3 personne(s) reprise(s)", page)
        # ⚠ CHAQUE COMPTE DIT CE QU'IL COMPTE (14/08/2026, audit croisé). Les
        # sans-numéro se comptent par PERSONNE — une plage peut porter deux
        # rendez-vous de la même —, les doublons par RENDEZ-VOUS : ce sont les
        # lignes de la plage qui ne donnent pas un contact de plus.
        self.assertIn("1 numéro(s) à compléter dans la grille", page)
        self.assertIn("1 rendez-vous en doublon de numéro", page)

    def test_la_fenetre_dit_deja_qui_ne_sera_pas_appele(self):
        """⚠ SON DÉFAUT N° 7 DU 18/08/2026 : la fenêtre annonçait « 10 places
        libres et 13 rendez-vous » et se taisait sur les DEUX personnes
        qu'aucune campagne ne pourrait joindre.

        Il choisissait donc sa campagne sans le savoir, et ne l'apprenait qu'à
        l'écran suivant — « 2 personne(s) sans numéro écarté(s) » —, sans savoir
        LESQUELLES. Sur une journée de treize personnes, il fallait les chercher
        une à une. Et quand sa sélection ne couvrait QUE celles-là, il tombait
        sur le mur du défaut n° 1.

        La fenêtre le dit maintenant, AVANT les boutons, et elle NOMME les
        gens.
        """
        menu = self._menu()
        # Elle nomme la personne sans numéro, et dit QUOI FAIRE : le numéro se
        # tape dans la grille de l'étape 3, où elle figure désormais.
        self.assertIn("1 personne sans numéro", menu)
        self.assertIn("compléter dans la grille de l'étape 3", menu)
        self.assertIn("Mme Sans Numéro", menu)
        # Et le doublon de numéro, qui écarte lui aussi une ligne.
        self.assertIn("1 rendez-vous", menu)
        self.assertIn("numéro est déjà dans la liste", menu)
        # Le chemin pour corriger est là, pas seulement le constat.
        self.assertIn('href="/sans-numero"', menu)

        # ⚠ LE CŒUR : LA FENÊTRE ET L'ÉTAPE 2 COMPTENT PAREIL. C'est la règle
        # qu'on éprouve — deux écrans qui comptent chacun de leur côté
        # finissent par ne plus dire la même chose. Les deux comptes sortent
        # désormais du même tri (`_trier_les_rendezvous`).
        identifiants = sorted(set(re.findall(r'name="rdv" value="(\d+)"', menu)))
        _, page = self._poster("/suivi/plage/deplacement",
                               {"rdv": identifiants})
        self.assertIn("1 numéro(s) à compléter dans la grille", page)
        self.assertIn("1 rendez-vous en doublon de numéro", page)
        self.assertIn("3 personne(s) reprise(s)", page)

    def test_les_deux_ecrans_disent_qu_un_humain_rappellera(self):
        """⚠ LE TEXTE SUIT L'ÉTAT (20/08/2026), sur les DEUX écrans à la fois.

        « Elles ne seront pas appelées » était devenu à moitié faux : l'agent ne
        les appelle pas, mais elles ne disparaissent plus — elles attendent
        qu'un humain les rappelle. Le laisser tel quel lui aurait fait croire
        que ces personnes étaient perdues, alors qu'elles l'attendent dans
        🔁 Relances.

        ⚠ ET LES DEUX ÉCRANS ENSEMBLE, parce qu'il les traverse à la suite :
        deux formulations différentes pour le même fait lui feraient chercher
        laquelle est la bonne.
        """
        base = self.application.base
        vise = base.obtenir_rendezvous(self.attendus[0])
        base.definir_ne_plus_appeler(vise["client_id"], True)
        # ① LA FENÊTRE DE PLAGE.
        menu = self._menu()
        self.assertIn("1 personne marquée 🚫", menu)
        self.assertIn("l'agent ne l'appellera pas", menu)
        self.assertIn("rappel par un humain", menu)
        self.assertIn(vise["nom"], menu)
        # ② L'ÉTAPE ②, avec le MÊME fait dit de la même façon.
        identifiants = sorted(set(re.findall(r'name="rdv" value="(\d+)"', menu)))
        _, page = self._poster("/suivi/plage/deplacement",
                               {"rdv": identifiants})
        self.assertIn("1 personne(s) 🚫", page)
        self.assertIn("rappel par un humain", page)
        # ③ ET C'EST VRAI : la campagne créée la met bien dans cet état.
        b = self._etape2(self._brouillon(page))
        self._poster("/assistant/liste", self._grille(b))
        campagne_id = base.lister_campagnes()[0]["id"]
        contacts = {c["nom"]: c for c in base.contacts_de_campagne(campagne_id)}
        self.assertEqual(contacts[vise["nom"]]["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertTrue(db.refus_de_l_agent(contacts[vise["nom"]]["detail"]))

    def test_une_journee_entiere_se_choisit_d_un_seul_clic(self):
        """⚠ SON DÉFAUT N° 9 DU 18/08/2026 : le geste que le produit revendique
        — « vider une journée entière » — était IMPOSSIBLE d'un seul glissé.

        Mesuré sur une fenêtre de 1280 × 720 : la colonne d'un jour, de 08h00 à
        18h40, fait environ **830 pixels pour 720 visibles**, et le glissé ne
        fait pas défiler la page tout seul. Restaient deux échappatoires, dont
        aucune n'est évidente : Ctrl + glissé cumule des zones (mais Ctrl +
        molette agrandit la page dans le navigateur), et le repli « Sans
        glisser » demande de taper quatre valeurs.

        L'en-tête du jour était déjà là, et il désigne exactement la journée.
        """
        jour = self.demain.isoformat()
        _, page = self._obtenir(f"/suivi?date={jour}")
        liens = re.findall(r'<a class="jour-entier" href="([^"]+)"', page)
        vise = [lien for lien in liens if f"jour1={jour}" in lien]
        self.assertEqual(len(vise), 1, "aucun lien « toute la journée » pour ce jour")
        adresse = html.unescape(vise[0])
        # ⚠ IL EMPORTE LA SEMAINE REGARDÉE, pour le repli sans JavaScript : un
        # refus doit pouvoir y ramener (voir `_reponse_plage`).
        self.assertIn("annee=", adresse)
        self.assertIn("semaine=", adresse)

        # LE CŒUR : ce clic ramène EXACTEMENT ce que le glissé ramènerait.
        # Deux chemins vers la même plage qui ne diraient pas la même chose,
        # c'est le défaut suivant.
        _, par_le_clic = self._obtenir(adresse, fenetre=True)
        zone = urllib.parse.quote(f"{jour}|{jour}|00:00|23:59")
        _, par_le_glisse = self._obtenir(f"/suivi/plage?zone={zone}",
                                         fenetre=True)
        ids = lambda p: sorted(set(re.findall(r'name="rdv" value="(\d+)"', p)))
        self.assertEqual(ids(par_le_clic), sorted(str(r) for r in self.attendus))
        self.assertEqual(ids(par_le_clic), ids(par_le_glisse))

        # Et sans JavaScript, le même lien mène à la même plage en PAGE
        # entière — c'est le seul chemin au doigt, le glissé n'existant qu'à la
        # souris dans tout RingBack.
        _, en_page = self._obtenir(adresse)
        self.assertIn("<html", en_page)
        self.assertIn("Plage sélectionnée", en_page)
        self.assertEqual(ids(en_page), ids(par_le_clic))

    def _etape2(self, b):
        """Passe l'étape ② comme lui : entreprise, raison, places de repli.

        Depuis son planning, la sélection saute directement à l'étape ③ et le
        message reste à écrire — sans lui, rien ne part (voir l'essai du refus).
        """
        self._poster("/assistant/message", {
            "b": b, "action": "continuer",
            "info_entreprise": "Cabinet Essai",
            "info_raison": "un imprévu",
            "info_creneau_le_plus_proche": "2026-08-21T09:00",
            "info_creneaux_remplacement": "jeudi 14h00"})
        return b

    def _grille(self, b):
        """SON GESTE : la grille de l'étape ③ renvoyée telle qu'affichée, avec
        un numéro tapé dans chaque case vide. Ce sont les VRAIS champs du
        formulaire (`nom_N`, `tel_N`, `c_<code>_N`) — remplir le brouillon en
        mémoire ne testerait que la moitié du chemin. Un numéro DIFFÉRENT par
        ligne : la grille refuse les doublons, et c'est une bonne règle."""
        donnees = {"b": b, "action": "valider"}
        brouillon = self.application.obtenir_brouillon_assistant(b)
        for rang, contact in enumerate(brouillon["contacts"], start=1):
            donnees[f"nom_{rang}"] = contact["nom"]
            donnees[f"tel_{rang}"] = (contact["telephone"]
                                      or f"+33 6 00 00 00 5{rang}")
            for code, valeur in (contact.get("champs") or {}).items():
                donnees[f"c_{code}_{rang}"] = valeur
        return donnees

    def test_le_numero_tape_dans_la_grille_va_jusqu_a_la_fiche(self):
        """⚠ SON ÉCRAN DU 19/08/2026 : « Mme Aïcha Toussaint — 06 06 •• •• 06 —
        🚫 exclu — Aucun numéro à composer ».

        Il avait complété le numéro dans la grille, comme l'écran le lui
        demandait, et la campagne l'excluait quand même. Le numéro était bien
        enregistré SUR LA CAMPAGNE — mais c'est la FICHE CLIENT qui est
        composée (`db.client_pour_contact`), et la fiche, elle, restait vide.
        Le geste que l'écran réclame n'allait pas jusqu'au bout.
        """
        base = self.application.base
        identifiants = self._sans_aucun_numero()
        vides = [base.obtenir_rendezvous(r)["client_id"] for r in self.attendus]
        self.assertEqual({base.telephone_de(c) for c in vides}, {""})
        _, page = self._poster("/suivi/plage/deplacement",
                               {"rdv": identifiants})
        b = self._etape2(self._brouillon(page))
        self._poster("/assistant/liste", self._grille(b))
        campagne = base.lister_campagnes()[0]
        # LES FICHES SONT COMPLÉTÉES — sans quoi il n'y a rien à composer.
        self.assertEqual({base.telephone_de(c) for c in vides},
                         {"+33 6 00 00 00 51", "+33 6 00 00 00 52",
                          "+33 6 00 00 00 53", "+33 6 00 00 00 54"})
        # Et plus personne n'est écarté faute de numéro.
        contacts = base.contacts_de_campagne(campagne["id"])
        self.assertEqual(len(contacts), 4)
        self.assertEqual({c["etat"] for c in contacts}, {"à appeler"})
        self.assertEqual([c["detail"] for c in contacts if c["detail"]], [])

    def test_valider_sans_message_refuse_au_lieu_de_planter(self):
        """⚠ PAGE BLANCHE, mesurée le 20/08/2026 sur son parcours de tous les
        jours : planning → sélection → « Déplacer ces rendez-vous » → Valider.

        La sélection saute DIRECTEMENT à l'étape ③, et le brouillon arrive sans
        message (« mission » à None). Le bouton Valider est là, visible, actif.
        Cliquer dessus faisait remonter une IntegrityError de SQLite jusqu'au
        gestionnaire HTTP : connexion coupée, page blanche, aucune explication,
        et le travail de sélection perdu.

        La règle existait pourtant déjà quinze lignes plus haut, pour les cases
        de la grille : un champ obligatoire vide se REFUSE, en disant où aller
        le remplir. C'est cette règle-là qu'on éprouve, pas le cas.
        """
        base = self.application.base
        menu = self._menu()
        identifiants = sorted(set(re.findall(r'name="rdv" value="(\d+)"', menu)))
        _, page = self._poster("/suivi/plage/deplacement",
                               {"rdv": identifiants})
        b = self._brouillon(page)
        avant = len(self.application.obtenir_brouillon_assistant(b)["contacts"])
        self.assertGreater(avant, 0)
        self.assertIsNone(
            self.application.obtenir_brouillon_assistant(b)["mission"])
        # ⚠ PAS DE `_etape2` ICI : c'est tout l'objet de l'essai.
        code, refus = self._poster("/assistant/liste", self._grille(b))
        self.assertEqual(code, 200)
        self.assertIn("Le message à dire au téléphone est vide", refus)
        self.assertIn("étape ②", refus)
        # Rien n'est parti, et la sélection n'est pas perdue.
        self.assertEqual(base.lister_campagnes(), [])
        self.assertEqual(
            len(self.application.obtenir_brouillon_assistant(b)["contacts"]),
            avant)
        # Et le message écrit, la même grille passe.
        self._etape2(b)
        self._poster("/assistant/liste", self._grille(b))
        self.assertEqual(len(base.lister_campagnes()), 1)

    def test_un_numero_deja_en_fiche_n_est_jamais_ecrase(self):
        """La contre-épreuve : COMPLÉTER n'est pas ÉCRASER. Une campagne n'a
        pas à réécrire ses données clients sans qu'il l'ait demandé."""
        base = self.application.base
        menu = self._menu()
        identifiants = sorted(set(re.findall(r'name="rdv" value="(\d+)"', menu)))
        _, page = self._poster("/suivi/plage/deplacement",
                               {"rdv": identifiants})
        b = self._etape2(self._brouillon(page))
        brouillon = self.application.obtenir_brouillon_assistant(b)
        vise = next(c for c in brouillon["contacts"] if c["telephone"])
        client_id = base.obtenir_rendezvous(vise["rendezvous_id"])["client_id"]
        avant = base.telephone_de(client_id)
        self.assertNotEqual(avant, "")
        donnees = self._grille(b)
        rang = brouillon["contacts"].index(vise) + 1
        donnees[f"tel_{rang}"] = "+33 6 00 00 00 99"
        self._poster("/assistant/liste", donnees)
        self.assertEqual(base.telephone_de(client_id), avant)

    def test_une_plage_sans_rendez_vous_ne_propose_pas_ces_trois(self):
        menu = self._menu("17:00", "18:00")
        # ⚠ LE BOUTON NE DISPARAÎT PAS EN SILENCE : une ligne dit pourquoi.
        self.assertIn("Aucun rendez-vous dans cette plage", menu)
        self.assertNotIn('action="/suivi/plage/deplacement"', menu)
        self.assertNotIn('action="/suivi/plage/rappel-rdv"', menu)

    def _sans_aucun_numero(self):
        """Retire le numéro de tout le monde, et rend les identifiants."""
        base = self.application.base
        for rdv in self.attendus:
            fiche = base.obtenir_rendezvous(rdv)
            base.modifier_client(fiche["client_id"], fiche["nom"], "")
        menu = self._menu()
        return sorted(set(re.findall(r'name="rdv" value="(\d+)"', menu)))

    def test_personne_sans_numero_entre_dans_la_grille_a_completer(self):
        """⚠ SA DEMANDE DU 18/08/2026, et le défaut qu'elle corrige.

        Il sélectionnait quatre rendez-vous sur son planning et n'en retrouvait
        que trois à l'étape 3 : celui de 40 minutes manquait. Il en a conclu que
        la durée écartait la personne. La cause mesurée était autre — elle n'a
        pas de numéro — mais la conclusion qui compte est la sienne : **il avait
        sélectionné cette personne, il devait la retrouver**.

        La grille de l'étape 3 sait corriger un numéro en tapant, et elle REFUSE
        de se valider tant qu'une case obligatoire est vide : c'est l'endroit
        prévu pour ça. L'écarter en amont lui retirait le seul geste qui règle
        le problème.

        Avant, quand PERSONNE n'avait de numéro, la campagne était refusée tout
        court. Il n'y a plus de refus : il y a une grille à compléter.
        """
        identifiants = self._sans_aucun_numero()
        _, page = self._poster("/suivi/plage/deplacement",
                               {"rdv": identifiants})
        self.assertIn("3. Les personnes", page)
        brouillon = self.application.obtenir_brouillon_assistant(
            self._brouillon(page))
        # LES QUATRE SONT LÀ, chacun avec sa case téléphone vide.
        self.assertEqual(len(brouillon["contacts"]), 4)
        self.assertEqual({c["telephone"] for c in brouillon["contacts"]}, {""})
        self.assertIn("4 personne(s) reprise(s)", page)
        self.assertIn("4 numéro(s) à compléter dans la grille", page)

    def test_la_grille_refuse_de_se_valider_sans_les_numeros(self):
        """La contre-épreuve : laisser ENTRER ne veut pas dire laisser PASSER.
        Une campagne ne part pas avec un numéro vide — la grille le dit et le
        refuse, comme pour toute case obligatoire."""
        identifiants = self._sans_aucun_numero()
        _, page = self._poster("/suivi/plage/deplacement",
                               {"rdv": identifiants})
        _, refus = self._poster("/assistant/liste",
                                {"b": self._brouillon(page),
                                 "action": "valider"})
        # ⚠ ON NE CHERCHE PAS LE MOT « prête » : il est dans le LIBELLÉ du
        # bouton de validation (« état « prête », personne n'est appelé »), et
        # l'y chercher rendait cet essai vert quoi qu'il arrive.
        self.assertIn("3. Les personnes", refus)
        self.assertIn(assistant.MESSAGE_CHAMPS_OBLIGATOIRES, refus)
        self.assertEqual(len(self.application.base.lister_campagnes()), 0)

    def test_un_refus_de_plage_laisse_toujours_un_chemin_de_retour(self):
        """⚠ L'ÉCRAN SUR LEQUEL IL EST RESTÉ BLOQUÉ, le 17/08/2026.

        Ses trois formulaires de plage sont de vrais envois de formulaire — ils
        ne portent pas `data-modale-envoi`, donc le navigateur NAVIGUE. Le refus
        « aucun numéro utilisable » arrivait alors en pleine page : une fenêtre
        servie nue, sans menu, sans le moindre lien, et avec un bouton
        « Fermer ✕ » qui ne pouvait rien fermer puisqu'il n'y avait plus de page
        dessous. Mesuré dans le navigateur : zéro balise <a>, et l'adresse
        inchangée après le clic sur Fermer.

        L'essai qui existait vérifiait le CODE et la PHRASE — il était vert, et
        le produit était un cul-de-sac. La règle existait pourtant ailleurs :
        `_erreur` et la page « Rendez-vous sans numéro » rendent toutes deux une
        page entière avec un retour. C'est cette règle-là qu'on éprouve ici, et
        pour les trois refus à la fois.
        """
        # ⚠ LES REFUS QUI EXISTENT ENCORE. Celui de « aucun numéro utilisable »
        # a disparu le 18/08/2026 : ces personnes entrent désormais dans la
        # grille pour y être complétées. Restent la plage vide, et les
        # rendez-vous disparus entre la sélection et le clic.
        refus = [("/suivi/plage/deplacement", {"rdv": []}, 400),
                 ("/suivi/plage/rappel-rdv", {"rdv": ["999999"]}, 409),
                 ("/suivi/plage/creneau-libere", {"creneau": []}, 400)]
        for chemin, donnees, code in refus:
            with self.subTest(chemin=chemin):
                with self.assertRaises(urllib.error.HTTPError) as leve:
                    self._poster(chemin, donnees)
                self.assertEqual(leve.exception.code, code)
                page = leve.exception.read().decode("utf-8")
                # UNE PAGE ENTIÈRE, pas une fenêtre orpheline : elle porte la
                # bannière et les onglets, donc tout le reste du produit reste
                # atteignable.
                self.assertIn("<html", page)
                self.assertIn('<nav class="onglets">', page)
                # ⚠ ET LE REFUS EST DANS LA PAGE, pas dans un dialogue posé sur
                # rien : c'est cette différence-là qui le piégeait. (Le mot
                # « modale » se trouve dans la feuille de style et le script de
                # TOUTES les pages — le chercher ne prouverait rien.)
                dedans = page.split("<main", 1)[1].split("</main>", 1)[0]
                self.assertIn("Retour au planning", dedans)
                # ET UN CHEMIN DE RETOUR, qui ramène au planning.
                self.assertIn('href="/suivi', dedans)

    def test_la_fenetre_nomme_les_personnes_a_completer(self):
        """« Complétez les fiches dans 👥 Contacts » sans dire LESQUELLES :
        sur sa journée de treize personnes, il fallait les chercher une à une.
        Les noms sont là, sous la main — et ils sont dits AVANT de choisir la
        campagne, pas après."""
        self._sans_aucun_numero()
        menu = self._menu()
        self.assertIn("4 personnes sans numéro", menu)
        # ⚠ TROIS NOMS CITÉS, PAS QUATRE : au-delà de trois, la liste
        # deviendrait plus longue que la fenêtre — on cite et on renvoie.
        for nom in ("M. Deux", "M. Doublon", "Mme Sans Numéro"):
            with self.subTest(nom=nom):
                self.assertIn(html.escape(nom), menu)
        self.assertIn("et 1 autre(s)", menu)
        self.assertIn('href="/sans-numero"', menu)

    def test_la_plage_sans_glisser_arrive_en_page_entiere(self):
        """Le repli « Sans glisser » est un formulaire GET ordinaire : c'est le
        SEUL chemin sans souris — donc au doigt, sur téléphone. Il tombait sur
        la même fenêtre nue que les refus."""
        jour = self.demain.isoformat()
        _, page = self._obtenir(f"/suivi/plage?jour1={jour}&jour2={jour}"
                                "&heure1=09%3A00&heure2=12%3A00")
        self.assertIn("<html", page)
        self.assertIn("Plage sélectionnée", page)
        # Les campagnes restent proposées : c'est une page, pas un refus.
        self.assertIn('action="/suivi/plage/deplacement"', page)
        self.assertIn("Retour au planning", page)

    def test_la_semaine_regardee_revient_avec_le_refus(self):
        """Le retour retombe sur la grille qu'il regardait, pas sur la semaine
        courante : l'année et la semaine voyagent avec chaque plage."""
        menu = self._menu()
        # La fenêtre les emporte dans les TROIS formulaires de rendez-vous,
        # comme elle le faisait déjà pour « créneau libéré ». (Cette plage-ci
        # n'a aucune place libre : elle ne porte donc que ces trois-là.)
        self.assertEqual(menu.count("</form>"), 3)
        self.assertEqual(menu.count('name="annee"'), 3)
        self.assertEqual(menu.count('name="semaine"'), 3)
        with self.assertRaises(urllib.error.HTTPError) as leve:
            self._poster("/suivi/plage/deplacement",
                         {"rdv": ["999999"], "annee": "2026",
                          "semaine": "34"})
        self.assertIn('href="/suivi?annee=2026&amp;semaine=34"',
                      leve.exception.read().decode("utf-8"))

    def test_sans_identifiant_c_est_refuse(self):
        with self.assertRaises(urllib.error.HTTPError) as refus:
            self._poster("/suivi/plage/deplacement", {"rdv": []},
                         fenetre=True)
        self.assertEqual(refus.exception.code, 400)

    def test_la_recette_dit_que_la_liste_n_est_pas_rejouable(self):
        """La plage est choisie à la main : la campagne n'est pas reproductible
        sur un autre créneau, et la recette le dit au lieu d'inventer une liste
        au maillon suivant."""
        menu = self._menu()
        identifiants = sorted(set(re.findall(r'name="rdv" value="(\d+)"', menu)))
        _, page = self._poster("/suivi/plage/deplacement",
                               {"rdv": identifiants})
        b = re.search(r'name="b" value="(\d+)"', page).group(1)
        brouillon = self.application.obtenir_brouillon_assistant(b)
        # ⚠ « planning » N'EST PAS UN MODE REPRODUCTIBLE : il lève le drapeau
        # « à la main », et c'est bien ce qu'on veut dire — une plage choisie
        # du doigt ne se recalcule pas sur un autre créneau.
        self.assertTrue(brouillon["recette"]["a_la_main"])
        self.assertFalse(
            assistant.recette_reproductible(brouillon["recette"]))


class TestRappelsHumainsParcourables(_TestAvecServeurWeb):
    """⚠ SON DÉFAUT N° 13 DU 18/08/2026 : 905 rappels par un humain servis
    d'un seul bloc.

    Mesuré dans sa base : la liste se rendait ENTIÈRE, sans page, sans tri,
    sans moyen de voir d'où venait la masse. Une liste qu'on ne peut pas
    parcourir n'est pas une liste de travail, c'est un mur — et elle finit
    ignorée.

    ⚠ ON N'EN SOLDE AUCUN À SA PLACE : ce sont des demandes de personnes. On
    rend la liste parcourable, et on DIT d'où vient la masse — c'est ce qui
    permet de décider. Mesuré sur sa base après correction : deux campagnes à
    elles seules pesaient 640 des 904 rappels.
    """

    def _peupler(self, combien):
        base = self.application.base
        campagnes_ids = []
        for rang in range(2):
            campagnes_ids.append(base.creer_campagne(
                f"Campagne massive {rang}", "deplacement", mission="Bonjour."))
        for rang in range(combien):
            campagne = campagnes_ids[0 if rang % 3 else 1]
            contact = base.ajouter_contact_campagne(
                campagne, rang + 1, f"M. Attente {rang:03d}",
                "+33 6 00 00 00 51")
            base.changer_etat_contact_campagne(
                contact, "à rappeler par un humain", "to_reschedule")
        return campagnes_ids

    def _panneau(self, page, famille="humains"):
        return page.split(f'id="panneau-{famille}"')[1].split("</section>")[0]

    def test_la_liste_se_parcourt_page_par_page(self):
        """⚠ LA MÊME PAGINATION QUE 👥 CONTACTS (21/08/2026, sa demande :
        « exactement la même chose que dans la page Contacts »). Deux écrans qui
        font le même geste doivent le faire de la même façon — sans quoi il faut
        réapprendre à chaque page."""
        par_page = serveur.Gestionnaire.PAR_PAGE_DEFAUT_RELANCES
        self._peupler(par_page + 2)
        _, page1 = self._obtenir("/relances?vue=humains")
        panneau = self._panneau(page1)
        # ⚠ ON COMPTE LES LIGNES DU TABLEAU, pas les contacts en base : c'est ce
        # que la page SERT qui doit être borné.
        self.assertEqual(panneau.count("✔ C'est fait"), par_page,
                         "la page ne borne pas ce qu'elle sert")
        self.assertIn(f"sur {par_page + 2}", panneau)
        self.assertIn("page <strong>1</strong> sur 2", panneau)
        # Les QUATRE boutons de 👥 Contacts, et pas des liens.
        for signe in ("≪", "‹", "›", "≫"):
            self.assertIn(f">{signe}</button>", panneau)
        self.assertIn('name="page_humains"', panneau)
        self.assertIn('form="filtres-relances-humains"', panneau)
        # La page 2 porte le reste.
        _, page2 = self._obtenir("/relances?vue=humains&page_humains=2")
        panneau2 = self._panneau(page2)
        self.assertEqual(panneau2.count("✔ C'est fait"), 2)
        self.assertIn("page <strong>2</strong> sur 2", panneau2)
        # ⚠ UNE PAGE HORS BORNES RETOMBE SUR LA DERNIÈRE, jamais sur du vide :
        # une liste vide se lirait « il n'y a plus rien », ce qui serait faux.
        _, loin = self._obtenir("/relances?vue=humains&page_humains=99")
        self.assertIn("page <strong>2</strong> sur 2", self._panneau(loin))

    def test_les_boutons_sont_desactives_aux_extremites(self):
        """⚠ DÉSACTIVÉS, JAMAIS MASQUÉS — la règle de 👥 Contacts, mot pour mot :
        un bouton qui disparaît fait douter de l'endroit où l'on est."""
        self._peupler(serveur.Gestionnaire.PAR_PAGE_DEFAUT_RELANCES + 2)
        _, page1 = self._obtenir("/relances?vue=humains")
        debut = self._panneau(page1)
        self.assertEqual(debut.count("disabled"), 2)   # ≪ et ‹
        _, page2 = self._obtenir("/relances?vue=humains&page_humains=2")
        self.assertEqual(self._panneau(page2).count("disabled"), 2)  # › et ≫

    def test_combien_par_page_se_choisit_comme_dans_contacts(self):
        """Les mêmes tailles, le même défaut, et « tous » qui retire la
        pagination — c'est le sélecteur de 👥 Contacts, pas un autre."""
        self.assertEqual(serveur.Gestionnaire.PAR_PAGE_CHOIX_RELANCES,
                         serveur.Gestionnaire.PAR_PAGE_CHOIX)
        # ⚠ LE SEUL ÉCART AVEC 👥 CONTACTS, ET IL EST VOULU (21/08/2026, sa
        # demande) : DIX par défaut, pas vingt-cinq. Une ligne de rappel porte
        # une demande à LIRE (« sa demande, en clair »), pas une fiche à
        # survoler — vingt-cinq paragraphes d'un coup ne se lisent pas.
        self.assertEqual(serveur.Gestionnaire.PAR_PAGE_DEFAUT_RELANCES, 10)
        self._peupler(30)
        _, page = self._obtenir("/relances?vue=humains&par_page=10")
        panneau = self._panneau(page)
        self.assertEqual(panneau.count("✔ C'est fait"), 10)
        self.assertIn("page <strong>1</strong> sur 3", panneau)
        # « tous » : la liste entière, et plus aucune barre de pages.
        _, tout = self._obtenir("/relances?vue=humains&par_page=0")
        entier = self._panneau(tout)
        self.assertEqual(entier.count("✔ C'est fait"), 30)
        self.assertNotIn('name="page_humains"', entier)

    def test_chaque_partie_a_SA_pagination(self):
        """⚠ SA DEMANDE, MOT POUR MOT : « il y a une pagination pour chaque
        partie qui contient des contacts ».

        Les cinq familles vivent dans la MÊME page (une seule est visible, les
        autres portent `hidden`). Un unique paramètre « page » aurait fait sauter
        les quatre autres au même numéro dès qu'on tourne une page. Chacune a
        donc le sien, et elles ne se marchent pas dessus.
        """
        base = self.application.base
        self._peupler(30)
        # Une seconde famille bien remplie : les 📵 non joints.
        campagne = base.creer_campagne("Bloqués", "deplacement",
                                       mission="Bonjour.")
        for rang in range(12):
            contact = base.ajouter_contact_campagne(
                campagne, rang + 1, f"M. Bloqué {rang:02d}",
                "+33 6 00 00 00 52")
            base.changer_etat_contact_campagne(contact, "injoignable",
                                               "no_answer")
        _, page = self._obtenir(
            "/relances?vue=humains&par_page=10&page_humains=3&page_bloques=2")
        self.assertIn("page <strong>3</strong> sur 3",
                      self._panneau(page, "humains"))
        self.assertIn("page <strong>2</strong> sur 2",
                      self._panneau(page, "bloques"))

    def test_une_partie_vide_n_a_pas_de_pagination(self):
        """LA CONTRE-ÉPREUVE : une barre de pages sur une liste vide serait un
        ornement, et un ornement finit par être lu comme une information."""
        self._peupler(3)
        _, page = self._obtenir("/relances?vue=dues")
        self.assertNotIn('name="page_dues"', self._panneau(page, "dues"))
        # Trois rappels humains : une seule page, donc pas de barre non plus.
        self.assertNotIn('name="page_humains"', self._panneau(page, "humains"))

    def test_le_bouton_LANCE_toutes_les_dues_pas_la_page_affichee(self):
        """⚠ UNE PAGINATION CHANGE CE QU'ON VOIT, JAMAIS CE QU'UN GESTE FAIT.
        Croire n'en lancer que vingt-cinq et en lancer cent serait le pire des
        malentendus — le bouton porte donc le TOTAL, pas le nombre affiché."""
        base = self.application.base
        campagne = base.creer_campagne("Dues", "deplacement", mission="B.")
        for rang in range(30):
            contact = base.ajouter_contact_campagne(
                campagne, rang + 1, f"M. Dû {rang:02d}", "+33 6 00 00 00 53")
            base.creer_relance(campagne, contact, HIER, tentative=1,
                               motif="pas de réponse")
        _, page = self._obtenir("/relances?vue=dues&par_page=10")
        panneau = self._panneau(page, "dues")
        self.assertIn("page <strong>1</strong> sur 3", panneau)
        self.assertIn("Lancer les 30 relance(s) due(s)", panneau)

    def test_la_barre_porte_les_memes_champs_que_contacts(self):
        """⚠ SA REMARQUE DU 21/08/2026 : « tu as oublié toute la partie filtre ».

        Il avait raison : je n'avais porté que « Combien par page ». Retrouver
        quelqu'un parmi 917 rappels étalés sur 37 pages sans recherche, c'est
        exactement le mur que la pagination devait abattre.
        """
        self._peupler(3)
        _, page = self._obtenir("/relances")
        barre = page[page.index('id="filtres-relances-humains"'):]
        barre = barre[:barre.index("</form>")]
        for champ in ('name="recherche"', 'name="interdit"',
                      'name="par_page"'):
            self.assertIn(champ, barre)
        self.assertIn("Rechercher un contact — nom ou numéro", barre)
        self.assertIn("Contact par l'agent", barre)
        self.assertIn("Filtrer", barre)

    def test_le_filtre_est_JUSTE_au_dessus_de_sa_liste(self):
        """⚠ SA DEMANDE DU 21/08/2026, capture à l'appui : « je veux que les
        filtres soient juste au-dessus de la pagination, pas au-dessus d'un
        texte, sinon c'est trop compliqué à comprendre pour l'utilisateur ».

        La barre était posée EN TÊTE DE PAGE, séparée de la liste qu'elle filtre
        par le titre de la famille et deux paragraphes d'explication : rien ne
        disait sur quoi elle agissait. On mesure donc l'ORDRE, pas la présence.
        """
        self._peupler(3)
        _, page = self._obtenir("/relances")
        panneau = self._panneau(page)
        formulaire = panneau.index('id="filtres-relances-humains"')
        compte = panneau.index("rappel(s) sur 3")
        pages = panneau.index('class="pagination"') if 'class="pagination"' in panneau else compte + 1
        tableau = panneau.index("<table")
        self.assertLess(formulaire, compte, "le filtre passe APRÈS son compte")
        self.assertLess(compte, tableau, "le compte passe APRÈS la liste")
        # ⚠ ET IL N'EST PLUS EN TÊTE DE PAGE : rien avant le premier panneau.
        avant = page[:page.index('id="panneau-humains"')]
        self.assertNotIn("filtres-relances", avant)

    def test_chaque_partie_a_SON_formulaire_sans_doublon_d_identifiant(self):
        """⚠ CINQ FORMULAIRES, CINQ IDENTIFIANTS. Le même `id` répété serait du
        HTML invalide, et les boutons de page des quatre dernières parties se
        rattacheraient tous au premier — on tournerait la page d'une famille en
        croyant tourner celle d'une autre."""
        base = self.application.base
        self._peupler(3)
        campagne = base.creer_campagne("Non joints", "deplacement",
                                       mission="B.")
        contact = base.ajouter_contact_campagne(campagne, 1, "M. Bloqué",
                                                "+33 6 00 00 00 71")
        base.changer_etat_contact_campagne(contact, "injoignable", "no_answer")
        _, page = self._obtenir("/relances")
        for famille in ("humains", "bloques"):
            with self.subTest(famille=famille):
                self.assertEqual(page.count(f'id="filtres-relances-{famille}"'),
                                 1)
                # Le formulaire de CETTE partie porte SA vue.
                bloc = page[page.index(f'id="filtres-relances-{famille}"'):]
                bloc = bloc[:bloc.index("</form>")]
                self.assertIn(f'name="vue" value="{famille}"', bloc)

    def test_ni_etat_ni_non_traite_ne_doublent_le_menu(self):
        """⚠ CE QUE JE N'AI PAS COPIÉ, ET POURQUOI. Sur 👥 Contacts, « État » et
        « non traité » découpent une liste unique. Sur 🔁 Relances, ce découpage
        EST déjà le menu des cinq familles : les remettre en sélecteur aurait
        posé deux commandes disant la même chose que le menu juste au-dessus —
        et qui pourraient le contredire."""
        self._peupler(3)
        _, page = self._obtenir("/relances")
        barre = page[page.index('id="filtres-relances-humains"'):]
        barre = barre[:barre.index("</form>")]
        self.assertNotIn('name="etat"', barre)
        self.assertNotIn('name="non_traite"', barre)
        # Le menu des familles, lui, est bien là : c'est LUI le découpage.
        self.assertIn('class="menu-familles"', page)

    def test_la_recherche_trouve_par_le_nom(self):
        base = self.application.base
        self._peupler(3)
        campagne = base.creer_campagne("Une", "deplacement", mission="B.")
        contact = base.ajouter_contact_campagne(campagne, 1, "Mme Lefèvre Cible",
                                                "+33 6 00 00 00 51")
        base.changer_etat_contact_campagne(contact, "à rappeler par un humain",
                                           "to_reschedule")
        # ⚠ SANS ACCENT NI CASSE : chercher un nom ne doit pas exiger de taper
        # les accents — la même règle que 👥 Contacts.
        _, page = self._obtenir("/relances?recherche=lefevre")
        panneau = self._panneau(page)
        self.assertIn("Mme Lefèvre Cible", panneau)
        self.assertIn("<strong>1</strong> rappel(s) sur 4", panneau)
        self.assertIn("nom ou numéro contenant « lefevre »", panneau)

    def test_la_recherche_trouve_par_le_numero(self):
        """⚠ ET LE NUMÉRO N'EST JAMAIS COMPARÉ À L'ÉCRAN : les lignes ne portent
        que le masque. La base rend des IDENTIFIANTS ; on ne fait que les
        reconnaître. C'est la règle du produit, et elle tient ici aussi."""
        base = self.application.base
        self._peupler(3)
        campagne = base.creer_campagne("Une", "deplacement", mission="B.")
        numero = "+33 6 00 00 00 61"
        contact = base.ajouter_contact_campagne(campagne, 1, "M. Par Numéro",
                                                numero)
        base.changer_etat_contact_campagne(contact, "à rappeler par un humain",
                                           "to_reschedule")
        # La fin du numéro suffit — on retient rarement l'indicatif.
        _, page = self._obtenir("/relances?recherche=000061")
        panneau = self._panneau(page)
        self.assertIn("M. Par Numéro", panneau)
        self.assertIn("<strong>1</strong> rappel(s) sur 4", panneau)
        # LE NUMÉRO EN CLAIR NE SORT PAS pour autant.
        self.assertNotIn(numero, page)

    def test_le_filtre_du_contact_par_l_agent(self):
        """⚠ CELUI-LÀ A UN SENS ICI : parmi les 🙋, certains ont refusé l'agent
        (20/08). Les isoler d'un geste, c'est séparer deux travaux qui ne se
        traitent pas pareil."""
        base = self.application.base
        self._peupler(3)
        campagne = base.creer_campagne("Une", "deplacement", mission="B.")
        client = base.ajouter_client("Mme Interdite", "+33 6 00 00 00 62")
        base.definir_ne_plus_appeler(client, True)
        contact = base.ajouter_contact_campagne(campagne, 1, "Mme Interdite",
                                                "+33 6 00 00 00 62",
                                                client_id=client)
        base.changer_etat_contact_campagne(contact, "à rappeler par un humain",
                                           None)
        _, page = self._obtenir("/relances?interdit=interdits")
        panneau = self._panneau(page)
        self.assertIn("Mme Interdite", panneau)
        self.assertIn("<strong>1</strong> rappel(s) sur 4", panneau)
        self.assertIn("contact par agent interdit", panneau)

    def test_un_filtre_sans_resultat_ne_dit_PAS_que_la_liste_est_vide(self):
        """⚠ « AUCUN RÉSULTAT » N'EST PAS « CETTE LISTE EST VIDE », et l'écran
        confondait les deux : filtrer sur un nom absent affichait le message de
        famille vide — alors qu'elle contenait tout son monde. Un écran qui ment
        sur ce qu'il contient est pire qu'un écran qui se tait."""
        self._peupler(5)
        _, page = self._obtenir("/relances?recherche=PersonneDeCeNom")
        panneau = self._panneau(page)
        self.assertIn("<strong>0</strong> rappel(s) sur 5", panneau)
        self.assertIn("Aucun résultat pour ce filtre", panneau)
        self.assertIn("n'est pas vide pour autant", panneau)

    def test_on_filtre_AVANT_de_paginer(self):
        """⚠ JAMAIS L'INVERSE. Paginer puis filtrer aurait cherché dans les
        vingt-cinq lignes affichées : une recherche qui ne fouille que la page
        en cours ne cherche rien."""
        base = self.application.base
        self._peupler(60)          # bien plus que la page par défaut
        campagne = base.creer_campagne("Une", "deplacement", mission="B.")
        contact = base.ajouter_contact_campagne(campagne, 1, "M. Tout Au Fond",
                                                "+33 6 00 00 00 63")
        base.changer_etat_contact_campagne(contact, "à rappeler par un humain",
                                           "to_reschedule")
        # Il est le 61e : la première page ne le porte pas.
        _, sans = self._obtenir("/relances")
        self.assertNotIn("M. Tout Au Fond", self._panneau(sans))
        # La recherche le trouve quand même.
        _, avec = self._obtenir("/relances?recherche="
                                + urllib.parse.quote("Tout Au Fond"))
        panneau = self._panneau(avec)
        self.assertIn("M. Tout Au Fond", panneau)
        self.assertIn("<strong>1</strong> rappel(s) sur 61", panneau)

    def test_le_filtre_vaut_pour_CHAQUE_partie(self):
        """Sa demande portait sur « chaque partie qui contient des contacts » :
        le filtre aussi, pas seulement la pagination."""
        base = self.application.base
        campagne = base.creer_campagne("Non joints", "deplacement",
                                       mission="B.")
        for rang, nom in enumerate(("M. Cherché", "M. Autre"), start=1):
            contact = base.ajouter_contact_campagne(campagne, rang, nom,
                                                    f"+33 6 00 00 00 7{rang}")
            base.changer_etat_contact_campagne(contact, "injoignable",
                                               "no_answer")
        _, page = self._obtenir("/relances?vue=bloques&recherche="
                                + urllib.parse.quote("Cherché"))
        panneau = self._panneau(page, "bloques")
        self.assertIn("M. Cherché", panneau)
        self.assertNotIn("M. Autre", panneau)
        self.assertIn("<strong>1</strong> personne(s) sur 2", panneau)

    def test_la_liste_dit_d_ou_vient_la_masse(self):
        """Sans ce compte, la liste ressemble à 900 problèmes distincts ;
        avec lui, on voit les deux campagnes qu'elle contient."""
        self._peupler(30)
        _, page = self._obtenir("/relances?vue=humains")
        panneau = page.split('id="panneau-humains"')[1].split("</section>")[0]
        self.assertIn("D'où viennent ces rappels", panneau)
        self.assertIn("2 campagne(s)", panneau)
        self.assertIn("Campagne massive 0", panneau)
        self.assertIn("Campagne massive 1", panneau)

    def test_une_seule_campagne_ne_declenche_aucun_compte(self):
        """La contre-épreuve : le compte par campagne n'apporte rien quand il
        n'y a qu'une campagne — et un bloc qui s'affiche toujours devient un
        bruit qu'on ne lit plus."""
        base = self.application.base
        campagne = base.creer_campagne("Seule", "deplacement", mission="B.")
        for rang in range(4):
            contact = base.ajouter_contact_campagne(
                campagne, rang + 1, f"M. Seul {rang}", "+33 6 00 00 00 51")
            base.changer_etat_contact_campagne(
                contact, "à rappeler par un humain", "to_reschedule")
        _, page = self._obtenir("/relances?vue=humains")
        panneau = page.split('id="panneau-humains"')[1].split("</section>")[0]
        self.assertNotIn("D'où viennent ces rappels", panneau)
        # Et sans deuxième page, aucun lien de page ne s'affiche.
        self.assertNotIn("page 1 sur", panneau)


class TestClePourFichier(unittest.TestCase):
    """La clé CALL-E peut venir d'un FICHIER, en plus de la variable.

    ⚠ POURQUOI ON A CHANGÉ UNE PROMESSE (10/08/2026). La clé n'était lue que
    dans CALLE_API_KEY, et le README promettait « jamais écrite dans un
    fichier ». Poser une variable d'environnement est un mur pour un
    indépendant : la solution n'était donc pas utilisable. On garde tout ce qui
    protège vraiment ; on abandonne la seule chose qui empêchait de s'en servir.
    """

    def setUp(self):
        self.dossier = tempfile.mkdtemp(prefix="ringback-cle-")
        self.addCleanup(shutil.rmtree, self.dossier, ignore_errors=True)
        self.chemin = os.path.join(self.dossier, "donnees", "cle_calle.txt")
        self._sauve = calle_client.CHEMIN_CLE
        calle_client.CHEMIN_CLE = self.chemin
        self.addCleanup(setattr, calle_client, "CHEMIN_CLE", self._sauve)
        self._cle_avant = os.environ.pop("CALLE_API_KEY", None)
        if self._cle_avant is not None:
            self.addCleanup(os.environ.__setitem__, "CALLE_API_KEY",
                            self._cle_avant)

    VALABLE = "ZZQQXX778899001122334455"

    def test_ranger_relire_retirer(self):
        self.assertEqual(calle_client.cle_rangee(), "")
        self.assertTrue(calle_client.ranger_cle(self.VALABLE))
        self.assertEqual(calle_client.cle_rangee(), self.VALABLE)
        self.assertTrue(calle_client.retirer_cle())
        self.assertEqual(calle_client.cle_rangee(), "")
        # Retirer deux fois ne casse rien.
        self.assertFalse(calle_client.retirer_cle())

    def test_les_espaces_autour_sont_rangés_nettoyés(self):
        """On colle depuis un courriel : il y a presque toujours un blanc."""
        calle_client.ranger_cle(f"  {self.VALABLE}\n")
        self.assertEqual(calle_client.cle_rangee(), self.VALABLE)

    def test_la_variable_gagne_contre_le_fichier(self):
        """⚠ L'ORDRE COMPTE : quelqu'un qui pose la variable pour un essai
        ponctuel doit gagner, sans avoir à supprimer le fichier."""
        calle_client.ranger_cle(self.VALABLE)
        self.assertEqual(calle_client.cle_disponible()[1],
                         calle_client.SOURCE_FICHIER)
        os.environ["CALLE_API_KEY"] = "ZZVARIABLE778899001122334455"
        self.addCleanup(os.environ.pop, "CALLE_API_KEY", None)
        cle, source = calle_client.cle_disponible()
        self.assertEqual(source, calle_client.SOURCE_VARIABLE)
        self.assertEqual(cle, "ZZVARIABLE778899001122334455")

    def test_une_cle_mal_formee_est_refusee_AVANT_d_etre_rangee(self):
        """⚠ SINON LE REFUS TOMBE AU PREMIER APPEL RÉEL — le plus mauvais
        moment. Et il ne CITE JAMAIS la clé : il la décrit."""
        for mauvaise in ("https://api.exemple.fr/ZZQQXX7788", "ZZQQ",
                         '"ZZQQXX778899001122334455"',
                         "ZZQQXX7788 99001122334455"):
            with self.subTest(cle=mauvaise):
                with self.assertRaises(calle_client.CleApiAbsente) as refus:
                    calle_client.ranger_cle(mauvaise)
                self.assertNotIn("ZZQQXX", str(refus.exception))
                self.assertFalse(os.path.exists(self.chemin))

    def test_un_fichier_illisible_vaut_pas_de_cle(self):
        """Un incident de lecture ne doit surtout pas ressembler à une clé
        fausse : il vaut « aucune clé », et la simulation continue."""
        calle_client.CHEMIN_CLE = os.path.join(self.dossier, "introuvable.txt")
        self.assertEqual(calle_client.cle_rangee(), "")
        self.assertFalse(calle_client.etat_de_la_cle()["presente"])

    def test_l_etat_decrit_la_cle_et_ne_la_montre_jamais(self):
        vide = calle_client.etat_de_la_cle()
        self.assertFalse(vide["presente"])
        calle_client.ranger_cle(self.VALABLE)
        etat = calle_client.etat_de_la_cle()
        self.assertTrue(etat["presente"])
        self.assertTrue(etat["valable"])
        self.assertEqual(etat["source"], calle_client.SOURCE_FICHIER)
        self.assertIn("caractère(s)", etat["description"])
        # ⚠ NULLE PART la clé elle-même.
        self.assertNotIn("ZZQQXX", repr(etat))

    def test_le_client_reel_lit_le_fichier(self):
        """La clé rangée doit VRAIMENT servir : sinon on l'aurait écrite pour
        rien, et l'écran annoncerait un verrou ouvert qui ne l'est pas."""
        calle_client.ranger_cle(self.VALABLE)
        reel = calle_client.AppelReel(
            chemin_audit=os.path.join(self.dossier, "audit.jsonl"))
        self.assertEqual(reel.cle_api, self.VALABLE)


class TestReglagesCalle(_TestAvecServeurWeb):
    """⚙ Réglages → 🔌 CALL-E, et la page de l'installeur.

    ⚠ LES TROIS VERROUS NE BOUGENT PAS. Ranger une clé n'autorise aucun appel :
    il faut encore lancer avec « --appels-reels » et retaper « APPELER ».
    L'écran le dit à l'endroit où l'on pourrait croire le contraire.
    """

    VALABLE = "ZZQQXX778899001122334455"

    def setUp(self):
        super().setUp()
        self.dossier_cle = tempfile.mkdtemp(prefix="ringback-cle-web-")
        self.addCleanup(shutil.rmtree, self.dossier_cle, ignore_errors=True)
        self._sauve = calle_client.CHEMIN_CLE
        calle_client.CHEMIN_CLE = os.path.join(self.dossier_cle, "d",
                                               "cle_calle.txt")
        self.addCleanup(setattr, calle_client, "CHEMIN_CLE", self._sauve)
        self._cle_avant = os.environ.pop("CALLE_API_KEY", None)
        if self._cle_avant is not None:
            self.addCleanup(os.environ.__setitem__, "CALLE_API_KEY",
                            self._cle_avant)

    def test_la_partie_ne_montre_que_la_cle(self):
        """⚠ RECADRÉ LE 10/08/2026, sur demande du propriétaire : « toute
        l'histoire des trois verrous on supprime, ce qu'on veut ici c'est la clé
        et c'est tout ».

        Les verrous eux-mêmes n'ont pas bougé dans le produit — c'est leur
        RÉCIT qui quitte l'écran, pour se lire dans la procédure repliée, là où
        on en a besoin.
        """
        zone = _zone_visible(self._obtenir("/reglages")[1])
        self.assertIn("🔌 CALL-E", zone)
        self.assertIn("Aucune clé enregistrée", zone)
        self.assertIn('name="cle"', zone)
        # La litanie des verrous n'est plus là.
        for disparu in ("Trois verrous", "Le mot « APPELER » a été retapé",
                        "verrous-calle", "Ranger une clé n'autorise"):
            with self.subTest(disparu=disparu):
                self.assertNotIn(disparu, zone)

    def test_la_procedure_est_repliee_et_va_jusqu_au_bout(self):
        """« Un lien "Comment l'obtenir" et quand on clique cela affiche une
        petite procédure : lien et démarche de bout en bout. »

        ⚠ « DE BOUT EN BOUT » : les étapes vont jusqu'au lancement en mode
        réel. S'arrêter à « collez la clé » laisserait quelqu'un avec une clé
        enregistrée et rien qui part.
        """
        zone = _zone_visible(self._obtenir("/reglages")[1])
        self.assertIn("Comment obtenir une clé CALL-E ?", zone)
        self.assertIn("heycall-e.com", zone)
        self.assertIn("dashboard.heycall-e.com", zone)
        self.assertIn("API keys", zone)
        self.assertIn("--appels-reels", zone)
        self.assertIn("APPELER", zone)
        # ⚠ REPLIÉE : l'écran va droit au but, l'aide attend qu'on la demande.
        # (Un <details> sans « open » est fermé.)
        aide = zone[zone.index('<details class="aide"'):]
        self.assertFalse(aide.startswith('<details class="aide" open'))

    def test_enregistrer_puis_retirer_depuis_les_reglages(self):
        _, page = self._poster("/reglages/calle", {"cle": self.VALABLE})
        self.assertTrue(os.path.exists(calle_client.CHEMIN_CLE))
        self.assertIn("✅ Clé enregistrée", page)
        # ⚠ DÉCRITE, JAMAIS MONTRÉE — et le champ de saisie repart VIDE.
        self.assertIn("caractère(s)", page)
        self.assertNotIn("ZZQQXX", page)
        self.assertNotIn('value="ZZQQXX', page)
        _, page = self._poster("/reglages/calle-retirer", {})
        self.assertFalse(os.path.exists(calle_client.CHEMIN_CLE))
        self.assertIn("Aucune clé enregistrée", page)

    def test_un_refus_reste_sur_l_ecran_et_ne_cite_pas_la_cle(self):
        for mauvaise, code in (("https://api.exemple.fr/ZZQQXX", 400),
                               ("   ", 400)):
            with self.subTest(cle=mauvaise):
                with self.assertRaises(urllib.error.HTTPError) as refus:
                    self._poster("/reglages/calle", {"cle": mauvaise})
                self.assertEqual(refus.exception.code, code)
                corps = refus.exception.read().decode("utf-8")
                self.assertIn("🔌 CALL-E", corps)
                self.assertNotIn("ZZQQXX", corps)
                self.assertFalse(os.path.exists(calle_client.CHEMIN_CLE))

    def test_la_page_de_l_installeur_est_la_premiere_d_appeler(self):
        self.assertEqual(installation.PAGES_APPELS[0][0], "calle")
        _, page = self._obtenir("/installation?page=calle")
        self.assertIn("Connexion à CALL-E", page)
        self.assertIn("La clé de CALL-E, et rien d'autre", page)
        # ⚠ ELLE N'EST PAS OBLIGATOIRE : la clé s'obtient chez CALL-E, ce qui
        # prend du temps. La simulation montre tout sans elle.
        self.assertIn("Passer cette page", page)
        self.assertIn("Passez cette page", page)
        # Et elle n'a PAS de formulaire principal : le pied ne doit pas
        # soumettre un champ de clé vide et effacer ce qui est rangé.
        self.assertNotIn('form="formulaire-page"', page)

    def test_depuis_l_installeur_on_revient_dans_l_installeur(self):
        """⚠ LE MÊME FORMULAIRE SERT AUX DEUX ÉCRANS. Renvoyer toujours aux
        Réglages faisait SORTIR du parcours de configuration, au milieu."""
        _, page = self._obtenir("/installation?page=calle")
        self.assertIn('name="retour" value="calle"', page)
        _, arrivee = self._poster("/reglages/calle",
                                  {"cle": self.VALABLE, "retour": "calle"})
        self.assertIn("Connexion à CALL-E", arrivee)
        self.assertIn("✅ Clé enregistrée", arrivee)
        # Un refus aussi reste dans l'installeur.
        with self.assertRaises(urllib.error.HTTPError) as refus:
            self._poster("/reglages/calle",
                         {"cle": "https://api.exemple.fr/x", "retour": "calle"})
        self.assertIn("Connexion à CALL-E",
                      refus.exception.read().decode("utf-8"))
        # Et le retrait revient au même endroit.
        _, arrivee = self._poster("/reglages/calle-retirer", {"retour": "calle"})
        self.assertIn("Connexion à CALL-E", arrivee)

    def test_l_adresse_de_l_api_est_affichee_sans_etre_saisissable(self):
        """Elle ne se règle que par variable d'environnement : on ne touche à
        l'adresse que pour viser un autre serveur que celui de CALL-E."""
        _, page = self._obtenir("/reglages")
        # ⚠ ELLE A REJOINT LA PROCÉDURE REPLIÉE (10/08/2026) : elle ne concerne
        # que celui qui vise un autre serveur, donc presque personne. Elle reste
        # LISIBLE — la cacher pour de bon aurait rendu ce cas insoluble.
        self.assertIn(calle_client.AppelReel.URL_DEFAUT, page)
        self.assertIn(calle_client.AppelReel.VARIABLE_URL, page)
        self.assertNotIn('name="calle_url"', page)


class TestAgendaExemple(unittest.TestCase):
    """Un agenda ICS fabriqué À L'INSTANT, jamais un fichier figé.

    ⚠ POURQUOI. Les trois exemples livrés portent des dates ÉCRITES : trois
    mois plus tard tout y est passé, l'import ne remplit plus le planning, et
    la démonstration ne montre rien. Celui-ci part de `datetime.now()`.
    """

    def test_il_couvre_cent_jours(self):
        """⚠ CENT JOURS, PARCE QUE LA RÈGLE PROPOSE « JUSQU'À 90 JOURS APRÈS ».
        Demande du propriétaire du 11/08/2026. Avant : 21 jours — les options
        « 30 jours » et « 90 jours » de `assistant.JOURS_APRES` ne pouvaient donc
        rien donner de différent de « sans limite ».
        """
        maintenant = datetime.datetime(2026, 9, 1, 8, 30)
        liste = agenda_exemple.rendezvous(maintenant)
        self.assertGreaterEqual(len(liste), 100, "« une bonne centaine »")
        jours = sorted({debut.date() for debut, *_ in liste})
        self.assertGreaterEqual(len(jours), 10)     # 2 semaines ouvrées
        self.assertGreater(jours[0], maintenant.date())   # tout est DEVANT
        etendue = (jours[-1] - maintenant.date()).days
        self.assertGreaterEqual(etendue, 90, "il faut dépasser la fenêtre de 90")
        self.assertLessEqual(etendue, agenda_exemple.JOURS_COUVERTS)
        # Aucun samedi ni dimanche : un cabinet fermé n'a pas de rendez-vous.
        for jour in jours:
            self.assertLess(jour.weekday(), 5, jour)

    def test_la_densite_decroit_avec_l_eloignement(self):
        """Un agenda réel est presque plein la semaine prochaine et presque vide
        dans trois mois. C'est aussi ce qui laisse des places libres AU LOIN —
        celles qu'une campagne de créneau libéré cherche.
        """
        maintenant = datetime.datetime(2026, 9, 1, 8, 30)
        liste = agenda_exemple.rendezvous(maintenant)
        proche = sum(1 for debut, *_ in liste
                     if (debut.date() - maintenant.date()).days <= 21)
        lointain = sum(1 for debut, *_ in liste
                       if (debut.date() - maintenant.date()).days > 70)
        # Les deux tranches n'ont pas la même longueur : on compare par jour.
        self.assertGreater(proche / 21, lointain / 30)
        self.assertGreater(lointain, 0, "le loin ne doit pas être VIDE")

    def test_une_semaine_type_etroite_reste_dans_les_cent_jours(self):
        """⚠ LE PLAFOND N'ALLONGE JAMAIS L'ÉTENDUE. Un cabinet ouvert une seule
        demi-journée par semaine ne peut pas donner cent rendez-vous en cent
        jours : on prend alors TOUTES ses places libres, et l'on s'arrête quand
        même au centième jour. Sans cette règle, l'exemple s'étalait sur plus
        d'un an — mesuré à 400 jours — ce qui ne ressemble plus à un agenda.
        """
        maintenant = datetime.datetime(2026, 9, 1, 8, 30)
        preferences = generation.Preferences(None)
        horaires.definir_semaine(preferences, {2: [(9 * 60, 12 * 60)]})
        liste = agenda_exemple.rendezvous(maintenant, preferences)
        self.assertTrue(liste)
        etendue = (max(d for d, *_ in liste).date() - maintenant.date()).days
        self.assertLessEqual(etendue, agenda_exemple.JOURS_COUVERTS)
        # Toutes les places sont prises : c'est le repli du plancher.
        jours = {d.date() for d, *_ in liste}
        par_jour = len([d for d, *_ in liste
                        if d.date() == min(jours)])
        self.assertEqual(par_jour, len(agenda_exemple._creneaux(
            [(9 * 60, 12 * 60)], horaires.pas_minutes(preferences))))

    def test_il_se_cale_sur_les_horaires_regles(self):
        """⚠ LA DEMANDE DU 10/08/2026, mot pour mot : « il faut te caler par
        rapport aux journées ouvertes et aux créneaux horaires ».

        Avant, les plages étaient ÉCRITES dans le module : importé dans un
        cabinet qui ouvre le samedi et ferme le mercredi, l'exemple tombait à
        CÔTÉ des heures d'ouverture — le planning montrait des rendez-vous hors
        des cases, et les campagnes de créneau libre ne trouvaient pas les
        places attendues.
        """
        maintenant = datetime.datetime(2026, 9, 1, 8, 30)
        preferences = generation.Preferences(None)
        # Un cabinet ouvert le LUNDI matin et le SAMEDI, par vingt minutes.
        horaires.definir_semaine(preferences, {0: [(9 * 60, 12 * 60)],
                                              5: [(10 * 60, 13 * 60)]})
        preferences.definir(horaires.CLE_PAS, 20)
        liste = agenda_exemple.rendezvous(maintenant, preferences)
        self.assertGreaterEqual(len(liste), 100)      # la cible est tenue
        # ⚠ AUCUN JOUR QUI N'EST PAS OUVERT.
        self.assertEqual(sorted({d.weekday() for d, *_ in liste}), [0, 5])
        # ⚠ AUCUNE HEURE HORS DES PÉRIODES, et toutes sur le PAS réglé.
        for debut, duree, *_ in liste:
            with self.subTest(quand=debut.isoformat()):
                minute = debut.hour * 60 + debut.minute
                periode = ((9 * 60, 12 * 60) if debut.weekday() == 0
                           else (10 * 60, 13 * 60))
                self.assertGreaterEqual(minute, periode[0])
                self.assertLessEqual(minute + duree, periode[1])
                self.assertEqual((minute - periode[0]) % 20, 0)
        # Et la durée est un multiple du pas réglé, jamais 30 minutes écrites.
        self.assertEqual(sorted({d for _, d, *_ in liste}), [20, 40])

    def test_il_saute_les_jours_fermes(self):
        """Un jour férié ou un congé n'a pas de rendez-vous : le proposer
        aurait mis l'exemple en contradiction avec le planning."""
        maintenant = datetime.datetime(2026, 9, 1, 8, 30)
        preferences = generation.Preferences(None)
        horaires.definir_semaine(
            preferences, {jour: [(9 * 60, 12 * 60)] for jour in range(5)})
        horaires.ajouter_jour_ferme(preferences, "2026-09-07", "congé")
        liste = agenda_exemple.rendezvous(maintenant, preferences)
        self.assertTrue(liste)
        jours = {debut.date().isoformat() for debut, *_ in liste}
        self.assertNotIn("2026-09-07", jours)
        self.assertIn("2026-09-08", jours)             # le lendemain, lui, y est

    def test_sans_horaires_regles_c_est_un_repli_annonce(self):
        """⚠ ON NE DEVINE PAS LES HEURES OUVRÉES D'UN CABINET. Sans réglage, on
        prend les plages de repli — et `plan` le DIT, pour que l'écran puisse
        le dire aussi."""
        maintenant = datetime.datetime(2026, 9, 1, 8, 30)
        vide = generation.Preferences(None)
        for preferences in (None, vide):
            with self.subTest(preferences=preferences):
                detail = agenda_exemple.plan(maintenant, preferences)
                self.assertTrue(detail["repli"])
                self.assertEqual(detail["pas"], agenda_exemple.PAS_REPLI)
        horaires.definir_semaine(vide, {2: [(9 * 60, 12 * 60)]})
        self.assertFalse(agenda_exemple.plan(maintenant, vide)["repli"])

    def test_il_reste_des_places_libres_a_proposer(self):
        """⚠ UN AGENDA PLEIN À CRAQUER NE MONTRERAIT PAS LE PRODUIT : proposer
        une place libérée est ce qu'il sait faire de mieux. Une place sur deux
        est prise, et deux rendez-vous ne se chevauchent jamais."""
        maintenant = datetime.datetime(2026, 9, 1, 8, 30)
        preferences = generation.Preferences(None)
        horaires.definir_semaine(
            preferences, {jour: [(9 * 60, 12 * 60)] for jour in range(5)})
        preferences.definir(horaires.CLE_PAS, 30)
        liste = sorted(agenda_exemple.rendezvous(maintenant, preferences))
        par_jour = {}
        for debut, duree, *_ in liste:
            par_jour.setdefault(debut.date(), []).append((debut, duree))
        for jour, poses in par_jour.items():
            with self.subTest(jour=jour):
                # 6 créneaux de 30 min entre 9h et 12h, une place sur deux.
                self.assertLess(len(poses), 6)
                # Aucun chevauchement : la fin de l'un précède le début du
                # suivant.
                for (debut, duree), (apres, _) in zip(poses, poses[1:]):
                    self.assertLessEqual(
                        debut + datetime.timedelta(minutes=duree), apres)

    def test_il_part_de_maintenant_donc_il_ne_vieillit_pas(self):
        """⚠ LE POINT DE LA DEMANDE, mot pour mot : « peu importe le moment où
        l'on génère le jeu de données, ce soit toujours valable »."""
        for annee in (2026, 2027, 2030):
            with self.subTest(annee=annee):
                maintenant = datetime.datetime(annee, 2, 3, 9, 0)
                liste = agenda_exemple.rendezvous(maintenant)
                self.assertTrue(all(debut > maintenant for debut, *_ in liste))

    def test_il_est_deterministe_le_meme_jour(self):
        """Un exemple qui changerait à chaque ouverture serait impossible à
        décrire dans une documentation."""
        maintenant = datetime.datetime(2026, 9, 1, 8, 30)
        self.assertEqual(agenda_exemple.agenda_ics(maintenant),
                         agenda_exemple.agenda_ics(maintenant))
        self.assertNotEqual(
            agenda_exemple.agenda_ics(maintenant),
            agenda_exemple.agenda_ics(maintenant + datetime.timedelta(days=1)))

    def test_les_trois_familles_sont_disjointes(self):
        """⚠ LE DÉFAUT MESURÉ : la première version faisait paraître le même nom
        tantôt avec un numéro, tantôt sans, et lui donnait un numéro DIFFÉRENT
        à chaque rendez-vous. L'import créait alors huit fiches pour la même
        personne — cinq noms en huit exemplaires."""
        liste = agenda_exemple.rendezvous(datetime.datetime(2026, 9, 1, 8, 30))
        avec, sans = {}, set()
        for _, _, nom, _, telephone in liste:
            if telephone:
                avec.setdefault(nom, set()).add(telephone)
            else:
                sans.add(nom)
        self.assertTrue(avec)
        self.assertTrue(sans)
        # Personne n'est des deux côtés.
        self.assertEqual(set(avec) & sans, set())
        # Et UN SEUL numéro par personne.
        for nom, numeros in avec.items():
            with self.subTest(nom=nom):
                self.assertEqual(len(numeros), 1, numeros)

    def test_l_immense_majorite_des_gens_est_joignable(self):
        """⚠ LE DÉFAUT QUI A COÛTÉ QUATRE ALLERS-RETOURS AU PROPRIÉTAIRE
        (13/08/2026). Dans sa base réelle, l'agenda d'exemple avait posé 62
        personnes SANS numéro sur 81 : une campagne de créneau libéré n'y
        trouvait que 7 personnes, quel que soit le réglage — il a cherché
        quatre fois la cause dans les options, elle était dans l'exemple.

        Un contact sans numéro NE PEUT PAS ÊTRE APPELÉ. Le cas doit exister
        (l'écran « à compléter » est fait pour lui), mais il doit rester rare :
        un agenda d'exemple sert à faire tourner des campagnes.
        """
        liste = agenda_exemple.rendezvous(datetime.datetime(2026, 9, 1, 8, 30))
        gens = {}
        for _, _, nom, _, telephone in liste:
            gens[nom] = gens.get(nom) or telephone
        sans = [nom for nom, telephone in gens.items() if not telephone]
        # Le cas existe…
        self.assertTrue(sans)
        # … et il reste minoritaire : UNE PERSONNE SUR DIX est la règle (voir
        # `rang % 10` dans agenda_exemple), l'arrondi peut donner 10,1 %. On
        # borne à 12 % pour que l'essai mesure l'intention, pas la division.
        self.assertLessEqual(len(sans) * 100, len(gens) * 12, sans)
        # Et l'exemple offre de quoi remplir une campagne de trente appels.
        self.assertGreaterEqual(len(gens) - len(sans), 30)

    def test_une_personne_un_rendezvous(self):
        """⚠ SA DEMANDE DU 14/08/2026, mot pour mot : « il faut que ce soit une
        liste de noms uniquement, sinon les tests deviennent juste
        impossibles ». Mesuré avant : 643 rendez-vous pour 102 personnes — SIX
        rendez-vous par personne en moyenne, DIX-SEPT pour la plus servie. La
        même personne revenait dans la liste d'appel, dans le planning et dans
        le cahier, à des dates différentes : plus rien n'était suivable."""
        liste = agenda_exemple.rendezvous(datetime.datetime(2026, 9, 1, 8, 30))
        combien = collections.Counter(nom for _, _, nom, _, _ in liste)
        revenants = {nom: n for nom, n in combien.items() if n > 1}
        self.assertEqual(revenants, {}, "une personne = un rendez-vous")
        self.assertEqual(len(combien), len(liste))
        # Et les gens du carnet n'y font pas exception.
        carnet = {nom for nom, _ in agenda_exemple._deja_au_carnet()}
        for nom in carnet & set(combien):
            with self.subTest(nom=nom):
                self.assertEqual(combien[nom], 1)

    def test_aucun_nom_de_l_exemple_ne_porte_deux_numeros_en_base(self):
        """⚠ CE QUI ARRIVE QUAND DEUX LISTES D'IDENTITÉS S'IGNORENT : le jeu
        d'essai porte deux homonymes voulus, et les quatre contacts d'amorçage
        reprennent trois de ses noms sous un AUTRE numéro. L'exemple ne doit
        annoncer aucun de ces noms — sinon l'import crée une seconde fiche au
        même nom, exactement ce que cette famille démontre qu'on évite."""
        annonces = {nom for _, _, nom, _, telephone
                    in agenda_exemple.rendezvous(
                        datetime.datetime(2026, 9, 1, 8, 30)) if telephone}
        comptes = collections.Counter(nom for nom, _, _ in jeu_essai.CLIENTS)
        homonymes = {nom for nom, n in comptes.items() if n > 1}
        amorce = {nom for nom, _, _, _, _, _ in jeu_essai.PREMIERS_CONTACTS}
        self.assertEqual(annonces & homonymes, set())
        self.assertEqual(annonces & amorce, set())

    def test_tous_les_numeros_sont_reserves_a_la_fiction(self):
        """Les six racines de l'Arcep ne sont attribuées à personne : aucun de
        ces numéros ne peut sonner chez quelqu'un."""
        liste = agenda_exemple.rendezvous(datetime.datetime(2026, 9, 1, 8, 30))
        racines = tuple(r.replace(" ", "")
                        for r in jeu_essai.RACINES_FICTION)
        for _, _, _, _, telephone in liste:
            if not telephone:
                continue
            chiffres = "".join(c for c in telephone if c.isdigit())
            with self.subTest(telephone=telephone):
                self.assertTrue(chiffres.startswith(racines), chiffres)

    def test_aucun_numero_de_l_exemple_n_exige_une_issue_du_simulateur(self):
        """⚠ LE DÉFAUT QUI A ARRÊTÉ SA CAMPAGNE AU CINQUIÈME APPEL (14/08/2026).

        Le simulateur RÉSERVE les fins 51 à 59 : un numéro qui finit par là
        exige son issue, et « 59 » exige que l'agent ne rende rien de lisible —
        la campagne se met alors EN PAUSE, à dessein. En portant AVEC_NUMERO de
        8 à 30 noms, la formule « 40 + rang » s'est mise à traverser cette
        plage. Mesuré dans sa base : sur ses cinq premiers appels, un « 57 », un
        « 58 », un « 52 » et un « 59 » — cinq appels, une place pourvue, puis
        pause, là où il attendait trente appels.

        Ces fins-là restent à la main de celui qui essaie : il tape un numéro en
        59 quand il VEUT voir ce cas.
        """
        vus = set()
        for rang in range(800):
            numero = agenda_exemple._numero(rang)
            chiffres = "".join(c for c in numero if c.isdigit())
            with self.subTest(rang=rang):
                self.assertNotIn(chiffres[-2:],
                                 calle_client.TERMINAISONS_FORCEES)
                # ⚠ ET DIX CHIFFRES, TOUJOURS. L'ancienne formule débordait dès
                # le centième rang : elle écrivait trois chiffres là où il en
                # faut deux, et le numéro n'était plus composable.
                self.assertEqual(len(chiffres), 10, numero)
                # ⚠ ET JAMAIS DEUX PERSONNES SUR LE MÊME NUMÉRO : l'import en
                # ferait une seule fiche.
                self.assertNotIn(numero, vus)
                vus.add(numero)

    def test_l_exemple_ne_porte_jamais_les_trois_fins_qui_bloquent(self):
        """Les fins 57, 58 et 59 ne sont portées par AUCUN contact de
        démonstration, à dessein (voir l'entête de jeu_essai) : elles laissent
        une trace durable ou mettent la campagne en pause. L'agenda d'exemple
        doit tenir la même règle — 51 à 56 restent permises, ce sont celles que
        le jeu d'essai porte exprès pour montrer la variété des issues."""
        liste = agenda_exemple.rendezvous(datetime.datetime(2026, 9, 1, 8, 30))
        fins = {"".join(c for c in telephone if c.isdigit())[-2:]
                for _, _, _, _, telephone in liste if telephone}
        self.assertEqual(fins & {"57", "58", "59"}, set())

    def test_le_lecteur_du_produit_relit_son_propre_exemple(self):
        """⚠ SANS CET ESSAI, on livrerait un fichier que le produit refuse. Le
        même module lit les agendas des gens : ce qu'il ne sait pas relire ne
        vaut rien comme exemple."""
        texte = agenda_exemple.agenda_ics(datetime.datetime(2026, 9, 1, 8, 30))
        evenements, erreurs = ics.analyser_ics(texte)
        self.assertEqual(erreurs, [])
        self.assertEqual(len(evenements), texte.count("BEGIN:VEVENT"))
        for evenement in evenements:
            self.assertTrue(evenement["nom"])
            self.assertTrue(evenement["motif"])
            self.assertTrue(datetime.datetime.fromisoformat(
                evenement["horaire"]))
        # Les durées sont lues : DTEND est explicite.
        self.assertTrue(all(e["minutes"] for e in evenements))
        # Et les numéros annoncés sont retrouvés.
        avec_numero = sum(1 for e in evenements if e["telephone"])
        attendus = sum(1 for r in agenda_exemple.rendezvous(
            datetime.datetime(2026, 9, 1, 8, 30)) if r[4])
        self.assertEqual(avec_numero, attendus)

    def test_le_fichier_respecte_la_forme_icalendar(self):
        texte = agenda_exemple.agenda_ics(datetime.datetime(2026, 9, 1, 8, 30))
        self.assertTrue(texte.startswith("BEGIN:VCALENDAR\r\n"))
        self.assertTrue(texte.endswith("END:VCALENDAR\r\n"))
        self.assertIn("TZID:Europe/Paris", texte)
        self.assertEqual(texte.count("BEGIN:VEVENT"), texte.count("END:VEVENT"))
        # Les CRLF, partout : c'est ce que la norme demande.
        self.assertNotIn("\n\n", texte)
        for ligne in texte.split("\r\n"):
            self.assertNotIn("\n", ligne)


class TestAgendaExempleTelechargement(_TestAvecServeurWeb):
    """Le bouton de ⚙ Réglages → 🧪 Jeu d'essai, et ce qu'il sert."""

    def test_le_bouton_annonce_des_chiffres_calcules(self):
        """⚠ CALCULÉS, JAMAIS RECOPIÉS : un compte écrit à la main deviendrait
        faux au premier réglage du générateur, et l'écran annoncerait un
        fichier qui n'existe pas.

        ⚠ ET ILS NE PARAISSENT QUE DANS L'AIDE depuis le 10/08/2026 (demande du
        propriétaire : « trop d'informations »). La partie elle-même dit une
        phrase et porte un bouton.
        """
        zone = _zone_visible(self._obtenir("/reglages")[1])
        self.assertIn("Un agenda d'exemple à importer", zone)
        self.assertIn('action="/reglages/agenda-exemple.ics"', zone)
        # La phrase de la partie : courte, et sans aucun compte.
        # ⚠ </h3> depuis le 15/08/2026 : ce bloc vit DANS « Jeu d'essai », qui
        # porte déjà le <h2> de la sous-partie.
        partie = zone[zone.index('id="agenda-exemple"'):]
        phrase = partie[partie.index("</h3>"):partie.index("<form")]
        self.assertIn("calé sur vos heures d'ouverture", phrase)
        self.assertNotIn("rendez-vous", phrase)
        # Le bouton non plus ne porte plus de compte.
        self.assertIn("⬇ Télécharger l'agenda d'exemple</button>", zone)
        # Les chiffres, eux, sont dans l'aide — et calculés.
        attendu = len(agenda_exemple.rendezvous(
            preferences=self.application.preferences))
        self.assertIn(f"{attendu} rendez-vous</strong>", zone)
        self.assertRegex(zone, r"\d+ rendez-vous portent\s+un")
        # Et l'aide dit ce qu'est un fichier ICS.
        self.assertIn("iCalendar", zone)
        self.assertIn("Google&nbsp;Agenda", zone)

    def test_le_telechargement_sert_un_fichier_calendrier(self):
        adresse = self.racine + "/reglages/agenda-exemple.ics"
        with urllib.request.urlopen(adresse, timeout=20) as reponse:
            entetes = dict(reponse.headers)
            contenu = reponse.read().decode("utf-8")
        self.assertIn("text/calendar", entetes["Content-Type"])
        self.assertIn("agenda-exemple-ringback.ics",
                      entetes["Content-Disposition"])
        self.assertGreaterEqual(contenu.count("BEGIN:VEVENT"), 100)
        # ⚠ RIEN N'EST ÉCRIT SUR LE DISQUE : un fichier rangé vieillirait, et
        # c'est précisément ce qu'on cherche à éviter. On le prouve sur le
        # dossier de l'application, seul endroit où il pourrait atterrir.
        dossier = os.path.dirname(os.path.dirname(
            os.path.abspath(serveur.__file__)))
        self.assertFalse(os.path.exists(
            os.path.join(dossier, "agenda-exemple-ringback.ics")))
        self.assertFalse(os.path.exists(
            os.path.join(dossier, "donnees", "agenda-exemple-ringback.ics")))

    def test_le_fichier_telecharge_s_importe_sans_rejet_ni_doublon(self):
        """⚠ L'ESSAI QUI COMPTE : le produit doit avaler son propre exemple. Et
        sans créer plusieurs fiches pour la même personne — c'est le défaut
        mesuré à la première version."""
        base = self.application.base
        avant = base.conn.execute("SELECT COUNT(*) FROM rendezvous").fetchone()[0]
        adresse = self.racine + "/reglages/agenda-exemple.ics"
        with urllib.request.urlopen(adresse, timeout=20) as reponse:
            contenu = reponse.read().decode("utf-8")
        frontiere = "----essai-ics"
        corps = (f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="fichier"; '
                 'filename="agenda.ics"\r\n'
                 "Content-Type: text/calendar\r\n\r\n"
                 f"{contenu}\r\n--{frontiere}--\r\n").encode("utf-8")
        requete = urllib.request.Request(
            self.racine + "/importer-ics", data=corps,
            headers={"Content-Type":
                     f"multipart/form-data; boundary={frontiere}"})
        with urllib.request.urlopen(requete, timeout=60) as reponse:
            page = reponse.read().decode("utf-8")
            arrivee = reponse.geturl()
        # ⚠ ON REVIENT SUR L'AGENDA (10/08/2026) : l'import se fait POUR remplir
        # le planning, et c'est le planning qu'on veut voir ensuite. Le compte
        # rendu s'affiche en tête, et son jeton ne porte AUCUN nom.
        self.assertIn("/suivi?import=", arrivee)
        self.assertIn('<section id="planning">', page)
        self.assertIn(f"<strong>{contenu.count('BEGIN:VEVENT')}</strong> "
                      "rendez-vous importé(s)", page)
        self.assertNotIn("rejetée", page)
        apres = base.conn.execute("SELECT COUNT(*) FROM rendezvous").fetchone()[0]
        self.assertEqual(apres - avant, contenu.count("BEGIN:VEVENT"))
        # AUCUN nom en double, et un seul numéro par nom.
        doubles = base.conn.execute(
            "SELECT nom, COUNT(*) c FROM clients GROUP BY nom "
            "HAVING c > 1").fetchall()
        self.assertEqual([(r["nom"], r["c"]) for r in doubles], [])
        multi = base.conn.execute(
            "SELECT nom, COUNT(DISTINCT telephone) n FROM clients "
            "GROUP BY nom HAVING n > 1").fetchall()
        self.assertEqual([(r["nom"], r["n"]) for r in multi], [])
        # Ceux sans numéro sont annoncés, avec le lien qui sert à les compléter.
        self.assertIn("rendez-vous sans numéro — à compléter", page)
        self.assertIn('href="/sans-numero"', page)


class TestRenvoiReglage(unittest.TestCase):
    """Le réglage « toujours utiliser MON numéro » : lecture, écriture, refus.

    ⚠ IL NE SE CONFOND PAS AVEC LES TESTEURS. Un testeur fait qu'une FICHE
    porte son numéro (la base change, l'écran le marque 🧪) ; le renvoi ne
    touche aucune fiche et ne change que le numéro COMPOSÉ. Confondre les deux
    mènerait droit à un appel chez un vrai client.
    """

    def setUp(self):
        self.preferences = generation.Preferences(None)

    def test_rien_de_regle_aucun_renvoi(self):
        self.assertEqual(essai_reel.numero_impose(self.preferences), "")
        etat = essai_reel.etat_du_renvoi(self.preferences)
        self.assertFalse(etat["actif"])
        self.assertFalse(etat["incoherent"])
        self.assertEqual(etat["masque"], "")

    def test_cochee_avec_un_numero_le_renvoi_est_actif_et_masque(self):
        essai_reel.enregistrer_renvoi(self.preferences, True, "06 39 98 00 24")
        self.assertEqual(essai_reel.numero_impose(self.preferences),
                         "06 39 98 00 24")
        etat = essai_reel.etat_du_renvoi(self.preferences)
        self.assertTrue(etat["actif"])
        self.assertEqual(etat["masque"], "06 39 •• •• 24")

    def test_la_case_seule_est_refusee_et_rien_n_est_enregistre(self):
        """⚠ SINON RINGBACK APPELLERAIT LES VRAIS CONTACTS — exactement ce que
        la case promet d'empêcher."""
        with self.assertRaises(saisie.SaisieInvalide) as refus:
            essai_reel.enregistrer_renvoi(self.preferences, True, "")
        self.assertIn("donnez un numéro", str(refus.exception))
        self.assertFalse(self.preferences.obtenir(essai_reel.CLE_IMPOSER_NUMERO))
        self.assertEqual(essai_reel.numero_impose(self.preferences), "")

    def test_decocher_ne_perd_pas_le_numero(self):
        """Le champ est TOUJOURS vide à l'écran (un numéro ne se réaffiche
        pas) : si décocher effaçait le numéro, il faudrait le retaper à chaque
        fois qu'on reprend un essai."""
        essai_reel.enregistrer_renvoi(self.preferences, True, "06 39 98 00 24")
        essai_reel.enregistrer_renvoi(self.preferences, False, "")
        self.assertEqual(essai_reel.numero_impose(self.preferences), "")
        self.assertEqual(essai_reel.numero_range(self.preferences),
                         "06 39 98 00 24")
        essai_reel.enregistrer_renvoi(self.preferences, True, "")  # on recoche
        self.assertEqual(essai_reel.numero_impose(self.preferences),
                         "06 39 98 00 24")

    def test_un_numero_illisible_est_refuse_meme_case_decochee(self):
        """La faute de frappe doit se voir tout de suite, pas le jour où l'on
        cochera — ce jour-là, on croirait le réglage prêt."""
        with self.assertRaises(saisie.SaisieInvalide):
            essai_reel.enregistrer_renvoi(self.preferences, False, "06 12 34")
        self.assertEqual(essai_reel.numero_range(self.preferences), "")

    def test_retirer_arrete_le_renvoi_et_efface_le_numero(self):
        essai_reel.enregistrer_renvoi(self.preferences, True, "06 39 98 00 24")
        self.assertEqual(essai_reel.retirer_renvoi(self.preferences),
                         "06 39 98 00 24")
        self.assertEqual(essai_reel.numero_range(self.preferences), "")
        self.assertFalse(essai_reel.etat_du_renvoi(self.preferences)["coche"])

    def test_un_reglage_bricole_a_la_main_est_dit_incoherent(self):
        """On n'y arrive qu'en modifiant donnees/preferences.json à la main.
        L'écran le dit quand même : le mode réel, lui, refusera d'appeler."""
        self.preferences.definir(essai_reel.CLE_IMPOSER_NUMERO, True)
        self.preferences.definir(essai_reel.CLE_NUMERO_IMPOSE, "pas-un-numéro")
        etat = essai_reel.etat_du_renvoi(self.preferences)
        self.assertTrue(etat["incoherent"])
        self.assertFalse(etat["actif"])
        # ⚠ ET LE NUMÉRO EST QUAND MÊME RENDU au client d'appels : c'est lui
        # qui refuse. Rendre "" ici ferait appeler le contact.
        self.assertEqual(essai_reel.numero_impose(self.preferences),
                         "pas-un-numéro")

    def test_composable_ecarte_ce_qui_n_est_pas_un_numero(self):
        for bon in ("06 39 98 00 24", "+33639980024", "0639980024"):
            with self.subTest(numero=bon):
                self.assertTrue(calle_client.numero_composable(bon))
        for mauvais in ("", "06 12 34", "https://api.exemple.fr", "moi", "+33"):
            with self.subTest(numero=mauvais):
                self.assertFalse(calle_client.numero_composable(mauvais))


class TestReglagesEssaisEnTroisParties(_TestAvecServeurWeb):
    """⚙ Réglages → 🧪 Essais : trois parties, un « ? » chacune.

    ⚠ DEMANDE DU PROPRIÉTAIRE, 10/08/2026 : « trop d'informations, mais là au
    lieu de le supprimer tu fais trois parties […] avec un bouton "?" ». Le
    principe qu'on garde : l'écran va droit au but, l'explication attend qu'on
    la demande — et elle reste À CÔTÉ de ce qu'elle explique.
    """

    def test_les_parties_sont_dans_le_menu(self):
        _, page = self._obtenir("/reglages")
        for code, libelle in (("jeu-essai", "Jeu d&#x27;essai"),
                              ("renvoi-essai", "Toujours mon numéro")):
            with self.subTest(partie=code):
                # La section, et son entrée de menu (les codes SONT les ancres).
                self.assertIn(f'id="section-{code}"', page)
                self.assertIn(f'data-section="{code}"', page)
                self.assertIn(libelle, page)

    def test_l_agenda_d_exemple_est_DANS_le_jeu_d_essai(self):
        """⚠ SA DEMANDE DU 15/08/2026 : « mettre Agenda d'exemple dans Jeu
        d'essai ». Les deux fabriquent la même chose — de quoi essayer sans
        toucher aux vraies données — et les séparer obligeait à chercher dans
        deux sous-parties ce qui se fait d'un même geste.
        """
        _, page = self._obtenir("/reglages")
        # Plus de sous-partie à lui : ni section, ni entrée de menu.
        self.assertNotIn('id="section-agenda-exemple"', page)
        self.assertNotIn('data-section="agenda-exemple"', page)
        # Mais son contenu est bien là, DANS la section du jeu d'essai, et un
        # cran plus bas dans la hiérarchie (h3 sous le h2 de la sous-partie).
        zone = _zone_visible(page)
        debut = zone.index('id="section-jeu-essai"')
        section = zone[debut:]
        self.assertIn('<h3 id="agenda-exemple"', section)
        self.assertIn('action="/reglages/agenda-exemple.ics"', section)

    def test_chaque_partie_porte_son_aide_repliee(self):
        """⚠ REPLIÉE : un <details> sans « open ». Ouverte d'office, elle
        rendrait l'écran exactement aussi bavard qu'avant."""
        zone = _zone_visible(self._obtenir("/reglages")[1])
        aides = re.findall(r'<details class="aide"( open)?><summary '
                           r'title="([^"]+)"', zone)
        titres = [titre for _, titre in aides]
        self.assertIn("À quoi sert le jeu d&#x27;essai ?", titres)
        self.assertTrue(any("fichier ICS" in titre for titre in titres))
        self.assertIn("Que fait ce renvoi ?", titres)
        # AUCUNE n'est ouverte d'office.
        self.assertEqual([ouvert for ouvert, _ in aides if ouvert], [])

    def test_le_jeu_d_essai_ne_recite_plus_son_contenu(self):
        """« Pas de chiffre, de nombre de rendez-vous etc. » — la partie dit ce
        que c'est, en une phrase. Le détail est dans l'aide."""
        zone = _zone_visible(self._obtenir("/reglages")[1])
        partie = zone[zone.index('id="jeu-essai"'):]
        phrase = partie[partie.index("</h2>") + 5:partie.index("<form")]
        self.assertIn("complète votre agenda et vos contacts", phrase)
        self.assertNotRegex(phrase, r"\d")
        # Ce qui a quitté l'écran principal.
        for parti in ("racines que l'Arcep", "ne plus\nappeler »",
                      "sans numéro.</p>"):
            with self.subTest(parti=parti):
                self.assertNotIn(parti, phrase)
        # Mais l'aide, elle, le dit toujours.
        self.assertIn("l'Arcep réserve aux œuvres", zone)
        self.assertIn("additif", zone)


class TestRenvoiEcran(_TestAvecServeurWeb):
    """⚙ Réglages → 🧪 Essais → Jeu d'essai : la case, le champ, et l'honnêteté.

    ⚠ CE QUI SE VÉRIFIE ICI N'EST PAS LE FORMULAIRE, C'EST CE QUE DIT L'ÉCRAN.
    Un renvoi actif qui ne se voit pas ferait relire une campagne entière en
    croyant avoir appelé de vrais contacts — ou l'inverse.
    """

    NUMERO = "06 39 98 00 24"

    def _en_mode_reel(self):
        self.application.mode_reel = True
        self.addCleanup(setattr, self.application, "mode_reel", False)

    def test_la_case_et_le_champ_sont_la_avec_ce_qu_ils_font(self):
        """⚠ ALLÉGÉ LE 10/08/2026 (demande du propriétaire) : la partie porte
        son titre, la case, le champ — et un « ? » qui dit ce que fait le
        renvoi. Le reste (comparaison avec les testeurs, rappel des verrous,
        conséquence sur les fiches) a quitté l'écran ; il reste écrit dans
        PROCEDURE-ESSAI-REEL.md et dans le README.
        """
        zone = _zone_visible(self._obtenir("/reglages")[1])
        self.assertIn("Toujours utiliser mon numéro de téléphone pour les "
                      "essais", zone)
        self.assertIn('action="/reglages/renvoi-essai"', zone)
        self.assertIn('name="imposer" value="1"', zone)
        self.assertIn('name="numero"', zone)
        # Le « ? » porte le premier paragraphe, et lui seul.
        self.assertIn("Que fait ce renvoi ?", zone)
        self.assertIn("remplacer le numéro de chaque contact", zone)
        self.assertIn("l'identité ne change pas d'un mot", zone)
        for parti in ("aucun verrou", "Ne le confondez pas",
                      "sera écrit sur la"):
            with self.subTest(parti=parti):
                self.assertNotIn(parti, zone)
        # La case suit l'idiome du produit : elle n'est pas pleine largeur.
        self.assertIn('<div class="ligne-option"><label class="option">', zone)

    def test_enregistre_le_renvoi_est_dit_sur_toutes_les_pages(self):
        _, page = self._poster("/reglages/renvoi-essai",
                               {"imposer": "1", "numero": self.NUMERO})
        self.assertIn("Renvoi actif", page)
        self.assertIn("06 39 •• •• 24", page)
        # ⚠ LE NUMÉRO NE SE RÉAFFICHE JAMAIS EN CLAIR, même le sien : un écran
        # finit toujours par être photographié.
        self.assertNotIn(self.NUMERO, page)
        self.assertNotIn('value="06 39', page)
        # En simulation, le bandeau se tait : aucun numéro n'est composé.
        self.assertNotIn("TOUS LES APPELS SONT RENVOYÉS",
                         _zone_visible(self._obtenir("/")[1]))
        self._en_mode_reel()
        # LES CINQ ONGLETS, sans exception : c'est la seule façon d'être sûr
        # qu'aucune page ne laisse croire à un mode réel ordinaire.
        for _, chemin, _ in serveur.ONGLETS:
            with self.subTest(page=chemin):
                zone = _zone_visible(self._obtenir(chemin)[1])
                self.assertIn("TOUS LES APPELS SONT RENVOYÉS", zone)
                self.assertIn("aucun contact ne sera appelé", zone)
                self.assertIn("06 39 •• •• 24", zone)

    def test_toute_page_d_ou_un_appel_part_porte_le_bandeau(self):
        """⚠ LE RENVOI NE SE VOIT QUE PAR LE BANDEAU, et chaque page insère le
        sien — il n'y a pas de point de passage unique. Une page d'où un appel
        peut partir sans bandeau annoncerait un mode réel ORDINAIRE alors que
        tous les appels sont renvoyés (ou l'inverse) : c'est exactement le
        malentendu qu'on ne peut pas rattraper après coup.
        """
        source = inspect.getsource(serveur.Gestionnaire)
        morceaux = re.split(r"(?m)^    def (\w+)", source)
        depart = re.compile(r"_libelle_rappel|/executer|RÉELLEMENT|Démarrer")
        examinees, manquantes = [], []
        for indice in range(1, len(morceaux), 2):
            nom, corps = morceaux[indice], morceaux[indice + 1]
            if not nom.startswith("_page_") or "self._page(" not in corps:
                continue
            if not depart.search(corps):
                continue
            examinees.append(nom)
            if "_bandeau()" not in corps:
                manquantes.append(nom)
        self.assertEqual(manquantes, [])
        # ⚠ ET LE GARDE-FOU DOIT AVOIR TROUVÉ QUELQUE CHOSE À GARDER : un motif
        # qui ne correspondrait plus à rien passerait vert sans rien vérifier.
        self.assertGreaterEqual(len(examinees), 5, examinees)

    def test_la_case_seule_est_refusee_sans_rien_enregistrer(self):
        with self.assertRaises(urllib.error.HTTPError) as refus:
            self._poster("/reglages/renvoi-essai", {"imposer": "1"})
        self.assertEqual(refus.exception.code, 400)
        self.assertIn("donnez un numéro",
                      refus.exception.read().decode("utf-8"))
        self.assertEqual(
            essai_reel.numero_impose(self.application.preferences), "")

    def test_une_saisie_refusee_revient_dans_son_champ(self):
        """Sans JavaScript la page revient avec le message ; avec, c'est le
        seul bloc qui revient — et la saisie avec lui."""
        _, fragment = self._poster("/reglages/renvoi-essai",
                                   {"imposer": "1", "numero": "06 12 34",
                                    "fragment": "1"})
        self.assertIn("Réglage refusé", fragment)
        self.assertIn('value="06 12 34"', fragment)
        self.assertIn("checked", fragment)      # la case reste comme on l'a mise

    def test_retirer_mon_numero(self):
        self._poster("/reglages/renvoi-essai",
                     {"imposer": "1", "numero": self.NUMERO})
        _, page = self._poster("/reglages/renvoi-essai", {"action": "retirer"})
        self.assertIn("Aucun numéro d'essai enregistré", page)
        self.assertEqual(
            essai_reel.numero_impose(self.application.preferences), "")

    def test_la_campagne_d_essai_dit_le_renvoi(self):
        """L'endroit où l'on prépare de vrais appels doit répondre à « qui va
        sonner ? » sans qu'on aille le chercher ailleurs.

        ⚠ LA PARTIE 🔌 CALL-E NE LE DIT PLUS (10/08/2026) : elle ne porte plus
        que la clé, sur demande du propriétaire. Le renvoi se lit dans SA partie,
        dans celle de la campagne d'essai, sur le bandeau de chaque page en mode
        réel, et en console avant l'invite APPELER.
        """
        self._poster("/reglages/renvoi-essai",
                     {"imposer": "1", "numero": self.NUMERO})
        zone = _zone_visible(self._obtenir("/reglages")[1])
        self.assertIn("Le renvoi d'essai est actif", zone)
        self.assertIn("Renvoi actif", zone)

    def test_un_reglage_bricole_a_la_main_est_crie_partout(self):
        preferences = self.application.preferences
        preferences.definir(essai_reel.CLE_IMPOSER_NUMERO, True)
        preferences.definir(essai_reel.CLE_NUMERO_IMPOSE, "pas-un-numéro")
        self.assertIn("n'est pas un numéro",
                      _zone_visible(self._obtenir("/reglages")[1]))
        self._en_mode_reel()
        self.assertIn("AUCUN APPEL NE PEUT PARTIR",
                      _zone_visible(self._obtenir("/")[1]))

    def test_le_client_reel_du_serveur_lit_le_reglage_a_chaque_appel(self):
        """⚠ LE CÂBLAGE, ÉPROUVÉ POUR LUI-MÊME : un réglage juste et un client
        qui ne le lit pas, c'est un écran qui promet ce qui n'arrivera pas."""
        essai_reel.enregistrer_renvoi(self.application.preferences, True,
                                      self.NUMERO)
        client = calle_client.AppelReel(
            cle_api="cle-de-test-0123456789",
            chemin_audit=os.path.join(tempfile.mkdtemp(), "audit.jsonl"),
            numero_impose=lambda: essai_reel.numero_impose(
                self.application.preferences))
        self.assertEqual(client._numero_impose(), self.NUMERO)
        essai_reel.retirer_renvoi(self.application.preferences)
        self.assertEqual(client._numero_impose(), "")


class TestConsoleEtCheminDesReglages(unittest.TestCase):
    """Le chemin du fichier de réglages, et ce que la console annonce.

    ⚠ UN SEUL CALCUL DE CHEMIN, pour deux lecteurs. La console lit le réglage
    AVANT que l'Application n'existe : deux calculs qui divergeraient feraient
    annoncer un renvoi qui n'est pas celui qui s'appliquera — au moment précis
    où l'opérateur décide de laisser partir de vrais appels.
    """

    class _Tampon:
        """De quoi lire ce qui est imprimé, sans importer io pour si peu."""

        def __init__(self):
            self.texte = ""

        def write(self, morceau):
            self.texte += morceau
            return len(morceau)

        def flush(self):
            pass

    def setUp(self):
        self.dossier = tempfile.mkdtemp(prefix="ringback-console-")
        self.addCleanup(shutil.rmtree, self.dossier, ignore_errors=True)
        self.chemin_base = os.path.join(self.dossier, "ringback.db")

    def test_un_seul_calcul_du_chemin_des_reglages(self):
        application = serveur.Application(self.chemin_base)
        self.addCleanup(application.base.fermer)
        self.assertEqual(application.preferences.chemin,
                         serveur.chemin_preferences(self.chemin_base))
        self.assertIsNone(serveur.chemin_preferences(":memory:"))

    def _confirmer(self, reponse="APPELER"):
        """Joue le verrou 3 en console ; rend (accepté ?, ce qui s'est imprimé)."""
        import builtins
        tampon = self._Tampon()
        sauve_input, sauve_sortie = builtins.input, sys.stdout
        builtins.input = lambda *arguments: reponse
        sys.stdout = tampon
        try:
            accepte = serveur._confirmation_tapee()
        finally:
            builtins.input, sys.stdout = sauve_input, sauve_sortie
        return accepte, tampon.texte


    def test_le_verrou_accepte_les_deux_mots_et_parle_les_deux_langues(self):
        """⚠ SA DEMANDE DU 04/09/2026 : « peu importe d'où tu viens ».

        Le message était entièrement en français, y compris l'avertissement
        sur le renvoi d'essai — un membre du jury anglophone lisait « Taper
        exactement APPELER » et ne savait pas quoi faire. La console tourne
        AVANT l'application : on ne peut pas s'appuyer sur le réglage de
        langue, qu'il n'a peut-être jamais ouvert.
        """
        sauve = serveur.CHEMIN_BASE
        serveur.CHEMIN_BASE = self.chemin_base
        self.addCleanup(setattr, serveur, "CHEMIN_BASE", sauve)

        accepte, imprime = self._confirmer("APPELER")
        self.assertTrue(accepte)
        # ⚠ LES DEUX LANGUES, CÔTE À CÔTE, dans l'avertissement ET la question.
        self.assertIn("Les appels partiront VRAIMENT", imprime)
        self.assertIn("Calls will REALLY be placed", imprime)

        for mot in ("CALL", "call", "appeler", "  CALL  "):
            with self.subTest(mot=mot):
                self.assertTrue(self._confirmer(mot)[0],
                                f"« {mot} » devrait être accepté")
        for mot in ("", "oui", "yes", "APPELE", "CALLS"):
            with self.subTest(mot=mot):
                self.assertFalse(self._confirmer(mot)[0],
                                 f"« {mot} » ne devrait PAS être accepté")

    def test_la_console_annonce_le_renvoi_avant_la_question(self):
        sauve = serveur.CHEMIN_BASE
        serveur.CHEMIN_BASE = self.chemin_base
        self.addCleanup(setattr, serveur, "CHEMIN_BASE", sauve)
        preferences = generation.Preferences(
            serveur.chemin_preferences(self.chemin_base))
        # Sans renvoi, la console ne dit rien de plus qu'avant.
        accepte, sortie = self._confirmer()
        self.assertTrue(accepte)
        self.assertNotIn("RENVOI", sortie)
        essai_reel.enregistrer_renvoi(preferences, True, "06 39 98 00 24")
        _, sortie = self._confirmer()
        self.assertIn("RENVOI D'ESSAI ACTIF", sortie)
        self.assertIn("06 39 •• •• 24", sortie)          # masqué, comme partout
        self.assertNotIn("06 39 98 00 24", sortie)
        # Un réglage bricolé à la main le dit aussi : aucun appel ne partira.
        preferences.definir(essai_reel.CLE_NUMERO_IMPOSE, "pas-un-numéro")
        _, sortie = self._confirmer()
        self.assertIn("AUCUN appel ne pourra partir", sortie)


class TestImportQuiRemplace(unittest.TestCase):
    """Un rendez-vous importé prend la place de celui qui l'occupait.

    ⚠ DEMANDE DU PROPRIÉTAIRE, 10/08/2026 : « dans tous les cas, les nouveaux
    créneaux de l'import remplacent les anciens (pas de superposition de
    rendez-vous possible) ».

    ⚠ RIEN N'EST EFFACÉ, et la règle n'est pas récrite : c'est
    `horaires.decision_annulation` — celle du retrait à la main, tenue en un
    seul endroit depuis le 31/07 — qui décide « annulé » (date passée) ou
    « supprimé » (date à venir). Les deux rendent la place ; aucun des deux ne
    perd la trace.
    """

    def setUp(self):
        self.dossier = tempfile.mkdtemp(prefix="ringback-remplace-")
        self.addCleanup(shutil.rmtree, self.dossier, ignore_errors=True)
        self.base = db.Base(os.path.join(self.dossier, "essai.db"))
        self.addCleanup(self.base.fermer)
        self.preferences = generation.Preferences(None)
        self.preferences.definir(horaires.CLE_PAS, 30)
        horaires.definir_semaine(
            self.preferences, {jour: [(9 * 60, 18 * 60)] for jour in range(7)})
        self.jour = (datetime.datetime.now()
                     + datetime.timedelta(days=4)).replace(
                         hour=9, minute=0, second=0, microsecond=0)

    def _poser(self, nom, minutes_apres=0, tranches=1, numero="+33 6 00 00 00 11"):
        client = self.base.ajouter_client(nom, numero)
        quand = self.jour + datetime.timedelta(minutes=minutes_apres)
        return self.base.ajouter_rendezvous(
            client, quand.isoformat(timespec="minutes"), "Ancien",
            duree_tranches=tranches)

    def _ics(self, *evenements):
        lignes = ["BEGIN:VCALENDAR", "VERSION:2.0"]
        for rang, (nom, minutes_apres, minutes) in enumerate(evenements, start=1):
            debut = self.jour + datetime.timedelta(minutes=minutes_apres)
            fin = debut + datetime.timedelta(minutes=minutes)
            lignes += ["BEGIN:VEVENT", f"UID:essai-{rang}",
                       f"DTSTART:{debut:%Y%m%dT%H%M%S}",
                       f"DTEND:{fin:%Y%m%dT%H%M%S}",
                       f"SUMMARY:{nom} — Importé", "END:VEVENT"]
        lignes.append("END:VCALENDAR")
        return "\r\n".join(lignes) + "\r\n"

    def _statut(self, rendezvous_id):
        return self.base.obtenir_rendezvous(rendezvous_id)["statut"]

    def test_l_importe_prend_la_place_de_l_ancien(self):
        ancien = self._poser("Mme Ancienne")
        bilan = {}
        importes, erreurs = ics.importer_ics(
            self.base, self._ics(("Mme Nouvelle", 0, 30)), self.preferences,
            bilan=bilan)
        self.assertEqual((importes, erreurs), (1, []))
        self.assertEqual(self._statut(ancien), db.STATUT_SUPPRIME)
        # Le bilan NOMME qui a été déplacé : sans le nom, l'écran ne pourrait
        # pas le dire, et un import viderait une journée en silence.
        self.assertEqual([r["nom"] for r in bilan["remplaces"]],
                         ["Mme Ancienne"])
        self.assertEqual(bilan["remplaces"][0]["statut_pose"],
                         db.STATUT_SUPPRIME)

    def test_le_chevauchement_compte_pas_seulement_l_heure_pile(self):
        """⚠ « PAS DE SUPERPOSITION POSSIBLE » : un rendez-vous d'une heure est
        déplacé par un importé qui commence en son milieu. Comparer les heures
        de début aurait laissé les deux en place, l'un sur l'autre."""
        ancien = self._poser("Mme Longue", tranches=2)      # 9h00 → 10h00
        ics.importer_ics(self.base, self._ics(("M. Milieu", 30, 30)),
                         self.preferences)                   # 9h30 → 10h00
        self.assertEqual(self._statut(ancien), db.STATUT_SUPPRIME)
        # Et plus aucune superposition ne reste au planning.
        occupants = self.base.rendezvous_occupants(
            self.jour.isoformat(timespec="minutes"),
            (self.jour + datetime.timedelta(days=1)).isoformat(
                timespec="minutes"))
        self.assertEqual(len(occupants), 1)

    def test_un_voisin_qui_ne_chevauche_pas_ne_bouge_pas(self):
        """Le remplacement ne déborde pas : la place d'à côté est intacte."""
        voisin = self._poser("M. Voisin", minutes_apres=60)  # 10h00
        ics.importer_ics(self.base, self._ics(("Mme Nouvelle", 0, 30)),
                         self.preferences)                    # 9h00 → 9h30
        self.assertEqual(self._statut(voisin), "prévu")

    def test_un_rendez_vous_passe_devient_annule_pas_supprime(self):
        """La règle du 31/07, tenue en un seul endroit : « annulé, c'est pour
        les dates passées »."""
        self.jour = (datetime.datetime.now()
                     - datetime.timedelta(days=3)).replace(
                         hour=9, minute=0, second=0, microsecond=0)
        ancien = self._poser("M. Passé")
        ics.importer_ics(self.base, self._ics(("Mme Nouvelle", 0, 30)),
                         self.preferences)
        self.assertEqual(self._statut(ancien), "annulé")

    def test_remplacer_entierement_vide_l_a_venir_et_garde_le_passe(self):
        futur = self._poser("M. Futur")
        self.jour = (datetime.datetime.now()
                     - datetime.timedelta(days=5)).replace(
                         hour=9, minute=0, second=0, microsecond=0)
        passe = self._poser("Mme Passée")
        self.base.mettre_a_jour_rendezvous(passe, statut="confirmé")
        self.jour = (datetime.datetime.now()
                     + datetime.timedelta(days=10)).replace(
                         hour=9, minute=0, second=0, microsecond=0)
        bilan = {}
        ics.importer_ics(self.base, self._ics(("M. Tout Neuf", 0, 30)),
                         self.preferences, remplacer_tout=True, bilan=bilan)
        self.assertEqual(self._statut(futur), db.STATUT_SUPPRIME)
        # ⚠ LE PASSÉ N'EST PAS TOUCHÉ : un import ne récrit pas l'histoire.
        self.assertEqual(self._statut(passe), "confirmé")
        self.assertEqual([r["nom"] for r in bilan["vides"]], ["M. Futur"])

    def test_sans_la_case_l_agenda_n_est_pas_vide(self):
        ailleurs = self._poser("M. Ailleurs", minutes_apres=180)
        ics.importer_ics(self.base, self._ics(("Mme Nouvelle", 0, 30)),
                         self.preferences)
        self.assertEqual(self._statut(ailleurs), "prévu")

    def test_le_csv_remplace_aussi(self):
        """La règle dit « dans tous les cas » : le CSV suit la même."""
        ancien = self._poser("Mme Ancienne")
        quand = self.jour.strftime("%Y-%m-%d %H:%M")
        contenu = ("nom;telephone;date_heure;motif\n"
                   f"Mme Nouvelle;+33 6 00 00 00 22;{quand};Importée\n")
        bilan = {}
        importes, erreurs = saisie.importer_csv(
            self.base, contenu, self.preferences, bilan)
        self.assertEqual((importes, erreurs), (1, []))
        self.assertEqual(self._statut(ancien), db.STATUT_SUPPRIME)
        self.assertEqual([r["nom"] for r in bilan["remplaces"]],
                         ["Mme Ancienne"])

    def test_rien_n_est_efface(self):
        """⚠ LA GARANTIE QUI COMPTE. Un rendez-vous déplacé reste lisible :
        c'est ce qui distingue « remplacer » de « perdre »."""
        ancien = self._poser("Mme Ancienne")
        ics.importer_ics(self.base, self._ics(("Mme Nouvelle", 0, 30)),
                         self.preferences)
        noms = [r["nom"] for r in self.base.tous_les_rendezvous()]
        self.assertIn("Mme Ancienne", noms)
        self.assertIn("Mme Nouvelle", noms)
        self.assertIsNotNone(self.base.obtenir_rendezvous(ancien))


class TestPageRendezVousAllegee(_TestAvecServeurWeb):
    """La page Rendez-vous après le 10/08/2026 : le planning, et l'import.

    ⚠ CE QUI COMPTE ICI N'EST PAS CE QUI A DISPARU, mais que ce qui reste
    suffise : le planning montre les rendez-vous, et une liste complète est à
    UN clic. Sans ce lien, la page ne mènerait plus à aucune liste.
    """

    def test_la_page_ne_garde_que_le_planning_et_l_import(self):
        zone = _zone_visible(self._obtenir("/suivi")[1])
        self.assertIn('<section id="planning">', zone)
        self.assertIn("＋ Importer votre agenda", zone)
        self.assertIn('href="/tous"', zone)
        for retiree in ("À contacter à la main", "Rendez-vous à venir"):
            with self.subTest(retiree=retiree):
                self.assertNotIn(retiree, zone)
        # ⚠ « Sans glisser » EST REVENU le même jour, REPLIÉ derrière son
        # intitulé (demande du propriétaire) : il ne coûte plus qu'une ligne à
        # l'écran, et il reste le seul chemin sans souris vers la fenêtre de
        # plage. Voir TestSelectionnerUnePlageDuPlanning.
        self.assertIn("Saisie manuelle des créneaux", zone)
        self.assertNotIn('<details class="repli-geste" open', zone)

    def test_le_lien_d_import_est_juste_sous_le_planning(self):
        """« Déplacer juste en dessous du tableau le lien » — la suite du
        regard, et le seul texte que la page porte encore."""
        zone = _zone_visible(self._obtenir("/suivi")[1])
        apres = zone[zone.index("</section>"):]
        self.assertIn("＋ Importer votre agenda", apres)
        # Rien entre la grille et lui.
        avant_lien = apres[:apres.index("＋ Importer votre agenda")]
        self.assertNotIn("<table", avant_lien)
        self.assertNotIn("<h2", avant_lien)

    def test_la_fenetre_d_import_ne_porte_que_les_deux_imports(self):
        code, fenetre = self._obtenir("/suivi/importer")
        self.assertEqual(code, 200)
        self.assertIn("Importer un fichier CSV", fenetre)
        self.assertIn("Importer un agenda (fichier ICS)", fenetre)
        self.assertIn('action="/importer"', fenetre)
        self.assertIn('action="/importer-ics"', fenetre)
        # La case de remplacement total, et l'avertissement — mot pour mot.
        self.assertIn('name="remplacer_tout"', fenetre)
        self.assertIn("Remplacer entièrement l'agenda", fenetre)
        self.assertIn(html.escape(serveur.AVERTISSEMENT_IMPORT), fenetre)
        # ⚠ ET RIEN D'AUTRE : pas le formulaire d'ajout à la main.
        self.assertNotIn('name="motif"', fenetre)

    def test_l_avertissement_est_le_meme_sur_la_page_de_repli(self):
        """Sans JavaScript, le lien mène à « /ajouter » : le même texte doit y
        être, sinon on aurait deux vérités selon le chemin pris."""
        _, page = self._obtenir("/ajouter")
        self.assertIn(html.escape(serveur.AVERTISSEMENT_IMPORT), page)
        self.assertIn("Remplacer entièrement l'agenda", page)
        # Et le formulaire à la main, lui, y est TOUJOURS.
        self.assertIn('name="motif"', page)

    def test_la_fenetre_d_ajout_arrive_preremplie_du_creneau(self):
        """⚠ TOUT L'INTÉRÊT D'OUVRIR CE FORMULAIRE DEPUIS UNE PLACE LIBRE :
        la date et l'heure sont déjà là. Les retaper aurait été une corvée, et
        une source d'erreur de plus."""
        creneau = "2026-09-07T09:30"
        code, fenetre = self._obtenir(
            "/suivi/ajout?creneau=" + urllib.parse.quote(creneau))
        self.assertEqual(code, 200)
        self.assertIn("＋ Ajouter un rendez-vous", fenetre)
        self.assertIn(f'value="{creneau}"', fenetre)
        self.assertIn('action="/ajouter"', fenetre)
        # Un créneau illisible ne casse rien : le champ arrive vide.
        _, sans = self._obtenir("/suivi/ajout?creneau=n-importe-quoi")
        self.assertIn('name="date_heure"', sans)
        self.assertNotIn("n-importe-quoi", sans)

    def test_le_creneau_libre_ouvre_la_fenetre_et_reste_un_lien(self):
        """Sans JavaScript, le même bouton mène à « /ajouter » : rien n'est
        perdu, c'est simplement moins fluide."""
        _, fenetre = self._obtenir(
            "/suivi/detail?creneau=" + urllib.parse.quote("2026-09-07T09:30"))
        self.assertIn('data-modale="/suivi/ajout?creneau=', fenetre)
        self.assertIn('href="/ajouter"', fenetre)


class TestStopAuTelephoneSchema(unittest.TestCase):
    """Le champ « do_not_call » : sa forme, et ce qu'il ne casse pas.

    ⚠ TROIS REFUS DE SCHÉMA ont déjà coûté des essais réels à ce projet (types
    multiples, champ réservé, schéma manquant). Un champ neuf se vérifie donc
    ICI, avant toute connexion.
    """

    def test_le_champ_est_declare_dans_les_deux_schemas(self):
        for schema in (calle_client.SCHEMA_RESULTAT,
                       calle_client.SCHEMA_RESULTAT_CASCADE):
            with self.subTest(schema=schema["properties"].keys()):
                champ = schema["properties"][calle_client.CHAMP_NE_PLUS_APPELER]
                # ⚠ UN ENUM DE TEXTE, jamais un booléen : « string + enum » est
                # ce que l'exemple de référence du sponsor emploie.
                self.assertEqual(champ["type"], "string")
                self.assertEqual(champ["enum"],
                                 list(calle_client.VALEURS_NE_PLUS_APPELER))
                # ⚠ ET AUCUN NOM RÉSERVÉ : CALL-E refuse la demande entière.
                self.assertEqual(calle_client.champs_reserves_dans(schema), [])

    def test_il_n_est_PAS_obligatoire(self):
        """⚠ LE POINT QUI PROTÈGE LES CAMPAGNES EXISTANTES. Dans « required »,
        un résultat où l'agent l'oublie serait déclaré ILLISIBLE — donc une
        campagne entière en pause pour un champ neuf."""
        for schema in (calle_client.SCHEMA_RESULTAT,
                       calle_client.SCHEMA_RESULTAT_CASCADE):
            self.assertNotIn(calle_client.CHAMP_NE_PLUS_APPELER,
                             schema["required"])
        # Et un résultat sans le champ passe la validation, comme avant.
        calle_client.valider_resultat({"appointment_status": "canceled",
                                       "new_datetime": None, "notes": "x"})
        calle_client.valider_resultat_cascade({"outcome": "refused",
                                               "new_datetime": None,
                                               "notes": "x"})

    def test_seul_un_oui_explicite_compte(self):
        """On ne devine pas un 🚫 dans du bruit : ce serait couper le téléphone
        à quelqu'un qui n'a rien demandé."""
        for valeur in ("yes", "YES", " oui ", "true", "1", "vrai"):
            with self.subTest(valeur=valeur):
                self.assertTrue(calle_client.ne_plus_appeler_demande(
                    {calle_client.CHAMP_NE_PLUS_APPELER: valeur}))
        for valeur in ("no", "", "  ", "peut-être", "non", None, 0):
            with self.subTest(valeur=valeur):
                self.assertFalse(calle_client.ne_plus_appeler_demande(
                    {calle_client.CHAMP_NE_PLUS_APPELER: valeur}))
        # Absent, et résultat qui n'est pas un objet : non.
        self.assertFalse(calle_client.ne_plus_appeler_demande({}))
        self.assertFalse(calle_client.ne_plus_appeler_demande(None))

    def test_la_consigne_dit_a_l_agent_quoi_faire(self):
        """⚠ SANS CETTE PHRASE, LE CHAMP RESTE VIDE À JAMAIS : l'agent ne
        remplit que ce qu'on lui demande. Et elle dit que ce n'est PAS une
        issue — il conclut quand même sur l'une des trois."""
        texte = consigne.Consigne("Bonjour.", "savoir si elle vient").texte()
        self.assertIn("do_not_call", texte)
        self.assertIn("ne me rappelez plus", texte)
        self.assertIn("conclus quand même sur l'une des trois issues", texte)
        # Le champ figure aussi dans le schéma que la consigne accompagne.
        self.assertIn(calle_client.CHAMP_NE_PLUS_APPELER,
                      calle_client.SCHEMA_RESULTAT["properties"])

    def test_la_simulation_le_produit_de_deux_facons(self):
        rdv = {"horaire": DEMAIN, "motif": "Essai"}
        # ① La terminaison forcée « 57 » : elle refuse ET demande le 🚫.
        simulateur = calle_client.AppelSimule(graine=1, latence=0)
        resultat = simulateur.appeler("X", "+33 6 00 00 00 57", rdv).resultat
        self.assertEqual(resultat["appointment_status"], "canceled")
        self.assertTrue(calle_client.ne_plus_appeler_demande(resultat))
        self.assertIn("ne plus être appelée", resultat["notes"])
        # ② La suite écrite en porte un — sinon une campagne simulée ne
        # montrerait jamais ce chemin.
        for chemin, appel in (("rappel", lambda s: s.appeler(
                "X", "+33 6 00 00 00 42", rdv)),
                ("cascade", lambda s: s.appeler_cascade(
                    "X", "+33 6 00 00 00 42", "mission", DEMAIN))):
            with self.subTest(chemin=chemin):
                simulateur = calle_client.AppelSimule(graine=1, latence=0)
                vus = 0
                for _ in range(len(calle_client.SUITE_RAPPEL)):
                    try:
                        resultat = appel(simulateur).resultat
                    except calle_client.PasDeReponse:
                        continue
                    if calle_client.ne_plus_appeler_demande(resultat):
                        vus += 1
                self.assertEqual(vus, 1)

    def test_les_terminaisons_d_avant_ne_demandent_jamais_le_stop(self):
        """51 à 56 n'ont pas changé de sens : un contrôle qui exige « refus »
        ne doit pas se retrouver avec un 🚫 en prime."""
        rdv = {"horaire": DEMAIN, "motif": "Essai"}
        simulateur = calle_client.AppelSimule(graine=1, latence=0)
        for fin in ("51", "52", "54", "55"):
            with self.subTest(terminaison=fin):
                resultat = simulateur.appeler(
                    "X", f"+33 6 00 00 00 {fin}", rdv).resultat
                self.assertFalse(
                    calle_client.ne_plus_appeler_demande(resultat))


class TestAutresPlacesEtIncomprehension(unittest.TestCase):
    """Les deux manques qui se voient dans la consigne et le schéma.

    ⚠ POURQUOI CES DEUX-LÀ COMPTENT. Refuser UNE place ne veut pas dire
    refuser les suivantes : sans la question, la seule échappatoire d'une
    personne lassée était le 🚫 — qui coupe aussi les appels sur SES
    rendez-vous. Et un agent qui ne comprend pas tranche quand même : la
    personne croit avoir été comprise, et le découvre devant une porte.
    """

    def test_le_champ_des_autres_places_est_en_cascade_SEULEMENT(self):
        """La question n'a de sens que si l'on appelle POUR proposer une place.
        Ailleurs, on appelle à propos du rendez-vous de la personne."""
        cascade = calle_client.SCHEMA_RESULTAT_CASCADE["properties"]
        self.assertIn(calle_client.CHAMP_AUTRES_PLACES, cascade)
        self.assertEqual(cascade[calle_client.CHAMP_AUTRES_PLACES]["type"],
                         "string")
        self.assertNotIn(calle_client.CHAMP_AUTRES_PLACES,
                         calle_client.SCHEMA_RESULTAT["properties"])
        # Hors de « required », et aucun nom réservé.
        self.assertNotIn(calle_client.CHAMP_AUTRES_PLACES,
                         calle_client.SCHEMA_RESULTAT_CASCADE["required"])
        self.assertEqual(calle_client.champs_reserves_dans(
            calle_client.SCHEMA_RESULTAT_CASCADE), [])

    def test_seul_un_non_explicite_ecarte_quelqu_un(self):
        """⚠ LE SENS PAR DÉFAUT EST « ELLE CONTINUE DE RECEVOIR » : personne
        n'est écarté par le silence de l'agent."""
        for valeur in ("no", "NON", " faux ", "0", "false"):
            with self.subTest(valeur=valeur):
                self.assertTrue(calle_client.refuse_les_autres_places(
                    {calle_client.CHAMP_AUTRES_PLACES: valeur}))
        for valeur in ("yes", "oui", "", None, "peut-être"):
            with self.subTest(valeur=valeur):
                self.assertFalse(calle_client.refuse_les_autres_places(
                    {calle_client.CHAMP_AUTRES_PLACES: valeur}))
        self.assertFalse(calle_client.refuse_les_autres_places({}))

    def test_la_consigne_pose_la_question_en_cascade_et_pas_ailleurs(self):
        cascade = consigne.Consigne(
            "Bonjour.", "savoir si elle prend la place",
            issues=consigne.ISSUES_DEFAUT_CASCADE,
            genre=consigne.GENRE_CASCADE).texte()
        classique = consigne.Consigne("Bonjour.", "savoir si elle vient").texte()
        self.assertIn("un autre créneau se libère", cascade)
        self.assertIn(calle_client.CHAMP_AUTRES_PLACES, cascade)
        self.assertNotIn("un autre créneau se libère", classique)
        # ⚠ ET SEULEMENT SUR UN REFUS : la poser à tout le monde serait du
        # démarchage.
        self.assertIn("QUE sur un refus", cascade)

    def test_la_consigne_dit_a_l_agent_d_avouer_qu_il_n_a_pas_compris(self):
        """⚠ SANS CETTE LIGNE, IL TRANCHE QUAND MÊME. C'est le pire des cas :
        RingBack écrit une décision que la personne n'a pas prise."""
        for texte in (consigne.Consigne("Bonjour.", "objectif").texte(),
                      consigne.Consigne(
                          "Bonjour.", "objectif",
                          issues=consigne.ISSUES_DEFAUT_CASCADE,
                          genre=consigne.GENRE_CASCADE).texte()):
            with self.subTest(genre=texte[:20]):
                self.assertIn("pas bien compris votre réponse", texte)
                self.assertIn("rien n'est changé de votre côté", texte)
                self.assertIn("Ne devine JAMAIS une issue", texte)
                # Elle demande de reformuler AVANT de passer la main.
                self.assertIn("demande de reformuler", texte)

    def test_la_simulation_produit_le_refus_des_propositions(self):
        """La terminaison « 58 » : elle décline la place ET ne veut plus qu'on
        lui en propose. « 52 », elle, décline mais accepte d'être rappelée —
        les deux cas doivent être exigibles séparément."""
        simulateur = calle_client.AppelSimule(graine=1, latence=0)
        for fin, refuse in (("58", True), ("52", False)):
            with self.subTest(terminaison=fin):
                resultat = simulateur.appeler_cascade(
                    "X", f"+33 6 00 00 00 {fin}", "mission", DEMAIN).resultat
                self.assertEqual(resultat["outcome"], "refused")
                self.assertEqual(
                    calle_client.refuse_les_autres_places(resultat), refuse)
        # ⚠ SUR UN OUI, LE CHAMP N'EST MÊME PAS LÀ : la question ne s'est pas
        # posée, et un champ rempli laisserait croire le contraire.
        resultat = simulateur.appeler_cascade(
            "X", "+33 6 00 00 00 51", "mission", DEMAIN).resultat
        self.assertNotIn(calle_client.CHAMP_AUTRES_PLACES, resultat)


class TestEffacerUneListeDeCampagnes(_TestAvecServeurWeb):
    """« Effacer la liste » : le seul geste du produit qui détruit un
    historique. Il compte avant, il confirme, il ne touche ni aux clients ni
    aux rendez-vous, et il refuse pendant qu'une campagne appelle."""

    def _campagne(self, nom, statut):
        """Une campagne d'un statut donné, avec une personne dans sa liste."""
        base = self.application.base
        client = base.ajouter_client(nom, "+33 6 00 00 00 21")
        rdv = base.ajouter_rendezvous(client, "2026-09-01T09:00", "Bilan")
        campagne = base.creer_campagne(nom, "creneau_libere")
        base.ajouter_contact_campagne(campagne, 1, nom, "+33 6 00 00 00 21",
                                      rendezvous_id=rdv)
        base.changer_statut_campagne(campagne, statut)
        return campagne, client, rdv

    def test_un_bouton_par_liste_affichee_et_aligne_a_droite(self):
        self._campagne("Liste prête", "prête")
        self._campagne("Liste terminée", "terminée")
        _, page = self._obtenir("/")
        # Un bouton par liste NON VIDE, et chacun désigne SA liste.
        # ⚠ On compte le BOUTON, pas la phrase : la feuille de style est
        # écrite dans chaque page et son commentaire la contient aussi.
        self.assertEqual(page.count(">Effacer la liste</a>"), 2)
        self.assertIn('data-modale="/campagnes/effacer?groupe=pretes"', page)
        self.assertIn('data-modale="/campagnes/effacer?groupe=terminees"', page)
        self.assertNotIn("groupe=en-cours", page)     # cette liste est vide
        # Il est DANS l'entête du titre, celle qui l'aligne à droite ; et le
        # lien reste un vrai lien pour le repli sans JavaScript.
        self.assertIn('class="entete-liste"', page)
        self.assertIn('href="/campagnes/effacer?groupe=pretes"', page)
        corps = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE, ".entete-liste"))
        self.assertIn("justify-content: space-between", corps)

    def test_un_get_ne_supprime_rien_il_compte(self):
        """⚠ LE CONTRÔLE ESSENTIEL : ouvrir la confirmation n'efface pas."""
        campagne, _, _ = self._campagne("À confirmer", "terminée")
        _, modale = self._obtenir("/campagnes/effacer?groupe=terminees")
        self.assertIn("Effacer «", modale)
        self.assertIn("1 campagne(s)", modale)
        self.assertIn("1 personne(s) dans leurs listes", modale)
        self.assertIn("ne se défait pas", modale)
        # Rien n'a bougé.
        self.assertIsNotNone(self.application.base.obtenir_campagne(campagne))

    def test_effacer_emporte_la_liste_et_epargne_le_reste(self):
        garde, _, _ = self._campagne("À garder", "prête")
        cible, client, rdv = self._campagne("À effacer", "terminée")
        base = self.application.base
        _, page = self._poster("/campagnes/effacer", {"groupe": "terminees"})
        # La campagne visée est partie, l'autre liste est intacte.
        self.assertIsNone(base.obtenir_campagne(cible))
        self.assertIsNotNone(base.obtenir_campagne(garde))
        self.assertEqual(base.contacts_de_campagne(cible), [])
        # ⚠ ET LE RÉSULTAT DU TRAVAIL RESTE : le client et son rendez-vous.
        self.assertIsNotNone(base.obtenir_client(client))
        self.assertIsNotNone(base.obtenir_rendezvous(rdv))
        # L'écran le dit, et le dit juste.
        self.assertIn("Liste effacée : 1 campagne(s)", page)
        self.assertIn("rendez-vous sont intacts", page)

    def test_on_refuse_pendant_qu_une_campagne_appelle(self):
        """Effacer une campagne en vol retirerait les lignes sous son fil."""
        campagne, _, _ = self._campagne("En vol", "en cours")
        with self.application._verrou_executions:
            self.application.executions[campagne] = {"commande": None}
        self.addCleanup(self.application.terminer_execution, campagne)
        _, modale = self._obtenir("/campagnes/effacer?groupe=en-cours")
        self.assertIn("Impossible pour l'instant", modale)
        self.assertIn("En vol", modale)
        self.assertNotIn("Effacer ces", modale)      # aucun bouton d'action
        # Et même en forçant l'envoi, rien n'est effacé.
        with self.assertRaises(urllib.error.HTTPError) as refus:
            self._poster("/campagnes/effacer", {"groupe": "en-cours"})
        self.assertEqual(refus.exception.code, 409)
        self.assertIsNotNone(
            self.application.base.obtenir_campagne(campagne))

    def test_un_appel_parti_dont_le_resultat_manque_est_signale(self):
        campagne, _, _ = self._campagne("Résultat en attente", "terminée")
        contact = self.application.base.contacts_de_campagne(campagne)[0]
        self.application.base.definir_appel_en_attente(
            contact["id"], "appel-essai-1", 0)
        _, modale = self._obtenir("/campagnes/effacer?groupe=terminees")
        self.assertIn("PARTIS chez CALL-E", modale)
        self.assertIn("Récupérer les résultats en attente", modale)

    def test_une_liste_inconnue_ou_vide_le_dit_sans_casser(self):
        _, modale = self._obtenir("/campagnes/effacer?groupe=martien")
        self.assertIn("n'existe pas", modale)
        _, modale = self._obtenir("/campagnes/effacer?groupe=pretes")
        self.assertIn("déjà vide", modale)
        with self.assertRaises(urllib.error.HTTPError) as refus:
            self._poster("/campagnes/effacer", {"groupe": "martien"})
        self.assertEqual(refus.exception.code, 400)


class TestListeDeCreneauxLiberes(_TestAvecServeurWeb):
    """Une campagne « créneau libéré » porte PLUSIEURS places (03/08/2026).

    Le « + » ajoute, la croix retire, l'ordre est chronologique croissant.
    Et rien de tout cela ne renomme le champ : les campagnes à UNE place
    envoient toujours le même « info_creneau_libere », mot pour mot.
    """

    def _brouillon(self):
        _, page = self._poster("/assistant/nature", {"nature": "creneau_libere"})
        return re.search(r'name="b" value="(\d+)"', page).group(1)

    def _places(self, page):
        """Les places de la liste, dans l'ordre où elles sont affichées."""
        if "liste-creneaux" not in page:
            return []
        zone = page.split("liste-creneaux", 1)[1]
        return re.findall(r'name="info_creneau_libere"\s+value="([^"]+)"', zone)

    def _ajouter(self, b, horaire, deja=()):
        return self._poster("/assistant/message", {
            "b": b, "info_entreprise": "Cabinet Essai",
            "info_creneau_libere": list(deja),
            "creneau_libere_ajout": horaire, "action": "creneau-ajouter"})[1]

    def test_le_plus_et_la_croix_tiennent_la_liste_en_ordre(self):
        b = self._brouillon()
        self._ajouter(b, "2026-08-13T10:00")
        page = self._obtenir(f"/assistant/message?b={b}")[1]
        self.assertEqual(self._places(page), ["2026-08-13T10:00"])
        # Une place PLUS ANCIENNE se range EN TÊTE : l'ordre de rangement est
        # l'ordre d'affichage, il n'y en a pas deux.
        self._ajouter(b, "2026-08-12T09:00", self._places(page))
        page = self._obtenir(f"/assistant/message?b={b}")[1]
        self.assertEqual(self._places(page),
                         ["2026-08-12T09:00", "2026-08-13T10:00"])
        # Et elle est lisible, pas en ISO brut.
        self.assertIn("mercredi 12/08 à 09h00", page)
        # Une troisième au milieu, puis la croix la retire — par son HORAIRE,
        # pas par un rang qui aurait désigné une autre place après le tri.
        self._ajouter(b, "2026-08-12T15:00", self._places(page))
        page = self._obtenir(f"/assistant/message?b={b}")[1]
        self.assertEqual(len(self._places(page)), 3)
        self._poster("/assistant/message", {
            "b": b, "info_creneau_libere": self._places(page),
            "action": "creneau-retirer:2026-08-12T15:00"})
        page = self._obtenir(f"/assistant/message?b={b}")[1]
        self.assertEqual(self._places(page),
                         ["2026-08-12T09:00", "2026-08-13T10:00"])
        # Un doublon ne s'ajoute pas deux fois.
        self._ajouter(b, "2026-08-12T09:00", self._places(page))
        page = self._obtenir(f"/assistant/message?b={b}")[1]
        self.assertEqual(len(self._places(page)), 2)

    def test_le_champ_garde_son_nom_pour_les_campagnes_a_une_place(self):
        """⚠ LE NOM NE CHANGE PAS. Douze essais envoient « info_creneau_libere »
        seul : les renommer en creneau_1, creneau_2… les aurait cassés en bloc
        et aurait fait perdre la garantie que rien n'a bougé pour elles."""
        b = self._brouillon()
        self._poster("/assistant/message", {
            "b": b, "info_entreprise": "Cabinet Essai", "ordre": "anciennete",
            "info_creneau_libere": "2026-08-12T09:00", "action": "continuer"})
        brouillon = self.application.obtenir_brouillon_assistant(b)
        self.assertEqual([f["horaire"] for f in brouillon["creneaux"]],
                         ["2026-08-12T09:00"])
        # ET la valeur unique reste lisible là où elle l'a toujours été : tout
        # ce qui lit infos["creneau_libere"] continue de marcher.
        self.assertEqual(brouillon["infos"]["creneau_libere"],
                         "2026-08-12T09:00")

    def test_une_place_illisible_n_emporte_pas_les_autres(self):
        b = self._brouillon()
        self._poster("/assistant/message", {
            "b": b, "info_entreprise": "Cabinet Essai", "ordre": "anciennete",
            "info_creneau_libere": ["2026-08-12T09:00", "bientôt",
                                    "2026-08-13T10:00"],
            "action": "continuer"})
        page = self._obtenir(f"/assistant/message?b={b}")[1]
        # Le refus NOMME la place fautive.
        self.assertIn("bientôt : Date illisible", page)
        # Et les trois sont toujours là — y compris celle qui a été refusée :
        # une saisie refusée n'est jamais perdue.
        self.assertEqual(len(self._places(page)), 3)
        self.assertIn("bientôt", self._places(page))

    def test_sans_aucune_place_le_refus_montre_le_chemin(self):
        b = self._brouillon()
        self._poster("/assistant/message", {
            "b": b, "info_entreprise": "Cabinet Essai", "ordre": "anciennete",
            "action": "continuer"})
        page = self._obtenir(f"/assistant/message?b={b}")[1]
        self.assertIn("est obligatoire pour cette nature de campagne", page)
        self.assertIn("ajoutez au moins une place avec le « + »", page)
        # ⚠ L'identifiant que lit l'aperçu vivant existe MÊME sans place :
        # sans lui, l'aperçu ne retrouverait plus jamais le champ.
        self.assertIn('id="info_creneau_libere"', page)

    def test_la_campagne_creee_porte_toute_sa_liste(self):
        b = self._brouillon()
        self._poster("/assistant/message", {
            "b": b, "info_entreprise": "Cabinet Essai", "ordre": "anciennete",
            "info_creneau_libere": ["2026-08-13T10:00", "2026-08-12T09:00"],
            "action": "continuer"})
        brouillon = self.application.obtenir_brouillon_assistant(b)
        brouillon["contacts"] = [{"nom": "Mme Essai Places",
                                  "telephone": "+33 6 00 00 00 31",
                                  "champs": {}}]
        campagne_id = assistant.creer_campagne_prete(
            self.application.base, brouillon, self.application.preferences)
        campagne = self.application.base.obtenir_campagne(campagne_id)
        self.assertEqual([f["horaire"] for f in assistant.creneaux_de(campagne)],
                         ["2026-08-12T09:00", "2026-08-13T10:00"])
        # ⚠ La colonne « creneau » garde la PREMIÈRE : tout ce qui la lit
        # (parcours direct, fiche, écran Clients, banc d'essai) continue.
        self.assertEqual(campagne["creneau"], "2026-08-12T09:00")


class TestSelectionnerUnePlageDuPlanning(_TestAvecServeurWeb):
    """Glisser sur la grille des rendez-vous pour en faire une campagne.

    Le geste est écrit à part, sur la seule zone du planning : celui du
    calendrier des Réglages poste « geste=basculer » vers /reglages/semaine,
    et s'il prenait ce geste-ci il changerait les HORAIRES D'OUVERTURE.
    """

    def setUp(self):
        super().setUp()
        # Sans horaires d'ouverture, aucune place n'est libre : l'essai
        # passerait à vide.
        for jour in range(5):
            horaires.basculer_periode(self.application.preferences,
                                      jour, 9 * 60, 12 * 60, "ouvrir")

    def _semaine_a_venir(self):
        """La grille d'une semaine FUTURE : c'est là qu'il y a des places."""
        quand = datetime.date.today() + datetime.timedelta(days=21)
        return self._obtenir(
            f"/suivi?date={urllib.parse.quote(quand.strftime('%d/%m/%Y'))}")[1]

    @staticmethod
    def _places_libres(page):
        return sorted(set(re.findall(
            r'data-quand="([^"]+)"\s+data-contenu="libre"', page)))

    @staticmethod
    def _zone(jour1, jour2, heure1, heure2):
        """Un rectangle, dans l'écriture qu'envoie le glissé."""
        return urllib.parse.quote(f"{jour1}|{jour2}|{heure1}|{heure2}")

    def _menu(self, *zones):
        return self._obtenir(
            "/suivi/plage?" + "&".join(f"zone={z}" for z in zones),
            fenetre=True)[1]

    @staticmethod
    def _proposees(menu):
        return re.findall(r'name="creneau" value="([^"]+)"', menu)

    def test_chaque_case_dit_son_horaire_et_ce_qu_elle_contient(self):
        page = self._semaine_a_venir()
        # ⚠ L'HORAIRE, pas une position à l'écran : une position aurait
        # désigné une autre case au premier retri de la grille.
        self.assertIn('data-quand="', page)
        self.assertIn('data-contenu="libre"', page)
        # ⚠ ET SURTOUT PAS les marques du calendrier des Réglages : son geste
        # écoute le document et changerait les horaires d'ouverture.
        # ⚠ On s'arrête à la FERMETURE de la section : aller jusqu'au bout de
        # la page attrapait SCRIPT_FRAGMENTS, dont les commentaires parlent
        # justement de « data-calendrier ».
        debut = page.index('id="planning"')
        grille = page[debut:page.index("</section>", debut)]
        self.assertNotIn("data-calendrier", grille)
        self.assertNotIn('class="tranche', grille)

    def test_le_menu_compte_la_plage_avant_de_proposer(self):
        page = self._semaine_a_venir()
        libres = self._places_libres(page)
        self.assertTrue(libres, "aucune place libre : l'essai ne prouve rien")
        jour = libres[0][:10]
        menu = self._menu(self._zone(jour, jour, libres[0][11:],
                                     libres[3][11:]))
        # C'est la fenêtre commune, posée sur le côté par le style.
        self.assertIn("modale-laterale", menu)
        self.assertIn("modale-fermer", menu)
        # Elle COMPTE, et elle écrit la plage en mots : la couleur de la
        # sélection ne porte pas seule.
        self.assertRegex(menu, r"\d+ place\(s\) libre\(s\)")
        self.assertRegex(menu, r"\d+ rendez-vous")
        self.assertIn("de 09h00", menu)
        # Les places partent en champs cachés, une par une.
        self.assertEqual(len(re.findall(r'name="creneau" value=', menu)), 4)
        # ⚠ Le déplacement est AFFICHÉ mais sans bouton : la demande dit
        # « pour l'instant ne faire que le créneau libre ». Le masquer en
        # silence, ou le laisser cliquable sans effet, seraient deux mensonges.
        # ⚠ DÉPLACEMENT, RAPPEL ET CONFIRMATION ONT LEUR BOUTON depuis le
        # 10/08/2026 — mais SEULEMENT si la plage contient des rendez-vous.
        # Celle-ci n'en contient aucun : l'écran dit pourquoi, au lieu de
        # montrer trois boutons qui refuseraient (voir
        # TestTroisCampagnesDepuisUnePlage pour le cas où il y en a).
        self.assertIn("Aucun rendez-vous dans cette plage", menu)
        self.assertNotIn("action=\"/suivi/plage/deplacement\"", menu)


    def test_une_plage_sans_place_le_dit_et_ne_propose_rien(self):
        menu = self._menu(self._zone("2020-01-01", "2020-01-01",
                                     "09:00", "10:00"))
        # ⚠ UNE LIGNE, PAS UN PARAGRAPHE (10/08/2026) : le bouton ne disparaît
        # pas en silence, mais on ne raconte plus pourquoi une place passée ne
        # se propose pas — ça se devine, et ça encombrait.
        self.assertIn("Aucune place libre à venir dans cette plage", menu)
        self.assertNotIn("Campagne pour remplir les créneaux libres", menu)

    def test_une_plage_illisible_ne_casse_rien(self):
        """Une zone à moitié comprise vaudrait moins que pas de zone du tout."""
        for brut in ("bientot|jamais|midi|minuit", "2026-08-10|2026-08-12",
                     "2026-08-10|2026-08-12|09:00|", ""):
            with self.subTest(zone=brut):
                menu = self._menu(urllib.parse.quote(brut))
                self.assertIn("Plage illisible", menu)
                self.assertIn("Recommencez la sélection", menu)

    def test_la_plage_ouvre_un_brouillon_et_n_appelle_personne(self):
        page = self._semaine_a_venir()
        libres = self._places_libres(page)
        self.assertTrue(libres, "aucune place libre : l'essai ne prouve rien")
        jour = libres[0][:10]
        menu = self._menu(self._zone(jour, jour, libres[0][11:],
                                     libres[2][11:]))
        places = self._proposees(menu)
        avant = len(self.application.base.lister_campagnes())
        _, arrivee = self._poster("/suivi/plage/creneau-libere",
                                  {"creneau": places})
        # ⚠ AUCUNE CAMPAGNE N'EST CRÉÉE : on ouvre l'assistant, l'opérateur
        # décide. C'est la règle « rien ne part sans un geste humain ».
        self.assertEqual(len(self.application.base.lister_campagnes()), avant)
        # On est bien à l'étape ② de l'assistant, avec la liste des places.
        self.assertIn("liste-creneaux", arrivee)
        self.assertIn("Créneau libéré", arrivee)
        # Et les places sont déjà posées dans le brouillon, dans l'ordre.
        identifiant = re.search(r'name="b" value="(\d+)"', arrivee).group(1)
        brouillon = self.application.obtenir_brouillon_assistant(identifiant)
        self.assertEqual(brouillon["nature"], "creneau_libere")
        self.assertEqual([f["horaire"] for f in brouillon["creneaux"]], places)
        self.assertEqual(brouillon["infos"]["creneau_libere"], places[0])

    def test_sans_aucune_place_la_creation_est_refusee(self):
        with self.assertRaises(urllib.error.HTTPError) as refus:
            self._poster("/suivi/plage/creneau-libere", {"creneau": []})
        self.assertEqual(refus.exception.code, 400)

    def test_le_repli_est_replie_derriere_son_intitule(self):
        """⚠ RETIRÉ PUIS REMIS LE MÊME JOUR (10/08/2026), sur demande du
        propriétaire : « remets Sans glisser replié derrière un lien Saisie
        manuelle des créneaux ».

        Le glisser du planning n'existe qu'À LA SOURIS dans tout RingBack
        (aucun touchstart, aucun pointerdown) : sans ce formulaire, ni le doigt
        ni un navigateur sans script ne pouvaient ouvrir la fenêtre de plage.
        Replié, il ne coûte plus qu'un intitulé à l'écran.

        ⚠ ET LE REPLI NE DEMANDE AUCUN SCRIPT — c'est un <details>. Un panneau
        ouvert par JavaScript aurait laissé le formulaire hors d'atteinte sur
        le seul appareil qui en a besoin.
        """
        page = self._semaine_a_venir()
        self.assertIn('action="/suivi/plage" class="carte repli-plage"', page)
        self.assertIn("Sans glisser", page)
        # L'intitulé, en clair, et le repli qui le porte.
        self.assertIn("Saisie manuelle des créneaux", page)
        self.assertIn('<details class="repli-geste"', page)
        # ⚠ REPLIÉ : pas de « open ».
        self.assertNotIn('<details class="repli-geste" open', page)
        # ⚠ QUATRE VALEURS, parce que la plage est un rectangle : deux jours,
        # deux heures. Deux champs « du … au … » ne savaient pas dire « du
        # lundi au mercredi, de 9h00 à 10h15 ».
        for champ in ("jour1", "jour2", "heure1", "heure2"):
            with self.subTest(champ=champ):
                self.assertIn(f'name="{champ}"', page)
        for entete in ("Du jour", "Au jour", "De", "À", "Plage"):
            with self.subTest(entete=entete):
                self.assertIn(f'>{entete}</th>', page)
        # La semaine affichée voyage avec : la fenêtre s'en sert pour ses
        # campagnes, et le retour au planning ne doit pas la perdre.
        self.assertIn('name="annee"', page)
        self.assertIn('name="semaine"', page)

    def test_les_quatre_champs_ouvrent_bien_la_fenetre(self):
        """⚠ LE CHEMIN COMPLET, pas seulement le formulaire : ce sont ces
        quatre champs que le serveur relit (voir _zones_de_plage)."""
        jour = (datetime.date.today() + datetime.timedelta(days=1)).isoformat()
        _, menu = self._obtenir(f"/suivi/plage?jour1={jour}&jour2={jour}"
                                "&heure1=09:00&heure2=10:00")
        self.assertIn("Plage sélectionnée", menu)
        self.assertRegex(menu, r"\d+ place\(s\) libre\(s\)")

    def test_la_plage_est_un_rectangle_pas_une_periode(self):
        """⚠ L'ESSAI CENTRAL de ce changement (09/08/2026). « Du lundi au
        mercredi, de 9h00 à 10h15 » retient SIX cases par jour, pas tout ce
        qui se trouve entre le lundi 9h00 et le mercredi 10h15. Avec l'ancienne
        période, les fins de matinée du lundi et du mardi partaient avec.
        """
        page = self._semaine_a_venir()
        libres = self._places_libres(page)
        self.assertTrue(libres, "aucune place libre : l'essai ne prouve rien")
        jours = sorted({place[:10] for place in libres})
        self.assertGreaterEqual(len(jours), 3, "il faut trois jours ouverts")
        premier, dernier = jours[0], jours[2]
        menu = self._menu(self._zone(premier, dernier, "09:00", "10:15"))
        places = self._proposees(menu)
        self.assertTrue(places)
        # Les trois jours sont là…
        self.assertEqual(sorted({p[:10] for p in places}), jours[:3])
        # … et AUCUNE heure hors de la tranche choisie.
        self.assertEqual(sorted({p[11:] for p in places})[0], "09:00")
        for place in places:
            self.assertLessEqual(place[11:], "10:15", place)
        # ⚠ LA PREUVE PAR LA CONTRE-ÉPREUVE : une place de fin de matinée du
        # PREMIER jour existe bien, et elle n'est PAS retenue. Sous l'ancienne
        # période elle l'aurait été — elle est entre les deux bouts.
        tardives = [p for p in libres if p[:10] == premier and p[11:] > "10:15"]
        self.assertTrue(tardives, "aucune place tardive : l'essai ne prouve rien")
        for place in tardives:
            self.assertNotIn(place, places)

    def test_les_coins_se_lisent_dans_les_quatre_sens(self):
        """On glisse aussi de bas en haut et de droite à gauche."""
        page = self._semaine_a_venir()
        jours = sorted({place[:10] for place in self._places_libres(page)})
        droit = self._proposees(
            self._menu(self._zone(jours[0], jours[1], "09:00", "10:00")))
        inverse = self._proposees(
            self._menu(self._zone(jours[1], jours[0], "10:00", "09:00")))
        self.assertTrue(droit)
        self.assertEqual(droit, inverse)

    def test_plusieurs_zones_s_additionnent_sans_doublon(self):
        """Ctrl + glissé répété. Deux zones qui se CHEVAUCHENT ne comptent pas
        deux fois la même place : « 8 places » là où il y en a 5 aurait été un
        chiffre faux sur lequel on décide d'appeler des gens."""
        page = self._semaine_a_venir()
        jours = sorted({place[:10] for place in self._places_libres(page)})
        une = self._proposees(
            self._menu(self._zone(jours[0], jours[0], "09:00", "09:30")))
        deux = self._proposees(
            self._menu(self._zone(jours[1], jours[1], "10:00", "10:30")))
        ensemble = self._proposees(
            self._menu(self._zone(jours[0], jours[0], "09:00", "09:30"),
                       self._zone(jours[1], jours[1], "10:00", "10:30")))
        self.assertEqual(ensemble, sorted(une + deux))
        # Chevauchement : la même place n'apparaît qu'une fois.
        chevauche = self._proposees(
            self._menu(self._zone(jours[0], jours[0], "09:00", "10:00"),
                       self._zone(jours[0], jours[0], "09:30", "10:30")))
        self.assertEqual(len(chevauche), len(set(chevauche)))

    def test_le_menu_ecrit_chaque_zone_en_toutes_lettres(self):
        """La couleur de la sélection ne porte jamais seule — et avec
        plusieurs zones, encore moins."""
        page = self._semaine_a_venir()
        jours = sorted({place[:10] for place in self._places_libres(page)})
        seule = self._menu(self._zone(jours[0], jours[2], "09:00", "10:15"))
        self.assertIn("de 09h00 à 10h15", seule)
        self.assertIn("du ", seule)
        self.assertIn("au ", seule)
        plusieurs = self._menu(
            self._zone(jours[0], jours[0], "09:00", "09:30"),
            self._zone(jours[1], jours[1], "10:00", "10:30"))
        self.assertIn("sur 2 zones", plusieurs)
        self.assertIn("de 09h00 à 09h30", plusieurs)
        self.assertIn("de 10h00 à 10h30", plusieurs)
        # Une zone d'UNE case — un Ctrl + clic — ne dit pas « de 09h00 à
        # 09h00 » : exact, et illisible.
        une_case = self._menu(self._zone(jours[0], jours[0], "09:00", "09:00"))
        self.assertIn("à 09h00", une_case)
        self.assertNotIn("de 09h00 à 09h00", une_case)

    def test_le_repli_sans_javascript_lit_les_quatre_champs(self):
        """Le formulaire n'a pas de JavaScript pour assembler ses champs en
        « zone= » : le serveur doit les lire séparément, sinon le repli ne
        marche plus du tout."""
        page = self._semaine_a_venir()
        jours = sorted({place[:10] for place in self._places_libres(page)})
        _, menu = self._obtenir(
            f"/suivi/plage?jour1={jours[0]}&jour2={jours[1]}"
            "&heure1=09%3A00&heure2=10%3A00")
        self.assertNotIn("Plage illisible", menu)
        places = self._proposees(menu)
        self.assertTrue(places)
        self.assertEqual(sorted({p[:10] for p in places}), jours[:2])

    # ------------------------------------------ le cumul par Ctrl, dans le geste
    def test_le_geste_compose_un_rectangle(self):
        script = _sans_espaces_superflus(serveur.SCRIPT_PLANNING)
        # Le jour et l'heure sont LUS dans « data-quand » : deux attributs de
        # plus auraient pu se désaccorder de celui-là.
        self.assertIn("function jourDe(q){return q.slice(0,10)}", script)
        self.assertIn("function heureDe(q){return q.slice(11)}", script)
        self.assertIn("function rectangle(a,b)", script)
        self.assertIn("j>=r.j1&&j<=r.j2&&h>=r.h1&&h<=r.h2", script)
        # Et ce qui part au serveur est bien une zone.
        self.assertIn("'zone='+encodeURIComponent(r.j1+'|'+r.j2+'|'+r.h1+'|'+r.h2)",
                      script)

    def test_ctrl_cumule_et_n_ouvre_qu_au_relachement(self):
        """⚠ SANS L'ATTENTE, la fenêtre se serait rouverte à chaque zone et
        aurait recouvert la grille sur laquelle on choisit la suivante."""
        script = _sans_espaces_superflus(serveur.SCRIPT_PLANNING)
        self.assertIn("cumul=!!e.ctrlKey;", script)
        # Un glissé SANS Ctrl repart de zéro.
        self.assertIn("if(!cumul){zones=[]}", script)
        # Ctrl encore enfoncé au relâché de la souris : on n'ouvre pas.
        self.assertIn("var attendre=cumul&&e.ctrlKey;", script)
        self.assertIn("if(!attendre){ouvrir()}", script)
        # C'est le relâchement de Ctrl qui ouvre…
        self.assertIn("if(e.key!=='Control'&&e.keyCode!==17){return}", script)
        # … sauf si un glissé est en cours : c'est alors la souris qui ouvrira.
        self.assertIn("if(depart!==null){return}", script)

    def test_ctrl_n_ouvre_pas_la_fiche_de_la_case(self):
        """Ctrl COMPOSE une sélection. Sans cette sortie, ajouter une case
        seule ouvrait la fiche du créneau par-dessus la grille."""
        script = _sans_espaces_superflus(serveur.SCRIPT_PLANNING)
        self.assertIn("if(e.ctrlKey){return}", script)

    def test_le_geste_ne_double_pas_le_clic_simple(self):
        """⚠ UNE SEULE CASE = UN CLIC : sans cette sortie, le même geste
        ouvrait DEUX fenêtres — celle de la case et celle de la plage."""
        script = _sans_espaces_superflus(serveur.SCRIPT_PLANNING)
        self.assertIn("if(arrivee===d&&!cumul){effacer();cumul=false;return}",
                      script)
        # Et le geste vit sur la zone du planning, pas sur le document.
        self.assertIn("zone.addEventListener('mousedown'", script)
        # ⚠ On vérifie qu'il n'ENVOIE rien aux réglages, pas que la chaîne
        # soit absente : le commentaire qui explique le danger la contient.
        self.assertNotIn("fetch('/reglages", script)
        self.assertNotIn('action="/reglages', script)


class TestOrdreDAppelParEloignement(_TestAvecServeurWeb):
    """Le rendez-vous le plus LOINTAIN d'abord (décision du 03/08/2026).

    C'est lui qui a le plus à gagner à avancer sur la place qui se libère ;
    celui dont le rendez-vous est déjà proche n'y gagnerait presque rien.
    """

    GENS = (("Proche", "2026-08-25T09:00"),
            ("Lointain", "2026-12-01T09:00"),
            ("Milieu", "2026-09-15T09:00"))

    def _prepare(self, ordre="eloignement"):
        """Un brouillon d'étape ③ avec trois personnes en désordre."""
        _, page = self._poster("/assistant/nature", {"nature": "creneau_libere"})
        b = re.search(r'name="b" value="(\d+)"', page).group(1)
        self._poster("/assistant/message", {
            "b": b, "info_entreprise": "Cabinet Essai", "ordre": ordre,
            "info_creneau_libere": "2026-08-20T09:00", "action": "continuer"})
        # Le sélecteur d'ordre de la GRILLE : donc le mode manuel (celui de la
        # règle a le sien, éprouvé par TestOrdreDuModeAutomatique).
        self._poster("/assistant/liste", {"b": b, "action": "liste:manuel"})
        brouillon = self.application.obtenir_brouillon_assistant(b)
        brouillon["contacts"] = [
            {"nom": nom, "telephone": f"+33 6 00 00 00 0{rang}",
             "champs": {"rdv_existant": rdv, "motif": "Bilan"}}
            for rang, (nom, rdv) in enumerate(self.GENS, start=1)]
        return b

    def _envoyer(self, b, ordre):
        """Renvoie la grille TELLE QU'ELLE EST AFFICHÉE, avec un nouvel ordre."""
        brouillon = self.application.obtenir_brouillon_assistant(b)
        donnees = {"b": b, "ordre": ordre, "action": "enregistrer"}
        for rang, contact in enumerate(brouillon["contacts"], start=1):
            donnees[f"nom_{rang}"] = contact["nom"]
            donnees[f"tel_{rang}"] = ""
            donnees[f"c_rdv_existant_{rang}"] = contact["champs"]["rdv_existant"]
            donnees[f"c_motif_{rang}"] = "Bilan"
        return self._poster("/assistant/liste", donnees)

    def test_le_tri_met_le_plus_lointain_en_tete(self):
        gens = [{"nom": nom, "telephone": "+33 6 00 00 00 01",
                 "champs": {"rdv_existant": rdv}} for nom, rdv in self.GENS]
        gens.append({"nom": "Sans date", "telephone": "+33 6 00 00 00 09",
                     "champs": {}})
        self.assertEqual(
            [c["nom"] for c in assistant.ordonner_contacts(gens, "eloignement")],
            ["Lointain", "Milieu", "Proche", "Sans date"])
        # L'autre sens existe toujours, et il est nommé pour ce qu'il fait.
        self.assertEqual(
            [c["nom"] for c in assistant.ordonner_contacts(gens, "anciennete")],
            ["Proche", "Milieu", "Lointain", "Sans date"])
        # ⚠ « Sans date » RESTE EN DERNIER dans les deux : un simple
        # reverse=True l'aurait renvoyé en tête, sans rendez-vous à comparer.
        self.assertIn("LOINTAIN", assistant.ORDRES_APPEL["eloignement"])
        self.assertIn("PROCHE", assistant.ORDRES_APPEL["anciennete"])

    def test_la_nature_propose_l_eloignement(self):
        _, page = self._poster("/assistant/nature", {"nature": "creneau_libere"})
        self.assertEqual(
            assistant.NATURES["creneau_libere"]["ordre_defaut"], "eloignement")
        self.assertIn('<option value="eloignement" selected>', page)

    def test_le_selecteur_est_au_dessus_de_la_grille(self):
        b = self._prepare()
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        # ⚠ AU-DESSUS, et DANS le formulaire de la grille : ailleurs, il
        # n'aurait été lu par personne — _enregistrer_etape2 ne tourne que sur
        # l'étape ②, et un « ordre » posté avec la grille était jeté.
        self.assertIn("ordre-grille", page)
        formulaire = page[page.index('action="/assistant/liste"'):]
        self.assertLess(formulaire.index('name="ordre"'),
                        formulaire.index("<table>"))
        apres = page.split('name="ordre"', 1)[1]
        self.assertEqual(re.findall(r'<option value="(\w+)"', apres)[:2],
                         ["eloignement", "anciennete"])

    def test_enregistrer_reordonne_la_liste_et_pas_l_affichage(self):
        """⚠ LE CONTRÔLE ESSENTIEL. Les cellules sont nommées par POSITION et
        relues par la même position : trier au seul rendu aurait écrit un
        numéro corrigé sur la personne restée en position 1."""
        b = self._prepare()
        self._envoyer(b, "eloignement")
        brouillon = self.application.obtenir_brouillon_assistant(b)
        self.assertEqual([c["nom"] for c in brouillon["contacts"]],
                         ["Lointain", "Milieu", "Proche"])
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        affiches = re.findall(r'name="nom_\d+"[^>]*value="([^"]*)"', page)
        # La grille affichée COÏNCIDE avec la liste : les positions désignent
        # bien les mêmes personnes de part et d'autre.
        self.assertEqual(affiches, [c["nom"] for c in brouillon["contacts"]])

    def test_changer_d_ordre_retourne_la_liste(self):
        b = self._prepare()
        self._envoyer(b, "eloignement")
        self._envoyer(b, "anciennete")
        brouillon = self.application.obtenir_brouillon_assistant(b)
        self.assertEqual([c["nom"] for c in brouillon["contacts"]],
                         ["Proche", "Milieu", "Lointain"])
        self.assertEqual(brouillon["ordre"], "anciennete")

    def test_un_autre_ordre_choisi_a_l_etape_2_n_est_pas_ecrase(self):
        """Le sélecteur ne propose que deux choix. S'il en cachait un
        troisième déjà retenu, le premier envoi l'aurait effacé en silence."""
        b = self._prepare(ordre="alphabetique")
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        # ⚠ On DÉSÉCHAPPE : le HTML écrit « l&#x27;étape », et chercher
        # l'apostrophe brute ne trouvait rien sur une page pourtant juste.
        apres = html.unescape(page.split('name="ordre"', 1)[1])
        self.assertIn('value="alphabetique" selected', apres)
        self.assertIn("choisi à l'étape ②", apres)
        # Et il survit à un envoi qui ne le change pas.
        self._envoyer(b, "alphabetique")
        self.assertEqual(
            self.application.obtenir_brouillon_assistant(b)["ordre"],
            "alphabetique")

    def test_retirer_une_ligne_ne_retrie_pas_sous_les_doigts(self):
        """Retirer désigne une POSITION : retrier dans le même envoi aurait
        retiré une autre personne que celle visée."""
        b = self._prepare()
        self._envoyer(b, "eloignement")
        brouillon = self.application.obtenir_brouillon_assistant(b)
        donnees = {"b": b, "ordre": "anciennete", "action": "retirer:1"}
        for rang, contact in enumerate(brouillon["contacts"], start=1):
            donnees[f"nom_{rang}"] = contact["nom"]
            donnees[f"tel_{rang}"] = ""
            donnees[f"c_rdv_existant_{rang}"] = contact["champs"]["rdv_existant"]
            donnees[f"c_motif_{rang}"] = "Bilan"
        _, page = self._poster("/assistant/liste", donnees)
        # C'est bien « Lointain », en position 1 à l'écran, qui est parti.
        self.assertIn("« Lointain » retiré", page)
        restants = [c["nom"] for c in
                    self.application.obtenir_brouillon_assistant(b)["contacts"]]
        self.assertNotIn("Lointain", restants)
        self.assertEqual(sorted(restants), ["Milieu", "Proche"])


class TestDeuxDatesPourUneSeulePlace(unittest.TestCase):
    """⚠ SON APPEL RÉEL DU 01/09/2026 : la campagne à liste de places s'est
    arrêtée après le PREMIER contact, sur un 422 de CALL-E dont le message est
    une question :

        « Quelle est la bonne date du créneau libéré à proposer à madame
          Émilie Aubry ? »

    Il avait raison de demander. Mesuré sur sa campagne n°133 : la présentation
    disait « une place s'est libérée le vendredi 2 octobre 2026 à 9 heures 40 »
    et « ce que tu sais » disait « Créneau libéré : mercredi 2 septembre 2026 à
    9 heures 40 » — la place que le PREMIER contact venait de prendre.

    LA CAUSE : en avançant d'une place à l'autre, la campagne mettait à jour sa
    colonne `creneau` et son message, mais PAS ses informations d'étape 2 — or
    ce sont elles qui nourrissent les faits de la consigne. Les infos recalées
    étaient bien calculées par `mission_sur_la_place`… puis jetées.
    """

    def _campagne_a_deux_places(self):
        """Une campagne à liste, dont la première place vient d'être pourvue."""
        base = db.Base(":memory:")
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        depart = (datetime.datetime.now()
                  + datetime.timedelta(days=1)).replace(
            hour=9, minute=0, second=0, microsecond=0)
        places = [depart, depart + datetime.timedelta(days=30)]
        telephone = "+33 6 00 00 00 51"
        contacts = []
        for rang in range(2):
            client = base.ajouter_client(f"Mme A{rang + 1}", telephone)
            rdv = base.ajouter_rendezvous(
                client, (depart + datetime.timedelta(days=60 + rang * 3))
                .isoformat(timespec="minutes"), "Bilan", statut="confirmé")
            contacts.append((f"Mme A{rang + 1}", telephone, rdv))
        brouillon = {
            "nature": "creneau_libere",
            "infos": {"creneau_libere": places[0].isoformat(timespec="minutes"),
                      "entreprise": "Cabinet Essai"},
            "infos_auto": {}, "politique": "premier_oui",
            "ordre": "eloignement",
            "options": {"liberer_creneau": True, "cascade": False},
            "champs": [dict(c)
                       for c in assistant.NATURES["creneau_libere"]["champs"]],
            # ⚠ LE MESSAGE EST CELUI DU GABARIT, pas un texte à la main : un
            # message récrit empêche justement la campagne d'avancer de place
            # (mission_editee), et l'essai n'aurait rien mesuré.
            "mission": assistant.construire_mission(
                "creneau_libere",
                {"creneau_libere": places[0].isoformat(timespec="minutes"),
                 "entreprise": "Cabinet Essai"}, prefs, {}),
            "recette": {"apports": [{"quoi": "base"}], "a_la_main": False},
            "creneaux": assistant.normaliser_creneaux(
                [p.isoformat(timespec="minutes") for p in places]),
            "contacts": [
                {"nom": nom, "telephone": tel, "rendezvous_id": rdv,
                 "champs": {"rdv_existant":
                            base.obtenir_rendezvous(rdv)["horaire"],
                            "motif": "Bilan"}}
                for nom, tel, rdv in contacts]}
        campagne_id = assistant.creer_campagne_prete(base, brouillon, prefs)
        campagne = base.obtenir_campagne(campagne_id)
        configuration = assistant.configuration_campagne(campagne)
        # La PREMIÈRE place est pourvue, et la campagne avance.
        assistant.marquer_creneau(base, campagne_id,
                                  places[0].isoformat(timespec="minutes"),
                                  assistant.CRENEAU_POURVU)
        campagne, configuration, suivante, _ = (
            assistant.avancer_sur_la_place_suivante(
                base, prefs, campagne, configuration))
        self.assertIsNotNone(suivante, "la campagne n'a pas avancé")
        return base, prefs, campagne, configuration

    @staticmethod
    def _dates_dites(texte):
        return set(MOTIF_DATE_PARLEE.findall(texte))

    def test_la_tache_ne_porte_qu_UNE_date_pour_la_place_liberee(self):
        """⚠ LA RÈGLE, ET C'EST CELLE QUE CALL-E A FAIT RESPECTER. Une seule
        place libérée, une seule date — la présentation et les faits doivent
        dire la MÊME."""
        base, prefs, campagne, configuration = self._campagne_a_deux_places()
        contact = base.contacts_de_campagne(campagne["id"])[1]
        mission = assistant.finaliser_mission(
            campagne["mission"], contact,
            assistant.champs_campagne(configuration))
        texte = assistant.consigne_de_l_appel(
            base, prefs, campagne, configuration, contact, mission,
            True).texte()
        ouverture = texte.split("mot pour mot :")[1].split("\n\n")[0]
        faits = [l for l in texte.splitlines()
                 if l.strip().startswith("- Créneau libéré")]
        self.assertTrue(faits, "le fait « Créneau libéré » a disparu")
        # ⚠ ON COMPARE LES DATES NUES, PAS LES PHRASES. La présentation écrit
        # « une place s'est libérée LE vendredi… » et le fait écrit « Créneau
        # libéré : vendredi… » : l'article diffère, la date ne doit pas.
        en_cours = themes.date_parlee(campagne["creneau"])
        prise = themes.date_parlee(
            assistant.creneaux_de(campagne, configuration)[0]["horaire"])
        self.assertNotEqual(en_cours, prise,
                            "l'essai ne mesure rien : une seule date en jeu")
        self.assertIn(en_cours, ouverture)
        self.assertIn(en_cours, faits[0])
        # ⚠ ET LA PLACE DÉJÀ POURVUE N'APPARAÎT NULLE PART : c'est elle qui
        # créait la contradiction que CALL-E a refusée.
        self.assertNotIn(prise, ouverture)
        self.assertNotIn(prise, faits[0])

    def test_la_configuration_suit_la_place_en_cours(self):
        """La correction DE FOND : ce qui est écrit en base est juste."""
        base, prefs, campagne, configuration = self._campagne_a_deux_places()
        relue = assistant.configuration_campagne(
            base.obtenir_campagne(campagne["id"]))
        self.assertEqual(relue["infos"]["creneau_libere"],
                         campagne["creneau"])

    def test_une_campagne_DEJA_enregistree_de_travers_repart_juste(self):
        """⚠ LE SECOND VERROU, ET IL RÉPARE LE PASSÉ. Sa campagne n°133 porte
        déjà la mauvaise information en base : sans ce verrou de lecture, la
        reprendre aurait renvoyé exactement la même tâche contradictoire, et
        CALL-E l'aurait refusée une seconde fois.

        On abîme donc la configuration EXPRÈS, comme la sienne, et l'on
        vérifie que la consigne reste juste."""
        base, prefs, campagne, configuration = self._campagne_a_deux_places()
        ancienne = assistant.creneaux_de(campagne, configuration)[0]["horaire"]
        self.assertNotEqual(ancienne, campagne["creneau"])
        abimee = dict(configuration)
        abimee["infos"] = dict(configuration["infos"],
                               creneau_libere=ancienne)
        contact = base.contacts_de_campagne(campagne["id"])[1]
        mission = assistant.finaliser_mission(
            campagne["mission"], contact, assistant.champs_campagne(abimee))
        texte = assistant.consigne_de_l_appel(
            base, prefs, campagne, abimee, contact, mission, True).texte()
        faits = [l for l in texte.splitlines()
                 if l.strip().startswith("- Créneau libéré")]
        self.assertIn(themes.date_parlee(campagne["creneau"]), faits[0])
        self.assertNotIn(themes.date_parlee(ancienne), faits[0])

    def test_sans_place_en_cours_on_ne_touche_a_rien(self):
        """LA CONTRE-ÉPREUVE : le verrou ne doit pas écraser une information
        quand la campagne n'a pas de créneau — les autres natures n'en ont
        aucun, et leurs informations doivent passer intactes."""
        infos = {"creneau_libere": "2026-09-02T09:40", "entreprise": "X"}
        for campagne in ({"nature": "creneau_libere", "creneau": None},
                         {"nature": "confirmation", "creneau": "2026-10-02T09:40"}):
            with self.subTest(campagne=campagne):
                self.assertEqual(
                    assistant.infos_sur_la_place_en_cours(
                        campagne, {"infos": infos}),
                    infos)


class TestCurseurDePlaceEnPlace(unittest.TestCase):
    """Une campagne à LISTE passe d'une place à la suivante (03/08/2026).

    ⚠ L'ESSAI CENTRAL est `test_chaque_oui_prend_une_place_differente` : la
    revue avait trouvé que la campagne, lue une seule fois en mémoire,
    écrivait tous les OUI sur le PREMIER créneau — deux personnes à la même
    heure. C'est le défaut le plus grave de tout ce chantier.
    """

    def _monter(self, nb_places, mission_editee=False, contacts=3):
        base = db.Base(":memory:")
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        # ⚠ LA PLAGE D'APPEL COUVRE TOUTE LA JOURNÉE, sinon l'essai dépend de
        # L'HEURE QU'IL EST : lancé après 19 h, le garde-fou de politesse met
        # la campagne en pause et l'essai échoue sans qu'aucun code n'ait
        # bougé. Constaté le 03/08/2026 à 19 h 06.
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        depart = (datetime.datetime.now() + datetime.timedelta(days=1)).replace(
            hour=9, minute=0, second=0, microsecond=0)
        places = [depart + datetime.timedelta(hours=2 * rang)
                  for rang in range(nb_places)]
        lignes = []
        for rang in range(contacts):
            # ⚠ TOUS LE MÊME NUMÉRO DE FICTION, et c'est voulu : la série
            # documentée n'autorise que ses deux derniers chiffres à varier
            # (06 + six zéros + XX), et ce sont eux qui forceraient l'issue.
            # Trois numéros différents finissant tous par « 51 » n'existent
            # donc pas. L'issue est imposée autrement, par un client d'appels
            # FIXE — c'est plus honnête : l'essai ne dépend plus d'un hasard
            # ni d'une convention de numéro.
            telephone = "+33 6 00 00 00 51"
            client = base.ajouter_client(f"Mme A{rang + 1}", telephone)
            rdv = base.ajouter_rendezvous(
                client, (depart + datetime.timedelta(days=20 + rang * 3))
                .isoformat(timespec="minutes"), "Bilan", statut="confirmé")
            lignes.append((f"Mme A{rang + 1}", telephone, rdv))
        brouillon = {
            "nature": "creneau_libere",
            "infos": {"creneau_libere": places[0].isoformat(timespec="minutes"),
                      "entreprise": "Cabinet Essai"},
            "infos_auto": {}, "politique": "premier_oui",
            "ordre": "eloignement",
            "options": {"liberer_creneau": True, "cascade": True},
            "champs": [dict(c)
                       for c in assistant.NATURES["creneau_libere"]["champs"]],
            "mission": "Bonjour, une place s'est libérée.",
            "mission_editee": mission_editee,
            "recette": {"apports": [{"quoi": "base"}], "a_la_main": False},
            "creneaux": assistant.normaliser_creneaux(
                [p.isoformat(timespec="minutes") for p in places]),
            "contacts": [
                {"nom": nom, "telephone": tel, "rendezvous_id": rdv,
                 "champs": {"rdv_existant": base.obtenir_rendezvous(rdv)["horaire"],
                            "motif": "Bilan"}}
                for nom, tel, rdv in lignes]}
        campagne = assistant.creer_campagne_prete(base, brouillon, prefs)

        class ToujoursOui(calle_client.ClientAppels):
            """Un agent qui accepte à chaque fois — aucun hasard dans l'essai."""

            class _Issue:
                def __init__(self, resultat):
                    self.resultat = resultat
                    self.transcription = ""
                    self.identifiant = "appel-essai-1"

                def __getattr__(self, nom):
                    return None

            def appeler_cascade(self, nom, telephone, mission, creneau,
                                consigne=None, nature=None):
                return self._Issue({"outcome": "accepted",
                                    "new_datetime": None, "notes": ""})

            def appeler(self, nom, telephone, rendezvous, mission=None,
                        consigne=None, nature=None):
                return self._Issue({"appointment_status": "confirmed",
                                    "new_datetime": None, "notes": ""})

        class Appli:
            def __init__(self):
                self.base, self.preferences = base, prefs
                self.executions, self.mode_reel = {}, False
                self.planif = planificateur.Planificateur(
                    base, ToujoursOui(), preferences=prefs)

            def commande_execution(self, identifiant):
                return None

            def terminer_execution(self, identifiant):
                pass

        return base, campagne, Appli(), places

    def test_chaque_oui_prend_une_place_differente(self):
        """⚠ LE CONTRÔLE ESSENTIEL : jamais deux personnes à la même heure."""
        base, campagne, appli, places = self._monter(3)
        assistant.executer_campagne(appli, campagne)
        fin = base.obtenir_campagne(campagne)
        pourvues = [f["horaire"] for f in assistant.creneaux_de(fin)
                    if f["statut"] == assistant.CRENEAU_POURVU]
        self.assertEqual(sorted(pourvues),
                         sorted(p.isoformat(timespec="minutes")
                                for p in places))
        # Et en base : trois rendez-vous neufs, à trois heures différentes.
        neufs = sorted(r["horaire"] for r in base.tous_les_rendezvous()
                       if r["statut"] == "confirmé"
                       and r["horaire"] in {p.isoformat(timespec="minutes")
                                            for p in places})
        self.assertEqual(len(neufs), 3)
        self.assertEqual(len(set(neufs)), 3, "deux personnes à la même heure")
        # Chaque place sait QUI l'a prise.
        preneurs = [f["contact_id"] for f in assistant.creneaux_de(fin)
                    if f["statut"] == assistant.CRENEAU_POURVU]
        self.assertEqual(len(set(preneurs)), 3)

    def test_une_seule_place_garde_le_comportement_d_avant(self):
        """⚠ « Le décalage en cascade reste tel quel pour les campagnes à un
        seul créneau » — décision du propriétaire. Le drapeau
        « liste_de_places » est ce qui les distingue : compter les places ne
        suffisait pas, puisque toute campagne en porte une depuis le lot 1."""
        base, campagne, appli, _ = self._monter(1)
        configuration = assistant.configuration_campagne(
            base.obtenir_campagne(campagne))
        self.assertFalse(configuration["liste_de_places"])
        assistant.executer_campagne(appli, campagne)
        etats = [c["etat"] for c in base.contacts_de_campagne(campagne)]
        # Un seul appel abouti, les autres ÉPARGNÉS : l'arrêt au premier oui.
        self.assertEqual(etats.count("accepté"), 1)
        self.assertEqual(etats.count("épargné"), 2)

    def test_plusieurs_places_le_drapeau_est_leve(self):
        base, campagne, _, _ = self._monter(3)
        configuration = assistant.configuration_campagne(
            base.obtenir_campagne(campagne))
        self.assertTrue(configuration["liste_de_places"])

    def test_le_message_suit_la_place_en_cours(self):
        """Sans recalage, l'agent annoncerait la date de la PREMIÈRE place et
        prendrait rendez-vous à une autre heure."""
        base, campagne, appli, places = self._monter(2)
        depart = base.obtenir_campagne(campagne)["mission"]
        assistant.executer_campagne(appli, campagne)
        fin = base.obtenir_campagne(campagne)
        configuration = assistant.configuration_campagne(fin)
        # Le curseur est sur une place de la liste — pas forcément la
        # dernière d'origine : les places RENDUES par ceux qui acceptent s'y
        # ajoutent, et la campagne continue dessus.
        self.assertIn(fin["creneau"],
                      [f["horaire"] for f in assistant.creneaux_de(fin)])
        # ⚠ ET LE MESSAGE DIT CETTE PLACE-LÀ. On le refabrique pour comparer :
        # c'est la seule façon de prouver qu'il annonce la bonne date, sans
        # dépendre de la façon dont la phrase est tournée.
        attendu, infos = assistant.mission_sur_la_place(
            base, appli.preferences, fin, configuration, fin["creneau"])
        self.assertEqual(fin["mission"], attendu)
        # ⚠ ET LA CONFIGURATION SUIT (01/09/2026) : les informations
        # d'étape 2 doivent porter la place EN COURS, pas la précédente.
        # Sans cela, la consigne annonçait deux dates pour une seule place et
        # CALL-E refusait la tâche — voir TestDeuxDatesPourUneSeulePlace.
        code = assistant.INFO_CRENEAU_PAR_NATURE[fin["nature"]]
        self.assertEqual(
            assistant.configuration_campagne(fin)["infos"][code],
            fin["creneau"])
        self.assertNotEqual(fin["mission"], depart)

    def test_un_message_recrit_a_la_main_arrete_la_campagne_et_dit_pourquoi(self):
        """On n'avance PAS : on ne devine pas où est la date dans un texte
        humain, et annoncer la mauvaise heure serait pire que s'arrêter."""
        base, campagne, appli, _ = self._monter(3, mission_editee=True)
        assistant.executer_campagne(appli, campagne)
        fin = base.obtenir_campagne(campagne)
        restantes = [f for f in assistant.creneaux_de(fin)
                     if f["statut"] == assistant.CRENEAU_A_POURVOIR]
        self.assertTrue(restantes, "il devrait rester des places")
        # ⚠ LA RAISON EXACTE, pas « arrêt au premier oui » : c'est ce qu'un
        # opérateur relira pour comprendre pourquoi il reste des places.
        details = [c["detail"] or "" for c in base.contacts_de_campagne(campagne)
                   if c["etat"] == "épargné"]
        self.assertTrue(details, "personne n'a été épargné")
        self.assertIn("récrit à la main", details[0])
        self.assertNotIn("arrêt au premier oui", details[0])

    def test_la_place_quittee_rejoint_la_liste(self):
        base, campagne, appli, places = self._monter(1, contacts=1)
        # Une campagne d'UNE place ne prend pas ce chemin : on en monte une à
        # deux places pour le voir.
        base, campagne, appli, places = self._monter(2, contacts=1)
        ancien = base.contacts_de_campagne(campagne)[0]["rendezvous_id"]
        quittee = base.obtenir_rendezvous(ancien)["horaire"]
        assistant.executer_campagne(appli, campagne)
        fin = base.obtenir_campagne(campagne)
        horaires_liste = [f["horaire"] for f in assistant.creneaux_de(fin)]
        self.assertIn(quittee, horaires_liste)
        rendue = next(f for f in assistant.creneaux_de(fin)
                      if f["horaire"] == quittee)
        self.assertEqual(rendue["statut"], assistant.CRENEAU_A_POURVOIR)
        self.assertIn("place quittée par", rendue["pourquoi"])
        # Et AUCUNE campagne « prête » séparée : le décalage en cascade est
        # sauté quand une liste existe.
        self.assertEqual(len(base.lister_campagnes()), 1)

    def _appli_qui_dit_autre_date(self, base, prefs, quand):
        """Une application dont l'agent rend TOUJOURS « moved » vers `quand ».

        C'est la réponse réelle qu'on veut éprouver : « oui, mais plutôt la
        deuxième de celles que vous venez de me citer ».
        """
        class AutreDate(calle_client.ClientAppels):
            class _Issue:
                def __init__(self, resultat):
                    self.resultat = resultat
                    self.transcription = ""
                    self.identifiant = "appel-essai-1"

                def __getattr__(self, nom):
                    return None

            def appeler_cascade(self, nom, telephone, mission, creneau,
                                consigne=None, nature=None):
                return self._Issue({"outcome": "moved",
                                    "new_datetime": quand, "notes": ""})

        class Appli:
            def __init__(self):
                self.base, self.preferences = base, prefs
                self.executions, self.mode_reel = {}, False
                self.planif = planificateur.Planificateur(
                    base, AutreDate(), preferences=prefs)

            def commande_execution(self, identifiant):
                return None

            def terminer_execution(self, identifiant):
                pass

        return Appli()

    def test_une_autre_date_prise_PARMI_les_places_annoncees_les_pourvoit(self):
        """⚠ L'ÉCART TROUVÉ PAR L'AUDIT DU 14/08/2026. Quand plusieurs places
        sont annoncées dans le même appel, « une autre date » veut souvent dire
        « une autre de celles que vous venez de me citer ». La branche créait
        alors le rendez-vous dessus SANS marquer la place : elle restait « à
        pourvoir », était réannoncée au contact suivant qui se la voyait
        refuser, puis elle était déclarée « prise entre-temps » — alors que
        c'est CETTE campagne qui l'avait pourvue. « Pourvu par nous » n'est pas
        « pris ailleurs ».
        """
        base, campagne, montage, places = self._monter(3, contacts=3)
        visee = places[1].isoformat(timespec="minutes")
        appli = self._appli_qui_dit_autre_date(base, montage.preferences, visee)
        assistant.executer_campagne(appli, campagne)

        fin = base.obtenir_campagne(campagne)
        statuts = {f["horaire"]: f["statut"]
                   for f in assistant.creneaux_de(fin)}
        # ⚠ LE CŒUR : la place prise est POURVUE, pas laissée à pourvoir, et
        # certainement pas « perdue » — ce n'est pas un tiers qui l'a prise,
        # c'est cette campagne.
        self.assertEqual(statuts[visee], assistant.CRENEAU_POURVU)
        self.assertNotIn(assistant.CRENEAU_PERDU, statuts.values())
        # Un seul rendez-vous sur cette place : jamais deux personnes à la
        # même heure.
        occupants = [r for r in base.tous_les_rendezvous()
                     if r["horaire"] == visee
                     and r["statut"] in horaires.STATUTS_OCCUPANTS]
        self.assertEqual(len(occupants), 1)
        # Et l'écran ne dit plus « le créneau libéré reste à pourvoir » à
        # quelqu'un qui vient justement d'en prendre un.
        contacts = base.contacts_de_campagne(campagne)
        preneurs = [c for c in contacts if c["etat"] == "accepté"]
        self.assertEqual(len(preneurs), 1)
        self.assertIn("elle est pourvue", preneurs[0]["detail"])
        self.assertNotIn("reste à pourvoir", preneurs[0]["detail"])
        # La place sait QUI l'a prise — c'est ce qui distingue « pourvu » de
        # « perdu » sur la fiche.
        fiche = next(f for f in assistant.creneaux_de(fin)
                     if f["horaire"] == visee)
        self.assertEqual(fiche["contact_id"], preneurs[0]["id"])

    def test_une_autre_date_hors_des_places_ne_pourvoit_rien(self):
        """Le cas ordinaire de « moved » ne change pas d'un caractère : la date
        convenue est à elle, le créneau libéré reste à pourvoir."""
        base, campagne, montage, places = self._monter(2, contacts=2)
        ailleurs = (places[0] + datetime.timedelta(days=9)).isoformat(
            timespec="minutes")
        appli = self._appli_qui_dit_autre_date(base, montage.preferences,
                                               ailleurs)
        assistant.executer_campagne(appli, campagne)
        statuts = [f["statut"] for f in assistant.creneaux_de(
            base.obtenir_campagne(campagne))]
        self.assertEqual(set(statuts), {assistant.CRENEAU_A_POURVOIR})
        details = " ".join(c["detail"] or ""
                          for c in base.contacts_de_campagne(campagne))
        self.assertIn("le créneau libéré reste à pourvoir", details)

    def test_une_autre_date_ne_prepare_pas_de_campagne_sans_l_option(self):
        """⚠ L'AUTRE ÉCART DE LA MÊME BRANCHE : elle appelait _suite_de_cascade
        DIRECTEMENT, sautant l'option « décaler en cascade » et le partage des
        deux chemins. Sur une campagne à liste, elle fabriquait donc une
        campagne préparée à côté — pendant que la fiche annonçait « la place
        quittée rejoint cette campagne ». L'écran disait l'un, le produit
        faisait l'autre."""
        base, campagne, montage, places = self._monter(3, contacts=3)
        # L'option est cochée par le montage, mais SANS date limite : le chemin
        # « liste » agit, le chemin « campagne préparée » ne doit pas.
        ailleurs = (places[0] + datetime.timedelta(days=9)).isoformat(
            timespec="minutes")
        appli = self._appli_qui_dit_autre_date(base, montage.preferences,
                                               ailleurs)
        assistant.executer_campagne(appli, campagne)
        # AUCUNE campagne préparée à côté.
        self.assertEqual(len(base.lister_campagnes()), 1,
                         [c["nom"] for c in base.lister_campagnes()])
        # La place quittée a bien REJOINT la liste de cette campagne.
        details = " ".join(c["detail"] or ""
                          for c in base.contacts_de_campagne(campagne))
        self.assertIn("rejoint la liste", details)

    def test_la_boucle_relit_sa_file(self):
        """Une boucle « for » sur une liste figée ne pouvait pas voir une
        place qui s'ajoute, et découper « restants[indice + 1:] » aurait
        indexé une AUTRE liste — des contacts marqués « épargné » à tort."""
        source = inspect.getsource(assistant.executer_campagne)
        self.assertIn("while True:", source)
        self.assertIn("def file_a_appeler():", source)
        self.assertIn("traites", source)
        # ⚠ On interdit la FORME du code, pas le mot : le commentaire qui
        # explique l'ancien défaut cite forcément l'ancienne écriture.
        self.assertNotIn("for indice, contact in enumerate(", source)


class TestAjouterDesContacts(_TestAvecServeurWeb):
    """Étape ③ : la grille et les voies de remplissage ne se regardent plus
    en même temps (demande du propriétaire du 03/08/2026)."""

    def _brouillon(self):
        _, page = self._poster("/assistant/nature", {"nature": "creneau_libere"})
        b = re.search(r'name="b" value="(\d+)"', page).group(1)
        self._poster("/assistant/message", {
            "b": b, "info_entreprise": "Cabinet Essai", "ordre": "eloignement",
            "info_creneau_libere": "2026-08-20T09:00", "action": "continuer"})
        # ⚠ ON BASCULE EN MANUEL : depuis le 09/08/2026 une campagne
        # « créneau libéré » s'ouvre en AUTOMATIQUE, et la grille comme les
        # voies de remplissage n'existent qu'en manuel. Sans ce geste, cette
        # classe éprouverait un écran qui n'est pas affiché.
        self._poster("/assistant/liste", {"b": b, "action": "liste:manuel"})
        return b

    @staticmethod
    def _vues(page):
        """(état de la vue grille, état de la vue ajout)."""
        grille = re.search(
            r'<form method="post" action="/assistant/liste" '
            r'id="form-grille"( hidden)?>', page)
        ajout = re.search(r'id="vue-ajout"[^>]*?( hidden)?>', page)
        return (bool(grille and grille.group(1)),
                bool(ajout and ajout.group(1)))

    def test_le_bouton_bascule_les_deux_vues(self):
        b = self._brouillon()
        page = self._obtenir(f"/assistant/liste?b={b}")[1]
        self.assertIn('class="entete-grille"', page)
        self.assertIn("Ajouter des contacts", page)
        self.assertEqual(self._vues(page), (False, True))   # grille visible
        # Au clic, les voies de remplissage prennent la place de la grille.
        self._poster("/assistant/liste", {"b": b, "action": "vue:ajout"})
        page = self._obtenir(f"/assistant/liste?b={b}")[1]
        self.assertEqual(self._vues(page), (True, False))   # ajout visible
        self.assertIn("Revenir à la grille", page)
        # ⚠ RIEN N'EST RETIRÉ DU HTML : la grille reste dans la page, avec
        # ses valeurs. Sans cela, ouvrir « Ajouter des contacts » aurait
        # effacé ce qui venait d'être corrigé à la main.
        self.assertIn('name="ordre"', page)
        self.assertIn('action="/assistant/liste"', page)
        # Et le retour ramène la grille.
        self._poster("/assistant/liste", {"b": b, "action": "vue:grille"})
        self.assertEqual(
            self._vues(self._obtenir(f"/assistant/liste?b={b}")[1]),
            (False, True))

    def test_un_remplissage_reussi_ramene_a_la_grille(self):
        self.application.base.ajouter_client("Mme Base Une",
                                             "+33 6 00 00 00 61")
        b = self._brouillon()
        self._poster("/assistant/liste", {"b": b, "action": "vue:ajout"})
        self._poster("/assistant/importer",
                     {"b": b, "mode": "clients", "etat_client": ""})
        page = self._obtenir(f"/assistant/liste?b={b}")[1]
        self.assertEqual(self._vues(page), (False, True))   # grille revenue
        self.assertRegex(page, r"Les personnes à appeler \(\d+\)")

    def test_un_remplissage_refuse_reste_sur_sa_voie(self):
        """⚠ Revenir à la grille aurait fait disparaître l'erreur ET la
        saisie : une saisie refusée n'est jamais perdue."""
        b = self._brouillon()
        self._poster("/assistant/liste", {"b": b, "action": "vue:ajout"})
        self._poster("/assistant/importer",
                     {"b": b, "mode": "collage", "liste": "n'importe quoi"})
        page = self._obtenir(f"/assistant/liste?b={b}")[1]
        self.assertEqual(self._vues(page), (True, False))   # on reste
        self.assertIn("n&#x27;importe quoi", page)

    def test_le_titre_est_retire_et_le_bouton_passe_en_bleu(self):
        b = self._brouillon()
        page = self._obtenir(f"/assistant/liste?b={b}")[1]
        self.assertNotIn("<h2>Remplir la grille</h2>", page)
        # Le bouton principal n'est plus « secondaire » : il est en bleu.
        self.assertIn("<button>Ajouter ces personnes à la grille</button>",
                      page)
        self.assertNotIn(
            '<button class="secondaire">Ajouter ces personnes à la grille',
            page)

    def test_le_message_de_grille_vide_ne_ment_plus(self):
        """Il disait « ci-dessous » ; les voies de remplissage n'y sont plus."""
        b = self._brouillon()
        page = self._obtenir(f"/assistant/liste?b={b}")[1]
        self.assertIn("Aucune personne dans la grille", page)
        self.assertIn("Ajouter des contacts", page)
        vide = re.search(r'class="grille-vide">(.*?)</p>', page, re.S).group(1)
        self.assertNotIn("ci-dessous", vide)

    def test_la_bascule_marche_sans_javascript(self):
        """C'est un vrai bouton d'envoi, et la vue vit dans le BROUILLON —
        pas dans une classe CSS. Une bascule qui ne vivrait qu'à l'écran
        aurait laissé les deux moitiés partir ensemble au serveur."""
        b = self._brouillon()
        page = self._obtenir(f"/assistant/liste?b={b}")[1]
        self.assertIn('name="action" value="vue:ajout"', page)
        self._poster("/assistant/liste", {"b": b, "action": "vue:ajout"})
        self.assertEqual(
            self.application.obtenir_brouillon_assistant(b)["vue_liste"],
            "ajout")


class TestSourceARecaser(unittest.TestCase):
    """« Annulés, manqués et en attente » — et « en attente » a une définition.

    Le mot ne désigne aucun statut du produit : il veut dire « déplacé, et
    ce client n'a repris AUCUN rendez-vous ». Sans ce dernier morceau, on
    rappellerait des gens déjà pourvus pour leur offrir une place.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        passe = (datetime.datetime.now() - datetime.timedelta(days=3)).replace(
            hour=9, minute=0, second=0, microsecond=0).isoformat(
                timespec="minutes")
        futur = (datetime.datetime.now() + datetime.timedelta(days=3)).replace(
            hour=9, minute=0, second=0, microsecond=0).isoformat(
                timespec="minutes")
        self.cas = (("Mme Annulée", "annulé", passe, None),
                    ("M. Manqué", "manqué", passe, None),
                    ("Mme Déplacée", "déplacé", passe, None),
                    ("M. Déjà recasé", "déplacé", passe, futur),
                    ("Mme Confirmée", "confirmé", futur, None))
        for rang, (nom, statut, quand, suite) in enumerate(self.cas):
            client = self.base.ajouter_client(nom, f"+33 6 00 00 00 {60 + rang}")
            self.base.ajouter_rendezvous(client, quand, "Bilan", statut=statut)
            if suite:
                self.base.ajouter_rendezvous(client, suite, "Bilan",
                                             statut="confirmé")

    def test_les_trois_statuts_sont_retenus_et_eux_seuls(self):
        noms = [r["nom"] for r in self.base.rendezvous_a_recaser()]
        self.assertEqual(sorted(noms),
                         ["M. Manqué", "Mme Annulée", "Mme Déplacée"])

    def test_celui_qui_a_deja_repris_rendez_vous_est_ecarte(self):
        """⚠ LE « NOT EXISTS » EST LE CŒUR de cette source."""
        noms = [r["nom"] for r in self.base.rendezvous_a_recaser()]
        self.assertNotIn("M. Déjà recasé", noms)
        self.assertNotIn("Mme Confirmée", noms)

    def test_la_source_datee_remplit_la_colonne_obligatoire(self):
        """Sans date de rendez-vous, la grille refuserait ces personnes : la
        nature « créneau libéré » exige cette colonne."""
        champs = [dict(c)
                  for c in assistant.NATURES["creneau_libere"]["champs"]]
        contacts, _ = assistant.contacts_depuis_base(
            self.base, "a_recaser", champs, [])
        self.assertEqual(len(contacts), 3)
        for contact in contacts:
            with self.subTest(nom=contact["nom"]):
                self.assertTrue(contact["champs"].get("rdv_existant"))

    def test_une_source_inconnue_ne_devient_plus_manque_en_silence(self):
        """⚠ LE PIÈGE DE LA REVUE : la table avait « manqué » par défaut. Un
        code neuf y tombait sans bruit — l'écran annonçait une source, la
        grille en contenait une autre."""
        self.assertEqual(assistant.STATUT_PAR_SOURCE_DATEE["a_recaser"],
                         "a_recaser")
        with self.assertRaises(KeyError):
            assistant.STATUT_PAR_SOURCE_DATEE["martien"]

    def test_le_libelle_porte_sa_definition(self):
        libelle = assistant.SOURCES_BASE["a_recaser"]
        self.assertIn("annulés, manqués et en attente", libelle)
        self.assertIn("déplacés sans nouveau rendez-vous", libelle)
        self.assertIn("a_recaser", assistant.SOURCES_RENDEZVOUS)
        self.assertIn("a_recaser", assistant.SOURCES_DATEES)


class TestRegleDeListeRejouee(unittest.TestCase):
    """Le mode AUTOMATIQUE ne porte pas une liste : il porte une règle."""

    def _campagne(self, mode="automatique"):
        base = db.Base(":memory:")
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        depart = (datetime.datetime.now() + datetime.timedelta(days=1)).replace(
            hour=9, minute=0, second=0, microsecond=0)
        places = [depart, depart + datetime.timedelta(days=15)]
        for rang, jours in enumerate((3, 25)):
            client = base.ajouter_client(f"Mme {rang}",
                                         f"+33 6 00 00 00 {51 + rang}")
            base.ajouter_rendezvous(
                client, (depart + datetime.timedelta(days=jours)).isoformat(
                    timespec="minutes"), "Bilan", statut="annulé")
        brouillon = {
            "nature": "creneau_libere",
            "infos": {"creneau_libere": places[0].isoformat(timespec="minutes"),
                      "entreprise": "Cabinet Essai"},
            "infos_auto": {}, "politique": "premier_oui",
            "ordre": "eloignement", "options": {"liberer_creneau": True},
            "champs": [dict(c)
                       for c in assistant.NATURES["creneau_libere"]["champs"]],
            "mission": "Bonjour.", "mission_editee": False,
            "recette": {"apports": [], "a_la_main": False},
            "mode_liste": mode,
            "regle_liste": {"source": "a_recaser", "jours": ""},
            "creneaux": assistant.normaliser_creneaux(
                [p.isoformat(timespec="minutes") for p in places]),
            "contacts": []}
        campagne = assistant.creer_campagne_prete(base, brouillon, prefs)
        return base, prefs, campagne, places

    def test_la_regle_est_enregistree_et_jouee_des_la_creation(self):
        """⚠ JOUÉE DÈS LA CRÉATION depuis le 09/08/2026. Elle ne l'était qu'au
        changement de place : la campagne naissait VIDE, et le ▶ Démarrer se
        terminait sans un seul appel. Le mode automatique étant devenu celui
        par défaut, c'était le chemin normal.

        Et la rejouer ensuite n'ajoute personne deux fois — c'est le même
        dédoublonnage par numéro que partout ailleurs.
        """
        base, prefs, campagne, _ = self._campagne()
        configuration = assistant.configuration_campagne(
            base.obtenir_campagne(campagne))
        self.assertEqual(configuration["regle_liste"]["source"], "a_recaser")
        self.assertEqual(len(base.contacts_de_campagne(campagne)), 2)
        ajoutes = assistant.regenerer_la_liste(
            base, prefs, base.obtenir_campagne(campagne), configuration)
        self.assertEqual(ajoutes, 0)
        self.assertEqual(len(base.contacts_de_campagne(campagne)), 2)

    def test_rejouer_deux_fois_n_ajoute_personne_deux_fois(self):
        base, prefs, campagne, _ = self._campagne()
        configuration = assistant.configuration_campagne(
            base.obtenir_campagne(campagne))
        assistant.regenerer_la_liste(
            base, prefs, base.obtenir_campagne(campagne), configuration)
        combien = len(base.contacts_de_campagne(campagne))
        assistant.regenerer_la_liste(
            base, prefs, base.obtenir_campagne(campagne), configuration)
        self.assertEqual(len(base.contacts_de_campagne(campagne)), combien)

    def test_une_campagne_manuelle_ne_regenere_rien(self):
        base, prefs, campagne, _ = self._campagne(mode="manuel")
        configuration = assistant.configuration_campagne(
            base.obtenir_campagne(campagne))
        self.assertFalse(configuration["regle_liste"])
        self.assertEqual(assistant.regenerer_la_liste(
            base, prefs, base.obtenir_campagne(campagne), configuration), 0)

    def test_la_fenetre_part_de_la_place_jamais_d_une_date_absolue(self):
        """⚠ Une période ABSOLUE rendrait la campagne non rejouable : la
        rejouer sur une autre place donnerait les mêmes personnes.

        ⚠ ÉPROUVÉ SUR « poses », PAS SUR « a_recaser » (09/08/2026). Depuis la
        règle de l'intérêt, la fenêtre ne s'applique qu'aux sources de
        rendez-vous À VENIR : ceux qui n'ont plus de rendez-vous du tout sont
        intéressés par n'importe quelle place, et les borner sur leur ancienne
        date — passée par construction — les écartait tous. Ce que cet essai
        garde, c'est que la fenêtre reste RELATIVE À LA PLACE là où elle
        s'applique.
        """
        base, prefs, campagne, places = self._campagne()
        # Les deux rendez-vous du montage sont « annulés » : on les remet
        # « confirmés » pour éprouver la source qui, elle, porte la fenêtre.
        for rdv in base.tous_les_rendezvous():
            base.mettre_a_jour_rendezvous(rdv["id"], statut="confirmé")
        champs = [dict(c)
                  for c in assistant.NATURES["creneau_libere"]["champs"]]
        # ⚠ « JOURS » EST UN GAIN MINIMUM (11/08/2026). Depuis la PREMIÈRE place,
        # « au moins 7 jours » écarte « Mme 0 » — son rendez-vous n'est que
        # 3 jours plus tard, la place ne lui ferait presque rien gagner — et
        # retient « Mme 1 », qui gagnerait 25 jours.
        gain, _ = assistant.contacts_de_la_regle(
            base, prefs, {"source": "poses", "jours": "7"}, champs,
            places[0].isoformat(timespec="minutes"))
        self.assertEqual([c["nom"] for c in gain], ["Mme 1"])
        # ⚠ LA MÊME RÈGLE, DEPUIS UNE AUTRE PLACE, DONNE D'AUTRES GENS. C'est
        # tout l'intérêt : « Mme 0 » est AVANT la seconde place, avancer ne
        # lui apporterait rien ; « Mme 1 », elle, est après.
        loin, _ = assistant.contacts_de_la_regle(
            base, prefs, {"source": "poses", "jours": ""}, champs,
            places[1].isoformat(timespec="minutes"))
        self.assertEqual([c["nom"] for c in loin], ["Mme 1"])
        # Et un gain minimum trop exigeant depuis la seconde place ne trouve
        # personne : le seuil part de LA PLACE, il est donc relatif lui aussi.
        aucun, _ = assistant.contacts_de_la_regle(
            base, prefs, {"source": "poses", "jours": "30"}, champs,
            places[1].isoformat(timespec="minutes"))
        self.assertEqual(aucun, [])

    def test_la_fenetre_dit_combien_elle_a_ecarte_et_pourquoi(self):
        """⚠ LE DÉFAUT QUE CET ESSAI INTERDIT (11/08/2026). La borne écartait du
        monde SANS UN MOT. Le propriétaire a monté une campagne sur une place
        libre et n'a vu que cinq personnes « au lieu de beaucoup » : la règle
        avait raison, mais un compte sans sa raison se lit comme un défaut.
        """
        base, prefs, campagne, places = self._campagne()
        for rdv in base.tous_les_rendezvous():
            base.mettre_a_jour_rendezvous(rdv["id"], statut="confirmé")
        champs = [dict(c)
                  for c in assistant.NATURES["creneau_libere"]["champs"]]
        # Depuis la SECONDE place, « Mme 0 » est écartée : son rendez-vous est
        # avant. L'écran doit le dire, avec le nombre.
        retenus, notes = assistant.contacts_de_la_regle(
            base, prefs, {"source": "poses", "jours": ""}, champs,
            places[1].isoformat(timespec="minutes"))
        self.assertEqual(len(retenus), 1)
        self.assertTrue(any("1 personne(s) écartée(s)" in note
                            for note in notes), notes)
        self.assertTrue(any("ne leur ferait rien gagner" in note
                            for note in notes), notes)
        # Et quand un GAIN MINIMUM est réglé, la phrase le nomme : sans cela,
        # « écartée » resterait à moitié expliqué.
        _, avec_minimum = assistant.contacts_de_la_regle(
            base, prefs, {"source": "poses", "jours": "30"}, champs,
            places[1].isoformat(timespec="minutes"))
        self.assertTrue(any("gagner 30 jours" in note
                            for note in avec_minimum), avec_minimum)

    def test_le_reglage_des_jours_est_un_GAIN_MINIMUM(self):
        """⚠ LA DÉFINITION DU PROPRIÉTAIRE, MOT POUR MOT (11/08/2026) : « jusqu'à
        30 jours après, cela signifie qu'on va demander les personnes à partir de
        la date du rendez-vous + 30 j (date de début), et la date de fin est le
        dernier rendez-vous enregistré, donc le rendez-vous le plus dans le
        futur ».

        LE DÉFAUT QUE CET ESSAI INTERDIT : le réglage faisait l'INVERSE. Il
        fermait la fenêtre à 30 jours et retenait donc ceux qui gagnaient le
        moins — mesuré sur le jeu d'essai : « jusqu'à 7 jours » rendait dix
        personnes qui gagnaient de 0 à 6 jours. Une place libérée sert à faire
        gagner du temps.
        """
        base, prefs, campagne, places = self._campagne()
        for rdv in base.tous_les_rendezvous():
            base.mettre_a_jour_rendezvous(rdv["id"], statut="confirmé")
        champs = [dict(c)
                  for c in assistant.NATURES["creneau_libere"]["champs"]]
        place = places[0]
        # Le montage : « Mme 0 » gagne 3 jours, « Mme 1 » en gagne 25.
        for minimum, attendus in (("", ["Mme 0", "Mme 1"]),
                                  ("7", ["Mme 1"]),
                                  ("30", [])):
            with self.subTest(minimum=minimum or "peu importe"):
                retenus, _ = assistant.contacts_de_la_regle(
                    base, prefs, {"source": "poses", "jours": minimum}, champs,
                    place.isoformat(timespec="minutes"))
                self.assertEqual(sorted(c["nom"] for c in retenus), attendus)
        # ⚠ ET IL N'Y A PAS DE FIN : le dernier rendez-vous enregistré ferme la
        # liste tout seul. « Mme 1 » est à 25 jours et reste retenue même avec
        # un minimum de 7 — c'est exactement ce qui n'était pas le cas avant.
        loin, _ = assistant.contacts_de_la_regle(
            base, prefs, {"source": "poses", "jours": "7"}, champs,
            place.isoformat(timespec="minutes"))
        self.assertIn("Mme 1", [c["nom"] for c in loin])

    def test_les_intitules_disent_un_minimum_pas_une_limite(self):
        """CLIQUET SUR LES MOTS. Le libellé et le calcul doivent aller ensemble :
        c'est leur désaccord qui a coûté deux essais au propriétaire."""
        libelles = dict(assistant.JOURS_APRES)
        self.assertEqual(libelles[""], "peu importe")
        for jours in ("7", "30", "90"):
            self.assertEqual(libelles[jours], f"au moins {jours} jours")
            self.assertNotIn("jusqu'à", libelles[jours])

    def test_ce_que_la_regle_a_ecarte_est_ecrit_sur_la_campagne(self):
        """Écrit sur la campagne, pas recalculé à l'affichage : la fiche est
        relue longtemps après, et un second calcul donnerait un autre chiffre.
        """
        # ⚠ EN MODE MANUEL, donc une campagne qui naît SANS liste : les deux
        # personnes ne sont pas déjà dedans. Le dédoublonnage par numéro écarte
        # ce qui est déjà présent — une campagne déjà remplie n'a plus rien à
        # écarter, et l'essai ne mesurerait rien.
        base, prefs, campagne, places = self._campagne(mode="manuel")
        for rdv in base.tous_les_rendezvous():
            base.mettre_a_jour_rendezvous(rdv["id"], statut="confirmé")
        configuration = assistant.configuration_campagne(
            base.obtenir_campagne(campagne))
        configuration["regle_liste"] = {"source": "poses", "jours": ""}
        base.definir_configuration_campagne(
            campagne, json.dumps(configuration, ensure_ascii=False))
        base.definir_creneau_campagne(
            campagne, places[1].isoformat(timespec="minutes"), "Bonjour.")
        assistant.regenerer_la_liste(
            base, prefs, base.obtenir_campagne(campagne),
            assistant.configuration_campagne(base.obtenir_campagne(campagne)))
        jouee = assistant.configuration_campagne(
            base.obtenir_campagne(campagne))["regle_jouee"]
        self.assertEqual(jouee["creneau"],
                         places[1].isoformat(timespec="minutes"))
        self.assertTrue(any("écartée(s)" in note for note in jouee["notes"]),
                        jouee)
        # Et l'écran de la campagne le montre — c'est là que ça compte.
        bandeau = assistant_web.RoutesAssistant._bandeau_regle_jouee(
            {"regle_jouee": jouee})
        self.assertIn("Liste établie par la règle", bandeau)
        self.assertIn("écartée(s)", bandeau)


class TestPlafondDeContacts(unittest.TestCase):
    """⚠ LA DEMANDE DU 11/08/2026, mot pour mot : « un champ pour limiter le
    nombre de contact à charger dans l'étape 3 pour limiter le nombre d'appel ».

    Deux propriétés que ces essais tiennent, et qui ne vont pas de soi :
    · le plafond limite CE QUI ENTRE, il ne taille jamais ce qui est déjà là ;
    · il garde les plus PERTINENTS, pas les premiers venus.
    """

    def _contacts(self, combien):
        """`combien` contacts, du rendez-vous le plus proche au plus lointain."""
        depart = datetime.datetime.now() + datetime.timedelta(days=2)
        return [{"nom": f"Mme N{rang:02d}", "telephone": "",
                 "champs": {"rdv_existant": (
                     depart + datetime.timedelta(days=rang)
                 ).isoformat(timespec="minutes")}}
                for rang in range(combien)]

    def test_sans_plafond_rien_n_est_ecarte(self):
        """Le chemin d'avant reste le chemin d'avant — et l'ordre n'est pas
        touché non plus : un plafond vide ne doit RIEN faire."""
        contacts = self._contacts(12)
        for vide in ("", None, "0", "beaucoup", "-3"):
            with self.subTest(plafond=vide):
                self.assertIsNone(assistant.plafond_de({"plafond": vide}))
                gardes, ecartes = assistant.limiter_au_plafond(
                    contacts, assistant.plafond_de({"plafond": vide}),
                    ordre="eloignement")
                self.assertEqual(ecartes, 0)
                self.assertEqual([c["nom"] for c in gardes],
                                 [c["nom"] for c in contacts])

    def test_il_garde_les_plus_pertinents_pas_les_premiers_venus(self):
        """⚠ L'ORDRE D'APPEL DÉCIDE QUI ON GARDE. Sur une campagne de créneau
        libéré, garder « les trois premiers de la base » au lieu des « trois
        dont le rendez-vous est le plus lointain » aurait appelé les gens à qui
        la place apporte le MOINS.
        """
        contacts = self._contacts(10)
        gardes, ecartes = assistant.limiter_au_plafond(
            contacts, 3, ordre="eloignement")
        self.assertEqual(ecartes, 7)
        self.assertEqual([c["nom"] for c in gardes],
                         ["Mme N09", "Mme N08", "Mme N07"])
        # L'ordre inverse garde les autres : c'est bien l'ordre qui décide.
        proches, _ = assistant.limiter_au_plafond(
            contacts, 3, ordre="anciennete")
        self.assertEqual([c["nom"] for c in proches],
                         ["Mme N00", "Mme N01", "Mme N02"])

    def test_les_presents_comptent_dans_le_plafond_sans_etre_touches(self):
        """⚠ IL NE TAILLE JAMAIS CE QUI EST DÉJÀ LÀ. Une ligne tapée à la main
        n'est pas retirée par un plafond réglé après coup — mais elle occupe
        bien une place, sinon le plafond ne plafonnerait rien.
        """
        gardes, ecartes = assistant.limiter_au_plafond(
            self._contacts(10), 5, ordre="liste", deja=3)
        self.assertEqual(len(gardes), 2)
        self.assertEqual(ecartes, 8)
        # Plafond DÉJÀ atteint : plus rien n'entre, et rien n'est retiré.
        gardes, ecartes = assistant.limiter_au_plafond(
            self._contacts(10), 5, ordre="liste", deja=9)
        self.assertEqual(gardes, [])
        self.assertEqual(ecartes, 10)

    def test_la_raison_dit_le_nombre_et_le_plafond(self):
        """Un compte sans sa raison se lit comme un défaut. Vide quand il n'y a
        rien à dire : un message qui apparaît pour rien ne se lit plus."""
        self.assertEqual(assistant.raison_plafond(5, 0), "")
        phrase = assistant.raison_plafond(5, 12)
        self.assertIn("12 personne(s) écartée(s)", phrase)
        self.assertIn("réglée au maximum sur 5 personne(s)", phrase)
        self.assertNotIn("plafond", phrase.lower())


class TestPlafondSurLaRegleAutomatique(unittest.TestCase):
    """Le plafond tient AUSSI quand la règle est rejouée de place en place."""

    def _campagne(self, plafond):
        base = db.Base(":memory:")
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        depart = (datetime.datetime.now() + datetime.timedelta(days=2)).replace(
            hour=9, minute=0, second=0, microsecond=0)
        # Dix personnes qui attendent une place : la source « à recaser ».
        for rang in range(10):
            client = base.ajouter_client(f"Mme R{rang:02d}",
                                         f"+33 6 00 00 00 {rang:02d}")
            base.ajouter_rendezvous(
                client, (depart - datetime.timedelta(days=10 + rang)
                         ).isoformat(timespec="minutes"),
                "Bilan", statut="déplacé")
        places = [depart + datetime.timedelta(days=7 * n) for n in range(3)]
        campagne = assistant.creer_campagne_prete(base, {
            "nature": "creneau_libere",
            "infos": {"creneau_libere": places[0].isoformat(timespec="minutes"),
                      "entreprise": "Cabinet Essai"},
            "infos_auto": {}, "politique": "premier_oui",
            "ordre": "eloignement", "options": {"liberer_creneau": True},
            "champs": [dict(c)
                       for c in assistant.NATURES["creneau_libere"]["champs"]],
            "mission": "Bonjour.", "mission_editee": False,
            "recette": {"apports": [], "a_la_main": False},
            "mode_liste": "automatique",
            "regle_liste": {"source": "a_recaser", "jours": ""},
            "plafond": plafond,
            "creneaux": assistant.normaliser_creneaux(
                [p.isoformat(timespec="minutes") for p in places]),
            "contacts": []}, prefs)
        return base, prefs, campagne

    def test_la_regle_respecte_le_plafond_des_la_creation(self):
        base, _, campagne = self._campagne("4")
        self.assertEqual(len(base.contacts_de_campagne(campagne)), 4)
        configuration = assistant.configuration_campagne(
            base.obtenir_campagne(campagne))
        self.assertEqual(configuration["plafond"], "4")
        notes = configuration["regle_jouee"]["notes"]
        self.assertTrue(any("au maximum sur 4 personne(s)" in note
                            for note in notes),
                        notes)

    def test_le_plafond_ne_se_renouvelle_pas_a_chaque_place(self):
        """⚠ LE DÉFAUT QUE CET ESSAI INTERDIT. La règle est rejouée à CHAQUE
        place : un plafond qui ne compterait que les nouveaux venus laisserait
        entrer quatre personnes de plus par place — une campagne à trois places
        en aurait appelé douze avec un plafond de quatre.
        """
        base, prefs, campagne = self._campagne("4")
        for _ in range(3):
            assistant.regenerer_la_liste(
                base, prefs, base.obtenir_campagne(campagne),
                assistant.configuration_campagne(
                    base.obtenir_campagne(campagne)))
        self.assertEqual(len(base.contacts_de_campagne(campagne)), 4)

    def test_sans_plafond_la_regle_prend_tout_le_monde(self):
        base, _, campagne = self._campagne("")
        self.assertEqual(len(base.contacts_de_campagne(campagne)), 10)
        configuration = assistant.configuration_campagne(
            base.obtenir_campagne(campagne))
        self.assertNotIn("plafond", configuration)


class TestServeurReglagesDisque(unittest.TestCase):
    """Les réglages survivent à un redémarrage (donnees/preferences.json)."""

    def test_reglages_relus_apres_redemarrage(self):
        dossier = tempfile.mkdtemp(prefix="ringback-reglages-")
        self.addCleanup(shutil.rmtree, dossier, ignore_errors=True)
        chemin_base = os.path.join(dossier, "ringback.db")

        def demarrer():
            serveur_http = serveur.creer_serveur(port=0, chemin_base=chemin_base)
            threading.Thread(target=serveur_http.serve_forever, daemon=True).start()
            return serveur_http, f"http://127.0.0.1:{serveur_http.server_address[1]}"

        premier, racine = demarrer()
        octets = urllib.parse.urlencode({
            "entreprise": "Cabinet Persistant", "plage_debut": "10:00",
            "plage_fin": "17:00"}).encode("utf-8")
        urllib.request.urlopen(racine + "/reglages/enregistrer", data=octets,
                               timeout=15).read()
        octets = urllib.parse.urlencode(
            {"creneau": "2026-08-01T14:00"}).encode("utf-8")
        urllib.request.urlopen(racine + "/reglages/creneau-ajouter", data=octets,
                               timeout=15).read()
        chemin_prefs = os.path.join(dossier, "preferences.json")
        with open(chemin_prefs, encoding="utf-8") as fichier:
            contenu = json.load(fichier)
        self.assertEqual(contenu["entreprise"], "Cabinet Persistant")
        self.assertEqual(contenu["plage_debut"], "10:00")
        self.assertEqual(contenu["creneaux_disponibles"], ["2026-08-01T14:00"])
        premier.RequestHandlerClass.application.base.fermer()
        premier.shutdown()
        premier.server_close()
        second, racine = demarrer()                        # redémarrage : relu
        with urllib.request.urlopen(racine + "/reglages", timeout=15) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn('value="Cabinet Persistant"', page)
        self.assertIn('value="10:00"', page)
        # Le créneau ne s'affiche plus sur la page (sous-partie retirée le
        # 03/08/2026) : on le relit là où il vit encore, dans son fragment.
        with urllib.request.urlopen(racine + "/reglages/creneaux",
                                    timeout=15) as reponse:
            self.assertIn("le 01/08/2026 à 14h00",
                          reponse.read().decode("utf-8"))
        second.RequestHandlerClass.application.base.fermer()
        second.shutdown()
        second.server_close()


class TestServeurInterface(_TestAvecServeurWeb):
    """Le lot « belle interface » : bannière, onglets, bascule, pastilles."""

    def test_banniere_logo_et_navigation(self):
        _, page = self._obtenir("/")
        self.assertIn("RingBack", page)
        self.assertIn("Campagnes d'appels par thème, relances programmées", page)
        self.assertIn("<svg", page)                         # logo SVG en ligne
        for libelle in ("📣 Campagnes", "🔁 Relances", "📅 Rendez-vous",
                        "👥 Contacts", "⚙ Réglages"):
            self.assertIn(libelle, page)
        self.assertIn('class="actif"', page)                # onglet actif marqué

    def test_bascule_clair_sombre_presente_et_memorisee(self):
        _, page = self._obtenir("/")
        self.assertIn('id="btn-theme"', page)               # le bouton ☾/☀
        self.assertIn("prefers-color-scheme: dark", page)   # détection système
        self.assertIn("localStorage.getItem('rb-theme')", page)   # mémorisé
        self.assertIn("localStorage.setItem('rb-theme'", page)
        self.assertIn(":root {", page)                      # variables clair
        self.assertIn('[data-theme="dark"]', page)          # variables sombre

    def test_pastilles_de_statut_colorees(self):
        base = self.application.base
        client_id = base.ajouter_client("Mme Palette Exemple", "+33 6 00 00 00 45")
        for statut in ("prévu", "confirmé", "annulé", "déplacé", "ignoré"):
            base.ajouter_rendezvous(client_id, DEMAIN, f"Essai {statut}",
                                    statut=statut)
        _, page = self._obtenir("/tous")
        for classe in ("st-prevu", "st-manque", "st-confirme", "st-annule",
                       "st-ignore", "st-deplace"):
            self.assertIn(classe, page)                     # 6 couleurs en jeu


class TestServeurRappelSouhaite(_TestAvecServeurWeb):
    """Le champ optionnel « date/heure de rappel souhaitée » d'un rendez-vous."""

    def test_ajout_affichage_et_optionnel(self):
        donnees = urllib.parse.urlencode({
            "nom": "Mme Rappel Choisi", "telephone": "+33 6 00 00 00 47",
            "date_heure": HIER, "motif": "Essai",
            "rappel_souhaite": "2026-08-03T15:00"}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            confirmation = reponse.read().decode("utf-8")
        self.assertIn("Rendez-vous enregistré", confirmation)
        self.assertIn("🔔 Rappel souhaité : 03/08/2026 à 15h00", confirmation)
        # Affiché dans 🗂 Tous les rendez-vous (la liste des manqués de la
        # page 📅 Rendez-vous a été retirée le 10/08/2026).
        # Et sur « Tous les rendez-vous ».
        _, tous = self._obtenir("/tous")
        self.assertIn("🔔 rappel souhaité", tous)
        # Le champ reste optionnel : sans lui, rien ne s'affiche en plus.
        donnees = urllib.parse.urlencode({
            "nom": "M. Sans Souhait", "telephone": "+33 6 00 00 00 48",
            "date_heure": DEMAIN, "motif": "Essai",
            "rappel_souhaite": ""}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            confirmation = reponse.read().decode("utf-8")
        self.assertIn("Rendez-vous enregistré", confirmation)
        self.assertNotIn("🔔", confirmation.split("<h1>")[1].split("</p>")[0])

    def test_rappel_souhaite_illisible_refuse(self):
        donnees = urllib.parse.urlencode({
            "nom": "Mme Date Fausse", "telephone": "+33 6 00 00 00 49",
            "date_heure": DEMAIN, "motif": "Essai",
            "rappel_souhaite": "bientôt"}).encode("utf-8")
        with urllib.request.urlopen(self.racine + "/ajouter", data=donnees,
                                    timeout=5) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn("Saisie refusée", page)
        self.assertIn("Rappel souhaité", page)
        self.assertIn("Date illisible", page)



# --------------------------------------------------------------------------
# NOUVEAU MODÈLE : campagnes (thèmes de travail instanciés sur une liste de
# l'instant) et relances programmées. Tout est exercé pour de vrai — base en
# mémoire, jamais la base réelle donnees/ringback.db.
# --------------------------------------------------------------------------
class TestEcheanceRelance(unittest.TestCase):
    """Le délai de relance compté en heures OUVRÉES dans la plage d'appel."""

    def _echeance(self, depart, heures):
        return campagnes.echeance_apres_heures_ouvrees(
            datetime.datetime.fromisoformat(depart), heures, "09:00", "19:00")

    def test_dans_la_plage(self):
        self.assertEqual(self._echeance("2026-07-27T10:00", 4),
                         datetime.datetime(2026, 7, 27, 14, 0))

    def test_a_cheval_sur_deux_jours(self):
        # 18h + 4h ouvrées : 1 h aujourd'hui (18→19), 3 h demain (9→12).
        self.assertEqual(self._echeance("2026-07-27T18:00", 4),
                         datetime.datetime(2026, 7, 28, 12, 0))

    def test_depart_apres_fermeture(self):
        self.assertEqual(self._echeance("2026-07-27T20:00", 2),
                         datetime.datetime(2026, 7, 28, 11, 0))

    def test_depart_avant_ouverture_et_delai_nul(self):
        # Délai 0 : la prochaine ouverture (ou l'instant même s'il est dedans).
        self.assertEqual(self._echeance("2026-07-27T07:00", 0),
                         datetime.datetime(2026, 7, 27, 9, 0))
        self.assertEqual(self._echeance("2026-07-27T11:30", 0),
                         datetime.datetime(2026, 7, 27, 11, 30))


class TestCampagnesModele(unittest.TestCase):
    """Le modèle campagne au niveau module : thèmes, appels, relances."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.prefs = generation.Preferences()
        self.prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        self.prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        self.prefs.definir(campagnes.CLE_RELANCE_DELAI, 0)  # dues tout de suite
        self.planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=8, latence=0))

    # ------------------------------------------------------------- outillage
    def _campagne(self, theme, contacts, mission="Bonjour [client].",
                  creneau=None, sujet=""):
        campagne_id = campagnes.creer_campagne(
            self.base, theme, contacts, mission, creneau=creneau, sujet=sujet)
        campagnes.executer_campagne_initiale(
            self.base, self.planif, self.prefs, campagne_id)
        return campagne_id

    # ------------------------------------------------------ noms et gabarits
    def test_nom_auto_lisible(self):
        quand = datetime.date(2026, 7, 28)
        self.assertEqual(
            campagnes.nom_auto("creneau_libere", creneau="2026-08-03T14:00",
                               quand=quand),
            "Créneau libéré du 03/08 14h — 28/07")
        self.assertIn("2 contact(s)",
                      campagnes.nom_auto("confirmation", nb_contacts=2))
        self.assertEqual(
            campagnes.nom_auto("manque", nb_contacts=3, quand=quand),
            "Rappel de rendez-vous manqués (3 contact(s)) — 28/07")

    def test_un_theme_retire_garde_son_nom_a_l_ecran(self):
        """Retirer un thème ne doit pas rendre ANONYMES les campagnes déjà en
        base : une campagne qu'on ne sait plus nommer est une donnée perdue."""
        self.assertNotIn("contact_unique", campagnes.THEMES_CAMPAGNE)
        self.assertNotIn("personnalise", campagnes.THEMES_CAMPAGNE)
        self.assertEqual(campagnes.libelle_theme("contact_unique"),
                         "Contact unique avec sujet (retiré)")
        self.assertEqual(campagnes.libelle_theme("personnalise"),
                         "Personnalisé (retiré)")
        # Un code jamais vu revient tel quel : on n'invente pas de libellé.
        self.assertEqual(campagnes.libelle_theme("martien"), "martien")
        # Mais on ne peut plus en INSTANCIER : pas de gabarit, donc refus.
        for retire in ("contact_unique", "personnalise"):
            with self.assertRaises(ValueError):
                campagnes.gabarit_mission(retire, self.prefs)

    def test_gabarit_mission_par_theme(self):
        self.prefs.definir(themes.CLE_ENTREPRISE, "Cabinet Essai")
        texte = campagnes.gabarit_mission("manque", self.prefs)
        self.assertIn("Cabinet Essai", texte)
        self.assertNotRegex(texte, r"\d{4}")           # jamais de numéro
        self.assertIn("confirmer", campagnes.gabarit_mission("confirmation",
                                                             self.prefs))
        with self.assertRaises(ValueError):
            campagnes.gabarit_mission("martien", self.prefs)

    def test_analyse_csv_contacts(self):
        personnes, erreurs = campagnes.analyser_csv_contacts(
            "nom;telephone\n"
            "Mme Une Exemple;+33 6 00 00 00 51\n"
            "M. Faux Numero;12345\n"
            "Mme Doublon Exemple;+33 6 00 00 00 51\n")
        self.assertEqual([p["nom"] for p in personnes], ["Mme Une Exemple"])
        self.assertEqual(len(erreurs), 2)
        # L'ancien format 4 colonnes est toléré (colonnes en plus ignorées).
        personnes, erreurs = campagnes.analyser_csv_contacts(
            "nom;telephone;date_heure;motif\n"
            f"Mme Complete Exemple;0600000052;{DEMAIN};Essai\n")
        self.assertEqual(erreurs, [])
        self.assertEqual(personnes[0]["telephone"], "06 00 00 00 52")
        with self.assertRaises(saisie.SaisieInvalide):
            campagnes.analyser_csv_contacts("prenom;tel\nA;B\n")

    def test_contacts_depuis_rendezvous_exclusions(self):
        libre = self.base.ajouter_client("Mme Libre Exemple", "+33 6 00 00 00 41")
        rdv_libre = self.base.ajouter_rendezvous(libre, DEMAIN, "Essai")
        stop = self.base.ajouter_client("M. Stop Exemple", "+33 6 00 00 00 42")
        self.base.ajouter_rendezvous(stop, DEMAIN, "Essai")
        self.base.definir_ne_plus_appeler(stop, True)
        sans = self.base.ajouter_client("Mme Sans Fil", "")
        self.base.ajouter_rendezvous(sans, DEMAIN, "Essai")
        contacts, sans_numero, exclus_stop = campagnes.contacts_depuis_rendezvous(
            self.base, "prévu")
        self.assertEqual([c["nom"] for c in contacts], ["Mme Libre Exemple"])
        self.assertEqual(contacts[0]["rendezvous_id"], rdv_libre)
        self.assertEqual((sans_numero, exclus_stop), (1, 1))

    # --------------------------------------------- une campagne par thème
    def test_campagne_confirmation_liee_a_la_base(self):
        client_id = self.base.ajouter_client("Mme Sure Exemple",
                                             "+33 6 00 00 00 51")
        rdv_id = self.base.ajouter_rendezvous(client_id, DEMAIN, "Bilan annuel")
        campagne_id = self._campagne(
            "confirmation",
            [{"nom": "Mme Sure Exemple", "telephone": "+33 6 00 00 00 51",
              "rendezvous_id": rdv_id}])
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual((contact["etat"], contact["issue"]),
                         ("abouti", "confirmed"))
        self.assertEqual(contact["telephone_masque"], "+33 6 •• •• •• 51")
        self.assertNotIn("telephone", contact)      # le brut ne sort pas
        # Le rendez-vous LIÉ a été confirmé par la logique existante.
        self.assertEqual(self.base.obtenir_rendezvous(rdv_id)["statut"],
                         "confirmé")
        self.assertEqual(self.base.obtenir_campagne(campagne_id)["statut"],
                         "terminée")               # aucune relance à attendre

    def test_deplacement_non_conclu_cree_une_relance_theme_conserve(self):
        """Scénario (c) au niveau module : 55 = déplacement non conclu."""
        client_id = self.base.ajouter_client("M. Hesitant Exemple",
                                             "+33 6 00 00 00 55")
        rdv_id = self.base.ajouter_rendezvous(client_id, DEMAIN, "Contrôle")
        campagne_id = self._campagne(
            "confirmation",
            [{"nom": "M. Hesitant Exemple", "telephone": "+33 6 00 00 00 55",
              "rendezvous_id": rdv_id}],
            mission="Bonjour [client], je confirme votre rendez-vous [date_rdv].")
        # Rien n'est conclu : le rendez-vous est INTACT.
        self.assertEqual(self.base.obtenir_rendezvous(rdv_id)["statut"], "prévu")
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual((contact["etat"], contact["issue"]),
                         ("appelé", "to_reschedule"))
        # La relance existe, avec LE thème et LES paramètres de la campagne.
        relances = self.base.relances_de_campagne(campagne_id)
        self.assertEqual(len(relances), 1)
        relance = relances[0]
        self.assertEqual(relance["statut"], "planifiée")
        self.assertEqual(relance["motif"], "déplacement non conclu")
        self.assertEqual(relance["campagne_theme"], "confirmation")
        self.assertEqual(relance["tentative"], 1)
        self.assertEqual(relance["telephone_masque"], "+33 6 •• •• •• 55")
        campagne = self.base.obtenir_campagne(campagne_id)
        self.assertEqual(campagne["statut"], "en cours")
        self.assertIn("je confirme votre rendez-vous", campagne["mission"])

    def test_contact_unique_sans_reponse_puis_relance_aboutie(self):
        """Scénario (b) au niveau module : 56 = pas de réponse, puis oui."""
        campagne_id = self._campagne(
            "contact_unique",
            [{"nom": "Secrétariat Spécialiste", "telephone": "+33 6 00 00 00 56"}],
            mission="Bonjour, rendez-vous pour M. Martin au sujet : [sujet].",
            sujet="Rendez-vous chez le spécialiste pour M. Martin")
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual((contact["etat"], contact["issue"]),
                         ("appelé", "no_answer"))
        dues = self.base.relances_dues()
        self.assertEqual(len(dues), 1)              # délai 0 : due tout de suite
        self.assertEqual(dues[0]["campagne_theme"], "contact_unique")
        self.assertEqual(dues[0]["motif"], "pas de réponse")
        # GESTE humain : on lance les relances dues — cette fois, ça répond.
        comptes = campagnes.executer_relances_dues(self.base, self.planif,
                                                   self.prefs)
        self.assertEqual(len(comptes), 1)
        self.assertTrue(comptes[0]["abouti"])
        self.assertEqual(comptes[0]["issue"], "confirmed")
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(contact["etat"], "abouti")
        # La chaîne est close : plus aucune relance planifiée, campagne finie.
        self.assertEqual(self.base.relances_dues(), [])
        self.assertEqual(self.base.obtenir_campagne(campagne_id)["statut"],
                         "terminée")
        # L'appel abouti a créé le rendez-vous obtenu (client sans lien rdv).
        rdv = self.base.tous_les_rendezvous()[0]
        self.assertEqual(rdv["nom"], "Secrétariat Spécialiste")
        self.assertEqual(rdv["statut"], "confirmé")

    def test_max_tentatives_puis_abandon(self):
        self.prefs.definir(campagnes.CLE_RELANCE_MAX, 2)
        campagne_id = self._campagne(
            "contact_unique",
            [{"nom": "M. Toujours Absent", "telephone": "+33 6 00 00 00 53"}],
            mission="Bonjour.", sujet="Relance fournisseur")
        # Relance 1 puis relance 2 : toujours pas de réponse.
        for tentative in (1, 2):
            dues = self.base.relances_dues()
            self.assertEqual(len(dues), 1)
            self.assertEqual(dues[0]["tentative"], tentative)
            comptes = campagnes.executer_relances_dues(self.base, self.planif,
                                                       self.prefs)
            self.assertFalse(comptes[0]["abouti"])
        # Maximum atteint : chaîne abandonnée, RIEN de nouveau n'est planifié.
        self.assertEqual(self.base.relances_dues(), [])
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(contact["etat"], "abandonné")
        self.assertEqual(self.base.obtenir_campagne(campagne_id)["statut"],
                         "terminée")
        # Trace complète : appel initial + 2 relances.
        appels = self.base.appels_du_contact_campagne(contact["id"])
        self.assertEqual([a["tentative"] for a in appels], [0, 1, 2])

    def test_cascade_pourvue_aucune_relance(self):
        personnes = [
            {"nom": "Mme Refus Un", "telephone": "+33 6 00 00 00 52"},
            {"nom": "Mme Accord Deux", "telephone": "+33 6 00 00 00 51"},
            {"nom": "M. Epargne Trois", "telephone": "+33 6 00 00 00 49"},
        ]
        cascade_id = self.planif.executer_cascade(personnes, "Mission.", DEMAIN)
        campagne_id = campagnes.campagne_depuis_cascade(
            self.base, self.prefs, cascade_id, personnes, "Mission.", DEMAIN)
        campagne = self.base.obtenir_campagne(campagne_id)
        self.assertEqual(campagne["cascade_id"], cascade_id)
        self.assertEqual(campagne["statut"], "terminée")   # créneau pourvu
        etats = {c["nom"]: c["etat"]
                 for c in self.base.contacts_de_campagne(campagne_id)}
        self.assertEqual(etats, {"Mme Refus Un": "appelé",
                                 "Mme Accord Deux": "abouti",
                                 "M. Epargne Trois": "épargné"})
        # Créneau pourvu : PERSONNE n'est relancé.
        self.assertEqual(self.base.relances_de_campagne(campagne_id), [])

    def test_un_stop_dans_une_cascade_part_vers_un_humain(self):
        """⚠ L'ENTRÉE QUE MES TROIS PREMIERS ESSAIS NE TENAIENT PAS.

        La cascade « premier oui » a son propre chemin : le planificateur écrit
        « exclu » dans SA table à elle, et la reprise en campagne recopie ensuite
        cet état sur le contact. En remplaçant chaque entrée par l'ancienne
        écriture, l'une après l'autre, celle-ci n'a fait tomber AUCUN essai :
        la personne y redisparaissait en silence, et rien ne le disait.

        ⚠ LA TABLE DE LA CASCADE GARDE SON VOCABULAIRE (« exclu » / « épargné ») :
        c'est ce que montre la page Cascade, et le changer aurait été corriger
        un écran qui n'a rien demandé. Ce qui voyage en plus, c'est la RAISON,
        et c'est elle qui décide de l'état du contact de campagne.
        """
        exclu = self.base.ajouter_client("Mme Stop Cascade",
                                         "+33 6 00 00 00 61")
        self.base.definir_ne_plus_appeler(exclu, True)
        personnes = [
            {"nom": "Mme Stop Cascade", "telephone": "+33 6 00 00 00 61"},
            {"nom": "Mme Accord Deux", "telephone": "+33 6 00 00 00 51"},
        ]
        cascade_id = self.planif.executer_cascade(personnes, "Mission.", DEMAIN)
        # La cascade, elle, dit toujours « exclu » — et porte désormais la raison.
        lignes = self.base.appels_de_cascade(cascade_id)
        self.assertEqual(lignes[0]["etat"], "exclu")
        self.assertIsNone(lignes[0]["issue"])       # jamais composé
        self.assertEqual(lignes[0]["note"], db.REFUS_STOP)
        # Et le contact de campagne, lui, part vers un humain.
        campagne_id = campagnes.campagne_depuis_cascade(
            self.base, self.prefs, cascade_id, personnes, "Mission.", DEMAIN)
        contacts = {c["nom"]: c
                    for c in self.base.contacts_de_campagne(campagne_id)}
        stop = contacts["Mme Stop Cascade"]
        self.assertEqual(stop["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertTrue(db.refus_de_l_agent(stop["detail"]))
        self.assertEqual(self.base.appels_du_contact_campagne(stop["id"]), [])
        # Elle est dans la liste des rappels humains, et pas relancée.
        self.assertIn(stop["id"],
                      [c["id"] for c in self.base.contacts_rappel_humain()])
        self.assertEqual([r for r in self.base.relances_de_campagne(campagne_id)
                          if r["contact_id"] == stop["id"]], [])

    def test_un_stop_pose_avant_une_relance_de_cascade_va_vers_un_humain(self):
        """⚠ LA DERNIÈRE DES SIX ENTRÉES, et la plus facile à oublier : la
        RELANCE d'une campagne de créneau libéré a son propre code d'appel
        (`_executer_relance_cascade`), distinct de l'appel initial.

        Le scénario est celui qui arrive vraiment : la cascade n'a pourvu
        personne, des relances sont armées — et entre-temps quelqu'un demande
        qu'on ne le rappelle plus. C'est à la relance, pas à l'appel initial,
        que le 🚫 est relu.
        """
        client = self.base.ajouter_client("M. Silence Deux",
                                          "+33 6 00 00 00 53")
        personnes = [
            {"nom": "Mme Refus Un", "telephone": "+33 6 00 00 00 52"},
            {"nom": "M. Silence Deux", "telephone": "+33 6 00 00 00 53"},
        ]
        cascade_id = self.planif.executer_cascade(personnes, "Mission.", DEMAIN)
        campagne_id = campagnes.campagne_depuis_cascade(
            self.base, self.prefs, cascade_id, personnes, "Mission.", DEMAIN)
        # Des relances sont bien armées : le créneau n'a pas été pourvu.
        contacts = {c["nom"]: c
                    for c in self.base.contacts_de_campagne(campagne_id)}
        silence = contacts["M. Silence Deux"]
        self.assertTrue([r for r in self.base.relances_dues()
                         if r["contact_id"] == silence["id"]])
        # ⚠ LE 🚫 ARRIVE ICI, entre l'appel initial et sa relance.
        self.base.definir_ne_plus_appeler(client, True)
        avant = len(self.base.appels_du_contact_campagne(silence["id"]))
        campagnes.executer_relances_dues(self.base, self.planif, self.prefs)
        repris = self.base.obtenir_contact_campagne(silence["id"])
        self.assertEqual(repris["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertTrue(db.refus_de_l_agent(repris["detail"]))
        # Et la relance n'a composé AUCUN numéro : pas une tentative de plus.
        self.assertEqual(len(self.base.appels_du_contact_campagne(silence["id"])),
                         avant)

    def test_un_stop_dans_la_file_d_appels_part_vers_un_humain(self):
        """⚠ LA CINQUIÈME ENTRÉE, elle non plus tenue par aucun essai — et par
        laquelle passe le bouton « Rappeler les rendez-vous manqués ».

        Le planificateur relit le 🚫 à l'instant de composer et annule l'appel
        avec la raison en NOTE ; c'est la reprise en campagne qui décide de
        l'état du contact. `campagne_depuis_file` n'avait aucun essai du tout
        avant aujourd'hui.
        """
        client = self.base.ajouter_client("M. Stop File", "+33 6 00 00 00 63")
        rdv = self.base.ajouter_rendezvous(client, HIER, "Séance",
                                           statut="manqué")
        appel_id = self.planif.programmer(rdv)
        # ⚠ LE 🚫 ARRIVE APRÈS la mise en file, avant de composer.
        self.base.definir_ne_plus_appeler(client, True)
        passes = self.planif.executer()
        appel = self.base.obtenir_appel(appel_id)
        self.assertEqual(appel["statut"], "annulé")
        self.assertEqual(appel["note"], db.REFUS_STOP)
        campagne_id = campagnes.campagne_depuis_file(
            self.base, self.prefs, passes or [appel_id], "Mission.")
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(contact["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertTrue(db.refus_de_l_agent(contact["detail"]))
        self.assertIn(contact["id"],
                      [c["id"] for c in self.base.contacts_rappel_humain()])

    def test_un_refus_sans_numero_dans_la_file_reste_exclu(self):
        """LA CONTRE-ÉPREUVE de la file : sans numéro, un humain n'a rien à
        composer non plus. Ce refus-là ne bouge pas."""
        client = self.base.ajouter_client("M. Sans Numero File", "")
        rdv = self.base.ajouter_rendezvous(client, HIER, "Séance",
                                           statut="manqué")
        appel_id = self.planif.programmer(rdv)
        self.planif.executer()
        appel = self.base.obtenir_appel(appel_id)
        self.assertEqual(appel["note"], db.REFUS_SANS_NUMERO)
        campagne_id = campagnes.campagne_depuis_file(
            self.base, self.prefs, [appel_id], "Mission.")
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertNotEqual(contact["etat"], db.ETAT_RAPPEL_HUMAIN)

    def test_une_cascade_d_avant_la_regle_reste_lisible(self):
        """LA CONTRE-ÉPREUVE DE LA REPRISE : les cascades déjà en base n'ont pas
        de raison écrite (la colonne était vide avant le 20/08/2026). Elles
        doivent rester exactement ce qu'elles étaient — « exclu » — plutôt que
        de partir vers un humain sur une supposition."""
        personnes = [
            {"nom": "Mme Ancienne", "telephone": "+33 6 00 00 00 62"},
            {"nom": "Mme Accord Deux", "telephone": "+33 6 00 00 00 51"},
        ]
        cascade_id = self.planif.executer_cascade(personnes, "Mission.", DEMAIN)
        # On refabrique l'état d'AVANT : « exclu » sans la moindre note.
        rang1 = self.base.appels_de_cascade(cascade_id)[0]
        self.base.conn.execute(
            "UPDATE appels_cascade SET etat = 'exclu', issue = NULL, "
            "note = NULL WHERE id = ?", (rang1["id"],))
        self.base.conn.commit()
        campagne_id = campagnes.campagne_depuis_cascade(
            self.base, self.prefs, cascade_id, personnes, "Mission.", DEMAIN)
        contacts = {c["nom"]: c
                    for c in self.base.contacts_de_campagne(campagne_id)}
        self.assertEqual(contacts["Mme Ancienne"]["etat"], "exclu")

    def test_cascade_epuisee_relances_avec_theme_conserve(self):
        personnes = [
            {"nom": "Mme Refus Un", "telephone": "+33 6 00 00 00 52"},
            {"nom": "M. Silence Deux", "telephone": "+33 6 00 00 00 53"},
        ]
        cascade_id = self.planif.executer_cascade(personnes, "Mission.", DEMAIN)
        campagne_id = campagnes.campagne_depuis_cascade(
            self.base, self.prefs, cascade_id, personnes, "Mission.", DEMAIN)
        self.assertEqual(self.base.obtenir_campagne(campagne_id)["statut"],
                         "en cours")
        relances = self.base.relances_de_campagne(campagne_id)
        self.assertEqual({r["motif"] for r in relances},
                         {"refus à requalifier", "pas de réponse"})
        self.assertTrue(all(r["campagne_theme"] == "creneau_libere"
                            for r in relances))

    def test_relance_cascade_qui_aboutit_clot_la_campagne(self):
        """56 : pas de réponse à la cascade, OUI à la relance -> créneau pris."""
        personnes = [
            {"nom": "M. Occupe Un", "telephone": "+33 6 00 00 00 56"},
            {"nom": "Mme Refus Deux", "telephone": "+33 6 00 00 00 52"},
        ]
        cascade_id = self.planif.executer_cascade(personnes, "Mission.", DEMAIN)
        campagne_id = campagnes.campagne_depuis_cascade(
            self.base, self.prefs, cascade_id, personnes, "Mission.", DEMAIN)
        self.assertEqual(len(self.base.relances_dues()), 2)  # épuisée : 2 chaînes
        comptes = campagnes.executer_relances_dues(self.base, self.planif,
                                                   self.prefs)
        # M. Occupe accepte à la relance : créneau attribué, rendez-vous créé,
        # et la relance de Mme Refus (créneau désormais pris) est ANNULÉE.
        self.assertEqual(comptes[0]["issue"], "accepted")
        self.assertTrue(comptes[0]["abouti"])
        self.assertEqual(len(comptes), 1)                  # la 2e n'est pas passée
        self.assertEqual(self.base.obtenir_campagne(campagne_id)["statut"],
                         "terminée")
        self.assertEqual(self.base.relances_dues(), [])
        rdv = self.base.tous_les_rendezvous()[0]
        self.assertEqual((rdv["nom"], rdv["horaire"], rdv["statut"]),
                         ("M. Occupe Un", DEMAIN, "confirmé"))
        # La cascade rattachée est repassée « pourvue ».
        self.assertEqual(self.base.obtenir_cascade(cascade_id)["statut"],
                         "pourvue")

    def test_contact_exclu_jamais_compose_dans_une_campagne(self):
        stop = self.base.ajouter_client("Mme Stop Exemple", "+33 6 00 00 00 51")
        self.base.definir_ne_plus_appeler(stop, True)
        campagne_id = self._campagne(
            "personnalise",
            [{"nom": "Mme Stop Exemple", "telephone": "+33 6 00 00 00 51"},
             {"nom": "M. Libre Exemple", "telephone": "+33 6 00 00 00 52"}],
            mission="Bonjour [client].")
        etats = [c["etat"] for c in self.base.contacts_de_campagne(campagne_id)]
        # ⚠ « à rappeler par un humain », PLUS « exclu » (sa demande du
        # 20/08/2026) : elle a refusé l'AGENT, pas le cabinet. La garantie qui
        # compte n'a pas bougé d'un pouce — aucune tentative, ci-dessous.
        self.assertEqual(etats, [db.ETAT_RAPPEL_HUMAIN, "abouti"])
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(self.base.appels_du_contact_campagne(contact["id"]),
                         [])                                # aucune tentative
        self.assertTrue(db.refus_de_l_agent(contact["detail"]))
        # Et elle est bien DANS la liste des rappels humains.
        self.assertIn(contact["id"],
                      [c["id"] for c in self.base.contacts_rappel_humain()])

    def test_cloture_manuelle_annule_les_relances(self):
        campagne_id = self._campagne(
            "contact_unique",
            [{"nom": "M. Toujours Absent", "telephone": "+33 6 00 00 00 53"}],
            mission="Bonjour.", sujet="Essai")
        self.assertEqual(len(self.base.relances_dues()), 1)
        annulees = campagnes.clore_campagne(self.base, campagne_id)
        self.assertEqual(annulees, 1)
        self.assertEqual(self.base.relances_dues(), [])
        self.assertEqual(self.base.obtenir_campagne(campagne_id)["statut"],
                         "close")
        # Le geste « lancer les relances » ne trouve plus rien.
        self.assertEqual(campagnes.executer_relances_dues(
            self.base, self.planif, self.prefs), [])

    def test_verrous_reels_sur_les_relances(self):
        """Les 3 verrous s'appliquent aux relances : dry_run bloque TOUT."""
        campagne_id = self._campagne(
            "contact_unique",
            [{"nom": "M. Toujours Absent", "telephone": "+33 6 00 00 00 53"}],
            mission="Bonjour.", sujet="Essai")
        reel = calle_client.AppelReel(cle_api="cle-de-test-0123456789")  # jamais utilisée
        planif_reel = planificateur.Planificateur(self.base, reel)  # dry_run
        with self.assertRaises(planificateur.GardeFou):
            campagnes.executer_relances_dues(self.base, planif_reel, self.prefs)
        # La relance n'a PAS été consommée : elle reste planifiée, intacte.
        dues = self.base.relances_dues()
        self.assertEqual(len(dues), 1)
        self.assertEqual(dues[0]["statut"], "planifiée")
        self.assertEqual(self.base.obtenir_campagne(campagne_id)["statut"],
                         "en cours")

    def test_lancement_campagne_reelle_bloque_par_dry_run(self):
        reel = calle_client.AppelReel(cle_api="cle-de-test-0123456789")
        planif_reel = planificateur.Planificateur(self.base, reel)
        campagne_id = campagnes.creer_campagne(
            self.base, "contact_unique",
            [{"nom": "Mme Test", "telephone": "+33 6 00 00 00 51"}], "Bonjour.")
        with self.assertRaises(planificateur.GardeFou):
            campagnes.executer_campagne_initiale(
                self.base, planif_reel, self.prefs, campagne_id)
        contact = self.base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(contact["etat"], "à appeler")     # rien n'a bougé


class TestServeurCampagnes(_TestAvecServeurWeb):
    """L'assistant « Nouvelle campagne » et l'accueil Campagnes, en vraies
    requêtes HTTP — masquage vérifié à chaque étape."""

    def test_accueil_campagnes_et_etape_theme(self):
        statut, page = self._obtenir("/")
        self.assertEqual(statut, 200)
        self.assertIn("📣 Campagnes", page)
        self.assertIn("➕ Nouvelle campagne", page)
        self.assertIn("Aucune campagne pour l'instant", page)
        # UN SEUL parcours de création : l'ancienne adresse mène à l'assistant
        # (tuiles cliquables), plus jamais à la page de thèmes à cases rondes.
        statut, page = self._obtenir("/campagne/nouvelle")
        self.assertEqual(statut, 200)
        self.assertGreaterEqual(page.count("carte-nature"), 5)
        self.assertNotIn('type="radio" name="theme"', page)
        self.assertNotIn("étape ① sur 3", page)
        # Le nom de la nature ne porte plus la politique d'appel : la cascade
        # est une OPTION, pas la nature.
        self.assertNotIn("cascade « premier oui »)", page)

    def _etape2_liste_nue(self, mission="Bonjour [identite], petit message."):
        """Ouvre un brouillon qui n'exige RIEN d'autre que nom et téléphone,
        franchit l'étape ② avec un texte écrit à la main, et rend
        l'identifiant du brouillon (on est alors à l'étape ③).

        C'est « prise de rendez-vous » : depuis le retrait de la nature
        « Personnalisé » (03/08/2026), c'est la seule nature dont la GRILLE
        n'impose aucune colonne — ce qu'il faut pour éprouver un collage ou
        un import à l'état nu. Le texte reste écrit à la main : ce que
        l'agent lira ne dépend donc pas du gabarit de la nature.
        """
        _, page = self._poster("/assistant/nature", {"nature": "prise_rdv"})
        identifiant = self._brouillon(page)
        _, page = self._poster("/assistant/message", {
            "b": identifiant, "action": "continuer",
            "info_entreprise": "Cabinet Essai",
            "info_origine": "vous avez demandé un rendez-vous",
            "info_creneaux_proposes": "lundi 10h, mardi 14h",
            "politique": "tous",
            "ordre": "liste", "mission": mission, "mission_editee": "1",
            "opt_recontacter": "1", "opt_liberer": "1", "opt_repondeur": "1",
            "relance_mode": "delai", "relance_delai": "4", "relance_max": "3"})
        self.assertIn("3. Les personnes", page)
        return identifiant

    def test_nature_manquante_refusee(self):
        """L'étape ① refuse d'ouvrir un brouillon sans nature (vide ou inconnue)
        — c'est elle qui décide message, informations et colonnes."""
        for envoye in ({"nature": ""}, {"nature": "martien"}):
            _, page = self._poster("/assistant/nature", envoye)
            self.assertIn("Choisissez d&#x27;abord une nature de campagne", page)
            self.assertGreaterEqual(page.count("carte-nature"), 5)  # étape ①
        self.assertEqual(self.application.brouillons_assistant, {})

    def test_brouillon_inconnu_en_404(self):
        for chemin in ("/assistant/message?b=999", "/assistant/liste?b=999"):
            with self.assertRaises(urllib.error.HTTPError) as contexte:
                self._obtenir(chemin)
            self.assertEqual(contexte.exception.code, 404)
            self.assertIn("recommencez",
                          contexte.exception.read().decode("utf-8"))

    def test_collage_puis_lancement_texte_ecrit_a_la_main(self):
        base = self.application.base
        identifiant = self._etape2_liste_nue()
        _, page = self._poster("/assistant/importer", {
            "b": identifiant, "mode": "collage",
            "liste": "Mme Une Exemple;+33 6 00 00 00 51\n"
                     "M. Deux Exemple;+33 6 00 00 00 52\n"})
        # Étape ③ : la grille est MASQUÉE, jamais de numéro en clair.
        self.assertIn("2 contact(s) ajouté(s)", page)
        self.assertIn("+33 6 •• •• •• 51", page)
        self.assertNotIn("+33 6 00 00 00 51", page)
        self.assertNotIn("+33 6 00 00 00 52", page)
        _, page = self._poster("/assistant/liste",
                               {"b": identifiant, "action": "valider"})
        self.assertIn("prête", page)                  # personne n'est appelé
        campagne = base.lister_campagnes()[0]
        self.assertIn("Prise de rendez-vous (2 contact(s))", campagne["nom"])
        self._demarrer(campagne["id"])
        self._attendre_statut(campagne["id"], "terminée")
        # Les deux contacts sont traités (51 confirme, 52 annule — deux
        # chaînes conclues, aucune relance), aucun numéro en clair.
        _, page = self._obtenir(f"/campagne?id={campagne['id']}")
        self.assertIn("terminée", page)
        self.assertIn("Confirmé", page)
        self.assertIn("Annulé par le client", page)
        self.assertIn("Agent : Bonjour Mme Une Exemple, petit message.", page)
        self.assertNotIn("+33 6 00 00 00 5", page)
        etats = {c["nom"]: c["etat"]
                 for c in base.contacts_de_campagne(campagne["id"])}
        self.assertEqual(etats, {"Mme Une Exemple": "accepté",
                                 "M. Deux Exemple": "le client rappellera"})
        self.assertEqual(base.relances_de_campagne(campagne["id"]), [])
        # L'accueil liste la campagne avec son avancement.
        _, accueil = self._obtenir("/")
        self.assertIn("Prise de rendez-vous", accueil)
        self.assertIn("2/2 appelé(s) · 1 accepté(s) · 0 relance(s)", accueil)

    def test_import_csv_dans_l_assistant(self):
        identifiant = self._etape2_liste_nue()
        contenu = ("nom;telephone\n"
                   "Mme Fichier Exemple;+33 6 00 00 00 51\n"
                   "M. Faux Numero;12345\n")
        frontiere = "----frontiereDeTest"
        corps = (f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="b"\r\n\r\n'
                 f"{identifiant}\r\n"
                 f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="mode"\r\n\r\n'
                 "csv\r\n"
                 f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="fichier"; filename="liste.csv"\r\n'
                 "Content-Type: text/csv\r\n\r\n"
                 f"{contenu}\r\n--{frontiere}--\r\n").encode("utf-8")
        requete = urllib.request.Request(
            self.racine + "/assistant/importer", data=corps,
            headers={"Content-Type": f"multipart/form-data; boundary={frontiere}"})
        with urllib.request.urlopen(requete, timeout=15) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn("1 contact(s) ajouté(s)", page)  # une bonne ligne suffit
        self.assertIn("Numéro de téléphone invalide", page)  # la fautive signalée
        self.assertIn("Mme Fichier Exemple", page)
        self.assertIn("+33 6 •• •• •• 51", page)
        self.assertNotIn("+33 6 00 00 00 51", page)          # masqué

    def test_liste_vide_reste_a_l_etape_3(self):
        identifiant = self._etape2_liste_nue()
        _, page = self._poster("/assistant/importer", {
            "b": identifiant, "mode": "collage", "liste": "  \n"})
        self.assertIn("Liste vide", page)
        self.assertIn("3. Les personnes", page)             # on ne passe pas
        # Et valider une grille vide reste refusé : rien n'est créé.
        _, page = self._poster("/assistant/liste",
                               {"b": identifiant, "action": "valider"})
        self.assertIn("La grille est vide", page)
        self.assertEqual(self.application.base.lister_campagnes(), [])

    def test_sans_creneau_refuse_pour_creneau_libere(self):
        _, page = self._poster("/assistant/nature", {"nature": "creneau_libere"})
        identifiant = self._brouillon(page)
        _, page = self._poster("/assistant/message", {
            "b": identifiant, "action": "continuer",
            "info_entreprise": "Cabinet Essai", "politique": "premier_oui",
            "ordre": "liste", "opt_recontacter": "1", "relance_mode": "delai",
            "relance_delai": "4", "relance_max": "3"})
        self.assertIn("Créneau libéré (date et heure) » est obligatoire", page)
        self.assertIn('id="apercu"', page)          # on reste à l'étape ②
        _, accueil = self._obtenir("/")
        self.assertIn("Aucune campagne pour l'instant", accueil)  # rien créé

    def test_ancien_parcours_cascade_rattache_aux_campagnes(self):
        # Une cascade épuisée lancée par l'ANCIENNE page crée sa campagne,
        # avec les relances « refus à requalifier » / « pas de réponse ».
        _, page = self._poster("/cascade/executer", {
            "liste": "Mme Refus Un;+33 6 00 00 00 52\n"
                     "M. Silence Deux;+33 6 00 00 00 53\n",
            "mission": "Un créneau s'est libéré.", "creneau": DEMAIN})
        self.assertIn("liste épuisée", page)
        _, accueil = self._obtenir("/")
        self.assertIn("Créneau libéré du", accueil)
        self.assertIn("2 relance(s)", accueil)
        _, relances = self._obtenir("/relances")
        self.assertIn("refus à requalifier", relances)
        self.assertIn("pas de réponse", relances)
        self.assertIn("Relances à venir (2)", relances)      # délai par défaut 4 h
        self.assertNotIn("+33 6 00 00 00 5", relances)       # masqué partout

    def test_ancien_parcours_file_rattache_aux_campagnes(self):
        self._poster("/file/tout-rappeler")
        _, page = self._poster("/file/executer")
        self.assertIn("campagne de rappel des manqués", page)
        _, accueil = self._obtenir("/")
        self.assertIn("Rappel de rendez-vous manqués", accueil)

    def test_reglages_relances_enregistres(self):
        _, page = self._obtenir("/reglages")
        self.assertIn("relance_delai", page)
        self.assertIn("relance_max", page)
        _, page = self._poster("/reglages/enregistrer", {
            "entreprise": "Cabinet Essai", "plage_debut": "00:00",
            "plage_fin": "23:59", "relance_delai": "2", "relance_max": "5"})
        self.assertIn("Réglages enregistrés", page)
        preferences = self.application.preferences
        self.assertEqual(campagnes.parametres_relance(preferences), (2, 5))
        # Valeur hors bornes refusée en français.
        _, page = self._poster("/reglages/enregistrer", {
            "entreprise": "", "plage_debut": "00:00", "plage_fin": "23:59",
            "relance_delai": "999", "relance_max": "3"})
        self.assertIn("entre 0 et 168", page)
        self.assertEqual(campagnes.parametres_relance(preferences), (2, 5))


class TestServeurRelances(_TestAvecServeurWeb):
    """La page « 🔁 Relances » : dues en évidence, geste humain, reporter,
    annuler, verrous — en vraies requêtes HTTP."""

    def _creer_relance_due(self, telephone="+33 6 00 00 00 53"):
        """Une campagne « contact unique » dont l'appel initial échoue :
        avec un délai de 0 h, la relance est due immédiatement."""
        application = self.application
        application.preferences.definir(campagnes.CLE_RELANCE_DELAI, 0)
        campagne_id = campagnes.creer_campagne(
            application.base, "contact_unique",
            [{"nom": "Secrétariat Exemple", "telephone": telephone}],
            "Bonjour, au sujet de : [sujet].", sujet="Demande de devis")
        campagnes.executer_campagne_initiale(
            application.base, application.planif, application.preferences,
            campagne_id)
        relance = application.base.relances_dues()[0]
        return campagne_id, relance["id"]

    def test_page_vide_et_execution_sans_dues(self):
        statut, page = self._obtenir("/relances")
        self.assertEqual(statut, 200)
        # ⚠ UN MENU DES TYPES, PAS UN PARAGRAPHE (demande du propriétaire,
        # 02/08/2026). Les cinq types y sont, chacun avec SON nombre — c'est
        # ainsi qu'on apprend qu'il n'y a rien, sans cinq blocs vides. Et la
        # page ne devient jamais muette : quand tout est à zéro, elle le dit.
        # ⚠ QUATRE FAMILLES DEPUIS LE 21/08/2026 : « Demandes déjà traitées »
        # a été retirée (sa demande). Elle gardait, dans un cinquième onglet,
        # ce qu'il venait justement de sortir de sa liste de travail.
        self.assertEqual(self._menu_relances(page), {
            "🙋 Rappels par un humain": 0, "⏰ Relances dues": 0,
            "🕓 Relances à venir": 0,
            "📵 Non joints — maximum de rappels atteint": 0})
        self.assertIn("Rien n'attend de rappel", page)
        # Le type d'arrivée est « rappels par un humain », lui seul est visible.
        visible, contenu = self._panneau_relance(page, "humains")
        self.assertTrue(visible)
        self.assertIn("Aucun rappel par un humain en attente", contenu)
        for autre in ("dues", "a_venir", "bloques"):
            self.assertFalse(self._panneau_relance(page, autre)[0], autre)
        _, page = self._poster("/relances/executer")
        self.assertIn("Aucune relance n'était due", page)

    def test_le_menu_mene_a_chaque_type_meme_vide(self):
        """Cliquer un type l'affiche : liste vide, mais titre et explication.

        Sans JavaScript le lien recharge la page avec ?vue= — c'est ce que
        cet essai exerce, donc le repli est vérifié pour de bon.
        """
        for code, titre in (("dues", "⏰ Relances dues (0)"),
                            ("a_venir", "🕓 Relances à venir (0)"),
                            ("bloques", "📵 Non joints — maximum de rappels atteint (0)"),
                            ("humains", "🙋 Rappels par un humain (0)")):
            with self.subTest(vue=code):
                _, page = self._obtenir(f"/relances?vue={code}")
                visible, contenu = self._panneau_relance(page, code)
                self.assertTrue(visible)
                self.assertIn(titre, page)          # le titre est conservé
                self.assertIn("<p>", contenu)       # l'explication aussi
                self.assertIn("vide-famille", contenu)
                # Les trois autres restent en réserve, masqués.
                for autre, _, _ in serveur.VUES_RELANCES:
                    if autre != code:
                        self.assertFalse(self._panneau_relance(page, autre)[0])
        # Une vue inconnue ne casse rien : on retombe sur celle d'arrivée.
        _, page = self._obtenir("/relances?vue=n_importe_quoi")
        self.assertTrue(self._panneau_relance(page, "humains")[0])

    def test_due_en_evidence_puis_geste_reporter_annuler(self):
        campagne_id, relance_id = self._creer_relance_due()
        _, page = self._obtenir("/relances?vue=dues")
        self.assertIn("⏰ Relances dues (1)", page)
        self.assertEqual(self._menu_relances(page)["⏰ Relances dues"], 1)
        visible, contenu = self._panneau_relance(page, "dues")
        self.assertTrue(visible)
        self.assertIn("Lancer les 1 relance(s) due(s)", contenu)
        self.assertIn("Secrétariat Exemple", contenu)
        self.assertIn("pas de réponse", contenu)
        self.assertIn("+33 6 •• •• •• 53", contenu)
        self.assertNotIn("+33 6 00 00 00 53", page)          # jamais en clair
        # Reporter à 2030 : plus due, mais à venir — l'échéance est modifiable.
        # Le geste emporte le type qu'on regardait : on ne perd pas sa place.
        _, page = self._poster("/relances/reporter", {
            "relance": relance_id, "vue": "dues",
            "echeance": "2030-01-01T10:00"})
        self.assertIn("Relance reportée", page)
        self.assertTrue(self._panneau_relance(page, "dues")[0])
        menu = self._menu_relances(page)
        self.assertEqual(menu["⏰ Relances dues"], 0)
        self.assertEqual(menu["🕓 Relances à venir"], 1)
        self.assertIn("01/01/2030", self._panneau_relance(page, "a_venir")[1])
        # Reporter à une date passée : elle redevient due (le geste décide).
        self._poster("/relances/reporter", {
            "relance": relance_id, "echeance": "2020-01-01T10:00"})
        _, page = self._obtenir("/relances")
        self.assertEqual(self._menu_relances(page)["⏰ Relances dues"], 1)
        # Annuler : la chaîne s'arrête, la campagne se termine.
        _, page = self._poster("/relances/annuler", {"relance": relance_id})
        self.assertIn("Relance annulée", page)
        self.assertIn("Rien n'attend de rappel", page)
        base = self.application.base
        self.assertEqual(base.obtenir_relance(relance_id)["statut"], "annulée")
        self.assertEqual(base.obtenir_campagne(campagne_id)["statut"],
                         "terminée")
        # L'annuler à nouveau : message honnête, rien ne casse.
        _, page = self._poster("/relances/annuler", {"relance": relance_id})
        self.assertIn("Relance introuvable", page)

    def test_echeance_illisible_refusee(self):
        _, relance_id = self._creer_relance_due()
        _, page = self._poster("/relances/reporter", {
            "relance": relance_id, "echeance": "bientôt"})
        self.assertIn("Date illisible", page)

    def test_hors_plage_refuse_le_geste_et_garde_la_relance(self):
        campagne_id, relance_id = self._creer_relance_due()
        if datetime.datetime.now().hour < 12:
            debut, fin = "22:00", "23:00"
        else:
            debut, fin = "01:00", "02:00"
        preferences = self.application.preferences
        preferences.definir(serveur.themes.CLE_PLAGE_DEBUT, debut)
        preferences.definir(serveur.themes.CLE_PLAGE_FIN, fin)
        with self.assertRaises(urllib.error.HTTPError) as contexte:
            self._poster("/relances/executer")
        self.assertEqual(contexte.exception.code, 403)
        self.assertIn("hors de la plage",
                      contexte.exception.read().decode("utf-8"))
        # La relance n'a pas été consommée.
        preferences.definir(serveur.themes.CLE_PLAGE_DEBUT, "00:00")
        preferences.definir(serveur.themes.CLE_PLAGE_FIN, "23:59")
        self.assertEqual(len(self.application.base.relances_dues()), 1)


class TestServeurRelancesDeuxFamilles(_TestAvecServeurWeb):
    """🔁 Relances montre TOUT ce qui attend un rappel, en DEUX familles :
    les rappels automatiques (programmés par le système, 📵 injoignables
    compris) et les rappels par un humain (jamais appelés tout seuls)."""

    def _campagne_injoignable_et_humain(self):
        """Une campagne RÉELLE en simulation : le silencieux (53) avec un
        plafond de 0 rappel finit 📵 injoignable, et celui qui veut déplacer
        sans conclure (55) finit 🙋 à rappeler par un humain."""
        _, page = self._poster("/assistant/nature", {"nature": "prise_rdv"})
        identifiant = self._brouillon(page)
        _, page = self._poster("/assistant/message", {
            "b": identifiant, "action": "continuer",
            "info_entreprise": "Cabinet Essai",
            "info_origine": "vous avez demandé un rendez-vous",
            "info_creneaux_proposes": "lundi 10h, mardi 14h",
            "ordre": "liste", "mission_editee": "1",
            "mission": "Bonjour [client], au sujet de votre dossier.",
            "opt_recontacter": "1", "relance_mode": "delai",
            "relance_delai": "0", "relance_max": "0"})
        self.assertIn("3. Les personnes", page)
        _, page = self._poster("/assistant/importer", {
            "b": identifiant, "mode": "collage",
            "liste": "Mme Silence Essai;+33 6 00 00 00 53\n"
                     "M. Hesitant Essai;+33 6 00 00 00 55"})
        self.assertIn("2 contact(s) ajouté(s)", page)
        self._poster("/assistant/liste", {"b": identifiant, "action": "valider"})
        campagne = self.application.base.lister_campagnes()[0]
        self._demarrer(campagne["id"])
        self._attendre_statut(campagne["id"], "terminée")
        return campagne["id"]

    def test_injoignable_et_humain_chacun_dans_sa_famille(self):
        campagne_id = self._campagne_injoignable_et_humain()
        base = self.application.base
        etats = {c["nom"]: c for c in base.contacts_de_campagne(campagne_id)}
        self.assertEqual(etats["Mme Silence Essai"]["etat"], "injoignable")
        self.assertEqual(etats["M. Hesitant Essai"]["etat"],
                         "à rappeler par un humain")
        # Plafond 0 : AUCUNE relance n'est programmée — et pourtant les deux
        # personnes attendent bien un rappel, donc elles s'affichent.
        self.assertEqual(base.lister_relances("planifiée"), [])
        _, page = self._obtenir("/relances")
        # ⚠ UN NOMBRE PAR RÉALITÉ. Le compteur additionnait les relances
        # programmées et les personnes pour qui plus rien ne partira : il
        # annonçait « 1 rappel automatique » alors qu'AUCUN n'était
        # programmé. Le propriétaire a demandé ce que cela voulait dire —
        # cela ne voulait rien dire. Chaque type porte maintenant le sien.
        self.assertEqual(self._menu_relances(page), {
            "🙋 Rappels par un humain": 1, "⏰ Relances dues": 0,
            "🕓 Relances à venir": 0,
            "📵 Non joints — maximum de rappels atteint": 1})
        _, bloques = self._panneau_relance(page, "bloques")
        self.assertIn("Mme Silence Essai", bloques)          # l'injoignable Y EST
        self.assertIn("plus de relance programmée", bloques)
        self.assertNotIn("M. Hesitant Essai", bloques)       # chacun chez soi
        humains_visible, humains = self._panneau_relance(page, "humains")
        self.assertTrue(humains_visible)                     # le type d'arrivée
        self.assertIn("M. Hesitant Essai", humains)
        self.assertNotIn("Mme Silence Essai", humains)
        # ⚠ Sa demande ne s'étale plus dans la cellule : un lien l'ouvre.
        self.assertIn("Voir sa demande…", humains)
        self.assertNotIn("Demande du client", humains)
        self.assertIn("Prise de rendez-vous", humains)       # d'où ça vient
        self.assertNotIn("+33 6 00 00 00 5", page)           # masqué partout
        # Et la demande est bien au bout du lien, mot pour mot.
        contact = self.application.base.contacts_rappel_humain()[0]
        _, modale = self._obtenir(f"/relances/demande?contact={contact['id']}")
        self.assertIn("Demande du client", modale)
        self.assertIn("Sa demande — M. Hesitant Essai", modale)
        self.assertNotIn("<!DOCTYPE", modale)                # un fragment

    def test_rappel_humain_traite_puis_repris_et_jamais_appele_seul(self):
        campagne_id = self._campagne_injoignable_et_humain()
        base = self.application.base
        contact = base.contacts_rappel_humain()[0]
        # Jamais appelé automatiquement : aucune relance ne le vise, et le
        # geste « Lancer les relances dues » ne le touche pas.
        self.assertEqual([r for r in base.relances_de_campagne(campagne_id)
                          if r["contact_id"] == contact["id"]], [])
        _, page = self._poster("/relances/executer")
        self.assertIn("Aucune relance n'était due", page)
        self.assertEqual(base.obtenir_contact_campagne(contact["id"])["etat"],
                         "à rappeler par un humain")
        self.assertEqual(len(base.appels_du_contact_campagne(contact["id"])), 1)
        # ⚠ « C'EST FAIT » LE SORT DE LA LISTE, ET RIEN N'EST EFFACÉ. Depuis
        # le 21/08/2026 (sa demande), il n'y a plus de cinquième onglet
        # « Demandes déjà traitées » : ce qu'il vient de ranger n'a pas à
        # revenir occuper un onglet. La DONNÉE, elle, reste — la date de
        # traitement est en base et la fiche de la campagne montre tout.
        _, page = self._poster("/relances/humain",
                               {"contact": contact["id"], "valeur": 1,
                                "vue": "humains"})
        menu = self._menu_relances(page)
        self.assertEqual(menu["🙋 Rappels par un humain"], 0)
        self.assertNotIn("✅ Demandes déjà traitées", menu)
        self.assertNotIn('id="panneau-traites"', page)
        # Le geste ramène sur le type qu'on regardait, qui dit son vide.
        visible, humains = self._panneau_relance(page, "humains")
        self.assertTrue(visible)
        self.assertIn("Aucun rappel par un humain en attente", humains)
        # ⚠ RIEN N'EST EFFACÉ : la date de traitement est écrite, et sa demande
        # reste ouvrable — c'est ce qui rend le retrait de l'onglet tenable.
        self.assertIsNotNone(
            base.obtenir_contact_campagne(contact["id"])["traite_le"])
        _, modale = self._obtenir(f"/relances/demande?contact={contact['id']}")
        self.assertIn("Demande du client", modale)
        self.assertEqual(base.contacts_rappel_humain(), [])
        # ⚠ LE RETOUR EN ARRIÈRE EXISTE ENCORE, MAIS IL N'A PLUS DE BOUTON.
        # Le geste « Remettre dans la liste » vivait dans l'onglet « déjà
        # traitées », retiré le 21/08/2026 à sa demande. La ROUTE, elle, n'a
        # pas bougé — c'est elle qu'on éprouve ici — et une vue inconnue
        # retombe sur la famille d'arrivée, sans casser.
        _, page = self._poster("/relances/humain",
                               {"contact": contact["id"], "valeur": 0,
                                "vue": "traites"})
        self.assertEqual(self._menu_relances(page)["🙋 Rappels par un humain"], 1)
        self.assertTrue(self._panneau_relance(page, "humains")[0])
        self.assertIsNone(
            base.obtenir_contact_campagne(contact["id"])["traite_le"])


class TestServeurEditionEnModale(_TestAvecServeurWeb):
    """On MODIFIE dans une modale, jamais en changeant de page : seul
    l'élément concerné revient (la zone du planning, la ligne du client)."""

    def _poster_modale(self, chemin, donnees):
        """Le POST tel que la modale l'envoie ; rend (cible, corps).

        La cible est l'en-tête X-RingBack-Cible : « modale » quand la saisie
        est refusée, sinon l'identifiant de l'élément à remplir à nouveau.
        """
        octets = urllib.parse.urlencode(donnees, doseq=True).encode("utf-8")
        requete = urllib.request.Request(
            self.racine + chemin, data=octets,
            headers={"X-RingBack-Fragment": "1"})
        with urllib.request.urlopen(requete, timeout=15) as reponse:
            return (reponse.headers.get("X-RingBack-Cible"),
                    reponse.read().decode("utf-8"))

    def test_rendezvous_modifie_dans_la_modale(self):
        base = self.application.base
        rdv = base.tous_les_rendezvous()[0]
        # La modale porte le détail ET l'édition ; chaque valeur est DANS son champ.
        _, modale = self._obtenir(f"/suivi/detail?rdv={rdv['id']}")
        self.assertIn('action="/suivi/detail/enregistrer"', modale)
        self.assertIn("data-modale-envoi", modale)
        self.assertIn(f'value="{html.escape(rdv["motif"])}"', modale)
        self.assertIn(f'value="{rdv["horaire"]}"', modale)
        # Saisie refusée : la MODALE revient, avec l'erreur et la saisie.
        cible, corps = self._poster_modale("/suivi/detail/enregistrer", {
            "rdv": rdv["id"], "motif": "", "horaire": rdv["horaire"],
            "duree": "30", "statut": "manqué"})
        self.assertEqual(cible, "modale")
        self.assertIn("Saisie refusée", corps)
        self.assertIn("motif du rendez-vous est obligatoire", corps)
        self.assertIn('value="30"', corps)                  # rien n'est perdu
        self.assertEqual(base.obtenir_rendezvous(rdv["id"])["motif"],
                         rdv["motif"])                      # rien n'est écrit
        # Enregistrement : seul le PLANNING revient, la page ne bouge pas.
        cible, corps = self._poster_modale("/suivi/detail/enregistrer", {
            "rdv": rdv["id"], "motif": "  Bilan   complet  ",
            "horaire": rdv["horaire"], "duree": "30", "statut": "manqué"})
        self.assertEqual(cible, "planning")
        self.assertIn("Semaine du", corps)
        self.assertNotIn("<html", corps)                    # un fragment, pas la page
        frais = base.obtenir_rendezvous(rdv["id"])
        self.assertEqual(frais["motif"], "Bilan complet")
        self.assertEqual(frais["duree_tranches"], 2)
        self.assertEqual(frais["statut"], "manqué")
        # Le repli sans JavaScript reste entier : la fiche pleine page marche.
        statut, page = self._obtenir(f"/rendezvous?id={rdv['id']}")
        self.assertEqual(statut, 200)
        self.assertIn("Bilan complet", page)

    def test_client_modifie_dans_la_modale_seule_sa_ligne_revient(self):
        base = self.application.base
        client = base.lister_clients()[0]
        masque = client["telephone_masque"]
        # La liste ouvre la MODALE, et garde le lien vers la fiche (repli).
        _, liste = self._obtenir("/clients")
        self.assertIn(f'data-modale="/clients/detail?id={client["id"]}"', liste)
        self.assertIn(f'href="/clients/fiche?id={client["id"]}"', liste)
        self.assertIn(f'<tr id="client-{client["id"]}">', liste)
        _, modale = self._obtenir(f"/clients/detail?id={client['id']}")
        self.assertIn('action="/clients/detail/enregistrer"', modale)
        self.assertIn(f'value="{html.escape(client["nom"])}"', modale)
        self.assertIn(masque, modale)                       # masqué, même ici
        self.assertIn("Laissez le champ", modale)           # garder le numéro
        # Saisie refusée : la modale revient avec l'erreur ET la saisie.
        cible, corps = self._poster_modale("/clients/detail/enregistrer", {
            "client": client["id"], "nom": "X", "telephone": "12345"})
        self.assertEqual(cible, "modale")
        self.assertIn("Saisie refusée", corps)
        self.assertIn('value="X"', corps)
        self.assertIn('value="12345"', corps)
        self.assertEqual(base.obtenir_client(client["id"])["nom"], client["nom"])
        # Enregistrement : SEULE la ligne de ce client revient.
        cible, corps = self._poster_modale("/clients/detail/enregistrer", {
            "client": client["id"], "nom": "Mme Nadia Lefèvre-Roy",
            "telephone": "", "ne_plus_appeler": "1"})
        self.assertEqual(cible, f"client-{client['id']}")
        self.assertIn("Mme Nadia Lefèvre-Roy", corps)
        self.assertIn("🚫 ne plus appeler", corps)
        self.assertNotIn("<html", corps)
        self.assertNotIn("<tr", corps)                      # les cellules seules
        frais = base.obtenir_client(client["id"])
        self.assertEqual(frais["nom"], "Mme Nadia Lefèvre-Roy")
        self.assertEqual(frais["telephone_masque"], masque)  # numéro gardé
        self.assertTrue(frais["ne_plus_appeler"])
        # Le repli sans JavaScript reste entier.
        statut, page = self._obtenir(f"/clients/fiche?id={client['id']}")
        self.assertEqual(statut, 200)
        self.assertIn("Mme Nadia Lefèvre-Roy", page)


class TestScenariosProprietaire(_TestAvecServeurWeb):
    """Les TROIS scénarios exacts du propriétaire du produit, joués de bout
    en bout contre le serveur, en vraies requêtes HTTP."""

    def test_scenario_a_place_liberee_cascade_premier_oui(self):
        """(a) Place libérée -> liste de l'instant + créneau -> appels un par
        un -> premier oui : créneau attribué, suivants épargnés."""
        base = self.application.base
        ancien = (datetime.datetime.now() + datetime.timedelta(days=10)
                  ).replace(hour=9, minute=0, second=0,
                            microsecond=0).isoformat(timespec="minutes")
        # ① la nature « créneau libéré » (la cascade en est l'OPTION).
        _, page = self._poster("/assistant/nature", {"nature": "creneau_libere"})
        identifiant = self._brouillon(page)
        # ② le message : le CRÉNEAU LIBÉRÉ (⚠) et l'arrêt au premier oui.
        _, page = self._poster("/assistant/message", {
            "b": identifiant, "action": "continuer",
            "info_entreprise": "Cabinet Essai", "info_creneau_libere": DEMAIN,
            "politique": "premier_oui", "ordre": "liste",
            "opt_recontacter": "1", "opt_liberer": "1", "opt_repondeur": "1",
            "relance_mode": "delai", "relance_delai": "4", "relance_max": "3"})
        self.assertIn("3. Les personnes", page)
        # ⚠ MODE MANUEL : une campagne « créneau libéré » s'ouvre en
        # AUTOMATIQUE depuis le 09/08/2026, et sa règle recruterait en plus des
        # gens de la base. Ce scénario-ci porte sur une liste COLLÉE, choisie à
        # la main — c'est le mode manuel, celui que l'opérateur demandera.
        self._poster("/assistant/liste",
                     {"b": identifiant, "action": "liste:manuel"})
        # ③ la liste de l'instant, collée à l'instant même.
        _, page = self._poster("/assistant/importer", {
            "b": identifiant, "mode": "collage",
            "liste": f"Mme Refus Un;+33 6 00 00 00 52;{ancien};Séance\n"
                     f"M. Silence Deux;+33 6 00 00 00 53;{ancien};Séance\n"
                     f"Mme Accord Trois;+33 6 00 00 00 51;{ancien};Séance\n"
                     f"M. Épargné Quatre;+33 6 00 00 00 49;{ancien};Séance\n"})
        self.assertIn("4 contact(s) ajouté(s)", page)
        self.assertNotIn("+33 6 00 00 00 5", page)           # masqué dès la grille
        # Valider crée la campagne « prête » : PERSONNE n'est encore appelé.
        _, page = self._poster("/assistant/liste",
                               {"b": identifiant, "action": "valider"})
        self.assertIn("prête", page)
        campagne = base.lister_campagnes()[0]
        self.assertIn("Créneau libéré du", campagne["nom"])
        for contact in base.contacts_de_campagne(campagne["id"]):
            self.assertEqual(base.appels_du_contact_campagne(contact["id"]), [])
        # ▶ Démarrer : un appel à la fois, arrêt au premier oui.
        self._demarrer(campagne["id"])
        self._attendre_statut(campagne["id"], "terminée")
        # Le poste de pilotage prouve le déroulé : premier oui, arrêt.
        _, page = self._obtenir(f"/campagne?id={campagne['id']}")
        self.assertIn("terminée", page)                      # créneau pourvu
        self.assertIn("Mme Accord Trois", page)
        self.assertIn("ligne-acceptee", page)                # le oui mis en valeur
        self.assertIn("Accepté — créneau attribué", page)    # l'issue de l'appel
        # ⚠ LE MOT AFFICHÉ EST « pas appelé » depuis le 11/08/2026 : le
        # propriétaire ne comprenait pas « épargné ». Le CODE en base, lui, reste
        # « épargné » (voir assistant.mot_etat).
        self.assertIn("💤 pas appelé : 1", page)             # M. Épargné Quatre
        self.assertIn("🔁 à recontacter : 1", page)          # M. Silence Deux
        self.assertNotIn("+33 6 00 00 00 5", page)           # masqué partout
        self.assertNotIn("+33 6 00 00 00 49", page)
        etats = {c["nom"]: c for c in base.contacts_de_campagne(campagne["id"])}
        self.assertEqual(etats["Mme Refus Un"]["etat"], "refusé")
        self.assertEqual(etats["M. Silence Deux"]["etat"], "à recontacter")
        self.assertEqual(etats["Mme Accord Trois"]["etat"], "accepté")
        # Le rendez-vous du premier oui existe, AU CRÉNEAU, confirmé.
        pris = [r for r in base.tous_les_rendezvous()
                if r["nom"] == "Mme Accord Trois"]
        self.assertEqual([(r["horaire"], r["statut"]) for r in pris],
                         [(DEMAIN, "confirmé")])
        # Créneau pourvu : plus AUCUNE relance en attente — et l'épargné n'a
        # jamais été appelé.
        self.assertEqual([r for r in base.relances_de_campagne(campagne["id"])
                          if r["statut"] == "planifiée"], [])
        self.assertEqual(etats["M. Épargné Quatre"]["etat"], "épargné")
        self.assertEqual(base.appels_du_contact_campagne(
            etats["M. Épargné Quatre"]["id"]), [])
        # L'accueil montre l'avancement : 3 appelés sur 4, 1 accepté.
        _, accueil = self._obtenir("/")
        self.assertIn("3/4 appelé(s) · 1 accepté(s) · 0 relance(s)", accueil)

    def test_scenario_b_prise_rdv_relance_aboutie(self):
        """(b) Prise de rendez-vous -> pas de réponse -> relance visible avec
        son thème -> geste humain -> aboutie, rendez-vous créé.

        Ce scénario reposait sur « contact unique avec sujet », retirée le
        03/08/2026. La MÉCANIQUE éprouvée est la même — un appel qui
        n'aboutit pas programme une relance qui conserve le thème, et le
        geste humain la conclut — et elle porte désormais sur une nature qui
        écrit vraiment dans le carnet de rendez-vous.
        """
        base = self.application.base
        origine = "vous avez demandé un rendez-vous sur notre site"
        # ① la nature « prise de rendez-vous ».
        _, page = self._poster("/assistant/nature", {"nature": "prise_rdv"})
        self.assertIn("2. Le message", page)
        self.assertIn("Origine de la demande", page)         # le champ dédié
        identifiant = self._brouillon(page)
        # ② l'origine + relance due IMMÉDIATEMENT (délai 0 h ouvrée).
        _, page = self._poster("/assistant/message", {
            "b": identifiant, "action": "continuer",
            "info_entreprise": "Cabinet Essai", "info_origine": origine,
            "info_creneaux_proposes": "lundi 10h, mardi 14h",
            "ordre": "liste", "opt_recontacter": "1", "opt_repondeur": "1",
            "relance_mode": "delai", "relance_delai": "0", "relance_max": "3"})
        self.assertIn("3. Les personnes", page)
        # L'origine nourrit la mission pré-remplie : plus de [origine] en attente.
        _, etape2 = self._obtenir(f"/assistant/message?b={identifiant}")
        apercu = etape2.split('id="apercu"')[1].split("</div>")[0]
        # Civilités DÉVELOPPÉES : l'aperçu montre ce qui sera DIT au
        # téléphone, pas ce qui est écrit dans la fiche.
        self.assertIn(consigne.developper_civilites(origine), apercu)
        self.assertNotIn("[origine]", apercu)
        # ③ LE contact, numéro masqué dès la grille.
        _, page = self._poster("/assistant/importer", {
            "b": identifiant, "mode": "collage",
            "liste": "Mme Demandeuse Exemple;+33 6 00 00 00 56\n"})
        self.assertIn("+33 6 •• •• •• 56", page)
        self.assertNotIn("+33 6 00 00 00 56", page)
        self._poster("/assistant/liste", {"b": identifiant, "action": "valider"})
        campagne = base.lister_campagnes()[0]
        self.assertIn("Prise de rendez-vous (1 contact(s))", campagne["nom"])
        self.assertIn(origine, campagne["mission"])          # l'origine EST lue
        # ① l'appel initial ne répond pas -> relance programmée, thème gardé.
        self._demarrer(campagne["id"])
        self._attendre_statut(campagne["id"], "terminée")
        _, fiche = self._obtenir(f"/campagne?id={campagne['id']}")
        self.assertIn("🔁 à recontacter : 1", fiche)
        # L'ÉCHÉANCE se lit sur 🔁 Relances, et la fiche y renvoie : la colonne
        # « Détail » du tableau des contacts est retirée (11/08/2026).
        self.assertIn("Des relances sont programmées", fiche)
        self.assertIn('href="/relances"', fiche)
        _, relances_page = self._obtenir("/relances?vue=dues")
        self.assertEqual(
            self._menu_relances(relances_page)["⏰ Relances dues"], 1)
        _, dues = self._panneau_relance(relances_page, "dues")
        self.assertIn("Prise de rendez-vous (1 contact(s))", dues)
        self.assertIn("Prise de rendez-vous", dues)          # le THÈME
        self.assertIn("pas de réponse", dues)
        self.assertNotIn("+33 6 00 00 00 56", relances_page)
        # ② le GESTE humain : « Lancer les relances dues » -> ça aboutit.
        _, resultat = self._poster("/relances/executer")
        self.assertIn("Relances exécutées", resultat)
        self.assertIn("Confirmé", resultat)
        self.assertIn("Chaîne conclue", resultat)
        # ③ la campagne est terminée, la chaîne close, rendez-vous obtenu.
        campagne = base.lister_campagnes()[0]
        self.assertEqual(campagne["statut"], "terminée")
        self.assertEqual(campagne["relances"], 0)            # plus rien en attente
        _, fiche = self._obtenir(f"/campagne?id={campagne['id']}")
        self.assertIn("✅ accepté : 1", fiche)
        self.assertNotIn("+33 6 00 00 00 56", fiche)
        rdv = base.tous_les_rendezvous()[0]
        self.assertEqual(rdv["nom"], "Mme Demandeuse Exemple")
        self.assertEqual(rdv["statut"], "confirmé")

    def test_scenario_c_deplacement_non_conclu_relance_theme_sauvegarde(self):
        """(c) Confirmation : le client veut déplacer SANS conclure de date ->
        RIEN n'est inventé (son rendez-vous reste intact, il part « à rappeler
        par un humain ») ; et la relance du contact non joint de la MÊME
        campagne conserve le thème et les paramètres."""
        base = self.application.base
        plus_tard = (datetime.datetime.fromisoformat(DEMAIN)
                     + datetime.timedelta(hours=2)).isoformat(timespec="minutes")
        # Deux rendez-vous À VENIR : « veut déplacer » (55) et « silencieux » (53).
        self._poster("/ajouter", {
            "nom": "M. Hesitant Exemple", "telephone": "+33 6 00 00 00 55",
            "date_heure": DEMAIN, "motif": "Bilan annuel"})
        self._poster("/ajouter", {
            "nom": "M. Silence Deux", "telephone": "+33 6 00 00 00 53",
            "date_heure": plus_tard, "motif": "Contrôle"})
        # ① la nature « confirmation de rendez-vous ».
        _, page = self._poster("/assistant/nature", {"nature": "confirmation"})
        identifiant = self._brouillon(page)
        # ② le message + relance due immédiatement (délai 0 h ouvrée).
        _, page = self._poster("/assistant/message", {
            "b": identifiant, "action": "continuer",
            "info_entreprise": "Cabinet Essai", "ordre": "liste",
            "opt_recontacter": "1", "opt_liberer": "1", "opt_repondeur": "1",
            "relance_mode": "delai", "relance_delai": "0", "relance_max": "3"})
        self.assertIn("3. Les personnes", page)
        # ③ reprise DEPUIS LA BASE : les rendez-vous à venir remplissent les
        # colonnes « rendez-vous existant » et « motif » de la grille.
        # ⚠ Le libellé DIT maintenant ce que la source contient. « à venir »
        # ne prend que les rendez-vous PAS ENCORE confirmés ; pour tout ce
        # qui occupe une place (prévus + confirmés), c'est « posés » — la
        # source ajoutée le 02/08/2026, celle qui compte comme le planning.
        self.assertIn("Rendez-vous à venir, pas encore confirmés", page)
        self.assertIn("prévus ET confirmés (comme au planning)", page)
        _, page = self._poster("/assistant/importer", {
            "b": identifiant, "mode": "base", "source": "a_venir"})
        self.assertIn("2 contact(s) ajouté(s)", page)
        self.assertIn("M. Hesitant Exemple", page)
        self.assertIn("Bilan annuel", page)
        self.assertNotIn("+33 6 00 00 00 55", page)          # masqué
        _, page = self._poster("/assistant/liste",
                               {"b": identifiant, "action": "valider"})
        self.assertIn("prête", page)
        campagne = base.lister_campagnes()[0]
        self.assertEqual(campagne["theme"], "confirmation")  # THÈME sauvegardé
        self.assertEqual(campagne["nature"], "confirmation")
        mission = campagne["mission"]                        # PARAMÈTRES gardés
        self.assertIn("merci de me confirmer votre présence", mission)
        self._demarrer(campagne["id"])
        self._attendre_statut(campagne["id"], "terminée")
        etats = {c["nom"]: c for c in base.contacts_de_campagne(campagne["id"])}
        # ⚠ LA RÈGLE A CHANGÉ LE 11/08/2026 (décision du propriétaire) : le
        # rappel par un humain n'existe plus que sur « déplacement de
        # rendez-vous » et « prise de rendez-vous ». Sur une CONFIRMATION, rien
        # n'attend de notre côté — le rendez-vous dont on parle est le sien, il
        # peut nous rappeler lui-même. D'où « le client rappellera », et ce qu'il
        # a dit est repris en clair : rien n'est inventé.
        self.assertEqual(etats["M. Hesitant Exemple"]["etat"],
                         "le client rappellera")
        self.assertEqual(etats["M. Hesitant Exemple"]["issue"], "to_reschedule")
        self.assertIn("Rien n'a été conclu au téléphone",
                      etats["M. Hesitant Exemple"]["detail"])
        self.assertIn("le client rappellera : 1",
                      self._obtenir(f"/campagne?id={campagne['id']}")[1])
        # Le rendez-vous est ANNULÉ, et sa DATE ne bouge pas.
        #
        # ⚠ CET ESSAI ATTENDAIT « prévu » JUSQU'AU 17/08/2026. Sa règle de ce
        # jour-là : « si la personne doit rappeler, le rendez-vous est simplement
        # annulé ». Ce qui reste vrai de l'ancienne raison : on ne le passe
        # SURTOUT pas « confirmé » — ce serait inventer la confirmation qu'on n'a
        # justement pas obtenue. Mais le laisser « prévu » gardait le créneau
        # bloqué pour quelqu'un qui vient de dire qu'il ne viendra pas comme
        # prévu ; « annulé » rend la place, et la ligne reste au planning.
        rdv = [r for r in base.tous_les_rendezvous()
               if r["nom"] == "M. Hesitant Exemple"][0]
        self.assertEqual(rdv["statut"], "annulé")
        self.assertEqual(rdv["horaire"], DEMAIN)
        # Le silencieux, lui, programme une relance qui CONSERVE le thème.
        self.assertEqual(etats["M. Silence Deux"]["etat"], "à recontacter")
        relance = base.relances_dues()[0]
        self.assertEqual(relance["campagne_theme"], "confirmation")
        self.assertEqual(relance["motif"], "pas de réponse")
        self.assertEqual(relance["telephone_masque"], "+33 6 •• •• •• 53")
        self.assertEqual(base.obtenir_campagne(relance["campagne_id"])["mission"],
                         mission)
        # La page Relances porte le thème conservé, en toutes lettres.
        _, relances_page = self._obtenir("/relances")
        self.assertIn("Confirmation de rendez-vous", relances_page)
        self.assertIn("pas de réponse", relances_page)
        self.assertNotIn("+33 6 00 00 00 5", relances_page)
        # La fiche : issue affichée, transcription avec la mission substituée
        # pour CE contact (date et motif du rendez-vous), jamais le numéro.
        _, fiche = self._obtenir(f"/campagne?id={campagne['id']}")
        self.assertIn("À reprogrammer (date non conclue)", fiche)
        self.assertIn("Agent : Bonjour M. Hesitant Exemple", fiche)
        self.assertIn("pour Bilan annuel : merci de me confirmer votre présence.",
                      fiche)
        self.assertNotIn("+33 6 00 00 00 55", fiche)


class TestAssistantUnite(unittest.TestCase):
    """L'assistant en 3 étapes : les briques unitaires ciblées (maquette)."""

    def test_collage_multi_colonnes_avec_dates_validees(self):
        champs = assistant.champs_campagne(
            {"champs": list(assistant.NATURES["creneau_libere"]["champs"])})
        contacts, erreurs, refusees = assistant.analyser_collage(
            f"Mme Une Exemple;+33 6 00 00 00 51;{DEMAIN};Séance\n"
            "M. Deux Exemple;0600000052\n"
            "M. Date Fausse;0600000053;bientôt;Séance\n", champs)
        self.assertEqual(len(contacts), 2)
        self.assertEqual(contacts[0]["champs"],
                         {"rdv_existant": DEMAIN, "motif": "Séance"})
        self.assertEqual(contacts[1]["champs"], {})     # colonnes ⚠ à compléter
        # Ligne 2 : colonnes ⚠ absentes -> SIGNALÉE en disant ce qui est
        # attendu, mais la ligne est gardée (elle se complète dans la grille).
        ligne_manque = [e for e in erreurs if "Ligne 2" in e][0]
        self.assertIn("il manque", ligne_manque)
        self.assertIn("Rendez-vous existant", ligne_manque)
        self.assertIn("Motif", ligne_manque)
        # Ligne 3 : date illisible -> REFUSÉE, et rendue pour correction.
        ligne_date = [e for e in erreurs if "Ligne 3" in e][0]
        self.assertIn("Date illisible", ligne_date)
        self.assertEqual(refusees, ["M. Date Fausse;0600000053;bientôt;Séance"])

    def test_periode_interdite_traverse_minuit(self):
        prefs = generation.Preferences()
        prefs.definir(assistant.CLE_INTERDIT_DEBUT, "20:00")
        prefs.definir(assistant.CLE_INTERDIT_FIN, "08:00")
        soir = datetime.datetime(2026, 7, 28, 21, 30)
        matin = datetime.datetime(2026, 7, 29, 7, 0)
        midi = datetime.datetime(2026, 7, 29, 12, 0)
        self.assertIn("période interdite",
                      assistant.dans_periode_interdite(prefs, soir))
        self.assertIn("période interdite",
                      assistant.dans_periode_interdite(prefs, matin))
        self.assertIsNone(assistant.dans_periode_interdite(prefs, midi))


class TestAssistantCampagne(_TestAvecServeurWeb):
    """LE parcours nominal de l'assistant (spécification v1.1), en vraies
    requêtes HTTP : créneau libéré → ⚠ bloque → renseigner → collage →
    valider (prête, personne n'est appelé) → démarrer en simulation →
    arrêt au premier oui + épargné + ancien rendez-vous libéré."""

    def test_parcours_nominal_creneau_libere(self):
        base = self.application.base
        # Le futur « oui » a déjà un rendez-vous en base : il sera libéré.
        rdv_lointain = (datetime.datetime.now() + datetime.timedelta(days=10)
                        ).replace(hour=9, minute=0, second=0, microsecond=0
                                  ).isoformat(timespec="minutes")
        client_id = base.ajouter_client("Mme Accord Trois",
                                        "+33 6 00 00 00 51")
        rdv_ancien = base.ajouter_rendezvous(client_id, rdv_lointain,
                                             "Séance d'essai")
        # Étape 1 : les huit cartes, politique par défaut affichée ; le fil
        # d'Ariane montre l'étape courante et bloque celles pas atteignables.
        statut, page = self._obtenir("/assistant")
        self.assertEqual(statut, 200)
        self.assertGreaterEqual(page.count("carte-nature"), 5)
        self.assertIn("arrêt au premier OUI", page)
        self.assertIn('class="fil-ariane"', page)
        self.assertIn("1. La nature", page)
        self.assertIn("fa-etape fa-courante", page)
        # Nature « créneau libéré » → étape 2, aperçu vivant. L'étape 1 devient
        # cliquable (changer de nature), l'étape 3 reste bloquée.
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        self.assertIn('<a id="fa-etape-1" class="fa-etape fa-faite" '
                      'href="/assistant">', page)
        self.assertIn("2. Le message", page)
        self.assertIn("fa-bloquee", page)          # étape 3 pas atteignable
        self.assertIn('id="apercu"', page)
        self.assertIn("var-manquante", page)  # variables en rouge
        b = self._brouillon(page)
        formulaire = {
            "b": b, "action": "continuer", "info_entreprise": "Cabinet Essai",
            "ordre": "liste", "opt_recontacter": "1", "opt_liberer": "1",
            "opt_repondeur": "1", "relance_mode": "delai",
            "relance_delai": "4", "relance_max": "3"}
        # ⚠ : continuer SANS la date du créneau libéré est REFUSÉ (serveur).
        _, page = self._poster("/assistant/message", formulaire)
        self.assertIn("obligatoire pour cette nature", page)
        self.assertIn('id="apercu"', page)                 # on n'est pas passé
        self.assertNotIn("3. Les personnes</span></a>", page)  # étape 3 fermée
        # Renseigner la date → étape 3 (le fil d'Ariane s'ouvre jusqu'au bout).
        formulaire["info_creneau_libere"] = DEMAIN
        _, page = self._poster("/assistant/message", formulaire)
        self.assertIn("3. Les personnes", page)
        self.assertIn('<a id="fa-etape-2" class="fa-etape fa-faite" '
                      f'href="/assistant/message?b={b}">', page)
        # ⚠ L'ÉTAPE ③ S'OUVRE EN AUTOMATIQUE depuis le 09/08/2026. Ce parcours
        # éprouve la grille, du collage à la validation : il demande donc le
        # mode MANUEL, comme le fera l'opérateur qui veut choisir ses gens.
        _, page = self._poster("/assistant/liste",
                               {"b": b, "action": "liste:manuel"})
        # Les deux traits d'avancement sont pleins (le style CSS ne compte pas).
        self.assertEqual(page.count('class="fa-trait fa-trait-fait"'), 2)
        # Collage : 3 contacts (fins 52, 53, 51) + un 4e pour prouver
        # l'épargne — la 4e ligne SANS rendez-vous existant (⚠ vide).
        _, page = self._poster("/assistant/importer", {
            "b": b, "mode": "collage", "liste":
            f"Mme Refus Un;+33 6 00 00 00 52;{rdv_lointain};Séance\n"
            f"M. Silence Deux;+33 6 00 00 00 53;{rdv_lointain};Séance\n"
            f"Mme Accord Trois;+33 6 00 00 00 51;{rdv_lointain};Séance d'essai\n"
            "M. Épargné Quatre;+33 6 00 00 00 49\n"})
        self.assertIn("4 contact(s) ajouté(s)", page)
        self.assertIn("•• •• ••", page)                    # grille masquée
        self.assertNotIn("+33 6 00 00 00 51", page)
        # ⚠ de la grille : valider avec la ligne 4 incomplète est REFUSÉ.
        # UNE SEULE PHRASE depuis le 02/08/2026, et la CASE fautive colorée :
        # trente phrases identiques ne disaient jamais où taper.
        _, page = self._poster("/assistant/liste", {"b": b, "action": "valider"})
        self.assertIn(assistant.MESSAGE_CHAMPS_OBLIGATOIRES, page)
        self.assertIn('name="c_rdv_existant_4" class="manque"', page)
        # Et une ligne complète n'est PAS colorée.
        self.assertNotIn('name="c_rdv_existant_1" class="manque"', page)
        # Compléter la ligne 4 dans la grille, puis valider.
        self._poster("/assistant/liste", {
            "b": b, "action": "enregistrer",
            "c_rdv_existant_4": rdv_lointain, "c_motif_4": "Séance"})
        _, page = self._poster("/assistant/liste", {"b": b, "action": "valider"})
        self.assertIn("prête", page)
        campagne = base.lister_campagnes()[0]
        self.assertEqual(campagne["statut"], "prête")
        contacts = base.contacts_de_campagne(campagne["id"])
        for contact in contacts:                            # PERSONNE n'est appelé
            self.assertEqual(base.appels_du_contact_campagne(contact["id"]), [])
        # ▶ Démarrer : le fil appelle un contact à la fois, en simulation.
        _, page = self._demarrer(campagne["id"])
        self._attendre_statut(campagne["id"], "terminée")
        etats = {c["nom"]: c for c in base.contacts_de_campagne(campagne["id"])}
        self.assertEqual(etats["Mme Refus Un"]["etat"], "refusé")        # 52
        self.assertEqual(etats["M. Silence Deux"]["etat"], "à recontacter")  # 53
        self.assertEqual(etats["Mme Accord Trois"]["etat"], "accepté")   # 51
        # Arrêt au premier oui : le 4e n'a JAMAIS été appelé.
        self.assertEqual(etats["M. Épargné Quatre"]["etat"], "épargné")
        self.assertEqual(base.appels_du_contact_campagne(
            etats["M. Épargné Quatre"]["id"]), [])
        # ⚠ UNE SEULE LIGNE, QUI CHANGE DE DATE (décision du propriétaire du
        # 14/08/2026 : « tu déplaces un rendez-vous d'une date à une autre »).
        # Avant, on créait une SECONDE ligne à la nouvelle date et on marquait
        # l'ancienne « déplacé » : elle restait dans l'agenda, et il voyait deux
        # rendez-vous pour un seul déplacement. C'est la MÊME ligne qui bouge,
        # et elle est confirmée — l'histoire, elle, vit au cahier.
        ancien = base.obtenir_rendezvous(rdv_ancien)
        self.assertEqual(ancien["statut"], "confirmé")
        self.assertEqual(ancien["horaire"], DEMAIN)
        self.assertIn("DÉPLACÉ", etats["Mme Accord Trois"]["detail"])
        # Et le cahier porte UN SEUL geste : un déplacement avec ses deux
        # dates, pas un couple suppression + ajout qui en raconterait deux.
        changements = base.changements_de_campagne(campagne["id"])
        gestes = [c["genre"] for c in changements
                  if c["nom"] == "Mme Accord Trois"]
        self.assertIn("deplacement", gestes)
        self.assertNotIn("suppression", gestes)
        self.assertNotIn("ajout", gestes)
        ligne = next(c for c in changements
                     if c["nom"] == "Mme Accord Trois"
                     and c["genre"] == "deplacement")
        self.assertTrue(ligne["ancienne_date"])
        self.assertEqual(ligne["nouvelle_date"], DEMAIN)
        nouveaux = [r for r in base.tous_les_rendezvous()
                    if r["nom"] == "Mme Accord Trois"
                    and r["statut"] == "confirmé"]
        self.assertEqual([r["horaire"] for r in nouveaux], [DEMAIN])
        # La relance du silencieux est annulée : l'objectif est atteint.
        relances = base.relances_de_campagne(campagne["id"])
        self.assertEqual([r["statut"] for r in relances], ["annulée"])
        # Le poste de pilotage : accepté mis en valeur, épargné, masqué.
        _, fiche = self._obtenir(f"/campagne?id={campagne['id']}")
        self.assertIn("ligne-acceptee", fiche)
        self.assertIn("épargné", fiche)
        # Le décalage en cascade n'est plus « à venir » : il est réglable, et
        # cette campagne ne l'a pas coché — la fiche le dit en clair.
        self.assertIn("Décaler en cascade : non", fiche)
        # ⚠ LE CAHIER PORTE UN SEUL GESTE depuis le 03/08/2026 : ce OUI a
        # DÉPLACÉ le rendez-vous. Écrire « supprimé » puis « ajouté » aurait
        # raconté deux gestes pour un seul, et l'opérateur qui recopie dans
        # son logiciel aurait retiré une ligne pour en créer une autre.
        self.assertIn("Le cahier des changements à reporter", fiche)
        self.assertIn("Rendez-vous déplacé", fiche)
        self.assertNotIn("Rendez-vous supprimé", fiche)
        self.assertNotIn("+33 6 00 00 00 5", fiche)
        self.assertNotIn("+33 6 00 00 00 49", fiche)

    def test_periode_interdite_bloque_le_demarrage(self):
        # Réglée PAR L'ÉCRAN ⚙, la période interdite couvre tout le jour :
        # le ▶ Démarrer est réellement refusé, la campagne reste « prête ».
        # Le démarrage part ici AVEC le geste sur l'agenda : c'est la preuve
        # que la période interdite reste prioritaire — le nouveau rappel ne
        # s'intercale pas devant les verrous existants.
        self._poster("/reglages/enregistrer", {
            "entreprise": "Cabinet Essai", "plage_debut": "00:00",
            "plage_fin": "23:59", "interdit_debut": "00:00",
            "interdit_fin": "23:59"})
        _, page = self._poster("/assistant/nature", {"nature": "prise_rdv"})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "ordre": "liste",
            "info_entreprise": "Cabinet Essai",
            "info_origine": "vous avez demandé un rendez-vous",
            "info_creneaux_proposes": "lundi 10h, mardi 14h",
            "mission": "Bonjour [identite], petit message.",
            "mission_editee": "1"})
        self._poster("/assistant/importer", {
            "b": b, "mode": "collage", "liste": "Mme Test;+33 6 00 00 00 41"})
        self._poster("/assistant/liste", {"b": b, "action": "valider"})
        campagne = self.application.base.lister_campagnes()[0]
        self.assertEqual(campagne["statut"], "prête")
        with self.assertRaises(urllib.error.HTTPError) as contexte:
            self._demarrer(campagne["id"])
        self.assertEqual(contexte.exception.code, 403)
        self.assertIn("période interdite",
                      contexte.exception.read().decode("utf-8"))
        self.assertEqual(self.application.base.obtenir_campagne(
            campagne["id"])["statut"], "prête")             # rien n'a bougé

    def test_etape3_voies_format_attendu_et_saisie_conservee(self):
        """Étape 3 : radios qui ouvrent un écran, format attendu, saisie gardée."""
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "info_entreprise": "Cabinet Essai",
            "info_creneau_libere": DEMAIN, "politique": "premier_oui",
            "ordre": "liste", "opt_recontacter": "1", "relance_mode": "delai",
            "relance_delai": "4", "relance_max": "3"})
        # Chaque voie de remplissage OUVRE un écran différent : ici les boutons
        # radio sont la bonne forme, et un seul panneau est ouvert au départ.
        _, page = self._poster("/assistant/importer", {
            "b": b, "mode": "collage", "liste":
            f"Mme Bonne Ligne;+33 6 00 00 00 51;{DEMAIN};Séance\n"
            "M. Date Fausse;+33 6 00 00 00 53;bientôt;Séance\n"})
        # SIX voies depuis le 02/08/2026 : « Reprendre depuis la base »
        # mélangeait deux questions sans rapport (quelles DATES ? quels
        # CLIENTS ?) ; elle est décomposée en trois voies distinctes, rangées
        # en deux colonnes — ce qu'on apporte, et ce que RingBack a déjà.
        self.assertEqual(page.count('name="remplissage"'), 6)
        self.assertEqual(page.count('class="panneau" id="panneau-'), 6)
        self.assertEqual(page.count('id="panneau-collage">'), 1)   # ouvert
        self.assertEqual(len(re.findall(r'id="panneau-\w+" hidden', page)), 5)
        self.assertEqual(page.count('class="deux-colonnes"'), 1)
        for voie in ("clients", "rendezvous", "campagne"):
            with self.subTest(voie=voie):
                self.assertIn(f'id="panneau-{voie}" hidden', page)
        # Le format attendu est affiché, colonnes obligatoires marquées, et un
        # exemple en filigrane (jamais envoyé : ce serait un faux contact).
        self.assertIn("Nom;Téléphone;Rendez-vous existant (date + heure) ⚠;"
                      "Motif ⚠", page)
        self.assertIn('placeholder="Mme Dupont Martine;+33 6 39 98 12 34;', page)
        # Le message d'erreur dit ce qui était ATTENDU, pas juste ce qui cloche.
        self.assertIn("Date illisible", page)
        # La ligne refusée revient dans la zone ; la bonne, déjà dans la
        # grille, n'y revient PAS (sinon second envoi = doublon).
        zone = re.search(r'<textarea name="liste"[^>]*>(.*?)</textarea>',
                         page, re.S).group(1)
        self.assertIn("M. Date Fausse", zone)
        self.assertNotIn("Mme Bonne Ligne", zone)
        # Le numéro masqué est DANS son champ (pas au-dessus : pas de décalage)
        # et le renvoyer tel quel vaut « inchangé ».
        self.assertIn('name="tel_1" value="+33 6 •• •• •• 51"', page)
        self.assertNotIn("+33 6 00 00 00 51", page)
        _, page = self._poster("/assistant/liste", {
            "b": b, "action": "enregistrer", "nom_1": "Mme Bonne Ligne",
            "tel_1": "+33 6 •• •• •• 51", "c_rdv_existant_1": DEMAIN,
            "c_motif_1": "Séance"})
        self.assertIn('name="tel_1" value="+33 6 •• •• •• 51"', page)
        self.assertNotIn("À corriger", page)

    def test_regles_de_forme_des_formulaires(self):
        """Les règles d'interface : sélecteurs, options révélées, sans rechargement."""
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        b = self._brouillon(page)
        # Règle : un sélecteur plutôt qu'une pile de boutons radio.
        self.assertNotIn('<input type="radio"', page)
        for nom in ('name="politique"', 'name="relance_mode"', 'name="ordre"'):
            self.assertIn(f"<select class=\"select-option\" {nom}", page)
        # ⚠ ORDRE D'APPEL RENVERSÉ LE 03/08/2026 : « créneau libéré » propose
        # désormais le rendez-vous le plus LOINTAIN d'abord — c'est lui qui a
        # le plus à gagner à avancer sur la place qui se libère. Le choix
        # reste ouvert.
        self.assertIn('<option value="eloignement" selected>', page)
        self.assertIn("— à choisir —", page)
        # Une nature sans ordre évident ne présélectionne toujours RIEN.
        _, libre = self._poster("/assistant/nature", {"nature": "prise_rdv"})
        self.assertIn('<option value="" selected>— à choisir —</option>', libre)
        # Règle : une case à cocher ne prend jamais toute la largeur.
        self.assertIn('<label class="option">', page)
        # Règle : les options d'une option sont dans un bloc que le script
        # révèle seulement quand la parente est active.
        for bloc in ("bloc-relance", "bloc-delai", "bloc-creneau", "bloc-cascade"):
            self.assertIn(f'id="{bloc}"', page)
        self.assertIn("b.hidden=!(r&&r.checked)", page)      # le dévoilement
        # Règle : ajouter un champ ne recharge pas la page — il voyage dans le
        # formulaire et arrive en colonne à l'étape 3.
        formulaire = {
            "b": b, "action": "continuer", "info_entreprise": "Cabinet Essai",
            "info_creneau_libere": DEMAIN, "politique": "premier_oui",
            "ordre": "liste", "opt_recontacter": "1", "relance_mode": "delai",
            "relance_delai": "4", "relance_max": "3",
            "champ_perso": ["Numéro de dossier|texte|", "Visite|date|1"]}
        _, page = self._poster("/assistant/message", formulaire)
        self.assertIn("Numéro de dossier", page)
        self.assertIn("Visite", page)
        # Retirer un champ = ne plus l'envoyer ; les autres restent.
        formulaire["champ_perso"] = ["Numéro de dossier|texte|"]
        _, page = self._poster("/assistant/message", formulaire)
        self.assertIn("Numéro de dossier", page)
        self.assertNotIn("Visite", page)


class TestVerificationAgendaAvantDemarrage(_TestAvecServeurWeb):
    """▶ Démarrer demande un GESTE CONSCIENT sur l'état de l'agenda.

    Le travail est double (§8.1 de CAS_DE_FIGURE_CAMPAGNES.md) : ce qui se
    décide au téléphone change l'agenda LOCAL de RingBack **et** alimente le
    cahier des changements à reporter dans le logiciel de planification. Les
    créneaux annoncés au téléphone étant DÉDUITS de cet agenda, un agenda
    périmé fait proposer des places déjà prises dans la vraie vie.
    Le rappel est donc montré AU MOMENT de démarrer — et nulle part
    ailleurs — avec les chiffres du jour tirés de la base.
    """

    def _campagne_prete(self, contacts="Mme Essai Une;+33 6 00 00 00 51",
                        nature="prise_rdv"):
        _, page = self._poster("/assistant/nature", {"nature": nature})
        b = self._brouillon(page)
        formulaire = {"b": b, "action": "continuer", "ordre": "liste",
                      "info_entreprise": "Cabinet Essai",
                      "mission": "Bonjour [identite], essai du rappel.",
                      "mission_editee": "1"}
        if nature == "prise_rdv":
            formulaire["info_origine"] = "vous avez demandé un rendez-vous"
            formulaire["info_creneaux_proposes"] = "lundi 10h, mardi 14h"
        self._poster("/assistant/message", formulaire)
        self._poster("/assistant/importer",
                     {"b": b, "mode": "collage", "liste": contacts})
        self._poster("/assistant/liste", {"b": b, "action": "valider"})
        campagne = self.application.base.lister_campagnes()[0]
        self.assertEqual(campagne["statut"], "prête")
        return campagne["id"]

    def _agenda_garni(self):
        """Une semaine type ouverte tous les jours + trois rendez-vous connus."""
        preferences = self.application.preferences
        preferences.definir(horaires.CLE_SEMAINE,
                            {str(jour): [[540, 720]] for jour in range(7)})
        base = self.application.base
        client = base.ajouter_client("Mme Agenda Essai", "+33 6 00 00 00 61")
        demain = (datetime.datetime.now() + datetime.timedelta(days=1)).replace(
            hour=9, minute=0, second=0, microsecond=0)
        base.ajouter_rendezvous(client, demain.isoformat(timespec="minutes"),
                                "Séance", statut="prévu")
        base.ajouter_rendezvous(
            client, (demain + datetime.timedelta(minutes=30)).isoformat(
                timespec="minutes"), "Séance", statut="confirmé")
        # Un annulé : CONNU sur la période, mais il n'occupe plus sa place.
        base.ajouter_rendezvous(
            client, (demain + datetime.timedelta(minutes=60)).isoformat(
                timespec="minutes"), "Séance", statut="annulé")

    def test_aucun_appel_ne_part_sans_le_geste(self):
        campagne_id = self._campagne_prete()
        base = self.application.base
        _, page = self._poster("/campagne/demarrer", {"campagne": campagne_id})
        # La campagne n'a pas bougé, et personne n'a été composé.
        self.assertEqual(base.obtenir_campagne(campagne_id)["statut"], "prête")
        for contact in base.contacts_de_campagne(campagne_id):
            self.assertEqual(base.appels_du_contact_campagne(contact["id"]), [])
        # La page revient AVEC le rappel ouvert (le repli sans JavaScript) :
        # la raison est dite, et rien n'est perdu.
        self.assertIn("Rien n&#x27;est parti", page)
        self.assertIn('class="verif-agenda"', page)
        self.assertIn("sortent de l&#x27;agenda de RingBack", page)
        self.assertIn('name="agenda_verifie"', page)
        self.assertNotIn("+33 6 00 00 00 51", page)      # numéro jamais en clair

    def test_le_geste_lance_vraiment_la_campagne(self):
        campagne_id = self._campagne_prete()
        _, page = self._poster("/campagne/demarrer",
                               {"campagne": campagne_id, "agenda_verifie": "1"})
        self.assertIn("Campagne démarrée", page)
        self._attendre_statut(campagne_id, "terminée")

    def test_les_chiffres_du_panneau_sont_ceux_de_la_base(self):
        """Aucun chiffre inventé : le panneau et la base disent la même chose."""
        self._agenda_garni()
        campagne_id = self._campagne_prete(
            "Mme Essai Une;+33 6 00 00 00 51\nM. Essai Deux;+33 6 00 00 00 52")
        base, preferences = self.application.base, self.application.preferences

        def places_libres():
            return len([creneau for creneau
                        in horaires.creneaux_proposables(base, preferences)
                        if not creneau["occupe"]])

        # Le nombre de places bouge avec l'heure : on ne compare que si le
        # calcul donne la même chose juste avant et juste après la demande.
        for _ in range(3):
            avant = places_libres()
            _, panneau = self._obtenir(
                f"/campagne/verification-agenda?id={campagne_id}")
            apres = places_libres()
            if avant == apres:
                break
        self.assertEqual(avant, apres, "le calcul a changé pendant l'essai")
        self.assertIn(f"<strong>{avant}</strong> place(s) libre(s)", panneau)
        # Trois rendez-vous connus sur la période, dont deux qui occupent.
        self.assertIn("<strong>3</strong> rendez-vous connu(s)", panneau)
        self.assertIn("<strong>2</strong> qui occupe(nt)", panneau)
        self.assertIn("<strong>2</strong> personne(s) à appeler", panneau)
        # Les premières places annoncées sont celles que RingBack proposera.
        self.assertIn(horaires.creneaux_lisibles(base, preferences, limite=3),
                      panneau)
        self.assertNotIn("+33 6 00 00 00 5", panneau)    # jamais de numéro

    def test_agenda_douteux_le_panneau_le_dit_franchement(self):
        """Aucune semaine type, aucun rendez-vous : c'est dit, pas enrobé."""
        campagne_id = self._campagne_prete()
        _, panneau = self._obtenir(
            f"/campagne/verification-agenda?id={campagne_id}")
        self.assertIn("Ce que RingBack constate lui-même", panneau)
        self.assertIn("Aucune semaine type n&#x27;est réglée", panneau)
        self.assertIn("Aucun rendez-vous n&#x27;est connu sur la période",
                      panneau)
        # Aucune trace d'import : c'est dit INCONNU, jamais une date inventée.
        self.assertIn("Dernier import de rendez-vous par fichier : "
                      "<strong>inconnu</strong>", panneau)
        # Le bouton change de mot quand il y a un doute : on ne clique pas le
        # même bouton par habitude.
        self.assertIn("Démarrer quand même", panneau)

    def test_agenda_sain_le_bouton_porte_les_chiffres(self):
        self._agenda_garni()
        campagne_id = self._campagne_prete()
        _, panneau = self._obtenir(
            f"/campagne/verification-agenda?id={campagne_id}")
        self.assertNotIn("Ce que RingBack constate lui-même", panneau)
        self.assertIn("Oui, l&#x27;agenda est à jour", panneau)
        self.assertIn("1 personne(s), ", panneau)
        self.assertIn("place(s) libre(s)</button>", panneau)

    def test_la_date_du_dernier_import_vient_de_l_import_reel(self):
        """La date affichée est écrite PAR l'import, pas devinée."""
        frontiere = "----frontiereAgenda"
        with open(os.path.join(RACINE, "exemple_agenda.ics"),
                  encoding="utf-8") as fichier:
            contenu = fichier.read()
        corps = (f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="fichier"; '
                 'filename="agenda.ics"\r\n'
                 "Content-Type: text/calendar\r\n\r\n"
                 f"{contenu}\r\n--{frontiere}--\r\n").encode("utf-8")
        requete = urllib.request.Request(
            self.racine + "/importer-ics", data=corps,
            headers={"Content-Type": f"multipart/form-data; boundary={frontiere}"})
        with urllib.request.urlopen(requete, timeout=10) as reponse:
            reponse.read()
        trace = horaires.dernier_import_agenda(self.application.preferences)
        self.assertEqual(trace["quoi"], "agenda ICS")
        self.assertEqual(trace["rendezvous"], 3)         # le fichier en porte 3
        campagne_id = self._campagne_prete()
        _, panneau = self._obtenir(
            f"/campagne/verification-agenda?id={campagne_id}")
        self.assertIn(themes.date_lisible(trace["quand"]), panneau)
        self.assertIn("agenda ICS, 3 rendez-vous", panneau)

    def test_le_rappel_n_est_montre_qu_au_moment_de_demarrer(self):
        """Un avertissement qu'on voit partout ne se lit plus nulle part."""
        campagne_id = self._campagne_prete()
        for chemin in ("/", "/suivi", "/clients", "/relances", "/reglages"):
            _, page = self._obtenir(chemin)
            self.assertNotIn('class="verif-agenda"', page, chemin)
        # Sur le poste de pilotage lui-même, le bloc existe mais reste VIDE
        # tant que le clic ne l'a pas demandé au serveur.
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn('<div id="verification-agenda" hidden></div>', page)
        self.assertNotIn('class="verif-agenda"', page)
        # Une fois la campagne lancée, le rappel n'a plus lieu d'être.
        self._demarrer(campagne_id)
        self._attendre_statut(campagne_id, "terminée")
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertNotIn('id="verification-agenda"', page)


class TestJeuEssai(unittest.TestCase):
    """Le jeu d'essai : chargé sur geste explicite, additif, retirable."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)

    def test_numeros_dans_les_racines_reservees_a_la_fiction(self):
        # Garde-fou : AUCUN numéro du jeu d'essai ne doit pouvoir sonner chez
        # quelqu'un. Tous viennent des six racines que l'Arcep réserve aux
        # œuvres audiovisuelles (voir jeu_essai.py pour la source).
        terminaisons = set()
        for nom, telephone, _ in jeu_essai.CLIENTS:
            if not telephone:
                continue
            compact = re.sub(r"\D", "", telephone)
            racines = {re.sub(r"\D", "", r) for r in jeu_essai.RACINES_FICTION}
            self.assertTrue(any(compact.startswith(r) for r in racines),
                            f"{nom} : {telephone} hors des racines de fiction")
            terminaisons.add(compact[-2:])
        # Une poignée porte les terminaisons que le simulateur reconnaît :
        # une campagne d'essai produit ainsi tous les cas de figure.
        self.assertTrue({"51", "52", "53", "54", "55", "56"} <= terminaisons)
        # ⚠ ET AUCUN CONTACT NE PORTE 57, 58 NI 59 : ces trois-là laissent une
        # trace durable ou mettent la campagne en pause. Posés sur un contact
        # d'essai, ils changeraient toutes les campagnes qui le croisent — et le
        # banc ne rendrait plus deux fois le même rapport.
        self.assertFalse({"57", "58", "59"} & terminaisons)

    def test_recharger_un_autre_jour_ne_double_pas_l_agenda(self):
        """⚠ LE CAS RÉEL : on recharge le jeu d'essai DES JOURS PLUS TARD, pour
        récupérer des données de démonstration enrichies.

        Les horaires étant calculés depuis « maintenant », comparer par horaire
        n'aurait rien reconnu — d'où l'identité (patient, motif). Sans elle,
        chaque rechargement ajoutait 112 rendez-vous de plus.
        """
        jeu_essai.charger(self.base)
        combien = len(self.base.tous_les_rendezvous())
        demain = datetime.datetime.now() + datetime.timedelta(days=1)
        self.assertEqual(jeu_essai.charger(self.base, maintenant=demain),
                         (0, 0))
        self.assertEqual(len(self.base.tous_les_rendezvous()), combien)

    def test_un_rendez_vous_de_demonstration_a_une_identite_unique(self):
        """CLIQUET SUR L'IDENTITÉ. Le dédoublonnage repose sur (patient, motif) :
        si deux lignes du jeu d'essai partageaient ce couple, l'une d'elles ne
        serait plus jamais chargée — en silence."""
        vus, doubles = set(), set()
        for entree in jeu_essai.RENDEZVOUS:
            cle = (entree[0], entree[4])
            if cle in vus:
                doubles.add(cle)
            vus.add(cle)
        self.assertEqual(doubles, set())

    def test_le_jeu_d_essai_porte_sur_cent_jours(self):
        """⚠ LA DEMANDE DU 11/08/2026 : « puisqu'on a du 90 jours on devrait
        avoir des exemples sur 100 jours ».

        MESURÉ AVANT : le rendez-vous à venir le plus lointain était à +9 jours.
        Une place libérée au-delà ne trouvait donc PERSONNE, et les options
        « jusqu'à 30 jours » et « jusqu'à 90 jours » de la règle de liste ne
        pouvaient rien donner de différent de « sans limite ».
        """
        futurs = [jours for _, jours, *_ in jeu_essai.RENDEZVOUS if jours > 0]
        self.assertGreaterEqual(max(futurs), 90,
                                "il faut de la matière au-delà de 90 jours")
        # Réparti, pas entassé : chaque mois du trimestre en a.
        for borne_basse, borne_haute in ((10, 30), (30, 60), (60, 90),
                                         (90, 101)):
            with self.subTest(entre=(borne_basse, borne_haute)):
                self.assertTrue([j for j in futurs
                                 if borne_basse <= j < borne_haute])

    def test_deux_patients_n_ont_de_rendez_vous_qu_au_dela_de_quatre_vingt_dix(self):
        """⚠ LA CORRECTION NÉE D'UNE MESURE. Quatre rendez-vous passent 90 jours,
        mais ils appartenaient à des patients qui en ont AUSSI un plus proche —
        or la liste ne retient qu'un rendez-vous par personne, le premier.
        « Jusqu'à 90 jours après » rendait donc encore exactement la même liste
        que « sans limite ». Il faut des gens dont le SEUL rendez-vous soit hors
        de la fenêtre pour que la fenêtre se voie.
        """
        par_client = {}
        for nom, jours, *_ in jeu_essai.RENDEZVOUS:
            par_client.setdefault(nom, []).append(jours)
        seulement_loin = [nom for nom, jours in par_client.items()
                          if jours and min(jours) > 90]
        self.assertGreaterEqual(len(seulement_loin), 2, par_client)

    def test_la_source_des_deplaces_en_attente_garde_ses_candidats(self):
        """⚠ LE GARDE-FOU DU RENFORT. « Déplacés en attente » ne retient que les
        clients SANS aucun rendez-vous à venir : donner une séance lointaine aux
        six patients qui la servent les en aurait sortis, et une nature de
        campagne entière n'aurait plus eu de matière.
        """
        jeu_essai.charger(self.base)
        candidats, _, _ = self.base.candidats_cascade("deplaces")
        self.assertGreaterEqual(len(candidats), 6)

    def test_charge_puis_retire_sans_toucher_aux_vraies_donnees(self):
        mien = self.base.ajouter_client("Mme Vraie Cliente",
                                        "+33 6 00 00 00 42")
        self.base.ajouter_rendezvous(mien, DEMAIN, "Mon vrai rendez-vous")
        self.assertFalse(jeu_essai.est_charge(self.base))
        clients, rendezvous = jeu_essai.charger(self.base)
        self.assertEqual(clients, len(jeu_essai.CLIENTS))
        self.assertEqual(rendezvous, len(jeu_essai.RENDEZVOUS))
        self.assertTrue(jeu_essai.est_charge(self.base))
        # Additif : le client de l'utilisateur est toujours là, non marqué.
        self.assertEqual(self.base.compter_clients(), clients + 1)
        self.assertFalse(self.base.obtenir_client(mien)["jeu_essai"])
        # ⚠ UN SECOND CHARGEMENT NE DOUBLE RIEN — NI LES CLIENTS, NI LES
        # RENDEZ-VOUS. Cet essai ne regardait que les CLIENTS, et le défaut est
        # passé dessous : les rendez-vous, eux, étaient recréés à chaque fois.
        # Mesuré le 11/08/2026 : 112, puis 224, puis 336. Et c'est un défaut qui
        # mord — pour obtenir des données enrichies il FAUT recharger.
        agenda_avant = len(self.base.tous_les_rendezvous())
        self.assertEqual(jeu_essai.charger(self.base), (0, 0))
        self.assertEqual(len(self.base.tous_les_rendezvous()), agenda_avant)
        # Réversible : seules les fiches 🧪 partent.
        self.base.supprimer_jeu_essai()  # (retirer() n'en est que l'alias)
        self.assertFalse(jeu_essai.est_charge(self.base))
        self.assertEqual(self.base.compter_clients(), 1)
        self.assertEqual(self.base.obtenir_client(mien)["nb_rendezvous"], 1)

    def test_contenu_realiste_annonce_avant_le_chargement(self):
        info = jeu_essai.resume()
        jeu_essai.charger(self.base)
        clients = self.base.lister_clients()
        self.assertEqual(sum(1 for c in clients if c["ne_plus_appeler"]),
                         info["ne_plus_appeler"])
        self.assertEqual(sum(1 for c in clients if not c["telephone_masque"]),
                         info["sans_numero"])
        noms = [c["nom"] for c in clients]
        self.assertEqual(noms.count("M. Jean Martin"), 2)       # homonymes
        self.assertIn("Mme Marie-Christine de La Tour du Pin", noms)  # nom long
        # Passé ET futur, avec des manqués, des annulés et des déplacés.
        statuts = {r["statut"] for r in self.base.tous_les_rendezvous()}
        self.assertTrue({"manqué", "annulé", "déplacé", "prévu"} <= statuts)


class TestImportICSRealiste(unittest.TestCase):
    """Le téléphone lu LÀ OÙ IL SE TROUVE VRAIMENT dans un .ics."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)

    @staticmethod
    def _lire(nom):
        with open(os.path.join(RACINE, nom), encoding="utf-8") as fichier:
            return fichier.read()

    def test_export_google_agenda_description_etiquetee(self):
        evenements, erreurs = ics.analyser_ics(
            self._lire("exemple_agenda_realiste.ics"))
        par_nom = {e["nom"]: e for e in evenements}
        # DESCRIPTION « Téléphone : … » (le cas de loin le plus fréquent).
        self.assertEqual(par_nom["Mme Solange Dupuis-Ferrand"]["telephone"],
                         "06 39 98 01 23")
        # DESCRIPTION « Mobile … » (autre étiquette, ligne pliée).
        self.assertEqual(par_nom["M. Théo Sanchez"]["telephone"],
                         "02 61 91 06 53")
        # Aucun numéro dans l'agenda : le contact reste SANS numéro — jamais
        # de numéro inventé, même quand la note contient d'autres nombres.
        self.assertEqual(par_nom["Mme Perrine Vasseur-Delaunay"]["telephone"], "")
        self.assertEqual(par_nom["Mme Zoé Berthier"]["telephone"], "")
        # STATUS:CANCELLED devient un rendez-vous « annulé ».
        self.assertEqual(par_nom["M. Sébastien Nguyen"]["statut"], "annulé")
        # La « journée entière » reste rejetée, en français.
        self.assertEqual(len(erreurs), 1)
        self.assertIn("journée entière", erreurs[0])

    def test_export_outlook_uri_tel_contact_et_x_alt_desc(self):
        evenements, erreurs = ics.analyser_ics(
            self._lire("exemple_agenda_outlook.ics"))
        self.assertEqual(erreurs, [])
        par_nom = {e["nom"]: e for e in evenements}
        # ATTENDEE en URI « tel: » (RFC 5545 § 3.3.3 + RFC 3966).
        self.assertEqual(par_nom["M. Hervé Dombasle"]["telephone"],
                         "+33 6 39 98 00 56")
        # CONTACT en texte libre (l'exemple même de RFC 5545 § 3.8.4.2).
        self.assertEqual(par_nom["Mme Gaëlle Le Goff"]["telephone"],
                         "06 39 98 01 14")
        # X-ALT-DESC : la version HTML qu'Outlook ajoute à DESCRIPTION.
        self.assertEqual(par_nom["Mme Noémie Fauconnier"]["telephone"],
                         "06 39 98 01 16")

    def test_import_relie_les_fiches_au_lieu_de_les_doubler(self):
        jeu_essai.charger(self.base)
        avant = self.base.compter_clients()
        importes, _ = ics.importer_ics(
            self.base, self._lire("exemple_agenda_outlook.ics"))
        self.assertEqual(importes, 3)
        # « +33 6 39 98 00 56 » et « 06 39 98 00 56 » sont le MÊME numéro :
        # aucune seconde fiche pour M. Hervé Dombasle.
        noms = [c["nom"] for c in self.base.lister_clients()]
        self.assertEqual(noms.count("M. Hervé Dombasle"), 1)
        self.assertEqual(self.base.compter_clients(), avant)
        # Le garde-fou 🚫 résiste au changement d'écriture du numéro.
        stop = self.base.conn.execute(
            "SELECT id, telephone FROM clients WHERE ne_plus_appeler = 1"
        ).fetchone()
        international = "+33 " + stop["telephone"][1:]
        self.assertTrue(self.base.telephone_exclu(international))


class TestRepriseDepuisCampagne(unittest.TestCase):
    """Repartir des RÉSULTATS d'une campagne précédente, filtrés par état."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.campagne_id = self.base.creer_campagne(
            "Rappel du 28/07", "rappel_rdv", nature="rappel_rdv")
        etats = (("Mme Injoignable Une", "06 39 98 02 01", "injoignable"),
                 ("M. Injoignable Deux", "06 39 98 02 02", "injoignable"),
                 ("Mme Refus Trois", "06 39 98 02 03", "refusé"),
                 ("M. Accepté Quatre", "06 39 98 02 04", "accepté"),
                 ("Mme Sans Numéro", "", "injoignable"),
                 ("M. Stop Six", "06 39 98 02 06", "injoignable"))
        for rang, (nom, telephone, etat) in enumerate(etats, start=1):
            self.base.ajouter_contact_campagne(
                self.campagne_id, rang, nom, telephone, etat=etat,
                champs=json.dumps({"motif": "Séance de kinésithérapie"}))
        # Le dernier a demandé 🚫 « ne plus appeler » depuis la campagne.
        client = self.base.ajouter_client("M. Stop Six", "06 39 98 02 06")
        self.base.definir_ne_plus_appeler(client, True)
        self.champs = assistant.champs_campagne(
            {"champs": [assistant._champ("motif", "Motif")]})

    def test_comptes_par_etat_visibles_avant_l_ajout(self):
        comptes = self.base.compter_contacts_par_etat(self.campagne_id)
        self.assertEqual(comptes["tous"], 6)
        self.assertEqual(comptes["injoignable"], 4)
        self.assertEqual(comptes["refusé"], 1)
        reprenables = assistant.campagnes_reprenables(self.base)
        self.assertEqual(len(reprenables), 1)
        self.assertIn("6 contact(s)", reprenables[0][1])

    def test_filtre_injoignables_ecarte_sans_numero_et_stop(self):
        contacts, complements = assistant.contacts_depuis_campagne(
            self.base, self.campagne_id, "injoignable", self.champs)
        self.assertEqual([c["nom"] for c in contacts],
                         ["Mme Injoignable Une", "M. Injoignable Deux"])
        # Les colonnes déjà remplies suivent : rien à ressaisir.
        self.assertEqual(contacts[0]["champs"]["motif"],
                         "Séance de kinésithérapie")
        self.assertIn("1 contact(s) sans numéro écarté(s)", complements)
        self.assertIn("1 contact(s) 🚫 « Ne plus appeler » écarté(s)",
                      complements)

    def test_autres_etats_et_etat_inconnu_refuse(self):
        for etat, attendu in (("refusé", 1), ("accepté", 1), ("tous", 4)):
            contacts, _ = assistant.contacts_depuis_campagne(
                self.base, self.campagne_id, etat, self.champs)
            self.assertEqual(len(contacts), attendu, f"état « {etat} »")
        with self.assertRaises(saisie.SaisieInvalide):
            assistant.contacts_depuis_campagne(
                self.base, self.campagne_id, "inventé", self.champs)


class TestInstallationUnite(unittest.TestCase):
    """La CARTE de l'installeur : ses parties, ses pages, son avancement."""

    NATURES = (("creneau_libere", "📞", "Créneau libéré"),
               ("prise_rdv", "🗓", "Prise de rendez-vous"))

    def setUp(self):
        self.prefs = generation.Preferences()

    def test_la_carte_suit_les_natures_du_produit(self):
        """Une nature retirée retire sa partie : l'installeur suit le produit,
        il ne tient pas une seconde liste qui finirait par diverger."""
        parties = installation.parties(self.NATURES)
        codes = [code for code, _, _ in parties]
        # ⚠ L'AGENDA PASSE AVANT LES CAMPAGNES (03/08/2026) : les places
        # qu'une campagne propose sortent de l'agenda, autant l'avoir rempli
        # avant de régler ce qui s'en sert.
        self.assertEqual(codes, ["bienvenue", "appel", "agenda",
                                 "nature-creneau_libere",
                                 "nature-prise_rdv", "fin"])
        # Plus aucun pictogramme décoratif dans les libellés : seules la coche
        # et la croix ont leur place dans ce menu.
        for _, libelle, _ in parties:
            with self.subTest(libelle=libelle):
                self.assertTrue(libelle.isprintable())
                self.assertNotRegex(libelle, r"[\U0001F300-\U0001FAFF☀-➿]")
        self.assertEqual([libelle for _, libelle, _ in parties],
                         ["Bienvenue", "Appeler", "Agenda", "Créneau libéré",
                          "Prise de rendez-vous", "Terminer"])
        # Deux pages par nature : ses options, puis son discours.
        pages_nature = dict((c, [p for p, _ in s]) for c, _, s in parties)
        self.assertEqual(pages_nature["nature-prise_rdv"],
                         ["prise_rdv-comportement", "prise_rdv-discours"])
        # L'agenda ne demande PAS les créneaux à proposer : ils se calculent.
        self.assertEqual(pages_nature["agenda"],
                         ["horaires", "jours-fermes", "import"])
        self.assertNotIn("creneaux", installation.pages(self.NATURES))

    def test_le_parcours_est_un_fil_sans_trou(self):
        pages = installation.pages(self.NATURES)
        self.assertEqual(pages[0], "bienvenue")
        self.assertEqual(pages[-1], "fin")
        for avant, apres in zip(pages, pages[1:]):
            self.assertEqual(installation.suivante(avant, self.NATURES), apres)
        self.assertIsNone(installation.suivante("fin", self.NATURES))
        # Une page inconnue ne casse rien : on repart du début.
        self.assertEqual(installation.page_valide("martien", self.NATURES),
                         "bienvenue")
        self.assertEqual(installation.suivante("martien", self.NATURES),
                         "bienvenue")

    def test_une_partie_ne_verdit_qu_entierement_faite(self):
        # ⚠ « calle » A REJOINT LA PARTIE « Appeler » le 10/08/2026, en TÊTE :
        # c'est ce qui décide si le produit peut appeler du tout. La partie ne
        # verdit donc qu'avec elle — l'essai le lit dans la carte au lieu de
        # recopier la liste, pour qu'un ajout futur ne le rende pas faux.
        toutes = [code for code, _ in installation.PAGES_APPELS]
        self.assertEqual(toutes[0], "calle")
        for page in toutes[:-1]:
            installation.marquer_faite(self.prefs, page)
            self.assertFalse(installation.partie_faite(
                "appel", self.prefs, self.NATURES), page)
        installation.marquer_faite(self.prefs, toutes[-1])
        self.assertTrue(installation.partie_faite("appel", self.prefs,
                                                  self.NATURES))
        # Marquer deux fois ne compte pas deux fois.
        installation.marquer_faite(self.prefs, toutes[-1])
        self.assertEqual(installation.progression(self.prefs, self.NATURES),
                         (len(toutes), len(installation.pages(self.NATURES))))

    def test_reprendre_efface_les_coches_pas_les_reglages(self):
        installation.marquer_faite(self.prefs, "identite")
        installation.marquer_terminee(self.prefs)
        self.prefs.definir(themes.CLE_ENTREPRISE, "Cabinet Essai")
        installation.rouvrir(self.prefs)
        self.assertFalse(installation.terminee(self.prefs))
        self.assertEqual(installation.faites(self.prefs), set())
        # Le réglage lui-même est intact : on refait le tour, on ne repart
        # pas de zéro.
        self.assertEqual(self.prefs.obtenir(themes.CLE_ENTREPRISE),
                         "Cabinet Essai")


class TestServeurInstallation(_TestAvecServeurWeb):
    """L'installeur à l'écran : il s'ouvre, il écrit par le même chemin que
    les ⚙ Réglages, il note ce qui est fait, et il se referme sur un geste."""

    def _natures(self):
        return [(code, fiche["icone"], fiche["nom"])
                for code, fiche in assistant.NATURES.items()]

    def _ouvert(self, page):
        """Vrai si la fenêtre de l'installeur est visible sur cette page."""
        return ('id="fond-installeur"' in page
                and 'id="fond-installeur" hidden' not in page)

    @staticmethod
    def _fenetre(page):
        """La fenêtre de l'installeur SEULE, apostrophes rétablies.

        ⚠ Deux pièges, tous deux rencontrés le 03/08/2026 :
        · la feuille de style est incluse dans chaque page, donc chercher
          « arbre-installeur » dans la page entière le trouve d'abord dans le
          CSS — l'assertion ne prouve alors rien ;
        · les libellés sont échappés (« l&#x27;agent IA »), donc un test qui
          cherche le texte tel qu'on l'écrit échoue sur une page correcte.
        """
        # ⚠ Le préfixe SEUL : la fenêtre porte une classe de plus sur
        # l'accueil et la fin (« installeur-libre », hauteur ajustée au
        # contenu). Chercher la chaîne exacte ne trouvait plus rien.
        marque = '<div class="modale installeur'
        if marque not in page:
            return ""
        return html.unescape(page[page.index(marque):])

    @staticmethod
    def _sous_menu(fenetre, classe):
        """Le contenu d'une des deux navigations de la fenêtre."""
        marque = f'class="{classe}"'
        if marque not in fenetre:
            return ""
        debut = fenetre.index(marque)
        return fenetre[debut:fenetre.index("</nav>", debut)]

    def test_il_s_ouvre_au_premier_lancement_et_pas_apres(self):
        accueil = self._obtenir("/")[1]
        self.assertTrue(self._ouvert(accueil))
        self.assertIn("Bienvenue dans RingBack", accueil)
        # ⚠ L'ACCUEIL N'A AUCUNE NAVIGATION (03/08/2026) : ni arbre, ni liste
        # de pages, ni la moindre croix. Elles arrivent au démarrage.
        fenetre = self._fenetre(accueil)
        self.assertTrue(fenetre, "la fenêtre de l'installeur est introuvable")
        self.assertNotIn('class="barre-installeur"', fenetre)
        self.assertNotIn('class="menu-installeur"', fenetre)
        self.assertNotIn("marque-partie", fenetre)
        self._poster("/installation/terminer", {})
        self.assertFalse(self._ouvert(self._obtenir("/")[1]))
        # Mais il reste joignable à la demande : le lien des Réglages doit
        # avoir quelque chose à rouvrir.
        self.assertTrue(self._ouvert(self._obtenir("/?installation=1")[1]))

    def test_demarrer_mene_a_la_premiere_page_et_fait_paraitre_le_menu(self):
        """« Démarrer » ouvre « Appeler », et la navigation apparaît alors.

        Demande du propriétaire du 03/08/2026 : l'accueil est nu, le clic sur
        « Démarrer » emmène sur la page des appels, et le menu se montre —
        sans « Bienvenue », sur laquelle on ne revient pas.
        """
        _, page = self._poster("/installation/valider", {"page": "bienvenue"})
        fenetre = self._fenetre(page)
        self.assertIn('class="barre-installeur"', fenetre)
        self.assertIn('class="menu-installeur"', fenetre)
        # On est bien arrivé sur la première page de « Appeler ».
        self.assertIn('data-page="identite"', fenetre)
        self.assertIn("Identité de l'établissement", fenetre)
        # « Bienvenue » a disparu du menu : le mot ne s'y trouve plus.
        self.assertNotIn("Bienvenue",
                         self._sous_menu(fenetre, "barre-installeur"))

    def test_le_bandeau_est_horizontal_et_deroule_les_campagnes(self):
        """Quatre sections dans un bandeau ; les campagnes dans un panneau.

        Le panneau se pose PAR-DESSUS le contenu au lieu de le pousser :
        c'est ce qui permet à la fenêtre de garder sa hauteur. Il part
        FERMÉ — un menu déroulant déjà ouvert n'est plus un menu déroulant.
        """
        def bandeau_de(page):
            """⚠ On NAVIGUE, on ne valide pas : « marquer » avance d'une page,
            et l'essai se serait retrouvé ailleurs qu'il ne croyait."""
            return self._sous_menu(
                self._fenetre(self._obtenir(f"/installation?page={page}")[1]),
                "barre-installeur")

        bandeau = bandeau_de("identite")
        for libelle in ("Appeler", "Agenda", "Comportement de l'agent IA",
                        "Terminer"):
            with self.subTest(libelle=libelle):
                self.assertIn(libelle, bandeau)
        # Les cinq campagnes sont dans le panneau, et il est replié.
        self.assertIn('class="panneau-deroulant" id="panneau-campagnes" hidden',
                      bandeau)
        self.assertIn('aria-expanded="false"', bandeau)
        for _, _, nom in self._natures():
            with self.subTest(nom=nom):
                self.assertIn(nom, bandeau)
        # Une seule entrée déroule : les trois autres mènent à une page.
        self.assertEqual(bandeau.count("data-menu-deroulant"), 1)

        # Sur une campagne : c'est l'entrée qui déroule qui devient active.
        bandeau = bandeau_de("confirmation-discours")
        self.assertIn('class="actif" data-menu-deroulant', bandeau)
        self.assertIn('class="actif" data-page="confirmation-comportement"',
                      bandeau)

    def test_le_menu_des_pages_suit_la_section(self):
        """À gauche du formulaire, les pages de la section où l'on est.

        Le bandeau porte les sections, ce menu porte les pages. Deux
        niveaux, deux endroits — et « Terminer », qui n'a qu'une page, n'a
        pas de menu du tout.
        """
        def menu_de(page):
            return self._sous_menu(
                self._fenetre(self._obtenir(f"/installation?page={page}")[1]),
                "menu-installeur")

        menu = menu_de("identite")
        self.assertIn("Quand appeler", menu)
        self.assertIn("Délais d'un appel réel", menu)
        self.assertNotIn("Créneau libéré", menu)     # ça, c'est le bandeau

        menu = menu_de("confirmation-discours")
        self.assertIn("Options de comportement", menu)
        self.assertIn("Discours de l'agent", menu)
        self.assertNotIn("Quand appeler", menu)      # plus la section d'à côté

        self.assertEqual(menu_de("fin"), "",
                         "une section d'une seule page n'a pas de menu")

    def test_le_panneau_deroulant_fait_naviguer(self):
        """Chaque entrée du panneau mène vraiment à sa campagne.

        Un bouton qui ne mènerait nulle part ne se verrait pas à la simple
        lecture du HTML — on fait donc l'aller-retour complet.
        """
        bandeau = self._sous_menu(
            self._fenetre(self._obtenir(
                "/installation?page=creneau_libere-discours")[1]),
            "barre-installeur")
        # ⚠ On s'arrête à la fermeture du panneau : aller jusqu'au bout du
        # bandeau attrapait aussi « Terminer », et l'essai comptait six
        # campagnes pour cinq.
        debut = bandeau.index('class="panneau-deroulant"')
        panneau = bandeau[debut:bandeau.index("</div>", debut)]
        cibles = re.findall(r'data-page="([^"]+)"', panneau)
        self.assertEqual(len(cibles), len(self._natures()))
        for cible in cibles:
            with self.subTest(cible=cible):
                _, arrivee = self._obtenir(f"/installation?page={cible}")
                fenetre = self._fenetre(arrivee)
                self.assertIn("Options de comportement", fenetre)
                # On est bien dans la section des campagnes, sur la bonne.
                self.assertIn('class="actif" data-menu-deroulant', fenetre)
                self.assertIn(f'class="actif" data-page="{cible}"', fenetre)

    def test_le_panneau_se_referme_de_trois_facons(self):
        """Ouvert, il doit pouvoir se refermer — et pas seulement de dehors.

        ⚠ Il ne se fermait QUE sur un clic hors de la fenêtre : il restait
        en travers du formulaire pendant qu'on le remplissait. Vu à la
        mesure, pas à la lecture. Les trois voies vivent dans le script :
        un clic sur l'entrée, un clic ailleurs dans la fenêtre, Échap.
        """
        script = _sans_espaces_superflus(serveur.SCRIPT_INSTALLATION)
        # Une fonction unique referme tout : trois fermetures écrites trois
        # fois se seraient désaccordées.
        self.assertIn("function fermerDeroulants()", script)
        # ① l'entrée elle-même bascule ; ② un clic ailleurs DANS la fenêtre ;
        # ③ un clic hors de la fenêtre ; ④ la touche Échap.
        self.assertIn("data-menu-deroulant", script)
        self.assertIn("closest('.entree-deroulante')", script)
        self.assertIn("!fond.contains(e.target)", script)
        self.assertIn("e.key==='Escape'", script)

    def test_le_menu_ne_porte_que_des_coches_et_des_croix(self):
        """Aucune icône décorative : ni cotillon, ni téléphone, ni calendrier.

        Elles ne disaient rien. La coche et la croix, elles, portent une
        information — et le signe se lit même sans voir la couleur.
        """
        _, page = self._poster("/installation/marquer", {"page": "identite"})
        bandeau = self._sous_menu(self._fenetre(page), "barre-installeur")
        self.assertIn("marque-partie a-faire", bandeau)
        for icone in ("🎉", "📞", "🗓", "🔔", "📆", "🚀"):
            with self.subTest(icone=icone):
                self.assertNotIn(icone, bandeau)

    def test_la_fenetre_a_une_hauteur_fixe(self):
        """Elle respirait de 349 à 774 pixels selon la page ouverte.

        Une fenêtre qui change de taille à chaque déplacement saute sous les
        yeux. Elle a maintenant une hauteur imposée, et c'est le contenu qui
        défile — les deux colonnes ont leur propre ascenseur.
        """
        corps = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE, ".modale.installeur"))
        self.assertIn("height: min(", corps)
        self.assertIn("display: flex", corps)
        self.assertIn("flex-direction: column", corps)
        # ⚠ DEUX RÉGIMES depuis le 03/08/2026 : l'accueil et la fin
        # s'ajustent à leur contenu, les pages de configuration gardent leur
        # hauteur. C'est entre celles-là qu'on navigue.
        libre = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE, ".modale.installeur.installeur-libre"))
        self.assertIn("height: auto", libre)
        self.assertIn("max-height: min(", libre)
        # Et leur titre est plus gros : il porte l'écran entier.
        titre = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE,
                            ".installeur-libre .page-installeur h2"))
        self.assertIn("font-size: 1.75rem", titre)
        # Le pied ne défile pas : il est collé au bas de la fenêtre.
        pied = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE, ".pied-installeur"))
        self.assertIn("flex: none", pied)
        # Le contenu défile, sinon la hauteur fixe couperait des pages.
        colonnes = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE, ".installeur-deux-parts > *"))
        self.assertIn("overflow-y: auto", colonnes)
        self.assertIn("min-height: 0", colonnes)
        # Et les colonnes s'étirent : sans cela, « overflow » ne sert à rien.
        grille = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE, ".installeur-deux-parts"))
        self.assertIn("align-items: stretch", grille)

    def test_le_groupe_des_campagnes_ne_verdit_qu_entierement_fait(self):
        """Une coche sur le groupe alors qu'une campagne reste à faire serait
        un mensonge : le groupe suit TOUTES ses campagnes."""
        prefs = self.application.preferences
        natures = self._natures()
        self.assertFalse(installation.noeud_fait(installation.GROUPE_AGENT,
                                                 prefs, natures))
        for code, _, _ in natures[:-1]:
            for page in (f"{code}-comportement", f"{code}-discours"):
                installation.marquer_faite(prefs, page)
        self.assertFalse(installation.noeud_fait(installation.GROUPE_AGENT,
                                                 prefs, natures),
                         "il reste une campagne : pas de coche verte")
        dernier = natures[-1][0]
        for page in (f"{dernier}-comportement", f"{dernier}-discours"):
            installation.marquer_faite(prefs, page)
        self.assertTrue(installation.noeud_fait(installation.GROUPE_AGENT,
                                                prefs, natures))

    def test_l_accueil_et_la_fin_sont_debarrasses(self):
        """Les textes et les icônes retirés le 03/08/2026 ne reviennent pas."""
        accueil = self._fenetre(self._obtenir("/")[1])
        # Les quatre points de configuration, en bleu. Les libellés sont
        # comparés SANS leurs retours à la ligne : la mise en forme du source
        # ne doit pas décider si un essai passe.
        self.assertEqual(accueil.count('class="point-config"'), 4)
        plat = _sans_espaces_superflus(accueil)
        for intitule in ("Ce que l'agent dit",
                         "Quand il a le droit d'appeler",
                         "Les places qu'il peut proposer",
                         "Ce qu'il fait quand ça n'aboutit pas"):
            with self.subTest(intitule=intitule):
                self.assertIn(intitule, plat)
        # Les deux blocs supprimés.
        self.assertNotIn("Trois choses à savoir", plat)
        self.assertNotIn("ferme cette fenêtre pour aujourd'hui", plat)

        fin = self._fenetre(
            self._poster("/installation/marquer", {"page": "fin"})[1])
        self.assertIn("Vous êtes désormais prêt", fin)
        self.assertNotIn("🎉", fin)
        self.assertNotIn("🚀", fin)
        self.assertNotIn("Votre établissement est déclaré", fin)
        # Le bouton final : plus gros et en gras.
        self.assertIn("bouton-final", fin)
        corps = _sans_espaces_superflus(
            _corps_de_regle(serveur.STYLE,
                            ".installeur-accueil .bouton-final"))
        self.assertIn("font-weight: 700", corps)
        self.assertIn("font-size", corps)

    def test_plus_tard_ne_s_ecrit_pas_sur_le_disque(self):
        """« Configurer plus tard » vaut pour la session, pas pour toujours :
        ces mots-là ne veulent pas dire « ne me le redemande jamais »."""
        self._poster("/installation/plus-tard", {})
        self.assertFalse(self._ouvert(self._obtenir("/")[1]))
        self.assertFalse(installation.terminee(self.application.preferences))
        # Un redémarrage (ici : on efface la marque de session) le ramène.
        self.application.installation_reportee = False
        self.assertTrue(self._ouvert(self._obtenir("/")[1]))

    def test_toutes_les_pages_se_rendent(self):
        for page in installation.pages(self._natures()):
            with self.subTest(page=page):
                statut, fragment = self._obtenir(f"/installation?page={page}")
                self.assertEqual(statut, 200)
                # Le préfixe : l'accueil et la fin portent en plus
                # « installeur-libre » (hauteur ajustée à leur contenu).
                self.assertIn('class="modale installeur', fragment)
                self.assertNotIn("Page inconnue", fragment)
                self.assertNotIn("<!DOCTYPE", fragment)   # un fragment

    def test_valider_ecrit_pour_de_vrai_et_passe_a_la_suite(self):
        _, page = self._poster("/installation/valider?page=identite",
                               {"entreprise": "Cabinet Val Fleuri"})
        self.assertEqual(
            self.application.preferences.obtenir(themes.CLE_ENTREPRISE),
            "Cabinet Val Fleuri")
        # On est sur la page SUIVANTE, et la page faite porte sa coche.
        self.assertIn("Quand RingBack a le droit d'appeler", page)
        self.assertIn("identite", installation.faites(
            self.application.preferences))
        self.assertIn("marque-partie faite", page)
        # Et le réglage est bien celui des ⚙ Réglages : la page le montre.
        self.assertIn("Cabinet Val Fleuri", self._obtenir("/reglages")[1])

    def test_une_saisie_refusee_reste_sur_place_et_n_ecrit_rien(self):
        _, page = self._poster("/installation/valider?page=appel",
                               {"plage_debut": "19:00", "plage_fin": "09:00"})
        self.assertIn("doit précéder", page)
        self.assertIn("Quand RingBack a le droit d'appeler", page)  # sur place
        self.assertNotIn("appel", installation.faites(
            self.application.preferences))

    def test_le_discours_refuse_un_numero_ici_comme_ailleurs(self):
        cle = assistant.cle_discours("confirmation")
        _, page = self._poster(
            "/installation/valider?page=confirmation-discours",
            {cle: "Bonjour, rappelez-nous au 06 12 34 56 78."})
        self.assertIn("numéro de téléphone a été trouvé", page)
        self.assertFalse(self.application.preferences.obtenir(cle))

    def test_charger_la_meme_configuration_ne_copie_que_le_comportement(self):
        # Une nature réglée finement…
        self._poster("/installation/valider?page=rappel_rdv-comportement",
                     {"nature": "rappel_rdv", "recontacter": "1",
                      "relance_mode": "delai", "relance_delai": "7",
                      "relance_max": "2", "ordre": "proximite"})
        self.application.preferences.definir(
            assistant.cle_discours("rappel_rdv"), "Un texte à moi.")
        # …recopiée sur une autre.
        _, page = self._poster("/installation/copier",
                               {"page": "confirmation-comportement",
                                "nature": "confirmation",
                                "source": "rappel_rdv"})
        self.assertIn("Options reprises de", page)
        regle = self.application.preferences.obtenir(
            assistant.cle_comportement("confirmation"))
        self.assertEqual(regle["relance_delai"], "7")
        self.assertEqual(regle["relance_max"], "2")
        self.assertEqual(regle["ordre"], "proximite")
        # Le DISCOURS, lui, ne suit pas : il parle d'autre chose.
        self.assertFalse(self.application.preferences.obtenir(
            assistant.cle_discours("confirmation")))
        # Sans choisir de source : on le dit, on ne copie rien au hasard.
        _, page = self._poster("/installation/copier",
                               {"page": "confirmation-comportement",
                                "nature": "confirmation", "source": ""})
        self.assertIn("Choisissez la campagne", page)

    def test_recharger_les_valeurs_par_defaut(self):
        preferences = self.application.preferences
        preferences.definir(assistant.cle_comportement("confirmation"),
                            {"recontacter": False, "relance_max": "9"})
        preferences.definir(assistant.cle_discours("confirmation"), "À moi.")
        _, page = self._poster("/installation/defauts",
                               {"page": "confirmation-comportement",
                                "nature": "confirmation",
                                "quoi": "comportement"})
        self.assertIn("valeurs d&#x27;origine", page)
        self.assertEqual(
            preferences.obtenir(assistant.cle_comportement("confirmation")), {})
        self._poster("/installation/defauts",
                     {"page": "confirmation-discours",
                      "nature": "confirmation", "quoi": "discours"})
        self.assertEqual(
            preferences.obtenir(assistant.cle_discours("confirmation")), "")

    def test_charger_un_agenda_depuis_l_installeur(self):
        contenu = ("BEGIN:VCALENDAR\r\nVERSION:2.0\r\nBEGIN:VEVENT\r\n"
                   "SUMMARY:Mme Agenda Essai - Séance\r\n"
                   "DTSTART:20261201T090000\r\nDTEND:20261201T100000\r\n"
                   "END:VEVENT\r\nEND:VCALENDAR\r\n")
        frontiere = "----frontiereInstalleur"
        corps = (f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="page"\r\n\r\nimport\r\n'
                 f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="fichier"; '
                 'filename="agenda-cabinet.ics"\r\n'
                 "Content-Type: text/calendar\r\n\r\n"
                 f"{contenu}\r\n--{frontiere}--\r\n").encode("utf-8")
        requete = urllib.request.Request(
            self.racine + "/installation/agenda", data=corps,
            headers={"Content-Type":
                     f"multipart/form-data; boundary={frontiere}"})
        with urllib.request.urlopen(requete, timeout=15) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn("Agenda chargé", page)
        # ⚠ L'AGENDA PRÉCÈDE DÉSORMAIS LES CAMPAGNES (03/08/2026) : après
        # « Charger votre agenda » on arrive sur la première campagne, plus
        # sur la page de fin.
        self.assertIn("Options de comportement", page)
        self.assertTrue(any(r["nom"] == "Mme Agenda Essai"
                            for r in self.application.base.tous_les_rendezvous()))

    def test_sans_fichier_on_le_dit_et_on_reste(self):
        frontiere = "----frontiereVide"
        corps = (f"--{frontiere}\r\n"
                 'Content-Disposition: form-data; name="page"\r\n\r\nimport\r\n'
                 f"--{frontiere}--\r\n").encode("utf-8")
        requete = urllib.request.Request(
            self.racine + "/installation/agenda", data=corps,
            headers={"Content-Type":
                     f"multipart/form-data; boundary={frontiere}"})
        with urllib.request.urlopen(requete, timeout=15) as reponse:
            page = reponse.read().decode("utf-8")
        self.assertIn("Choisissez un fichier", page)
        self.assertIn("Charger votre agenda", page)         # on n'a pas bougé

    def test_reglages_essais_installeur_remet_la_variable(self):
        """⚙ Réglages → 🧪 Essais → Installeur : le bouton réinitialise la
        variable de premier lancement, et une simple actualisation de
        l'accueil fait réapparaître l'installeur."""
        self._poster("/installation/valider?page=identite",
                     {"entreprise": "Cabinet Val Fleuri"})
        self._poster("/installation/terminer", {})
        reglages = self._obtenir("/reglages")[1]
        # La sous-partie vit sous « 🧪 Essais », pas dans une partie à elle.
        self.assertIn('data-section="installeur"', reglages)
        self.assertIn("Réinitialiser l'installeur", reglages)
        self.assertIn("est <strong>posée</strong>", reglages)
        # Le geste : la variable retombe, les pages repassent à faire…
        self._poster("/installation/rouvrir", {})
        preferences = self.application.preferences
        self.assertFalse(installation.terminee(preferences))
        self.assertEqual(installation.faites(preferences), set())
        # …mais le RÉGLAGE, lui, est intact : on refait le tour, pas les
        # valeurs. C'est ce que le bouton promet.
        self.assertEqual(preferences.obtenir(themes.CLE_ENTREPRISE),
                         "Cabinet Val Fleuri")
        # Et l'écran le dit, plutôt que de forcer l'installeur sous le nez.
        reglages = self._obtenir("/reglages?installeur=remis")[1]
        self.assertIn("Installeur réinitialisé", reglages)
        self.assertIn("Actualisez l'accueil", reglages)
        # Une actualisation de l'accueil suffit.
        self.assertTrue(self._ouvert(self._obtenir("/")[1]))

    def test_aucun_appel_ne_peut_partir_de_l_installeur(self):
        """Un écran de configuration ne compose pas de numéro. Aucune de ses
        adresses ne touche au planificateur : on le vérifie en comptant."""
        compte = {"appels": 0}
        vrai = self.application.planif.executer

        def compter(*args, **mots):
            compte["appels"] += 1
            return vrai(*args, **mots)

        self.application.planif.executer = compter
        try:
            for page in installation.pages(self._natures()):
                self._obtenir(f"/installation?page={page}")
                self._poster("/installation/marquer", {"page": page})
        finally:
            self.application.planif.executer = vrai
        self.assertEqual(compte["appels"], 0)


class TestCalendrierDansLesDeuxEcrans(_TestAvecServeurWeb):
    """Le calendrier de la semaine type se comporte PAREIL dans les ⚙ Réglages
    et dans l'installeur — c'est le même bloc, servi aux deux.

    Le défaut qui a mené ici (03/08/2026) : dans l'installeur, ouvrir ou
    fermer une période avec le formulaire de repli renvoyait la PAGE des
    réglages, qui venait remplacer la fenêtre. Trois causes, toutes
    corrigées : l'écoute de l'installeur prenait tous les formulaires ;
    les routes ne savaient pas répondre un fragment ; et le geste à la
    souris n'était relié qu'au calendrier présent au chargement.
    """

    def _bloc(self, page, identifiant):
        """Le contenu d'un élément identifié, dans une page servie."""
        marque = f'id="{identifiant}"'
        self.assertIn(marque, page, f"élément « {identifiant} » absent")
        debut = page.index(marque)
        return page[debut:debut + 40000]

    def test_les_deux_ecrans_servent_le_meme_bloc(self):
        reglages = self._obtenir("/reglages")[1]
        installeur = self._obtenir("/installation?page=horaires")[1]
        for page, ou in ((reglages, "réglages"), (installeur, "installeur")):
            with self.subTest(ou=ou):
                # La zone se nomme elle-même : c'est ce qui relie le geste
                # à la souris, où que le calendrier ait été inséré.
                self.assertIn('data-calendrier="calendrier"', page)
                self.assertIn('id="bloc-horaires"', page)
                # Le formulaire de période dit quel élément recharger.
                self.assertIn('action="/reglages/semaine" class="carte"\n'
                              '      data-fragment-cible="calendrier"', page)
                self.assertIn('class="calendrier"', page)
                # Et il est en TABLEAU depuis le 03/08/2026 : quatre colonnes,
                # les deux boutons dans la dernière.
                self.assertIn('class="tableau-saisie"', page)
                for entete in ("Jour", "Début", "Fin", "Période"):
                    self.assertIn(f'<th scope="col">{entete}</th>', page)
                self.assertIn('<button name="geste" value="ouvrir">Ouvrir'
                              "</button>", page)
        # ⚠ UNE SEULE DIFFÉRENCE, ET ELLE EST VOULUE : la durée moyenne d'un
        # rendez-vous ne s'affiche que dans les ⚙ Réglages. Le propriétaire a
        # fait retirer son bouton de l'installeur le 03/08/2026, et un champ
        # sans bouton ne peut plus s'enregistrer — c'est la carte entière qui
        # part, là-bas seulement.
        self.assertIn('data-fragment-cible="bloc-horaires"', reglages)
        self.assertIn("Enregistrer la durée", reglages)
        self.assertNotIn("Enregistrer la durée", installeur)
        self.assertNotIn("Durée moyenne d'un rendez-vous", installeur)

    def test_le_formulaire_de_repli_rend_un_fragment(self):
        """C'est LE défaut : sans fragment, la réponse était une page entière
        et la fenêtre de l'installeur s'en trouvait remplacée."""
        _, fragment = self._poster("/reglages/semaine", {
            "jour": "1", "debut": "09:00", "fin": "12:00",
            "geste": "ouvrir", "fragment": "1"})
        self.assertNotIn("<!DOCTYPE", fragment)
        self.assertNotIn("<nav class=\"onglets\">", fragment)
        self.assertIn('class="calendrier"', fragment)
        self.assertIn("tranche ouverte", fragment)
        # Refermer la même période : réversible, et toujours un fragment.
        _, fragment = self._poster("/reglages/semaine", {
            "jour": "1", "debut": "09:00", "fin": "12:00",
            "geste": "fermer", "fragment": "1"})
        self.assertNotIn("<!DOCTYPE", fragment)
        semaine = horaires.semaine(self.application.preferences)
        self.assertEqual(semaine[1], [])
        # Sans « fragment », le repli sans JavaScript garde son comportement :
        # on revient sur la page des réglages.
        statut, page = self._poster("/reglages/semaine", {
            "jour": "1", "debut": "09:00", "fin": "12:00", "geste": "ouvrir"})
        self.assertEqual(statut, 200)
        self.assertIn("<!DOCTYPE", page)

    def test_le_pas_rend_un_fragment_et_son_refus_reste_dedans(self):
        _, fragment = self._poster("/reglages/pas", {"pas": "60",
                                                     "fragment": "1"})
        self.assertNotIn("<!DOCTYPE", fragment)
        self.assertIn('class="calendrier"', fragment)
        self.assertEqual(horaires.pas_minutes(self.application.preferences), 60)
        # Un refus s'affiche DANS le bloc, là où le geste a eu lieu.
        _, fragment = self._poster("/reglages/pas", {"pas": "3",
                                                     "fragment": "1"})
        self.assertNotIn("<!DOCTYPE", fragment)
        self.assertIn("Refusé", fragment)
        self.assertIn("hors des bornes", fragment)
        # Et rien n'a été écrit : le réglage précédent tient.
        self.assertEqual(horaires.pas_minutes(self.application.preferences), 60)

    def test_les_jours_fermes_se_rechargent_seuls(self):
        _, fragment = self._poster("/reglages/jour-ferme", {
            "date": "2026-12-24", "libelle": "Réveillon", "fragment": "1"})
        self.assertNotIn("<!DOCTYPE", fragment)
        self.assertIn("24/12/2026", fragment)
        self.assertIn("Réveillon", fragment)
        _, fragment = self._poster("/reglages/jour-ferme", {
            "action": "retirer", "date": "2026-12-24", "fragment": "1"})
        self.assertNotIn("<!DOCTYPE", fragment)
        self.assertNotIn("Réveillon", fragment)
        # Une date illisible : le refus reste dans le bloc, rien n'est ajouté.
        _, fragment = self._poster("/reglages/jour-ferme", {
            "date": "pas-une-date", "fragment": "1"})
        self.assertIn("Refusé", fragment)
        self.assertEqual(horaires.jours_fermes(self.application.preferences), [])

    def test_l_installeur_ne_prend_que_ses_propres_formulaires(self):
        """Le garde-fou, lu dans le script : sans lui, l'écoute de la fenêtre
        avalait les formulaires des réglages et affichait leur réponse à la
        place de la page d'installation."""
        script = serveur.SCRIPT_INSTALLATION
        self.assertIn("action.indexOf('/installation/')!==0", script)
        # Et la machinerie partagée est servie sur TOUTES les pages : c'est
        # elle qui prend les autres formulaires, y compris ceux arrivés plus
        # tard par innerHTML (le calendrier de l'installeur).
        for chemin in ("/", "/reglages", "/suivi"):
            with self.subTest(chemin=chemin):
                self.assertIn("data-fragment-cible",
                              self._obtenir(chemin)[1])

    def test_la_periode_interdite_donne_le_bon_exemple(self):
        """Demande du propriétaire : 12:00 → 14:00 (la pause de midi), et
        plus un mot sur minuit — qui laissait croire à autre chose."""
        for page in (self._obtenir("/reglages")[1],
                     self._obtenir("/installation?page=appel")[1]):
            self.assertIn("ex. 12:00", page)
            self.assertIn("ex. 14:00", page)
            self.assertNotIn("traverser minuit", page)
            # Et les champs restent VIDES par défaut : aucune période
            # interdite n'est imposée à personne.
            self.assertIn('name="interdit_debut"\n           value=""', page)
            self.assertIn('name="interdit_fin"\n           value=""', page)


class TestServeurJeuEssai(_TestAvecServeurWeb):
    """Le jeu d'essai à l'écran : geste explicite, annoncé, retirable."""

    def test_charger_annonce_puis_retirer_en_requetes_reelles(self):
        base = self.application.base
        propres = base.compter_clients()          # les 4 clients de démo
        # Rien n'est chargé tant qu'on n'a rien demandé.
        statut, page = self._obtenir("/reglages")
        self.assertEqual(statut, 200)
        self.assertIn("Charger un jeu d'essai…", page)
        self.assertNotIn("JEU D'ESSAI CHARGÉ", page)
        # Le bouton mène à une page de CONFIRMATION qui annonce le contenu.
        _, page = self._obtenir("/reglages/jeu-essai?action=charger")
        self.assertIn("Charger un jeu d'essai ?", page)
        self.assertIn(f"<strong>{len(jeu_essai.CLIENTS)} contacts</strong>",
                      page)
        self.assertIn("Arcep", page)              # d'où viennent les numéros
        # Sans confirmation, rien ne se charge.
        self.assertEqual(base.compter_clients_jeu_essai(), 0)
        _, page = self._poster("/reglages/jeu-essai",
                               {"action": "charger", "confirmer": "oui"})
        self.assertIn("Jeu d'essai chargé", page)
        self.assertEqual(base.compter_clients_jeu_essai(),
                         len(jeu_essai.CLIENTS))
        # ⚠ LE BANDEAU DE TOUTES LES PAGES EST PARTI (21/08/2026, sa
        # demande). Ce qui reste — et qui suffit — c'est le marquage 🧪 fiche
        # par fiche, éprouvé juste en dessous.
        _, accueil = self._obtenir("/suivi")
        self.assertNotIn("JEU D'ESSAI CHARGÉ", accueil)
        # ⚠ « par_page=0 » = TOUS : la page est paginée depuis le 10/08/2026
        # (25 par défaut) et le jeu d'essai compte 36 contacts. Compter les 🧪
        # sur la première page seule en trouvait 23.
        _, clients = self._obtenir("/clients?par_page=0")
        self.assertEqual(clients.count("🧪 jeu d'essai"),
                         len(jeu_essai.CLIENTS))
        self.assertNotIn("06 39 98 00 51", clients)   # numéros toujours masqués
        self.assertIn("06 39 •• •• 51", clients)
        # Retrait : seules les fiches 🧪 partent, les données propres restent.
        _, page = self._poster("/reglages/jeu-essai",
                               {"action": "retirer", "confirmer": "oui"})
        self.assertIn("Jeu d'essai retiré", page)
        self.assertEqual(base.compter_clients(), propres)


class TestServeurRepriseCampagne(_TestAvecServeurWeb):
    """Étape ③ : une campagne bâtie sur les résultats d'une campagne passée."""

    def test_filtre_deroulant_puis_seconde_campagne(self):
        base = self.application.base
        campagne_id = base.creer_campagne("Rappel d'essai", "rappel_rdv",
                                          nature="rappel_rdv")
        for rang, (nom, tel, etat) in enumerate(
                (("Mme Injoignable Une", "+33 6 00 00 00 53", "injoignable"),
                 ("M. Injoignable Deux", "+33 6 00 00 00 56", "injoignable"),
                 ("Mme Acceptée Trois", "+33 6 00 00 00 51", "accepté")),
                start=1):
            base.ajouter_contact_campagne(campagne_id, rang, nom, tel,
                                          etat=etat)
        _, page = self._poster("/assistant/nature", {"nature": "rappel_rdv"})
        b = self._brouillon(page)
        _, page = self._poster("/assistant/message", {
            "b": b, "action": "continuer", "info_entreprise": "Cabinet Essai",
            "ordre": "liste", "relance_mode": "delai", "relance_delai": "4",
            "relance_max": "0"})
        # Un FILTRE, donc deux listes déroulantes (pas des boutons radio),
        # et le nombre trouvé est lisible AVANT d'ajouter quoi que ce soit.
        self.assertIn('<select class="select-option" name="campagne"', page)
        self.assertIn('<select class="select-option" name="etat"', page)
        self.assertIn("📵 Injoignables", page)
        self.assertIn("personne(s) trouvée(s) avec ce filtre", page)
        self.assertIn('"injoignable": 2', page)   # comptes réels, lus en base
        # Reprise des seuls injoignables.
        _, page = self._poster("/assistant/importer", {
            "b": b, "mode": "campagne", "campagne": campagne_id,
            "etat": "injoignable"})
        self.assertIn("2 contact(s) ajouté(s)", page)
        self.assertIn("Mme Injoignable Une", page)
        self.assertNotIn("Mme Acceptée Trois", page)
        self.assertNotIn("+33 6 00 00 00 53", page)   # toujours masqué
        # Un état vide le dit, au lieu de faire semblant.
        _, page = self._poster("/assistant/importer", {
            "b": b, "mode": "campagne", "campagne": campagne_id,
            "etat": "à rappeler par un humain"})
        self.assertIn("Aucun contact de cette campagne n&#x27;est dans cet "
                      "état", page)
        # Le filtre choisi se réaffiche DANS ses champs (rien à re-choisir).
        self.assertIn('<option value="à rappeler par un humain" selected>', page)
        self.assertIn("0 personne(s) trouvée(s) avec ce filtre", page)
        # La seconde campagne se crée bel et bien depuis la première.
        self._poster("/assistant/liste", {
            "b": b, "action": "enregistrer",
            "c_rdv_existant_1": DEMAIN, "c_motif_1": "Séance",
            "c_rdv_existant_2": DEMAIN, "c_motif_2": "Séance"})
        _, page = self._poster("/assistant/liste", {"b": b, "action": "valider"})
        self.assertIn("prête", page)
        self.assertEqual(len(base.lister_campagnes()), 2)
        nouvelle = base.lister_campagnes()[0]
        self.assertEqual(nouvelle["contacts"], 2)


class TestHorairesOuverture(unittest.TestCase):
    """Semaine type, jours fermés, tranches consécutives et créneaux calculés.

    Un lundi de référence est choisi loin dans le futur (le 2026-09-07, un
    lundi) pour que les tests ne dépendent jamais du jour où on les joue.
    """

    LUNDI = datetime.date(2026, 9, 7)

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.preferences = generation.Preferences(None)
        self.client_id = self.base.ajouter_client("Mme Horaire Exemple",
                                                  "+33 6 00 00 00 61")
        # Semaine type : lundi 9h → 12h, avec un pas de 15 minutes.
        self.preferences.definir(horaires.CLE_PAS, 15)
        horaires.basculer_periode(self.preferences, 0, 9 * 60, 12 * 60,
                                  "ouvrir")

    def _matin(self, heure, minute=0, jours=0):
        return (datetime.datetime.combine(self.LUNDI, datetime.time())
                + datetime.timedelta(days=jours, hours=heure, minutes=minute))

    def test_glisser_relache_ouvre_puis_referme_la_meme_periode(self):
        """Le geste est une BASCULE : refait sur une période ouverte, il ferme."""
        semaine = horaires.semaine(self.preferences)
        self.assertEqual(semaine[0], [(540, 720)])       # lundi 9h→12h
        self.assertEqual(semaine[1], [])                 # mardi intact
        # Même geste sur une demi-heure DÉJÀ ouverte : elle se referme.
        ouverte = horaires.basculer_periode(self.preferences, 0, 600, 630,
                                            "basculer")
        self.assertFalse(ouverte)
        self.assertEqual(horaires.semaine(self.preferences)[0],
                         [(540, 600), (630, 720)])
        # Et le même geste rouvre le trou (aucune donnée perdue au passage).
        self.assertTrue(horaires.basculer_periode(self.preferences, 0, 600,
                                                  630, "basculer"))
        self.assertEqual(horaires.semaine(self.preferences)[0], [(540, 720)])

    def test_periode_vide_ou_jour_inconnu_refuses_avec_le_format_attendu(self):
        with self.assertRaises(ValueError) as refus:
            horaires.basculer_periode(self.preferences, 9, 540, 600, "ouvrir")
        self.assertIn("0 = lundi", str(refus.exception))
        with self.assertRaises(ValueError):
            horaires.minutes_depuis_hhmm("9h00")   # format non attendu

    def test_creneaux_libres_retire_ce_qui_est_deja_pris(self):
        """Ouvert − occupé : un rendez-vous mange EXACTEMENT ses tranches."""
        self.base.ajouter_rendezvous(self.client_id,
                                     self._matin(9, 30).isoformat(timespec="minutes"),
                                     "Séance", duree_tranches=2)
        libres = horaires.creneaux_libres(self.base, self.preferences,
                                          depuis=self._matin(0), jours=0)
        heures = [creneau[11:] for creneau in libres]
        self.assertIn("09:00", heures)
        self.assertIn("09:15", heures)
        self.assertNotIn("09:30", heures)   # pris (tranche 1 sur 2)
        self.assertNotIn("09:45", heures)   # pris (tranche 2 sur 2)
        self.assertIn("10:00", heures)
        self.assertEqual(len(libres), 10)   # 12 tranches − 2 occupées

    def test_annuler_un_rendezvous_de_deux_tranches_en_libere_deux(self):
        rdv_id = self.base.ajouter_rendezvous(
            self.client_id, self._matin(10).isoformat(timespec="minutes"),
            "Séance de 30 minutes", duree_tranches=2)
        avant = horaires.creneaux_libres(self.base, self.preferences,
                                         depuis=self._matin(0), jours=0)
        self.base.mettre_a_jour_rendezvous(rdv_id, statut="annulé")
        apres = horaires.creneaux_libres(self.base, self.preferences,
                                         depuis=self._matin(0), jours=0)
        self.assertEqual(len(apres) - len(avant), 2)
        rendues = sorted(set(apres) - set(avant))
        self.assertEqual([c[11:] for c in rendues], ["10:00", "10:15"])

    def test_creneaux_d_une_demi_heure_exigent_deux_tranches_consecutives(self):
        """Un client de 30 min ne se voit proposer que des SUITES de 2."""
        # Il ne reste qu'un trou d'une seule tranche entre 10h15 et 10h30.
        self.base.ajouter_rendezvous(self.client_id,
                                     self._matin(9).isoformat(timespec="minutes"),
                                     "Séance", duree_tranches=5)   # 9h→10h15
        self.base.ajouter_rendezvous(self.client_id,
                                     self._matin(10, 30).isoformat(timespec="minutes"),
                                     "Séance", duree_tranches=6)   # 10h30→12h
        seules = horaires.creneaux_libres(self.base, self.preferences,
                                          tranches=1, depuis=self._matin(0),
                                          jours=0)
        self.assertEqual([c[11:] for c in seules], ["10:15"])
        doubles = horaires.creneaux_libres(self.base, self.preferences,
                                           tranches=2, depuis=self._matin(0),
                                           jours=0)
        self.assertEqual(doubles, [])   # aucune suite de 2 : rien n'est proposé

    def test_jour_ferme_supprime_toutes_ses_tranches(self):
        libres = horaires.creneaux_libres(self.base, self.preferences,
                                          depuis=self._matin(0), jours=0)
        self.assertEqual(len(libres), 12)
        horaires.ajouter_jour_ferme(self.preferences, self.LUNDI.isoformat(),
                                    "vacances d'été")
        self.assertEqual(horaires.est_ferme(self.preferences, self.LUNDI),
                         "vacances d'été")
        self.assertEqual(horaires.creneaux_libres(self.base, self.preferences,
                                                  depuis=self._matin(0),
                                                  jours=0), [])
        # Retrait : la journée redevient proposable (rien n'est perdu).
        self.assertTrue(horaires.retirer_jour_ferme(self.preferences,
                                                    self.LUNDI.isoformat()))
        self.assertEqual(len(horaires.creneaux_libres(
            self.base, self.preferences, depuis=self._matin(0), jours=0)), 12)

    def test_refus_de_deplacer_un_client_trop_long_dit_ce_qui_manque(self):
        """La règle du propriétaire, à la lettre — et le refus est explicite."""
        # 9h→11h45 occupé : il ne reste qu'UNE tranche libre, 11h45.
        self.base.ajouter_rendezvous(self.client_id,
                                     self._matin(9).isoformat(timespec="minutes"),
                                     "Long", duree_tranches=11)
        rdv_id = self.base.ajouter_rendezvous(
            self.client_id, self._matin(15).isoformat(timespec="minutes"),
            "Demi-heure", duree_tranches=2)
        rdv = self.base.obtenir_rendezvous(rdv_id)
        cible = self._matin(11, 45).isoformat(timespec="minutes")
        refus = horaires.refus_deplacement(self.base, self.preferences, rdv,
                                           cible)
        self.assertIsNotNone(refus)
        self.assertIn("2 tranches de 15 min (30 minutes)", refus)
        self.assertIn("1 tranche de 15 min", refus)
        self.assertIn("il en manque 1", refus)
        # Une place assez longue, elle, est acceptée (aucun refus).
        horaires.basculer_periode(self.preferences, 0, 14 * 60, 15 * 60,
                                  "ouvrir")
        self.assertIsNone(horaires.refus_deplacement(
            self.base, self.preferences, rdv, self._matin(14).isoformat(
                timespec="minutes")))

    def test_refus_de_deplacer_vers_un_jour_ferme(self):
        rdv_id = self.base.ajouter_rendezvous(
            self.client_id, self._matin(9).isoformat(timespec="minutes"),
            "Séance")
        horaires.ajouter_jour_ferme(self.preferences, self.LUNDI.isoformat(),
                                    "Assomption")
        refus = horaires.refus_deplacement(
            self.base, self.preferences, self.base.obtenir_rendezvous(rdv_id),
            self._matin(9, 30).isoformat(timespec="minutes"))
        self.assertIn("déclaré FERMÉ", refus)
        self.assertIn("Assomption", refus)

    def test_creneaux_ajoutes_a_la_main_completent_le_calcul(self):
        """Le cas particulier tapé à la main s'AJOUTE, il ne remplace rien."""
        exception = self._matin(9, 0, jours=5).isoformat(timespec="minutes")
        self.preferences.definir(themes.CLE_CRENEAUX, [exception])
        proposes = horaires.creneaux_proposables(self.base, self.preferences,
                                                 depuis=self._matin(0),
                                                 jours=0)
        origines = {entree["horaire"]: entree["origine"] for entree in proposes}
        self.assertEqual(origines.get(exception), "à la main")
        self.assertEqual(
            origines.get(self._matin(9).isoformat(timespec="minutes")),
            "calculé")

    def test_jours_feries_francais_calcules_paques_comprise(self):
        """Pâques par le calcul (aucune bibliothèque extérieure)."""
        self.assertEqual(horaires.paques(2026), datetime.date(2026, 4, 5))
        self.assertEqual(horaires.paques(2027), datetime.date(2027, 3, 28))
        feries2026 = dict(horaires.feries(2026))
        self.assertEqual(feries2026[datetime.date(2026, 4, 6)],
                         "Lundi de Pâques")
        self.assertEqual(feries2026[datetime.date(2026, 5, 14)], "Ascension")
        self.assertEqual(feries2026[datetime.date(2026, 5, 25)],
                         "Lundi de Pentecôte")
        self.assertEqual(len(feries2026), 11)
        # PROPOSÉS, jamais ajoutés : la liste des jours fermés reste vide.
        proposition = horaires.feries_a_proposer(
            self.preferences, depuis=datetime.date(2026, 7, 29))
        self.assertTrue(proposition)
        self.assertEqual(horaires.jours_fermes(self.preferences), [])


class TestMigrationDureeRendezvous(unittest.TestCase):
    """Migration ADDITIVE : un rendez-vous d'avant la durée vaut UNE tranche."""

    def test_ancienne_base_sans_duree_vaut_une_tranche(self):
        dossier = tempfile.mkdtemp(prefix="ringback-duree-")
        self.addCleanup(shutil.rmtree, dossier, ignore_errors=True)
        chemin = os.path.join(dossier, "ringback.db")
        import sqlite3
        brute = sqlite3.connect(chemin)
        brute.executescript("""
            CREATE TABLE clients (id INTEGER PRIMARY KEY AUTOINCREMENT,
                                  nom TEXT NOT NULL, telephone TEXT NOT NULL);
            CREATE TABLE rendezvous (id INTEGER PRIMARY KEY AUTOINCREMENT,
                                     client_id INTEGER NOT NULL,
                                     horaire TEXT NOT NULL, motif TEXT NOT NULL,
                                     statut TEXT NOT NULL DEFAULT 'prévu');
            INSERT INTO clients (nom, telephone)
                VALUES ('Mme Avant Durée', '+33 6 00 00 00 62');
            INSERT INTO rendezvous (client_id, horaire, motif, statut)
                VALUES (1, '2026-09-07T09:00', 'Séance ancienne', 'prévu');
        """)
        brute.commit()
        brute.close()
        base = db.Base(chemin)            # la migration additive se joue ici
        self.addCleanup(base.fermer)
        rdv = base.rendezvous_a_venir()[0]
        self.assertEqual(rdv["motif"], "Séance ancienne")   # donnée intacte
        self.assertEqual(rdv["duree_tranches"], 1)          # une tranche
        occupants = base.rendezvous_occupants("2026-09-07T00:00",
                                              "2026-09-08T00:00")
        self.assertEqual([o["duree_tranches"] for o in occupants], [1])


class TestServeurHoraires(_TestAvecServeurWeb):
    """Les horaires vus de l'écran : calendrier, repli sans JavaScript,
    jours fermés, créneaux calculés, refus de déplacement."""

    LUNDI = datetime.date(2026, 9, 7)

    def test_calendrier_et_repli_sans_javascript(self):
        _, page = self._obtenir("/reglages")
        self.assertIn("Horaires d'ouverture", page)
        self.assertIn('data-jour="0" data-min="540"', page)   # lundi 9h00
        # Le repli est TOUJOURS visible (pas seulement sans JavaScript).
        self.assertIn("Sans glisser-relâché", page)
        self.assertIn('name="geste" value="ouvrir"', page)
        # Repli : ouvrir mardi 9h→12h par le formulaire.
        self._poster("/reglages/semaine", {"jour": 1, "debut": "09:00",
                                           "fin": "12:00", "geste": "ouvrir"})
        semaine = horaires.semaine(self.application.preferences)
        self.assertEqual(semaine[1], [(540, 720)])
        # Le glisser-relâché : même route, réponse en FRAGMENT (la page
        # entière n'est jamais rechargée).
        _, fragment = self._poster("/reglages/semaine",
                                   {"jour": 1, "debut_min": 600,
                                    "fin_min": 630, "geste": "basculer",
                                    "fragment": 1})
        self.assertNotIn("<!DOCTYPE", fragment)
        self.assertIn('title="mardi 10h00 — fermé"', fragment)
        self.assertEqual(horaires.semaine(self.application.preferences)[1],
                         [(540, 600), (630, 720)])

    def test_pas_refuse_dit_le_format_attendu_et_ne_change_rien(self):
        _, page = self._poster("/reglages/pas", {"pas": "un quart d'heure"})
        self.assertIn("Réglage refusé", page)
        self.assertIn("nombre entier de minutes", page)
        self.assertEqual(horaires.pas_minutes(self.application.preferences), 15)
        self._poster("/reglages/pas", {"pas": "30"})
        self.assertEqual(horaires.pas_minutes(self.application.preferences), 30)

    def test_jour_ferme_declare_puis_retire_depuis_l_ecran(self):
        self._poster("/reglages/jour-ferme", {"date": "15/08/2026",
                                              "libelle": "Assomption"})
        _, page = self._obtenir("/reglages")
        self.assertIn("samedi 15/08/2026", page)
        self.assertIn("Assomption", page)
        self._poster("/reglages/jour-ferme", {"action": "retirer",
                                              "date": "2026-08-15"})
        self.assertEqual(horaires.jours_fermes(self.application.preferences), [])
        # Les fériés sont PROPOSÉS, jamais ajoutés d'office.
        _, page = self._obtenir("/reglages")
        self.assertIn("Ajouter aux jours fermés", page)
        self.assertIn("ne les ajoute jamais tout seul", page)

    def test_un_creneau_passe_dit_son_etat_en_mots(self):
        """La couleur ne porte jamais seule — c'est ce qui permet de l'unifier.

        Les trois calendriers montrent depuis le 03/08/2026 le MÊME vert, sans
        atténuation. Retirer celle des créneaux passés n'ôte aucune
        information — mais seulement parce que l'état est écrit ailleurs. Cet
        essai est la contrepartie de l'unification : si l'infobulle ou le
        texte de lecture d'écran disparaissaient, la couleur porterait seule.

        Deux semaines entières, l'une derrière nous et l'autre devant : aucune
        dépendance à l'heure qu'il est quand l'essai tourne.
        """
        # Cette classe part SANS horaires d'ouverture : sans en ouvrir, il n'y
        # aurait aucune case libre et l'essai passerait à vide.
        for jour in range(5):
            horaires.basculer_periode(self.application.preferences,
                                      jour, 9 * 60, 12 * 60, "ouvrir")
        passee = datetime.date.today() - datetime.timedelta(days=28)
        future = datetime.date.today() + datetime.timedelta(days=28)

        _, page = self._obtenir(f"/suivi?date={passee:%d/%m/%Y}")
        cases = re.findall(r'<td class="libre revolue"[^>]*>.*?</td>', page)
        self.assertTrue(cases, "aucune case passée : l'essai ne prouve rien")
        for case in cases:
            with self.subTest(case=case[:90]):
                # L'état, en mots, DEUX fois : à la souris et à la voix.
                self.assertIn("libre, déjà passé", case)
                self.assertIn('<span class="lecture-seule">libre, déjà passé',
                              case)
                # Et aucun clic : pas de data-modale, donc pas de liseré.
                self.assertNotIn("data-modale", case)

        _, page = self._obtenir(f"/suivi?date={future:%d/%m/%Y}")
        cases = re.findall(r'<td class="libre"[^>]*>.*?</td>', page)
        self.assertTrue(cases, "aucune case ouvrable : l'essai ne prouve rien")
        for case in cases:
            with self.subTest(case=case[:90]):
                self.assertIn("data-modale", case)
                self.assertNotIn("déjà passé", case)

    def test_creneaux_calcules_puis_refus_de_deplacement_a_l_ecran(self):
        base, preferences = self.application.base, self.application.preferences
        horaires.basculer_periode(preferences, 0, 9 * 60, 10 * 60, "ouvrir")
        lundi = datetime.datetime.combine(self.LUNDI, datetime.time(9, 0))
        client_id = base.ajouter_client("Mme Créneau Exemple",
                                        "+33 6 00 00 00 63")
        # 9h00 → 9h45 occupé : il ne reste que 9h45 (une seule tranche).
        base.ajouter_rendezvous(client_id, lundi.isoformat(timespec="minutes"),
                                "Long", duree_tranches=3)
        rdv_id = base.ajouter_rendezvous(
            client_id, (lundi + datetime.timedelta(days=7)).isoformat(
                timespec="minutes"), "Demi-heure", duree_tranches=2)
        _, fragment = self._obtenir("/reglages/creneaux")
        self.assertNotIn("<!DOCTYPE", fragment)
        self.assertIn("calculé", fragment)
        # Déplacement refusé, avec ce qui manque, sans perdre la fiche.
        _, page = self._poster("/rendezvous/deplacer", {
            "rdv": rdv_id,
            "cible": (lundi + datetime.timedelta(minutes=45)).isoformat(
                timespec="minutes")})
        self.assertIn("Action refusée", page)
        self.assertIn("il en manque 1", page)
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["horaire"],
                         (lundi + datetime.timedelta(days=7)).isoformat(
                             timespec="minutes"))   # rien n'a bougé

    def test_duree_et_annulation_depuis_la_fiche(self):
        base = self.application.base
        client_id = base.ajouter_client("M. Durée Exemple", "+33 6 00 00 00 64")
        # Une date VOLONTAIREMENT LOINTAINE, et non DEMAIN : la règle
        # d'annulation dépend du seuil de remplacement (12 h par défaut), or
        # « demain 10 h » passe SOUS ce seuil dès que l'essai tourne après
        # 22 h — l'essai échouait alors pour l'heure qu'il était, pas pour ce
        # qu'il vérifie. Le cas « à moins de 12 h » a ses essais dédiés
        # (horaires.decision_annulation).
        loin = (datetime.datetime.now() + datetime.timedelta(days=3)).replace(
            hour=10, minute=0, second=0, microsecond=0).isoformat(
                timespec="minutes")
        rdv_id = base.ajouter_rendezvous(client_id, loin, "Séance")
        _, page = self._poster("/rendezvous/duree", {"rdv": rdv_id,
                                                     "duree": "22"})
        self.assertIn("Durée refusée", page)
        self.assertIn("multiple de 15", page)
        self.assertIn('value="22"', page)   # la saisie refusée revient
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["duree_tranches"], 1)
        self._poster("/rendezvous/duree", {"rdv": rdv_id, "duree": "30"})
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["duree_tranches"], 2)
        _, page = self._obtenir(f"/rendezvous?id={rdv_id}")
        self.assertIn("2 tranches de 15 min (30 minutes)", page)
        # Le geste « Annuler » sur un rendez-vous À VENIR le SUPPRIME (règle
        # du propriétaire) : il n'existe plus et sa place redevient libre.
        # « annulé » ne s'applique qu'aux dates passées — l'essai juste
        # après le vérifie.
        self._poster("/rendezvous/annuler", {"rdv": rdv_id})
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"],
                         db.STATUT_SUPPRIME)

    def test_annuler_un_rendezvous_passe_le_laisse_annule(self):
        """Le statut d'HISTOIRE : derrière nous, « annulé » reste « annulé »."""
        base = self.application.base
        client_id = base.ajouter_client("Mme Passée Fiche", "+33 6 00 00 00 65")
        rdv_id = base.ajouter_rendezvous(client_id, HIER, "Séance")
        self._poster("/rendezvous/annuler", {"rdv": rdv_id})
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"], "annulé")


class TestCampagneCreneauxCalcules(unittest.TestCase):
    """Les campagnes proposent les créneaux RÉELLEMENT libres, et de la
    bonne durée pour le client concerné."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.preferences = generation.Preferences(None)
        horaires.basculer_periode(self.preferences, 0, 9 * 60, 10 * 60,
                                  "ouvrir")
        # Le PROCHAIN lundi (jamais aujourd'hui) : la mission d'appel calcule
        # ses créneaux « à partir de maintenant », le test doit donc vivre
        # dans le futur, quel que soit le jour où on le joue.
        aujourdhui = datetime.date.today()
        self.lundi = aujourdhui + datetime.timedelta(
            days=(7 - aujourdhui.weekday()) % 7 or 7)
        self.depuis = datetime.datetime.combine(self.lundi, datetime.time())
        self.jour = f"{self.lundi:%d/%m/%Y}"
        self.client_id = self.base.ajouter_client("Mme Longue Séance",
                                                  "+33 6 00 00 00 65")

    def test_mission_adaptee_a_la_duree_du_contact(self):
        # 9h15 pris : restent 9h00 seul, puis 9h30-9h45 (une suite de 2).
        self.base.ajouter_rendezvous(
            self.client_id,
            (self.depuis + datetime.timedelta(hours=9, minutes=15)).isoformat(
                timespec="minutes"), "Séance")
        rdv_id = self.base.ajouter_rendezvous(
            self.client_id,
            (self.depuis + datetime.timedelta(days=14, hours=9)).isoformat(
                timespec="minutes"), "Demi-heure", duree_tranches=2)
        courts = horaires.creneaux_lisibles(self.base, self.preferences,
                                            tranches=1, depuis=self.depuis)
        longs = horaires.creneaux_lisibles(self.base, self.preferences,
                                           tranches=2, depuis=self.depuis)
        # ⚠ ON COMPARE DES ÉLÉMENTS, PAS DES SOUS-CHAÎNES. « le lundi 31 août
        # 2026 à 9 heures » est un PRÉFIXE de « … à 9 heures 30 » : un
        # `assertNotIn` sur le texte entier serait faux dès que la demie est
        # dans la liste. C'est le même piège que celui qui abîmait le recalcul
        # de l'instant de l'appel — ici il rend un essai MENTEUR au lieu d'un
        # texte abîmé.
        neuf = date_parlee_de(f"{self.lundi:%Y-%m-%d}T09:00")
        neuf_trente = date_parlee_de(f"{self.lundi:%Y-%m-%d}T09:30")
        self.assertIn(neuf, courts.split(", "))     # une tranche suffit
        self.assertNotIn(neuf, longs.split(", "))   # 30 min : trop court
        self.assertIn(neuf_trente, longs.split(", "))
        # La campagne : liste CALCULÉE (donc repérée « auto »), contact dont
        # le rendez-vous dure 30 minutes → la mission est réadaptée.
        campagne_id = self.base.creer_campagne(
            "Essai", theme="deplacement", nature="deplacement",
            mission=f"Je peux vous proposer : {courts}.",
            configuration=json.dumps({"infos": {"creneaux_remplacement": courts},
                                      "infos_auto": {"creneaux_remplacement":
                                                     courts}},
                                     ensure_ascii=False))
        contact_id = self.base.ajouter_contact_campagne(
            campagne_id, 1, "Mme Longue Séance", "+33 6 00 00 00 65",
            rendezvous_id=rdv_id)
        contact = self.base.obtenir_contact_campagne(contact_id)
        configuration = assistant.configuration_campagne(
            self.base.obtenir_campagne(campagne_id))
        adaptee = assistant.creneaux_adaptes_au_contact(
            self.base, self.preferences, configuration, contact,
            f"Je peux vous proposer : {courts}.")
        # ⚠ PAR ÉLÉMENTS, pas par sous-chaînes : « à 9 heures » est un
        # PRÉFIXE de « à 9 heures 30 ».
        proposees = adaptee.split(" : ")[1].rstrip(".").split(", ")
        self.assertIn(neuf_trente, proposees)
        # Le trou d'une seule tranche de ce lundi disparaît de la proposition.
        self.assertNotIn(neuf, proposees)
        # Liste RETAPÉE à la main (pas « auto ») : jamais touchée.
        configuration["infos_auto"] = {}
        intacte = assistant.creneaux_adaptes_au_contact(
            self.base, self.preferences, configuration, contact,
            "Je peux vous proposer : mardi matin.")
        self.assertEqual(intacte, "Je peux vous proposer : mardi matin.")


