# LE PLANNING (📅 Rendez-vous) et LE POSTE DE TRAVAIL DES ÉTATS (👥 Clients).
# Tout est exercé pour de vrai — base en mémoire, jamais donnees/ringback.db.
# --------------------------------------------------------------------------
def _date_jour_lisible_test(jour):
    """« lundi 07/09/2026 » — comme l'écrit l'écran, pour les assertions."""
    return f"{horaires.JOURS[jour.weekday()]} {jour:%d/%m/%Y}"



class TestGrilleSemaine(unittest.TestCase):
    """La grille du planning : une tuile par rendez-vous, jamais une par tranche."""

    LUNDI = datetime.date(2026, 9, 7)

    def setUp(self):
        self.base = db.Base(":memory:")
        self.preferences = generation.Preferences(None)
        for jour in range(5):
            horaires.basculer_periode(self.preferences, jour, 9 * 60,
                                      12 * 60, "ouvrir")

    def _poser(self, nom, jour, heure, minute, tranches, statut="prévu"):
        client_id = self.base.obtenir_ou_creer_client(nom, "+33 6 00 00 00 70")
        quand = datetime.datetime.combine(
            self.LUNDI + datetime.timedelta(days=jour),
            datetime.time(heure, minute))
        return self.base.ajouter_rendezvous(
            client_id, quand.isoformat(timespec="minutes"), "Séance",
            statut=statut, duree_tranches=tranches)

    def test_trois_tranches_consecutives_font_UNE_tuile_de_hauteur_trois(self):
        self._poser("Mme Longue", 0, 9, 0, 3)
        grille = horaires.grille_semaine(self.base, self.preferences, self.LUNDI)
        lundi = grille["jours"][0]["cellules"]
        tuiles = [c for c in lundi if c["type"] == "tuile"]
        couvertes = [c for c in lundi if c["type"] == "couverte"]
        self.assertEqual(len(tuiles), 1)            # UNE tuile, pas trois
        self.assertEqual(tuiles[0]["hauteur"], 3)   # de hauteur 3
        self.assertEqual(len(couvertes), 2)         # deux tranches avalées
        self.assertFalse(tuiles[0]["tronquee"])
        # Et les tranches qu'elle occupe ne sont plus « libres ».
        libres = [c for c in lundi if c["type"] == "libre"]
        self.assertEqual(len(libres), 12 - 3)       # 9h→12h = 12 tranches

    def test_seuls_les_rendezvous_qui_occupent_font_une_tuile(self):
        self._poser("Mme Annulée", 0, 9, 0, 2, statut="annulé")
        self._poser("M. Déplacé", 0, 10, 0, 2, statut="déplacé")
        self._poser("Mme Confirmée", 0, 11, 0, 2, statut="confirmé")
        grille = horaires.grille_semaine(self.base, self.preferences, self.LUNDI)
        tuiles = [c for c in grille["jours"][0]["cellules"] if c["type"] == "tuile"]
        self.assertEqual([t["rdv"]["nom"] for t in tuiles], ["Mme Confirmée"])

    def test_l_amplitude_s_elargit_pour_un_rendezvous_hors_horaires(self):
        self._poser("M. Très Tôt", 0, 6, 30, 2)
        grille = horaires.grille_semaine(self.base, self.preferences, self.LUNDI)
        self.assertEqual(grille["minutes"][0], 6 * 60 + 30)   # rien n'est caché
        tuiles = [c for c in grille["jours"][0]["cellules"] if c["type"] == "tuile"]
        self.assertEqual(len(tuiles), 1)

    def test_un_jour_ferme_n_a_aucune_tranche_libre(self):
        horaires.ajouter_jour_ferme(self.preferences,
                                    (self.LUNDI + datetime.timedelta(days=1)
                                     ).isoformat(), "Formation")
        grille = horaires.grille_semaine(self.base, self.preferences, self.LUNDI)
        mardi = grille["jours"][1]
        self.assertEqual(mardi["ferme"], "Formation")
        self.assertEqual([c for c in mardi["cellules"] if c["type"] == "libre"], [])

    def test_deux_rendezvous_superposes_ne_s_ecrasent_pas(self):
        self._poser("Mme Première", 0, 9, 0, 2)
        self._poser("M. Second", 0, 9, 0, 2)
        grille = horaires.grille_semaine(self.base, self.preferences, self.LUNDI)
        tuiles = [c for c in grille["jours"][0]["cellules"] if c["type"] == "tuile"]
        self.assertEqual(len(tuiles), 1)
        self.assertEqual(len(grille["superposes"]), 1)   # signalé, jamais caché

    def test_suites_libres_datees_donnent_les_trous_l_un_apres_l_autre(self):
        self._poser("Mme Milieu", 0, 10, 0, 2)     # coupe le lundi en deux
        depuis = datetime.datetime.combine(self.LUNDI, datetime.time(0, 0))
        trous = horaires.suites_libres_datees(self.base, self.preferences,
                                              depuis=depuis, jours=0)
        self.assertEqual([(t["debut"].strftime("%H:%M"), t["tranches"])
                          for t in trous],
                         [("09:00", 4), ("10:30", 6)])


class TestServeurPlanning(_TestAvecServeurWeb):
    """Le planning à l'écran : tuiles fusionnées, modale, navigation."""

    LUNDI = datetime.date(2026, 9, 7)

    def setUp(self):
        super().setUp()
        preferences = self.application.preferences
        for jour in range(5):
            horaires.basculer_periode(preferences, jour, 9 * 60, 12 * 60,
                                      "ouvrir")

    def _poser(self, nom, jour, heure, minute, tranches, statut="prévu"):
        base = self.application.base
        client_id = base.obtenir_ou_creer_client(nom, "+33 6 00 00 00 71")
        quand = datetime.datetime.combine(
            self.LUNDI + datetime.timedelta(days=jour),
            datetime.time(heure, minute))
        return base.ajouter_rendezvous(client_id,
                                       quand.isoformat(timespec="minutes"),
                                       "Séance longue", statut=statut,
                                       duree_tranches=tranches)

    def _semaine(self, **extra):
        parametres = {"annee": 2026, "semaine": 37}
        parametres.update(extra)
        return self._obtenir("/suivi/planning?"
                             + urllib.parse.urlencode(parametres))

    def test_le_planning_est_sur_la_page_rendez_vous(self):
        _, page = self._obtenir("/suivi")
        self.assertIn('id="planning"', page)
        self.assertIn("Prochain créneau disponible", page)
        # Le vert des tranches libres est EXACTEMENT celui du calendrier des
        # réglages : la même variable CSS, pas une couleur recopiée. Elle a
        # changé de nom le 02/08/2026 (--creneau-libre, identique dans les
        # deux thèmes) ; ce qui compte reste qu'il n'y en ait qu'UNE.
        self.assertIn("table.planning td.libre { background: var(--creneau-libre)",
                      serveur.STYLE)
        self.assertIn("table.calendrier td.tranche.ouverte { background: "
                      "var(--creneau-libre)", serveur.STYLE)

    def test_une_tuile_unique_pour_un_rendezvous_de_quatre_tranches(self):
        self._poser("Mme Quatre Tranches", 0, 9, 0, 4)
        _, fragment = self._semaine()
        self.assertNotIn("<!DOCTYPE", fragment)          # un FRAGMENT
        self.assertEqual(fragment.count('class="tuile" rowspan="4"'), 1)
        self.assertEqual(fragment.count("Mme Quatre Tranches"), 2)  # tuile + bulle
        # Aucune tuile de hauteur 1 : les trois autres tranches sont avalées.
        self.assertNotIn('class="tuile" rowspan="1"', fragment)

    def test_la_modale_donne_le_detail_avec_le_numero_MASQUE(self):
        rdv_id = self._poser("Mme Modale Exemple", 0, 9, 0, 2)
        _, modale = self._obtenir(f"/suivi/detail?rdv={rdv_id}")
        self.assertNotIn("<!DOCTYPE", modale)
        self.assertIn("Mme Modale Exemple", modale)
        self.assertIn("Séance longue", modale)
        self.assertIn("lundi 07/09/2026", modale)
        self.assertIn("de 09h00 à 09h30", modale)
        self.assertIn("2 tranches de 15 min (30 minutes)", modale)
        self.assertIn("+33 6 •• •• •• 71", modale)       # masqué, comme partout
        self.assertNotIn("+33 6 00 00 00 71", modale)
        self.assertIn("modale-fermer", modale)
        # Un créneau libre a sa propre modale, calculée elle aussi.
        _, creneau = self._obtenir("/suivi/detail?creneau=2026-09-07T10:00")
        self.assertIn("Créneau libre", creneau)
        self.assertIn("lundi 07/09/2026", creneau)
        # R15 FERMÉE : la création de campagne est RÉELLE, plus « à venir ».
        self.assertNotIn("à venir", creneau)
        self.assertIn('action="/suivi/creneau/campagne"', creneau)
        self.assertIn('value="2026-09-07T10:00"', creneau)

    def test_naviguer_autrement_que_par_la_date_REINITIALISE_le_champ_date(self):
        # 1. Le champ date mène à sa semaine ET reste rempli.
        _, page = self._semaine(aller="date", date="2026-09-15")
        self.assertIn('name="date" value="2026-09-15"', page)
        self.assertIn("Semaine du 14/09/2026", page)
        # 2. La flèche « suivant » vide le champ date — règle du propriétaire.
        _, page = self._semaine(aller="suivant", semaine=38, date="2026-09-15")
        self.assertIn('name="date" value=""', page)
        self.assertIn("Semaine du 21/09/2026", page)
        # 3. Et la flèche « précédent » aussi.
        _, page = self._semaine(aller="precedent", semaine=38,
                                date="2026-09-15")
        self.assertIn('name="date" value=""', page)
        self.assertIn("Semaine du 07/09/2026", page)
        # 4. Le sélecteur de semaine aussi.
        _, page = self._semaine(aller="semaine", semaine=40,
                                date="2026-09-15")
        self.assertIn('name="date" value=""', page)
        self.assertIn("Semaine du 28/09/2026", page)

    def test_date_illisible_refusee_sans_perdre_la_saisie(self):
        _, page = self._semaine(aller="date", date="bientôt")
        self.assertIn("Date refusée", page)
        self.assertIn("Date illisible", page)
        self.assertIn('name="date" value="bientôt"', page)   # jamais perdue

    def test_prochain_creneau_avance_de_trou_en_trou_puis_se_remet_a_zero(self):
        base = self.application.base
        # Une seule journée ouverte, coupée en deux par un rendez-vous.
        for jour in range(5):
            horaires.basculer_periode(self.application.preferences, jour,
                                      9 * 60, 12 * 60, "fermer")
        futur = datetime.date.today() + datetime.timedelta(days=2)
        horaires.basculer_periode(self.application.preferences,
                                  futur.weekday(), 9 * 60, 10 * 60, "ouvrir")
        client_id = base.obtenir_ou_creer_client("M. Milieu", "+33 6 00 00 00 72")
        base.ajouter_rendezvous(
            client_id,
            datetime.datetime.combine(futur, datetime.time(9, 15)).isoformat(
                timespec="minutes"), "Séance", duree_tranches=1)
        # Premier clic : le trou le plus proche (9h00, une tranche).
        _, page = self._obtenir("/suivi/planning?aller=prochain&rang=0")
        self.assertIn("Prochain créneau disponible n° 1", page)
        self.assertIn("à 9h00", page)
        self.assertIn('name="rang" value="1"', page)
        self.assertIn("place libre : 1 tranche de 15 min", page)
        self.assertEqual(page.count('<td class="tuile"'), 1)
        # Deuxième clic : le trou D'APRÈS (9h30, deux tranches).
        _, page = self._obtenir("/suivi/planning?aller=prochain&rang=1")
        self.assertIn("Prochain créneau disponible n° 2", page)
        self.assertIn("à 9h30", page)
        self.assertIn('name="rang" value="2"', page)
        # Troisième clic : le trou d'après encore — la SEMAINE SUIVANTE.
        _, page = self._obtenir("/suivi/planning?aller=prochain&rang=2")
        self.assertIn("Prochain créneau disponible n° 3", page)
        self.assertIn(_date_jour_lisible_test(futur + datetime.timedelta(days=7)),
                      page)
        self.assertIn('name="rang" value="3"', page)
        # Au bout de la liste, la position repart de zéro (et le dit).
        _, page = self._obtenir("/suivi/planning?aller=prochain&rang=999")
        self.assertIn("Plus de créneau au-delà du n° 999", page)
        self.assertIn('name="rang" value="0"', page)
        # Naviguer autrement remet aussi la position à zéro.
        _, page = self._obtenir("/suivi/planning?aller=suivant&rang=2")
        self.assertIn('name="rang" value="0"', page)

    def test_sans_horaires_ouverts_le_prochain_creneau_le_dit(self):
        for jour in range(5):
            horaires.basculer_periode(self.application.preferences, jour,
                                      9 * 60, 12 * 60, "fermer")
        _, page = self._obtenir("/suivi/planning?aller=prochain&rang=0")
        self.assertIn("Aucun créneau libre", page)
        self.assertIn('name="rang" value="0"', page)


class TestEtatsClients(unittest.TestCase):
    """Les deux états d'un client, et la définition exacte de « non traité »."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.preferences = generation.Preferences(None)

    def _client(self, nom, telephone="+33 6 00 00 00 80"):
        return self.base.ajouter_client(nom, telephone)

    def test_un_rendezvous_long_compte_pour_UN_rendezvous(self):
        client_id = self._client("Mme Longue Séance")
        self.base.ajouter_rendezvous(client_id, DEMAIN, "Bilan",
                                     duree_tranches=4)
        client = self.base.obtenir_client(client_id)
        self.assertEqual(client["nb_rendezvous"], 1)     # 1, pas 4
        fiche = etats_clients.tableau_clients(self.base, self.preferences)[0]
        self.assertEqual(fiche["resume"]["total"], 1)
        self.assertEqual(fiche["agenda"], "rendez-vous prévu")

    def test_etat_d_agenda_et_etat_de_conversation_sont_distincts(self):
        client_id = self._client("M. Deux États")
        self.base.ajouter_rendezvous(client_id, HIER, "Séance", statut="manqué")
        campagne_id = self.base.creer_campagne("Essai", "personnalise",
                                               nature="prise_rdv",
                                               statut="terminée")
        contact_id = self.base.ajouter_contact_campagne(
            campagne_id, 0, "M. Deux États", "+33 6 00 00 00 80",
            etat="injoignable")
        self.base.ajouter_appel_campagne(campagne_id, contact_id, 0,
                                         issue="no_answer")
        self.base.ajouter_appel_campagne(campagne_id, contact_id, 1,
                                         issue="no_answer")
        fiche = etats_clients.tableau_clients(self.base, self.preferences)[0]
        self.assertEqual(fiche["agenda"], "rendez-vous manqué (absent)")
        self.assertEqual(fiche["conversation"], "injoignable")
        self.assertEqual(fiche["tentatives"], 2)
        self.assertIn("(2)", etats_clients.libelle_conversation(
            "injoignable", fiche["tentatives"]))

    def test_non_traite_bascule_quand_une_campagne_EN_COURS_le_prend(self):
        client_id = self._client("Mme À Recaler")
        self.base.ajouter_rendezvous(client_id, HIER, "Séance", statut="manqué")
        fiche = etats_clients.tableau_clients(self.base, self.preferences)[0]
        self.assertTrue(fiche["non_traite"])
        self.assertEqual([b["etat"] for b in fiche["besoins"]],
                         ["rendez-vous manqué (absent)"])
        # Une campagne CLOSE ne le traite pas.
        close_id = self.base.creer_campagne("Close", "personnalise",
                                            nature="prise_rdv", statut="close")
        self.base.ajouter_contact_campagne(close_id, 0, "Mme À Recaler",
                                           "+33 6 00 00 00 80")
        fiche = etats_clients.tableau_clients(self.base, self.preferences)[0]
        self.assertTrue(fiche["non_traite"])
        # Une campagne EN COURS de la bonne nature, si.
        vivante_id = self.base.creer_campagne("Vivante", "personnalise",
                                              nature="prise_rdv",
                                              statut="en cours")
        self.base.ajouter_contact_campagne(vivante_id, 0, "Mme À Recaler",
                                           "+33 6 00 00 00 80")
        fiche = etats_clients.tableau_clients(self.base, self.preferences)[0]
        self.assertFalse(fiche["non_traite"])
        self.assertEqual([c["nom"] for c in fiche["campagnes"]], ["Vivante"])
        self.assertEqual(fiche["campagnes"][0]["etat_entree"],
                         "rendez-vous manqué (absent)")
        # Une campagne d'une AUTRE nature ne traite pas cet état.
        autre_id = self.base.creer_campagne("Autre", "personnalise",
                                            nature="creneau_libere",
                                            statut="en cours")
        self.base.ajouter_contact_campagne(autre_id, 0, "Mme À Recaler",
                                           "+33 6 00 00 00 80")
        fiche = etats_clients.tableau_clients(self.base, self.preferences)[0]
        self.assertFalse(fiche["non_traite"])   # toujours pris par « Vivante »

    def test_exclu_ou_sans_numero_n_est_jamais_non_traite(self):
        exclu_id = self._client("M. Exclu", "+33 6 00 00 00 81")
        self.base.ajouter_rendezvous(exclu_id, HIER, "Séance", statut="manqué")
        self.base.definir_ne_plus_appeler(exclu_id, True)
        muet_id = self._client("Mme Sans Numéro", "")
        self.base.ajouter_rendezvous(muet_id, HIER, "Séance", statut="manqué")
        fiches = {f["client"]["nom"]: f for f in
                  etats_clients.tableau_clients(self.base, self.preferences)}
        self.assertFalse(fiches["M. Exclu"]["non_traite"])
        self.assertEqual(fiches["M. Exclu"]["conversation"], "ne plus appeler")
        self.assertFalse(fiches["Mme Sans Numéro"]["non_traite"])
        self.assertTrue(fiches["Mme Sans Numéro"]["sans_numero"])

    def test_les_etats_sans_campagne_restent_du_travail_humain(self):
        client_id = self._client("M. Humain")
        campagne_id = self.base.creer_campagne("Essai", "personnalise",
                                               nature="prise_rdv",
                                               statut="en cours")
        self.base.ajouter_contact_campagne(
            campagne_id, 0, "M. Humain", "+33 6 00 00 00 80",
            etat="à rappeler par un humain")
        fiche = etats_clients.tableau_clients(self.base, self.preferences)[0]
        self.assertEqual(fiche["conversation"], "à rappeler par un humain")
        self.assertTrue(fiche["humain"])
        self.assertTrue(fiche["non_traite"])   # aucune campagne ne le traitera

    def test_le_filtre_ignore_la_casse_et_les_accents(self):
        self._client("Mme Nadia Lefèvre")
        fiches = etats_clients.tableau_clients(self.base, self.preferences)
        self.assertEqual(len(etats_clients.filtrer(fiches, "LEFEVRE")), 1)
        self.assertEqual(len(etats_clients.filtrer(fiches, "lefèvre")), 1)
        self.assertEqual(len(etats_clients.filtrer(fiches, "durand")), 0)


class TestServeurPosteClients(_TestAvecServeurWeb):
    """La page 👥 Clients : états, campagnes, filtres et édition de fiche."""

    def test_la_liste_montre_les_deux_etats_et_le_compte_de_rendezvous(self):
        base = self.application.base
        client_id = base.obtenir_ou_creer_client("Mme Longue Séance",
                                                 "+33 6 00 00 00 82")
        base.ajouter_rendezvous(client_id, DEMAIN, "Bilan", duree_tranches=4)
        _, page = self._obtenir("/clients")
        self.assertIn("Contacts (5)", page)
        self.assertIn("État d'agenda", page)
        self.assertIn("État de conversation", page)
        ligne = page.split("Mme Longue Séance")[1].split("</tr>")[0]
        self.assertIn("<strong>1</strong>", ligne)      # 1 rendez-vous, pas 4
        self.assertIn("📅 rendez-vous prévu", ligne)
        self.assertIn("— jamais appelé", ligne)
        self.assertIn("+33 6 •• •• •• 82", ligne)
        self.assertNotIn("+33 6 00 00 00 82", page)    # masqué partout

    def test_les_filtres_rechargent_la_SEULE_liste(self):
        _, fragment = self._obtenir("/clients/liste?recherche=nadia")
        self.assertNotIn("<!DOCTYPE", fragment)         # un FRAGMENT
        self.assertIn("<strong>1</strong> contact(s) sur 4", fragment)
        self.assertIn("Mme Nadia Lefèvre", fragment)
        self.assertNotIn("M. Karim Osman", fragment)
        # Le filtre « non traité » : les 4 manqués de la démo le sont tous…
        _, fragment = self._obtenir("/clients/liste?non_traite=1")
        self.assertIn("<strong>4</strong> contact(s) sur 4", fragment)
        self.assertIn("non traité", fragment)
        # …jusqu'à ce qu'une campagne EN COURS en prenne un.
        base = self.application.base
        campagne_id = base.creer_campagne("Reprise", "personnalise",
                                          nature="prise_rdv", statut="en cours")
        base.ajouter_contact_campagne(campagne_id, 0, "Mme Nadia Lefèvre",
                                      "+33 6 00 00 00 41")
        _, fragment = self._obtenir("/clients/liste?non_traite=1")
        self.assertIn("<strong>3</strong> contact(s) sur 4", fragment)
        self.assertNotIn("Mme Nadia Lefèvre", fragment)
        # Et elle apparaît, elle, comme prise en charge.
        _, fragment = self._obtenir("/clients/liste?recherche=nadia")
        self.assertIn("pris en charge", fragment)
        # ⚠ LE DÉTAIL DES CAMPAGNES N'EST PLUS DANS LA LIGNE (02/08/2026) :
        # elle ne porte qu'un NOMBRE, qui mène au détail. C'est ce qui a
        # ramené la ligne à une hauteur lisible.
        self.assertNotIn("entré pour : rendez-vous manqué (absent)", fragment)
        self.assertIn('data-modale="/clients/detail-campagnes?id=1"', fragment)
        # Et le détail, lui, est bien au bout du lien — pas perdu.
        _, modale = self._obtenir("/clients/detail-campagnes?id=1")
        self.assertIn("Reprise", modale)
        self.assertIn("entré pour : rendez-vous manqué (absent)", modale)

    def test_les_deux_colonnes_ne_montrent_qu_un_nombre(self):
        """Une ligne de client tenait sur six lignes d'écran.

        Demande du propriétaire (02/08/2026) : un NOMBRE dans la cellule, le
        détail au clic. Le lien mène toujours à la fiche pleine page — sans
        JavaScript, rien n'est perdu.
        """
        _, fragment = self._obtenir("/clients/liste?recherche=nadia")
        self.assertIn('data-modale="/clients/detail-rendezvous?id=1"', fragment)
        self.assertIn('href="/clients/fiche?id=1"', fragment)
        # Le détail d'avant a quitté la ligne.
        self.assertNotIn("prochain :", fragment)
        self.assertNotIn("dernier :", fragment)
        # Et il est au bout du lien, plus complet qu'avant : la liste entière.
        _, modale = self._obtenir("/clients/detail-rendezvous?id=1")
        self.assertIn("rendez-vous, du plus récent", modale)
        self.assertIn("<th>Motif</th>", modale)
        self.assertNotIn("<!DOCTYPE", modale)          # un fragment

    def test_un_client_sans_rien_n_a_aucun_lien_mort(self):
        """Zéro n'est pas cliquable : une fenêtre vide ne dit rien."""
        base = self.application.base
        base.ajouter_client("M. Sans Rien", "+33 6 00 00 00 47")
        _, fragment = self._obtenir("/clients/liste?recherche=sans+rien")
        self.assertNotIn("detail-rendezvous", fragment)
        self.assertNotIn("detail-campagnes", fragment)
        self.assertIn("aucune", fragment)

    def test_un_identifiant_inconnu_est_refuse_proprement(self):
        for chemin in ("/clients/detail-rendezvous", "/clients/detail-campagnes"):
            with self.subTest(chemin=chemin):
                with self.assertRaises(urllib.error.HTTPError) as refus:
                    self._obtenir(f"{chemin}?id=999999")
                self.assertEqual(refus.exception.code, 404)
                with self.assertRaises(urllib.error.HTTPError) as refus:
                    self._obtenir(f"{chemin}?id=abc")
                self.assertEqual(refus.exception.code, 400)

    def test_editer_un_client_refus_puis_enregistrement(self):
        base = self.application.base
        _, page = self._obtenir("/clients/fiche?id=1")
        self.assertIn("Modifier sa fiche", page)
        self.assertIn('name="nom" value="Mme Nadia Lefèvre"', page)
        self.assertIn("+33 6 •• •• •• 41", page)         # masqué même ici
        self.assertNotIn("+33 6 00 00 00 41", page)
        self.assertIn("Laissez le champ", page)          # le format est dit
        # Refus : la saisie fautive revient dans son champ, rien n'est écrit.
        _, page = self._poster("/clients/modifier",
                               {"client": 1, "nom": "N",
                                "telephone": "06 12"})
        self.assertIn("Saisie refusée", page)
        self.assertIn("deux caractères minimum", page)
        self.assertIn("Numéro de téléphone invalide", page)
        self.assertIn('name="nom" value="N"', page)
        self.assertIn('name="telephone" value="06 12"', page)
        self.assertEqual(base.obtenir_client(1)["nom"], "Mme Nadia Lefèvre")
        # Enregistrement : nom corrigé, numéro changé (et masqué), 🚫 posé.
        _, page = self._poster("/clients/modifier",
                               {"client": 1, "nom": "Mme Nadia Lefèvre-Martin",
                                "telephone": "0199001234",
                                "ne_plus_appeler": "1"})
        self.assertIn("Fiche du client enregistrée", page)
        self.assertIn("Mme Nadia Lefèvre-Martin", page)
        self.assertIn("01 99 •• •• 34", page)
        self.assertNotIn("01 99 00 12 34", page)         # jamais en clair
        client = base.obtenir_client(1)
        self.assertEqual(client["nom"], "Mme Nadia Lefèvre-Martin")
        self.assertTrue(client["ne_plus_appeler"])
        self.assertEqual(base.telephone_de(1), "01 99 00 12 34")
        # Le champ téléphone laissé VIDE garde le numéro tel quel.
        self._poster("/clients/modifier",
                     {"client": 1, "nom": "Mme Nadia Lefèvre-Martin",
                      "telephone": ""})
        self.assertEqual(base.telephone_de(1), "01 99 00 12 34")
        self.assertFalse(base.obtenir_client(1)["ne_plus_appeler"])  # décoché


# =========================================================================
# R15 — LES DEUX PORTES MÈNENT ENFIN À UNE CAMPAGNE
# -------------------------------------------------------------------------
# « Une campagne se crée toujours à partir de ce qui manque » (§1 de
# CAS_DE_FIGURE_CAMPAGNES.md) : un TEMPS pour une personne qui attend
# (porte 👥), ou une PERSONNE pour un temps disponible (porte 📅). Les deux
# portes étaient décrites et affichées « à venir » ; ces tests prouvent
# qu'elles mènent maintenant à l'assistant, à l'étape 2, liste remplie —
# et qu'AUCUN APPEL n'en part.
# =========================================================================


class TestPorteClientsVersCampagne(_TestAvecServeurWeb):
    """§4 — de l'état filtré au bouton, et du bouton à l'étape 2."""

    ETAT_MANQUE = "rendez-vous manqué (absent)"

    def _client_prevu(self, nom="M. Rendez Vous Prévu"):
        """Un client dont le rendez-vous TIENT : deux natures le traitent."""
        base = self.application.base
        client_id = base.obtenir_ou_creer_client(nom, "+33 6 00 00 00 61")
        base.ajouter_rendezvous(client_id, DEMAIN, "Contrôle")
        return client_id

    def _client_humain(self, nom="M. Pour Un Humain"):
        """Un client que SEUL un humain peut reprendre (§6)."""
        base = self.application.base
        client_id = base.obtenir_ou_creer_client(nom, "+33 6 00 00 00 62")
        campagne_id = base.creer_campagne("Passée", "personnalise",
                                          nature="prise_rdv",
                                          statut="terminée")
        base.ajouter_contact_campagne(campagne_id, 1, nom,
                                      "+33 6 00 00 00 62",
                                      etat="à rappeler par un humain",
                                      client_id=client_id)
        return client_id

    def test_le_bouton_nait_du_filtre_et_nomme_la_nature_DEDUITE(self):
        # Sans « non traité », aucun bouton : la sélection contient alors des
        # clients déjà pris en charge, un bouton mentirait sur son compte.
        _, sans = self._obtenir("/clients/liste?etat="
                                + urllib.parse.quote(self.ETAT_MANQUE))
        self.assertNotIn("Créer la campagne", sans)
        # Avec « non traité » : un bouton, la NATURE déduite de l'état par
        # etats_clients.TRAITEMENT, et le compte exact des 4 manqués de démo.
        _, fragment = self._obtenir(
            "/clients/liste?non_traite=1&etat="
            + urllib.parse.quote(self.ETAT_MANQUE))
        self.assertNotIn("<!DOCTYPE", fragment)     # c'est bien le FRAGMENT
        self.assertIn("➕ Créer la campagne « 🗓 Prise de rendez-vous » — "
                      "4 client(s) concerné(s)", fragment)
        self.assertIn('action="/clients/campagne"', fragment)
        self.assertIn('name="nature" value="prise_rdv"', fragment)
        self.assertIn("Aucun appel ne part de ces boutons", fragment)
        # Le bouton n'est pas grisé, il n'annonce rien « à venir ».
        self.assertNotIn("badge-a-venir", fragment)

    def test_un_bouton_PAR_NATURE_quand_le_filtre_mele_les_etats(self):
        """La décision du propriétaire du 31/07/2026, tenue à la lettre."""
        self._client_prevu()
        # Un seul état peut déjà appeler DEUX natures (§3).
        _, prevu = self._obtenir("/clients/liste?non_traite=1&etat="
                                 + urllib.parse.quote("rendez-vous prévu"))
        self.assertIn("« 🔔 Rappel de rendez-vous » — 1 client(s)", prevu)
        self.assertIn("« ✅ Confirmation de rendez-vous » — 1 client(s)",
                      prevu)
        self.assertNotIn("Prise de rendez-vous", prevu)
        # Sans filtre d'état, la sélection mêle les deux familles : TROIS
        # boutons, chacun avec SON compte — jamais un bouton grisé.
        _, mele = self._obtenir("/clients/liste?non_traite=1")
        self.assertIn("« 🗓 Prise de rendez-vous » — 4 client(s)", mele)
        self.assertIn("« 🔔 Rappel de rendez-vous » — 1 client(s)", mele)
        self.assertIn("« ✅ Confirmation de rendez-vous » — 1 client(s)",
                      mele)
        self.assertEqual(mele.count('action="/clients/campagne"'), 3)

    def test_un_etat_sans_campagne_ne_donne_AUCUN_bouton_mais_dit_pourquoi(self):
        self._client_humain()
        _, fragment = self._obtenir(
            "/clients/liste?non_traite=1&etat="
            + urllib.parse.quote("à rappeler par un humain"))
        self.assertIn("M. Pour Un Humain", fragment)
        self.assertNotIn("Créer la campagne", fragment)
        self.assertIn("aucune campagne ne traite cela", fragment)
        # Et le compteur humain de la page reste visible (§6).
        _, page = self._obtenir("/clients")
        self.assertIn("🙋 1 client(s) attendent un appel HUMAIN", page)

    def test_le_clic_ouvre_l_ETAPE_2_liste_remplie_et_AUCUN_APPEL(self):
        base = self.application.base
        statut, page = self._poster("/clients/campagne",
                                    {"nature": "prise_rdv",
                                     "etat": self.ETAT_MANQUE,
                                     "recherche": ""})
        self.assertEqual(statut, 200)
        # C'est bien l'étape ② : le fil d'Ariane l'annonce, et la nature
        # n'est PAS redemandée.
        self.assertIn('id="fa-etape-2" class="fa-etape fa-courante"', page)
        self.assertIn("Nouvelle campagne — message", page)
        self.assertIn("🗓 <strong>Prise de rendez-vous</strong>", page)
        # La liste est déjà remplie, et le compte est dit.
        self.assertIn("👥 Liste déjà remplie : <strong>4</strong> personne(s)",
                      page)
        self.assertIn("depuis 👥 Contacts — état « ⚠ absent à son rendez-vous »",
                      page)
        # AUCUN APPEL, AUCUNE campagne : rien n'existe encore en base.
        self.assertEqual(base.lister_campagnes(), [])
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM appels").fetchone()[0], 0)
        # Le brouillon porte bien les 4 personnes, numéros compris.
        brouillon = self.application.obtenir_brouillon_assistant(
            self._brouillon(page))
        self.assertEqual(len(brouillon["contacts"]), 4)
        self.assertIn("Mme Nadia Lefèvre",
                      [c["nom"] for c in brouillon["contacts"]])

    def test_la_recette_garde_le_critere_et_reste_REJOUABLE(self):
        _, page = self._poster("/clients/campagne",
                               {"nature": "prise_rdv",
                                "etat": self.ETAT_MANQUE, "recherche": ""})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "ordre": "liste",
            "info_entreprise": "Cabinet Essai",
            "info_origine": "vous avez demandé un rendez-vous",
            "info_creneaux_proposes": "mardi 9h00",
            "relance_mode": "delai", "relance_delai": "4", "relance_max": "3"})
        _, fiche = self._poster("/assistant/liste", {"b": b,
                                                     "action": "valider"})
        self.assertIn("prête", fiche)
        base = self.application.base
        campagne = base.lister_campagnes()[0]
        configuration = assistant.configuration_campagne(campagne)
        self.assertEqual(configuration["recette"]["apports"],
                         [{"mode": "etat", "etat": self.ETAT_MANQUE,
                           "nature": "prise_rdv", "recherche": ""}])
        self.assertTrue(assistant.recette_reproductible(
            configuration["recette"]))
        self.assertIn("rejouable sur un autre créneau", fiche)
        # Et elle se REJOUE vraiment : le critère reconstruit la liste.
        contacts, _ = assistant.contacts_de_recette(
            base, configuration["recette"],
            assistant.champs_campagne(configuration),
            self.application.preferences)
        self.assertEqual(len(contacts), 4)


class TestPortePlanningVersCampagne(_TestAvecServeurWeb):
    """§5 — les trois gestes du calendrier, et la boucle qui se referme."""

    def _poster_modale(self, chemin, donnees):
        """Le POST tel que la modale l'envoie ; rend (cible, corps)."""
        octets = urllib.parse.urlencode(donnees, doseq=True).encode("utf-8")
        requete = urllib.request.Request(
            self.racine + chemin, data=octets,
            headers={"X-RingBack-Fragment": "1"})
        with urllib.request.urlopen(requete, timeout=15) as reponse:
            return (reponse.headers.get("X-RingBack-Cible"),
                    reponse.read().decode("utf-8"))

    def _rendezvous(self, heures, nom="Mme Place Prise"):
        """Un rendez-vous dans N heures — c'est LUI qui décide de la règle."""
        base = self.application.base
        client_id = base.obtenir_ou_creer_client(nom, "+33 6 00 00 00 63")
        quand = (datetime.datetime.now()
                 + datetime.timedelta(hours=heures)).replace(
                     second=0, microsecond=0)
        return base.ajouter_rendezvous(client_id,
                                       quand.isoformat(timespec="minutes"),
                                       "Séance")

    def test_un_creneau_libre_mene_a_la_campagne_sur_CETTE_place(self):
        for jour in range(7):
            horaires.basculer_periode(self.application.preferences, jour,
                                      9 * 60, 18 * 60, "ouvrir")
        creneau = (datetime.datetime.now()
                   + datetime.timedelta(days=3)).replace(
                       hour=10, minute=0, second=0,
                       microsecond=0).isoformat(timespec="minutes")
        _, modale = self._obtenir("/suivi/detail?creneau="
                                  + urllib.parse.quote(creneau))
        self.assertNotIn("à venir", modale)     # R15 : plus de promesse
        self.assertIn('action="/suivi/creneau/campagne"', modale)
        self.assertIn(f'name="creneau" value="{creneau}"', modale)
        # Le clic mène à l'étape 2, créneau DÉJÀ rempli, sans aucun appel.
        _, page = self._poster("/suivi/creneau/campagne",
                               {"creneau": creneau, "depuis": "planning"})
        self.assertIn('id="fa-etape-2" class="fa-etape fa-courante"', page)
        self.assertIn("📞 <strong>Créneau libéré</strong>", page)
        self.assertIn(f'name="info_creneau_libere" value="{creneau}"', page)
        self.assertEqual(self.application.base.lister_campagnes(), [])
        self.assertEqual(self.application.base.conn.execute(
            "SELECT COUNT(*) FROM appels").fetchone()[0], 0)

    def test_un_rendezvous_propose_RAPPELER_DEPLACER_et_ANNULER(self):
        rdv_id = self._rendezvous(72)
        _, modale = self._obtenir(f"/suivi/detail?rdv={rdv_id}")
        # TROIS gestes depuis le 02/08/2026 : le rappel a rejoint le
        # déplacement et l'annulation, sur demande du propriétaire.
        self.assertIn("Les trois gestes", modale)
        self.assertIn('action="/suivi/detail/rappel"', modale)
        self.assertIn('action="/suivi/detail/deplacer"', modale)
        self.assertIn('action="/suivi/detail/annuler"', modale)
        # « Rappeler » monte la campagne 🔔 sur CE rendez-vous, à l'étape 2.
        _, page = self._poster("/suivi/detail/rappel", {"rdv": rdv_id})
        self.assertIn('id="fa-etape-2" class="fa-etape fa-courante"', page)
        self.assertIn("🔔 <strong>Rappel de rendez-vous</strong>", page)
        self.assertIn("👥 Liste déjà remplie : <strong>1</strong> personne(s)",
                      page)
        self.assertIn("Mme Place Prise", page)
        self.assertEqual(self.application.base.lister_campagnes(), [])
        # « Déplacer » monte la campagne 📆 sur CE rendez-vous, à l'étape 2.
        _, page = self._poster("/suivi/detail/deplacer", {"rdv": rdv_id})
        self.assertIn('id="fa-etape-2" class="fa-etape fa-courante"', page)
        self.assertIn("📆 <strong>Déplacement de rendez-vous</strong>", page)
        self.assertIn("👥 Liste déjà remplie : <strong>1</strong> personne(s)",
                      page)
        self.assertIn("Mme Place Prise", page)
        self.assertEqual(self.application.base.lister_campagnes(), [])
        self.assertEqual(self.application.base.conn.execute(
            "SELECT COUNT(*) FROM appels").fetchone()[0], 0)

    def _lundi_du_rendezvous(self, rdv_id):
        rdv = self.application.base.obtenir_rendezvous(rdv_id)
        jour = datetime.date.fromisoformat(rdv["horaire"][:10])
        return jour, jour - datetime.timedelta(days=jour.weekday())

    def test_la_semaine_propose_une_campagne_de_rappel(self):
        """Le bouton de l'entête, et sa fenêtre semaine / jours choisis.

        Demande du propriétaire (02/08/2026). Deux temps : on demande QUI
        contacter avant de montrer la liste des jours — sinon ce seraient
        les options d'une option.
        """
        rdv_id = self._rendezvous(72)
        jour, lundi = self._lundi_du_rendezvous(rdv_id)
        # ⚠ On demande LA SEMAINE DU RENDEZ-VOUS : à +72 h il peut tomber la
        # semaine suivante, et le bouton n'apparaît que s'il y a du monde.
        annee, semaine = lundi.isocalendar()[0], lundi.isocalendar()[1]
        _, page = self._obtenir(f"/suivi?annee={annee}&semaine={semaine}")
        self.assertIn("🔔 Créer une campagne de rappel", page)
        self.assertIn('class="entete-section"', page)
        _, modale = self._obtenir(
            f"/suivi/detail?rappel=semaine&lundi={lundi:%Y-%m-%d}")
        self.assertIn("Créer une campagne de rappel pour", modale)
        self.assertIn('name="qui" value="semaine"', modale)
        self.assertIn('name="qui" value="jours"', modale)
        # Les jours proposés sont ceux qui PORTENT des rendez-vous.
        self.assertIn(f'value="{jour:%Y-%m-%d}"', modale)
        self.assertIn('id="rappel-jours" hidden', modale)   # replié d'abord
        # Toute la semaine : l'assistant s'ouvre, liste remplie, zéro appel.
        _, page = self._poster("/suivi/rappel/campagne",
                               {"lundi": f"{lundi:%Y-%m-%d}", "qui": "semaine"})
        self.assertIn('id="fa-etape-2" class="fa-etape fa-courante"', page)
        self.assertIn("🔔 <strong>Rappel de rendez-vous</strong>", page)
        self.assertIn("personne(s) à rappeler pour la semaine du", page)
        self.assertEqual(self.application.base.lister_campagnes(), [])
        self.assertEqual(self.application.base.conn.execute(
            "SELECT COUNT(*) FROM appels").fetchone()[0], 0)

    def test_un_jour_choisi_ne_prend_que_ce_jour(self):
        rdv_id = self._rendezvous(72)
        jour, lundi = self._lundi_du_rendezvous(rdv_id)
        _, page = self._poster("/suivi/rappel/campagne", {
            "lundi": f"{lundi:%Y-%m-%d}", "qui": "jours",
            "jour": f"{jour:%Y-%m-%d}"})
        self.assertIn("👥 Liste déjà remplie : <strong>1</strong> personne(s)",
                      page)
        # ⚠ Le jour est nommé EN FRANÇAIS : « %A » suit la langue du système
        # et écrivait « Monday 03/08 » sur cette machine (vu à l'écran le
        # 02/08/2026). Les noms de jours du produit sont dans horaires.JOURS.
        self.assertIn(horaires.JOURS[jour.weekday()], page)
        for anglais in ("Monday", "Tuesday", "Wednesday", "Thursday",
                        "Friday", "Saturday", "Sunday"):
            self.assertNotIn(anglais, page)
        # Aucun jour coché : refusé, et rien n'est monté.
        with self.assertRaises(urllib.error.HTTPError) as refus:
            self._poster("/suivi/rappel/campagne",
                         {"lundi": f"{lundi:%Y-%m-%d}", "qui": "jours"})
        self.assertEqual(refus.exception.code, 409)

    def test_un_rendezvous_confirme_est_rappele_lui_aussi(self):
        """L'entête comptait 13, la campagne n'en reprenait aucun.

        Constaté par le propriétaire le 02/08/2026 : « erreur 409, personne à
        rappeler », alors que son rendez-vous était bien là — mais CONFIRMÉ.
        Le planning compte les prévus ET les confirmés ; la campagne ne
        prenait que les prévus. Un rendez-vous confirmé se rappelle aussi.
        """
        base = self.application.base
        rdv_id = self._rendezvous(72)
        base.mettre_a_jour_rendezvous(rdv_id, statut="confirmé")
        jour, lundi = self._lundi_du_rendezvous(rdv_id)
        # La fenêtre le compte…
        _, modale = self._obtenir(
            f"/suivi/detail?rappel=semaine&lundi={lundi:%Y-%m-%d}")
        self.assertIn(f'value="{jour:%Y-%m-%d}"', modale)
        # …et la campagne le reprend, au lieu du 409 d'avant.
        _, page = self._poster("/suivi/rappel/campagne",
                               {"lundi": f"{lundi:%Y-%m-%d}", "qui": "semaine"})
        self.assertIn("👥 Liste déjà remplie : <strong>1</strong> personne(s)",
                      page)

    def test_une_semaine_vide_ne_propose_rien(self):
        """Proposer de rappeler une semaine vide serait creux."""
        loin = datetime.date.today() + datetime.timedelta(days=400)
        lundi = loin - datetime.timedelta(days=loin.weekday())
        _, modale = self._obtenir(
            f"/suivi/detail?rappel=semaine&lundi={lundi:%Y-%m-%d}")
        self.assertIn("il n'y a personne à rappeler", modale)
        self.assertNotIn('name="qui"', modale)

    def test_annuler_APPELLE_la_regle_des_12h_et_propose_la_compensation(self):
        base = self.application.base
        rdv_id = self._rendezvous(72)          # bien au-delà du seuil
        rdv = base.obtenir_rendezvous(rdv_id)
        # 1er temps : on ANNONCE, on n'écrit rien.
        cible, panneau = self._poster_modale("/suivi/detail/annuler",
                                             {"rdv": rdv_id,
                                              "geste": "demander"})
        self.assertEqual(cible, "modale")
        self.assertIn("« supprimé »", panneau)
        self.assertIn("Rien n'est encore écrit", panneau)
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"], "prévu")
        # 2e temps : la règle s'applique — c'est decision_annulation qui a
        # tranché, et la place mène en UN CLIC à la campagne qui la remplira.
        cible, resultat = self._poster_modale("/suivi/detail/annuler",
                                              {"rdv": rdv_id,
                                               "geste": "confirmer"})
        self.assertEqual(cible, "modale")
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"],
                         db.STATUT_SUPPRIME)
        self.assertIn('action="/suivi/creneau/campagne"', resultat)
        self.assertIn(f'name="creneau" value="{rdv["horaire"]}"', resultat)
        # Le planning derrière la fenêtre se remet à jour SEUL.
        self.assertIn('data-rafraichir="planning"', resultat)
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM appels").fetchone()[0], 0)

    def test_annuler_en_deca_du_seuil_reste_ANNULE_et_dit_pourquoi(self):
        base = self.application.base
        rdv_id = self._rendezvous(2)           # moins de 12 h : trop tard
        _, panneau = self._poster_modale("/suivi/detail/annuler",
                                         {"rdv": rdv_id, "geste": "demander"})
        self.assertIn("« annulé »", panneau)
        self.assertIn("ne proposera <strong>pas</strong>", panneau)
        _, resultat = self._poster_modale("/suivi/detail/annuler",
                                          {"rdv": rdv_id,
                                           "geste": "confirmer"})
        self.assertEqual(base.obtenir_rendezvous(rdv_id)["statut"], "annulé")
        self.assertIn("Le faire quand même à la main", resultat)
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM appels").fetchone()[0], 0)


# =========================================================================
# TESTS DE SÉCURITÉ — les quatre ruptures de gravité 1 de INTERCONNEXIONS.md
# -------------------------------------------------------------------------
# Ce sont les tests qui empêchent le produit de faire sonner un téléphone
# qui ne devait pas sonner. Ils comptent plus que les autres : si l'un
# d'eux tombe, c'est une PERSONNE qui reçoit un appel qu'elle a refusé, ou
# un rendez-vous qui apparaît là où il ne peut pas exister.
# =========================================================================


class TestSecuriteNumeroCorrige(unittest.TestCase):
    """R1 — le 🚫 n'est plus contournable par une correction de numéro.

    Le scénario prouvé par l'audit : une campagne recopiait le numéro à sa
    création et composait cette copie ; corriger le numéro du client (et
    cocher 🚫) laissait la campagne appeler l'ANCIEN numéro — donc, en mode
    réel, le téléphone de quelqu'un d'autre.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.preferences = generation.Preferences()
        self.planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=7, latence=0))
        self.campagne_id = self.base.creer_campagne(
            "Campagne d'essai", "personnalise", mission="Bonjour [client].")

    def _contact(self, nom="Mme Yvonne Lecomte", telephone="+33 6 39 98 07 51"):
        return self.base.ajouter_contact_campagne(
            self.campagne_id, 1, nom, telephone)

    def test_le_contact_porte_un_lien_vers_la_fiche_client(self):
        contact_id = self._contact()
        client_id = self.base.client_du_contact(contact_id)
        self.assertIsNotNone(client_id)     # une fiche a été créée à l'entrée
        self.assertEqual(self.base.obtenir_client(client_id)["nom"],
                         "Mme Yvonne Lecomte")

    def test_le_numero_compose_est_celui_de_la_fiche_pas_la_copie(self):
        contact_id = self._contact()
        client_id = self.base.client_du_contact(contact_id)
        self.base.modifier_client(client_id, telephone="+33 6 39 98 07 77")
        # La copie d'époque reste lisible (c'est de l'histoire)…
        contact = self.base.conn.execute(
            "SELECT telephone FROM contacts_campagne WHERE id = ?",
            (contact_id,)).fetchone()
        self.assertEqual(contact["telephone"], "+33 6 39 98 07 51")
        # …mais c'est le numéro ACTUEL qui serait composé.
        self.assertEqual(self.base.telephone_contact_campagne(contact_id),
                         "+33 6 39 98 07 77")

    def test_numero_corrige_plus_stop_le_contact_est_exclu(self):
        """LE scénario de l'audit, à la lettre."""
        contact_id = self._contact()
        client_id = self.base.client_du_contact(contact_id)
        # Le geste exact du formulaire : nouveau numéro ET 🚫, même envoi.
        self.base.modifier_client(client_id, telephone="+33 6 39 98 07 77")
        self.base.definir_ne_plus_appeler(client_id, True)
        # L'ancien garde-fou, seul, ne reconnaît toujours pas la personne :
        # c'est bien la faille prouvée, et elle est contournée autrement.
        self.assertFalse(self.base.telephone_exclu("+33 6 39 98 07 51"))
        cible = self.base.cible_appel_contact(contact_id)
        self.assertIsNone(cible["telephone"])
        self.assertEqual(cible["refus"], db.REFUS_STOP)
        # Et l'appel ne part vraiment pas.
        campagne = self.base.obtenir_campagne(self.campagne_id)
        contact = self.base.obtenir_contact_campagne(contact_id)
        compte_rendu = campagnes._appeler_contact_classique(
            self.base, self.planif, self.preferences, campagne, contact,
            tentative=0)
        self.assertEqual(compte_rendu["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertEqual(self.base.appels_du_contact_campagne(contact_id), [])
        self.assertEqual(
            self.base.obtenir_contact_campagne(contact_id)["detail"],
            db.suite_du_refus(db.REFUS_STOP)[1])

    def test_filet_de_securite_par_le_NOM_seul(self):
        """Même sans lien ni numéro commun, le NOM suffit à écarter."""
        # Contact d'une base ANCIENNE : aucun lien vers une fiche.
        contact_id = self.base.ajouter_contact_campagne(
            self.campagne_id, 2, "Mme Yvonne Lecomte", "+33 6 39 98 07 51",
            client_id=0)
        self.base.conn.execute(
            "UPDATE contacts_campagne SET client_id = NULL WHERE id = ?",
            (contact_id,))
        self.base.conn.commit()
        # Une AUTRE fiche, même personne, numéro tout différent, marquée 🚫.
        autre = self.base.ajouter_client("mme  yvonne LEFEVRE", "01 99 00 00 01")
        self.base.definir_ne_plus_appeler(autre, True)
        self.assertIsNone(self.base.cible_appel_contact(contact_id)["refus"])
        # Le nom exact (casse et accents ignorés) est reconnu.
        homonyme = self.base.ajouter_client("mme  YVONNE lecomte",
                                            "01 99 00 00 02")
        self.base.definir_ne_plus_appeler(homonyme, True)
        cible = self.base.cible_appel_contact(contact_id)
        self.assertEqual(cible["refus"], db.REFUS_STOP_NOM)
        self.assertIsNone(cible["telephone"])

    def test_cascade_collee_a_la_main_ecarte_aussi_par_le_nom(self):
        exclu = self.base.ajouter_client("M. Colle Exemple", "01 99 00 00 03")
        self.base.definir_ne_plus_appeler(exclu, True)
        cascade_id = self.planif.executer_cascade(
            [{"nom": "M. Colle Exemple", "telephone": "+33 6 39 98 07 51"}],
            "Mission [créneau].", DEMAIN)
        lignes = self.base.appels_de_cascade(cascade_id)
        self.assertEqual([l["etat"] for l in lignes], ["exclu"])
        self.assertIsNone(lignes[0]["issue"])       # jamais composé


class TestSecuriteNumeroCorrigeWeb(_TestAvecServeurWeb):
    """R1, de bout en bout : la campagne tourne pour de vrai et n'appelle pas."""

    def test_campagne_ne_compose_pas_un_numero_corrige_et_stoppe(self):
        base = self.application.base
        campagne_id = base.creer_campagne(
            "Essai R1", "personnalise", nature="personnalise",
            mission="Bonjour [client].", statut="prête",
            configuration=json.dumps({"politique": "tous", "ordre": "liste",
                                      "options": {}, "infos": {},
                                      "infos_auto": {}, "champs": []}))
        contact_id = base.ajouter_contact_campagne(
            campagne_id, 1, "Mme Yvonne Lecomte", "+33 6 39 98 07 51")
        client_id = base.client_du_contact(contact_id)
        # Le formulaire de la fiche client : nouveau numéro + 🚫, même envoi.
        self._poster("/clients/modifier",
                     {"client": client_id, "nom": "Mme Yvonne Lecomte",
                      "telephone": "+33 6 39 98 07 77", "ne_plus_appeler": "1"})
        self._demarrer(campagne_id)
        self._attendre_statut(campagne_id, "terminée")
        contact = base.obtenir_contact_campagne(contact_id)
        self.assertEqual(contact["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertEqual(base.appels_du_contact_campagne(contact_id), [])
        # ⚠ C'EST DIT À L'ÉCRAN, et aucun numéro n'y est en clair. La colonne
        # « Détail » du tableau a été retirée le 11/08/2026 (sa décision) :
        # sans ce bandeau, la personne serait une pastille 🙋 de plus, et rien
        # ne dirait qu'il y a un appel à passer soi-même.
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn("🚫 1 personne(s) ont refusé d'être appelées par un "
                      "agent", page)
        self.assertIn("attendent qu'un <strong>humain</strong> les rappelle",
                      page)
        self.assertIn('href="/relances?vue=humains"', page)
        self.assertNotIn("+33 6 39 98 07 77", page)
        self.assertNotIn("+33 6 39 98 07 51", page)


class TestSecuritePeriodeInterdite(_TestAvecServeurWeb):
    """R2 — la période interdite vaut pour les CINQ portes, sans dérogation.

    L'audit avait mesuré : 1 porte sur 5 protégée (démarrage de campagne),
    les quatre autres laissaient partir de vrais appels.
    """

    def _interdire_toute_la_journee(self):
        preferences = self.application.preferences
        preferences.definir(assistant.CLE_INTERDIT_DEBUT, "00:00")
        preferences.definir(assistant.CLE_INTERDIT_FIN, "23:59")

    def _campagne_prete(self):
        base = self.application.base
        campagne_id = base.creer_campagne(
            "Essai R2", "personnalise", nature="personnalise",
            mission="Bonjour [client].", statut="prête",
            configuration=json.dumps({"politique": "tous", "ordre": "liste",
                                      "options": {}, "infos": {},
                                      "infos_auto": {}, "champs": []}))
        base.ajouter_contact_campagne(campagne_id, 1, "M. Porte Une",
                                      "+33 6 39 98 07 51")
        return campagne_id

    def test_les_cinq_portes_refusent_pendant_la_periode_interdite(self):
        base = self.application.base
        campagne_id = self._campagne_prete()
        self._poster("/file/tout-rappeler")      # la file se remplit (n'appelle pas)
        appels_en_file = len(self.application.planif.file)
        self.assertGreater(appels_en_file, 0)
        self._interdire_toute_la_journee()
        portes = (
            ("/campagne/demarrer", {"campagne": campagne_id}),
            ("/rappeler", {"rdv": 1}),
            ("/cascade/executer", {"liste": "M. Test;+33 6 39 98 07 51",
                                   "mission": "Mission [créneau].",
                                   "creneau": DEMAIN}),
            ("/relances/executer", {}),
            ("/file/executer", {}),
        )
        for chemin, donnees in portes:
            with self.assertRaises(urllib.error.HTTPError,
                                   msg=f"{chemin} aurait dû être refusé") as ctx:
                self._poster(chemin, donnees)
            self.assertEqual(ctx.exception.code, 403, chemin)
            page = ctx.exception.read().decode("utf-8")
            self.assertIn("période interdite", page, chemin)
            self.assertIn("Réglages", page, chemin)
        # RIEN n'est parti : ni appel, ni cascade, ni campagne démarrée.
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM appels WHERE statut != 'en file'").fetchone()[0], 0)
        self.assertEqual(base.conn.execute(
            "SELECT COUNT(*) FROM appels_campagne").fetchone()[0], 0)
        self.assertEqual(base.lister_cascades(), [])
        self.assertEqual(base.obtenir_campagne(campagne_id)["statut"], "prête")
        self.assertEqual(len(self.application.planif.file), appels_en_file)

    def test_le_message_dit_l_heure_et_la_periode_reglee(self):
        self._interdire_toute_la_journee()
        with self.assertRaises(urllib.error.HTTPError) as ctx:
            self._poster("/rappeler", {"rdv": 1})
        page = ctx.exception.read().decode("utf-8")
        self.assertIn(f"il est {datetime.datetime.now():%Hh}", page)
        self.assertIn("00 h 00", page)
        self.assertIn("23 h 59", page)
        self.assertIn("même déclenché à la main", page)   # aucune dérogation

    def test_le_verrou_tient_meme_sans_passer_par_la_page(self):
        """Le geste manuel ne peut pas être « forcé » en court-circuitant
        la route : le planificateur lui-même refuse."""
        self._interdire_toute_la_journee()
        with self.assertRaises(planificateur.GardeFou) as ctx:
            self.application.planif.executer()
        self.assertIn("période interdite", str(ctx.exception))


class TestSecuriteRendezVousTelephone(unittest.TestCase):
    """R3 — une date convenue au téléphone obéit aux horaires d'ouverture.

    L'audit avait prouvé qu'un rappel automatique posait un rendez-vous sur
    un jour DÉCLARÉ FERMÉ, alors que le même déplacement fait à la main
    était refusé. Ici : rien n'est écrit, et la raison est dite.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.preferences = generation.Preferences()
        # Semaine type : du lundi au vendredi, 9h-18h.
        horaires.definir_semaine(self.preferences,
                                 {jour: [(540, 1080)] for jour in range(5)})
        # La PLAGE D'APPEL, elle, est ouverte en grand : ces tests portent sur
        # les horaires du RENDEZ-VOUS, pas sur l'heure qu'il est. Sans cette
        # ligne, ils échouaient dès qu'on les lançait le soir — un filet qui
        # ne tient qu'aux heures de bureau ne protège rien (vu à 22h28).
        self.preferences.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        self.preferences.definir(themes.CLE_PLAGE_FIN, "23:59")
        self.planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=1, latence=0),
            preferences=self.preferences)

    def _lundi_prochain(self, semaines=1):
        jour = datetime.date.today() + datetime.timedelta(days=7 * semaines)
        while jour.weekday() != 0:
            jour += datetime.timedelta(days=1)
        return jour

    def test_une_date_deja_passee_est_refusee(self):
        """⚠ TROUVÉ PAR LE BANC LE 18/08/2026, et jamais par les essais.

        La règle est pourtant écrite deux fois dans `horaires` : « Un
        rendez-vous déplacé vers hier n'est pas un rendez-vous déplacé : c'est
        un rendez-vous perdu. » Elle n'était tenue que du côté des dates
        PROPOSÉES. Du côté de ce qu'on ACCEPTE d'écrire, rien ne regardait le
        calendrier : une date convenue au téléphone un mois en arrière était
        écrite sans un mot, statut « confirmé » — puis la règle du manqué la
        repassait « manqué » au chargement suivant. Le rendez-vous disparaissait
        et personne ne pouvait dire pourquoi.
        """
        lundi = self._lundi_prochain()
        passe = (datetime.datetime.combine(lundi, datetime.time(10))
                 - datetime.timedelta(days=21)).isoformat(timespec="minutes")
        refus = horaires.refus_rendezvous_telephone(
            self.base, self.preferences, passe)
        self.assertIsNotNone(refus, "une date passée est acceptée")
        self.assertIn("DÉJÀ PASSÉ", refus)
        self.assertIn("perdu", refus)
        # ⚠ ET LA MÊME DATE, DANS LE FUTUR, PASSE : sans cette contre-épreuve,
        # un refus qui refuserait TOUT serait vert lui aussi.
        futur = datetime.datetime.combine(lundi, datetime.time(10)).isoformat(
            timespec="minutes")
        self.assertIsNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, futur))

    def test_on_refuse_le_passe_pas_aujourd_hui(self):
        """La frontière, et elle compte : ne jamais PROPOSER le jour même est
        une règle de proposition (`plancher_de_proposition`) — elle protège le
        client, qui ne peut pas s'organiser en deux heures. Refuser d'ÉCRIRE
        une date de cet après-midi dont on vient de convenir AVEC LUI au
        téléphone serait autre chose : ce serait perdre un accord réel."""
        # Un jour ouvert, une heure ouverte, mais « aujourd'hui » : on prend
        # midi d'un lundi à venir et on fait comme si c'était le jour même.
        lundi = self._lundi_prochain()
        midi = datetime.datetime.combine(lundi, datetime.time(12))
        self.assertIsNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, midi.isoformat(timespec="minutes"),
            maintenant=midi - datetime.timedelta(hours=3)))
        # Trois heures plus TARD, la même place est derrière nous : refusée.
        self.assertIsNotNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, midi.isoformat(timespec="minutes"),
            maintenant=midi + datetime.timedelta(hours=3)))

    def test_la_file_propose_une_AUTRE_date_qui_existe_vraiment(self):
        """⚠ LA MÊME RÈGLE QUE LES CAMPAGNES, qui manquait à la file (18/08).

        Quand la personne propose une AUTRE date, l'appelant doit fournir une
        seconde place réellement libre — les campagnes le font depuis le
        16/08/2026. La file d'appels, elle, ne fournissait que la première :
        l'autre date retombait alors sur la convention « rendez-vous manqué + 2
        jours », donc dans le PASSÉ pour un manqué d'il y a un mois.
        """
        vieux = (datetime.datetime.now() - datetime.timedelta(days=30)).replace(
            hour=14, minute=0, second=0, microsecond=0)
        client_id = self.base.ajouter_client("M. Report Fil",
                                             "+33 6 39 98 07 54")
        rdv_id = self.base.ajouter_rendezvous(
            client_id, vieux.isoformat(timespec="minutes"), "Séance",
            statut="manqué")
        appel_id = self.planif.programmer(rdv_id)
        self.planif.executer(seulement=appel_id)
        appel = self.base.obtenir_appel(appel_id)
        convenue = (appel["resultat"] or {}).get("new_datetime")
        self.assertEqual((appel["resultat"] or {}).get("appointment_status"),
                         "rescheduled", "l'essai ne joue pas le bon cas")
        # LA DATE CONVENUE EST DEVANT NOUS — c'est tout l'objet.
        self.assertGreater(convenue,
                           datetime.datetime.now().isoformat(timespec="minutes"),
                           "l'autre date convenue est dans le passé")
        # Et elle a été écrite : une seule ligne, à cette date.
        self.assertIsNone(appel["note"], appel["note"])
        siennes = [r for r in self.base.tous_les_rendezvous()
                   if r["nom"] == "M. Report Fil"]
        self.assertEqual([r["horaire"] for r in siennes], [convenue])
        self.assertEqual(siennes[0]["statut"], "confirmé")

    def test_jour_ferme_refuse(self):
        jour = self._lundi_prochain()
        horaires.ajouter_jour_ferme(self.preferences, jour.isoformat(),
                                    "Formation")
        refus = horaires.refus_rendezvous_telephone(
            self.base, self.preferences, f"{jour.isoformat()}T09:30")
        self.assertIsNotNone(refus)
        self.assertIn("FERMÉ", refus)
        self.assertIn("Formation", refus)

    def test_hors_horaires_refuse(self):
        jour = self._lundi_prochain()
        self.assertIsNotNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, f"{jour.isoformat()}T06:00"))
        self.assertIsNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, f"{jour.isoformat()}T09:00"))

    def test_place_deja_prise_refuse(self):
        jour = self._lundi_prochain()
        client_id = self.base.ajouter_client("M. Deja La", "+33 6 39 98 07 41")
        self.base.ajouter_rendezvous(client_id, f"{jour.isoformat()}T09:00",
                                     "Séance")
        self.assertIsNotNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, f"{jour.isoformat()}T09:00"))

    def test_duree_qui_ne_tient_pas_refuse(self):
        jour = self._lundi_prochain()
        client_id = self.base.ajouter_client("M. Bloque", "+33 6 39 98 07 41")
        self.base.ajouter_rendezvous(client_id, f"{jour.isoformat()}T09:15",
                                     "Séance")
        # 09:00 est libre, mais 09:15 est pris : deux tranches ne tiennent pas.
        self.assertIsNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, f"{jour.isoformat()}T09:00",
            tranches=1))
        refus = horaires.refus_rendezvous_telephone(
            self.base, self.preferences, f"{jour.isoformat()}T09:00",
            tranches=2)
        self.assertIsNotNone(refus)
        self.assertIn("il en manque 1", refus)

    def test_sans_semaine_type_reglee_rien_n_est_pretendu(self):
        """Honnêteté : sans horaires d'ouverture, RingBack ne sait rien —
        il ne refuse que le jour DÉCLARÉ fermé et le DOUBLE emploi."""
        preferences = generation.Preferences()
        jour = self._lundi_prochain()
        self.assertIsNone(horaires.refus_rendezvous_telephone(
            self.base, preferences, f"{jour.isoformat()}T03:00"))
        # Deux personnes à la même place, ça se voit sans connaître les horaires.
        client_id = self.base.ajouter_client("M. Deja La", "+33 6 39 98 07 41")
        self.base.ajouter_rendezvous(client_id, f"{jour.isoformat()}T03:00",
                                     "Séance")
        refus = horaires.refus_rendezvous_telephone(
            self.base, preferences, f"{jour.isoformat()}T03:00")
        self.assertIn("DÉJÀ PRISE", refus)
        horaires.ajouter_jour_ferme(preferences, jour.isoformat(), "Congé")
        self.assertIn("FERMÉ", horaires.refus_rendezvous_telephone(
            self.base, preferences, f"{jour.isoformat()}T04:00"))

    def test_une_place_choisie_a_la_main_reste_possible(self):
        """« Exceptionnellement, je peux recevoir samedi » : un créneau
        ajouté à la main dans ⚙ Réglages n'est pas jugé sur les horaires
        d'ouverture — c'est déjà une décision de l'utilisateur."""
        samedi = self._lundi_prochain() + datetime.timedelta(days=5)
        self.assertEqual(samedi.weekday(), 5)
        horaire = f"{samedi.isoformat()}T10:00"
        # Sans déclaration : samedi est fermé dans la semaine type.
        self.assertIsNotNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, horaire))
        self.preferences.definir(themes.CLE_CRENEAUX, [horaire])
        self.assertIsNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, horaire))
        # Mais deux personnes à la même place, jamais.
        client_id = self.base.ajouter_client("M. Samedi", "+33 6 39 98 07 41")
        self.base.ajouter_rendezvous(client_id, horaire, "Séance")
        self.assertIn("DÉJÀ PRISE", horaires.refus_rendezvous_telephone(
            self.base, self.preferences, horaire))

    def test_le_creneau_libere_choisi_par_l_utilisateur_n_est_pas_bloque(self):
        """Le créneau d'une campagne « créneau libéré » vient de
        l'utilisateur : hors horaires il passe, PRIS il ne passe pas."""
        samedi = self._lundi_prochain() + datetime.timedelta(days=5)
        horaire = f"{samedi.isoformat()}T10:00"
        self.assertIsNone(horaires.refus_rendezvous_telephone(
            self.base, self.preferences, horaire, place_choisie=True))
        horaires.ajouter_jour_ferme(self.preferences, samedi.isoformat(),
                                    "Congé")
        self.assertIn("FERMÉ", horaires.refus_rendezvous_telephone(
            self.base, self.preferences, horaire, place_choisie=True))

    def test_appel_sur_jour_ferme_ne_cree_aucun_rendezvous(self):
        """Le scénario de l'audit : le rappel du n°44 créait le n°45 un jour
        fermé. Ici : aucun rendez-vous, l'ancien intact, la raison écrite.

        ⚠ LA DATE FERMÉE EST DÉSORMAIS IMPOSÉE, et il le fallait (18/08/2026).
        Cet essai comptait sur le fait que la file proposait « rendez-vous + 2
        jours » — une date obtenue par formule, qui tombait par chance sur le
        jour fermé. Depuis que la file fournit une AUTRE place réellement libre
        (voir `planificateur._support_de_l_appel`), le simulateur ne propose
        plus jamais de jour fermé : l'essai passait au vert sans plus rien
        éprouver de sa règle. On lui donne donc directement la réponse que
        l'agent pourrait rendre — c'est bien elle, la question : ce que
        l'interface refuse à la main, le téléphone doit le refuser aussi.
        """
        jour = self._lundi_prochain()
        ferme = jour + datetime.timedelta(days=2)
        horaires.ajouter_jour_ferme(self.preferences, ferme.isoformat(),
                                    "Formation")
        client_id = self.base.ajouter_client("M. Ferme Test",
                                             "+33 6 39 98 07 54")
        rdv_id = self.base.ajouter_rendezvous(
            client_id, f"{jour.isoformat()}T10:00", "Séance", statut="manqué")
        avant = len(self.base.tous_les_rendezvous())
        rdv = self.base.obtenir_rendezvous(rdv_id)
        note = self.planif.appliquer_issue(rdv, {
            "appointment_status": "rescheduled",
            "new_datetime": f"{ferme.isoformat()}T10:00",
            "notes": "Le client propose ce jour-là."})
        self.assertEqual(len(self.base.tous_les_rendezvous()), avant)
        self.assertEqual(self.base.obtenir_rendezvous(rdv_id)["statut"],
                         "manqué")            # RIEN n'a bougé
        self.assertEqual(self.base.obtenir_rendezvous(rdv_id)["horaire"],
                         f"{jour.isoformat()}T10:00")
        self.assertIsNotNone(note)
        self.assertIn("FERMÉ", note)
        # La date obtenue au téléphone n'est PAS perdue : elle est en clair.
        self.assertIn(f"{ferme:%d/%m/%Y}", note)
        self.assertIn("un humain", note)

    def test_campagne_le_contact_passe_a_rappeler_par_un_humain(self):
        jour = self._lundi_prochain()
        ferme = jour + datetime.timedelta(days=2)
        horaires.ajouter_jour_ferme(self.preferences, ferme.isoformat(), "")
        client_id = self.base.ajouter_client("M. Ferme Campagne",
                                             "+33 6 39 98 07 54")
        rdv_id = self.base.ajouter_rendezvous(
            client_id, f"{jour.isoformat()}T10:00", "Séance")
        campagne_id = self.base.creer_campagne(
            "Essai R3", "confirmation", mission="Bonjour [client].")
        contact_id = self.base.ajouter_contact_campagne(
            campagne_id, 1, "M. Ferme Campagne", "+33 6 39 98 07 54",
            rendezvous_id=rdv_id)
        campagnes._appeler_contact_classique(
            self.base, self.planif, self.preferences,
            self.base.obtenir_campagne(campagne_id),
            self.base.obtenir_contact_campagne(contact_id), tentative=0)
        contact = self.base.obtenir_contact_campagne(contact_id)
        self.assertEqual(contact["etat"], "à rappeler par un humain")
        self.assertEqual(contact["issue"], planificateur.ISSUE_DATE_REFUSEE)
        self.assertIn("FERMÉ", contact["detail"])
        self.assertIn(f"{ferme:%d/%m/%Y}", contact["detail"])
        self.assertEqual(self.base.obtenir_rendezvous(rdv_id)["statut"],
                         "prévu")             # jamais « déplacé »

    def test_une_date_tenable_passe_toujours(self):
        """Le garde-fou ne bloque pas ce qui est possible : contre-épreuve."""
        jour = self._lundi_prochain()
        client_id = self.base.ajouter_client("Mme Date Tenable",
                                             "+33 6 39 98 07 54")
        rdv_id = self.base.ajouter_rendezvous(
            client_id, f"{jour.isoformat()}T10:00", "Séance", statut="manqué")
        appel_id = self.planif.programmer(rdv_id)
        self.planif.executer(seulement=appel_id)
        self.assertIsNone(self.base.obtenir_appel(appel_id)["note"])
        # La MÊME ligne, déplacée et confirmée — pas une seconde à côté.
        bouge = self.base.obtenir_rendezvous(rdv_id)
        self.assertEqual(bouge["statut"], "confirmé")
        self.assertNotEqual(bouge["horaire"], f"{jour.isoformat()}T10:00")
        self.assertEqual(len(self.base.tous_les_rendezvous()), 1)

    def test_la_duree_suit_le_deplacement_telephonique(self):
        """La place vérifiée est celle du rendez-vous ENTIER, et la ligne
        déplacée garde sa durée (sinon la vérification mentirait)."""
        jour = self._lundi_prochain()
        client_id = self.base.ajouter_client("Mme Longue", "+33 6 39 98 07 54")
        rdv_id = self.base.ajouter_rendezvous(
            client_id, f"{jour.isoformat()}T10:00", "Séance", statut="manqué",
            duree_tranches=2)
        appel_id = self.planif.programmer(rdv_id)
        self.planif.executer(seulement=appel_id)
        lignes = self.base.tous_les_rendezvous()
        self.assertEqual(len(lignes), 1)
        self.assertEqual(lignes[0]["statut"], "confirmé")
        self.assertEqual(lignes[0]["duree_tranches"], 2)


class TestSecuriteCreneauxProposesAuTelephone(unittest.TestCase):
    """R3, volet ALLER : l'agent ne reçoit que des places RÉELLEMENT libres."""

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.preferences = generation.Preferences()
        horaires.definir_semaine(self.preferences,
                                 {jour: [(540, 1080)] for jour in range(5)})

    def test_la_liste_est_recalculee_a_l_instant_de_l_appel(self):
        jour = datetime.date.today() + datetime.timedelta(days=7)
        while jour.weekday() != 0:
            jour += datetime.timedelta(days=1)
        depuis = datetime.datetime.combine(jour, datetime.time())
        liste_avant = horaires.creneaux_lisibles(
            self.base, self.preferences, depuis=depuis, limite=3)
        self.assertIn(date_parlee_de(f"{jour:%Y-%m-%d}T09:00"), liste_avant)
        # Une campagne montée AVEC cette liste, puis la place se prend.
        campagne_id = self.base.creer_campagne(
            "Essai créneaux", "confirmation",
            mission=f"Places libres : {liste_avant}.")
        contact_id = self.base.ajouter_contact_campagne(
            campagne_id, 1, "M. Ecoute", "+33 6 39 98 07 51")
        occupant = self.base.ajouter_client("Mme Occupe", "+33 6 39 98 07 41")
        self.base.ajouter_rendezvous(occupant, f"{jour.isoformat()}T09:00",
                                     "Séance")
        configuration = {"infos_auto": {"creneaux_disponibles": liste_avant}}
        mission = assistant.creneaux_adaptes_au_contact(
            self.base, self.preferences, configuration,
            self.base.obtenir_contact_campagne(contact_id),
            self.base.obtenir_campagne(campagne_id)["mission"])
        self.assertNotIn(f"{jour:%d/%m/%Y} à 09h00", mission)  # place prise
        self.assertNotIn("[créneaux_disponibles]", mission)    # rien d'inventé

    def test_un_jour_ferme_ne_se_propose_jamais(self):
        jour = datetime.date.today() + datetime.timedelta(days=7)
        while jour.weekday() != 0:
            jour += datetime.timedelta(days=1)
        horaires.ajouter_jour_ferme(self.preferences, jour.isoformat(), "Congé")
        depuis = datetime.datetime.combine(jour, datetime.time())
        liste = horaires.creneaux_lisibles(self.base, self.preferences,
                                           depuis=depuis, limite=6)
        self.assertNotIn(f"{jour:%d/%m/%Y}", liste)


class TestSecuriteSuppressionDesarme(unittest.TestCase):
    """R4 — supprimer ne laisse JAMAIS une relance armée derrière soi.

    L'audit avait ramené une relance de client supprimé à échéance et vu
    l'appel PARTIR vers un numéro gelé. Décision du propriétaire : on garde
    l'historique, on désarme.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.addCleanup(self.base.fermer)
        self.campagne_id = self.base.creer_campagne(
            "Essai R4", "personnalise", mission="Bonjour [client].")

    def _contact_avec_relance(self, nom="Mme Relance Armee",
                              telephone="+33 6 39 98 07 53"):
        contact_id = self.base.ajouter_contact_campagne(
            self.campagne_id, 1, nom, telephone)
        self.base.ajouter_appel_campagne(self.campagne_id, contact_id, 0,
                                         issue="no_answer")
        relance_id = self.base.creer_relance(
            self.campagne_id, contact_id, HIER, tentative=1,
            motif="pas de réponse")
        return contact_id, relance_id

    def test_supprimer_un_client_annule_ses_relances_et_garde_l_histoire(self):
        contact_id, relance_id = self._contact_avec_relance()
        client_id = self.base.client_du_contact(contact_id)
        self.assertEqual(self.base.desarmer_contacts_du_client(client_id), 1)
        self.base.supprimer_client(client_id)
        self.assertEqual(self.base.obtenir_relance(relance_id)["statut"],
                         "annulée")
        self.assertEqual(self.base.relances_dues(), [])
        # L'historique reste lisible : contact et appels sont toujours là.
        contact = self.base.obtenir_contact_campagne(contact_id)
        self.assertIsNotNone(contact)
        self.assertEqual(contact["nom"], "Mme Relance Armee")
        self.assertEqual(len(self.base.appels_du_contact_campagne(contact_id)), 1)

    def test_un_contact_dont_le_client_a_disparu_n_est_plus_compose(self):
        contact_id, _ = self._contact_avec_relance()
        client_id = self.base.client_du_contact(contact_id)
        self.base.supprimer_client(client_id)
        cible = self.base.cible_appel_contact(contact_id)
        self.assertIsNone(cible["telephone"])
        self.assertEqual(cible["refus"], db.REFUS_CLIENT_SUPPRIME)
        self.assertIsNone(self.base.telephone_contact_campagne(contact_id))

    def test_une_relance_reamorcee_a_la_main_ne_compose_toujours_pas(self):
        """Ceinture et bretelles : même une relance remise « planifiée »
        après coup ne fait sonner personne."""
        contact_id, relance_id = self._contact_avec_relance()
        client_id = self.base.client_du_contact(contact_id)
        self.base.supprimer_client(client_id)
        self.base.changer_relance(relance_id, statut="planifiée")
        preferences = generation.Preferences()
        planif = planificateur.Planificateur(
            self.base, calle_client.AppelSimule(graine=5, latence=0))
        comptes = campagnes.executer_relances_dues(self.base, planif,
                                                   preferences)
        self.assertEqual([c["etat"] for c in comptes], ["exclu"])
        self.assertEqual(len(self.base.appels_du_contact_campagne(contact_id)), 1)
        self.assertEqual(
            self.base.obtenir_contact_campagne(contact_id)["detail"],
            db.REFUS_CLIENT_SUPPRIME)

    def test_retirer_le_jeu_essai_desarme_aussi(self):
        client_id = self.base.ajouter_client("Mme Essai Jetable",
                                             "+33 6 39 98 07 53",
                                             jeu_essai=True)
        contact_id = self.base.ajouter_contact_campagne(
            self.campagne_id, 1, "Mme Essai Jetable", "+33 6 39 98 07 53",
            client_id=client_id)
        relance_id = self.base.creer_relance(self.campagne_id, contact_id,
                                             HIER, tentative=1, motif="essai")
        self.assertEqual(self.base.desarmer_jeu_essai(), 1)
        self.base.supprimer_jeu_essai()
        self.assertEqual(self.base.obtenir_relance(relance_id)["statut"],
                         "annulée")
        self.assertEqual(self.base.relances_dues(), [])
        self.assertEqual(
            self.base.cible_appel_contact(contact_id)["refus"],
            db.REFUS_CLIENT_SUPPRIME)

    def test_un_autre_client_n_est_pas_desarme_au_passage(self):
        contact_id, relance_id = self._contact_avec_relance()
        voisin_contact = self.base.ajouter_contact_campagne(
            self.campagne_id, 2, "M. Voisin Intact", "+33 6 39 98 07 44")
        voisine = self.base.creer_relance(self.campagne_id, voisin_contact,
                                          HIER, tentative=1, motif="voisin")
        client_id = self.base.client_du_contact(contact_id)
        self.base.supprimer_client(client_id)
        self.assertEqual(self.base.obtenir_relance(voisine)["statut"],
                         "planifiée")
        self.assertIsNotNone(
            self.base.cible_appel_contact(voisin_contact)["telephone"])


class TestSecuriteSuppressionClientWeb(_TestAvecServeurWeb):
    """R4, de bout en bout : la page le dit, et plus rien ne part."""

    def test_la_page_annonce_les_relances_desarmees(self):
        base = self.application.base
        campagne_id = base.creer_campagne("Essai R4 web", "personnalise",
                                          mission="Bonjour [client].")
        contact_id = base.ajouter_contact_campagne(
            campagne_id, 1, "Mme A Supprimer", "+33 6 39 98 07 53")
        client_id = base.client_du_contact(contact_id)
        base.creer_relance(campagne_id, contact_id, HIER, tentative=1,
                           motif="pas de réponse")
        _, page = self._poster("/clients/supprimer",
                               {"client": client_id, "confirmer": "oui"})
        self.assertIn("1 relance(s) encore programmée(s) ont été annulées",
                      page)
        self.assertIn("restent lisibles", page)
        # La page 🔁 Relances ne propose plus rien pour lui.
        _, relances = self._obtenir("/relances")
        self.assertNotIn("Mme A Supprimer", relances)
        with self.assertRaises(urllib.error.HTTPError):
            self._obtenir(f"/clients/fiche?id={client_id}")


class TestSecuriteMigrationAdditive(unittest.TestCase):
    """Les colonnes nouvelles s'ajoutent SANS perte à une base existante."""

    def test_base_existante_ouverte_sans_perte(self):
        dossier = tempfile.mkdtemp(prefix="ringback-migration-r1-")
        self.addCleanup(shutil.rmtree, dossier, ignore_errors=True)
        chemin = os.path.join(dossier, "ringback.db")
        # 1) une base écrite par la version PRÉCÉDENTE (sans client_id
        #    ni note) — on la construit avec le schéma d'avant.
        import sqlite3
        brute = sqlite3.connect(chemin)
        brute.executescript("""
            CREATE TABLE clients (id INTEGER PRIMARY KEY AUTOINCREMENT,
                nom TEXT NOT NULL, telephone TEXT NOT NULL,
                ne_plus_appeler INTEGER NOT NULL DEFAULT 0,
                jeu_essai INTEGER NOT NULL DEFAULT 0);
            CREATE TABLE rendezvous (id INTEGER PRIMARY KEY AUTOINCREMENT,
                client_id INTEGER NOT NULL, horaire TEXT NOT NULL,
                motif TEXT NOT NULL, statut TEXT NOT NULL DEFAULT 'prévu');
            CREATE TABLE appels (id INTEGER PRIMARY KEY AUTOINCREMENT,
                rendezvous_id INTEGER NOT NULL,
                statut TEXT NOT NULL DEFAULT 'en file', resultat TEXT,
                transcription TEXT,
                cree_le TEXT NOT NULL DEFAULT (datetime('now')));
            CREATE TABLE appels_cascade (id INTEGER PRIMARY KEY AUTOINCREMENT,
                cascade_id INTEGER NOT NULL, rang INTEGER NOT NULL,
                nom TEXT NOT NULL, telephone TEXT NOT NULL, etat TEXT NOT NULL,
                issue TEXT, resultat TEXT, transcription TEXT);
            CREATE TABLE campagnes (id INTEGER PRIMARY KEY AUTOINCREMENT,
                nom TEXT NOT NULL, theme TEXT NOT NULL,
                sujet TEXT NOT NULL DEFAULT '',
                mission TEXT NOT NULL DEFAULT '', creneau TEXT,
                statut TEXT NOT NULL DEFAULT 'en cours', cascade_id INTEGER,
                cree_le TEXT NOT NULL DEFAULT (datetime('now')));
            CREATE TABLE contacts_campagne (id INTEGER PRIMARY KEY AUTOINCREMENT,
                campagne_id INTEGER NOT NULL, rang INTEGER NOT NULL,
                nom TEXT NOT NULL, telephone TEXT NOT NULL,
                rendezvous_id INTEGER, etat TEXT NOT NULL DEFAULT 'à appeler',
                issue TEXT);
            INSERT INTO clients (nom, telephone) VALUES
                ('Mme Base Ancienne', '+33 6 39 98 07 41');
            INSERT INTO rendezvous (client_id, horaire, motif, statut)
                VALUES (1, '2026-01-05T10:00', 'Séance', 'manqué');
            INSERT INTO campagnes (nom, theme) VALUES ('Vieille campagne', 'manque');
            INSERT INTO contacts_campagne (campagne_id, rang, nom, telephone,
                etat) VALUES (1, 1, 'Mme Base Ancienne', '+33 6 39 98 07 41',
                'appelé');
        """)
        brute.commit()
        brute.close()
        base = db.Base(chemin)            # la migration additive se joue ici
        self.addCleanup(base.fermer)
        # 2) rien n'est perdu.
        self.assertEqual(len(base.lister_clients()), 1)
        self.assertEqual(base.lister_clients()[0]["nom"], "Mme Base Ancienne")
        contacts = base.contacts_de_campagne(1)
        self.assertEqual(len(contacts), 1)
        self.assertEqual(contacts[0]["etat"], "appelé")
        # 3) les colonnes nouvelles existent, vides — et le contact ancien
        #    (sans lien) reste composable sur sa copie d'époque.
        self.assertIsNone(contacts[0]["client_id"])
        cible = base.cible_appel_contact(contacts[0]["id"])
        self.assertEqual(cible["telephone"], "+33 6 39 98 07 41")
        self.assertIsNone(cible["refus"])
        # 4) …mais le filet de sécurité le couvre quand même.
        base.definir_ne_plus_appeler(1, True)
        self.assertEqual(base.cible_appel_contact(contacts[0]["id"])["refus"],
                         db.REFUS_STOP)


# --------------------------------------------------------------------------
# CE QUE LE BANC D'ESSAI A RÉVÉLÉ
#
# banc-essai.cmd parcourt la matrice complète (les natures créables × les
# points de départ × les issues). Les cas ci-dessous sont ceux qu'il a fait
# apparaître et qui manquaient au filet quotidien :
#   1. des natures de campagne n'étaient JAMAIS traversées de bout en bout
#      (déplacement, prise de rendez-vous) ;
#   2. le jeu d'essai ne portait les six terminaisons déterministes que parmi
#      les MANQUÉS — les autres sources de campagne n'en avaient aucune ;
#   3. deux combinaisons de bord découvertes en chemin (colonnes ⚠ vides
#      depuis une source sans rendez-vous lié ; doublon traité différemment
#      par la cascade et par la grille) ;
#   4. un DÉFAUT du produit, épinglé en attente de correction.
# --------------------------------------------------------------------------
class _CampagneAssistant(_TestAvecServeurWeb):
    """Outillage commun : monter une campagne par l'assistant, la dérouler.

    La campagne est déroulée DANS LE FIL DU TEST (assistant.executer_campagne,
    exactement le code du bouton ▶ Démarrer) plutôt que par le fil de fond :
    même moteur, mais aucune concurrence sur la connexion de la base — le
    test ne peut donc pas échouer pour une raison de minutage.
    """

    INFOS = {
        "deplacement": {
            "info_entreprise": "Cabinet Essai",
            "info_raison": "un imprévu dans notre planning",
            "info_creneaux_remplacement": "mardi 9h00, mercredi 14h30"},
        "prise_rdv": {
            "info_entreprise": "Cabinet Essai",
            "info_origine": "vous avez demandé un rendez-vous sur notre site",
            "info_creneaux_proposes": "mardi 9h00, mercredi 14h30"},
        "appel_manque": {
            "info_entreprise": "Cabinet Essai",
            "info_creneaux_proposes": "mardi 9h00, jeudi 10h00"},
        "creneau_libere": {"info_entreprise": "Cabinet Essai"},
        "rappel_rdv": {"info_entreprise": "Cabinet Essai"},
        "confirmation": {"info_entreprise": "Cabinet Essai"},
    }

    # Les informations que RingBack CALCULE lui-même (voir
    # assistant.valeur_calculee_info). Un essai qui mesure ces calculs doit
    # renvoyer ce que la page affiche, comme le navigateur — pas les valeurs
    # d'exemple de INFOS, qui les remplaceraient.
    CHAMPS_CALCULES = ("info_creneaux_remplacement",
                       "info_creneau_le_plus_proche",
                       "info_creneaux_proposes", "info_creneaux_annulation")

    def _campagne(self, nature, lignes, reprendre_les_calculs=False,
                  **options):
        _, page = self._poster("/assistant/nature", {"nature": nature})
        b = self._brouillon(page)
        formulaire = {"b": b, "action": "continuer", "ordre": "liste",
                      "opt_recontacter": "1", "opt_liberer": "1",
                      "relance_mode": "delai", "relance_delai": "4",
                      "relance_max": "3"}
        formulaire.update(self.INFOS[nature])
        if reprendre_les_calculs:
            for code in self.CHAMPS_CALCULES:
                valeur = self._valeur_affichee(page, code)
                if valeur is not None:
                    formulaire[code] = valeur
        formulaire.update(options)
        _, page = self._poster("/assistant/message", formulaire)
        self.assertIn("3. Les personnes", page)
        self._poster("/assistant/importer",
                     {"b": b, "mode": "collage", "liste": "\n".join(lignes)})
        _, page = self._poster("/assistant/liste", {"b": b, "action": "valider"})
        self.assertIn("prête", page)
        return self.application.base.lister_campagnes()[0]["id"]

    def _derouler(self, campagne_id):
        self.application.planif.client_appels = calle_client.AppelSimule(
            graine=1, latence=0)
        assistant.executer_campagne(self.application, campagne_id)
        campagne = self.application.base.obtenir_campagne(campagne_id)
        self.assertEqual(campagne["statut"], "terminée")
        return {c["nom"]: c for c in
                self.application.base.contacts_de_campagne(campagne_id)}


class TestLeGainChoisiEstToujoursPris(_TestAvecServeurWeb):
    """⚠ LE DÉFAUT LE PLUS COÛTEUX DE TOUT CE CHANTIER (14/08/2026).

    Le gain minimum — « au moins 30 jours » — n'était enregistré QUE par le
    bouton « Enregistrer la règle ». Choisi dans le sélecteur puis suivi d'un
    clic sur « Valider », il était SILENCIEUSEMENT PERDU. Et l'écran continuait
    d'afficher « au moins 30 jours », puisque c'est le navigateur qui tient
    cette valeur : rien ne pouvait le lui apprendre.

    Mesuré dans sa base : la campagne n°33 porte « jours: "" », et elle a
    appelé des gens dont le rendez-vous était le JOUR MÊME de la place. Il a
    cherché la cause quatre fois de suite, et il avait raison à chaque fois.
    """

    def _monter(self, **champs_de_regle):
        base = self.application.base
        for jour in range(7):
            horaires.basculer_periode(self.application.preferences, jour,
                                      8 * 60, 19 * 60, "ouvrir")
        self.place = (datetime.datetime.now() + datetime.timedelta(days=1)
                      ).replace(hour=9, minute=0, second=0, microsecond=0)
        for rang in range(8):
            client = base.ajouter_client(f"Mme Essai {rang}",
                                         f"06 39 98 41 {40 + rang:02d}")
            base.ajouter_rendezvous(
                client,
                (self.place + datetime.timedelta(days=5 + rang * 10)
                 ).isoformat(timespec="minutes"), "Séance", statut="prévu")
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "ordre": "anciennete",
            "info_entreprise": "Cabinet Essai", "politique": "premier_oui",
            "info_creneau_libere": self.place.isoformat(timespec="minutes")})
        formulaire = {"b": b, "ordre": "anciennete", "plafond": ""}
        formulaire.update(champs_de_regle)
        self._poster("/assistant/liste", formulaire)
        campagnes_creees = base.lister_campagnes()
        if not campagnes_creees:          # « Enregistrer la règle » ne valide pas
            return None, self.application.obtenir_brouillon_assistant(b)
        campagne = campagnes_creees[0]
        return campagne["id"], assistant.configuration_campagne(
            base.obtenir_campagne(campagne["id"]))

    def test_le_gain_choisi_puis_valide_directement_est_pris(self):
        """⚠ LE GESTE EXACT DU PROPRIÉTAIRE : il choisit la source et le gain,
        puis il clique « Valider ». Il ne repasse pas par « Enregistrer la
        règle » — rien à l'écran ne lui dit qu'il le faudrait."""
        campagne_id, config = self._monter(
            action="valider", regle_source="a_venir", regle_jours="30")
        self.assertEqual(config["regle_liste"],
                         {"source": "a_venir", "jours": "30"})
        # ⚠ ET LE RÉSULTAT, pas seulement le réglage : personne dont le
        # rendez-vous serait à moins de trente jours de la place.
        contacts = self.application.base.contacts_de_campagne(campagne_id)
        self.assertTrue(contacts)
        for contact in contacts:
            rdv = assistant.champs_contact(contact).get("rdv_existant")
            gain = (datetime.datetime.fromisoformat(rdv) - self.place).days
            with self.subTest(contact=contact["nom"]):
                self.assertGreaterEqual(gain, 30)

    def test_le_bouton_valider_emporte_la_regle_affichee(self):
        """⚠ LA VRAIE CAUSE, TROUVÉE LE 15/08/2026 APRÈS QUATRE SIGNALEMENTS.

        Le panneau de la règle était un formulaire À PART, avec son bouton
        « Enregistrer la règle ». Le bouton « ▶ Valider », lui, soumet
        `form-grille` — un AUTRE formulaire, qui ne portait donc ni la source ni
        le gain minimum. Le choix « au moins 30 jours » n'atteignait jamais le
        serveur : la campagne partait avec « jours: "" » et appelait des gens de
        la semaine suivante.

        Cet essai vérifie le HTML lui-même : les champs de la règle DOIVENT être
        rattachés à `form-grille`, sinon le défaut revient sans que rien d'autre
        ne le voie.
        """
        base = self.application.base
        for jour in range(7):
            horaires.basculer_periode(self.application.preferences, jour,
                                      8 * 60, 19 * 60, "ouvrir")
        place = (datetime.datetime.now() + datetime.timedelta(days=1)
                 ).replace(hour=9, minute=0, second=0, microsecond=0)
        for rang in range(10):
            client = base.ajouter_client(f"Mme Essai {rang}",
                                         f"06 39 98 48 {40 + rang:02d}")
            base.ajouter_rendezvous(
                client, (place + datetime.timedelta(days=2 + rang * 8)
                         ).isoformat(timespec="minutes"), "Séance",
                statut="prévu")
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "ordre": "anciennete",
            "info_entreprise": "Cabinet Essai", "politique": "premier_oui",
            "info_creneau_libere": place.isoformat(timespec="minutes")})
        _, page = self._obtenir(f"/assistant/liste?b={b}")

        # ⚠ LE CONTRÔLE DE FOND : ce que le navigateur enverra en cliquant
        # « Valider ». Un champ non rattaché ne part pas.
        attaches = set(re.findall(r'name="([a-z_]+)"[^>]*form="form-grille"',
                                  page))
        attaches |= set(re.findall(r'form="form-grille"[^>]*name="([a-z_]+)"',
                                   page))
        for champ in ("regle_source", "regle_jours", "ordre", "plafond"):
            with self.subTest(champ=champ):
                self.assertIn(champ, attaches)

        # Et le résultat : le geste réel, sans passer par « Enregistrer ».
        self._poster("/assistant/liste",
                     {"b": b, "action": "valider", "regle_source": "a_venir",
                      "regle_jours": "30", "ordre": "gain_max", "plafond": ""})
        campagne = base.lister_campagnes()[0]
        config = assistant.configuration_campagne(
            base.obtenir_campagne(campagne["id"]))
        self.assertEqual(config["regle_liste"],
                         {"source": "a_venir", "jours": "30"})
        contacts = base.contacts_de_campagne(campagne["id"])
        self.assertTrue(contacts)
        for contact in contacts:
            rdv = assistant.champs_contact(contact)["rdv_existant"]
            gain = (datetime.datetime.fromisoformat(rdv) - place).days
            with self.subTest(contact=contact["nom"]):
                self.assertGreaterEqual(gain, 30)

    def test_le_chargement_manuel_applique_le_gain(self):
        """⚠ LE CHEMIN QU'IL A RÉELLEMENT EMPRUNTÉ (14/08/2026). Le champ « au
        moins N jours » vivait dans le formulaire « Enregistrer la règle », en
        mode automatique. Le chargement manuel — « Ajouter ces personnes à la
        grille », depuis les rendez-vous — ne le portait pas et n'appliquait
        donc AUCUN gain : il a chargé 328 personnes, dont certaines gagnaient
        zéro jour, et ses rendez-vous ont avancé de deux jours au lieu de
        trente. Deux panneaux, deux formulaires, un seul écran.
        """
        base = self.application.base
        for jour in range(7):
            horaires.basculer_periode(self.application.preferences, jour,
                                      8 * 60, 19 * 60, "ouvrir")
        place = (datetime.datetime.now() + datetime.timedelta(days=1)
                 ).replace(hour=9, minute=0, second=0, microsecond=0)
        for rang in range(10):
            client = base.ajouter_client(f"Mme Essai {rang}",
                                         f"06 39 98 46 {40 + rang:02d}")
            base.ajouter_rendezvous(
                client, (place + datetime.timedelta(days=2 + rang * 8)
                         ).isoformat(timespec="minutes"), "Séance",
                statut="prévu")
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        b = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "ordre": "anciennete",
            "info_entreprise": "Cabinet Essai", "politique": "premier_oui",
            "info_creneau_libere": place.isoformat(timespec="minutes")})
        # Le champ EXISTE dans ce formulaire-là, et pas seulement dans l'autre.
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        self.assertIn("Gain minimum", page)
        # Le geste : charger depuis les rendez-vous à venir, gain 30 jours.
        self._poster("/assistant/importer",
                     {"b": b, "mode": "rendezvous", "source": "a_venir",
                      "regle_jours": "30"})
        brouillon = self.application.obtenir_brouillon_assistant(b)
        self.assertTrue(brouillon["contacts"])
        for contact in brouillon["contacts"]:
            rdv = contact["champs"]["rdv_existant"]
            gain = (datetime.datetime.fromisoformat(rdv) - place).days
            with self.subTest(contact=contact["nom"]):
                self.assertGreaterEqual(gain, 30)
        # Et l'écran DIT ce qui a été appliqué.
        self.assertIn("gain minimum : 30 jours", brouillon.get("message") or "")

    def test_le_bouton_enregistrer_la_regle_marche_toujours(self):
        """L'autre chemin ne change pas d'un caractère."""
        _, config = self._monter(action="regle", regle_source="a_venir",
                                 regle_jours="90")
        self.assertEqual(config.get("regle_liste") or {},
                         {"source": "a_venir", "jours": "90"})

    def test_sans_gain_choisi_la_regle_reste_ouverte(self):
        """« Peu importe » est un choix légitime : il ne devient pas 30."""
        campagne_id, config = self._monter(
            action="valider", regle_source="a_venir", regle_jours="")
        self.assertEqual(config["regle_liste"],
                         {"source": "a_venir", "jours": ""})
        self.assertGreater(
            len(self.application.base.contacts_de_campagne(campagne_id)), 5)


class TestLePlafondEstUnBudgetDAppels(unittest.TestCase):
    """⚠ SON SCÉNARIO DU 15/08/2026, mot pour mot :

    « 30 appels autorisés, on en consomme 8 pour occuper le créneau, on ajoute
    le nouveau créneau libéré à cause du décalage, on continue à traiter pour
    placer tous les créneaux libres initiaux puis quand on est sur un créneau
    en cascade, alors on recharge la liste des contacts. Donc si on en a
    consommé 8 appels, qu'on en a autorisé 30, cela laisse 22 appels, on
    cherche les 22 contacts sur la base du créneau en cascade et des options
    automatiques sélectionnées, on ajoute les contacts, on les appelle. »

    CE QUI SE PASSAIT, mesuré sur exactement ce scénario : le plafond comptait
    les contacts PRÉSENTS dans la liste, pas les appels passés. La règle en
    charge trente au départ, donc le plafond était atteint dès le premier tour
    et plus PERSONNE n'entrait jamais. Résultat : SIX appels sur trente
    autorisés, et trois places de cascade laissées « à pourvoir », faute de
    quelqu'un à appeler — alors que l'écran affichait « 77 personne(s)
    écartée(s) : cette campagne est réglée au maximum sur 30 personne(s) ».

    Il l'a signalé trois jours de suite. La cascade S'OUVRAIT bien — c'est
    pour cela que je ne trouvais rien en la regardant — mais elle ne pouvait
    plus être SERVIE.
    """

    PLAFOND = 30

    def _monter(self, monde):
        base = db.Base(":memory:")
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        demain = (datetime.datetime.now() + datetime.timedelta(days=1)
                  ).replace(hour=9, minute=0, second=0, microsecond=0)
        places = [(demain + datetime.timedelta(hours=h)).isoformat(
            timespec="minutes") for h in (0, 2, 4)]
        for rang in range(monde):
            client = base.ajouter_client(
                f"Mme Essai {rang:03d}",
                "06 39 %02d %02d 10" % (10 + rang // 90, 10 + rang % 90))
            base.ajouter_rendezvous(
                client, (demain + datetime.timedelta(days=5 + rang * 2)
                         ).isoformat(timespec="minutes"), "Séance",
                statut="prévu")

        class ToujoursOui(calle_client.ClientAppels):
            class _Issue:
                def __init__(self, resultat):
                    self.resultat = resultat
                    self.transcription = ""
                    self.identifiant = "appel-essai-1"

                def __getattr__(self, nom):
                    return None

            def appeler_cascade(self, nom, telephone, mission, creneau,
                                consigne=None, nature=None):
                return self._Issue({"outcome": "accepted",
                                    "new_datetime": None, "notes": ""})

        class Appli:
            def __init__(self):
                self.base, self.preferences = base, prefs
                self.executions, self.mode_reel = {}, False
                self.planif = planificateur.Planificateur(
                    base, ToujoursOui(), preferences=prefs)

            def commande_execution(self, identifiant):
                return None

            def terminer_execution(self, identifiant):
                pass

        campagne = assistant.creer_campagne_prete(base, {
            "nature": "creneau_libere",
            "infos": {"creneau_libere": places[0], "entreprise": "Essai"},
            "infos_auto": {}, "politique": "premier_oui", "ordre": "liste",
            "options": {"liberer_creneau": True, "cascade": True,
                        "cascade_jusqu_au": (
                            demain + datetime.timedelta(days=400)
                        ).date().isoformat()},
            "champs": [dict(c) for c
                       in assistant.NATURES["creneau_libere"]["champs"]],
            "mission": "Bonjour.",
            "recette": {"apports": [], "a_la_main": False,
                        "mission_editee": False},
            "mode_liste": "automatique",
            "regle_liste": {"source": "a_venir", "jours": "30"},
            "plafond": str(self.PLAFOND),
            "creneaux": assistant.normaliser_creneaux(places),
            "contacts": []}, prefs)
        assistant.executer_campagne(Appli(), campagne)
        fiche = base.obtenir_campagne(campagne)
        config = assistant.configuration_campagne(fiche)
        return base, campagne, places, assistant.creneaux_de(fiche, config)

    def test_la_cascade_recharge_des_contacts_et_pourvoit_ses_places(self):
        """⚠ LE CŒUR : les places nées de la cascade sont VRAIMENT pourvues.

        Avant, elles naissaient et restaient « à pourvoir » : la liste ne se
        rechargeait jamais. C'est ce qu'il voyait à l'écran.
        """
        base, campagne, initiales, places = self._monter(600)
        cascade = [f for f in places if f["horaire"] not in initiales]
        self.assertTrue(cascade, "la cascade doit ouvrir des places")
        pourvues = [f for f in cascade
                    if f["statut"] == assistant.CRENEAU_POURVU]
        # ⚠ PAS « TOUTES » : les dernières places naissent du DERNIER appel, et
        # il ne reste alors plus de budget pour les servir. C'est juste — mais
        # « avant, ZÉRO place de cascade était pourvue » est ce qui compte, et
        # une assertion trop gourmande aurait fait passer le produit pour
        # fautif là où il fait exactement ce qu'il doit.
        self.assertGreaterEqual(len(pourvues), 20,
                                [(f["horaire"], f["statut"])
                                 for f in cascade])
        # Ce qui reste à pourvoir n'est toléré que budget épuisé.
        if len(pourvues) < len(cascade):
            self.assertEqual(base.compter_personnes_appelees(campagne),
                             self.PLAFOND,
                             "une place de cascade ne reste sans preneur que "
                             "si le plafond d'appels est atteint")
        # Et la liste a bien GROSSI : des contacts sont entrés en cours de
        # route, ce que la règle seule du départ n'aurait pas pu donner.
        self.assertGreater(len(base.contacts_de_campagne(campagne)),
                           self.PLAFOND)

    def test_le_plafond_borne_les_APPELS_et_jamais_davantage(self):
        """⚠ LE GARDE-FOU JUMEAU, sans lequel le correctif serait pire que le
        défaut. Puisque la liste peut désormais grossir, ce n'est plus sa
        taille qui borne les appels : c'est la boucle qui doit compter.
        Trente autorisés veut dire trente composés, jamais trente-et-un.
        """
        base, campagne, _, _ = self._monter(600)
        appelees = base.compter_personnes_appelees(campagne)
        self.assertEqual(appelees, self.PLAFOND)

    def test_le_budget_restant_sert_vraiment(self):
        """Le budget non consommé doit finir en appels, pas dormir.

        Avant : six appels sur trente. C'est le chiffre qu'il citait.
        """
        base, campagne, _, _ = self._monter(600)
        self.assertGreaterEqual(base.compter_personnes_appelees(campagne), 20,
                                "le budget d'appels doit être réellement "
                                "employé, pas laissé dormir")

    def test_sans_assez_de_monde_la_campagne_le_dit_au_lieu_de_forcer(self):
        """⚠ ET ELLE N'INVENTE PERSONNE. Quand la base ne contient pas assez de
        gens que la place intéresse, la campagne s'arrête sous son plafond —
        et l'écran dit pourquoi, au lieu de laisser croire à un défaut."""
        base, campagne, _, _ = self._monter(120)
        appelees = base.compter_personnes_appelees(campagne)
        self.assertLess(appelees, self.PLAFOND)
        config = assistant.configuration_campagne(
            base.obtenir_campagne(campagne))
        notes = " ".join((config.get("regle_jouee") or {}).get("notes") or [])
        self.assertIn("n'en a pas trouvé plus", notes)

    def test_la_place_restee_vide_dit_elle_meme_pourquoi(self):
        """⚠ SON SIGNALEMENT DU SOIR DU 15/08/2026 : « la cascade s'arrête à la
        deuxième occurrence ; normalement cela doit continuer jusqu'à la date
        limite ».

        La mécanique était juste — mesuré dans sa base : la chaîne mourait sur
        la place du 06/11 parce qu'il aurait fallu un rendez-vous au 06/12 ou
        après, et que ses rendez-vous s'arrêtaient au 23/11. Le défaut, c'était
        le SILENCE : la place restait « à pourvoir » sans un mot, et la seule
        explication vivait dans une note interne. Devant un arrêt muet, on
        conclut que le produit est cassé — et on a raison de le croire.

        La place doit donc porter, écrite sur elle : la date qu'il aurait fallu,
        le gain demandé, et le fait que la date limite N'EST PAS en cause.
        """
        base, campagne, _, places = self._monter(120)
        restantes = [f for f in places
                     if f["statut"] == assistant.CRENEAU_A_POURVOIR]
        self.assertTrue(restantes, "ce montage doit laisser une place vide")
        pourquoi = restantes[0].get("pourquoi") or ""
        self.assertIn("personne n'a de rendez-vous", pourquoi)
        self.assertIn("30 jours demandés", pourquoi)
        # ⚠ ET IL FAUT LE DIRE : ce n'est PAS la date limite qui arrête.
        self.assertIn("ce n'est pas elle qui l'arrête", pourquoi)

    def test_le_plafond_atteint_se_dit_sur_la_place_aussi(self):
        """L'autre cause d'arrêt, et elle ne doit pas être confondue avec la
        précédente : ici il reste du monde, mais plus de budget."""
        base, campagne, _, places = self._monter(600)
        self.assertEqual(base.compter_personnes_appelees(campagne),
                         self.PLAFOND)
        restantes = [f for f in places
                     if f["statut"] == assistant.CRENEAU_A_POURVOIR]
        self.assertTrue(restantes)
        pourquoi = restantes[0].get("pourquoi") or ""
        self.assertIn(f"maximum de {self.PLAFOND} appel(s)", pourquoi)


class TestLeGainSuitLaPlaceEnCascade(unittest.TestCase):
    """⚠ SON CONSTAT DU 15/08/2026, mot pour mot : « le rendez-vous +30 jours
    pour le 15/08 cherche des contacts à partir du 15/09, et le créneau du
    15/09 devrait chercher à partir d'une date de rendez-vous au 15/10 ».

    C'était juste, et ce n'était pas fait. La règle chargeait la liste au seuil
    de la PREMIÈRE place ; ensuite, à chaque place gagnée par la cascade, le
    filtre d'appel ne demandait plus que « cette place est-elle plus tôt que son
    rendez-vous ». Quelqu'un retenu pour un gain de 35 jours sur la première
    place se voyait donc proposer, une fois la campagne avancée, une place qui
    ne lui en faisait plus gagner que deux.
    """

    def _derouler(self, gain):
        base = db.Base(":memory:")
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        self.place = (datetime.datetime.now() + datetime.timedelta(days=1)
                      ).replace(hour=9, minute=0, second=0, microsecond=0)
        # Vingt personnes, une tous les dix jours : +5, +15, +25 … +195.
        for rang in range(20):
            client = base.ajouter_client(f"Mme Essai {rang:02d}",
                                         f"06 39 98 61 {10 + rang:02d}")
            base.ajouter_rendezvous(
                client,
                (self.place + datetime.timedelta(days=5 + rang * 10)
                 ).isoformat(timespec="minutes"), "Séance", statut="prévu")
        campagne = assistant.creer_campagne_prete(base, {
            "nature": "creneau_libere",
            "infos": {"creneau_libere": self.place.isoformat(
                timespec="minutes"), "entreprise": "Essai"},
            "infos_auto": {}, "politique": "premier_oui", "ordre": "liste",
            "mode_liste": "automatique",
            "options": {"liberer_creneau": True, "cascade": True,
                        "cascade_jusqu_au": (
                            self.place + datetime.timedelta(days=400)
                        ).date().isoformat()},
            "champs": [dict(c)
                       for c in assistant.NATURES["creneau_libere"]["champs"]],
            "mission": "Bonjour, une place s'est libérée.",
            "recette": {"apports": [{"mode": "base", "source": "a_venir"}],
                        "a_la_main": False, "mission_editee": False},
            "regle_liste": {"source": "a_venir", "jours": str(gain)},
            "creneaux": assistant.normaliser_creneaux([
                self.place.isoformat(timespec="minutes"),
                (self.place + datetime.timedelta(minutes=30)).isoformat(
                    timespec="minutes")]),
            "contacts": []}, prefs)

        class ToujoursOui(calle_client.ClientAppels):
            class _Issue:
                def __init__(self, resultat):
                    self.resultat = resultat
                    self.transcription = ""
                    self.identifiant = "appel-essai-1"

                def __getattr__(self, nom):
                    return None

            def appeler_cascade(self, nom, telephone, mission, creneau,
                                consigne=None, nature=None):
                return self._Issue({"outcome": "accepted",
                                    "new_datetime": None, "notes": ""})

        class Appli:
            def __init__(self):
                self.base, self.preferences = base, prefs
                self.executions, self.mode_reel = {}, False
                self.planif = planificateur.Planificateur(
                    base, ToujoursOui(), preferences=prefs)

            def commande_execution(self, identifiant):
                return None

            def terminer_execution(self, identifiant):
                pass

        assistant.executer_campagne(Appli(), campagne)
        return base, campagne

    def test_chaque_place_gagnee_impose_le_meme_gain(self):
        """⚠ LE CŒUR : personne ne doit être déplacé pour moins que le gain
        demandé, à AUCUNE des places — ni la première, ni celles que la cascade
        ajoute en cours de route."""
        base, campagne = self._derouler(gain=30)
        deplacements = [c for c in base.changements_de_campagne(campagne)
                        if c["genre"] == "deplacement"]
        self.assertTrue(deplacements, "la campagne doit avoir déplacé du monde")
        for ligne in deplacements:
            ancienne = datetime.datetime.fromisoformat(ligne["ancienne_date"])
            nouvelle = datetime.datetime.fromisoformat(ligne["nouvelle_date"])
            with self.subTest(qui=ligne["nom"]):
                self.assertGreaterEqual((ancienne - nouvelle).days, 30)

    def test_une_campagne_automatique_enchaine_bien_la_cascade(self):
        """⚠ LE DÉFAUT QUI ARRÊTAIT LA CHAÎNE NET (15/08/2026). La « recette »
        ne retient que les chargements MANUELS ; en mode automatique, c'est la
        règle qui remplit la campagne, et personne n'y notait d'apport. La
        recette restait vide, et la cascade refusait de préparer la suite en
        accusant l'opérateur d'avoir « choisi la liste à la main » — alors que
        son critère était écrit sur la campagne.

        Constaté sur sa campagne n°5 : règle « à venir, au moins 30 jours »,
        recette vide, chaîne arrêtée au premier oui.
        """
        base = db.Base(":memory:")
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        place = (datetime.datetime.now() + datetime.timedelta(days=1)
                 ).replace(hour=9, minute=0, second=0, microsecond=0)
        for rang in range(20):
            client = base.ajouter_client(f"Mme Essai {rang:02d}",
                                         f"06 39 98 63 {10 + rang:02d}")
            base.ajouter_rendezvous(
                client, (place + datetime.timedelta(days=5 + rang * 10)
                         ).isoformat(timespec="minutes"), "Séance",
                statut="prévu")
        campagne = assistant.creer_campagne_prete(base, {
            "nature": "creneau_libere",
            "infos": {"creneau_libere": place.isoformat(timespec="minutes"),
                      "entreprise": "Essai"},
            "infos_auto": {}, "politique": "premier_oui",
            "ordre": "anciennete", "mode_liste": "automatique",
            "options": {"liberer_creneau": True, "cascade": True,
                        "cascade_jusqu_au": (
                            place + datetime.timedelta(days=400)
                        ).date().isoformat()},
            "champs": [dict(c)
                       for c in assistant.NATURES["creneau_libere"]["champs"]],
            "mission": "Bonjour.",
            # ⚠ RECETTE VIDE, comme la sienne : c'est la règle qui a tout fait.
            "recette": {"apports": [], "a_la_main": False,
                        "mission_editee": False},
            "regle_liste": {"source": "a_venir", "jours": "30"},
            "creneaux": assistant.normaliser_creneaux(
                [place.isoformat(timespec="minutes")]),
            "contacts": []}, prefs)

        class ToujoursOui(calle_client.ClientAppels):
            class _Issue:
                def __init__(self, resultat):
                    self.resultat = resultat
                    self.transcription = ""
                    self.identifiant = "appel-essai-1"

                def __getattr__(self, nom):
                    return None

            def appeler_cascade(self, nom, telephone, mission, creneau,
                                consigne=None, nature=None):
                return self._Issue({"outcome": "accepted",
                                    "new_datetime": None, "notes": ""})

        class Appli:
            def __init__(self):
                self.base, self.preferences = base, prefs
                self.executions, self.mode_reel = {}, False
                self.planif = planificateur.Planificateur(
                    base, ToujoursOui(), preferences=prefs)

            def commande_execution(self, identifiant):
                return None

            def terminer_execution(self, identifiant):
                pass

        assistant.executer_campagne(Appli(), campagne)

        # ⚠ LE CŒUR : la chaîne continue — DANS LA CAMPAGNE (15/08/2026, second
        # correctif du jour). Elle préparait jusque-là une campagne « prête » à
        # côté, qu'il fallait lancer à la main : de son poste, la campagne
        # s'arrêtait, et c'est ce qu'il appelait « la cascade ne marche pas ».
        self.assertEqual([c["id"] for c in base.lister_campagnes()],
                         [campagne],
                         "aucune campagne « prête » ne doit être semée à côté")
        fiche = base.obtenir_campagne(campagne)
        config = assistant.configuration_campagne(fiche)
        places = assistant.creneaux_de(fiche, config)
        # ⚠ LA PLACE D'ORIGINE EST `place`, CELLE QUE CET ESSAI A POSÉE. Il
        # lisait auparavant `config["infos"]["creneau_libere"]` — pratique,
        # mais faux depuis le 01/09/2026 : cette information suit désormais la
        # place EN COURS, comme la colonne `campagnes.creneau`. Les deux
        # divergeaient, et la consigne annonçait deux dates pour une seule
        # place (le 422 de CALL-E). Un essai ne doit pas dépendre d'un champ
        # dont le sens est « là où la campagne en est » pour dire « là où
        # elle a commencé ».
        nees = [f for f in places
                if datetime.datetime.fromisoformat(f["horaire"]) > place]
        self.assertTrue(nees, "la place quittée devait rejoindre la campagne")
        # La règle est toujours celle d'origine : elle se rejouera à son tour.
        self.assertEqual(config["regle_liste"],
                         {"source": "a_venir", "jours": "30"})
        # ⚠ ET LE SEUIL SUIT LA PLACE : chaque personne appelée POUR une place
        # née du décalage a un rendez-vous au moins trente jours après ELLE.
        # C'est sa demande du 15/08 : « le créneau du 15/09 cherche des
        # contacts à partir d'une date de rendez-vous au 15/10 ».
        pourvues = [f for f in nees
                    if f["statut"] == assistant.CRENEAU_POURVU
                    and f.get("contact_id")]
        self.assertTrue(pourvues, [(f["horaire"], f["statut"]) for f in nees])
        for fiche_place in pourvues:
            contact = base.obtenir_contact_campagne(fiche_place["contact_id"])
            ligne = [c for c in base.changements_de_campagne(campagne)
                     if c.get("nouvelle_date") == fiche_place["horaire"]]
            with self.subTest(place=fiche_place["horaire"]):
                self.assertTrue(ligne, "un déplacement doit être écrit")
                gain = (datetime.datetime.fromisoformat(ligne[0]["ancienne_date"])
                        - datetime.datetime.fromisoformat(
                            fiche_place["horaire"])).days
                self.assertGreaterEqual(gain, 30, contact["nom"])

    def test_sans_gain_demande_le_comportement_ne_change_pas(self):
        """« Peu importe » reste « peu importe » : toute place plus tôt que son
        rendez-vous vaut la peine d'être proposée."""
        base, campagne = self._derouler(gain="")
        deplacements = [c for c in base.changements_de_campagne(campagne)
                        if c["genre"] == "deplacement"]
        self.assertTrue(deplacements)
        gains = [(datetime.datetime.fromisoformat(l["ancienne_date"])
                  - datetime.datetime.fromisoformat(l["nouvelle_date"])).days
                 for l in deplacements]
        self.assertTrue(any(g < 30 for g in gains),
                        "sans seuil, les petits gains restent permis")


class TestUnDeplacementEstUneSeuleLigne(unittest.TestCase):
    """⚠ SA DEMANDE DU 14/08/2026, mot pour mot : « tu déplaces un rendez-vous
    d'une date à une autre en fonction des options sélectionnées. C'est ultra
    simple. » Et son constat : « l'ancien rendez-vous n'est pas supprimé ».

    Il avait raison, et il l'avait devant les yeux. Un OUI sur un créneau
    libéré créait une SECONDE ligne d'agenda à la nouvelle date, et marquait
    l'ancienne « déplacé » — celle-ci restait donc dans son agenda. Deux lignes
    pour un seul déplacement, dont une qui n'était jamais retirée. Mesuré dans
    sa base : rendez-vous n°1801 du 17/08 à 13h40 « déplacé », toujours là, à
    côté du n°2154 créé le 15/08 à 09h00.

    La règle tenue ici : UNE ligne, qui change de date et passe CONFIRMÉE.
    L'histoire ne se perd pas — le cahier des changements porte la ligne ↔ avec
    ses deux dates, et c'est lui le livrable de la campagne.
    """

    def _campagne(self, avec_rendezvous=True):
        base = db.Base(":memory:")
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        self.place = (datetime.datetime.now() + datetime.timedelta(days=2)
                      ).replace(hour=9, minute=0, second=0, microsecond=0
                                ).isoformat(timespec="minutes")
        client = base.ajouter_client("Mme Bouge Ici", "06 39 98 30 41")
        contact = {"nom": "Mme Bouge Ici", "telephone": "06 39 98 30 41",
                   "champs": {"motif": "Séance"}}
        self.ancienne = None
        if avec_rendezvous:
            self.ancienne = (datetime.datetime.fromisoformat(self.place)
                             + datetime.timedelta(days=20)).isoformat(
                                 timespec="minutes")
            rdv = base.ajouter_rendezvous(client, self.ancienne, "Séance",
                                          statut="prévu")
            contact["rendezvous_id"] = rdv
            contact["champs"]["rdv_existant"] = self.ancienne
            self.rdv_id = rdv
        campagne = assistant.creer_campagne_prete(base, {
            "nature": "creneau_libere",
            "infos": {"creneau_libere": self.place, "entreprise": "Essai"},
            "infos_auto": {}, "politique": "premier_oui", "ordre": "liste",
            "options": {"liberer_creneau": True},
            "champs": [dict(c)
                       for c in assistant.NATURES["creneau_libere"]["champs"]],
            "mission": "Bonjour.",
            "recette": {"apports": [], "a_la_main": False},
            "creneaux": assistant.normaliser_creneaux([self.place]),
            "contacts": [contact]}, prefs)

        class ToujoursOui(calle_client.ClientAppels):
            class _Issue:
                def __init__(self, resultat):
                    self.resultat = resultat
                    self.transcription = ""
                    self.identifiant = "appel-essai-1"

                def __getattr__(self, nom):
                    return None

            def appeler_cascade(self, nom, telephone, mission, creneau,
                                consigne=None, nature=None):
                return self._Issue({"outcome": "accepted",
                                    "new_datetime": None, "notes": ""})

        class Appli:
            def __init__(self):
                self.base, self.preferences = base, prefs
                self.executions, self.mode_reel = {}, False
                self.planif = planificateur.Planificateur(
                    base, ToujoursOui(), preferences=prefs)

            def commande_execution(self, identifiant):
                return None

            def terminer_execution(self, identifiant):
                pass

        assistant.executer_campagne(Appli(), campagne)
        return base, campagne

    def test_le_rendezvous_bouge_et_passe_confirme(self):
        base, campagne = self._campagne()
        lignes = base.conn.execute(
            "SELECT id, horaire, statut FROM rendezvous").fetchall()
        # ⚠ LE CŒUR : UNE seule ligne, et c'est la MÊME qu'avant.
        self.assertEqual(len(lignes), 1, [dict(r) for r in lignes])
        self.assertEqual(lignes[0]["id"], self.rdv_id)
        self.assertEqual(lignes[0]["horaire"], self.place)
        self.assertEqual(lignes[0]["statut"], "confirmé")
        # Plus aucun rendez-vous « déplacé » ne traîne dans l'agenda.
        self.assertNotIn("déplacé", [r["statut"] for r in lignes])
        # Et sa place d'avant est réellement libre.
        occupants = [r for r in base.tous_les_rendezvous()
                     if r["horaire"] == self.ancienne
                     and r["statut"] in horaires.STATUTS_OCCUPANTS]
        self.assertEqual(occupants, [])

    def test_le_cahier_porte_un_seul_geste_avec_ses_deux_dates(self):
        base, campagne = self._campagne()
        changements = base.changements_de_campagne(campagne)
        self.assertEqual([c["genre"] for c in changements], ["deplacement"])
        self.assertEqual(changements[0]["ancienne_date"], self.ancienne)
        self.assertEqual(changements[0]["nouvelle_date"], self.place)

    def test_sans_rendezvous_a_bouger_on_en_cree_bien_un(self):
        """Les gens qui ATTENDENT une place n'ont rien à déplacer : pour eux,
        un rendez-vous est créé, et le cahier écrit un ajout."""
        base, campagne = self._campagne(avec_rendezvous=False)
        lignes = base.conn.execute(
            "SELECT horaire, statut FROM rendezvous").fetchall()
        self.assertEqual(len(lignes), 1)
        self.assertEqual(lignes[0]["horaire"], self.place)
        self.assertEqual(lignes[0]["statut"], "confirmé")
        self.assertEqual([c["genre"]
                          for c in base.changements_de_campagne(campagne)],
                         ["ajout"])


class TestEcransSuivantLaNature(_TestAvecServeurWeb):
    """⚠ AUDIT CROISÉ DU 14/08/2026 — ce que l'écran offre, dit, ou tait.

    Sept écarts confirmés, tous de la même famille : une option proposée à une
    nature qui n'en fait rien, un mot pour deux choses, une pause sans raison.
    """

    def _brouillon(self, nature):
        _, page = self._poster("/assistant/nature", {"nature": nature})
        return re.search(r'name="b" value="(\d+)"', page).group(1)

    def test_l_option_cascade_n_est_offerte_qu_ou_elle_agit(self):
        """⚠ L'ÉCART : la case était proposée aux CINQ natures. Elle ne commande
        pourtant qu'une chose — ce que devient la place qu'un contact QUITTE —
        et trois natures n'en libèrent aucune. Cochée ou non, rien ne changeait
        : une case inerte est un mensonge d'interface."""
        for nature in ("creneau_libere", "deplacement"):
            with self.subTest(nature=nature):
                b = self._brouillon(nature)
                _, page = self._obtenir(f"/assistant/message?b={b}")
                self.assertIn('name="opt_cascade"', page)
        for nature in ("rappel_rdv", "confirmation", "prise_rdv"):
            with self.subTest(nature=nature):
                b = self._brouillon(nature)
                _, page = self._obtenir(f"/assistant/message?b={b}")
                self.assertNotIn('name="opt_cascade"', page)
                self.assertNotIn("Décaler en cascade", page)

    def test_l_ordre_par_date_n_est_offert_qu_avec_une_date(self):
        """⚠ L'ÉCART : les deux ordres trient sur le rendez-vous du contact. Une
        prise de rendez-vous n'en porte pas : les proposer laissait l'ordre
        inchangé, et la fiche annonçait ensuite un ordre jamais appliqué."""
        self.assertTrue(assistant.nature_porte_un_rendezvous("creneau_libere"))
        self.assertTrue(assistant.nature_porte_un_rendezvous("deplacement"))
        self.assertFalse(assistant.nature_porte_un_rendezvous("prise_rdv"))
        b = self._brouillon("prise_rdv")
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "ordre": "liste",
            "info_entreprise": "Cabinet Essai",
            "info_origine": "vous avez demandé un rendez-vous",
            "info_creneaux_proposes": "lundi 10h"})
        _, page = self._obtenir(f"/assistant/liste?b={b}")
        self.assertNotIn("le plus LOINTAIN d'abord", page)
        self.assertNotIn("le plus PROCHE d'abord", page)

    def test_une_pause_par_l_heure_dit_pourquoi(self):
        """⚠ L'ÉCART : une campagne démarrée à 18 h 55 s'arrêtait à 19 h au
        milieu de sa liste, statut « en pause » et RIEN d'autre. L'opérateur ne
        l'apprenait qu'en recliquant sur ▶ Reprendre."""
        base = self.application.base
        campagne_id = base.creer_campagne("Essai pause", "creneau_libere",
                                          nature="creneau_libere",
                                          mission="Bonjour.")
        base.ajouter_contact_campagne(campagne_id, 1, "Mme Une",
                                      "06 39 98 23 41")
        base.ajouter_contact_campagne(campagne_id, 2, "Mme Deux",
                                      "06 39 98 23 42")
        # Une plage d'appel FERMÉE : la boucle s'arrête entre deux appels.
        heure = datetime.datetime.now().hour
        debut, fin = ("22:00", "23:00") if heure < 12 else ("01:00", "02:00")
        self.application.preferences.definir(serveur.themes.CLE_PLAGE_DEBUT,
                                             debut)
        self.application.preferences.definir(serveur.themes.CLE_PLAGE_FIN, fin)
        assistant.executer_campagne(self.application, campagne_id)

        campagne = base.obtenir_campagne(campagne_id)
        self.assertEqual(campagne["statut"], "en pause")
        # ⚠ LE CŒUR : la raison est écrite, et lisible sur la fiche.
        self.assertIn("hors de la plage", campagne["raison_pause"] or "")
        _, fiche = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn("mise en pause toute seule", fiche)
        self.assertIn("plage d&#x27;appel", fiche)

    def test_le_bandeau_explique_les_non_appeles_meme_sans_deplacement(self):
        """⚠ L'ÉCART : la phrase ne s'écrivait que s'il existait une ligne ↔ au
        cahier. Une campagne conclue par quelqu'un SANS ancien rendez-vous
        laissait donc ses « pas appelé » sans un mot — la colonne détail ayant
        été retirée du tableau, il ne restait rien à lire."""
        base = self.application.base
        campagne_id = base.creer_campagne("Essai bandeau", "creneau_libere",
                                          nature="creneau_libere",
                                          mission="Bonjour.")
        for rang, nom in enumerate(("Mme Prise", "Mme Jamais"), start=1):
            contact = base.ajouter_contact_campagne(campagne_id, rang, nom,
                                                    f"06 39 98 24 {40 + rang}")
            if rang == 2:
                base.changer_etat_contact_campagne(contact, "épargné", None)
        _, fiche = self._obtenir(f"/campagne?id={campagne_id}")
        # ⚠ LE MÊME MOT QUE LE TABLEAU, et une explication qui existe.
        self.assertIn("1 contact(s) pas appelé(s)", fiche)
        self.assertNotIn("épargné(s)", fiche)


class TestComptesEtEcartsDits(unittest.TestCase):
    """⚠ « L'ÉCRAN DIT TOUJOURS POURQUOI » — audit croisé du 14/08/2026.

    Quatre écarts confirmés se ramenaient à la même faute : un contact retiré de
    la liste sans être compté, ou compté autrement que ce que la phrase promet.
    Un écart muet se lit comme un défaut du produit, et un compte gonflé envoie
    chercher au mauvais endroit — c'est arrivé au propriétaire deux fois.
    """

    def setUp(self):
        self.base = db.Base(":memory:")
        self.prefs = generation.Preferences()
        self.champs = [dict(c)
                       for c in assistant.NATURES["rappel_rdv"]["champs"]]

    def test_les_stop_sont_comptes_sur_la_source_tous_les_clients(self):
        """⚠ L'ÉCART : la requête les écartait (« AND ne_plus_appeler = 0 ») et
        personne ne les comptait. Mesuré dans sa base : 138 clients, 123 rendus,
        et cinq personnes qui disparaissaient sans un mot."""
        for rang in range(4):
            self.base.ajouter_client(f"Mme Ordinaire {rang}",
                                     f"06 39 98 21 {40 + rang:02d}")
        for rang in range(2):
            client = self.base.ajouter_client(f"M. Interdit {rang}",
                                              f"06 39 98 21 {30 + rang:02d}")
            self.base.definir_ne_plus_appeler(client, True)
        self.base.ajouter_client("Mme Sans Numéro", "")

        contacts, notes = assistant.contacts_depuis_base(
            self.base, "tous", self.champs)
        self.assertEqual(len(contacts), 4)
        joint = " | ".join(notes)
        self.assertIn("2 client(s) 🚫 « Ne plus appeler » écarté(s)", joint)
        self.assertIn("1 client(s) sans numéro écarté(s)", joint)

    def test_les_contacts_deja_dans_la_grille_sont_dits(self):
        """⚠ L'ÉCART : charger deux fois la même source écartait les doublons en
        silence, et l'écran concluait « Aucun contact trouvé depuis cette
        source » — faux, elle en contenait vingt, tous déjà là."""
        client = self.base.ajouter_client("Mme Deux Fois", "06 39 98 21 60")
        demain = (datetime.datetime.now() + datetime.timedelta(days=2)
                  ).replace(hour=9, minute=0, second=0, microsecond=0
                            ).isoformat(timespec="minutes")
        self.base.ajouter_rendezvous(client, demain, "Séance", statut="prévu")

        premiers, _ = assistant.contacts_depuis_base(
            self.base, "a_venir", self.champs)
        self.assertEqual(len(premiers), 1)
        # Deuxième chargement de la MÊME source, en disant ce qu'on a déjà.
        seconds, notes = assistant.contacts_depuis_base(
            self.base, "a_venir", self.champs,
            [c["telephone"] for c in premiers])
        self.assertEqual(seconds, [])
        self.assertIn("1 contact(s) déjà dans la grille — pas ajouté(s) une "
                      "seconde fois", " | ".join(notes))

    def test_le_rappel_de_jours_choisis_compte_les_gens_pas_les_rendezvous(self):
        """⚠ L'ÉCART : la reprise est appelée UNE FOIS PAR JOUR coché et les
        comptes s'additionnaient. Quelqu'un qui a un rendez-vous le lundi ET le
        vendredi était compté deux fois parmi les écartés, alors que la liste,
        elle, le dédoublonnait : l'écran se contredisait tout seul."""
        muet = self.base.ajouter_client("M. Sans Numéro", "")
        lundi = (datetime.datetime.now() + datetime.timedelta(days=2)
                 ).replace(hour=9, minute=0, second=0, microsecond=0)
        vendredi = lundi + datetime.timedelta(days=4)
        for quand in (lundi, vendredi):
            self.base.ajouter_rendezvous(muet,
                                         quand.isoformat(timespec="minutes"),
                                         "Séance", statut="prévu")
        # La MÊME lecture que l'écran : un appel par jour, les écartés réunis.
        ecartes = {}
        for quand in (lundi, vendredi):
            bornes = horaires.bornes_de_periode(
                quand.date(), quand.date() + datetime.timedelta(days=1))
            campagnes.contacts_depuis_rendezvous(
                self.base, "poses", bornes[0], bornes[1], ecartes=ecartes)
        # ⚠ LE CŒUR : UNE personne, pas deux.
        self.assertEqual(len(ecartes["sans_numero"]), 1)

    def test_le_plafond_suit_le_maillon_de_cascade(self):
        """⚠ L'ÉCART : l'écran annonce « la campagne n°X a été PRÉPARÉE, avec
        les mêmes critères ». Le plafond, lui, n'était pas recopié dans le
        brouillon du maillon : il était perdu, pas seulement ignoré."""
        configuration = {"plafond": "5", "ordre": "liste",
                         "politique": "premier_oui"}
        self.assertEqual(assistant.plafond_de(configuration), 5)
        contacts = [{"nom": f"Mme N{rang}",
                     "telephone": f"06 39 98 22 {rang:02d}", "champs": {}}
                    for rang in range(9)]
        gardes, ecartes = assistant.limiter_au_plafond(
            contacts, assistant.plafond_de(configuration),
            ordre=configuration["ordre"])
        self.assertEqual(len(gardes), 5)
        self.assertEqual(ecartes, 4)
        # Et le maillon lit bien le plafond de la campagne d'origine, puis le
        # transmet — les deux, sinon il est appliqué mais pas enregistré.
        source = inspect.getsource(assistant.preparer_cascade_creneau_libere)
        self.assertIn("plafond_de(configuration)", source)
        self.assertIn('"plafond": str(configuration.get("plafond") or "")',
                      source)


class TestProtectionsPorteesAuDeplacement(unittest.TestCase):
    """⚠ L'AUDIT CROISÉ « ADAPTATIONS × NATURES » DU 14/08/2026.

    Tout ce qui protège « créneau libéré » d'annoncer une place qui n'existe
    plus s'était arrêté à cette nature. « Déplacement » propose elle aussi des
    places — des créneaux de REMPLACEMENT, calculés — et n'avait reçu aucune
    des trois protections. Les essais ci-dessous les tiennent une par une.
    """

    def _cabinet(self, plages=((9 * 60, 10 * 60 + 40),)):
        base = db.Base(":memory:")
        prefs = generation.Preferences()
        for jour in range(7):
            for debut, fin in plages:
                horaires.basculer_periode(prefs, jour, debut, fin, "ouvrir")
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        return base, prefs

    @staticmethod
    def _jour(jours=3):
        return (datetime.datetime.now() + datetime.timedelta(days=jours)
                ).replace(hour=9, minute=0, second=0, microsecond=0)

    def _campagne_deplacement(self, base, prefs, horaires_contacts,
                              politique="tous"):
        """Une campagne de déplacement dont la liste de créneaux est CALCULÉE.

        C'est le cas normal : l'opérateur laisse le champ tel que RingBack l'a
        rempli, la valeur reste dans `infos_auto`, et elle est donc recalculée
        avant chaque appel.
        """
        calculee = horaires.creneaux_lisibles(base, prefs)
        lignes = []
        for rang, horaire in enumerate(horaires_contacts):
            client = base.ajouter_client(f"Mme Bouge {rang}",
                                         f"06 39 98 20 {40 + rang:02d}")
            rdv = base.ajouter_rendezvous(client, horaire, "Séance à déplacer",
                                          statut="prévu")
            lignes.append((f"Mme Bouge {rang}", f"06 39 98 20 {40 + rang:02d}",
                           rdv, horaire))
        return assistant.creer_campagne_prete(base, {
            "nature": "deplacement",
            "infos": {"entreprise": "Essai",
                      "raison": "un imprévu",
                      "creneaux_remplacement": calculee},
            "infos_auto": {"creneaux_remplacement": calculee},
            "politique": politique, "ordre": "liste",
            "options": {"liberer_creneau": True},
            "champs": [dict(c)
                       for c in assistant.NATURES["deplacement"]["champs"]],
            "mission": ("Bonjour, votre rendez-vous doit bouger. Places "
                        f"possibles : {calculee}."),
            "recette": {"apports": [], "a_la_main": False},
            "contacts": [
                {"nom": nom, "telephone": tel, "rendezvous_id": rdv,
                 "champs": {"rdv_existant": horaire, "motif": "Séance"}}
                for nom, tel, rdv, horaire in lignes]}, prefs)

    def _boucher_avant(self, base, prefs, jour):
        """Occupe toutes les places AVANT `jour` : les premières places libres
        sont alors celles du jour de la campagne, seul endroit où l'essai peut
        mesurer quelque chose."""
        pas = horaires.pas_minutes(prefs)
        intrus = base.ajouter_client("M. Bouchon", "06 39 98 20 95")
        debut = datetime.datetime.now().replace(hour=9, minute=0, second=0,
                                                microsecond=0)
        while debut.date() < jour.date():
            for rang in range(60 // pas):
                base.ajouter_rendezvous(
                    intrus, (debut + datetime.timedelta(minutes=pas * rang)
                             ).isoformat(timespec="minutes"), "Pris",
                    statut="confirmé")
            debut += datetime.timedelta(days=1)

    def _appli(self, base, prefs, client):
        class Appli:
            def __init__(self):
                self.base, self.preferences = base, prefs
                self.executions, self.mode_reel = {}, False
                self.planif = planificateur.Planificateur(
                    base, client, preferences=prefs)

            def commande_execution(self, identifiant):
                return None

            def terminer_execution(self, identifiant):
                pass

        return Appli()

    class _Espion(calle_client.ClientAppels):
        """Note les messages reçus, et accepte le créneau qu'on lui dicte."""

        class _Issue:
            def __init__(self, resultat):
                self.resultat = resultat
                self.transcription = ""
                self.identifiant = "appel-essai-1"

            def __getattr__(self, nom):
                return None

        def __init__(self, quand=None):
            self.missions = []
            # Une date par appel : sans cela, le deuxième appelé se verrait
            # refuser la place que le premier vient de prendre, et l'essai
            # mesurerait ce refus au lieu de ce qu'il vise.
            self.dates = list(quand or []) if isinstance(quand, (list, tuple)) \
                else [quand]

        def appeler(self, nom, telephone, rendezvous, mission=None,
                    consigne=None, nature=None):
            self.missions.append(mission or "")
            rang = min(len(self.missions) - 1, len(self.dates) - 1)
            return self._Issue({"appointment_status": "confirmed",
                                "new_datetime": self.dates[rang], "notes": ""})

    def test_plus_aucun_creneau_libre_n_appelle_personne(self):
        """⚠ L'ÉCART : le recalcul avant appel ne remplace RIEN quand il rend
        vide (« jamais de texte inventé »). L'agenda s'étant rempli, l'agent
        partait donc annoncer les six dates de la création, toutes occupées. Et
        le repli existant n'était atteint que si le contact n'avait AUCUN
        rendez-vous : sur « déplacement » il en a toujours un."""
        base, prefs = self._cabinet(plages=((9 * 60, 10 * 60),))
        pas = horaires.pas_minutes(prefs)
        jour = self._jour()
        # ⚠ L'AGENDA EST BOUCHÉ SUR TOUT L'HORIZON : une heure ouverte par
        # jour, et chaque place prise. Il ne reste donc RIEN à proposer, et le
        # message de la campagne annonce pourtant la liste de sa création.
        contacts = [(jour + datetime.timedelta(minutes=pas * rang)).isoformat(
            timespec="minutes") for rang in range(3)]
        campagne = self._campagne_deplacement(base, prefs, contacts)
        intrus = base.ajouter_client("M. Intrus", "06 39 98 20 90")
        depart = datetime.datetime.now().replace(hour=9, minute=0, second=0,
                                                 microsecond=0)
        # ⚠ JUSQU'AU PLUS LARGE HORIZON (17/08/2026). La recherche d'une place
        # s'élargit désormais quand le proche est saturé (horaires.HORIZONS_NEGO)
        # — boucher seulement trois semaines laissait des places au-delà, et cet
        # essai prouvait alors le contraire de son intention.
        for ecart in range(max(horaires.HORIZONS_NEGO) + 2):
            debut = depart + datetime.timedelta(days=ecart)
            for rang in range(60 // pas):
                horaire = (debut + datetime.timedelta(minutes=pas * rang)
                           ).isoformat(timespec="minutes")
                if horaire in contacts:
                    continue
                base.ajouter_rendezvous(intrus, horaire, "Pris",
                                        statut="confirmé")
        espion = self._Espion()
        assistant.executer_campagne(self._appli(base, prefs, espion), campagne)

        # ⚠ LE CŒUR : AUCUN appel n'est parti.
        self.assertEqual(espion.missions, [])
        for contact in base.contacts_de_campagne(campagne):
            self.assertEqual(contact["etat"], "à rappeler par un humain")
            self.assertIn("il n'en reste plus AUCUN de libre",
                          contact["detail"])
            # Le rendez-vous n'a pas bougé d'un pouce.
            self.assertEqual(base.obtenir_rendezvous(
                contact["rendezvous_id"])["horaire"],
                assistant.champs_contact(contact)["rdv_existant"])

    def test_une_campagne_de_deplacement_ne_repropose_pas_ce_qu_elle_vide(self):
        """⚠ L'ÉCART LE PLUS VISIBLE DE L'AUDIT. Une campagne « vider le mardi
        matin » recalcule ses créneaux de remplacement avant chaque appel : dès
        que le premier patient accepte de partir, la place qu'il quitte
        redevient libre — et elle était annoncée au patient suivant. La campagne
        remplissait le créneau qu'elle devait vider."""
        # ⚠ LA GÉOMÉTRIE COMPTE : les places que la campagne vide doivent être
        # les PLUS PROCHES, sinon elles ne figureraient de toute façon pas dans
        # les six premières places annoncées et l'essai ne prouverait rien. Une
        # seule heure ouverte par jour suffit à les mettre en tête.
        base, prefs = self._cabinet(plages=((9 * 60, 10 * 60),))
        pas = horaires.pas_minutes(prefs)
        jour = self._jour()
        contacts = [(jour + datetime.timedelta(minutes=pas * rang)).isoformat(
            timespec="minutes") for rang in range(3)]
        campagne = self._campagne_deplacement(base, prefs, contacts)
        # ⚠ ET LES JOURS D'AVANT SONT BOUCHÉS, sinon les places annoncées
        # seraient celles d'aujourd'hui et de demain, et les places que la
        # campagne vide ne pourraient de toute façon pas y figurer : l'essai
        # passerait sans rien prouver (mesuré).
        self._boucher_avant(base, prefs, jour)
        # L'agent accepte, et la date convenue est le LENDEMAIN — une place par
        # personne, prise hors du matin qu'on vide.
        demain = jour + datetime.timedelta(days=1)
        ailleurs = [(demain + datetime.timedelta(minutes=pas * rang)).isoformat(
            timespec="minutes") for rang in range(3)]
        espion = self._Espion(quand=ailleurs)
        assistant.executer_campagne(self._appli(base, prefs, espion), campagne)

        self.assertEqual(len(espion.missions), 3)
        # ⚠ LE CŒUR : aucune des places que la campagne vide n'est annoncée, à
        # aucun appel — pas même au troisième, quand les deux premières sont
        # déjà libres et sont les plus proches de toutes.
        for rang, mission in enumerate(espion.missions):
            for horaire in contacts:
                with self.subTest(appel=rang + 1, place=horaire):
                    self.assertNotIn(themes.date_lisible(horaire), mission)
        # Et le matin est bien VIDE à la fin : c'était le but.
        restants = [r["horaire"] for r in base.tous_les_rendezvous()
                    if r["horaire"] in contacts
                    and r["statut"] in horaires.STATUTS_OCCUPANTS]
        self.assertEqual(restants, [])

    def test_un_maillon_de_deplacement_ne_fait_pas_avancer_de_curseur(self):
        """⚠ L'ÉCART : le maillon porte la place libérée — c'est la trace §8.3,
        et l'anti-doublon s'en sert — mais son message annonce des créneaux de
        REMPLACEMENT, jamais cette place. La boucle « avançait » pourtant son
        curseur dessus au premier accord : elle recalait le message sur une
        place que personne ne proposait, et affichait aux contacts restants une
        raison qui ne correspondait à rien. Un oui doit simplement conclure."""
        base, prefs = self._cabinet(plages=((9 * 60, 12 * 60),
                                            (14 * 60, 17 * 60)))
        jour = self._jour()
        contacts = [(jour + datetime.timedelta(minutes=20 * rang)).isoformat(
            timespec="minutes") for rang in range(2)]
        campagne = self._campagne_deplacement(base, prefs, contacts,
                                              politique="premier_oui")
        configuration = assistant.configuration_campagne(
            base.obtenir_campagne(campagne))
        configuration["options"]["cascade"] = True
        configuration["options"]["cascade_jusqu_au"] = (
            jour + datetime.timedelta(days=60)).date().isoformat()
        # Une recette REJOUABLE : c'est elle qui fabrique la liste du maillon.
        configuration["recette"] = {
            "apports": [{"mode": "base", "source": "a_venir"}],
            "a_la_main": False, "mission_editee": False}
        base.definir_configuration_campagne(
            campagne, json.dumps(configuration, ensure_ascii=False))
        ailleurs = jour.replace(hour=15, minute=0).isoformat(timespec="minutes")
        espion = self._Espion(quand=ailleurs)
        assistant.executer_campagne(self._appli(base, prefs, espion), campagne)

        maillons = [c for c in base.lister_campagnes() if c["id"] != campagne]
        self.assertEqual(len(maillons), 1, "un maillon devait être préparé")
        maillon = base.obtenir_campagne(maillons[0]["id"])
        # Le maillon porte bien la place libérée : c'est la trace §8.3.
        self.assertIsNotNone(maillon["creneau"])
        # ⚠ LE CŒUR : la campagne d'ORIGINE, elle, n'a pas de place à pourvoir
        # et son premier oui la termine — sans curseur, sans raison inventée.
        self.assertFalse(assistant.campagne_a_des_places(
            base.obtenir_campagne(campagne)))
        self.assertEqual(base.obtenir_campagne(campagne)["statut"], "terminée")
        epargnes = [c for c in base.contacts_de_campagne(campagne)
                    if c["etat"] == "épargné"]
        self.assertEqual(len(epargnes), 1)
        self.assertIn("arrêt au premier oui", epargnes[0]["detail"])
        self.assertIn("déplacé", epargnes[0]["detail"])


class TestPlaceDejaPriseAvantDAppeler(unittest.TestCase):
    """⚠ LE DÉFAUT LE PLUS COÛTEUX DE CE CHANTIER (11/08/2026).

    MESURÉ AVANT : une campagne de créneau libéré dont la place était DÉJÀ
    OCCUPÉE a passé **trente appels** et envoyé **quatorze personnes** « à
    rappeler par un humain » — chacune s'étant entendu dire au téléphone que la
    place était pour elle. RingBack ne s'en apercevait qu'APRÈS l'appel, une fois
    par personne, en refusant d'écrire le rendez-vous.

    C'est ce que le propriétaire a vu sous la forme « je continue à avoir un état
    à rappeler par un humain ». La cause n'était pas la règle du rappel humain :
    c'était une campagne qui appelait pour une place inexistante.

    La règle tenue ici : **on relit la place AVANT chaque appel**. Même doctrine
    que la mise en pause sur panne — inutile d'infliger le même échec aux
    dix-neuf suivants — en pire, puisqu'ici on aurait PROMIS une place.
    """

    def _monter(self, places, occupees=(), fin="", jours_apres=30):
        """La campagne d'essai. `fin` force la terminaison des candidates —
        « 51 » les fait toutes ACCEPTER (voir calle_client.TERMINAISONS_FORCEES),
        ce qui rend un essai sur l'attribution des places déterministe."""
        base = db.Base(":memory:")
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        # Les places qu'on déclare occupées le sont VRAIMENT : un rendez-vous
        # dessus, comme dans un agenda réel.
        for rang, quand in enumerate(occupees):
            occupant = base.ajouter_client(f"M. Occupant {rang}",
                                           f"+33 6 00 00 00 {30 + rang:02d}")
            base.ajouter_rendezvous(occupant, quand, "Déjà pris",
                                    statut="confirmé")
        lignes = []
        for rang in range(6):
            # ⚠ RACINE ARCEP QUAND ON FORCE LA TERMINAISON. Avec la série en
            # +33, le contrôle de publication ne lit que le début du gabarit,
            # trop court pour être reconnu comme fictif : il bloquait la copie
            # publique (constaté le 14/08/2026). La racine, elle, se reconnaît
            # à ses six premiers chiffres.
            numero = (f"06 39 98 {rang:02d} {fin}" if fin
                      else f"+33 6 00 00 00 {40 + rang:02d}")
            client = base.ajouter_client(f"Mme Candidate {rang}", numero)
            rdv = base.ajouter_rendezvous(
                client, (datetime.datetime.fromisoformat(places[0])
                         + datetime.timedelta(days=jours_apres + rang)
                         ).isoformat(timespec="minutes"), "Bilan",
                statut="prévu")
            lignes.append((f"Mme Candidate {rang}", numero, rdv))
        campagne = assistant.creer_campagne_prete(base, {
            "nature": "creneau_libere",
            "infos": {"creneau_libere": places[0], "entreprise": "Essai"},
            "infos_auto": {}, "politique": "premier_oui",
            "ordre": "eloignement", "options": {"liberer_creneau": True},
            "champs": [dict(c)
                       for c in assistant.NATURES["creneau_libere"]["champs"]],
            "mission": "Bonjour.",
            "recette": {"apports": [], "a_la_main": False},
            "creneaux": assistant.normaliser_creneaux(places),
            "contacts": [
                {"nom": nom, "telephone": tel, "rendezvous_id": rdv,
                 "champs": {"rdv_existant": base.obtenir_rendezvous(rdv)["horaire"],
                            "motif": "Bilan"}}
                for nom, tel, rdv in lignes]}, prefs)
        return base, prefs, campagne

    def _derouler(self, base, prefs, campagne, client=None):
        planif = planificateur.Planificateur(
            base, client or calle_client.AppelSimule(graine=1, latence=0),
            preferences=prefs)

        class Appli:
            def __init__(self):
                self.base, self.preferences, self.planif = base, prefs, planif
                self.executions, self.mode_reel = {}, False

            def commande_execution(self, _):
                return None

            def terminer_execution(self, _):
                pass

        assistant.executer_campagne(Appli(), campagne)
        return [c for c in base.contacts_de_campagne(campagne)]

    @staticmethod
    def _demain(heure=10, jours=3):
        return (datetime.datetime.now() + datetime.timedelta(days=jours)
                ).replace(hour=heure, minute=0, second=0, microsecond=0
                          ).isoformat(timespec="minutes")

    def test_aucun_appel_ne_part_pour_une_place_deja_prise(self):
        place = self._demain()
        base, prefs, campagne = self._monter([place], occupees=[place])
        contacts = self._derouler(base, prefs, campagne)
        appels = sum(len(base.appels_du_contact_campagne(c["id"]))
                     for c in contacts)
        self.assertEqual(appels, 0, "personne ne doit être appelé")
        self.assertEqual({c["etat"] for c in contacts}, {"épargné"})
        # Et la raison est écrite, en clair, sur chaque contact.
        self.assertIn("la place proposée n'est plus disponible",
                      contacts[0]["detail"])
        # Aucun contact ne part vers un humain : c'était le symptôme.
        self.assertNotIn("à rappeler par un humain",
                         {c["etat"] for c in contacts})
        self.assertEqual(base.obtenir_campagne(campagne)["statut"], "terminée")

    def test_la_place_perdue_est_notee_comme_telle(self):
        """« perdu » existait dans le code sans que rien ne l'écrive jamais.
        C'est ce statut qui distingue « pourvue par nous » de « prise ailleurs ».
        """
        place = self._demain()
        base, prefs, campagne = self._monter([place], occupees=[place])
        self._derouler(base, prefs, campagne)
        configuration = assistant.configuration_campagne(
            base.obtenir_campagne(campagne))
        fiches = assistant.creneaux_de(base.obtenir_campagne(campagne),
                                       configuration)
        self.assertEqual([f["statut"] for f in fiches],
                         [assistant.CRENEAU_PERDU])

    def test_avec_plusieurs_places_la_campagne_passe_a_la_suivante(self):
        """⚠ ELLE NE S'ARRÊTE PAS BÊTEMENT. Une place prise n'invalide que
        celle-là : la campagne avance sur la suivante et appelle vraiment."""
        prise, libre = self._demain(9), self._demain(15)
        base, prefs, campagne = self._monter([prise, libre], occupees=[prise])
        contacts = self._derouler(base, prefs, campagne)
        appels = sum(len(base.appels_du_contact_campagne(c["id"]))
                     for c in contacts)
        self.assertGreater(appels, 0, "la seconde place, elle, est libre")
        statuts = {f["horaire"]: f["statut"] for f in assistant.creneaux_de(
            base.obtenir_campagne(campagne),
            assistant.configuration_campagne(base.obtenir_campagne(campagne)))}
        self.assertEqual(statuts[prise], assistant.CRENEAU_PERDU)
        self.assertNotEqual(statuts[libre], assistant.CRENEAU_PERDU)

    def test_une_place_libre_ne_declenche_rien(self):
        """Le garde-fou ne doit pas arrêter une campagne qui va bien."""
        base, prefs, campagne = self._monter([self._demain()])
        contacts = self._derouler(base, prefs, campagne)
        appels = sum(len(base.appels_du_contact_campagne(c["id"]))
                     for c in contacts)
        self.assertGreater(appels, 0)

    def test_une_place_prise_APRES_le_depart_n_est_proposee_qu_une_fois(self):
        """⚠ LE DÉFAUT MESURÉ DANS SA BASE LE 14/08/2026, et il est différent
        du précédent : la place n'était pas prise AU DÉPART — elle l'est devenue
        PENDANT la campagne. Le contrôle du départ ne pouvait donc rien voir.

        Dans sa campagne n°28, une personne avait convenu d'une autre date —
        15 h 30, hors du quadrillage — et ce rendez-vous chevauchait la place de
        15 h 40 encore annoncée. **Vingt-quatre personnes** ont dit oui à cette
        place morte, l'une après l'autre : vingt-quatre refus, vingt-quatre
        départs « à rappeler par un humain » sur une campagne de créneau libéré,
        où il avait justement fait retirer cet état.

        La règle tenue ici : le PREMIER refus retire la place. Personne d'autre
        ne se la voit proposer.
        """
        libre, piegee = self._demain(9), self._demain(15)
        # Toutes les candidates ACCEPTENT (terminaison 51) : c'est la seule
        # façon d'atteindre la seconde place à coup sûr.
        base, prefs, campagne = self._monter([libre, piegee], fin="51")
        # La seconde place est prise APRÈS la création de la campagne : le
        # contrôle du départ, qui ne regarde que la place en cours, la laisse
        # passer — exactement comme un rendez-vous convenu en cours de route.
        intrus = base.ajouter_client("M. Intrus Exemple", "+33 6 00 00 00 91")
        base.ajouter_rendezvous(intrus, piegee, "Pris entre-temps",
                                statut="confirmé")
        contacts = self._derouler(base, prefs, campagne)

        statuts = {f["horaire"]: f["statut"] for f in assistant.creneaux_de(
            base.obtenir_campagne(campagne),
            assistant.configuration_campagne(base.obtenir_campagne(campagne)))}
        self.assertEqual(statuts[piegee], assistant.CRENEAU_PERDU)
        # ⚠ LE CŒUR DE L'ESSAI : UN SEUL contact a essuyé le refus.
        # ⚠ Repéré par le DÉTAIL, plus par l'état (15/08/2026) : depuis que le
        # rappel manuel a disparu de cette nature, chercher « à rappeler par un
        # humain » ne trouvait plus personne — et un `assertLessEqual(…, 1)`
        # passait avec ZÉRO. L'essai ne prouvait donc plus rien.
        # ⚠ ET « NON créé », PAS « prise entre-temps » : cette seconde phrase
        # est aussi celle des ÉPARGNÉS, qui n'ont jamais été appelés. Seul
        # `_date_refusee` écrit « NON créé ».
        refuses = [c for c in contacts if "NON créé" in (c["detail"] or "")]
        self.assertEqual(len(refuses), 1,
                         [(c["nom"], c["etat"], c["detail"])
                          for c in contacts])
        # Et l'écran dit ce qui a été fait de la place, en toutes lettres.
        self.assertEqual(refuses[0]["etat"], "refusé")
        self.assertIn("a été prise entre-temps", refuses[0]["detail"])
        self.assertIn("plus personne ne se la verra proposer",
                      refuses[0]["detail"])

    def _cascade_reglee(self, campagne, base, jusqu_au):
        """Coche « décaler en cascade » et pose sa date limite."""
        configuration = assistant.configuration_campagne(
            base.obtenir_campagne(campagne))
        configuration["options"]["cascade"] = True
        configuration["options"]["cascade_jusqu_au"] = jusqu_au
        base.definir_configuration_campagne(
            campagne, json.dumps(configuration, ensure_ascii=False))

    def test_sans_l_option_la_place_quittee_ne_revient_pas(self):
        """⚠ SA DÉCISION DU 14/08/2026, mot pour mot : « seulement si l'option
        du traitement en cascade est demandé : c'est une option, pas une
        obligation ».

        Le défaut mesuré dans sa base : il avait choisi CINQ places, sa
        campagne en a compté TRENTE-SEPT. Chaque personne avancée creuse un
        trou plus loin, que la campagne comblait en creusant encore — sans rien
        demander, et sans s'arrêter aux places qu'il avait choisies.
        """
        places = [self._demain(9), self._demain(11)]
        base, prefs, campagne = self._monter(places, fin="51")
        self._derouler(base, prefs, campagne)
        fiches = assistant.creneaux_de(
            base.obtenir_campagne(campagne),
            assistant.configuration_campagne(base.obtenir_campagne(campagne)))
        # ⚠ LE CŒUR : deux places choisies, deux places en tout.
        self.assertEqual([f["horaire"] for f in fiches], sorted(places))
        # Et personne ne lit qu'une place « rejoint la liste ».
        for contact in base.contacts_de_campagne(campagne):
            self.assertNotIn("rejoint la liste", contact["detail"] or "")

    def test_avec_l_option_la_place_quittee_rejoint_la_campagne(self):
        """L'option cochée, le comportement d'avant revient — c'est bien une
        option, pas une suppression."""
        places = [self._demain(9), self._demain(11)]
        base, prefs, campagne = self._monter(places, fin="51")
        self._cascade_reglee(campagne, base, "")     # cochée, sans date limite
        self._derouler(base, prefs, campagne)
        fiches = assistant.creneaux_de(
            base.obtenir_campagne(campagne),
            assistant.configuration_campagne(base.obtenir_campagne(campagne)))
        self.assertGreater(len(fiches), len(places),
                           "les places quittées doivent rejoindre la liste")
        details = " ".join(c["detail"] or ""
                           for c in base.contacts_de_campagne(campagne))
        self.assertIn("rejoint la liste", details)

    def test_la_date_limite_borne_la_cascade_de_la_liste(self):
        """⚠ SANS BUTÉE, LA CAMPAGNE MARCHE VERS LE FUTUR SANS FIN. La date
        limite de l'option borne aussi ce chemin-là : au-delà, la place quittée
        reste simplement libre sur le planning, et l'écran le dit."""
        places = [self._demain(9), self._demain(11)]
        base, prefs, campagne = self._monter(places, fin="51")
        # Limite AVANT les rendez-vous des candidates (+30 jours et plus) :
        # aucune place quittée ne peut donc rejoindre la liste.
        self._cascade_reglee(campagne, base, (
            datetime.datetime.fromisoformat(places[0])
            + datetime.timedelta(days=5)).date().isoformat())
        self._derouler(base, prefs, campagne)
        fiches = assistant.creneaux_de(
            base.obtenir_campagne(campagne),
            assistant.configuration_campagne(base.obtenir_campagne(campagne)))
        self.assertEqual([f["horaire"] for f in fiches], sorted(places))
        details = " ".join(c["detail"] or ""
                           for c in base.contacts_de_campagne(campagne))
        self.assertIn("limite réglée pour le décalage en cascade", details)

    def test_une_SEULE_place_qui_meurt_arrete_la_campagne_tout_de_suite(self):
        """⚠ L'ÉCART TROUVÉ PAR L'AUDIT DU 14/08/2026, et c'est le défaut du
        14/08 lui-même, seulement déplacé d'un cran. Le premier correctif
        retirait la place de la LISTE, mais la boucle d'exécution ne relit la
        campagne que sur « pourvu » : sur une campagne à UNE SEULE place — le
        cas le plus courant, un trou et une liste de gens — elle continuait
        d'appeler tout le monde pour une place morte. Mesuré par l'audit : six
        contacts, six appels, six départs « à rappeler par un humain ».

        La règle tenue ici : le PREMIER refus arrête la campagne, comme le fait
        le contrôle du démarrage quand la place était déjà prise avant.
        """
        place = self._demain()
        base, prefs, campagne = self._monter([place])
        self.assertFalse(assistant.configuration_campagne(
            base.obtenir_campagne(campagne))["liste_de_places"])

        class PlaceVoleeAuPremierAppel(calle_client.ClientAppels):
            """Le premier appelé refuse, ET la place est prise pendant ce
            temps-là (un rendez-vous posé à la main, un import d'agenda…) ;
            tous les suivants acceptent. C'est l'enchaînement réel : la place
            était libre au démarrage, elle meurt en cours de route."""

            class _Issue:
                def __init__(self, resultat):
                    self.resultat = resultat
                    self.transcription = ""
                    self.identifiant = "appel-essai-1"

                def __getattr__(self, nom):
                    return None

            def __init__(self):
                self.tours = 0

            def appeler_cascade(self, nom, telephone, mission, creneau,
                                consigne=None, nature=None):
                self.tours += 1
                if self.tours == 1:
                    intrus = base.ajouter_client("M. Intrus Exemple",
                                                 "06 39 98 09 91")
                    base.ajouter_rendezvous(intrus, place, "Pris entre-temps",
                                            statut="confirmé")
                    return self._Issue({"outcome": "refused",
                                        "new_datetime": None, "notes": ""})
                return self._Issue({"outcome": "accepted",
                                    "new_datetime": None, "notes": ""})

        contacts = self._derouler(base, prefs, campagne,
                                  client=PlaceVoleeAuPremierAppel())

        appeles = [c for c in contacts
                   if base.appels_du_contact_campagne(c["id"])]
        # ⚠ LE CŒUR : DEUX appels seulement — celui qui refuse, puis celui qui
        # découvre la place morte. Pas les six.
        self.assertEqual(len(appeles), 2,
                         [(c["nom"], c["etat"]) for c in contacts])
        # ⚠ « refusé » depuis le 15/08/2026, plus « à rappeler par un humain » :
        # un créneau libéré ne produit plus de rappel manuel. Ce qui est
        # contrôlé reste le même — celui qui découvre la place morte lit
        # POURQUOI, en clair, sur sa fiche.
        # ⚠ « NON créé » et pas « prise entre-temps » : cette seconde phrase est
        # aussi celle des ÉPARGNÉS, qui n'ont jamais été appelés.
        prevenu = [c for c in contacts if "NON créé" in (c["detail"] or "")]
        self.assertEqual(len(prevenu), 1,
                         [(c["nom"], c["etat"], c["detail"])
                          for c in contacts])
        self.assertEqual(prevenu[0]["etat"], "refusé")
        self.assertIn("a été prise entre-temps", prevenu[0]["detail"])
        self.assertFalse([c for c in contacts
                          if c["etat"] == "à rappeler par un humain"])
        # Les autres sont « pas appelé », avec la raison en clair.
        epargnes = [c for c in contacts if c["etat"] == "épargné"]
        self.assertEqual(len(epargnes), len(contacts) - 2)
        self.assertIn("prise entre-temps", epargnes[0]["detail"])
        # La place est notée perdue, et la campagne est finie.
        fiches = assistant.creneaux_de(
            base.obtenir_campagne(campagne),
            assistant.configuration_campagne(base.obtenir_campagne(campagne)))
        self.assertEqual([f["statut"] for f in fiches],
                         [assistant.CRENEAU_PERDU])
        self.assertEqual(base.obtenir_campagne(campagne)["statut"], "terminée")

    def test_une_place_pourvue_par_nous_n_est_jamais_dite_perdue(self):
        """⚠ « POURVU PAR NOUS » N'EST PAS « PRIS AILLEURS ». Sur une campagne
        qui appelle TOUTE la liste, le premier oui pourvoit la place et le
        deuxième se la voit refuser — elle est occupée, mais par nous. La
        marquer perdue effacerait le fait qu'elle a servi. C'est le piège qui
        avait fait tomber vingt contrôles du banc le 11/08/2026."""
        place = self._demain()
        base, prefs, campagne = self._monter([place])
        configuration = assistant.configuration_campagne(
            base.obtenir_campagne(campagne))
        configuration["politique"] = "tous"
        base.definir_configuration_campagne(
            campagne, json.dumps(configuration, ensure_ascii=False))
        self._derouler(base, prefs, campagne)
        statuts = {f["horaire"]: f["statut"] for f in assistant.creneaux_de(
            base.obtenir_campagne(campagne),
            assistant.configuration_campagne(base.obtenir_campagne(campagne)))}
        self.assertEqual(statuts[place], assistant.CRENEAU_POURVU)


class TestAucunRappelManuelSurUnCreneauLibere(unittest.TestCase):
    """⚠ SA DEMANDE, SIGNALÉE UNE FOIS DE PLUS LE 15/08/2026 : « j'ai encore
    dans mes tests des rappels manuels alors qu'on a dit qu'il n'y en avait
    plus pour les créneaux libres ».

    Il avait raison, et la décision était écrite depuis le 11/08 (voir
    `assistant.NATURES_RAPPEL_HUMAIN` et le README du 14/08 : « sur une
    campagne de créneau libéré, où tu avais justement fait retirer cet état »).
    Elle n'était tenue que sur UN chemin — celui des réponses non conclusives.
    Le chemin des DATES REFUSÉES, lui, l'ignorait encore. Mesuré sur sa base :
    huit contacts « 🙋 à rappeler par un humain » dans ses quatre campagnes,
    tous par ce second chemin.

    ⚠ POURQUOI CET ESSAI BALAIE TOUTES LES ISSUES plutôt qu'une. C'est le
    défaut de fond de ce chantier : corriger le chemin signalé, pas la règle.
    Ici la règle est contrôlée telle qu'elle s'énonce — « AUCUNE issue, sur
    cette nature, ne produit un rappel manuel » — donc une porte de côté
    ouverte plus tard tombe toute seule.
    """

    ISSUES = ("accepted", "refused", "moved", "to_reschedule", "no_answer",
              "wrong_number", "do_not_call")

    def _jouer(self, issue, date_convenue):
        """Une campagne « créneau libéré », un contact, une issue imposée."""
        base = db.Base(":memory:")
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        place = (datetime.datetime.now() + datetime.timedelta(days=1)
                 ).replace(hour=9, minute=0, second=0, microsecond=0)
        rdv = (place + datetime.timedelta(days=40)).isoformat(
            timespec="minutes")
        client = base.ajouter_client("Mme Essai", "06 39 98 60 10")
        base.ajouter_rendezvous(client, rdv, "Séance", statut="prévu")

        class Simule(calle_client.ClientAppels):
            class _Issue:
                def __init__(self, resultat):
                    self.resultat = resultat
                    self.transcription = ""
                    self.identifiant = "appel-essai-1"

                def __getattr__(self, nom):
                    return None

            def appeler_cascade(self, nom, telephone, mission, creneau,
                                consigne=None, nature=None):
                return self._Issue({"outcome": issue,
                                    "new_datetime": date_convenue,
                                    "notes": ""})

        class Appli:
            def __init__(self):
                self.base, self.preferences = base, prefs
                self.executions, self.mode_reel = {}, False
                self.planif = planificateur.Planificateur(
                    base, Simule(), preferences=prefs)

            def commande_execution(self, identifiant):
                return None

            def terminer_execution(self, identifiant):
                pass

        campagne = assistant.creer_campagne_prete(base, {
            "nature": "creneau_libere",
            "infos": {"creneau_libere": place.isoformat(timespec="minutes"),
                      "entreprise": "Essai"},
            "infos_auto": {}, "politique": "premier_oui", "ordre": "liste",
            "options": {"liberer_creneau": True},
            "champs": [dict(c) for c
                       in assistant.NATURES["creneau_libere"]["champs"]],
            "mission": "Bonjour.", "mode_liste": "manuel",
            "recette": {"apports": [{"mode": "base", "source": "a_venir"}],
                        "a_la_main": False, "mission_editee": False},
            "creneaux": assistant.normaliser_creneaux(
                [place.isoformat(timespec="minutes")]),
            "contacts": [{"nom": "Mme Essai", "telephone": "06 39 98 60 10",
                          "champs": {"rdv_existant": rdv,
                                     "motif": "Séance"}}]}, prefs)
        assistant.executer_campagne(Appli(), campagne)
        return base.contacts_de_campagne(campagne)[0], place, rdv

    def test_aucune_issue_ne_produit_un_rappel_manuel(self):
        """Les sept issues du chemin « cascade », sans exception."""
        for issue in self.ISSUES:
            with self.subTest(issue=issue):
                contact, _, _ = self._jouer(issue, None)
                self.assertNotEqual(contact["etat"],
                                    "à rappeler par un humain",
                                    contact["detail"])

    def test_une_date_convenue_irrecevable_ne_produit_pas_de_rappel_manuel(
            self):
        """⚠ LE CHEMIN QU'IL VOYAIT : « oui, mais une autre date », et cette
        date n'est pas réservable. Ses huit contacts venaient tous de là.

        Trois façons de ne pas l'être : hors des horaires d'ouverture, déjà
        prise, illisible. Aucune ne doit produire de rappel manuel, et aucune
        ne doit écrire quoi que ce soit en agenda (§6.5).
        """
        place = (datetime.datetime.now() + datetime.timedelta(days=1)
                 ).replace(hour=9, minute=0, second=0, microsecond=0)
        irrecevables = {
            "hors des horaires": (place + datetime.timedelta(days=60)
                                  ).replace(hour=3).isoformat(
                                      timespec="minutes"),
            "déjà prise": (place + datetime.timedelta(days=40)).isoformat(
                timespec="minutes"),
            "illisible": None,
        }
        for pourquoi, quand in irrecevables.items():
            with self.subTest(date=pourquoi):
                contact, _, rdv = self._jouer("moved", quand)
                self.assertEqual(contact["etat"], "refusé", contact["detail"])
                # La raison reste lisible sur sa fiche, et l'agenda est intact.
                self.assertIn("aucun rendez-vous n'a été écrit",
                              contact["detail"])
                # Et son rendez-vous à lui n'a pas bougé : il est conservé,
                # et passé en « confirmé » puisqu'on lui a parlé.
                self.assertIn("conserve son rendez-vous", contact["detail"])

    def test_l_ecran_ne_promet_plus_un_rappel_que_personne_ne_fera(self):
        """⚠ LA DEMI-CORRECTION À NE PAS FAIRE. Changer l'état sans changer le
        texte laissait « un humain doit rappeler » écrit sur une fiche
        « refusé » : l'écran promettait un travail que plus personne ne ferait.
        """
        contact, _, _ = self._jouer(
            "moved", (datetime.datetime.now() + datetime.timedelta(days=61)
                      ).replace(hour=3, minute=0, second=0, microsecond=0
                                ).isoformat(timespec="minutes"))
        self.assertNotIn("un humain doit rappeler", contact["detail"])
        self.assertIn("proposée à quelqu'un d'autre", contact["detail"])


class TestCocheDesConfirmes(_TestAvecServeurWeb):
    """⚠ LA COCHE VERTE DES RENDEZ-VOUS CONFIRMÉS (demande du propriétaire,
    11/08/2026), au calendrier de la page Rendez-vous.

    La tuile portait la couleur du statut, et rien d'autre : la couleur seule ne
    dit rien à qui ne la connaît pas. Le MOT « confirmé » reste dans l'infobulle
    — une coche ne remplace pas un mot.
    """

    def _semaine(self, quand):
        jour = datetime.date.fromisoformat(quand[:10])
        lundi = jour - datetime.timedelta(days=jour.weekday())
        _, page = self._obtenir(f"/suivi/planning?date={lundi}")
        return page.split("</head>", 1)[-1]

    def _tuiles(self, corps):
        return re.findall(r'<td class="tuile".*?</td>', corps, re.S)

    def _poser(self, statut, heure=11):
        base = self.application.base
        quand = (datetime.datetime.now() + datetime.timedelta(days=2)).replace(
            hour=heure, minute=0, second=0, microsecond=0
        ).isoformat(timespec="minutes")
        client = base.ajouter_client(f"Mme Test {statut}",
                                     f"+33 6 00 00 00 {40 + heure:02d}")
        base.ajouter_rendezvous(client, quand, "Séance", statut=statut)
        return quand

    def test_la_coche_est_sur_les_confirmes_et_seulement_eux(self):
        quand = self._poser("confirmé", heure=11)
        self._poser("prévu", heure=12)
        corps = self._semaine(quand)
        coches = [t for t in self._tuiles(corps) if "coche-confirme" in t]
        self.assertTrue(coches, "aucune coche au calendrier")
        for tuile in coches:
            self.assertIn("Mme Test confirmé", tuile)
        # La tuile du rendez-vous PRÉVU ne doit pas en porter.
        prevues = [t for t in self._tuiles(corps) if "Mme Test prévu" in t]
        self.assertTrue(prevues)
        for tuile in prevues:
            self.assertNotIn("coche-confirme", tuile)

    def test_le_mot_confirme_reste_dans_l_infobulle(self):
        """⚠ UN PICTOGRAMME NE REMPLACE JAMAIS UN MOT. Le propriétaire ne lit pas
        les icônes : la coche signale, l'infobulle dit."""
        quand = self._poser("confirmé", heure=11)
        corps = self._semaine(quand)
        tuile = next(t for t in self._tuiles(corps) if "coche-confirme" in t)
        titre = re.search(r'title="([^"]*)"', tuile).group(1)
        self.assertIn("confirmé", titre)


class TestMotsDesEtats(unittest.TestCase):
    """⚠ « ÉPARGNÉ » NE VOULAIT RIEN DIRE POUR SON LECTEUR (11/08/2026) : « je ne
    sais pas ce que veut dire l'état "épargné" ». Le mot affiché devient « pas
    appelé » — le CODE écrit en base, lui, ne change pas (les migrations de ce
    produit sont additives, jamais des réécritures de données).
    """

    def test_le_mot_affiche_est_clair_et_le_code_ne_bouge_pas(self):
        self.assertEqual(assistant.mot_etat("épargné"), "pas appelé")
        # ⚠ SECOND RENOMMAGE, LE 21/08/2026 : « le client rappellera » était
        # vrai mais taisait le FAIT — le rendez-vous est ANNULÉ. Sur sa
        # campagne n° 119, il a compté deux annulations là où il y en avait
        # trois, parce que l'état ne le disait pas.
        self.assertEqual(assistant.mot_etat(assistant.ETAT_RAPPELLERA),
                         "annulé — le client rappellera")
        # ET LE PICTOGRAMME SUIT : 📞 évoquait un appel, pas une annulation.
        self.assertEqual(assistant.ETATS[assistant.ETAT_RAPPELLERA][0], "❌")
        # ⚠ LE CODE ÉCRIT EN BASE NE BOUGE PAS — c'est toute la règle.
        self.assertEqual(assistant.ETAT_RAPPELLERA, "le client rappellera")
        # Les autres états gardent leur mot : on ne renomme que ce qui bloque.
        for etat in assistant.ETATS:
            if etat not in ("épargné", assistant.ETAT_RAPPELLERA):
                self.assertEqual(assistant.mot_etat(etat), etat)

    def test_tous_les_etats_ont_un_mot(self):
        """CLIQUET : un état ajouté sans mot ressortirait tel quel à l'écran —
        ce qui est acceptable, mais doit rester un choix, pas un oubli."""
        for etat in assistant.ETATS:
            self.assertTrue(assistant.mot_etat(etat))


class TestRappelHumainSeulementDeuxNatures(_CampagneAssistant):
    """⚠ LA DÉCISION DU PROPRIÉTAIRE, 11/08/2026, mot pour mot : « nous allons
    permettre le rappel par un humain uniquement en cas de déplacement de
    rendez-vous ou de prise de rendez-vous ».

    POURQUOI CES DEUX-LÀ. Il reste une date à trouver : un humain a un travail
    réel. Ailleurs, non — et sur un créneau libéré, il l'a dit : « le créneau est
    certainement attribué à quelqu'un d'autre, alors ce sera contacter quelqu'un
    pour lui dire "en fait on voulait vous demander quelque chose, mais ce n'est
    plus d'actualité" ».
    """

    # « 55 » : la personne veut bouger, rien n'est convenu — l'issue qui menait
    # au rappel par un humain sur les cinq natures.
    NUMERO = "+33 6 00 00 00 55"

    def _rien_de_conclu(self, nature, lignes, **options):
        campagne = self._campagne(nature, lignes, **options)
        etats = self._derouler(campagne)
        return campagne, etats

    @staticmethod
    def _place_libre():
        """Une place libre à proposer — la nature « créneau libéré » l'exige."""
        return (datetime.datetime.now() + datetime.timedelta(days=3)).replace(
            hour=10, minute=0, second=0, microsecond=0
        ).isoformat(timespec="minutes")

    def test_le_deplacement_garde_le_rappel_par_un_humain(self):
        horaire = (datetime.datetime.now() + datetime.timedelta(days=4)
                   ).replace(hour=10, minute=0, second=0, microsecond=0
                             ).isoformat(timespec="minutes")
        _, etats = self._rien_de_conclu(
            "deplacement", [f"Mme Hésite;{self.NUMERO};{horaire};Séance"])
        contact = etats["Mme Hésite"]
        self.assertEqual(contact["etat"], "à rappeler par un humain")
        self.assertIn("Demande du client", contact["detail"])

    def test_la_prise_de_rendez_vous_le_garde_aussi(self):
        _, etats = self._rien_de_conclu(
            "prise_rdv", [f"M. Hésite;{self.NUMERO};Bilan initial"])
        self.assertEqual(etats["M. Hésite"]["etat"],
                         "à rappeler par un humain")

    def test_le_creneau_libere_confirme_le_rendez_vous_et_garde_la_place(self):
        """⚠ LE CŒUR DE LA DÉCISION. « On n'a pas pu définir si vous êtes
        intéressé, alors il conserve son rendez-vous, et le rendez-vous passe en
        confirmé. » La place, elle, reste à pourvoir : d'où l'état « refusé »,
        qui dit la vérité sur LA PLACE — la phrase, elle, dit la vérité sur la
        personne.
        """
        base = self.application.base
        horaire = (datetime.datetime.now() + datetime.timedelta(days=9)
                   ).replace(hour=14, minute=30, second=0, microsecond=0
                             ).isoformat(timespec="minutes")
        client = base.ajouter_client("Mme Peut-être", self.NUMERO)
        rdv = base.ajouter_rendezvous(client, horaire, "Bilan", statut="prévu")
        campagne, etats = self._rien_de_conclu(
            "creneau_libere", [f"Mme Peut-être;{self.NUMERO};{horaire};Bilan"],
            info_creneau_libere=self._place_libre())
        contact = etats["Mme Peut-être"]
        self.assertEqual(contact["etat"], "refusé")
        self.assertNotEqual(contact["etat"], "à rappeler par un humain")
        # Son rendez-vous est CONSERVÉ, et il passe en « confirmé ».
        self.assertEqual(base.obtenir_rendezvous(rdv)["statut"], "confirmé")
        self.assertEqual(base.obtenir_rendezvous(rdv)["horaire"], horaire)
        # Et l'écran le dit en mots, sans rien affirmer sur la personne.
        self.assertIn("pas pu déterminer si cette personne était intéressée",
                      contact["detail"])
        self.assertIn("conserve son rendez-vous", contact["detail"])
        self.assertIn("confirmé", contact["detail"])
        # Le changement de statut entre au cahier : c'est à reporter.
        genres = [c["genre"] for c in base.changements_de_campagne(campagne)]
        self.assertIn("confirmation", genres)

    def test_sans_rendez_vous_connu_rien_n_est_confirme_et_l_ecran_le_dit(self):
        """⚠ JAMAIS UN RENDEZ-VOUS INVENTÉ. Une ligne collée dont le rendez-vous
        n'existe PAS dans l'agenda de RingBack n'a rien à confirmer : la phrase
        le dit, plutôt que de laisser croire à une confirmation.

        (La date collée n'est qu'une information dite à l'agent — elle ne crée
        aucun rendez-vous, et c'est justement ce que cet essai exploite.)
        """
        base = self.application.base
        horaire = (datetime.datetime.now() + datetime.timedelta(days=9)
                   ).replace(hour=14, minute=30, second=0, microsecond=0
                             ).isoformat(timespec="minutes")
        _, etats = self._rien_de_conclu(
            "creneau_libere", [f"M. Collé Seul;{self.NUMERO};{horaire};Bilan"],
            info_creneau_libere=self._place_libre())
        contact = etats["M. Collé Seul"]
        self.assertEqual(contact["etat"], "refusé")
        self.assertIn("aucun rendez-vous connu", contact["detail"])
        # Et aucun rendez-vous n'a été inventé pour lui. (La base porte les
        # données de démonstration : on regarde LUI, pas l'agenda entier.)
        self.assertEqual([r for r in base.tous_les_rendezvous()
                          if r["nom"] == "M. Collé Seul"], [])

    def _sans_suite(self, nature):
        """Une campagne de `nature` où la personne ne conclut rien.

        ⚠ UN SEUL CONTACT PAR ESSAI, et pas une boucle sur les deux natures :
        la série de numéros de fiction n'autorise que ses deux derniers chiffres
        à varier, deux contacts distincts terminés par « 55 » n'existent donc
        pas — et la règle du numéro unique refuserait le second.
        """
        base = self.application.base
        horaire = (datetime.datetime.now() + datetime.timedelta(days=6)
                   ).replace(hour=9, minute=15, second=0, microsecond=0
                             ).isoformat(timespec="minutes")
        client = base.ajouter_client("Mme Sans Suite", self.NUMERO)
        rdv = base.ajouter_rendezvous(client, horaire, "Séance", statut="prévu")
        _, etats = self._rien_de_conclu(
            nature, [f"Mme Sans Suite;{self.NUMERO};{horaire};Séance"])
        contact = etats["Mme Sans Suite"]
        self.assertEqual(contact["etat"], "le client rappellera")
        # ⚠ CET ESSAI DISAIT L'INVERSE JUSQU'AU 17/08/2026 : « son rendez-vous
        # n'est pas touché ». Sa règle de ce jour-là : « si la personne doit
        # rappeler, le rendez-vous est simplement annulé » — le créneau ne reste
        # pas bloqué pour quelqu'un qui vient de dire qu'il ne viendra pas comme
        # prévu. La DATE, elle, ne bouge toujours pas : on n'invente rien.
        self.assertIn("ANNULÉ", contact["detail"])
        self.assertEqual(base.obtenir_rendezvous(rdv)["statut"], "annulé")
        self.assertEqual(base.obtenir_rendezvous(rdv)["horaire"], horaire)

    def test_le_rappel_de_rendez_vous_dit_que_le_client_rappellera(self):
        """Ici le rendez-vous est LE SIEN : il peut vraiment nous rappeler, et
        rien n'attend de notre côté."""
        self._sans_suite("rappel_rdv")

    def test_la_confirmation_dit_aussi_que_le_client_rappellera(self):
        """⚠ ET SON RENDEZ-VOUS RESTE « PRÉVU ». Le passer « confirmé » d'office
        sur une campagne de CONFIRMATION inventerait la confirmation qu'on n'a
        justement pas obtenue — c'est le seul but de cette campagne."""
        self._sans_suite("confirmation")

    def test_le_discours_ne_propose_le_rappel_humain_que_la_ou_il_existe(self):
        """CLIQUET. La phrase dite au téléphone et le comportement doivent aller
        ensemble : proposer un rappel humain sur une nature qui n'en fait pas un
        serait promettre ce qu'on ne tient pas — et l'inverse (le faire sans
        l'avoir proposé) était le cas de « prise de rendez-vous » avant ce jour.
        """
        for nature, fiche in assistant.NATURES.items():
            with self.subTest(nature=nature):
                propose = ("rappelée par un humain"
                           in fiche["issues"]["autre"]["quand"])
                self.assertEqual(
                    propose, nature in assistant.NATURES_RAPPEL_HUMAIN,
                    fiche["issues"]["autre"]["quand"])


class TestColonneProchainRdv(_CampagneAssistant):
    """⚠ LA DEMANDE DU 11/08/2026, mot pour mot : « dans le tableau des contacts,
    à la place de la colonne "détail" j'ai la colonne "Prochain rdv" et la date
    au format jj/mm/aaaa hh:mm ».

    Ce que ces essais tiennent en plus du libellé : la colonne lit l'AGENDA, pas
    la copie figée que la campagne a faite à sa création. C'est tout son
    intérêt — après un appel qui déplace un rendez-vous, elle montre la nouvelle
    date.
    """

    def _page(self, campagne_id):
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        return page.split("</head>", 1)[-1]   # jamais la feuille de style

    def _cases(self, corps, nom):
        """Les cellules de la ligne de `nom`, texte nu."""
        for bloc in re.findall(r"<tr[^>]*>\s*<td>\d+</td>.*?</tr>", corps,
                              re.S):
            cases = [" ".join(re.sub(r"<[^>]+>", " ", c).split())
                     for c in re.findall(r"<td>(.*?)</td>", bloc, re.S)]
            if len(cases) > 1 and nom in cases[1]:
                return cases
        return None

    def _campagne_avec_rendezvous(self, quand, numero):
        """Un contact qui a un VRAI rendez-vous dans l'agenda.

        Le collage porte quatre colonnes (nom, numéro, horaire, motif) : c'est
        ce que la nature « confirmation » demande. L'horaire collé n'est qu'une
        information dite à l'agent — le rendez-vous de l'AGENDA, celui que la
        colonne « Prochain rdv » lit, est celui créé juste au-dessus.
        """
        base = self.application.base
        client = base.ajouter_client("Mme Agenda Exemple", numero)
        rdv = base.ajouter_rendezvous(client, quand, "Bilan", statut="prévu")
        campagne = self._campagne(
            "confirmation", [f"Mme Agenda Exemple;{numero};{quand};Bilan"])
        return campagne, client, rdv

    def test_la_colonne_remplace_detail_et_porte_le_format_demande(self):
        quand = (datetime.datetime.now() + datetime.timedelta(days=9)).replace(
            hour=14, minute=30, second=0, microsecond=0)
        campagne, _, _ = self._campagne_avec_rendezvous(
            quand.isoformat(timespec="minutes"), "+33 6 00 00 00 51")
        corps = self._page(campagne)
        # ⚠ RENOMMÉE LE 21/08/2026 : elle ne dit plus seulement le
        # PROCHAIN rendez-vous, mais ce que ce rendez-vous est DEVENU
        # quand la campagne l'a annulé (son signalement du même jour).
        self.assertIn("<th>Son rendez-vous</th>", corps)
        self.assertNotIn("<th>Prochain rdv</th>", corps)
        self.assertNotIn("<th>Détail</th>", corps)
        cases = self._cases(corps, "Mme Agenda Exemple")
        self.assertIsNotNone(cases, corps[:400])
        # jj/mm/aaaa hh:mm — exactement le format demandé, rien d'autre.
        self.assertEqual(cases[4], quand.strftime("%d/%m/%Y %H:%M"))
        self.assertRegex(cases[4], r"^\d{2}/\d{2}/\d{4} \d{2}:\d{2}$")

    def test_elle_suit_l_agenda_apres_un_appel_qui_deplace(self):
        """⚠ LE POINT DE LA COLONNE. Elle lit l'agenda MAINTENANT, pas la copie
        que la campagne a faite d'un rendez-vous à sa création : sinon elle
        annoncerait encore l'ancienne date après un déplacement accepté.

        « 54 » propose une autre date, deux jours plus tard à 9h30 (convention
        déterministe du simulateur, voir calle_client._date_deplacee).
        """
        quand = (datetime.datetime.now() + datetime.timedelta(days=9)).replace(
            hour=14, minute=30, second=0, microsecond=0)
        campagne, _, _ = self._campagne_avec_rendezvous(
            quand.isoformat(timespec="minutes"), "+33 6 00 00 00 54")
        avant = self._cases(self._page(campagne), "Mme Agenda Exemple")[4]
        self.assertEqual(avant, quand.strftime("%d/%m/%Y %H:%M"))
        self._derouler(campagne)
        apres = self._cases(self._page(campagne), "Mme Agenda Exemple")[4]
        attendu = (quand + datetime.timedelta(days=2)).replace(hour=9, minute=30)
        self.assertEqual(apres, attendu.strftime("%d/%m/%Y %H:%M"))
        self.assertNotEqual(apres, avant)

    def test_un_contact_sans_rendez_vous_a_venir_montre_un_tiret(self):
        """Jamais une date inventée, et jamais une case vide sans explication :
        un tiret dit « rien à cette date-là », ce qui est vrai."""
        campagne = self._campagne(
            "prise_rdv", ["M. Sans Agenda;+33 6 00 00 00 52;Bilan initial"])
        cases = self._cases(self._page(campagne), "M. Sans Agenda")
        self.assertEqual(cases[4], "—")

    def test_la_case_d_etat_ne_porte_que_l_etat(self):
        """⚠ CORRIGE UNE PREMIÈRE TENTATIVE (11/08/2026). Le détail avait été
        glissé sous la pastille d'état ; le propriétaire l'a redit sans détour :
        « je t'ai demandé de supprimer la position, pas de le mettre dans une
        autre colonne ». La case d'état porte donc l'état, et rien d'autre.
        """
        quand = (datetime.datetime.now() + datetime.timedelta(days=9)).replace(
            hour=14, minute=30, second=0, microsecond=0)
        campagne, _, _ = self._campagne_avec_rendezvous(
            quand.isoformat(timespec="minutes"), "+33 6 00 00 00 51")
        cases = self._cases(self._page(campagne), "Mme Agenda Exemple")
        self.assertEqual(cases[3], "⏳ à appeler")


class TestDateChiffree(unittest.TestCase):
    """Le format jj/mm/aaaa hh:mm, et ce qu'il fait d'une valeur illisible."""

    def test_le_format_demande_et_rien_d_autre(self):
        self.assertEqual(assistant.date_chiffree("2026-08-03T14:00"),
                         "03/08/2026 14:00")
        # Avec les secondes, ou sans les minutes : la sortie ne change pas.
        self.assertEqual(assistant.date_chiffree("2026-08-03T14:00:00"),
                         "03/08/2026 14:00")

    def test_une_valeur_vide_ou_illisible_ne_rend_aucune_date(self):
        """⚠ JAMAIS UNE DATE INVENTÉE. Une valeur qu'on ne sait pas lire rend
        une chaîne vide, à charge de l'écran d'afficher son tiret — plutôt que
        d'afficher aujourd'hui, ou une date par défaut."""
        for valeur in ("", None, "   ", "demain", "2026-13-45T99:99", 42):
            with self.subTest(valeur=valeur):
                self.assertEqual(assistant.date_chiffree(valeur), "")


class _ClientQuiNeRepondJamais(calle_client.ClientAppels):
    """Personne ne décroche, JAMAIS — et ce n'est pas un `AppelSimule`.

    ⚠ CE DÉTAIL EST TOUT L'INTÉRÊT DE CETTE CLASSE. Depuis le 20/08/2026, le
    plafond de rappels est levé quand les appels sont SIMULÉS (sa demande :
    « en simulation, pas de finalité plafond atteint »). Un essai qui veut
    éprouver ce que fait le plafond doit donc sortir de la simulation — sans
    pour autant composer quoi que ce soit.
    """

    def appeler(self, nom_client, telephone, rendezvous, mission=None,
                consigne=None, nature=None):
        raise calle_client.PasDeReponse("personne ne décroche")

    def appeler_cascade(self, nom_client, telephone, mission, creneau,
                        consigne=None, nature=None):
        raise calle_client.PasDeReponse("personne ne décroche")


class TestRienNeDisparaitDuPlanning(_CampagneAssistant):
    """⚠ SON SIGNALEMENT DU 20/08/2026, sur sa campagne n° 118 :

    « j'avais 3 numéros à confirmer, un a abouti, l'autre c'est une demande de
    rappel et enfin la troisième a disparu (n'est plus présente dans le
    calendrier de la page rendez-vous). »

    Elle n'avait pas disparu : son rendez-vous était ANNULÉ — elle l'avait
    demandé pendant l'appel, et le message de la campagne le lui PROMET
    (« si aucune ne vous convient, j'annule votre rendez-vous »). Le défaut
    était ailleurs : la grille ne montre que ce qui OCCUPE une place, et la
    page n'offrait aucun autre endroit où le retrouver.

    ⚠ PIRE : LA LÉGENDE LE PROMETTAIT DÉJÀ — « il n'apparaît donc pas ici mais
    dans les listes ci-dessous » — alors qu'il n'y avait AUCUNE liste en
    dessous. Une promesse d'écran non tenue coûte plus cher qu'un silence :
    elle l'a envoyé chercher, et il n'a rien trouvé.

    Son choix du 20/08 : garder l'annulation (l'agent l'a promise à la
    personne), et la RENDRE VISIBLE.
    """

    def _rdv(self, nom, terminaison, heure, statut="prévu", prefixe="00 00 00"):
        base = self.application.base
        client = base.ajouter_client(nom, f"+33 6 {prefixe} {terminaison}")
        quand = (datetime.datetime.now() + datetime.timedelta(days=2)).replace(
            hour=heure, minute=0, second=0, microsecond=0)
        rdv = base.ajouter_rendezvous(client, quand.isoformat(timespec="minutes"),
                                      "Séance", statut=statut)
        return rdv, quand

    def _semaine(self, quand):
        annee, semaine, _ = quand.isocalendar()
        _, page = self._obtenir(f"/suivi?annee={annee}&semaine={semaine}")
        return page

    # ------------------------------------------------------------ LA RÈGLE
    def test_un_rendezvous_annule_reste_lisible_sur_la_page(self):
        """LA RÈGLE : rien ne disparaît de la page Rendez-vous. Ce qui n'occupe
        plus de place n'est pas dans la grille — c'est voulu — mais il se lit
        juste en dessous, avec ce qui l'a fait sortir."""
        base = self.application.base
        rdv, quand = self._rdv("Mme Partie", "51", 9, statut="annulé")
        page = self._semaine(quand)
        visible = _zone_visible(page)
        self.assertIn("Mme Partie", visible)
        self.assertIn("ne sont", visible)
        self.assertIn("plus au planning", visible)
        # Et il porte son statut, pas un mot inventé.
        self.assertIn("annulé", visible)

    def test_les_quatre_statuts_qui_sortent_du_planning_sont_là(self):
        """⚠ LA RÈGLE, PAS LE CAS. Ce n'est pas « les annulés » qu'on montre :
        c'est TOUT ce qui a rendu sa place. La légende en nomme quatre — elle
        ne peut pas en promettre quatre et n'en montrer qu'un."""
        base = self.application.base
        attendus = {}
        for rang, statut in enumerate(("annulé", "déplacé", "manqué", "ignoré"),
                                      start=1):
            nom = f"M. {statut.capitalize()} Essai"
            rdv, quand = self._rdv(nom, "51", 8 + rang, statut=statut,
                                   prefixe=f"00 00 0{rang}")
            attendus[nom] = statut
        visible = _zone_visible(self._semaine(quand))
        for nom, statut in attendus.items():
            with self.subTest(statut=statut):
                self.assertIn(nom, visible)

    def test_ce_qui_occupe_une_place_reste_dans_la_grille(self):
        """LA CONTRE-ÉPREUVE : la liste ne double pas la grille. Un rendez-vous
        prévu ou confirmé occupe sa place — il n'a rien à faire dans une liste
        de ce qui n'en occupe plus."""
        base = self.application.base
        rdv, quand = self._rdv("Mme Bien Là", "51", 9, statut="prévu")
        page = self._semaine(quand)
        # Elle est dans la GRILLE — c'est sa tuile qui la porte.
        grille = page[page.index('<table class="planning"'):]
        grille = grille[:grille.index("</table>")]
        self.assertIn("Mme Bien Là", grille)
        # Et PAS dans la liste de ce qui n'occupe plus de place.
        self.assertNotIn("Mme Bien Là", self._liste_des_sorties(page))

    def _liste_des_sorties(self, page):
        """Le bloc « plus au planning » seul, ou "" s'il n'y en a pas."""
        if "plus au planning" not in page:
            return ""
        bloc = page[page.index('<details class="carte sorties-planning">'):]
        return bloc[:bloc.index("</details>")]

    def test_la_raison_est_celle_du_cahier_des_changements(self):
        """⚠ ON NE RÉINVENTE PAS LE POURQUOI. La raison vient du cahier des
        changements — sa DERNIÈRE ligne pour ce rendez-vous, celle qui explique
        le statut actuel — et le lien ramène à la campagne qui l'a écrite."""
        base = self.application.base
        rdv, quand = self._rdv("Mme Annulée Par Appel", "51", 10)
        campagne_id = base.creer_campagne("Essai confirmation", "confirmation",
                                          mission="Bonjour.",
                                          nature="confirmation")
        contact = base.ajouter_contact_campagne(
            campagne_id, 1, "Mme Annulée Par Appel", "+33 6 00 00 00 51",
            rendezvous_id=rdv)
        assistant.noter_changement(
            base, base.obtenir_campagne(campagne_id),
            base.obtenir_contact_campagne(contact), "annulation",
            rendezvous_id=rdv, raison="elle a annulé pendant l'appel")
        base.mettre_a_jour_rendezvous(rdv, statut="annulé")
        visible = _zone_visible(self._semaine(quand))
        self.assertIn("elle a annulé pendant l&#x27;appel", visible)
        self.assertIn(f'href="/campagne?id={campagne_id}"', visible)

    def test_un_rendezvous_annule_a_la_main_n_invente_aucune_raison(self):
        """⚠ ON N'INVENTE RIEN. Un rendez-vous annulé depuis sa fiche n'a pas de
        ligne au cahier : la colonne reste vide, et c'est honnête."""
        base = self.application.base
        rdv, quand = self._rdv("M. Annulé À La Main", "51", 11,
                               statut="annulé")
        visible = _zone_visible(self._semaine(quand))
        self.assertIn("M. Annulé À La Main", visible)
        self.assertNotIn("pendant l&#x27;appel", visible)

    def test_la_legende_ne_promet_que_ce_qui_existe(self):
        """⚠ CE QUI L'A ENVOYÉ CHERCHER POUR RIEN. La légende annonçait « les
        listes ci-dessous » alors qu'il n'y en avait AUCUNE. Une promesse
        d'écran non tenue coûte plus cher qu'un silence."""
        base = self.application.base
        rdv, quand = self._rdv("Mme Partie", "51", 9, statut="annulé")
        visible = _zone_visible(self._semaine(quand))
        self.assertIn("dans la liste ci-dessous", visible)
        # ET LA LISTE EXISTE VRAIMENT, dans la même page.
        indice_legende = visible.index("dans la liste ci-dessous")
        self.assertGreater(visible.index("plus au planning"), indice_legende)


class TestConfirmationOrdreEtDejaConfirmes(_TestAvecServeurWeb):
    """⚠ SES DEUX DEMANDES DU 20/08/2026 sur la campagne de confirmation :

    · « Étape 2 avancé : choisir mettre par défaut pour l'ordre d'appel
      "ordre de la liste" » ;
    · « N'importer que les contacts dont les rendez-vous n'ont pas été
      confirmé. »

    Les deux se tiennent : on confirme les rendez-vous d'une journée qu'on vient
    de désigner — ils sont déjà dans l'ordre où on veut les traiter — et
    demander « serez-vous présent ? » à quelqu'un qui a déjà répondu, c'est le
    rappeler pour rien.
    """

    def setUp(self):
        super().setUp()
        base = self.application.base
        horaires.definir_semaine(
            self.application.preferences,
            {jour: [(8 * 60, 19 * 60)] for jour in range(7)})
        self.jour = datetime.date.today() + datetime.timedelta(days=2)
        self.rdvs = {}
        for rang, (nom, statut) in enumerate((("Mme Prévue", "prévu"),
                                              ("M. Déjà Confirmé", "confirmé"),
                                              ("Mme Autre", "prévu")), start=1):
            client = base.ajouter_client(nom, f"+33 6 00 00 00 {60 + rang}")
            quand = datetime.datetime.combine(
                self.jour, datetime.time(9 + rang, 0)).isoformat(
                    timespec="minutes")
            self.rdvs[nom] = base.ajouter_rendezvous(client, quand, "Séance",
                                                     statut=statut)

    def _identifiants(self):
        return [str(i) for i in self.rdvs.values()]

    def _brouillon_de(self, chemin):
        _, page = self._poster(chemin, {"rdv": self._identifiants()})
        b = re.search(r'name="b" value="(\d+)"', page).group(1)
        return self.application.obtenir_brouillon_assistant(b), page

    # -------------------------------------------------- ① L'ORDRE PAR DÉFAUT
    def test_l_ordre_de_la_liste_est_propose_d_office(self):
        """⚠ L'écran affichait « — à choisir — », et un ordre non choisi est un
        champ obligatoire de plus à chaque campagne. C'est le même mécanisme que
        pour le déplacement, réglé le 16/08 : `ordre_defaut` de la nature."""
        brouillon, _ = self._brouillon_de("/suivi/plage/confirmation")
        self.assertEqual(brouillon["ordre"], "liste")
        # ⚠ CE QU'IL VOIT À L'ÉCRAN est éprouvé juste en dessous
        # (`test_le_selecteur_de_l_etape_2_le_montre_selectionne`) : une valeur
        # posée en mémoire et un sélecteur qui affiche autre chose, c'est
        # exactement le défaut du « réglage ignoré ».

    def test_le_selecteur_de_l_etape_2_le_montre_selectionne(self):
        """⚠ ON NE MESURE PAS LA VALEUR EN MÉMOIRE, MAIS CE QU'IL VOIT. Un
        défaut posé en base et un sélecteur qui affiche autre chose, c'est
        exactement le défaut du « réglage ignoré »."""
        _, page = self._poster("/suivi/plage/confirmation",
                               {"rdv": self._identifiants()})
        b = re.search(r'name="b" value="(\d+)"', page).group(1)
        _, etape2 = self._obtenir(f"/assistant/message?b={b}")
        selecteur = etape2[etape2.index('name="ordre"'):]
        selecteur = selecteur[:selecteur.index("</select>")]
        choisi = re.search(r'value="([^"]*)" selected', selecteur)
        self.assertIsNotNone(choisi, "aucune option sélectionnée")
        self.assertEqual(choisi.group(1), "liste")

    def test_les_autres_ordres_restent_offerts(self):
        """LA CONTRE-ÉPREUVE : c'est un défaut, pas une contrainte."""
        _, page = self._poster("/suivi/plage/confirmation",
                               {"rdv": self._identifiants()})
        b = re.search(r'name="b" value="(\d+)"', page).group(1)
        _, etape2 = self._obtenir(f"/assistant/message?b={b}")
        selecteur = etape2[etape2.index('name="ordre"'):]
        selecteur = selecteur[:selecteur.index("</select>")]
        for code in assistant.ORDRES_APPEL:
            self.assertIn(f'value="{code}"', selecteur)

    # ------------------------------------------ ② LES DÉJÀ CONFIRMÉS ÉCARTÉS
    def test_un_rendezvous_deja_confirme_n_entre_pas(self):
        """⚠ Demander « serez-vous présent ? » à quelqu'un qui a déjà répondu,
        c'est le rappeler pour rien — et cela coûte un appel à chaque fois."""
        brouillon, page = self._brouillon_de("/suivi/plage/confirmation")
        noms = [c["nom"] for c in brouillon["contacts"]]
        self.assertEqual(noms, ["Mme Prévue", "Mme Autre"])
        self.assertNotIn("M. Déjà Confirmé", noms)
        # ⚠ ET L'ÉCART EST DIT, PAS TU. Sans cela il compterait ses
        # rendez-vous et n'en retrouverait pas le compte — le défaut n° 7.
        self.assertIn("1 rendez-vous déjà confirmé(s) écarté(s)", page)
        self.assertIn("2 personne(s) reprise(s)", page)

    def test_les_autres_natures_reprennent_tout_le_monde(self):
        """LA BORNE : le filtre ne vaut QUE pour la confirmation. Un rendez-vous
        confirmé se déplace et se rappelle comme les autres — l'écarter des
        trois autres campagnes serait un bien pire défaut."""
        for chemin in ("/suivi/plage/deplacement", "/suivi/plage/rappel-rdv"):
            with self.subTest(chemin=chemin):
                brouillon, _ = self._brouillon_de(chemin)
                noms = [c["nom"] for c in brouillon["contacts"]]
                self.assertIn("M. Déjà Confirmé", noms)
                self.assertEqual(len(noms), 3)

    def test_le_filtre_est_le_meme_pour_toutes_les_voies_d_import(self):
        """⚠ TROIS VOIES D'IMPORT, UN SEUL FILTRE. La plage du planning, le
        bouton « importer » de l'étape ③ et la règle automatique passent tous
        par `ecarter_les_deja_confirmes` — trois filtres séparés auraient fini
        par diverger."""
        base = self.application.base
        contacts = [{"nom": nom, "telephone": f"+33 6 00 00 00 6{rang}",
                     "champs": {}, "rendezvous_id": rdv}
                    for rang, (nom, rdv) in enumerate(self.rdvs.items(),
                                                      start=1)]
        gardes, ecartes = assistant.ecarter_les_deja_confirmes(
            base, "confirmation", contacts)
        self.assertEqual([c["nom"] for c in gardes],
                         ["Mme Prévue", "Mme Autre"])
        self.assertEqual(ecartes, 1)
        # Et sur les autres natures, rien n'est écarté.
        for nature in ("deplacement", "rappel_rdv", "creneau_libere", None):
            with self.subTest(nature=nature):
                gardes, ecartes = assistant.ecarter_les_deja_confirmes(
                    base, nature, contacts)
                self.assertEqual(len(gardes), 3)
                self.assertEqual(ecartes, 0)

    def test_un_contact_sans_rendezvous_connu_est_garde(self):
        """⚠ ON NE DEVINE PAS. Une ligne collée à la main peut n'avoir aucun
        rendez-vous en base : la déclarer confirmée reviendrait à la perdre en
        silence, et c'est exactement ce qu'il ne faut jamais faire."""
        base = self.application.base
        colle = [{"nom": "M. Collé à La Main",
                  "telephone": "+33 6 00 00 00 99", "champs": {}}]
        gardes, ecartes = assistant.ecarter_les_deja_confirmes(
            base, "confirmation", colle)
        self.assertEqual(len(gardes), 1)
        self.assertEqual(ecartes, 0)

    def test_la_campagne_creee_n_appelle_pas_le_deja_confirme(self):
        """LE BOUT DU CHEMIN : ce n'est pas la grille qu'on mesure, c'est la
        campagne — et surtout QUI elle appelle."""
        base = self.application.base
        _, page = self._poster("/suivi/plage/confirmation",
                               {"rdv": self._identifiants()})
        b = re.search(r'name="b" value="(\d+)"', page).group(1)
        self._poster("/assistant/message", {
            "b": b, "action": "continuer", "info_entreprise": "Cabinet Essai",
            "ordre": "liste"})
        brouillon = self.application.obtenir_brouillon_assistant(b)
        donnees = {"b": b, "action": "valider"}
        for rang, contact in enumerate(brouillon["contacts"], start=1):
            donnees[f"nom_{rang}"] = contact["nom"]
            donnees[f"tel_{rang}"] = contact["telephone"]
            for code, valeur in (contact.get("champs") or {}).items():
                donnees[f"c_{code}_{rang}"] = valeur
        self._poster("/assistant/liste", donnees)
        campagne_id = base.lister_campagnes()[0]["id"]
        noms = [c["nom"] for c in base.contacts_de_campagne(campagne_id)]
        self.assertNotIn("M. Déjà Confirmé", noms)
        self.assertEqual(len(noms), 2)


class TestClorreUneCampagnePrete(_CampagneAssistant):
    """⚠ SA DEMANDE DU 21/08/2026 : « clos ces campagnes ».

    Le bouton « Clore » ne s'affichait que sur une campagne EN COURS. Une
    campagne préparée puis abandonnée ne pouvait donc pas être fermée : il
    aurait fallu la DÉMARRER pour pouvoir la clore — c'est-à-dire faire sonner
    des téléphones pour rien.

    CE QUE CELA A COÛTÉ, mesuré dans sa base : **125 contacts** dormaient dans
    sept campagnes « prête » des 15 et 17/08, dont les rendez-vous avaient
    disparu depuis. Il n'avait aucun geste pour s'en débarrasser.
    """

    def _prete(self):
        base = self.application.base
        horaires.definir_semaine(self.application.preferences,
                                 {j: [(8 * 60, 19 * 60)] for j in range(7)})
        quand = (datetime.datetime.now() + datetime.timedelta(days=3)).replace(
            hour=10, minute=0, second=0, microsecond=0).isoformat(
                timespec="minutes")
        numero = "+33 6 00 00 00 51"
        rdv = base.ajouter_rendezvous(
            base.ajouter_client("M. Préparé", numero), quand, "Séance",
            statut="prévu")
        campagne_id = self._campagne(
            "deplacement", [f"M. Préparé;{numero};{quand};Séance"],
            politique="tous", relance_max="0")
        self.assertEqual(base.obtenir_campagne(campagne_id)["statut"], "prête")
        return campagne_id, rdv

    def test_le_bouton_clore_existe_sur_une_campagne_prete(self):
        """Sans lui, la seule façon de fermer une campagne préparée était de la
        LANCER d'abord. Le libellé dit ce que le geste fait ici : « je ne la
        lancerai pas » — ce n'est pas la même chose qu'annuler des relances."""
        campagne_id, _ = self._prete()
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        visible = _zone_visible(page)
        self.assertIn('action="/campagne/clore"', visible)
        self.assertIn("Clore — je ne la lancerai pas", visible)

    def test_clore_une_prete_n_appelle_personne_et_ne_touche_a_rien(self):
        """⚠ LA GARANTIE : fermer n'est pas lancer. Aucun téléphone, aucun
        rendez-vous touché — et surtout PAS la règle du 20/08 qui annule les
        déplacements non faits : ici on n'a jamais essayé de les faire."""
        base = self.application.base
        campagne_id, rdv = self._prete()
        contact = base.contacts_de_campagne(campagne_id)[0]
        self._poster("/campagne/clore", {"campagne": campagne_id})
        self.assertEqual(base.obtenir_campagne(campagne_id)["statut"], "close")
        self.assertEqual(base.appels_du_contact_campagne(contact["id"]), [])
        # LE RENDEZ-VOUS EST INTACT : on n'a jamais tenté de le déplacer.
        self.assertEqual(base.obtenir_rendezvous(rdv)["statut"], "prévu")
        self.assertEqual(
            [c for c in base.changements_de_campagne(campagne_id)
             if c["genre"] in ("annulation", "suppression")], [])

    def test_une_campagne_close_ne_montre_plus_le_bouton(self):
        """LA CONTRE-ÉPREUVE : le geste ne s'offre que là où il a un sens."""
        campagne_id, _ = self._prete()
        self._poster("/campagne/clore", {"campagne": campagne_id})
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertNotIn('action="/campagne/clore"', _zone_visible(page))


class TestLesCompteursNeMontrentQueCeQuiExiste(_CampagneAssistant):
    """⚠ SA DEMANDE DU 30/08/2026 : « que les résumés des états ne s'affichent
    que lorsqu'il y a au moins un contact concerné. Donc tous ceux à 0 seraient
    cachés. »

    Les DIX états étaient affichés, zéro compris. C'était une décision — « la
    vue d'ensemble honnête », montrer les états pour qu'on sache qu'ils
    existent. À l'usage, sa campagne du 30/08 alignait dix pastilles dont huit
    à zéro : il fallait les lire toutes pour trouver les deux qui disent
    quelque chose.
    """

    @staticmethod
    def _numero(terminaison, prefixe="00 00 00"):
        """⚠ CONSTRUIT, JAMAIS ÉCRIT EN DUR (`preparer_publication.py` refuse)."""
        return f"+33 6 {prefixe} {terminaison}"

    def _pastilles(self, page):
        """Les pastilles du résumé, {mot: nombre} — celles-là SEULEMENT.

        ⚠ ON LIT LE PREMIER PARAGRAPHE DE PASTILLES, pas la page : le tableau
        des personnes en porte une par ligne (son état), et les compter avec
        le résumé ferait dire n'importe quoi à cet essai.
        """
        visible = _zone_visible(page)
        debut = visible.index('<p style="display:flex;gap:.4rem;flex-wrap:wrap">')
        bloc = visible[debut:visible.index("</p>", debut)]
        return {mot.strip(): int(nombre) for mot, nombre in re.findall(
            r'<span class="pastille [^"]*">[^<]*?\s(\D+?)\s:\s(\d+)</span>',
            bloc)}

    def _campagne_deroulee(self):
        """Une campagne menée à son terme : quelques états atteints, pas tous."""
        campagne = self._campagne(
            "confirmation",
            [f"M. Un;{self._numero('51')};{DEMAIN};Séance",
             f"Mme Deux;{self._numero('52')};{DEMAIN};Séance"])
        self._derouler(campagne)
        _, page = self._obtenir(f"/campagne?id={campagne}")
        return page

    def test_aucun_zero_n_est_affiche(self):
        """⚠ LE CŒUR DE SA DEMANDE, mesuré sur les NOMBRES : pas une pastille du
        résumé ne porte zéro."""
        pastilles = self._pastilles(self._campagne_deroulee())
        self.assertTrue(pastilles, "le résumé est vide")
        for mot, nombre in pastilles.items():
            with self.subTest(etat=mot):
                self.assertGreater(nombre, 0, f"« {mot} » est affiché à zéro")

    def test_ce_qui_existe_est_toujours_là(self):
        """LA MOITIÉ QUI MANQUERAIT SINON : « aucun zéro » serait aussi vrai d'un
        résumé VIDE. On vérifie que la somme des pastilles couvre bien tous les
        contacts de la campagne."""
        page = self._campagne_deroulee()
        pastilles = self._pastilles(page)
        campagne = self.application.base.lister_campagnes()[0]["id"]
        contacts = self.application.base.contacts_de_campagne(campagne)
        self.assertEqual(sum(pastilles.values()), len(contacts))
        # Et chaque état réellement atteint a SA pastille.
        for contact in contacts:
            mot = assistant.mot_etat(contact["etat"])
            with self.subTest(etat=mot):
                self.assertIn(mot, pastilles)

    def test_une_campagne_neuve_n_annonce_que_ce_qui_reste_a_faire(self):
        """Avant le premier appel, un seul état concerne quelqu'un."""
        campagne = self._campagne(
            "confirmation", [f"M. Un;{self._numero('51')};{DEMAIN};Séance"])
        _, page = self._obtenir(f"/campagne?id={campagne}")
        self.assertEqual(self._pastilles(page), {"à appeler": 1})

    def test_sans_aucun_contact_il_n_y_a_pas_de_ligne_vide(self):
        """⚠ LA CONTRE-ÉPREUVE. Tous les compteurs à zéro laissaient un
        paragraphe vide — un blanc dans la page que personne ne s'explique."""
        base = self.application.base
        campagne = base.creer_campagne("Sans personne", "confirmation",
                                       mission="Bonjour.",
                                       nature="confirmation")
        _, page = self._obtenir(f"/campagne?id={campagne}")
        visible = _zone_visible(page)
        self.assertNotIn('<p style="display:flex;gap:.4rem;flex-wrap:wrap"></p>',
                         visible)
        self.assertIn("Les personnes, une par une", visible)


class TestLaListeDAbordLesDetailsEnsuite(_CampagneAssistant):
    """⚠ SA DEMANDE DU 30/08/2026 : « je ne veux que "Les personnes, une par
    une" de visible, et en dessous un lien "voir les détails" ».

    Trois tableaux se succédaient sur la fiche d'une campagne, et celui qu'il
    regarde PENDANT qu'elle tourne arrivait en troisième. Les deux autres ne
    parlent pas des appels en cours : ils disent ce qu'il faudra reporter
    ailleurs, et les places qu'une annulation a libérées. On les lit après.

    ⚠ RIEN N'EST RETIRÉ, TOUT EST REPLIÉ. Ces deux tableaux portent des gestes
    (copier le cahier, monter une campagne sur une place libérée). Les cacher
    pour de bon rejouerait le défaut du 21/08, quand un onglet retiré a
    emporté son seul bouton avec lui.
    """

    @staticmethod
    def _numero(terminaison, prefixe="00 00 00"):
        """⚠ CONSTRUIT, JAMAIS ÉCRIT EN DUR (`preparer_publication.py` refuse)."""
        return f"+33 6 {prefixe} {terminaison}"

    def _campagne_avec_les_trois(self):
        """Une campagne qui porte les TROIS tableaux : une confirmation où rien
        n'est conclu annule le rendez-vous, ce qui remplit le cahier ET libère
        une place à compenser."""
        horaires.definir_semaine(self.application.preferences,
                                 {j: [(8 * 60, 19 * 60)] for j in range(7)})
        base = self.application.base
        numero = self._numero("55")
        client = base.ajouter_client("Mme Rien Conclu", numero)
        quand = (datetime.datetime.now() + datetime.timedelta(days=3)).replace(
            hour=10, minute=0, second=0,
            microsecond=0).isoformat(timespec="minutes")
        base.ajouter_rendezvous(client, quand, "Séance", statut="prévu")
        campagne = self._campagne(
            "confirmation", [f"Mme Rien Conclu;{numero};{quand};Séance"],
            politique="tous", relance_max="0")
        self._derouler(campagne)
        _, page = self._obtenir(f"/campagne?id={campagne}")
        return _zone_visible(page)

    def test_la_liste_des_personnes_vient_en_premier(self):
        """⚠ LE CŒUR DE SA DEMANDE. On compare des POSITIONS : le titre de sa
        liste doit précéder les deux autres, quel que soit leur ordre entre
        eux."""
        visible = self._campagne_avec_les_trois()
        liste = visible.index("Les personnes, une par une")
        for autre in ("Le cahier des changements à reporter",
                      "Compenser une absence"):
            with self.subTest(titre=autre):
                self.assertLess(liste, visible.index(autre),
                                f"« {autre} » passe avant sa liste")

    def test_les_deux_autres_sont_repliés_derriere_un_lien(self):
        visible = self._campagne_avec_les_trois()
        # ⚠ FERMÉ À L'ARRIVÉE : pas d'attribut « open ».
        self.assertNotIn('<details class="repli-geste" open>\n<summary>Voir',
                         visible)
        repli = _le_repli_des_details(visible)
        # ⚠ AVEC LEURS TITRES, mot pour mot : « les deux autres tableaux avec
        # leurs titre etc. »
        self.assertIn("<h2>📋 Le cahier des changements à reporter</h2>", repli)
        self.assertIn("Compenser une absence", repli)
        # Et la liste, elle, n'est PAS dedans.
        self.assertNotIn("Les personnes, une par une", repli)

    def test_le_lien_se_lit_comme_un_lien(self):
        """Il a demandé « un lien », pas un bouton de plus : c'est la classe que
        le produit réserve déjà aux replis cliquables (`repli-geste`), soulignée
        et à la couleur d'accent."""
        visible = self._campagne_avec_les_trois()
        self.assertIn('<details class="repli-geste">\n<summary>Voir les '
                      "détails</summary>", visible)

    def test_sur_une_campagne_neuve_le_lien_ouvre_sur_du_texte(self):
        """LA CONTRE-ÉPREUVE. Le repli est TOUJOURS là — un lien qui
        apparaîtrait et disparaîtrait selon l'avancement serait un écran qui
        change de forme sous les yeux. Et il n'ouvre jamais sur du vide : sans
        changement, le cahier écrit lui-même qu'il n'y en a pas."""
        campagne = self._campagne(
            "confirmation",
            [f"M. Personne;{self._numero('51')};{DEMAIN};Séance"])
        _, page = self._obtenir(f"/campagne?id={campagne}")
        visible = _zone_visible(page)
        self.assertIn("Les personnes, une par une", visible)
        repli = _le_repli_des_details(visible)
        self.assertIn("rien n'a encore bougé", repli)


class TestLesIndicationsDisentLaSituationReelle(_CampagneAssistant):
    """⚠ SON SIGNALEMENT DU 21/08/2026, sur sa campagne n° 119 :

    « nous avons eu deux annulations mais dans le tableau initial c'est marqué
    "le client rappellera". Les états ne sont pas alignés sur la situation
    réelle. D'autre part dans le tableau 1 on voit 3 rendez-vous annulés. »

    Il avait raison sur les deux points, et ils n'avaient PAS la même cause :

    · la liste des contacts affichait « 📞 le client rappellera » et un TIRET
      dans la colonne des rendez-vous — alors que le rendez-vous venait d'être
      ANNULÉ. Un tiret se lit « on ne sait pas » ; ici on savait ;

    · le panneau « Compenser une absence » n'en montrait que DEUX sur trois,
      parce que l'annulation écrite par `_annuler_le_rendezvous` n'attachait pas
      son rendez-vous à la ligne du cahier. La troisième place se libérait en
      silence.
    """

    @staticmethod
    def _numero(terminaison, prefixe="00 00 00"):
        """⚠ CONSTRUIT, JAMAIS ÉCRIT EN DUR — `preparer_publication.py` refuse
        tout numéro en clair hors de la série de fiction documentée."""
        return f"+33 6 {prefixe} {terminaison}"

    def _rdv(self, nom, terminaison, heure=10, jours=3):
        """Un client, son numéro à issue forcée, et son rendez-vous."""
        base = self.application.base
        numero = self._numero(terminaison)
        client = base.ajouter_client(nom, numero)
        quand = (datetime.datetime.now() + datetime.timedelta(days=jours)
                 ).replace(hour=heure, minute=0, second=0,
                           microsecond=0).isoformat(timespec="minutes")
        return client, base.ajouter_rendezvous(client, quand, "Séance",
                                               statut="prévu"), quand

    def _confirmation_non_conclue(self):
        """Une confirmation où rien n'est conclu : le rendez-vous est annulé
        par la règle du 17/08 (« si la personne doit rappeler, le rendez-vous
        est simplement annulé »)."""
        base = self.application.base
        horaires.definir_semaine(self.application.preferences,
                                 {j: [(8 * 60, 19 * 60)] for j in range(7)})
        _, rdv, quand = self._rdv("Mme Rien Conclu", "55", heure=10)
        campagne_id = self._campagne(
            "confirmation",
            [f"Mme Rien Conclu;{self._numero('55')};{quand};Séance"],
            politique="tous", relance_max="0")
        self._derouler(campagne_id)
        return campagne_id, rdv

    def test_l_annulation_porte_SON_rendez_vous_au_cahier(self):
        """⚠ LE DÉFAUT MESURÉ : sans `rendezvous_id`, la ligne du cahier ne
        désigne aucune place — et le panneau « Compenser une absence », qui
        n'accepte que les changements qui en désignent une, l'ignore. Sur sa
        campagne n° 119 : trois annulations au cahier, DEUX places proposées."""
        base = self.application.base
        campagne_id, rdv = self._confirmation_non_conclue()
        self.assertEqual(base.obtenir_rendezvous(rdv)["statut"], "annulé")
        annulations = [c for c in base.changements_de_campagne(campagne_id)
                       if c["genre"] == "annulation"]
        self.assertEqual(len(annulations), 1)
        self.assertEqual(annulations[0]["rendezvous_id"], rdv)

    def test_la_place_liberee_est_donc_proposee_a_la_compensation(self):
        """LE BOUT DU CHEMIN : ce n'est pas la ligne du cahier qu'on mesure,
        c'est l'écran qui en dépend.

        ⚠ DEPUIS LE 30/08/2026, CE PANNEAU EST REPLIÉ (sa demande : il ne veut
        voir que sa liste en arrivant). Cet essai serait resté VERT sans rien
        prouver — un `details` fermé garde son contenu dans la page. On mesure
        donc que la place est proposée ET où elle l'est : dans le repli.
        """
        campagne_id, rdv = self._confirmation_non_conclue()
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        repli = _le_repli_des_details(_zone_visible(page))
        self.assertIn("Compenser une absence", repli)
        self.assertIn("Mme Rien Conclu", repli)

    def test_la_colonne_dit_que_le_rendez_vous_est_annule(self):
        """⚠ UN TIRET SE LIT « ON NE SAIT PAS ». La colonne montrait le PROCHAIN
        rendez-vous ; quand la campagne venait d'annuler le seul qu'il y avait,
        elle restait vide — et l'état « le client rappellera » taisait le
        fait."""
        campagne_id, _ = self._confirmation_non_conclue()
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        visible = _zone_visible(page)
        self.assertIn("Son rendez-vous", visible)      # l'en-tête suit
        self.assertNotIn("Prochain rdv", visible)
        # ⚠ ON LIT DANS LE TABLEAU DES CONTACTS, PAS DANS LA PAGE. Le cahier
        # des changements porte lui aussi « ✖ Rendez-vous annulé » : chercher
        # dans la page entière rendait cet essai vert quoi qu'il arrive — il
        # ne mesurait pas la colonne, il mesurait le cahier.
        tableau = visible[visible.rindex("<table"):]
        self.assertIn("Mme Rien Conclu", tableau)
        self.assertIn("✖ annulé", tableau)

    def test_un_rendez_vous_INTACT_montre_sa_date_comme_avant(self):
        """LA CONTRE-ÉPREUVE : la colonne n'a pas cessé de faire son travail.
        Un contact dont le rendez-vous tient montre SA DATE, pas une annulation
        inventée."""
        base = self.application.base
        horaires.definir_semaine(self.application.preferences,
                                 {j: [(8 * 60, 19 * 60)] for j in range(7)})
        _, rdv, quand = self._rdv("M. Confirme", "51", heure=11)
        campagne_id = self._campagne(
            "confirmation",
            [f"M. Confirme;{self._numero('51')};{quand};Séance"],
            politique="tous", relance_max="0")
        self._derouler(campagne_id)
        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        visible = _zone_visible(page)
        tableau = visible[visible.rindex("<table"):]
        self.assertNotIn("✖ annulé", tableau)
        self.assertIn(assistant.date_chiffree(
            base.obtenir_rendezvous(rdv)["horaire"]), visible)


class _PreferencesMuettes:
    """Le minimum que `construire_consigne` lit — sans base ni fichier.

    Une classe plutôt qu'un dictionnaire : `obtenir` est appelée avec un
    défaut, et `definir` existe côté produit.
    """

    def __init__(self, **valeurs):
        self.valeurs = {themes.CLE_ENTREPRISE: "Cabinet Essai",
                        themes.CLE_PLAGE_DEBUT: "09:00",
                        themes.CLE_PLAGE_FIN: "19:00"}
        self.valeurs.update(valeurs)

    def obtenir(self, cle, defaut=None):
        return self.valeurs.get(cle, defaut)

    def definir(self, cle, valeur):
        self.valeurs[cle] = valeur


class TestLaFinDecideeArriveVraiment(_CampagneAssistant):
    """⚠ L'ESSAI QUI VA AU BOUT : une campagne complète, un agent qui OBÉIT à la
    consigne, et la fin décrite dans `FINS-DE-CAMPAGNE.md` §4 — l'état du
    contact ET le sort du rendez-vous.

    ⚠ CE N'EST PAS LE MÊME ESSAI QUE LES PRÉCÉDENTS. Ils vérifient que la
    réponse dictée est ACCEPTÉE ; celui-ci vérifie qu'elle PRODUIT ce qu'on a
    décidé. Une réponse acceptée puis mal appliquée serait verte partout
    ailleurs.

    ⚠ ET LE RENDEZ-VOUS VIENT DU PLANNING, pas d'un collage. Un contact collé
    à la main porte une date dans sa colonne mais AUCUNE ligne d'agenda
    derrière : « je confirme ma présence » n'a alors rien à confirmer, et
    l'essai mesurerait autre chose que ce qu'il croit. C'est le piège dans
    lequel ma première mesure du 24/08 est tombée.
    """

    class Obeissant(calle_client.ClientAppels):
        """Il rend EXACTEMENT ce que la consigne lui dicte pour cette issue."""

        def __init__(self, statut, date=""):
            self.statut, self.date = statut, date

        def appeler(self, nom_client, telephone, rendezvous, mission=None,
                    consigne=None, nature=None):
            return calle_client.IssueAppel(
                calle_client.valider_resultat(
                    {"appointment_status": self.statut,
                     "new_datetime": self.date, "notes": "au téléphone"}),
                "Agent : …")

    def _un_rendezvous(self):
        """Un vrai rendez-vous au planning, dans trois semaines, en semaine."""
        quand = (datetime.datetime.now() + datetime.timedelta(days=21)).replace(
            hour=10, minute=20, second=0, microsecond=0)
        while quand.weekday() > 4:
            quand += datetime.timedelta(days=1)
        base = self.application.base
        client = base.ajouter_client("Mme Martin", self._numero("53"))
        iso = quand.isoformat(timespec="minutes")
        base.ajouter_rendezvous(client, iso, "séance", statut="prévu")
        return iso

    @staticmethod
    def _numero(terminaison, prefixe="00 00 00"):
        """⚠ CONSTRUIT, JAMAIS ÉCRIT EN DUR (`preparer_publication.py` refuse)."""
        return f"+33 6 {prefixe} {terminaison}"

    def _campagne_du_planning(self, nature):
        for jour in range(5):
            self._poster("/reglages/semaine",
                         {"jour": str(jour), "debut": "09:00", "fin": "18:00",
                          "geste": "ouvrir"})
        iso = self._un_rendezvous()
        _, page = self._poster("/assistant/nature", {"nature": nature})
        b = self._brouillon(page)
        formulaire = {"b": b, "action": "continuer", "ordre": "liste",
                      "opt_recontacter": "1", "opt_liberer": "1",
                      "relance_mode": "delai", "relance_delai": "4",
                      "relance_max": "3"}
        formulaire.update(self.INFOS[nature])
        for code in self.CHAMPS_CALCULES:
            valeur = self._valeur_affichee(page, code)
            if valeur is not None:
                formulaire[code] = valeur
        self._poster("/assistant/message", formulaire)
        self._poster("/assistant/importer",
                     {"b": b, "mode": "rendezvous", "source": "a_venir"})
        self._poster("/assistant/liste", {"b": b, "action": "valider"})
        return self.application.base.lister_campagnes()[0]["id"], iso

    def _jouer(self, nature, statut, date=""):
        campagne, iso = self._campagne_du_planning(nature)
        self.application.planif.client_appels = self.Obeissant(statut, date)
        assistant.executer_campagne(self.application, campagne)
        base = self.application.base
        contact = base.contacts_de_campagne(campagne)[0]
        fiche = base.obtenir_campagne(campagne)
        sien = [r for r in base.tous_les_rendezvous()
                if r["nom"] == "Mme Martin"]
        return contact, fiche, (dict(sien[0]) if sien else None), iso

    # ------------------------------------------------------------------ OUI
    def test_une_presence_confirmee_confirme_le_rendezvous(self):
        """⚠ LA FIN LA PLUS COURANTE, ET ELLE ÉTAIT INATTEIGNABLE. La consigne
        dicte « confirmed, new_datetime vide » ; jusqu'au 24/08/2026 cela
        déclarait la réponse ILLISIBLE, mettait la campagne EN PAUSE et envoyait
        la personne « à rappeler par un humain ». Toute campagne de confirmation
        s'arrêtait donc au premier succès."""
        for nature in ("confirmation", "rappel_rdv"):
            with self.subTest(nature=nature):
                contact, fiche, rdv, iso = self._jouer(nature, "confirmed", "")
                self.assertEqual(contact["etat"], "accepté")
                self.assertEqual(fiche["statut"], "terminée")
                # ⚠ LE RENDEZ-VOUS NE BOUGE PAS D'UNE MINUTE : il passe
                # « confirmé », à SA place. C'est §3 de FINS-DE-CAMPAGNE.md.
                self.assertEqual(rdv["horaire"], iso)
                self.assertEqual(rdv["statut"], "confirmé")

    # ----------------------------------------------------------------- AUTRE
    def test_veut_bouger_sans_conclure_annule_le_rendezvous(self):
        """§4 : sur ces deux natures, « le rendez-vous est ANNULÉ, le client
        rappellera » (sa règle du 17/08/2026)."""
        for nature in ("confirmation", "rappel_rdv"):
            with self.subTest(nature=nature):
                contact, _, rdv, iso = self._jouer(nature, "to_reschedule", "")
                self.assertEqual(contact["etat"], assistant.ETAT_RAPPELLERA)
                self.assertEqual(rdv["horaire"], iso)
                self.assertEqual(rdv["statut"], "annulé")

    def test_sur_un_deplacement_un_humain_reprend_la_main(self):
        """§4 : le déplacement, lui, envoie vers un humain — il y a un vrai
        travail à faire, trouver une date."""
        contact, _, rdv, iso = self._jouer("deplacement", "to_reschedule", "")
        self.assertEqual(contact["etat"], "à rappeler par un humain")
        # Et le rendez-vous non déplacé est ANNULÉ (sa règle du 21/08/2026).
        self.assertEqual(rdv["statut"], "annulé")

    # ------------------------------------------------------------------- NON
    def test_une_annulation_pendant_l_appel_libere_la_place(self):
        for nature in ("confirmation", "rappel_rdv", "deplacement"):
            with self.subTest(nature=nature):
                contact, _, rdv, _ = self._jouer(nature, "canceled", "")
                self.assertEqual(contact["etat"], assistant.ETAT_RAPPELLERA)
                self.assertNotIn(rdv["statut"], ("prévu", "confirmé"))


class TestCeQuOnDemandeALAgentEstAccepte(unittest.TestCase):
    """⚠ SA DEMANDE DU 24/08/2026 : « il faut adapter ce qu'on demande à
    l'agent pour s'assurer des fins que l'on a décidées lors des tests de
    simulation ».

    LE DÉFAUT QUI L'A MOTIVÉE, mesuré : deux natures dictent à l'agent, mot pour
    mot, « rends appointment_status = "confirmed" et laisse "new_datetime"
    vide » — c'est écrit dans leur fiche depuis toujours (`date="vide"`). Le
    contrôle de forme, lui, exigeait une date pour tout ce qui n'est pas une
    annulation. En réel, la PREMIÈRE personne qui répond « oui, je serai là »
    faisait donc déclarer la réponse ILLISIBLE, mettait la campagne EN PAUSE et
    partait « à rappeler par un humain ».

    ⚠ LA SIMULATION NE POUVAIT PAS LE VOIR : elle remplissait `new_datetime`
    sur « confirmed » quoi qu'il arrive. Elle ne jouait donc jamais la réponse
    qu'elle demande elle-même — et c'est exactement l'écart qu'il redoutait.

    CET ESSAI EST LA RÈGLE, PAS LE CAS : il parcourt TOUTES les natures et
    TOUTES leurs issues, construit la réponse qu'un agent obéissant rendrait,
    et exige qu'elle passe. Une nature ajoutée demain y entre toute seule.
    """

    UNE_DATE = "2026-09-15T14:30"

    @staticmethod
    def _consigne_de(nature):
        definition = assistant.NATURES[nature]
        return assistant.construire_consigne(
            nature, {"entreprise": "Cabinet Essai"}, _PreferencesMuettes(),
            genre=definition.get("genre", consigne.GENRE_CLASSIQUE))

    def _reponses_obeissantes(self, cadre):
        """Ce qu'un agent qui SUIT la consigne peut rendre, issue par issue.

        Le contrat est dans la consigne elle-même : « date » vaut « vide »,
        « facultative » ou « obligatoire ». On ne devine pas — on le lit.
        """
        cascade = cadre.genre == consigne.GENRE_CASCADE
        champ = "outcome" if cascade else "appointment_status"
        for cle, regle in cadre.issues.items():
            dates = {"vide": [""], "obligatoire": [self.UNE_DATE],
                     "facultative": [self.UNE_DATE, ""]}[regle["date"]]
            for date in dates:
                # Sans date, une issue « facultative » se replie sur son code
                # de secours : c'est la consigne qui le dit à l'agent.
                code = (regle["code"] if date or not regle["code_sans_date"]
                        else regle["code_sans_date"])
                yield cle, {champ: code, "new_datetime": date,
                            "notes": "au téléphone"}

    def test_toute_issue_dictee_est_acceptee_par_le_controle(self):
        """⚠ L'ESSAI QUI AURAIT ATTRAPÉ LE BLOCAGE. Ce qu'on demande à l'agent et
        ce qu'on accepte de lui sont deux écritures de la MÊME règle : elles ne
        peuvent pas diverger sans qu'un appel réussi soit jeté."""
        for nature in assistant.NATURES:
            cadre = self._consigne_de(nature)
            valideur = (calle_client.valider_resultat_cascade
                        if cadre.genre == consigne.GENRE_CASCADE
                        else calle_client.valider_resultat)
            for cle, reponse in self._reponses_obeissantes(cadre):
                with self.subTest(nature=nature, issue=cle,
                                  date=reponse["new_datetime"]):
                    try:
                        valideur(dict(reponse))
                    except calle_client.ResultatInvalide as refus:
                        self.fail(
                            f"« {nature} » dicte cette réponse à l'agent et "
                            f"RingBack la refuse : {reponse} — {refus.constat}")

    def test_les_deux_natures_de_presence_n_exigent_aucune_date(self):
        """⚠ LE CŒUR DU DÉFAUT, épinglé nature par nature. « Je serai là » ne
        s'accompagne d'aucune date : il n'y en a pas de nouvelle, le
        rendez-vous ne bouge pas."""
        for nature in ("confirmation", "rappel_rdv"):
            with self.subTest(nature=nature):
                self.assertEqual(
                    assistant.NATURES[nature]["issues"]["oui"]["date"], "vide")
                lu = calle_client.valider_resultat(
                    {"appointment_status": "confirmed", "new_datetime": "",
                     "notes": "Elle sera présente."})
                self.assertIsNone(lu["new_datetime"])

    def test_les_natures_qui_POSENT_une_date_l_exigent(self):
        """LA CONTRE-ÉPREUVE : accepter « confirmed » sans date ne doit rien
        relâcher là où une date est le résultat même de l'appel."""
        for nature in ("deplacement", "prise_rdv"):
            with self.subTest(nature=nature):
                self.assertEqual(
                    assistant.NATURES[nature]["issues"]["oui"]["date"],
                    "obligatoire")
                dit = self._consigne_de(nature).texte()
                self.assertIn("écris dans « new_datetime » la date convenue",
                              dit)

    def test_le_rappel_individuel_reclame_la_date_qu_il_propose(self):
        """⚠ LE MÊME DÉFAUT, DE L'AUTRE CÔTÉ (24/08/2026). Hors campagne — rappel
        individuel, file d'appels, essai réel — la consigne de repli PROPOSE un
        créneau précis (« je vous propose un nouveau créneau le mardi 25 août
        2026 à 9 heures »). Dire oui, c'est prendre CELUI-LÀ, et le
        planificateur doit l'écrire — or elle disait « laisse new_datetime
        vide ». L'accord revenait sans date, la vérification le refusait, et le
        rendez-vous ne bougeait pas d'une minute."""
        self.assertEqual(consigne.ISSUES_DEFAUT["oui"]["date"], "obligatoire")
        dit = calle_client.AppelReel(cle_api="cle-de-test-0123456789")._tache(
            "Mme Martin", {"horaire": "2026-09-14T10:20", "motif": "séance"})
        ligne = [l for l in dit.splitlines() if l.startswith("- OUI")]
        self.assertTrue(ligne)
        self.assertIn("écris dans « new_datetime » la date convenue", ligne[0])

    def test_la_cascade_n_exige_pas_de_date_pour_prendre_la_place(self):
        """Le cas inverse, et il est juste : la place proposée est DÉJÀ connue
        de RingBack. La redemander à l'agent, ce serait l'inviter à la recopier
        de travers."""
        self.assertEqual(consigne.ISSUES_DEFAUT_CASCADE["oui"]["date"], "vide")
        lu = calle_client.valider_resultat_cascade(
            {"outcome": "accepted", "new_datetime": "", "notes": "Elle prend."})
        self.assertIsNone(lu["new_datetime"])


class TestChaqueFinJoueeEnSimulationEstDemandee(unittest.TestCase):
    """⚠ L'AUTRE MOITIÉ DE SA DEMANDE. Une fin jouée en simulation mais jamais
    demandée à l'agent est une fin qu'on ÉPROUVE et qui n'arrivera JAMAIS en
    réel — le contraire exact de ce à quoi sert une simulation.

    MESURÉ LE 24/08/2026 : « 🗓 Prise de rendez-vous » jouait « rescheduled »
    (la personne propose SON propre moment, le produit pose le rendez-vous à
    cette date, contact « accepté ») et sa consigne n'autorisait que
    « to_reschedule ». Une date convenue au téléphone repartait donc en rappel
    par un humain — pour refixer ce qui venait d'être fixé.
    """

    @staticmethod
    def _codes_dictes(nature):
        definition = assistant.NATURES[nature]
        cadre = assistant.construire_consigne(
            nature, {"entreprise": "Cabinet Essai"}, _PreferencesMuettes(),
            genre=definition.get("genre", consigne.GENRE_CLASSIQUE))
        codes = set()
        for regle in cadre.issues.values():
            codes.add(regle["code"])
            if regle["code_sans_date"]:
                codes.add(regle["code_sans_date"])
        return codes, cadre.texte()

    def test_aucune_fin_simulee_n_est_hors_de_portee_de_l_agent(self):
        for nature in assistant.NATURES:
            jouees = calle_client.issues_simulees(nature)
            self.assertTrue(jouees, f"« {nature} » ne simule rien")
            codes, texte = self._codes_dictes(nature)
            for marque in jouees:
                if marque == calle_client.PAS_DE_REPONSE:
                    continue
                code = marque.split("+")[0]
                with self.subTest(nature=nature, issue=code):
                    self.assertIn(
                        code, codes,
                        f"« {nature} » joue « {code} » en simulation, mais la "
                        f"consigne ne le demande jamais à l'agent")
                    # Et il est bien ÉCRIT dans le texte dicté, pas seulement
                    # dans la table : c'est le texte qui part.
                    self.assertIn(f"« {code} »", texte)

    def test_les_deux_champs_a_cote_sont_dictes_la_ou_ils_se_jouent(self):
        """🚫 « ne me rappelez plus » et 🔇 « ne me proposez plus de place » :
        ils accompagnent une issue au lieu de la remplacer, et la simulation
        les joue. L'agent doit donc savoir quand les rendre."""
        for nature in assistant.NATURES:
            _, texte = self._codes_dictes(nature)
            joues = set()
            for marque in calle_client.issues_simulees(nature):
                if calle_client.SUFFIXE_STOP in marque:
                    joues.add(calle_client.CHAMP_NE_PLUS_APPELER)
                if calle_client.SUFFIXE_SANS_PROPOSITION in marque:
                    joues.add(calle_client.CHAMP_AUTRES_PLACES)
            for champ in joues:
                with self.subTest(nature=nature, champ=champ):
                    self.assertIn(champ, texte,
                                  f"« {nature} » joue {champ} en simulation "
                                  f"sans jamais le demander à l'agent")


class TestLeSimulateurRepondCommeLAgentReel(unittest.TestCase):
    """⚠ CE QUI A LAISSÉ PASSER LE BLOCAGE. Le simulateur posait une date sur
    « confirmed » quoi qu'il arrive — y compris sur les natures dont la consigne
    dit l'inverse. Il ne jouait donc jamais la réponse qu'il demande, et des
    centaines de campagnes simulées sont passées au vert sur un chemin que le
    réel ne pouvait pas emprunter.

    Il lit désormais le contrat DANS la consigne qu'il reçoit, comme l'agent.
    """

    RDV = {"horaire": "2026-09-14T10:20", "motif": "séance"}

    def _appel(self, nature):
        cadre = assistant.construire_consigne(
            nature, {"entreprise": "Cabinet Essai"}, _PreferencesMuettes())
        client = calle_client.AppelSimule(graine=3, latence=0)
        # Le numéro en « 51 » exige l'issue « accepte » : on éprouve CE
        # chemin-là, pas celui que le plan de la nature aurait tiré.
        return client.appeler("Mme Martin", "+33 6 00 00 00 51", self.RDV,
                              consigne=cadre, nature=nature).resultat

    def test_sans_date_demandee_le_simulateur_n_en_invente_pas(self):
        for nature in ("confirmation", "rappel_rdv"):
            with self.subTest(nature=nature):
                resultat = self._appel(nature)
                self.assertEqual(resultat["appointment_status"], "confirmed")
                self.assertIsNone(
                    resultat["new_datetime"],
                    "le simulateur pose une date que la consigne interdit")

    def test_avec_date_demandee_le_simulateur_en_pose_une(self):
        """LA CONTRE-ÉPREUVE : là où la date EST le résultat de l'appel, elle
        doit revenir."""
        for nature in ("deplacement", "prise_rdv"):
            with self.subTest(nature=nature):
                resultat = self._appel(nature)
                self.assertEqual(resultat["appointment_status"], "confirmed")
                self.assertTrue(resultat["new_datetime"],
                                "le simulateur ne rend plus de date")

    def test_sans_consigne_rien_ne_change(self):
        """Le rappel individuel et la file appellent SANS consigne de campagne
        (voir planificateur) : leur comportement d'avant est intact."""
        client = calle_client.AppelSimule(graine=3, latence=0)
        resultat = client.appeler("Mme Martin", "+33 6 00 00 00 51",
                                  self.RDV).resultat
        self.assertEqual(resultat["appointment_status"], "confirmed")
        self.assertTrue(resultat["new_datetime"])


class TestUnAccordSansDateLaOuIlEnFautUne(unittest.TestCase):
    """⚠ LE FILET, sous les deux natures qui POSENT une date. Accepter
    « confirmed » sans date ouvre un chemin nouveau : un agent qui conclut à un
    accord sans dire QUAND. Rien ne doit être écrit — et la phrase doit dire
    cela, pas parler d'un format."""

    def test_la_phrase_dit_ce_qui_s_est_passe(self):
        base = db.Base(":memory:")
        message = horaires.refus_rendezvous_telephone(base, None, None)
        self.assertIn("AUCUNE date", message)
        self.assertIn("Rappelez cette personne", message)
        # ⚠ ET PAS UN MOT DE FORMAT : « Date convenue illisible : « None » »
        # ne disait rien à personne.
        self.assertNotIn("illisible", message)
        self.assertNotIn("None", message)

    def test_une_date_vide_ou_blanche_compte_comme_absente(self):
        base = db.Base(":memory:")
        for brut in (None, "", "   "):
            with self.subTest(brut=brut):
                self.assertIn("AUCUNE date", horaires.refus_rendezvous_telephone(
                    base, None, brut))

    def test_une_date_illisible_garde_son_ancien_message(self):
        """LA CONTRE-ÉPREUVE : « absente » et « illisible » ne sont pas la même
        chose, et l'écran ne doit pas les confondre."""
        base = db.Base(":memory:")
        message = horaires.refus_rendezvous_telephone(base, None, "la semaine "
                                                                 "prochaine")
        self.assertIn("illisible", message)
        self.assertIn("la semaine prochaine", message)


class TestLeFrancaisNeTraverseRien(unittest.TestCase):
    """⚠ LA PROPRIÉTÉ QUI PROTÈGE TOUT LE PRODUIT (01/09/2026).

    L'anglais a été ajouté en traduisant la page FINIE, au moment où elle
    quitte le produit — et non en touchant les 238 fonctions qui la
    fabriquent. La garantie que cela vaut tient en une phrase : **en français,
    la traduction rend l'objet reçu, sans même le lire**.

    Ces essais tiennent cette phrase. S'ils tombent, le produit français peut
    régresser sans qu'on le voie, et tout le reste de l'ouvrage est à revoir.
    """

    PAGES = (
        "<p>Bonjour</p>",
        "<p>Bonjour {}</p>",
        "<script>var s = '<p>pas du texte</p>';</script><p>Vrai texte</p>",
        "<style>.a{content:'<b>x</b>'}</style><p>Après le style</p>",
        "<p title=\"Une infobulle\">Texte</p>",
        "<p>Une phrase <strong>coupée</strong> en deux.</p>",
        "<p>&#x27;échappé&#x27; et &nbsp; insécable</p>",
        "<img alt='sans guillemets doubles'>",
        "<p>balise jamais fermée",
        "<script>jamais fermé",
        "",
        "   ",
        "pas de balise du tout",
    )

    def test_le_francais_rend_l_objet_recu(self):
        """⚠ « is », PAS « == ». L'égalité prouverait que le résultat se lit
        pareil ; l'identité prouve qu'AUCUN traitement n'a eu lieu. C'est la
        seule forme de cette preuve qui ne puisse pas mentir."""
        for page in self.PAGES:
            with self.subTest(page=page[:40]):
                self.assertIs(langue.traduire(page, "fr"), page)

    def test_une_langue_inconnue_retombe_sur_le_francais(self):
        """Un réglage abîmé ne doit pas changer ce qui s'affiche."""
        for valeur in (None, "", "  ", "de", "FR-fr", "anglais", "en-US", 42):
            with self.subTest(valeur=valeur):
                self.assertEqual(langue.langue_valide(valeur), "fr")
        self.assertEqual(langue.langue_valide("EN"), "en")
        self.assertEqual(langue.langue_valide(" en "), "en")

    def test_sans_dictionnaire_l_anglais_ne_change_rien(self):
        """Une phrase inconnue reste en français : on ne traduit jamais au mot
        à mot. Sur un écran qui déclenche de vrais appels, une phrase mal
        traduite est pire qu'une phrase non traduite."""
        for page in self.PAGES:
            with self.subTest(page=page[:40]):
                self.assertEqual(
                    langue._traduire_texte(page, {}), page)

    def test_le_decoupage_se_recolle_a_l_octet_pres(self):
        """⚠ LE FONDEMENT. On ne reconstruit jamais le document : on le coupe
        et on ne remplace que des tranches entières. Si le recollage perdait
        un seul caractère, toute page traduite serait abîmée."""
        for page in self.PAGES:
            with self.subTest(page=page[:40]):
                self.assertEqual(
                    "".join(m for _, m in langue._zones(page)), page)

    def test_le_code_des_scripts_n_est_jamais_traduit(self):
        """Traduire à l'intérieur d'un <script> casserait la page."""
        page = ("<script>var Enregistrer = 1;</script>"
                "<p>Enregistrer</p>"
                "<style>.Enregistrer{color:red}</style>")
        table = {"Enregistrer": "Save"}
        obtenu = "".join(
            langue._traduire_texte(m, table) if genre == "texte" else m
            for genre, m in langue._zones(page))
        self.assertIn("var Enregistrer = 1;", obtenu)
        self.assertIn(".Enregistrer{color:red}", obtenu)
        self.assertIn("<p>Save</p>", obtenu)

    def test_seuls_les_attributs_lisibles_sont_traduits(self):
        """⚠ NAME, VALUE, ID, ACTION SONT DES IDENTIFIANTS. Les traduire
        casserait les formulaires — le champ posté ne porterait plus le nom
        que le serveur attend."""
        balise = ('<input name="Enregistrer" value="Enregistrer" '
                  'id="Enregistrer" title="Enregistrer" '
                  'placeholder="Enregistrer">')
        obtenu = langue._traduire_balise(balise, {"Enregistrer": "Save"})
        self.assertIn('name="Enregistrer"', obtenu)
        self.assertIn('value="Enregistrer"', obtenu)
        self.assertIn('id="Enregistrer"', obtenu)
        self.assertIn('title="Save"', obtenu)
        self.assertIn('placeholder="Save"', obtenu)

    def test_les_espaces_d_origine_sont_gardes(self):
        """L'indentation du code d'origine tient la mise en page : la perdre
        changerait l'aspect de l'écran d'une langue à l'autre."""
        self.assertEqual(
            langue._traduire_texte("\n    Enregistrer\n  ",
                                   {"Enregistrer": "Save"}),
            "\n    Save\n  ")


class TestLaBasculeDeLangue(_TestAvecServeurWeb):
    """Le geste FR/EN : il doit être VISIBLE, et rendre la main où l'on était."""

    def test_le_bouton_est_sur_toutes_les_pages(self):
        """⚠ SUR TOUTES, PAS DANS LES RÉGLAGES. Un testeur anglophone qui
        tombe sur du français ne cherchera pas un réglage : s'il ne voit pas
        le geste, il n'essaiera pas le produit."""
        for chemin in ("/", "/relances", "/suivi", "/clients", "/reglages"):
            with self.subTest(chemin=chemin):
                _, page = self._obtenir(chemin)
                self.assertIn('action="/langue"', page)
                self.assertIn('value="en"', page)

    def test_le_bouton_porte_l_AUTRE_langue(self):
        """Un bouton qui affiche l'état courant se lit à l'envers une fois
        sur deux : il porte donc ce qu'on OBTIENT en cliquant."""
        _, page = self._obtenir("/")
        self.assertIn(">EN</button>", page)
        self.application.preferences.definir(langue.CLE_LANGUE, "en")
        _, page = self._obtenir("/")
        self.assertIn(">FR</button>", page)

    def test_la_page_declare_sa_langue(self):
        """`lang` vit dans une balise, là où la traduction de sortie ne va
        jamais : il doit donc être juste dès la fabrication."""
        _, page = self._obtenir("/")
        self.assertIn('<html lang="fr">', page)
        self.application.preferences.definir(langue.CLE_LANGUE, "en")
        _, page = self._obtenir("/")
        self.assertIn('<html lang="en">', page)

    def test_le_geste_enregistre_la_langue(self):
        code, _ = self._poster("/langue", {"vers": "en"})
        self.assertIn(code, (200, 303))
        self.assertEqual(
            self.application.preferences.obtenir(langue.CLE_LANGUE), "en")

    def test_une_langue_inventee_ne_casse_rien(self):
        """Une adresse bricolée à la main ne doit pas laisser le produit dans
        un état qu'aucun écran ne sait afficher."""
        self._poster("/langue", {"vers": "klingon"})
        self.assertEqual(
            self.application.preferences.obtenir(langue.CLE_LANGUE), "fr")
        code, page = self._obtenir("/")
        self.assertEqual(code, 200)
        self.assertIn('<html lang="fr">', page)


class TestUneVraiePageRessortEnAnglais(_TestAvecServeurWeb):
    """⚠ L'ESSAI QUI MESURE LE RÉSULTAT, ET NON LA MÉCANIQUE.

    Les essais précédents éprouvent la fonction de traduction. Aucun n'aurait
    vu un dictionnaire vidé, une langue non transmise, ou une page servie par
    un chemin qui contourne la traduction : tout serait resté vert avec un
    produit entièrement français. Ceux-ci frappent le serveur pour de bon.
    """

    def _en_anglais(self, chemin="/", fenetre=False):
        self.application.preferences.definir(langue.CLE_LANGUE, "en")
        return self._obtenir(chemin, fenetre=fenetre)[1]

    def test_l_accueil_est_vraiment_traduit(self):
        """⚠ ET LE FRANÇAIS A DISPARU, pas seulement l'anglais ajouté. Une
        page qui porterait les deux serait pire que l'une des deux."""
        _, francais = self._obtenir("/")
        self.assertIn("📣 Campagnes", francais)
        anglais = self._en_anglais("/")
        self.assertIn("📣 Campaigns", anglais)
        self.assertNotIn("📣 Campagnes", anglais)

    def test_les_cinq_onglets_sont_traduits(self):
        anglais = self._en_anglais("/")
        for attendu in ("📣 Campaigns", "🔁 Follow-ups", "📅 Appointments",
                        "👥 Contacts", "⚙ Settings"):
            with self.subTest(onglet=attendu):
                self.assertIn(attendu, anglais)

    def test_une_FENETRE_est_traduite_elle_aussi(self):
        """⚠ LA SECONDE PORTE DE SORTIE, ET ELLE A SON PROPRE ENCODAGE.
        `_repondre_cible` n'appelle pas `_repondre` : elle ajoute un en-tête
        de cible et encode elle-même. L'oublier laisserait du français au
        milieu d'un écran anglais, sur tout ce qui se recharge sans changer
        de page — le défaut le plus visible qu'on puisse livrer.

        ⚠ CET ESSAI AVAIT UNE CONDITION, ET C'EST POURQUOI IL NE MESURAIT
        RIEN (trouvé par la contre-épreuve du 01/09/2026) : il n'affirmait
        que « si le mot est là, alors… ». Le correctif retiré, il restait
        vert. Il frappe maintenant une route qui passe VRAIMENT par
        `_repondre_cible`, et il affirme sans condition.
        """
        base = self.application.base
        client = base.ajouter_client("Mme Essai Fenêtre", "06 39 98 63 10")
        rdv = base.ajouter_rendezvous(client, DEMAIN, "Bilan", statut="prévu")
        envoi = {"rdv": rdv, "motif": "Bilan", "horaire": DEMAIN,
                 "duree": "1", "statut": "prévu"}

        _, fenetre_fr = self._poster("/suivi/detail/enregistrer", envoi,
                                     fenetre=True)
        self.assertFalse(fenetre_fr.startswith("<!DOCTYPE"),
                         "ce n'est pas une fenêtre : l'essai vise mal")
        self.assertIn("📅 Rendez-vous", fenetre_fr)

        self.application.preferences.definir(langue.CLE_LANGUE, "en")
        _, fenetre_en = self._poster("/suivi/detail/enregistrer", envoi,
                                     fenetre=True)
        self.assertIn("📅 Appointments", fenetre_en)
        self.assertNotIn("📅 Rendez-vous", fenetre_en)

    def test_les_donnees_ne_sont_JAMAIS_traduites(self):
        """⚠ LA RÈGLE QUI PROTÈGE SES DONNÉES. Le nom d'un contact, le motif
        d'un rendez-vous ne sont pas au dictionnaire : ils doivent traverser
        intacts. Traduire une donnée, ce serait la réécrire à l'écran."""
        base = self.application.base
        client = base.ajouter_client("Mme Sophie Enregistrer", "06 39 98 63 10")
        base.ajouter_rendezvous(client, DEMAIN, "Séance de kinésithérapie",
                                statut="prévu")
        anglais = self._en_anglais("/clients")
        self.assertIn("Mme Sophie Enregistrer", anglais)

    def test_la_couverture_ne_doit_pas_s_effondrer(self):
        """⚠ UN PLANCHER CHIFFRÉ, pas une impression. Sans lui, un
        dictionnaire à moitié perdu (fusion malheureuse, purge trop large)
        passerait inaperçu : la page s'afficherait, simplement en français.

        Le plancher est écrit en toutes lettres — 80 % — et non déduit de ce
        que le dictionnaire contient : un essai qui se déduit de ce qu'il
        garde ne peut pas échouer.
        """
        # ⚠ ON MESURE LA PAGE FRANÇAISE, PAS L'ANGLAISE. La question est
        # « de ce que cet écran affiche, combien sait-on traduire ? ». Mesurer
        # sur la page déjà traduite reviendrait à chercher de l'anglais dans
        # un dictionnaire français-vers-anglais : le chiffre tomberait à zéro
        # sans qu'aucune traduction ne manque. Erreur commise, puis corrigée.
        #
        # ⚠ ET SUR UN ÉCRAN DENSE : l'accueil d'une base vide ne porte que
        # 44 phrases ; les réglages en portent plus de 300, et tout le
        # vocabulaire du produit.
        _, francais = self._obtenir("/reglages")
        connues, inconnues = langue.phrases_connues(francais)
        # ⚠ ON NE COMPTE QUE CE QUI EST DU TEXTE — voir `langue.est_du_texte`.
        connues = [p for p in connues if langue.est_du_texte(p)]
        inconnues = [p for p in inconnues if langue.est_du_texte(p)]
        total = len(connues) + len(inconnues)
        self.assertGreater(total, 300, "la page mesurée est trop maigre")
        part = 100 * len(connues) / total
        # 90 %, écrit en toutes lettres. Mesuré le 01/09/2026 : 97,2 % sur cet
        # écran. La marge laisse passer une phrase neuve non encore traduite,
        # pas un dictionnaire à moitié perdu.
        self.assertGreaterEqual(
            part, 90.0,
            f"couverture tombée à {part:.1f} % ({len(inconnues)} phrases "
            f"non traduites) — exemples : {inconnues[:5]}")


class TestLesReglesNeSePerimentPas(unittest.TestCase):
    """⚠ LE DÉFAUT LE PLUS SOURNOIS DE CE CHANTIER (01/09/2026).

    La première passe de traduction a rendu 1 527 phrases écrites en toutes
    lettres. 804 d'entre elles — 53 % — portaient une date ou une heure de la
    semaine en cours : « dimanche 06/09 10h00 — hors horaires d'ouverture ».

    Elles auraient cessé de correspondre DÈS LE LENDEMAIN, et la traduction se
    serait effritée d'elle-même. Rien ne l'aurait signalé : la page se serait
    affichée, simplement en français.

    Ces essais emploient donc des dates VOLONTAIREMENT LOINTAINES — aucune ne
    peut se trouver dans un dictionnaire écrit aujourd'hui.
    """

    def _traduit(self, phrase):
        return langue.phrase_traduite(phrase, traductions.table("en"),
                                      traductions.motifs("en"))

    def test_une_case_de_grille_d_une_annee_lointaine(self):
        for phrase, attendu in (
                ("mardi 03/07/2074 14h15 — hors horaires d&#x27;ouverture",
                 "Tuesday 03/07/2074 14:15 — outside opening hours"),
                ("dimanche 22h45 — fermé", "Sunday 22:45 — closed"),
                ("lundi 01/01/2099 08h00 — fermé",
                 "Monday 01/01/2099 08:00 — closed")):
            with self.subTest(phrase=phrase):
                self.assertEqual(self._traduit(phrase), attendu)

    def test_un_pied_de_page_d_une_version_future(self):
        pied = ("RingBack — mode simulation : aucun appel réel, numéros "
                "fictifs et masqués. · code du 31/12 23h59")
        obtenu = self._traduit(pied)
        self.assertIsNotNone(obtenu, "le pied de page n'est plus traduit")
        self.assertIn("simulation mode", obtenu)
        self.assertIn("31/12 23h59", obtenu)
        self.assertNotIn("mode simulation", obtenu)

    def test_le_dictionnaire_ne_doit_plus_porter_de_dates(self):
        """⚠ LA RÈGLE, TENUE SUR LE DICTIONNAIRE LUI-MÊME. C'est ce qui
        empêche la prochaine passe de traduction de réintroduire 800 entrées
        périssables sans que personne ne le voie."""
        # ⚠ ON NE VISE QUE LES LIBELLES COURTS. Une date citee DANS un
        # paragraphe (« ce qui s'est produit le 01/08/2026 ») fait partie du
        # texte : elle ne changera jamais. Ce qui se perime, c'est un libelle
        # qui EST une date — « dimanche 06/09 10h00 — ferme ». La limite est
        # ecrite en clair, et non deduite du contenu du dictionnaire.
        motif = re.compile(r"\d{1,2}/\d{1,2}(?:/\d{2,4})?|\d{1,2}h\d{2}")
        coupables = sorted(cle for cle in traductions.FR_VERS_EN
                           if len(cle) <= 120 and motif.search(cle))
        self.assertLessEqual(
            len(coupables), 12,
            f"{len(coupables)} entrées portent une date ou une heure — "
            f"elles cesseront de correspondre. Écrire une RÈGLE (MOTIFS) "
            f"plutôt qu'une entrée. Exemples : {coupables[:5]}")

    def test_une_donnee_inconnue_reste_en_francais(self):
        """La contre-épreuve des règles : elles ne doivent pas se déclencher
        sur n'importe quoi. Une phrase qu'on ne sait pas traduire reste
        française — jamais traduite à moitié."""
        for phrase in ("Mme Nadia Lefèvre", "Séance de kinésithérapie",
                       "lundi 07h30 — motif que personne n'a écrit",
                       "vendredi 32/13/2026 99h99 — fermé"):
            with self.subTest(phrase=phrase):
                self.assertIsNone(self._traduit(phrase))


class TestLaConsigneSuitLaLangue(unittest.TestCase):
    """⚠ CE QUI PART À L'AGENT VOCAL, DANS LA LANGUE CHOISIE (01/09/2026).

    Sa demande : un jury de hackathon CALL-E doit pouvoir juger le produit. Or
    le critère de ce concours s'appelle « creative use of CALL-E » : ce qui est
    envoyé à l'agent EST ce qu'ils évaluent, et cela s'affiche en toutes
    lettres dans ⚙ Réglages et à l'étape ② de chaque campagne.

    ⚠ ET C'EST LE CŒUR QUI DÉCIDE DE VRAIS APPELS. D'où la même règle que
    partout : l'anglais s'AJOUTE, le français n'est pas touché. Le premier
    essai ci-dessous est celui qui le prouve.
    """

    def _preferences(self, langue_code=None):
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        prefs.definir(themes.CLE_ENTREPRISE, "Cabinet Essai")
        if langue_code:
            prefs.definir(langue.CLE_LANGUE, langue_code)
        return prefs

    def _infos(self, nature):
        valeurs = {}
        for info in assistant.NATURES[nature]["infos"]:
            if info.get("type") == "date":
                valeurs[info["code"]] = "2026-09-15T09:40"
            elif info["code"] == "entreprise":
                valeurs[info["code"]] = "Cabinet Essai"
            else:
                valeurs[info["code"]] = info.get("exemple") or "à préciser"
        return valeurs

    def _consigne(self, nature, langue_code=None):
        prefs = self._preferences(langue_code)
        return assistant.construire_consigne(
            nature, self._infos(nature), prefs, {})

    def test_le_francais_est_inchange(self):
        """⚠ LA GARANTIE, ET ELLE PASSE PAR L'IDENTITÉ DU TRADUCTEUR. En
        français, `langue.traducteur` rend une fonction identité : la consigne
        n'est traversée par aucun dictionnaire."""
        dire = langue.traducteur("fr")
        for texte in ("Bonjour", "", "n'importe quoi", consigne.ENTETE):
            with self.subTest(texte=texte[:30]):
                self.assertIs(dire(texte), texte)

    def test_aucun_crochet_n_est_perdu_ni_traduit(self):
        """⚠ LA FAUTE LA PLUS GRAVE POSSIBLE ICI. Les [crochets] sont des
        trous que le produit remplit ensuite avec le nom, la date, le motif.
        Un crochet traduit n'est jamais rempli — et l'agent dit « identite »
        à voix haute, à un patient."""
        motif = re.compile(r"\[[^\]\n]+\]")
        for nature in assistant.NATURES:
            with self.subTest(nature=nature):
                francais = self._consigne(nature).texte()
                anglais = self._consigne(nature, "en").texte()
                self.assertEqual(sorted(motif.findall(francais)),
                                 sorted(motif.findall(anglais)),
                                 "les crochets ne sont plus les mêmes")

    def test_les_noms_techniques_ne_sont_jamais_traduits(self):
        """Ce sont les champs que le produit RELIT dans la réponse : les
        traduire casserait la lecture de ce que l'agent a conclu."""
        for nature in assistant.NATURES:
            with self.subTest(nature=nature):
                texte = self._consigne(nature, "en").texte()
                attendu = ("new_datetime",
                           "appointment_status"
                           if assistant.NATURES[nature].get("genre")
                           != consigne.GENRE_CASCADE else "outcome")
                for nom in attendu:
                    self.assertIn(nom, texte)

    def test_le_dictionnaire_de_consigne_garde_ses_crochets(self):
        """⚠ LA RÈGLE TENUE SUR LE DICTIONNAIRE LUI-MÊME, et pas seulement sur
        le résultat : c'est ce qui empêchera la PROCHAINE passe de traduction
        d'y glisser un crochet traduit sans que personne ne le voie."""
        motif = re.compile(r"\[[^\]\n]+\]")
        fautes = []
        for fr, en in traductions.CONSIGNE_FR_VERS_EN.items():
            if sorted(motif.findall(fr)) != sorted(motif.findall(en)):
                fautes.append((fr[:60], en[:60]))
        self.assertEqual(fautes, [], f"{len(fautes)} entrée(s) ont perdu, "
                                     "ajouté ou traduit un [crochet]")

    def test_un_discours_ecrit_a_la_main_n_est_jamais_traduit(self):
        """Même règle qu'un message de campagne récrit : le texte appartient à
        celui qui l'a écrit."""
        prefs = self._preferences("en")
        maison = "Bonjour [identite], ici le cabinet."
        prefs.definir(assistant.cle_discours("confirmation"), maison)
        mission = assistant.construire_mission(
            "confirmation", self._infos("confirmation"), prefs, {})
        self.assertIn("ici le cabinet", mission)


class TestAucuneLigneDeConsigneNeResteFrancaise(unittest.TestCase):
    """⚠ LA MESURE ELLE-MÊME, TENUE PAR UN ESSAI (01/09/2026).

    On ne cherche pas des mots français dans le texte anglais : le premier
    instrument le faisait, et il s'est trompé — il comptait « date », qui est
    un mot des deux langues, et annonçait 18 % de restes là où il n'y en avait
    presque plus.

    **On COMPARE.** La même consigne est construite dans les deux langues et
    lue ligne à ligne : une ligne identique des deux côtés n'a pas été
    traduite. C'est exact, ça ne demande aucune liste de mots, et ça ne peut
    pas se tromper sur un faux ami.

    Cet essai seul aurait attrapé les quatre défauts du jour : les espaces de
    bord mangés, la plage d'appel restée française, les dates françaises dans
    les faits, et les treize libellés de faits jamais traduits.
    """

    DEUX_LETTRES = re.compile(r"[^\W\d_]{2,}", re.UNICODE)

    def _preferences(self, langue_code):
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        prefs.definir(themes.CLE_ENTREPRISE, "Val Fleuri Physiotherapy")
        prefs.definir(langue.CLE_LANGUE, langue_code)
        return prefs

    def _infos(self, nature):
        valeurs = {}
        for info in assistant.NATURES[nature]["infos"]:
            if info.get("type") == "date":
                valeurs[info["code"]] = "2026-09-15T09:40"
            elif info["code"] == "entreprise":
                valeurs[info["code"]] = "Val Fleuri Physiotherapy"
            else:
                valeurs[info["code"]] = info.get("exemple") or "to be specified"
        return valeurs

    def test_pas_une_seule_ligne_identique_en_francais_et_en_anglais(self):
        prefs = {code: self._preferences(code) for code in ("fr", "en")}
        options = {"liberer_creneau": True, "cascade": True,
                   "proposer_autre_date": True, "annuler_si_absent": True,
                   "confirmer_deplacement": True}
        compare, restes = 0, {}
        for nature in assistant.NATURES:
            infos = self._infos(nature)
            for genre in (consigne.GENRE_CLASSIQUE, consigne.GENRE_CASCADE):
                textes = {
                    code: assistant.construire_consigne(
                        nature, infos, prefs[code], options,
                        genre=genre).texte().splitlines()
                    for code in ("fr", "en")}
                self.assertEqual(len(textes["fr"]), len(textes["en"]),
                                 f"{nature}/{genre} : les deux consignes n'ont "
                                 "pas le même nombre de lignes")
                for ligne_fr, ligne_en in zip(textes["fr"], textes["en"]):
                    nu = ligne_fr.strip()
                    if not nu or not self.DEUX_LETTRES.search(nu):
                        continue
                    compare += 1
                    if nu == ligne_en.strip():
                        restes[nu] = restes.get(nu, 0) + 1
        self.assertGreater(compare, 300, "l'essai ne compare presque rien")
        self.assertEqual(
            sorted(restes)[:6], [],
            f"{len(restes)} ligne(s) de consigne restent en français sur "
            f"{compare} comparées")

    def test_les_espaces_de_bord_des_segments_sont_gardes(self):
        """⚠ CE QUI RECOLLE LES PHRASES. Le message est fait de morceaux
        collés par `"".join(...)` : chacun porte l'espace qui le sépare du
        suivant. Les perdre donnait « …votre présence.Cela se passe à… »."""
        table = {"Bonjour.": "Hello."}
        dire = langue.traducteur("en", table)
        self.assertEqual(dire(" Bonjour. "), " Hello. ")
        self.assertEqual(dire("Bonjour."), "Hello.")
        self.assertEqual(dire("\nBonjour."), "\nHello.")
        self.assertEqual(dire(" inconnue "), " inconnue ")

    def test_la_plage_d_appel_suit_la_langue(self):
        """Elle est dictée à l'agent dans sa sortie de secours : « qui vous
        rappellera entre… ». Restée française, elle serait lue telle quelle."""
        prefs = self._preferences("fr")
        self.assertIn("entre", themes.plage_lisible(prefs))
        self.assertIn("between", themes.plage_lisible(prefs, "en"))

    def test_les_dates_DANS_les_faits_suivent_la_langue(self):
        """⚠ LE DERNIER RESTE, ET LE PLUS SOURNOIS. « Créneau libéré : mardi
        15 septembre 2026 à 9 heures 40 » au milieu d'un texte anglais : lu par
        une voix anglaise, à un patient anglophone."""
        prefs = self._preferences("en")
        texte = assistant.construire_consigne(
            "creneau_libere", self._infos("creneau_libere"), prefs,
            {"liberer_creneau": True}).texte()
        self.assertIn("September", texte)
        self.assertNotIn("septembre", texte)


class TestLeGesteDeChargementSuitLaLangue(_TestAvecServeurWeb):
    """⚠ L'ESSAI QUI MANQUAIT, ET C'EST UN ESSAI DU GESTE (01/09/2026).

    Le décor anglophone était fait, éprouvé, et la contre-épreuve le tenait.
    Mais le BOUTON qui le charge appelait encore `jeu_essai.charger(base)`
    sans la langue : le geste que le juré fera — ⚙ Réglages → 🧪 Essais →
    « Charger le jeu d'essai » — rendait un décor français dans un écran
    anglais.

    Aucun des 1 193 essais ne l'a vu. C'est en exerçant le produit POUR DE
    VRAI, par sa propre route HTTP, que le défaut est apparu.

    ⚠ LA LEÇON, ET ELLE EST DÉJÀ ÉCRITE DANS CE PROJET : éprouver la fonction
    ne prouve pas que le bouton l'appelle.
    """

    def _charger(self, langue_code):
        """Les noms que LE GESTE ajoute — pas ceux qui étaient déjà là.

        ⚠ QUATRE CONTACTS SONT SEMÉS À LA CRÉATION DE LA BASE, avant qu'une
        langue ait pu être choisie (voir `jeu_essai.PREMIERS_CONTACTS`). Les
        compter ici ferait échouer l'essai sur un comportement correct — et
        surtout l'empêcherait de mesurer ce qu'il vise : ce que le BOUTON
        charge.
        """
        avant = {contact["nom"]
                 for contact in self.application.base.lister_clients()}
        self.application.preferences.definir(langue.CLE_LANGUE, langue_code)
        code, _ = self._poster("/reglages/jeu-essai",
                               {"action": "charger", "confirmer": "oui"})
        self.assertIn(code, (200, 303))
        return [contact["nom"]
                for contact in self.application.base.lister_clients()
                if contact["nom"] not in avant]

    def test_le_geste_charge_le_decor_de_la_langue_choisie(self):
        noms = self._charger("en")
        self.assertEqual(
            self.application.base.compter_clients_jeu_essai(),
            len(jeu_essai.CLIENTS))
        anglais, _, _, _ = jeu_essai.decor("en")
        attendus = {c[0] for c in anglais}
        trouves = sum(1 for nom in noms if nom in attendus)
        self.assertGreaterEqual(
            trouves, 70,
            f"seulement {trouves} noms anglais chargés — le geste n'a pas "
            "transmis la langue")
        francais = {c[0] for c in jeu_essai.CLIENTS} - attendus
        restes = sorted(nom for nom in noms if nom in francais)
        self.assertEqual(restes, [], "des noms français ont été chargés")

    def test_en_francais_le_geste_charge_le_decor_francais(self):
        """La contre-épreuve du précédent : la langue par défaut n'a pas
        changé de décor."""
        noms = self._charger("fr")
        attendus = {c[0] for c in jeu_essai.CLIENTS}
        trouves = sum(1 for nom in noms if nom in attendus)
        self.assertGreaterEqual(trouves, 70)


class TestLesSixVerrousSansGardien(unittest.TestCase):
    """⚠ ÉCRITS PARCE QUE LA CONTRE-ÉPREUVE LES A DÉSIGNÉS (01/09/2026).

    Neuf verrous du bilingue neutralisés un par un : **trois seulement** ont
    fait rougir un essai. Les six autres étaient en place, corrects, et gardés
    par personne — un jour, quelqu'un les enlève et rien ne le dit.

    Chacun de ces essais éprouve le RÉSULTAT, pas la mécanique : ce qui part,
    ce qui s'affiche, ce que le décor contient vraiment.
    """

    def _preferences(self, langue_code):
        prefs = generation.Preferences()
        for jour in range(7):
            horaires.basculer_periode(prefs, jour, 8 * 60, 19 * 60, "ouvrir")
        prefs.definir(themes.CLE_PLAGE_DEBUT, "00:00")
        prefs.definir(themes.CLE_PLAGE_FIN, "23:59")
        prefs.definir(themes.CLE_ENTREPRISE, "Val Fleuri Physiotherapy")
        prefs.definir(langue.CLE_LANGUE, langue_code)
        return prefs

    # ------------------------------------------------ verrous 1 et 2
    def test_le_message_d_ouverture_est_traduit(self):
        """⚠ CE QUI EST DIT MOT POUR MOT. C'est la seule partie de la consigne
        que l'agent récite : la laisser en français rendrait tout le reste
        inutile — le patient entendrait du français dès la première seconde."""
        # ⚠ AVEC UN LIEU ET UNE DURÉE, POUR ÉPROUVER LES SEGMENTS
        # CONDITIONNELS. Un gabarit est fait de morceaux : les uns toujours
        # présents, les autres suspendus à une information d'étape 2
        # (« si duree », « si lieu »). Une première écriture de cet essai ne
        # renseignait ni l'un ni l'autre : les segments conditionnels ne
        # sortaient pas, et l'essai restait vert même en cessant de les
        # traduire. La contre-épreuve l'a montré.
        infos = {"creneau_libere": "2026-09-15T09:40",
                 "entreprise": "Val Fleuri Physiotherapy",
                 "duree": "30 minutes", "lieu": "12 Harley Street"}
        ouvertures = {}
        for code in ("fr", "en"):
            ouvertures[code] = assistant.construire_mission(
                "creneau_libere", infos, self._preferences(code),
                {"liberer_creneau": True})
        self.assertIn("Bonjour", ouvertures["fr"])
        self.assertIn("Hello", ouvertures["en"])
        self.assertNotIn("Bonjour", ouvertures["en"])
        self.assertNotIn("s'est libérée", ouvertures["en"])
        # Les segments conditionnels, nommément.
        self.assertIn("La séance dure", ouvertures["fr"])
        self.assertIn("Cela se passe à", ouvertures["fr"])
        self.assertNotIn("La séance dure", ouvertures["en"])
        self.assertNotIn("Cela se passe à", ouvertures["en"])

    def test_l_objectif_et_l_entete_sont_traduits(self):
        """⚠ ON AFFIRME LA LIGNE D'OBJECTIF, PAS SEULEMENT L'ENTÊTE. Une
        première écriture vérifiait « You are » (l'entête) et l'absence de
        « Tu es un assistant » : en cessant de traduire l'OBJECTIF, les deux
        restaient vraies et l'essai restait vert. La contre-épreuve l'a
        montré — deux pièces différentes demandent deux affirmations."""
        infos = {"entreprise": "Val Fleuri Physiotherapy",
                 "rdv_existant": "2026-09-15T09:40"}
        textes = {code: assistant.construire_consigne(
            "confirmation", infos, self._preferences(code), {}).texte()
            for code in ("fr", "en")}
        # ① l'entête
        self.assertIn("Tu es un assistant", textes["fr"])
        self.assertIn("You are", textes["en"])
        self.assertNotIn("Tu es un assistant", textes["en"])
        # ② l'objectif, ligne à ligne — c'est une AUTRE pièce
        objectif = assistant.NATURES["confirmation"]["objectif"]
        self.assertIn(f"Ton objectif : {objectif}", textes["fr"])
        self.assertNotIn(objectif, textes["en"])
        self.assertIn("Your objective:", textes["en"])

    # ------------------------------------------------ verrou 7
    def test_le_decor_anglais_est_VRAIMENT_anglais(self):
        """⚠ SANS CET ESSAI, LE DÉCOR POUVAIT REDEVENIR FRANÇAIS EN SILENCE.
        Les autres essais du décor vérifiaient sa STRUCTURE — comptes,
        homonymes, numéros — et cette structure est la même dans les deux
        langues par construction. Aucun ne disait qu'il avait changé de
        langue."""
        fr_clients, fr_rdv, _, fr_metier = jeu_essai.decor("fr")
        en_clients, en_rdv, _, en_metier = jeu_essai.decor("en")
        self.assertNotEqual(en_metier, fr_metier)
        differents = sum(1 for a, b in zip(fr_clients, en_clients)
                         if a[0] != b[0])
        self.assertGreaterEqual(
            differents, 70,
            f"seulement {differents} noms sur {len(fr_clients)} ont changé")
        motifs_en = {r[4] for r in en_rdv}
        self.assertNotIn("Kinésithérapie respiratoire", motifs_en)
        self.assertTrue(any("rehabilitation" in m for m in motifs_en),
                        "aucun motif anglais dans le décor anglais")

    # ------------------------------------------------ verrou 8
    def test_le_numero_de_renvoi_accepte_tous_les_indicatifs(self):
        """Sa demande du 01/09 : « n'importe quel indicatif, comme ça les
        jurés peuvent tester aussi »."""
        for tape, attendu in (("+44 20 7946 0958", "+44 20 79 46 09 58"),
                              ("+1 212 555 0198", "+1 21 25 55 01 98"),
                              ("+351 21 234 5678", "+351 2 12 34 56 78"),
                              ("+442079460958", "+44 20 79 46 09 58")):
            with self.subTest(tape=tape):
                self.assertEqual(saisie.valider_telephone_essai(tape), attendu)

    def test_le_numero_francais_ne_change_pas_de_forme(self):
        """⚠ AU CARACTÈRE PRÈS. Un numéro déjà enregistré repasse par ce
        validateur à chaque relecture : s'il en ressortait autrement, le
        masquage et la comparaison de numéros d'essai changeraient de sens."""
        for tape in ("06 39 98 00 24", "+33 6 39 98 00 24", "0639980024"):
            with self.subTest(tape=tape):
                self.assertEqual(saisie.valider_telephone_essai(tape),
                                 saisie.valider_telephone(tape))

    def test_ce_qui_n_est_pas_un_numero_reste_refuse(self):
        """⚠ LA CONTRE-ÉPREUVE DU VERROU : élargir ne veut pas dire ouvrir.
        Un numéro illisible doit être refusé À LA SAISIE, sinon la faute se
        découvre le jour où l'on coche la case — et RingBack appelle alors les
        vrais contacts, ce que cette case promet d'empêcher."""
        for tape in ("bonjour", "+33", "12345", "+0123456789", "",
                     "contact@example.com", "+4420794609581234567"):
            with self.subTest(tape=tape):
                with self.assertRaises(saisie.SaisieInvalide):
                    saisie.valider_telephone_essai(tape)

    def test_un_numero_de_CONTACT_reste_francais(self):
        """La frontière : les numéros que le produit APPELLE ne bougent pas."""
        with self.assertRaises(saisie.SaisieInvalide):
            saisie.valider_telephone("+44 20 7946 0958")

    # ------------------------------------------------ verrou 9
    def test_les_civilites_ne_sont_developpees_qu_en_francais(self):
        """⚠ « monsieur Smith » SERAIT UNE FAUTE. Le développement vient d'un
        constat fait à l'oreille sur des appels français — « M. » mal lu par
        l'agent. « Mr Smith » se lit très bien tel quel."""
        infos = {"entreprise": "Val Fleuri Physiotherapy",
                 "rdv_existant": "2026-09-15T09:40"}
        contact = {"nom": "M. Jean Dupont", "champs": "{}"}
        for code, doit, ne_doit_pas in (("fr", "monsieur", "M. Jean"),
                                        ("en", "M. Jean", "monsieur")):
            with self.subTest(langue=code):
                cadre = assistant.construire_consigne(
                    "confirmation", infos, self._preferences(code), {})
                texte = cadre.substituer({"identite": "M. Jean Dupont"}).texte()
                self.assertIn(doit, texte)
                self.assertNotIn(ne_doit_pas, texte)


class TestLaLangueDeLAgentSuitLaConsigne(unittest.TestCase):
    """⚠ LA VOIX ET LES MOTS BOUGENT ENSEMBLE, OU PAS DU TOUT.

    Une consigne anglaise envoyée avec `locale: fr-FR` ferait lire de l'anglais
    à une voix française, avec sa prosodie : pire que de tout laisser en
    français. Le couple (région, locale) suit donc le même réglage que la
    consigne, et il est RELU à chaque départ d'appel.
    """

    def _client(self, langue_appel):
        client = calle_client.AppelReel.__new__(calle_client.AppelReel)
        client.langue_appel = langue_appel
        return client

    def test_le_couple_suit_la_langue(self):
        self.assertEqual(self._client("fr")._region_et_locale(),
                         ("FR", "fr-FR"))
        self.assertEqual(self._client("en")._region_et_locale(),
                         ("GB", "en-GB"))

    def test_il_est_RELU_a_chaque_appel(self):
        """⚠ RELU, JAMAIS RETENU. Le client réel est construit UNE fois au
        démarrage du serveur : une langue changée en cours de route n'aurait
        aucun effet, et l'écran dirait le contraire de ce qui part."""
        choisie = ["fr"]
        client = self._client(lambda: choisie[0])
        self.assertEqual(client._region_et_locale(), ("FR", "fr-FR"))
        choisie[0] = "en"
        self.assertEqual(client._region_et_locale(), ("GB", "en-GB"))

    def test_une_langue_illisible_retombe_sur_le_francais(self):
        for valeur in (None, "", "klingon", 42,
                       lambda: (_ for _ in ()).throw(ValueError("cassé"))):
            with self.subTest(valeur=valeur):
                self.assertEqual(self._client(valeur)._region_et_locale(),
                                 ("FR", "fr-FR"))


class TestLeDecorDEssaiSuitLaLangue(unittest.TestCase):
    """⚠ LE JEU D'ESSAI EST UN BANC, PAS UNE LISTE DE NOMS.

    Il porte exprès des civilités variées, des particules, des noms composés,
    un nom très long, DEUX HOMONYMES, deux fiches sans numéro, deux 🚫 —
    chacune éprouve une règle du produit. Une distribution anglophone qui
    perdrait ces propriétés ne serait plus un banc.
    """

    def test_la_structure_est_la_meme_dans_les_deux_langues(self):
        fr_clients, fr_rdv, fr_premiers, _ = jeu_essai.decor("fr")
        en_clients, en_rdv, en_premiers, _ = jeu_essai.decor("en")
        self.assertEqual(len(en_clients), len(fr_clients))
        self.assertEqual(len(en_rdv), len(fr_rdv))
        self.assertEqual(len(en_premiers), len(fr_premiers))

    def test_les_numeros_et_les_statuts_ne_bougent_PAS(self):
        """⚠ LES NUMÉROS SONT DES NUMÉROS DE FICTION VÉRIFIÉS (racines Arcep) :
        les toucher ferait sortir le jeu d'essai de la série qui ne peut
        appeler personne. Les statuts, eux, sont des DONNÉES stockées."""
        fr_clients, fr_rdv, _, _ = jeu_essai.decor("fr")
        en_clients, en_rdv, _, _ = jeu_essai.decor("en")
        self.assertEqual([c[1] for c in en_clients],
                         [c[1] for c in fr_clients])
        self.assertEqual([c[2] for c in en_clients],
                         [c[2] for c in fr_clients])
        self.assertEqual([r[1:4] for r in en_rdv], [r[1:4] for r in fr_rdv])
        self.assertEqual([r[5] for r in en_rdv], [r[5] for r in fr_rdv])

    def test_les_homonymes_restent_homonymes(self):
        """La clé d'un contact est (nom, téléphone) : deux fiches de même nom
        éprouvent cette règle. Sans elles, elle n'est plus éprouvée."""
        for langue_code in ("fr", "en"):
            with self.subTest(langue=langue_code):
                clients, _, _, _ = jeu_essai.decor(langue_code)
                noms = [c[0] for c in clients]
                doubles = {nom for nom in noms if noms.count(nom) > 1}
                self.assertTrue(doubles,
                                "le décor a perdu ses homonymes")

    def test_les_deux_fiches_sans_numero_restent(self):
        for langue_code in ("fr", "en"):
            with self.subTest(langue=langue_code):
                clients, _, _, _ = jeu_essai.decor(langue_code)
                self.assertEqual(
                    sum(1 for c in clients if not c[1]),
                    sum(1 for c in jeu_essai.CLIENTS if not c[1]))

    def test_chaque_rendez_vous_trouve_son_contact(self):
        """⚠ L'ESSAI QUI ATTRAPE UNE DISTRIBUTION INCOMPLÈTE. Les rendez-vous
        désignent leur patient PAR SON NOM : un nom traduit d'un côté et pas
        de l'autre ferait lever le chargement, et le geste « charger le jeu
        d'essai » tomberait en panne devant le juré."""
        for langue_code in ("fr", "en"):
            with self.subTest(langue=langue_code):
                clients, rdv, _, _ = jeu_essai.decor(langue_code)
                connus = {c[0] for c in clients}
                orphelins = sorted({r[0] for r in rdv} - connus)
                self.assertEqual(orphelins, [])

    def test_le_chargement_marche_dans_les_deux_langues(self):
        """⚠ ON CHARGE POUR DE VRAI, on ne relit pas des tuples. C'est le
        geste que le juré fera."""
        for langue_code in ("fr", "en"):
            with self.subTest(langue=langue_code):
                base = db.Base(":memory:")
                clients, rdv = jeu_essai.charger(base,
                                                 langue_code=langue_code)
                self.assertEqual(clients, len(jeu_essai.CLIENTS))
                self.assertEqual(rdv, len(jeu_essai.RENDEZVOUS))
                # Et un second chargement ne double rien, comme en français.
                self.assertEqual(
                    jeu_essai.charger(base, langue_code=langue_code), (0, 0))


class TestLesDatesDansLesDeuxLangues(unittest.TestCase):
    """⚠ TRADUIRE LES SEULS NOMS DE JOURS DONNERAIT UNE DATE FAUSSE.

    « monday 03/08/2026 » se lit « 8 mars » pour un anglophone. Le format
    anglais écrit donc le mois en lettres, et l'heure parlée passe sur
    l'horloge de 12 heures — « half past two », jamais « fourteen thirty ».
    """

    def test_le_francais_est_inchange(self):
        """⚠ LES VALEURS SONT ÉCRITES EN TOUTES LETTRES, pas recalculées. Un
        essai qui redemanderait au produit ce qu'il produit ne pourrait pas
        échouer."""
        self.assertEqual(themes.date_lisible("2026-08-24T10:20"),
                         "le 24/08/2026 à 10h20")
        self.assertEqual(themes.date_parlee("2026-08-24T10:20"),
                         "lundi 24 août 2026 à 10 heures 20")
        self.assertEqual(themes.date_parlee("2026-08-24T09:00"),
                         "lundi 24 août 2026 à 9 heures")

    def test_l_anglais_ecrit_le_mois_en_lettres(self):
        self.assertEqual(themes.date_lisible("2026-08-24T10:20", "en"),
                         "on 24 Aug 2026 at 10:20")
        self.assertEqual(themes.date_parlee("2026-08-24T10:20", "en"),
                         "Monday 24 August 2026 at 10:20 am")

    def test_l_heure_parlee_anglaise_est_sur_douze_heures(self):
        for iso, attendu in (("2026-08-24T14:30", "2:30 pm"),
                             ("2026-08-24T09:00", "9 am"),
                             ("2026-08-24T00:30", "12:30 am"),
                             ("2026-08-24T12:00", "12 pm"),
                             ("2026-08-24T23:59", "11:59 pm")):
            with self.subTest(iso=iso):
                self.assertTrue(
                    themes.date_parlee(iso, "en").endswith(attendu),
                    themes.date_parlee(iso, "en"))

    def test_ce_qui_est_dit_se_relit_dans_les_deux_langues(self):
        """L'aller-retour, sur une année entière et dans les deux langues :
        ce que le produit ÉCRIT, il doit savoir le RELIRE."""
        quand = datetime.datetime(2026, 1, 1)
        fin = datetime.datetime(2027, 1, 1)
        compte = 0
        while quand < fin:
            iso = quand.isoformat(timespec="minutes")
            for parlee in (themes.date_parlee(iso),
                           themes.date_parlee(iso, "en")):
                self.assertEqual(themes.lire_date(parlee), iso, parlee)
                compte += 1
            quand += datetime.timedelta(hours=7)
        self.assertGreater(compte, 2000, "l'essai doit couvrir l'année")


class TestLeLecteurDeDatesNePlantePlus(unittest.TestCase):
    """⚠ UN PLANTAGE RÉEL, TROUVÉ EN PRÉPARANT LE BILINGUE (01/09/2026).

    `lire_date("08/25/2026 09:00")` levait `ValueError: month must be in
    1..12`, NON RATTRAPÉE. Ce n'est pas un défaut d'anglais : une faute de
    frappe de l'agent — « 25/13/2026 » — suffisait à faire échouer un appel
    réel en français, sur une exception que personne ne rattrapait.
    """

    def test_une_date_impossible_rend_None_au_lieu_de_lever(self):
        for texte in ("08/25/2026 09:00", "25/13/2026 09:00",
                      "31/02/2026 09:00", "00/00/2026 09:00",
                      "32/01/2026 09:00", "29/02/2027 09:00"):
            with self.subTest(texte=texte):
                try:
                    obtenu = themes.lire_date(texte)
                except Exception as erreur:      # noqa: BLE001
                    self.fail(f"{texte!r} a levé {type(erreur).__name__}")
                self.assertIn(obtenu, (None, "2026-08-25T09:00"))

    def test_c_est_LE_LECTEUR_DE_DATE_qui_ecarte_l_impossible(self):
        """⚠ ET C'EST BIEN `_date_lue` QUI TRANCHE, PAS LE FILET.

        `lire_date` porte aussi un try/except — une ceinture en plus des
        bretelles. Mais un essai qui ne regarde que `lire_date` reste vert
        quand on retire le VRAI contrôle : le filet rattrape et rend None
        pareil. Mesuré par la contre-épreuve du 01/09/2026 — l'essai
        ci-dessus ne tenait rien.

        Le contrôle appartient à `_date_lue`, seule fonction qui sache ce que
        les trois nombres veulent dire. On l'éprouve donc directement.
        """
        for texte in ("25/13/2026", "31/02/2026", "00/00/2026",
                      "32/01/2026", "29/02/2027"):
            with self.subTest(texte=texte):
                self.assertIsNone(themes._date_lue(texte),
                                  "une date impossible est passée")
        # Et les dates possibles passent toujours, dans les deux ordres.
        self.assertEqual(themes._date_lue("25/08/2026"), (2026, 8, 25))
        self.assertEqual(themes._date_lue("08/25/2026"), (2026, 8, 25))
        self.assertEqual(themes._date_lue("29/02/2028"), (2028, 2, 29))

    def test_l_ordre_des_nombres_se_deduit_quand_il_le_peut(self):
        """⚠ ON DÉDUIT, ON NE DEVINE PAS. « 25/08 » n'est lisible que
        jour/mois, « 08/25 » que mois/jour. Quand les deux nombres sont ≤ 12,
        aucune déduction n'est possible : on garde l'ordre du calendrier."""
        self.assertEqual(themes.lire_date("25/08/2026 09:00"),
                         "2026-08-25T09:00")
        self.assertEqual(themes.lire_date("08/25/2026 09:00"),
                         "2026-08-25T09:00")
        self.assertEqual(themes.lire_date("01/02/2026 09:00"),
                         "2026-02-01T09:00")

    def test_les_formes_anglaises_sont_lues(self):
        """Sans elles, CHAQUE rendez-vous convenu en anglais partait « à
        rappeler par un humain » — mesuré : six formes, six fois None."""
        for texte, attendu in (
                ("Monday 24 August 2026 at 10:20 am", "2026-08-24T10:20"),
                ("Monday, 24 August 2026 at 10:20 am", "2026-08-24T10:20"),
                ("August 25, 2026 9:00 AM", "2026-08-25T09:00"),
                ("Aug 25 2026 at 12:00 pm", "2026-08-25T12:00"),
                ("Aug 25 2026 at 12:00 am", "2026-08-25T00:00"),
                ("25 August 2026 at 2:30 p.m.", "2026-08-25T14:30")):
            with self.subTest(texte=texte):
                self.assertEqual(themes.lire_date(texte), attendu)

    def test_pm_deplace_l_heure_de_douze_heures(self):
        """⚠ « pm » N'EST PAS UNE DÉCORATION. Lire « 2:30 pm » comme 2:30
        poserait un rendez-vous DOUZE HEURES trop tôt — et l'heure resterait
        assez plausible pour que personne ne voie la faute à l'écran."""
        self.assertEqual(themes.lire_date("25 August 2026 at 2:30 pm"),
                         "2026-08-25T14:30")
        self.assertEqual(themes.lire_date("25 August 2026 at 2:30 am"),
                         "2026-08-25T02:30")

    def test_le_francais_lit_toujours_comme_avant(self):
        """La contre-épreuve : l'anglais ne doit rien avoir pris au français."""
        for texte, attendu in (
                ("2026-08-25T09:00", "2026-08-25T09:00"),
                ("2026-08-25 09:00:00", "2026-08-25T09:00"),
                ("le mardi 25 août 2026 à 9 heures 20", "2026-08-25T09:20"),
                ("25 aout 2026 9h", "2026-08-25T09:00"),
                ("25/08/2026 à 09h00", "2026-08-25T09:00"),
                ("n'importe quoi", None)):
            with self.subTest(texte=texte):
                self.assertEqual(themes.lire_date(texte), attendu)


class TestCeQuiSeDitAuTelephone(unittest.TestCase):
    """⚠ SA DEMANDE DU 24/08/2026, la veille de ses essais réels : « que les
    dates quelle que soit la campagne soient bien transmises à l'agent sous la
    forme : de 2026-08-24 10:20 vers Lundi 24 août 2026 à 10 heure 20 ».

    MESURÉ AVANT DE CHANGER QUOI QUE CE SOIT, sur le vrai chemin (une campagne
    montée par les écrans, un espion à la place du client d'appels) : l'ISO brut
    n'y était pas — mais ce qui partait était « le 25/08/2026 à 09h00 ». Des
    chiffres et des barres obliques, qu'un agent vocal n'a aucun moyen de lire
    autrement que « vingt-cinq barre zéro huit ».
    """

    # ---------------------------------------------------- LE FORMAT, LITTÉRAL
    def test_une_date_se_dit_en_toutes_lettres(self):
        """⚠ L'ESSAI QUI ÉPINGLE LE FORMAT. Tous les autres comparent le produit
        à lui-même (ils appellent `date_parlee`) : ils prouvent la cohérence, pas
        la forme. Celui-ci écrit les lettres attendues, et c'est le seul."""
        self.assertEqual(themes.date_parlee("2026-08-24T10:20"),
                         "lundi 24 août 2026 à 10 heures 20")

    def test_une_heure_pile_ne_dit_pas_zero_zero(self):
        """Son choix du 24/08 : le français d'un secrétariat au téléphone."""
        self.assertEqual(themes.date_parlee("2026-08-25T09:00"),
                         "mardi 25 août 2026 à 9 heures")
        # « heure » au singulier à une heure, et rien d'autre.
        self.assertEqual(themes.date_parlee("2026-08-26T01:05"),
                         "mercredi 26 août 2026 à 1 heure 05")

    def test_l_annee_est_toujours_dite(self):
        """Son choix du 24/08. Une date sans année, dite en décembre pour un
        rendez-vous de janvier, est ambiguë — et personne ne s'en aperçoit avant
        que quelqu'un se présente onze mois trop tôt."""
        for iso in ("2026-01-02T14:30", "2027-12-31T08:00"):
            with self.subTest(iso=iso):
                self.assertIn(iso[:4], themes.date_parlee(iso))

    def test_le_jour_reste_en_minuscule(self):
        """La date s'emploie DANS une phrase — « votre rendez-vous du lundi 24
        août ». Une majuscule au milieu d'une phrase serait une faute, et c'est
        un texte lu par une machine à une personne."""
        self.assertTrue(themes.date_parlee("2026-08-24T10:20").startswith("lundi"))

    def test_ce_qui_n_est_pas_une_date_n_est_pas_invente(self):
        for brut in ("", None, "la semaine prochaine"):
            with self.subTest(brut=brut):
                self.assertEqual(themes.date_parlee(brut), brut or "")

    # ------------------------------------------- LES ÉCRANS NE CHANGENT PAS
    def test_les_ecrans_gardent_le_format_court(self):
        """⚠ LE REVERS, ET IL COMPTE AUTANT. Un tableau se lit en colonne : y
        écrire « lundi 24 août 2026 à 10 heures 20 » allongerait chaque ligne de
        chaque liste du produit sans que personne l'ait demandé. Deux besoins,
        deux fonctions — et cet essai empêche qu'on les confonde plus tard."""
        self.assertEqual(themes.date_lisible("2026-08-24T10:20"),
                         "le 24/08/2026 à 10h20")
        self.assertEqual(assistant.date_courte("2026-08-24T10:20"),
                         "24/08/2026 à 10h20")


class TestAucuneDateEnChiffresNePartVersLAgent(_CampagneAssistant):
    """⚠ LA RÈGLE À SON POINT DE PASSAGE, ET SUR TOUTES LES NATURES.

    « quelle que soit la campagne », mot pour mot. Éprouver une nature à la fois
    laisserait passer celle qu'on aurait oubliée — et c'est exactement ce qui
    est arrivé le 17/08 sur les créneaux (« la demi-correction »).

    On capture le texte EXACT du champ « task » en remplaçant le client
    d'appels par un espion : aucun appel n'est passé, et ce qu'on lit est ce
    qui partirait.
    """

    class Espion(calle_client.ClientAppels):
        def __init__(self):
            self.taches = []

        def _garder(self, consigne):
            self.taches.append(consigne.texte() if consigne else "")

        def appeler(self, nom_client, telephone, rendezvous, mission=None,
                    consigne=None, nature=None):
            self._garder(consigne)
            raise calle_client.PasDeReponse("espion : aucun appel")

        def appeler_cascade(self, nom_client, telephone, mission, creneau,
                            consigne=None, nature=None):
            self._garder(consigne)
            raise calle_client.PasDeReponse("espion : aucun appel")

    # Ce qu'on refuse de voir partir : une date en chiffres, sous ses deux
    # écritures. Les exemples de FORMAT dictés à l'agent (« écris la date au
    # format 2026-08-15T14:30 ») sont retirés avant : ils ne sont pas dits, ils
    # disent à la machine ce qu'elle doit écrire dans son résultat.
    CHIFFREE = re.compile(r"\d{1,2}/\d{1,2}/\d{4}|\d{4}-\d{2}-\d{2}")

    def _ouvrir_la_semaine(self):
        for jour in range(5):
            self._poster("/reglages/semaine",
                         {"jour": str(jour), "debut": "09:00", "fin": "18:00",
                          "geste": "ouvrir"})

    def _tache_de(self, nature, lignes):
        campagne = self._campagne(nature, lignes, reprendre_les_calculs=True)
        espion = self.Espion()
        self.application.planif.client_appels = espion
        try:
            assistant.executer_campagne(self.application, campagne)
        except Exception:                                    # noqa: BLE001
            pass
        self.assertTrue(espion.taches, f"aucun appel tenté sur « {nature} »")
        return espion.taches[0]

    def test_aucune_nature_ne_dicte_une_date_en_chiffres(self):
        self._ouvrir_la_semaine()
        avec_rdv = ["Mme Martin;+33 6 00 00 00 53;2026-09-14T10:20;séance"]
        cas = {"deplacement": avec_rdv, "confirmation": avec_rdv,
               "rappel_rdv": avec_rdv,
               "prise_rdv": ["Mme Martin;+33 6 00 00 00 53;séance"]}
        for nature, lignes in cas.items():
            with self.subTest(nature=nature):
                tache = self._tache_de(nature, lignes)
                # On ôte les EXEMPLES de format destinés au résultat structuré.
                dit = tache.replace("2026-08-15T14:30", "")
                restantes = self.CHIFFREE.findall(dit)
                self.assertEqual(
                    restantes, [],
                    f"« {nature} » dicterait des dates en chiffres : {restantes}")

    def test_et_les_dates_y_sont_bien_en_toutes_lettres(self):
        """⚠ LA MOITIÉ QUI MANQUERAIT SINON. « Aucune date en chiffres » serait
        aussi vrai d'un texte sans AUCUNE date — et c'est un dénouement qu'on
        a déjà vécu (le stock vide annoncé comme une liste)."""
        self._ouvrir_la_semaine()
        tache = self._tache_de(
            "deplacement", ["Mme Martin;+33 6 00 00 00 53;2026-09-14T10:20;séance"])
        self.assertIn("lundi 14 septembre 2026 à 10 heures 20", tache)
        self.assertTrue(MOTIF_DATE_PARLEE.findall(tache),
                        "aucune place dite en toutes lettres")


class TestLeStockDeNegociationArriveJusquALAgent(_CampagneAssistant):
    """⚠ MESURÉ LE 24/08/2026, la veille de ses essais réels — il n'avait pas
    signalé celui-là.

    Sur une campagne de ONZE déplacements : **77 places enregistrées** à la
    création (sa règle du 17/08 : sept par rendez-vous à replacer), et **six
    dictées à l'agent** — toutes la même matinée, en 1 h 15. Le recalcul de
    l'instant de l'appel écrasait le stock avec la liste des six prochaines
    places libres, qui sert à OUVRIR la conversation, pas à négocier.

    C'est mot pour mot le dénouement que sa demande du 16/08/2026 avait fait
    corriger : « les six premières se suivent — même matinée, souvent la même
    heure à vingt minutes près. L'agent n'avait donc rien à négocier : "non" sur
    la première valait "non" sur les six. » La règle était écrite, appliquée à
    la création — et perdue au dernier maillon.
    """

    A_DEPLACER = 11

    class Espion(calle_client.ClientAppels):
        def __init__(self):
            self.taches = []

        def appeler(self, nom_client, telephone, rendezvous, mission=None,
                    consigne=None, nature=None):
            self.taches.append(consigne.texte() if consigne else "")
            raise calle_client.PasDeReponse("espion : aucun appel")

        def appeler_cascade(self, *args, **mots):
            raise calle_client.PasDeReponse("espion : aucun appel")

    def _campagne_de_onze(self):
        for jour in range(5):
            self._poster("/reglages/semaine",
                         {"jour": str(jour), "debut": "08:00", "fin": "18:00",
                          "geste": "ouvrir"})
        lignes = [f"Mme N{n};{self._numero('53', f'00 00 {10 + n:02d}')};"
                  f"2026-09-1{n % 5}T1{n % 9}:00;séance"
                  for n in range(self.A_DEPLACER)]
        return self._campagne("deplacement", lignes, reprendre_les_calculs=True)

    @staticmethod
    def _numero(terminaison, prefixe="00 00 00"):
        """⚠ CONSTRUIT, JAMAIS ÉCRIT EN DUR. `preparer_publication.py` refuse
        tout numéro en clair hors de la série de fiction documentée, et il a
        raison : un numéro recopié dans un essai finit par être un vrai."""
        return f"+33 6 {prefixe} {terminaison}"

    def _ligne_de_negociation(self, campagne):
        espion = self.Espion()
        self.application.planif.client_appels = espion
        try:
            assistant.executer_campagne(self.application, campagne)
        except Exception:                                    # noqa: BLE001
            pass
        self.assertTrue(espion.taches, "aucun appel tenté")
        lignes = [ligne for ligne in espion.taches[0].splitlines()
                  if "négocier" in ligne]
        self.assertTrue(lignes, "la consigne ne porte aucun stock")
        return lignes[0]

    def test_le_stock_arrive_entier_jusqu_a_l_agent(self):
        campagne = self._campagne_de_onze()
        enregistre = set(MOTIF_DATE_PARLEE.findall(
            assistant.configuration_campagne(
                self.application.base.obtenir_campagne(campagne)
            )["infos"]["creneaux_remplacement"]))
        dictees = set(MOTIF_DATE_PARLEE.findall(
            self._ligne_de_negociation(campagne)))
        # ⚠ LE CHIFFRE DE SA RÈGLE, pas un « c'est mieux qu'avant ».
        attendu = self.A_DEPLACER * horaires.PAR_RENDEZVOUS_A_DEPLACER
        self.assertGreaterEqual(len(enregistre), attendu)
        self.assertGreaterEqual(
            len(dictees), attendu,
            f"l'agent n'entend que {len(dictees)} places sur {len(enregistre)}")

    def test_et_elles_restent_etalees_a_l_instant_de_l_appel(self):
        """⚠ COMPTER NE SUFFIT PAS : soixante-dix-sept places d'affilée le même
        matin ne se négocient pas mieux que six. C'est l'ÉTALEMENT qui fait le
        stock — plusieurs jours, le matin ET l'après-midi."""
        dictees = MOTIF_DATE_PARLEE.findall(
            self._ligne_de_negociation(self._campagne_de_onze()))
        jours = {date.split(" 2026")[0] for date in dictees}
        self.assertGreaterEqual(
            len(jours), horaires.JOURS_COUVERTS_NEGO,
            f"l'agent n'a que {len(jours)} journée(s) à proposer")
        heures = [int(date.split("à ")[1].split(" ")[0]) for date in dictees]
        self.assertTrue([h for h in heures if h < horaires.HEURE_BASCULE_MIDI],
                        "aucune place le matin")
        self.assertTrue([h for h in heures if h >= horaires.HEURE_BASCULE_MIDI],
                        "aucune place l'après-midi")

    def test_le_message_d_ouverture_ne_recite_pas_le_stock(self):
        """LA CONTRE-ÉPREUVE : un stock plus large ne doit pas se mettre à se
        réciter. Ce qu'on dit en ouvrant reste UNE date."""
        campagne = self._campagne_de_onze()
        espion = self.Espion()
        self.application.planif.client_appels = espion
        try:
            assistant.executer_campagne(self.application, campagne)
        except Exception:                                    # noqa: BLE001
            pass
        ouverture = espion.taches[0].split("mot pour mot :")[1].split("\n\n")[0]
        self.assertEqual(len(MOTIF_DATE_PARLEE.findall(ouverture)), 1,
                         f"l'ouverture récite le catalogue : {ouverture[:200]}")


class TestLaDateRendueRevientAuFormatDuCalendrier(unittest.TestCase):
    """⚠ SA DEMANDE DU 24/08/2026 : « lorsqu'il renvoie la réponse du choix du
    créneau, il faut pouvoir avoir le format utilisé dans le calendrier ».

    MESURÉ : la chaîne rendue par l'agent partait TELLE QUELLE dans la colonne
    « horaire » du planning. « 2026-08-25T09:00 », « 2026-08-25 09:00 » et
    « 2026-08-25T09:00:00 » sont le MÊME instant : ils entraient en base sous
    trois écritures différentes, et la comparaison de textes qui décide quelle
    place a été retenue en refusait deux sur trois.
    """

    CALENDRIER = "2026-08-25T09:00"
    MEMES = ("2026-08-25T09:00", "2026-08-25T09:00:00", "2026-08-25 09:00",
             "2026-08-25T09:00:00+02:00", "25/08/2026 09:00",
             "25/08/2026 à 09h00", "mardi 25 août 2026 à 9 heures",
             "le mardi 25 août 2026 à 9 heures", "25 aout 2026 9h")

    def test_toutes_les_ecritures_du_meme_instant_donnent_la_meme_ligne(self):
        for forme in self.MEMES:
            with self.subTest(forme=forme):
                self.assertEqual(themes.lire_date(forme), self.CALENDRIER)

    def test_ce_que_le_produit_dit_le_produit_sait_le_relire(self):
        """⚠ L'ALLER-RETOUR, ET C'EST LA RÈGLE ENTIÈRE. Le jour où la façon de
        DIRE une date changera, le lecteur devra suivre — sinon l'agent
        répétera ce qu'on lui a dit et RingBack ne le comprendra pas.

        Mesuré le 24/08 : c'est arrivé immédiatement. `lire_date` rendait None
        sur toute date sortie de `date_parlee`, parce qu'elle ne savait pas
        retirer l'article « le » que le produit écrit lui-même.
        """
        quand = datetime.datetime(2026, 1, 1, 0, 0)
        essayees = 0
        while quand < datetime.datetime(2027, 1, 1):
            iso = quand.isoformat(timespec="minutes")
            for forme in (themes.date_parlee(iso), f"le {themes.date_parlee(iso)}",
                          f"du {themes.date_parlee(iso)}"):
                essayees += 1
                self.assertEqual(themes.lire_date(forme), iso, forme)
            quand += datetime.timedelta(minutes=7 * 61)
        self.assertGreater(essayees, 3000)

    def test_on_lit_on_ne_devine_pas(self):
        """⚠ UNE FORME NON RECONNUE RESTE ILLISIBLE. Inventer une date poserait
        un rendez-vous que personne n'a pris — le seul dénouement qu'on ne
        puisse pas rattraper."""
        for brut in ("", "la semaine prochaine", "le mardi matin", "plutôt jeudi",
                     "2026-13-45T99:99", "demain"):
            with self.subTest(brut=brut):
                self.assertIsNone(themes.lire_date(brut))

    # ------------------------------------- À LA PORTE, PAS CHEZ LES APPELANTS
    def test_le_resultat_classique_arrive_deja_au_format_du_calendrier(self):
        for forme in self.MEMES:
            with self.subTest(forme=forme):
                lu = calle_client.valider_resultat(
                    {"appointment_status": "rescheduled", "new_datetime": forme,
                     "notes": "d'accord"})
                self.assertEqual(lu["new_datetime"], self.CALENDRIER)

    def test_le_resultat_de_cascade_aussi(self):
        for issue in ("moved", "accepted"):
            for forme in self.MEMES:
                with self.subTest(issue=issue, forme=forme):
                    lu = calle_client.valider_resultat_cascade(
                        {"outcome": issue, "new_datetime": forme,
                         "notes": "d'accord"})
                    self.assertEqual(lu["new_datetime"], self.CALENDRIER)

    def test_une_reponse_illisible_reste_illisible(self):
        with self.assertRaises(calle_client.ResultatInvalide) as refus:
            calle_client.valider_resultat(
                {"appointment_status": "rescheduled",
                 "new_datetime": "la semaine prochaine", "notes": "x"})
        # ⚠ ET LE MESSAGE MONTRE CE QU'IL N'A PAS SU LIRE : sans cela, on
        # relit « new_datetime illisible » sans jamais savoir sur quoi.
        self.assertIn("la semaine prochaine", refus.exception.constat)

    def test_la_place_retenue_reconnait_le_meme_instant(self):
        """⚠ LE DÉNOUEMENT QUI ÉTAIT MESURÉ : la personne dit oui, l'agent rend
        la même place écrite autrement, et `place_retenue` ne la reconnaissait
        pas — elle repartait « à rappeler par un humain » après un appel
        parfaitement réussi."""
        annoncees = [self.CALENDRIER, "2026-08-27T09:00"]
        for forme in self.MEMES:
            with self.subTest(forme=forme):
                resultat = calle_client.valider_resultat_cascade(
                    {"outcome": "accepted", "new_datetime": forme, "notes": "ok"})
                self.assertEqual(
                    assistant.place_retenue(resultat, annoncees, None),
                    self.CALENDRIER)

    def test_une_place_jamais_annoncee_reste_refusee(self):
        """LA CONTRE-ÉPREUVE : être plus tolérant sur la FORME ne doit rien
        céder sur le FOND. Une date qu'on n'a pas proposée n'est pas retenue."""
        resultat = calle_client.valider_resultat_cascade(
            {"outcome": "accepted",
             "new_datetime": "mardi 1 septembre 2026 à 9 heures", "notes": "ok"})
        self.assertIsNone(assistant.place_retenue(
            resultat, [self.CALENDRIER], None))


class TestLeRecalculDeLInstantDeLAppel(unittest.TestCase):
    """⚠ TROUVÉ EN MESURANT LE 24/08, avant ses essais réels — il n'avait pas
    signalé celui-là.

    `creneaux_adaptes_au_contact` écrivait la MÊME valeur dans les deux
    informations calculées : le champ « Créneau proposé en premier » — celui
    que la conduite dictée à l'agent appelle « une seule date, pas la liste »
    — recevait six dates. C'est le défaut corrigé le 17/08 au rafraîchissement
    du brouillon et à la reprise en cascade ; le troisième maillon, celui de
    l'instant de l'appel, l'avait gardé.

    ⚠ ET UN SECOND, PIRE : deux `str.replace` d'affilée sur des valeurs qui se
    contiennent l'une l'autre. « le mardi 25 août 2026 à 9 heures » est un
    PRÉFIXE de « … à 9 heures 15 » : la ligne dictée à l'agent répétait quatre
    fois la même liste et finissait par « … à 10 heures 15 15 ».
    """

    STOCK = ("le mardi 25 août 2026 à 9 heures, "
             "le mardi 25 août 2026 à 9 heures 15, "
             "le mercredi 26 août 2026 à 14 heures")
    PROCHE = "le mardi 25 août 2026 à 9 heures"
    NEUF = ("le jeudi 27 août 2026 à 9 heures, "
            "le jeudi 27 août 2026 à 9 heures 15")

    def setUp(self):
        self.base = db.Base(":memory:")
        self.contact = {"id": 1, "rendezvous_id": None, "champs": "{}"}
        # ⚠ « LE PLUS PROCHE » EN PREMIER DANS LE DICTIONNAIRE, et ce n'est pas
        # un détail : c'est son ordre dans une vraie campagne, et c'est CET
        # ordre qui déclenchait le dégât. La date seule était remplacée avant
        # le stock, et comme elle est un PRÉFIXE des lignes du stock, elle y
        # mordait au passage — après quoi le stock ne se reconnaissait plus et
        # gardait ses places périmées.
        self.configuration = {"infos_auto": {
            "creneau_le_plus_proche": self.PROCHE,
            "creneaux_remplacement": self.STOCK}}

    def _adapter(self, mission):
        return assistant.creneaux_adaptes_au_contact(
            self.base, None, self.configuration, self.contact, mission,
            adaptee=self.NEUF)

    def test_le_creneau_propose_en_premier_reste_UNE_date(self):
        mission = (f"Créneau proposé en premier : {self.PROCHE}.\n"
                   f"Créneaux disponibles : {self.STOCK}.")
        adaptee = self._adapter(mission)
        premiere = adaptee.split("premier : ")[1].split(".")[0]
        self.assertEqual(premiere, "le jeudi 27 août 2026 à 9 heures")
        # Et le stock, lui, reste une liste.
        self.assertIn(f"disponibles : {self.NEUF}.", adaptee)

    def test_le_stock_est_remplace_EN_ENTIER(self):
        """⚠ CE QUE MESURE VRAIMENT LA PASSE UNIQUE, et ce que l'essai de la
        première version ne mesurait pas.

        Deux `str.replace` d'affilée : la date seule est remplacée d'abord et
        mord sur les lignes du stock (elle en est le préfixe) ; après quoi le
        stock ne correspond plus à ce qu'on cherchait, il n'est PAS remplacé,
        et il garde ses places d'hier. Une place prise entre-temps repart donc
        au téléphone — c'est le défaut que ce recalcul existe pour éviter.
        """
        mission = (f"Créneau proposé en premier : {self.PROCHE}.\n"
                   f"Créneaux disponibles : {self.STOCK}.")
        adaptee = self._adapter(mission)
        stock_dit = adaptee.split("disponibles : ")[1].rstrip(".")
        self.assertEqual(stock_dit, self.NEUF)
        # ⚠ ET PLUS AUCUNE PLACE D'HIER : le mercredi 26 n'était que dans
        # l'ancien stock. Le voir survivre, c'est le voir proposé au téléphone.
        self.assertNotIn("mercredi 26", adaptee)
        # Aucune date dite deux fois dans la liste, aucun nombre orphelin.
        dites = MOTIF_DATE_PARLEE.findall(stock_dit)
        self.assertEqual(len(dites), len(set(dites)),
                         f"une date est dite deux fois : {dites}")
        self.assertNotIn("heures 15 15", adaptee)
        self.assertNotIn("heures 30 30", adaptee)

    def test_une_liste_retapee_a_la_main_n_est_jamais_touchee(self):
        """La règle d'avant, qui doit tenir : ce que l'opérateur a écrit lui
        appartient."""
        self.configuration["infos_auto"] = {}
        self.assertEqual(self._adapter("Plutôt mardi matin."),
                         "Plutôt mardi matin.")

    def test_sans_place_libre_on_ne_remplace_rien(self):
        """⚠ JAMAIS DE TEXTE INVENTÉ. Un recalcul qui ne rend rien laisse le
        message intact — c'est `_plus_rien_a_annoncer` qui refuse ensuite de
        composer, et c'est à lui de le faire."""
        mission = f"Créneaux disponibles : {self.STOCK}."
        self.assertEqual(
            assistant.creneaux_adaptes_au_contact(
                self.base, None, self.configuration, self.contact, mission,
                adaptee=""),
            mission)

    def test_un_code_un_reglage_sur_TOUTES_les_natures(self):
        """⚠ LE GARDE-FOU DU DÉTOUR. `reglage_du_code` retrouve le réglage sans
        connaître la nature ; cela n'est vrai que tant qu'un même code garde le
        même réglage partout. Le jour où deux natures en donneraient deux, cet
        essai le dira — avant que le détour ne devienne un mensonge."""
        vus = {}
        for nature, definition in assistant.NATURES.items():
            for info in definition.get("infos", ()):
                if not info.get("reglage"):
                    continue
                vus.setdefault(info["code"], set()).add(info["reglage"])
        self.assertTrue(vus)
        for code, reglages in vus.items():
            with self.subTest(code=code):
                self.assertEqual(len(reglages), 1, f"{code} : {reglages}")
                self.assertEqual(assistant.reglage_du_code(code),
                                 next(iter(reglages)))
        self.assertIsNone(assistant.reglage_du_code("un_code_qui_n_existe_pas"))


class TestTroisReglagesDEcranDu21(_TestAvecServeurWeb):
    """⚠ SES TROIS DEMANDES DU 21/08/2026 au soir, mesurées à LEUR POINT DE
    PASSAGE — et pas « le mot est quelque part dans la page ».

    Deux d'entre elles vivent dans du CSS et du JavaScript, que ces essais ne
    savent pas exécuter : ils éprouvent alors la règle à l'endroit où elle est
    écrite. Le rendu, lui, a été mesuré au navigateur sur une copie de sa base
    (texte à 8,4 px du haut et 8,6 px du bas de la pastille ; explication
    absente du texte visible et présente après ouverture ; « /reglages »
    arrivant sur la section `identite`, partie « 📞 Appels » dépliée).
    """

    # ------------------------------------------------------------------ (1)
    def test_le_texte_des_boutons_de_famille_est_centre_verticalement(self):
        """⚠ « CENTRER LE TEXTE VERTICALEMENT DANS LE BOUTON ». `baseline`
        alignait le libellé sur sa ligne d'écriture : dans une pastille plus
        haute que le texte, le mot se posait vers le bas."""
        _, page = self._obtenir("/relances")
        regle = page[page.index(".menu-familles a {"):]
        regle = regle[:regle.index("}")]
        self.assertIn("align-items: center", regle)
        self.assertNotIn("baseline", regle)

    # ------------------------------------------------------------------ (2)
    def _panneau(self, page, code):
        debut = page.index(f'id="panneau-{code}"')
        return page[debut:page.index("</section>", debut)]

    def test_l_explication_est_derriere_un_point_d_interrogation(self):
        """⚠ « UN BOUTON "?" À CÔTÉ DES TITRES […] et par défaut il est masqué ».
        L'explication s'étalait sous chaque titre : deux paragraphes à relire à
        chaque visite, au-dessus de la liste qu'il vient consulter.

        ⚠ ON MESURE L'EMBOÎTEMENT, PAS LA PRÉSENCE DU TEXTE. Le texte reste
        dans la page — c'est un `<details>` replié, pas un texte supprimé —
        donc le chercher « quelque part » rendrait cet essai vert avant comme
        après. C'est exactement ce qui s'est passé : l'essai d'origine cherchait
        `<p>` et est resté vert au travers du changement.
        """
        panneau = self._panneau(self._obtenir("/relances")[1], "humains")
        entete = panneau[panneau.index('class="entete-panneau"'):]
        entete = entete[:entete.index("</details>")]
        # Le titre et le « ? » partagent le même en-tête, dans cet ordre.
        self.assertLess(entete.index("<h2>"),
                        entete.index('<details class="aide"'))
        # ⚠ REPLIÉ À L'ARRIVÉE : pas d'attribut « open ».
        self.assertNotIn('<details class="aide" open', panneau)
        # ⚠ ET L'EXPLICATION EST DEDANS, pas à côté.
        aide = panneau[panneau.index('<details class="aide"'):]
        aide = aide[:aide.index("</details>")]
        self.assertIn("Deux façons d'arriver ici", aide)

    def test_chaque_famille_a_son_point_d_interrogation(self):
        """La règle, pas le cas : les QUATRE familles, pas seulement celle
        d'arrivée. Trois d'entre elles sont `hidden` à l'arrivée — elles sont
        rendues quand même, et c'est là qu'un oubli passerait inaperçu."""
        _, page = self._obtenir("/relances")
        for code, _, _ in serveur.VUES_RELANCES:
            with self.subTest(famille=code):
                panneau = self._panneau(page, code)
                self.assertIn('class="entete-panneau"', panneau)
                self.assertIn('<details class="aide"', panneau)

    def test_un_titre_qui_porte_du_html_ne_le_met_pas_dans_l_infobulle(self):
        """⚠ LE « ? » SEUL NE DIT RIEN à qui ne le survole pas, ni à un lecteur
        d'écran : `_aide` répète donc le titre. Mais un titre de panneau peut
        porter des balises — et le recopier tel quel écrirait des chevrons dans
        l'infobulle. On le débarrasse de ses balises AVANT.

        ⚠ ÉPROUVÉ EN APPELANT LA FONCTION, pas en lisant la page : aucun des
        quatre titres d'aujourd'hui ne porte de balise, donc la page ne
        montrerait rien — l'essai serait vert sans rien prouver.
        """
        panneau = serveur._panneau_relance(
            "essai", "🙋 Rappels <span class=\"pastille\">7</span>",
            "<p>Une explication.</p>", "<table></table>", "essai")
        infobulle = panneau.split('<summary title="')[1].split('"')[0]
        self.assertEqual(infobulle, "🙋 Rappels 7")
        # Le titre AFFICHÉ, lui, garde ses balises : la pastille reste une
        # pastille.
        self.assertIn(
            '<h2>🙋 Rappels <span class="pastille">7</span></h2>',
            panneau)

    # ------------------------------------------------------------------ (3)
    def test_les_reglages_s_ouvrent_sur_appels_identite(self):
        """⚠ SA DEMANDE, QUI REMPLACE CELLE DU 02/08. Il avait demandé l'inverse
        — tout replié, avec une invite à choisir — et l'écran d'accueil des
        réglages n'affichait donc rien."""
        _, page = self._obtenir("/reglages")
        self.assertIn("if(!depuisAncre()&&!ouvrir('identite'))", page)

    def test_la_rubrique_visee_existe_vraiment(self):
        """⚠ LE GARDE-FOU, ET IL NE PROUVE PAS LE CORRECTIF : il protège la
        SUITE. `ouvrir('identite')` désigne un code écrit en dur ; le jour où
        cette sous-partie sera renommée ou déplacée, l'appel rendra `false` et
        l'écran retombera sur l'invite — sans erreur, sans bruit, et personne
        ne verrait passer la régression. Cet essai la voit."""
        _, page = self._obtenir("/reglages")
        self.assertIn('data-section="identite"', page)
        self.assertIn("Identité de l'établissement", page)

    def test_une_ancre_garde_la_main_sur_le_defaut(self):
        """LA CONTRE-ÉPREUVE DU DÉFAUT : « /reglages#jeu-essai » doit toujours
        ouvrir le jeu d'essai. Le défaut ne s'applique qu'À DÉFAUT — c'est
        l'ordre du « && » qui le garantit, et le court-circuit ne marche que
        parce que `ouvrir` rend un booléen."""
        _, page = self._obtenir("/reglages")
        condition = page[page.index("if(!depuisAncre()&&"):]
        condition = condition[:condition.index("{")]
        self.assertLess(condition.index("depuisAncre()"),
                        condition.index("ouvrir('identite')"))
        self.assertIn("function ouvrir(code){", page)
        self.assertIn("if(!partie){return false}", page)
        self.assertIn('data-section="jeu-essai"', page)


class TestAccueilLesPasseesSontRepliees(_CampagneAssistant):
    """⚠ SA DEMANDE DU 21/08/2026 : « sur la page d'accueil il faut afficher
    simplement un texte (N campagnes déjà envoyées) et lorsqu'on clique dessus on
    affiche la liste, donc c'est caché par défaut ».

    Mesuré dans sa base : **113 campagnes passées**, et rien d'autre à l'écran. Ce
    qu'il vient de préparer ou de lancer — ce sur quoi il travaille — était noyé
    sous cent treize lignes d'archives.
    """

    def _campagne_terminee(self, nom="Une passée", avec_appel=True):
        """Une campagne passée, qui a appelé ou non."""
        base = self.application.base
        campagne = base.creer_campagne(nom, "deplacement", mission="Bonjour.",
                                       nature="deplacement")
        contact = base.ajouter_contact_campagne(campagne, 1, "M. Quelqu'un",
                                                "+33 6 00 00 00 51")
        if avec_appel:
            base.ajouter_appel_campagne(campagne, contact, 0, issue="no_answer")
        base.changer_statut_campagne(campagne, "terminée")
        return campagne

    def _accueil(self):
        _, page = self._obtenir("/")
        return page

    def _depliant(self, page):
        debut = page.index('class="carte campagnes-passees"')
        return page[debut:page.index("</details>", debut)]

    # ------------------------------------------------------- LA DEMANDE
    def _assez_pour_replier(self):
        """Plus de campagnes que l'aperçu n'en montre — sinon il n'y a rien à
        replier, et le produit n'affiche aucun dépliant (c'est voulu)."""
        combien = serveur.Gestionnaire.APERCU_PASSEES + 1
        for rang in range(combien):
            self._campagne_terminee(nom=f"Archive {rang:02d}")
        return combien

    def test_les_passees_sont_cachees_par_defaut(self):
        """⚠ « CACHÉ PAR DÉFAUT », mot pour mot : le dépliant ne porte pas
        `open`. La liste EST dans la page — un clic suffit, sans aller-retour
        au serveur — mais elle ne s'étale pas d'entrée."""
        self._assez_pour_replier()
        page = self._accueil()
        self.assertIn('<details class="carte campagnes-passees">', page)
        self.assertNotIn("campagnes-passees\" open", page)
        # La liste est bien DEDANS.
        self.assertIn("Archive 00", self._depliant(page))

    def test_le_texte_dit_le_nombre(self):
        combien = self._assez_pour_replier()
        page = self._accueil()
        self.assertIn(f"{combien} campagne(s) déjà envoyée(s)",
                      self._depliant(page))

    def test_effacer_la_liste_reste_accessible(self):
        """Le geste ne disparaît pas avec la liste : il est dans le dépliant,
        au-dessus du tableau."""
        self._assez_pour_replier()
        depliant = self._depliant(self._accueil())
        self.assertIn("Effacer la liste", depliant)
        self.assertIn("groupe=terminees", depliant)

    # ---------------------------------------------- LE MOT DOIT RESTER VRAI
    def test_une_campagne_qui_n_a_JAMAIS_appele_n_est_pas_envoyee(self):
        """⚠ LE PIÈGE, ET IL ÉTAIT DANS SA BASE. « Terminée » ne veut pas dire
        « envoyée » : mesuré le 21/08, DOUZE campagnes terminées n'avaient jamais
        passé un appel — dont deux de 320 contacts — et sept closes non plus.
        Les compter avec les autres aurait gonflé de dix-neuf un chiffre qu'il
        lit comme un travail fait."""
        self._assez_pour_replier()          # six qui ont appelé
        self._campagne_terminee(nom="Elle a appelé", avec_appel=True)
        self._campagne_terminee(nom="Elle na rien fait", avec_appel=False)
        depliant = self._depliant(self._accueil())
        self.assertIn("7 campagne(s) déjà envoyée(s)", depliant)
        self.assertIn("1 close(s) sans avoir appelé", depliant)
        # Les DEUX restent dans la liste : on n'en cache aucune.
        self.assertIn("Elle a appelé", depliant)
        self.assertIn("Elle na rien fait", depliant)

    def test_le_critere_est_la_trace_d_appel_pas_le_statut(self):
        """La règle à son point de passage : le seul fait qui ne ment pas est
        la trace d'appel elle-même."""
        base = self.application.base
        avec = self._campagne_terminee(nom="Avec", avec_appel=True)
        sans = self._campagne_terminee(nom="Sans", avec_appel=False)
        ayant = base.campagnes_ayant_appele()
        self.assertIn(avec, ayant)
        self.assertNotIn(sans, ayant)

    # ------------------------------------------- L'APERÇU ET LA LARGEUR
    def test_les_cinq_dernieres_se_lisent_sans_deplier(self):
        """⚠ SA DEMANDE DU 21/08 : « afficher au-dessus du bouton les 5
        dernières campagnes directement en clair ».

        Tout replier avait un défaut : la page ne montrait plus RIEN de ce qui
        vient de se passer. Ce qu'il veut voir en arrivant, c'est le travail
        récent ; ce qu'il veut ranger, c'est l'archive.
        """
        for rang in range(8):
            self._campagne_terminee(nom=f"Passée {rang:02d}")
        page = self._accueil()
        hors_depliant = page.replace(self._depliant(page), "")
        # ⚠ LES CINQ PLUS RÉCENTES, et la liste est la plus récente d'abord.
        for rang in range(3, 8):
            self.assertIn(f"Passée {rang:02d}", hors_depliant)
        for rang in range(0, 3):
            self.assertNotIn(f"Passée {rang:02d}", hors_depliant)
        self.assertIn("Les 5 plus récentes", hors_depliant)
        # Et le dépliant porte bien TOUTES les campagnes, les cinq comprises :
        # « voir la liste » ne doit pas ouvrir une liste amputée.
        depliant = self._depliant(page)
        for rang in range(8):
            self.assertIn(f"Passée {rang:02d}", depliant)

    def test_sans_archive_a_ranger_il_n_y_a_pas_de_bouton(self):
        """⚠ UN BOUTON QUI OUVRE CE QU'ON VOIT DÉJÀ EST UN FAUX GESTE. Avec
        cinq campagnes ou moins, l'aperçu EST la liste."""
        for rang in range(3):
            self._campagne_terminee(nom=f"Passée {rang}")
        page = self._accueil()
        self.assertNotIn('<details class="carte campagnes-passees">', page)
        self.assertNotIn("Les 5 plus récentes", page)
        self.assertIn("Passée 0", page)
        self.assertIn("Effacer la liste", page)

    def test_la_zone_prend_toute_la_largeur(self):
        """⚠ « IL FAUT QUE LA ZONE PRENNE TOUTE LA LARGEUR » (sa demande). Le
        « max-width: 28rem » de `.carte` est fait pour les FORMULAIRES — un
        champ large de soixante-quatre rem se lit mal. Une LISTE, elle, a
        besoin de toute la place."""
        for rang in range(8):
            self._campagne_terminee(nom=f"Passée {rang}")
        page = self._accueil()
        self.assertIn(".campagnes-passees { max-width: none; }", page)

    # ------------------------------------------------------ LA CONTRE-ÉPREUVE
    def test_ce_sur_quoi_il_travaille_reste_deplie(self):
        """⚠ LES DEUX AUTRES GROUPES NE SE REPLIENT PAS. « En cours » et
        « prêtes » sont son travail du moment : les replier reviendrait à les
        cacher, c'est-à-dire à refaire le défaut à l'envers."""
        base = self.application.base
        self._assez_pour_replier()
        prete = base.creer_campagne("Une prête", "deplacement",
                                    mission="Bonjour.", nature="deplacement",
                                    statut="prête")
        base.ajouter_contact_campagne(prete, 1, "M. Prêt",
                                      "+33 6 00 00 00 52")
        page = self._accueil()
        # Elle est visible SANS déplier quoi que ce soit.
        hors_depliant = page.replace(self._depliant(page), "")
        self.assertIn("Une prête", hors_depliant)
        self.assertIn("Prêtes", hors_depliant)


class TestPlusDeBandeauJeuDEssai(_TestAvecServeurWeb):
    """⚠ SA DEMANDE DU 21/08/2026 : « supprime le message en violet sur toutes
    les pages où on le voit ».

    Il s'affichait en tête de CHAQUE écran et prenait deux lignes pour redire une
    chose qu'il sait déjà : c'est lui qui a chargé le jeu d'essai.

    ⚠ L'INFORMATION N'EST PAS PERDUE, et c'est ce qui rend le retrait tenable :
    chaque client d'essai porte toujours son 🧪 partout où il apparaît, et
    ⚙ Réglages garde le bouton pour les retirer en bloc.
    """

    def test_le_bandeau_ne_parait_sur_aucune_page(self):
        base = self.application.base
        jeu_essai.charger(base)
        self.assertTrue(jeu_essai.est_charge(base))
        for chemin in ("/", "/relances", "/suivi", "/clients", "/reglages"):
            with self.subTest(page=chemin):
                _, page = self._obtenir(chemin)
                self.assertNotIn("JEU D'ESSAI CHARGÉ", page)

    def test_le_marquage_du_contact_reste(self):
        """LA CONTRE-ÉPREUVE : ce qui disparaît est la RÉPÉTITION, pas le fait.
        Un client d'essai reste reconnaissable là où il compte — sur sa fiche."""
        base = self.application.base
        jeu_essai.charger(base)
        _, page = self._obtenir("/clients")
        self.assertIn("🧪", page)
        # Et ⚙ Réglages garde le moyen de les retirer.
        _, reglages = self._obtenir("/reglages")
        self.assertIn("jeu-essai", reglages)


class TestOnRelitLeRendezVousAvantDeComposer(_CampagneAssistant):
    """⚠ SA DEMANDE DU 21/08/2026, et le défaut mesuré qui l'a amenée.

    Éprouvé avant correction : j'annule un rendez-vous entre la création de la
    campagne et l'appel — le téléphone sonne quand même, et le « oui » REMET le
    rendez-vous au planning. Mesuré dans sa base : **131 contacts** pouvaient
    encore sonner pour un rendez-vous supprimé ou annulé, et 35 rendez-vous
    étaient visés par deux à quatre campagnes à la fois.

    ⚠ C'EST L'ÉCART QUI DÉCIDE, PAS L'ÉTAT COURANT — et c'est le piège de cette
    règle. Une campagne de rappel des MANQUÉS prend des rendez-vous « manqué »,
    une reprise des ANNULÉS en prend des « annulé » : refuser sur le seul statut
    courant les aurait toutes cassées. Ce qui n'est pas normal, c'est qu'un
    rendez-vous ait QUITTÉ l'état où la campagne l'avait trouvé.
    """

    def _campagne_sur_un_rdv(self, nom="M. Un Rendez-vous", statut="prévu",
                             nature="deplacement"):
        """Une campagne d'une personne, liée à SON rendez-vous."""
        base = self.application.base
        horaires.definir_semaine(self.application.preferences,
                                 {j: [(8 * 60, 19 * 60)] for j in range(7)})
        numero = "+33 6 00 00 00 51"
        client = base.ajouter_client(nom, numero)
        quand = (datetime.datetime.now() + datetime.timedelta(days=3)).replace(
            hour=10, minute=0, second=0, microsecond=0).isoformat(
                timespec="minutes")
        rdv = base.ajouter_rendezvous(client, quand, "Séance", statut=statut)
        campagne_id = self._campagne(
            nature, [f"{nom};{numero};{quand};Séance"],
            politique="tous", relance_max="0")
        return campagne_id, rdv, quand

    def _a_sonne(self, campagne_id):
        base = self.application.base
        contact = base.contacts_de_campagne(campagne_id)[0]
        return bool(base.appels_du_contact_campagne(contact["id"])), contact

    # ------------------------------------------------------------- LA RÈGLE
    def test_un_rendezvous_annule_entre_temps_n_est_pas_compose(self):
        """LE CAS MESURÉ : la campagne parlerait d'un rendez-vous qui n'existe
        plus, et le « oui » le remettrait au planning."""
        base = self.application.base
        campagne_id, rdv, _ = self._campagne_sur_un_rdv()
        base.mettre_a_jour_rendezvous(rdv, statut="annulé")
        self._derouler(campagne_id)
        sonne, contact = self._a_sonne(campagne_id)
        self.assertFalse(sonne, "le téléphone a sonné")
        self.assertEqual(contact["etat"], "exclu")
        self.assertIn("a changé", contact["detail"])
        self.assertIn("annulé", contact["detail"])
        # ET LE RENDEZ-VOUS N'EST PAS RESSUSCITÉ.
        self.assertEqual(base.obtenir_rendezvous(rdv)["statut"], "annulé")

    def test_un_rendezvous_supprime_entre_temps_non_plus(self):
        """L'autre disparition : la ligne n'existe plus du tout.

        ⚠ ET LE TEXTE SUIT CE QU'ON SAIT. Ici la liste est COLLÉE, donc le lien
        se fait par la DATE : un rendez-vous introuvable a pu être déplacé,
        annulé ou supprimé, et les trois se ressemblent. Quand le contact est
        lié par IDENTIFIANT — le cas du planning et de la base —, l'absence est
        une suppression sans ambiguïté, et le texte le dit : c'est la seconde
        moitié de cet essai.
        """
        base = self.application.base
        campagne_id, rdv, _ = self._campagne_sur_un_rdv()
        base.conn.execute("DELETE FROM rendezvous WHERE id = ?", (rdv,))
        base.conn.commit()
        self._derouler(campagne_id)
        sonne, contact = self._a_sonne(campagne_id)
        self.assertFalse(sonne)
        self.assertIn("n'est plus à la date", contact["detail"])
        # LIÉ PAR IDENTIFIANT : le texte devient précis.
        base.conn.execute("UPDATE contacts_campagne SET rendezvous_id = ? "
                          "WHERE id = ?", (rdv, contact["id"]))
        base.conn.commit()
        self.assertIn("supprimé de l'agenda",
                      base.rendezvous_change_depuis_la_campagne(contact["id"]))

    def test_un_rendezvous_deplace_par_une_autre_campagne_non_plus(self):
        """⚠ SON « ALLER-RETOUR » DU 21/08, mesuré sur sa base : le même
        rendez-vous visé par trois campagnes, SIX appels, et deux « oui » à deux
        dates différentes à une seconde d'intervalle. La seconde campagne
        parlerait d'une date que la première vient de changer."""
        base = self.application.base
        campagne_id, rdv, quand = self._campagne_sur_un_rdv()
        ailleurs = (datetime.datetime.fromisoformat(quand)
                    + datetime.timedelta(days=1)).isoformat(timespec="minutes")
        base.mettre_a_jour_rendezvous(rdv, horaire=ailleurs)
        self._derouler(campagne_id)
        sonne, contact = self._a_sonne(campagne_id)
        self.assertFalse(sonne)
        # ⚠ La liste est COLLÉE : le lien se fait par la date, donc « déplacé »
        # et « supprimé » y sont indiscernables. Le texte le dit tel quel.
        self.assertIn("n'est plus à la date que la campagne avait retenue",
                      contact["detail"])

    # -------------------------------------------------------- LES BORNES
    def test_un_rendezvous_INCHANGE_est_compose_normalement(self):
        """LA CONTRE-ÉPREUVE QUI COMPTE LE PLUS : la règle ne doit empêcher
        aucun appel légitime. Rien n'a bougé → on appelle, comme avant."""
        base = self.application.base
        campagne_id, rdv, _ = self._campagne_sur_un_rdv()
        self._derouler(campagne_id)
        sonne, contact = self._a_sonne(campagne_id)
        self.assertTrue(sonne, "l'appel légitime n'est pas parti")
        self.assertEqual(contact["etat"], "accepté")

    def test_une_campagne_qui_VISE_les_manques_appelle_quand_meme(self):
        """⚠ LE PIÈGE DE CETTE RÈGLE, et la moitié qui compte le plus. Un rappel
        des rendez-vous MANQUÉS prend des rendez-vous « manqué » : c'est son
        objet même. Refuser sur le statut courant l'aurait cassé net."""
        base = self.application.base
        campagne_id, rdv, _ = self._campagne_sur_un_rdv(
            nom="M. A Manqué", statut="manqué", nature="rappel_rdv")
        self.assertEqual(base.obtenir_rendezvous(rdv)["statut"], "manqué")
        self._derouler(campagne_id)
        sonne, _ = self._a_sonne(campagne_id)
        self.assertTrue(sonne, "le rappel des manqués ne part plus")

    def test_un_rendezvous_qui_se_CONFIRME_entre_temps_est_compose(self):
        """L'autre borne : passer de « prévu » à « confirmé », c'est un changement
        — mais il occupe toujours sa place. Rien ne justifie de ne pas
        appeler."""
        base = self.application.base
        campagne_id, rdv, _ = self._campagne_sur_un_rdv()
        base.mettre_a_jour_rendezvous(rdv, statut="confirmé")
        self._derouler(campagne_id)
        sonne, _ = self._a_sonne(campagne_id)
        self.assertTrue(sonne)

    def test_une_ligne_collee_sans_rendezvous_connu_est_composee(self):
        """⚠ ON NE DEVINE PAS. Une date tapée à la main peut désigner un
        rendez-vous que RingBack ne connaît pas : rien n'a été capturé, donc
        rien n'a changé. L'écarter reviendrait à la perdre en silence."""
        base = self.application.base
        horaires.definir_semaine(self.application.preferences,
                                 {j: [(8 * 60, 19 * 60)] for j in range(7)})
        quand = (datetime.datetime.now() + datetime.timedelta(days=3)).replace(
            hour=10, minute=0, second=0, microsecond=0).isoformat(
                timespec="minutes")
        campagne_id = self._campagne(
            "deplacement",
            [f"M. Jamais En Base;+33 6 00 00 00 51;{quand};Séance"],
            politique="tous", relance_max="0")
        contact = base.contacts_de_campagne(campagne_id)[0]
        self.assertNotIn("rdv_statut", contact["champs"] or "")
        self._derouler(campagne_id)
        sonne, _ = self._a_sonne(campagne_id)
        self.assertTrue(sonne)

    def test_les_campagnes_d_avant_la_regle_ne_sont_pas_bloquees(self):
        """⚠ CE QUI EST DÉJÀ EN BASE N'A PAS D'ÉTAT DE CAPTURE. Sans lui on ne
        devine pas, et surtout on ne bloque pas : ses 116 campagnes existantes
        doivent continuer de fonctionner exactement comme avant."""
        base = self.application.base
        campagne_id, rdv, _ = self._campagne_sur_un_rdv()
        contact = base.contacts_de_campagne(campagne_id)[0]
        # On refabrique l'état d'AVANT : des champs sans « rdv_statut ».
        champs = json.loads(contact["champs"])
        champs.pop("rdv_statut")
        base.conn.execute("UPDATE contacts_campagne SET champs = ? WHERE id = ?",
                          (json.dumps(champs, ensure_ascii=False), contact["id"]))
        base.conn.commit()
        base.mettre_a_jour_rendezvous(rdv, statut="annulé")
        self.assertEqual(
            base.rendezvous_change_depuis_la_campagne(contact["id"]), "")
        self._derouler(campagne_id)
        sonne, _ = self._a_sonne(campagne_id)
        self.assertTrue(sonne)


class TestUnDeplacementNonFaitFinitAnnule(_CampagneAssistant):
    """⚠ SA RÈGLE, DU 20/08/2026, mot pour mot :

    « Lorsqu'on demande de déplacer un rendez-vous et que, pour une raison ou
    une autre, nous n'avons pas pu le déplacer : celui-ci est alors annulé.
    C'est après les recontacts, ou alors le client qui doit rappeler, pour fixer
    un rendez-vous. »

    Une campagne de déplacement dit « ce créneau doit être vidé ». Il ne l'était
    qu'à moitié : les rendez-vous qu'on n'avait pas su déplacer restaient au
    planning, et il croyait sa journée vide. Mesuré sur sa base le 20/08 : il
    vide un jeudi après-midi, **2 rendez-vous sur 6** restent en place.

    ⚠ SES DEUX CHOIX DU MÊME JOUR, qui bornent la règle :
    · QUAND : quand RingBack a FINI D'ESSAYER, pas au premier appel raté ;
    · QUI : ceux qu'on n'a jamais pu appeler aussi (🚫, sans numéro).
    """

    HEURE = 9

    def _rdv(self, nom, fin_de_numero, jours=3, heure=None,
             prefixe="00 00 00"):
        """Un client, son numéro à issue forcée, et son rendez-vous.

        ⚠ `prefixe` sert quand DEUX personnes doivent jouer la même issue : la
        grille refuse deux fois le même numéro (deux appels chez la même
        personne), et c'est une bonne règle — on change donc le début, pas la
        terminaison qui décide de l'issue.
        """
        base = self.application.base
        numero = self._numero(fin_de_numero, prefixe)
        client = base.ajouter_client(nom, numero)
        quand = (datetime.datetime.now() + datetime.timedelta(days=jours)
                 ).replace(hour=heure or self.HEURE, minute=0, second=0,
                           microsecond=0).isoformat(timespec="minutes")
        rdv = base.ajouter_rendezvous(client, quand, "Séance", statut="prévu")
        return client, rdv, quand

    @staticmethod
    def _numero(terminaison, prefixe="00 00 00"):
        """⚠ CONSTRUIT, JAMAIS ÉCRIT EN DUR. `preparer_publication.py` refuse
        tout numéro en clair hors de la série de fiction documentée, et il a
        raison : un numéro recopié dans un essai finit par être un vrai."""
        return f"+33 6 {prefixe} {terminaison}"

    def _campagne_de_deplacement(self, gens, **options):
        lignes = [f"{nom};{self._numero(*numero)};{quand};Séance"
                  for nom, numero, quand in gens]
        reglages = {"politique": "tous", "relance_max": "0"}
        reglages.update(options)
        return self._campagne("deplacement", lignes, **reglages)

    def _statuts(self, rdvs):
        base = self.application.base
        return {nom: base.obtenir_rendezvous(rdv)["statut"]
                for nom, rdv in rdvs.items()}

    # ------------------------------------------------------- ① LA RÈGLE
    def test_le_rendezvous_qu_on_n_a_pas_su_deplacer_est_annule(self):
        """⚠ « 53 » ne décroche jamais, et le plafond de rappels est à zéro :
        RingBack a fini d'essayer dès la première passe. Son rendez-vous ne
        peut pas rester au planning d'une journée qu'il ne travaille pas."""
        base = self.application.base
        _, absent, q1 = self._rdv("M. Jamais Là", "53")
        _, bouge, q2 = self._rdv("Mme Bouge", "51", heure=11)
        campagne_id = self._campagne_de_deplacement(
            [("M. Jamais Là", ("53",), q1), ("Mme Bouge", ("51",), q2)])
        self._derouler(campagne_id)
        etats = {c["nom"]: c for c in base.contacts_de_campagne(campagne_id)}
        # Celui qui n'a pas décroché : plus aucune tentative à venir.
        self.assertEqual(etats["M. Jamais Là"]["etat"], "injoignable")
        self.assertEqual(base.obtenir_rendezvous(absent)["statut"], "annulé")
        self.assertIn("n'a pas pu se faire", etats["M. Jamais Là"]["detail"])
        # ⚠ ET LA CONTRE-ÉPREUVE DANS LE MÊME ESSAI : celui qui a accepté n'est
        # PAS annulé — son rendez-vous a bel et bien bougé.
        self.assertEqual(etats["Mme Bouge"]["etat"], "accepté")
        self.assertNotEqual(base.obtenir_rendezvous(bouge)["statut"], "annulé")

    def test_la_place_liberee_redevient_libre(self):
        """CE QUE L'ANNULATION SERT À FAIRE : le créneau se vide pour de bon.
        Annuler sans libérer la place n'aurait rien réglé — c'est justement le
        trou qu'il ne savait pas avoir."""
        base = self.application.base
        _, absent, q1 = self._rdv("M. Jamais Là", "53")
        campagne_id = self._campagne_de_deplacement(
            [("M. Jamais Là", ("53",), q1)])
        self._derouler(campagne_id)
        self.assertEqual(base.obtenir_rendezvous(absent)["statut"], "annulé")
        # Une ligne au cahier des changements, avec la raison en clair : c'est
        # elle qu'il relit pour reporter dans son propre logiciel.
        lignes = [c for c in base.changements_de_campagne(campagne_id)
                  if c["genre"] == "annulation"]
        self.assertEqual(len(lignes), 1)
        self.assertIn("n'a pas pu être déplacé", lignes[0]["raison"])

    # --------------------------------------------------- ② QUAND (son choix)
    def test_tant_qu_une_relance_est_armee_le_rendezvous_reste(self):
        """SON CHOIX DU 20/08 : « quand RingBack a fini d'essayer ».

        Tant qu'un rappel est prévu, on va rappeler POUR DÉPLACER : annuler
        d'avance ferait parler d'un rendez-vous qui n'existe plus. Le plafond
        est ici à trois, donc une relance est armée.
        """
        base = self.application.base
        _, absent, q1 = self._rdv("M. Jamais Là", "53")
        campagne_id = self._campagne_de_deplacement(
            [("M. Jamais Là", ("53",), q1)], relance_max="3")
        self._derouler(campagne_id)
        contact = base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(contact["etat"], "à recontacter")
        self.assertTrue([r for r in base.relances_de_campagne(campagne_id)
                         if r["statut"] == "planifiée"])
        # Le rendez-vous est INTACT : on n'a pas fini d'essayer.
        self.assertEqual(base.obtenir_rendezvous(absent)["statut"], "prévu")

    def test_la_derniere_relance_ratee_annule_enfin_le_rendezvous(self):
        """L'AUTRE MOITIÉ DU MÊME CHOIX, et le second des trois moments où
        RingBack cesse d'essayer : la relance s'achève, plus rien ne vient.

        ⚠ CET ESSAI A RÉVÉLÉ UNE COLLISION avec la correction de la veille
        (« en simulation, pas de finalité plafond atteint ») : le plafond étant
        levé en simulation, les relances s'y enchaînent SANS FIN et ce moment
        n'arrive jamais. La règle, elle, est juste — c'est la levée du plafond
        qui n'a pas de borne. On éprouve donc ce moment là où le plafond
        s'applique : avec un client d'appels NON simulé.
        """
        base = self.application.base
        _, absent, q1 = self._rdv("M. Jamais Là", "53")
        campagne_id = self._campagne_de_deplacement(
            [("M. Jamais Là", ("53",), q1)], relance_max="1",
            relance_mode="delai", relance_delai="0")
        self._derouler(campagne_id)
        self.assertEqual(base.obtenir_rendezvous(absent)["statut"], "prévu")
        self.assertTrue([r for r in base.relances_de_campagne(campagne_id)
                         if r["statut"] == "planifiée"])
        # LE GESTE HUMAIN : il lance les relances dues. Elles ratent toutes.
        self.application.planif.client_appels = _ClientQuiNeRepondJamais()
        for _ in range(4):
            if not [r for r in base.relances_de_campagne(campagne_id)
                    if r["statut"] == "planifiée"]:
                break
            campagnes.executer_relances_dues(self.application.base,
                                             self.application.planif,
                                             self.application.preferences)
        self.assertEqual([r for r in base.relances_de_campagne(campagne_id)
                          if r["statut"] == "planifiée"], [])
        self.assertEqual(base.obtenir_rendezvous(absent)["statut"], "annulé")

    def test_clore_a_la_main_tranche_aussi(self):
        """LE TROISIÈME MOMENT : clore à la main annule les relances, donc plus
        aucune tentative ne viendra — le rendez-vous ne peut plus attendre."""
        base = self.application.base
        _, absent, q1 = self._rdv("M. Jamais Là", "53")
        campagne_id = self._campagne_de_deplacement(
            [("M. Jamais Là", ("53",), q1)], relance_max="3")
        self._derouler(campagne_id)
        self.assertEqual(base.obtenir_rendezvous(absent)["statut"], "prévu")
        campagnes.clore_campagne(base, campagne_id)
        self.assertEqual(base.obtenir_rendezvous(absent)["statut"], "annulé")

    # ----------------------------------------------------- ③ QUI (son choix)
    def test_celui_qu_on_n_a_jamais_pu_appeler_est_annule_aussi(self):
        """SON CHOIX DU 20/08 : les 🚫 aussi. Il n'est pas là ce jour-là — leur
        rendez-vous ne tient pas davantage. Ils sont dans sa liste de rappels
        humains, c'est en les appelant qu'il refixera.

        C'était exactement le cas qu'il a vu : 2 rendez-vous sur 6 restés au
        planning, et c'étaient les deux personnes marquées 🚫.
        """
        base = self.application.base
        client, absent, q1 = self._rdv("Mme Ne Plus Appeler", "51")
        base.definir_ne_plus_appeler(client, True)
        campagne_id = self._campagne_de_deplacement(
            [("Mme Ne Plus Appeler", ("51",), q1)])
        self._derouler(campagne_id)
        contact = base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(contact["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertEqual(base.appels_du_contact_campagne(contact["id"]), [])
        self.assertEqual(base.obtenir_rendezvous(absent)["statut"], "annulé")
        # Les DEUX raisons sont lisibles : pourquoi elle n'a pas été appelée,
        # et ce qu'il advient de son rendez-vous.
        self.assertTrue(db.refus_de_l_agent(contact["detail"].split(" ·")[0]))
        self.assertIn("n'a pas pu se faire", contact["detail"])

    def test_celui_que_la_campagne_a_deliberement_epargne_garde_le_sien(self):
        """⚠ LE DÉFAUT QUE LE BANC A ATTRAPÉ DANS MA PREMIÈRE VERSION.

        « Nous n'avons pas pu » n'est pas « nous n'avons pas voulu ». Une
        campagne « arrêt au premier oui » ÉPARGNE volontairement tous ceux qui
        suivent le premier accord : on ne leur a rien demandé, leur rendez-vous
        n'a aucune raison de bouger. Ma règle les annulait — trois rendez-vous
        par campagne, et la chaîne de cascade mourait au premier maillon.
        """
        base = self.application.base
        _, accepte, q1 = self._rdv("Mme Accepte", "51")
        _, epargne, q2 = self._rdv("M. Jamais Appelé", "51", heure=11,
                                   prefixe="11 22 33")
        campagne_id = self._campagne_de_deplacement(
            [("Mme Accepte", ("51",), q1),
             ("M. Jamais Appelé", ("51", "11 22 33"), q2)],
            politique="premier_oui")
        self._derouler(campagne_id)
        etats = {c["nom"]: c for c in base.contacts_de_campagne(campagne_id)}
        self.assertEqual(etats["M. Jamais Appelé"]["etat"], "épargné")
        self.assertEqual(base.appels_du_contact_campagne(
            etats["M. Jamais Appelé"]["id"]), [])
        # SON RENDEZ-VOUS EST INTACT.
        self.assertEqual(base.obtenir_rendezvous(epargne)["statut"], "prévu")

    def test_les_autres_natures_ne_sont_pas_touchees(self):
        """LA BORNE DE LA RÈGLE : elle ne vaut QUE pour le déplacement. Sur une
        confirmation ou un rappel, un non-joint garde son rendez-vous — rien
        n'a été demandé qui le remettrait en cause."""
        base = self.application.base
        for nature in ("confirmation", "rappel_rdv"):
            with self.subTest(nature=nature):
                _, rdv, quand = self._rdv("M. Jamais Là", "53")
                numero = self._numero("53")
                campagne_id = self._campagne(
                    nature, [f"M. Jamais Là;{numero};{quand};Séance"],
                    relance_max="0")
                self._derouler(campagne_id)
                self.assertEqual(base.obtenir_rendezvous(rdv)["statut"],
                                 "prévu")


class TestRefusDeLAgentVersUnHumain(_CampagneAssistant):
    """⚠ SA DEMANDE DU 20/08/2026, et la règle qu'elle installe.

    « Les personnes qui ont demandé de ne plus être appelées par un agent IA
    doivent être enregistrées comme à rappeler par un humain dans toutes les
    campagnes, et donc subir la logique de cet état. »

    Elles ont refusé L'AGENT, pas le cabinet. Les marquer « exclu » les faisait
    disparaître en silence — personne ne les rappelait jamais, et leur affaire
    tombait. Mesuré dans sa base ce jour-là : 32 contacts écartés ainsi, dans
    26 campagnes.

    ⚠ SIX CHEMINS refusent de composer (création de la campagne, appel de
    l'assistant, moteur classique, relance de cascade, reprise de cascade, file
    d'appels). On éprouve LA RÈGLE à son point de passage — `db.suite_du_refus`
    — puis on vérifie que les chemins y passent : une seule entrée oubliée, et
    la personne redisparaît sans que rien ne le signale.
    """

    NOM = "Mme Refus Agent"
    NUMERO = "+33 6 00 00 00 51"

    # ------------------------------------------------------- ① LA RÈGLE
    def test_seuls_les_deux_refus_du_stop_partent_vers_un_humain(self):
        """La table, dans les deux sens — c'est elle qui décide, pas les
        appelants. Les deux autres refus ne bougent pas : sans numéro, un
        humain n'a rien à composer non plus ; fiche supprimée, il n'y a plus
        personne à rappeler."""
        for refus in (db.REFUS_STOP, db.REFUS_STOP_NOM):
            with self.subTest(refus=refus):
                etat, detail = db.suite_du_refus(refus)
                self.assertEqual(etat, db.ETAT_RAPPEL_HUMAIN)
                self.assertIn("humain", detail)
                self.assertTrue(db.refus_de_l_agent(detail))
        for refus in (db.REFUS_SANS_NUMERO, db.REFUS_CLIENT_SUPPRIME):
            with self.subTest(refus=refus):
                self.assertEqual(db.suite_du_refus(refus), ("exclu", refus))
        # Un refus inconnu — ou pas de refus du tout — retombe sur l'ancien
        # comportement : c'est ce qui rend la table sûre à étendre.
        self.assertEqual(db.suite_du_refus(None), ("exclu", None))
        self.assertEqual(db.suite_du_refus("autre chose"),
                         ("exclu", "autre chose"))

    def test_la_table_ne_couvre_que_les_stop(self):
        """LE GARDE-FOU DE LA TABLE elle-même : y ajouter un refus par
        distraction enverrait vers un humain quelqu'un qu'aucun humain ne peut
        rappeler. Cet essai le dit avant que ça n'arrive."""
        self.assertEqual(set(db.SUITE_DU_REFUS),
                         {db.REFUS_STOP, db.REFUS_STOP_NOM})

    # -------------------------------------------- ② LA LOGIQUE DE L'ÉTAT
    def _campagne_avec_un_refuseur(self, par_le_nom=False):
        """Une campagne qui vise quelqu'un dont la fiche porte le 🚫."""
        base = self.application.base
        if par_le_nom:
            # L'HOMONYME : une AUTRE fiche, même nom, numéro différent.
            autre = base.ajouter_client(self.NOM, "+33 6 00 00 00 91")
            base.definir_ne_plus_appeler(autre, True)
        else:
            client = base.ajouter_client(self.NOM, self.NUMERO)
            base.definir_ne_plus_appeler(client, True)
        return self._campagne(
            "confirmation",
            [f"{self.NOM};{self.NUMERO};{DEMAIN};Bilan",
             f"M. Libre Exemple;+33 6 00 00 00 52;{DEMAIN};Bilan"])

    def test_elle_subit_la_logique_de_l_etat_du_debut_a_la_fin(self):
        """« Et donc subir la logique de cet état », mot pour mot :

        · jamais appelée automatiquement (l'état n'est pas appelable) ;
        · aucune relance armée, donc aucun plafond approché ;
        · visible dans 🔁 Relances § 🙋, avec la raison en clair ;
        · le geste « c'est fait » l'en sort sans rien effacer.
        """
        base = self.application.base
        campagne_id = self._campagne_avec_un_refuseur()
        # ⚠ LA CAMPAGNE TOURNE POUR DE BON : créer n'est pas exécuter, et
        # c'est pendant l'exécution que le 🚫 est relu au moment de composer.
        self._derouler(campagne_id)
        contact = base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(contact["etat"], db.ETAT_RAPPEL_HUMAIN)
        # ① aucun appel, jamais — la garantie qui ne doit pas bouger.
        self.assertEqual(base.appels_du_contact_campagne(contact["id"]), [])
        # ② aucune relance : rien ne repartira tout seul.
        self.assertEqual([r for r in base.relances_de_campagne(campagne_id)
                          if r["contact_id"] == contact["id"]], [])
        # ③ elle est DANS la liste des rappels humains, avec la raison.
        attente = base.contacts_rappel_humain()
        mien = next(c for c in attente if c["id"] == contact["id"])
        self.assertTrue(db.refus_de_l_agent(mien["detail"]))
        self.assertEqual(mien["tentatives_faites"], 0)
        # ④ « c'est fait » l'en sort, sans rien effacer.
        self.assertTrue(base.marquer_contact_traite(contact["id"]))
        self.assertNotIn(contact["id"],
                         [c["id"] for c in base.contacts_rappel_humain()])
        self.assertIn(
            contact["id"],
            [c["id"] for c in base.contacts_rappel_humain(traites=True)])

    def test_la_liste_des_rappels_montre_QUI_a_refuse_l_agent(self):
        """⚠ CE QUI SE VOIT SANS CLIQUER. Sa liste 🙋 en compte plus de neuf
        cents : ouvrir la fenêtre de chacune pour savoir à qui l'on a affaire
        n'est pas un geste tenable.

        Et les deux familles ne se traitent pas pareil : « ce que l'agent n'a
        pas su conclure » se reprend là où la conversation s'est arrêtée ; un
        refus d'agent, lui, n'a jamais eu de conversation. Le repère dit
        LEQUEL, la fenêtre dit QUOI — elle reste, elle n'est pas remplacée.
        """
        base = self.application.base
        campagne_id = self._campagne_avec_un_refuseur()
        self._derouler(campagne_id)
        contact = base.contacts_de_campagne(campagne_id)[0]
        _, page = self._obtenir("/relances?vue=humains")
        self.assertIn("🚫 a refusé l'agent", page)
        # La fenêtre reste accessible, et elle porte le texte entier.
        self.assertIn(f'data-modale="/relances/demande?contact={contact["id"]}"',
                      page)
        _, fenetre = self._obtenir(
            f"/relances/demande?contact={contact['id']}", fenetre=True)
        self.assertIn("ne plus être appelée par un agent", fenetre)

    def test_un_rappel_humain_ordinaire_ne_porte_pas_le_repere(self):
        """LA CONTRE-ÉPREUVE : le repère ne doit pas se poser sur tout le monde,
        sinon il ne distingue plus rien. Un 🙋 venu d'une conversation garde
        exactement la cellule qu'il avait."""
        base = self.application.base
        campagne_id = self._campagne_avec_un_refuseur()
        self._derouler(campagne_id)
        autre = base.contacts_de_campagne(campagne_id)[1]
        base.changer_etat_contact_campagne(autre["id"], db.ETAT_RAPPEL_HUMAIN,
                                           None)
        base.definir_detail_contact(
            autre["id"], "Le client veut déplacer mais ne peut pas fixer de "
                         "date aujourd'hui.")
        _, page = self._obtenir("/relances?vue=humains")
        # Sa demande s'ouvre en fenêtre, comme avant — le lien est bien là.
        self.assertIn(f'data-modale="/relances/demande?contact={autre["id"]}"',
                      page)
        _, fenetre = self._obtenir(
            f"/relances/demande?contact={autre['id']}", fenetre=True)
        self.assertIn("ne peut pas fixer de date", fenetre)
        # ⚠ ET LE REPÈRE N'APPARAÎT QU'UNE FOIS : pour le refus, pas pour lui.
        # Posé sur tout le monde, il ne distinguerait plus rien.
        self.assertEqual(page.count("a refusé l'agent"), 1)

    def test_l_homonyme_part_aussi_vers_un_humain(self):
        """SON CHOIX DU 20/08 : l'homonyme n'a rien demandé — mais un humain
        est justement le seul à pouvoir dire s'il s'agit de la même personne.
        C'est le cas le plus fréquent chez lui : 24 contacts sur 32."""
        base = self.application.base
        campagne_id = self._campagne_avec_un_refuseur(par_le_nom=True)
        self._derouler(campagne_id)
        contact = base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(contact["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertEqual(base.appels_du_contact_campagne(contact["id"]), [])
        self.assertIn("même nom", contact["detail"])
        self.assertIn("humain", contact["detail"])

    def test_les_autres_de_la_campagne_sont_appeles_normalement(self):
        """LA CONTRE-ÉPREUVE : la règle n'écarte QUE le 🚫. Une campagne dont
        tout le monde partirait vers un humain serait un bien pire défaut."""
        base = self.application.base
        campagne_id = self._campagne_avec_un_refuseur()
        self._derouler(campagne_id)
        libre = base.contacts_de_campagne(campagne_id)[1]
        self.assertEqual(libre["nom"], "M. Libre Exemple")
        self.assertNotEqual(libre["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertTrue(base.appels_du_contact_campagne(libre["id"]))

    # --------------------------------- ③ LE 🚫 POSÉ APRÈS LA CRÉATION
    def test_un_stop_pose_ENTRE_TEMPS_est_relu_au_moment_de_composer(self):
        """LE CHEMIN D'APPEL, pas celui de la création : la campagne est déjà
        faite quand la personne demande le 🚫. C'est par là que passent toutes
        les campagnes déjà prêtes, et c'est une entrée distincte — l'oublier
        aurait laissé la moitié des cas à l'ancienne règle."""
        base = self.application.base
        client = base.ajouter_client(self.NOM, self.NUMERO)
        campagne_id = self._campagne(
            "confirmation", [f"{self.NOM};{self.NUMERO};{DEMAIN};Bilan"])
        contact_id = base.contacts_de_campagne(campagne_id)[0]["id"]
        self.assertEqual(base.obtenir_contact_campagne(contact_id)["etat"],
                         "à appeler")
        # ⚠ LE 🚫 ARRIVE MAINTENANT, campagne déjà prête.
        base.definir_ne_plus_appeler(client, True)
        self._derouler(campagne_id)
        contact = base.obtenir_contact_campagne(contact_id)
        self.assertEqual(contact["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertEqual(base.appels_du_contact_campagne(contact_id), [])
        self.assertTrue(db.refus_de_l_agent(contact["detail"]))


class TestStopAuTelephone(_CampagneAssistant):
    """🚫 demandé PENDANT l'appel — ce que RingBack écrit alors.

    ⚠ LE MANQUE QUE ÇA COMBLE (10/08/2026) : le drapeau « ne plus appeler » ne
    se posait que depuis l'écran 👥 Contacts. Quelqu'un qui le demandait À
    L'AGENT n'était pas entendu — il était rappelé à la campagne suivante.
    C'est un manque de courtoisie autant qu'un manque de conformité.
    """

    NOM = "Mme Stop Exemple"
    # ⚠ « 57 » : elle refuse ET demande qu'on ne la rappelle plus.
    NUMERO = "+33 6 00 00 00 57"

    def _avec_fiche(self, numero=None, nature="confirmation"):
        """Un client, son rendez-vous, et une campagne qui le vise.

        La fiche existe AVANT l'appel : c'est elle que le 🚫 doit marquer, et
        c'est ainsi qu'un vrai cabinet se présente (les contacts viennent de
        l'agenda, pas d'un collage).
        """
        base = self.application.base
        client = base.ajouter_client(self.NOM, numero or self.NUMERO)
        rdv = base.ajouter_rendezvous(client, DEMAIN, "Bilan")
        campagne_id = self._campagne(
            nature, [f"{self.NOM};{numero or self.NUMERO};{DEMAIN};Bilan"])
        return campagne_id, client, rdv

    def test_la_fiche_est_marquee_et_le_dit(self):
        base = self.application.base
        campagne_id, client, _ = self._avec_fiche()
        etats = self._derouler(campagne_id)
        contact = etats[self.NOM]
        # ⚠ SUR LA FICHE, pas sur la campagne : le drapeau vaut pour TOUS les
        # appels à venir, de toutes les campagnes.
        self.assertTrue(base.obtenir_client(client)["ne_plus_appeler"])
        # L'écran le dit, et ce qui a été convenu pendant l'appel reste écrit.
        self.assertIn("A demandé à ne plus être appelée", contact["detail"])
        self.assertIn("🚫", contact["detail"])
        # L'issue, elle, a été appliquée normalement (57 = elle annule).
        self.assertEqual(contact["issue"], "canceled")
        self.assertEqual(contact["etat"], assistant.ETAT_RAPPELLERA)

    def test_le_cahier_des_changements_garde_la_trace(self):
        """⚠ C'EST LE SEUL ENDROIT qui garde QUAND et POURQUOI un contact a
        cessé d'être appelable. Sans lui, un 🚫 posé au téléphone serait
        indistinguable d'un 🚫 posé à la main six mois plus tôt."""
        campagne_id, _, _ = self._avec_fiche()
        self._derouler(campagne_id)
        changements = self.application.base.changements_de_campagne(campagne_id)
        lignes = [c for c in changements if c["genre"] == "ne_plus_appeler"]
        self.assertEqual(len(lignes), 1)
        self.assertEqual(lignes[0]["nom"], self.NOM)
        self.assertIn("demandé au téléphone", lignes[0]["raison"])
        # Et il se lit dans le cahier affiché.
        self.assertIn("Ne plus appeler", assistant.ligne_cahier(lignes[0]))

    def test_les_relances_programmees_tombent(self):
        """⚠ UNE RELANCE SURVIVANTE aurait rappelé la personne quelques heures
        après qu'elle a demandé le contraire — précisément ce qu'elle voulait
        éviter."""
        base = self.application.base
        campagne_id, _, _ = self._avec_fiche()
        contact = base.contacts_de_campagne(campagne_id)[0]
        # Une relance déjà programmée, comme après un premier appel sans réponse.
        base.creer_relance(campagne_id, contact["id"], DEMAIN, tentative=1,
                           motif="essai")
        self.assertEqual(len(base.relances_de_campagne(campagne_id)), 1)
        self._derouler(campagne_id)
        restantes = [r for r in base.relances_de_campagne(campagne_id)
                     if r["statut"] == "planifiée"]
        self.assertEqual(restantes, [])
        self.assertIn("relance(s) programmée(s) annulée(s)",
                      base.contacts_de_campagne(campagne_id)[0]["detail"])

    def test_plus_aucun_appel_ne_part_pour_elle_ensuite(self):
        """⚠ LA GARANTIE QUI COMPTE, éprouvée sur une SECONDE campagne : le
        drapeau est relu au moment de composer, par le numéro ET par le nom."""
        premiere, _, _ = self._avec_fiche()
        self._derouler(premiere)
        seconde = self._campagne(
            "confirmation", [f"{self.NOM};{self.NUMERO};{DEMAIN};Bilan"])
        etats = self._derouler(seconde)
        contact = etats[self.NOM]
        # ⚠ CE QUI COMPTE ICI N'A PAS CHANGÉ : aucun appel n'est parti. Ce qui
        # a changé, c'est qu'elle ne disparaît plus — un humain la rappellera.
        self.assertEqual(contact["etat"], db.ETAT_RAPPEL_HUMAIN)
        self.assertIsNone(contact["issue"])          # aucun appel n'est parti
        self.assertTrue(db.refus_de_l_agent(contact["detail"]))

    def test_ce_qui_a_ete_convenu_est_honore_AVANT_le_stop(self):
        """⚠ L'ORDRE COMPTE. « Oui pour cette fois, mais ne m'appelez plus
        ensuite » doit laisser le rendez-vous confirmé : poser le 🚫 d'abord
        aurait fait refuser l'appel en cours par le contrôle du 🚫 lui-même.
        """
        base = self.application.base
        # La terminaison « 51 » accepte ; on ajoute le 🚫 au résultat rendu.
        campagne_id, client, rdv = self._avec_fiche(
            numero="+33 6 00 00 00 51", nature="rappel_rdv")

        class AvecStop(calle_client.AppelSimule):
            def appeler(self, *arguments, **nommes):
                issue = super().appeler(*arguments, **nommes)
                issue.resultat[calle_client.CHAMP_NE_PLUS_APPELER] = "yes"
                return issue

        self.application.planif.client_appels = AvecStop(graine=1, latence=0)
        assistant.executer_campagne(self.application, campagne_id)
        contact = base.contacts_de_campagne(campagne_id)[0]
        # L'issue a été appliquée : sa présence est confirmée…
        self.assertEqual(contact["etat"], "accepté")
        self.assertEqual(base.obtenir_rendezvous(rdv)["statut"], "confirmé")
        # …ET le 🚫 est posé.
        self.assertTrue(base.obtenir_client(client)["ne_plus_appeler"])
        self.assertIn("A demandé à ne plus être appelée", contact["detail"])

    def test_il_se_retire_d_un_clic_comme_avant(self):
        """Le 🚫 posé au téléphone n'est pas d'une autre nature : il se lève
        depuis 👥 Contacts, comme celui posé à la main."""
        campagne_id, client, _ = self._avec_fiche()
        self._derouler(campagne_id)
        # Le formulaire de 👥 Contacts envoie « 0 » pour lever le drapeau.
        self._poster("/clients/ne-plus-appeler",
                     {"client": client, "valeur": "0"})
        self.assertFalse(
            self.application.base.obtenir_client(client)["ne_plus_appeler"])


class TestRefusDesPropositions(_CampagneAssistant):
    """« Ne me proposez plus de créneau » — le drapeau plus doux que le 🚫.

    ⚠ LA DIFFÉRENCE AVEC LE 🚫 EST TOUT L'INTÉRÊT : la personne reste
    appelable pour SES rendez-vous (rappel, confirmation, déplacement). Ce
    qu'elle refuse, c'est qu'on lui propose des places libérées.
    """

    def _cascade(self, numero):
        """Une campagne « créneau libéré » d'une personne, sur une place LIBRE.

        ⚠ CORRIGÉ LE 11/08/2026 : le montage offrait à cette personne la place
        qu'elle OCCUPAIT déjà (son rendez-vous et le créneau proposé étaient tous
        deux à DEMAIN). C'était sans conséquence tant que rien ne vérifiait la
        place ; depuis qu'une campagne relit sa place avant d'appeler, elle
        s'arrêtait à juste titre — et l'essai ne mesurait plus rien.

        Son rendez-vous est donc PLUS TARD que la place : c'est le cas normal,
        et c'est aussi celui que la règle de l'intérêt attend.
        """
        base = self.application.base
        plus_tard = (datetime.datetime.fromisoformat(DEMAIN)
                     + datetime.timedelta(days=14)).isoformat(timespec="minutes")
        client = base.ajouter_client("Mme Assez Merci", numero)
        base.ajouter_rendezvous(client, plus_tard, "Bilan")
        campagne_id = self._campagne(
            "creneau_libere", [f"Mme Assez Merci;{numero};{plus_tard};Bilan"],
            info_creneau_libere=DEMAIN)
        return campagne_id, client

    def test_le_refus_est_ecrit_sur_la_fiche_et_pas_le_stop(self):
        base = self.application.base
        campagne_id, client = self._cascade("+33 6 00 00 00 58")
        etats = self._derouler(campagne_id)
        contact = etats["Mme Assez Merci"]
        fiche = base.obtenir_client(client)
        self.assertTrue(fiche["plus_de_proposition"])
        # ⚠ ET SURTOUT PAS LE 🚫 : elle reste appelable pour ses rendez-vous.
        self.assertFalse(fiche["ne_plus_appeler"])
        self.assertEqual(contact["etat"], "refusé")
        self.assertIn("ne veut plus qu'on lui propose", contact["detail"])
        # Le cahier en garde la trace, avec son propre genre.
        genres = [c["genre"] for c in
                  base.changements_de_campagne(campagne_id)]
        self.assertIn("plus_de_proposition", genres)

    def test_un_refus_ordinaire_ne_pose_aucun_drapeau(self):
        """⚠ REFUSER UNE PLACE N'A JAMAIS VOULU DIRE REFUSER LES SUIVANTES."""
        base = self.application.base
        campagne_id, client = self._cascade("+33 6 00 00 00 52")
        self._derouler(campagne_id)
        fiche = base.obtenir_client(client)
        self.assertFalse(fiche["plus_de_proposition"])
        self.assertFalse(fiche["ne_plus_appeler"])

    def test_plus_aucune_proposition_ne_part_ensuite(self):
        """La garantie, éprouvée sur une SECONDE campagne de créneau libéré."""
        campagne_id, _ = self._cascade("+33 6 00 00 00 58")
        self._derouler(campagne_id)
        seconde = self._campagne(
            "creneau_libere",
            [f"Mme Assez Merci;+33 6 00 00 00 58;{DEMAIN};Bilan"],
            info_creneau_libere=DEMAIN)
        etats = self._derouler(seconde)
        contact = etats["Mme Assez Merci"]
        self.assertEqual(contact["etat"], "épargné")
        self.assertIsNone(contact["issue"])          # aucun appel n'est parti
        self.assertIn("ne lui propose plus", contact["detail"])

    def test_elle_reste_appelable_pour_SES_rendez_vous(self):
        """⚠ CE QUI DISTINGUE CE DRAPEAU DU 🚫. Le confondre aurait coupé le
        téléphone à quelqu'un qui ne l'a pas demandé."""
        campagne_id, _ = self._cascade("+33 6 00 00 00 58")
        self._derouler(campagne_id)
        rappel = self._campagne(
            "confirmation",
            [f"Mme Assez Merci;+33 6 00 00 00 58;{DEMAIN};Bilan"])
        etats = self._derouler(rappel)
        contact = etats["Mme Assez Merci"]
        self.assertNotEqual(contact["etat"], "épargné")
        self.assertIsNotNone(contact["issue"])       # l'appel EST parti
    def test_la_relance_rejoue_la_regle_de_l_interet(self):
        """⚠ LE MANQUE TROUVÉ EN ÉCRIVANT LE DOCUMENT DES FINALITÉS (10/08/2026).
        La règle filtrait la FILE de la campagne, pas le départ d'une relance :
        quelqu'un dont le rendez-vous est déjà plus tôt que toutes les places
        restantes était rappelé pour une place qui ne l'avançait plus.

        Ici, le contact refuse les propositions — la même fonction décide des
        deux (), et c'est le chemin de la relance
        qu'on éprouve : le téléphone ne doit PAS sonner.
        """
        base = self.application.base
        campagne_id, client = self._cascade("+33 6 00 00 00 58")
        self._derouler(campagne_id)          # elle refuse et pose le drapeau
        # Une seconde campagne, une relance déjà due pour cette personne.
        seconde = self._campagne(
            "creneau_libere",
            [f"Mme Assez Merci;+33 6 00 00 00 58;{DEMAIN};Bilan"],
            info_creneau_libere=DEMAIN)
        contact = base.contacts_de_campagne(seconde)[0]
        base.creer_relance(seconde, contact["id"], HIER, tentative=1,
                           motif="essai")
        self.application.planif.client_appels = calle_client.AppelSimule(
            graine=1, latence=0)
        comptes = campagnes.executer_relances_dues(
            base, self.application.planif, self.application.preferences)
        # ⚠ LA RELANCE EST CONSOMMÉE, mais AUCUN appel n'est parti.
        self.assertEqual(len(comptes), 1)
        self.assertEqual(comptes[0]["etat"], "épargné")
        self.assertIsNone(comptes[0]["issue"])
        frais = base.obtenir_contact_campagne(contact["id"])
        self.assertEqual(frais["etat"], "épargné")
        # ⚠ DEUX GARDE-FOUS MÈNENT ICI, et c est voulu : celui de la relance
        # (campagne à LISTE de places) et celui de l appel (toute cascade, y
        # compris une liste collée à la main). Le detail dit lequel a parle ;
        # ce qui compte est qu AUCUN appel ne soit parti.
        self.assertIn("ne lui propose plus de creneau".replace("creneau", "créneau"),
                      frais["detail"])
        self.assertEqual(base.appels_du_contact_campagne(contact["id"]), [])

    def test_il_se_leve_depuis_la_liste_des_contacts(self):
        """⚠ AU MÊME ENDROIT QUE LE 🚫 : la bascule « ne plus appeler » vit dans
        la ligne de 👥 Contacts, et celle-ci l'accompagne. Deux drapeaux voisins
        se lèvent au même endroit, sinon on cherche l'un en croyant l'autre."""
        campagne_id, client = self._cascade("+33 6 00 00 00 58")
        self._derouler(campagne_id)
        _, liste = self._obtenir("/clients?par_page=0")
        # Le texte est écrit tel quel dans la page (pas échappé).
        self.assertIn("Ne veut plus qu'on lui", liste)
        self.assertIn('action="/clients/propositions"', liste)
        # ⚠ ET IL NE SE CONFOND PAS AVEC LE 🚫 : le bouton « Ne plus appeler »
        # est TOUJOURS là, cette personne restant appelable.
        self.assertIn(">Ne plus appeler</button>", liste)
        self._poster("/clients/propositions", {"client": client, "valeur": "1"})
        self.assertFalse(
            self.application.base.obtenir_client(client)["plus_de_proposition"])


class TestModeSimplifieEtAvance(_CampagneAssistant):
    """Les deux modes de saisie — demande du propriétaire du 02/08/2026.

    LE POINT QUI COMPTE : le mode simplifié ne doit RIEN faire disparaître
    des données. Ce qu'il cache est dans la page, part avec le formulaire et
    garde la valeur des Réglages. Un mode qui perdrait une valeur en la
    cachant serait pire que pas de mode du tout.
    """

    def _etape2(self):
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        return self._brouillon(page), page

    def test_le_mode_par_defaut_est_le_simplifie(self):
        _, page = self._etape2()
        self.assertIn('data-mode="simplifie"', page)
        self.assertIn('class="bascule-mode actif" data-mode="simplifie"', page)

    def test_l_apercu_du_message_est_en_mode_avance(self):
        """A → C : l'aperçu passe en avancé, et les blocs se replient."""
        _, page = self._etape2()
        # La renumérotation demandée : A = informations, B = options,
        # C = aperçu (l'ancien A).
        self.assertIn("<h2>A. Informations générales", page)
        self.assertIn("<h2>B. Options de comportement", page)
        self.assertIn("<h2>C. Aperçu du message", page)
        self.assertNotIn("<h2>D.", page)
        # L'aperçu est dans la zone qui disparaît en mode simplifié.
        avant_apercu = page.split("<h2>C. Aperçu")[0]
        self.assertIn('<div class="avance">', avant_apercu)
        # Et ses deux parties écrites par la nature sont REPLIÉES : ce sont
        # des <details> sans « open ».
        self.assertIn("<summary><strong>② Son objectif et son contexte</strong>",
                      page)
        self.assertIn("<details><summary><strong>③ Les issues</strong>", page)

    def test_le_mode_simplifie_ne_perd_aucune_valeur(self):
        """LE CONTRÔLE ESSENTIEL : caché ≠ absent.

        Ce que le mode simplifié masque reste DANS le formulaire, avec sa
        valeur : c'est ce qui autorise à cacher quoi que ce soit. La bascule
        se fait dans la page (feuille de style), rien ne repart au serveur.
        """
        identifiant, _ = self._etape2()
        _, page = self._obtenir(f"/assistant/message?b={identifiant}")
        self.assertIn('data-mode="simplifie"', page)
        # ⚠ La zone de mission est là, seulement masquée : elle partira donc
        # avec le formulaire.
        self.assertIn('name="mission"', page)
        self.assertIn('name="mission_editee"', page)
        # Et les options de comportement aussi, avec leurs valeurs.
        self.assertIn('id="opt_recontacter"', page)
        self.assertIn('name="relance_max"', page)

    def test_le_formulaire_s_ouvre_toujours_en_simplifie(self):
        """Décision du propriétaire (02/08/2026) : plus de mémoire du mode.

        Un écran qui s'ouvre en « avancé » parce qu'on y était passé la
        veille surprend plus qu'il ne sert. La bascule reste entière dans la
        page.
        """
        for essai in range(2):
            with self.subTest(essai=essai):
                _, page = self._etape2()
                self.assertIn('data-mode="simplifie"', page)
                self.assertIn('class="bascule-mode actif" data-mode="simplifie"',
                              page)
        # Et il n'y a plus de route pour retenir le mode : une porte sans
        # pièce derrière serait pire qu'un réglage manquant.
        with self.assertRaises(urllib.error.HTTPError) as refus:
            self._poster("/assistant/mode", {"mode": "avance"})
        self.assertEqual(refus.exception.code, 404)

    def test_l_etape_3_n_a_plus_ni_bascule_ni_colonnes_attendues(self):
        """⚠ RETIRÉES LE 09/08/2026, à la demande du propriétaire.

        Le bloc « Les colonnes attendues » avait rejoint l'étape ③ le
        02/08 ; il en est parti. Ce qu'il montrait se lit ailleurs : l'entête
        de la grille nomme chaque colonne avec son ⚠, et le collage écrit le
        format attendu. La bascule « Simplifié / Avancé » ne commandait plus
        que lui — une bascule qui ne bascule rien est un bouton qui ment.

        L'étape ②, elle, GARDE la sienne : elle y cache l'aperçu du message.
        """
        identifiant, _ = self._etape2()
        self._poster("/assistant/message", {
            "b": identifiant, "action": "continuer",
            "info_entreprise": "Cabinet Essai", "info_creneau_libere": DEMAIN,
            "politique": "premier_oui", "ordre": "liste",
            "opt_recontacter": "1", "relance_mode": "delai",
            "relance_delai": "4", "relance_max": "3"})
        _, page = self._obtenir(f"/assistant/liste?b={identifiant}")
        self.assertNotIn("Les colonnes attendues", page)
        self.assertNotIn('action="/assistant/champs"', page)
        self.assertNotIn('<div class="avance">', page)
        # ⚠ « class="bascule-mode" » NE PROUVERAIT RIEN : les boutons
        # « Automatique / Manuel » reprennent cette même classe. Le marqueur
        # propre à la bascule d'affichage, c'est sa BARRE.
        self.assertNotIn('class="barre-mode"', page)
        self.assertNotIn("data-avance=", page)
        # ⚠ ET ON CHERCHE L'ATTRIBUT SUR <main>, PAS LE MOT DANS LA PAGE : la
        # feuille de style, inlinée, contient « main[data-mode="simplifie"] ».
        # Chercher le mot seul aurait toujours trouvé — le piège a déjà coûté
        # quatre essais faussement verts.
        self.assertIn("<main>", page)
        self.assertNotIn("<main data-mode", page)
        # Et l'étape ② n'a rien perdu.
        _, page2 = self._obtenir(f"/assistant/message?b={identifiant}")
        self.assertIn('<main data-mode="simplifie">', page2)
        self.assertIn('<div class="avance">', page2)


class TestColonnesAttenduesRevalidentLaGrille(_CampagneAssistant):
    """Changer les colonnes quand la grille est remplie la fait revérifier.

    Règle du propriétaire (02/08/2026) : « en trop c'est pas grave,
    manquante = erreur ».
    """

    def _campagne_remplie(self):
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        identifiant = self._brouillon(page)
        self._poster("/assistant/message", {
            "b": identifiant, "action": "continuer",
            "info_entreprise": "Cabinet Essai", "info_creneau_libere": DEMAIN,
            "politique": "premier_oui", "ordre": "liste",
            "opt_recontacter": "1", "relance_mode": "delai",
            "relance_delai": "4", "relance_max": "3"})
        self._poster("/assistant/importer", {
            "b": identifiant, "mode": "collage",
            "liste": f"Mme Une;+33 6 00 00 00 51;{DEMAIN};Séance"})
        return identifiant

    def test_une_colonne_obligatoire_ajoutee_signale_les_lignes_a_completer(self):
        identifiant = self._campagne_remplie()
        self._poster("/assistant/champs", {
            "b": identifiant, "action": "ajouter_champ",
            "champ_libelle": "Numéro de dossier", "champ_type": "texte",
            "champ_obligatoire": "1"})
        _, page = self._obtenir(f"/assistant/liste?b={identifiant}")
        # Une seule phrase, et la CASE fautive colorée : c'est elle qui dit
        # où taper, pas une ligne de texte par manque.
        self.assertIn(assistant.MESSAGE_CHAMPS_OBLIGATOIRES, page)
        self.assertIn('name="c_numero_de_dossier_1" class="manque"', page)
        # Les cases déjà remplies, elles, restent normales.
        self.assertNotIn('name="c_motif_1" class="manque"', page)

    def test_une_colonne_facultative_ajoutee_ne_reproche_rien(self):
        identifiant = self._campagne_remplie()
        self._poster("/assistant/champs", {
            "b": identifiant, "action": "ajouter_champ",
            "champ_libelle": "Commentaire", "champ_type": "texte"})
        _, page = self._obtenir(f"/assistant/liste?b={identifiant}")
        self.assertNotIn(assistant.MESSAGE_CHAMPS_OBLIGATOIRES, page)
        self.assertNotIn('name="c_commentaire_1" class="manque"', page)
        self.assertIn("Commentaire", page)

    def test_une_colonne_obligatoire_ajoutee_a_la_main_se_retire(self):
        """Un bouton qui s'affiche doit AGIR.

        Constaté à l'écran le 02/08/2026 : « Retirer » refusait toute colonne
        obligatoire, y compris une colonne ajoutée à la main et cochée ⚠ —
        le bouton était là et ne faisait rien. Ce qui protège une colonne,
        c'est sa provenance (elle vient de la nature), pas son ⚠.
        """
        identifiant = self._campagne_remplie()
        self._poster("/assistant/champs", {
            "b": identifiant, "action": "ajouter_champ",
            "champ_libelle": "Numéro de dossier", "champ_type": "texte",
            "champ_obligatoire": "1"})
        self._poster("/assistant/champs", {
            "b": identifiant, "action": "retirer_champ:numero_de_dossier"})
        _, page = self._obtenir(f"/assistant/liste?b={identifiant}")
        # On cherche la VARIABLE, pas le libellé : « Numéro de dossier » est
        # aussi l'exemple en filigrane du champ « Ajouter une colonne », et il
        # est donc toujours dans la page.
        self.assertNotIn("[numero_de_dossier]", page)
        # Plus rien ne manque : ni la phrase, ni une case colorée.
        self.assertNotIn(assistant.MESSAGE_CHAMPS_OBLIGATOIRES, page)
        self.assertNotIn('class="manque"', page)
        # Et la colonne de la NATURE, elle, résiste même à un envoi forgé.
        self._poster("/assistant/champs", {
            "b": identifiant, "action": "retirer_champ:motif"})
        _, page = self._obtenir(f"/assistant/liste?b={identifiant}")
        self.assertIn("Motif", page)
        self.assertIn("vient de la nature de la campagne", page)

    def test_une_valeur_devenue_orpheline_est_gardee_et_revient(self):
        """« En trop c'est pas grave » : rien n'est jeté, tout revient."""
        identifiant = self._campagne_remplie()
        self._poster("/assistant/champs", {
            "b": identifiant, "action": "ajouter_champ",
            "champ_libelle": "Commentaire", "champ_type": "texte"})
        brouillon = self.application.obtenir_brouillon_assistant(identifiant)
        brouillon["contacts"][0]["champs"]["commentaire"] = "à rappeler le soir"
        # On retire la colonne : la valeur reste dans la fiche du contact.
        self._poster("/assistant/champs", {
            "b": identifiant, "action": "retirer_champ:commentaire"})
        brouillon = self.application.obtenir_brouillon_assistant(identifiant)
        self.assertEqual(brouillon["contacts"][0]["champs"]["commentaire"],
                         "à rappeler le soir")
        # Et elle réapparaît à l'écran dès que la colonne revient.
        self._poster("/assistant/champs", {
            "b": identifiant, "action": "ajouter_champ",
            "champ_libelle": "Commentaire", "champ_type": "texte"})
        _, page = self._obtenir(f"/assistant/liste?b={identifiant}")
        self.assertIn("à rappeler le soir", page)


class TestMarqueurObligatoire(_TestAvecServeurWeb):
    """⛔ marquait DEUX choses ; il n'en marque plus qu'une.

    Demande du propriétaire (02/08/2026) : « le panneau interdit pour
    obligatoire doit être remplacé par un panneau avec ! ». Un champ à
    remplir n'est pas un interdit — et le produit continue d'employer ⛔ là
    où il veut vraiment dire « refusé ».
    """

    def test_les_champs_obligatoires_portent_le_panneau_d_avertissement(self):
        _, page = self._poster("/assistant/nature",
                               {"nature": "creneau_libere"})
        self.assertIn('<span class="obligatoire">⚠</span>', page)
        self.assertNotIn('<span class="obligatoire">⛔</span>', page)
        self.assertIn("(⚠ = obligatoire)", page)

    def test_le_panneau_sens_interdit_reste_sur_ce_qui_est_refuse(self):
        """Là où ⛔ veut dire « interdit », il ne bouge pas."""
        _, page = self._obtenir("/reglages")
        self.assertIn("⛔ Période interdite", page)

    def test_le_marqueur_prend_une_couleur_d_avertissement(self):
        """La couleur n'était pas décorative : elle ne se voyait même pas.

        ⛔ est un emoji COULEUR : il peignait ses propres teintes et
        ignorait la règle CSS. ⚠ se dessine en monochrome, donc la couleur
        s'applique enfin — et le rouge « danger » se lirait comme une faute
        déjà commise, alors qu'un champ vide n'est qu'à remplir.
        """
        _, page = self._obtenir("/reglages")
        self.assertIn(".obligatoire { color: var(--p-manque-t); }", page)


class TestDiscoursDeLAgent(_TestAvecServeurWeb):
    """Le texte d'ouverture réglé par nature — ⚙ Réglages → Discours."""

    def test_les_reglages_sont_un_accordeon_a_deux_niveaux(self):
        _, page = self._obtenir("/reglages")
        self.assertIn('class="menu-reglages"', page)
        # Niveau 1 : les parties, dépliables.
        self.assertIn("🗓 Agenda", page)
        self.assertNotIn("Agenda et créneaux", page)
        for code in ("appel", "discours", "comportement", "agenda", "essai"):
            with self.subTest(partie=code):
                self.assertIn(f'data-partie="{code}"', page)
                self.assertIn(f'id="section-{code}"', page)
        self.assertIn('class="menu-reglages-titre"', page)
        self.assertIn('aria-expanded="false"', page)
        # Niveau 2 : les sous-parties, une section chacune.
        # ⚠ Plus de « creneaux » : la sous-partie a été retirée le
        # 03/08/2026 (les créneaux se calculent depuis l'agenda).
        for sous in ("identite", "appel", "relances", "remplacement",
                     "delais", "horaires", "jours-fermes",
                     "jeu-essai", "numero-essai", "essai-reel"):
            with self.subTest(sous=sous):
                self.assertIn(f'id="section-{sous}"', page)
        self.assertNotIn('id="section-creneaux"', page)
        # Les ancres d'avant la refonte existent toujours : les liens posés
        # ailleurs dans le produit continuent de mener quelque part.
        for ancre in ("jeu-essai", "numero-essai", "essai-reel", "delais"):
            with self.subTest(ancre=ancre):
                self.assertIn(f'id="{ancre}"', page)
        # Et AUCUN lien du produit ne vise une ancre qui n'existe plus : le
        # discours se désigne maintenant nature par nature.
        _, campagne = self._poster("/assistant/nature",
                                   {"nature": "creneau_libere"})
        self.assertIn("/reglages#discours-creneau_libere", campagne)
        self.assertIn('id="section-discours-creneau_libere"', page)

    def test_sans_javascript_toutes_les_sous_parties_restent_lisibles(self):
        """Le repli est ENTIER : le serveur ne masque rien, seul le script."""
