    def test_les_deux_fonds_sont_composes_a_l_identique(self):
        """La matière est du MÊME côté dans les deux images — c'est ce que
        « aligner le clair sur le sombre » veut dire, et c'est mesurable."""
        octets = {}
        for nom in ("fond-clair.jpg", "fond-sombre.jpg"):
            requete = urllib.request.Request(f"{self.racine}/image/{nom}")
            with urllib.request.urlopen(requete, timeout=8) as reponse:
                octets[nom] = reponse.read()
        # Même rapport de toile : les deux sont en 16:9 (la référence). On le
        # lit dans l'en-tête JPEG plutôt que de faire confiance au nom.
        for nom, donnees in octets.items():
            with self.subTest(nom=nom):
                largeur, hauteur = _taille_jpeg(donnees)
                self.assertEqual((largeur, hauteur), (1600, 900), nom)

