    def test_le_detail_des_relances_est_rempli_sans_rien_enregistrer(self):
        """Les champs étaient VIDES tant qu'on n'avait pas enregistré.

        Constaté par le propriétaire le 02/08/2026 : seule la nature qu'il
        avait enregistrée montrait un délai et un plafond. L'écran des
        Réglages ne lisait pas les réglages généraux de relance — encore
        deux écrans, deux vérités.
        """
        _, page = self._obtenir("/reglages")
        delai, maximum = campagnes.parametres_relance(
            self.application.preferences)
        for nature in assistant.NATURES:
            with self.subTest(nature=nature):
                bloc = page.split(f'id="section-comportement-{nature}"')[1]
                bloc = bloc.split("</section>")[0]
                # On lit la VALEUR du champ, sans dépendre de l'indentation
                # du gabarit : un essai qui casse sur un retour à la ligne ne
                # protège rien.
                for champ, attendu in (("relance_delai", delai),
                                       ("relance_max", maximum)):
                    trouve = re.search(
                        rf'name="{champ}"[^>]*?value="([^"]*)"', bloc, re.S)
                    self.assertIsNotNone(trouve, f"{champ} absent")
                    self.assertEqual(trouve.group(1), str(attendu))

    def test_le_plafond_de_rappels_part_a_un(self):
        """Un rappel par défaut, pas trois (décision du 02/08/2026)."""
        self.assertEqual(campagnes.RELANCE_MAX_DEFAUT, 1)
        preferences = generation.Preferences()
        self.assertEqual(campagnes.parametres_relance(preferences)[1], 1)
        # Un réglage qui vaut l'ANCIEN défaut est repris : sans cela, une
        # installation existante aurait continué d'appeler trois fois.
        preferences.definir(campagnes.CLE_RELANCE_MAX, 3)
        self.assertTrue(
            campagnes.reprendre_ancien_plafond_de_relances(preferences))
        self.assertEqual(campagnes.parametres_relance(preferences)[1], 1)
        # Un plafond VOULU, lui, est respecté — on ne décide pas à sa place.
        preferences.definir(campagnes.CLE_RELANCE_MAX, 5)
        self.assertFalse(
            campagnes.reprendre_ancien_plafond_de_relances(preferences))
        self.assertEqual(campagnes.parametres_relance(preferences)[1], 5)

    def test_la_politique_de_lancien_defaut_du_deplacement_est_reprise(self):
        """Le réglage écrit par l'ANCIEN défaut ne doit pas survivre.

        Constaté le 17/08/2026 sur SON fichier : le déplacement portait
        « politique: premier_oui », écrit par l'écran des Réglages en même
        temps que son créneau de rappel. Quand la règle du déplacement a été
        corrigée — tout le monde est appelé — ce réglage a continué d'imposer
        l'ancienne. Sa campagne s'arrêtait donc au premier contact, et la
        correction lui était INVISIBLE. Même mécanique que le plafond de
        rappels ci-dessus, même remède.
        """
        preferences = generation.Preferences()
        preferences.definir(campagnes.CLE_COMPORTEMENT_DEPLACEMENT,
                            {"politique": campagnes.ANCIENNE_POLITIQUE_DEPLACEMENT,
                             "relance_creneau_debut": "12:00"})
        self.assertTrue(
            campagnes.reprendre_ancienne_politique_de_deplacement(preferences))
        _, politique, _ = assistant.comportement_regle("deplacement",
                                                       preferences)
        self.assertEqual(politique, assistant.NATURES["deplacement"]["politique"])
        # Le RESTE du réglage survit : on ne jette pas son créneau de rappel
        # au prétexte de corriger une autre clé.
        garde = preferences.obtenir(campagnes.CLE_COMPORTEMENT_DEPLACEMENT)
        self.assertEqual(garde.get("relance_creneau_debut"), "12:00")
        # Une politique VOULUE, elle, est respectée — on ne décide pas à sa
        # place, et un deuxième passage ne fait plus rien.
        preferences.definir(campagnes.CLE_COMPORTEMENT_DEPLACEMENT,
                            {"politique": "premier_oui_par_place"})
        self.assertFalse(
            campagnes.reprendre_ancienne_politique_de_deplacement(preferences))

    def test_un_reglage_egal_au_defaut_de_la_nature_nest_pas_ecrit(self):
        """Régler ses relances ne doit pas figer la politique AFFICHÉE.

        C'est la cause de fond : l'écran enregistre tout son bloc, donc le
        champ qu'on n'a pas touché s'écrivait quand même — avec la valeur du
        défaut d'alors. Un défaut corrigé plus tard n'atteignait plus
        personne. Une valeur égale au défaut n'est pas un choix : c'est le
        défaut, et on ne l'écrit pas.
        """
        for nature in ("deplacement", "creneau_libere"):
            with self.subTest(nature=nature):
                definition = assistant.NATURES[nature]
                self._poster("/reglages/comportement", {
                    "nature": nature,
                    "politique": definition["politique"],
                    "ordre": definition.get("ordre_defaut") or "liste",
                    "relance_creneau_debut": "12:00",
                    "relance_creneau_fin": "14:00"})
                regle = self.application.preferences.obtenir(
                    assistant.cle_comportement(nature)) or {}
                # Ce qu'il a vraiment saisi est enregistré — c'est aussi la
                # preuve que l'envoi n'a pas été refusé en silence.
                self.assertEqual(regle.get("relance_creneau_debut"), "12:00")
                self.assertNotIn("politique", regle)
                self.assertNotIn("ordre", regle)

    def test_la_campagne_porte_le_stock_du_nombre_reel_et_nomme_une_date(self):
        """⚠ SON CONSTAT DU 17/08/2026 : « j'ai fait un essai de décalage de 11
        rendez-vous et j'ai seulement 19 créneaux pour négocier ».

        Le calcul, lui, rendait bien 77 places — mesuré sur sa base. Le nombre
        n'arrivait pas jusqu'au CHAMP : le pré-remplissage de l'étape 2 a lieu
        avant l'étape 3, quand la liste des gens n'existe pas encore. Un chiffre
        juste que personne ne voit ne vaut rien.

        ⚠ ET CET ESSAI MESURAIT LE STOCK AU MAUVAIS ENDROIT — corrigé le
        17/08/2026 au soir. Il le comptait dans le MESSAGE, alors que sa règle
        du 16/08 dit exactement l'inverse, deux fois : « l'ouverture nomme UNE
        date, la plus proche ; la liste devient le STOCK dans lequel l'agent
        puise pour négocier — elle reste dans "ce que tu sais", jamais
        récitée », et, dans la conduite de l'agent : « une seule date, pas la
        liste ». L'intitulé du champ le dit aussi : « stock, NON RÉCITÉ ».

        L'essai passait au vert parce qu'un défaut l'y mettait : le
        rafraîchissement écrivait le stock dans « créneau le plus proche », qui
        est la seule des deux à entrer dans le message. Mesuré sur sa journée
        du 18/08 : le champ « Créneau proposé en premier » portait 1 842
        caractères et 77 dates, et l'aperçu du message récitait ce catalogue.
        Un essai vert ne prouve pas que le produit marche.

        On mesure donc chacun À SA PLACE : le stock dans le stock, la date
        d'ouverture dans le message.
        """
        base, preferences = self.application.base, self.application.preferences
        horaires.definir_semaine(preferences,
                                 {jour: [(8 * 60, 12 * 60), (14 * 60, 18 * 60)]
                                  for jour in range(5)})
        # ⚠ UNE JOURNÉE PROCHE, ET C'EST INDISPENSABLE. Ma première version la
        # plaçait à quarante jours : le stock, qui prend le proche d'abord,
        # n'allait jamais jusque-là — l'essai passait au vert MÊME SANS
        # l'exclusion par journée. Il ne prouvait donc rien de ce qu'il annonce.
        # À trois jours, cette journée est en pleine zone de choix : si elle
        # apparaît, c'est un vrai défaut.
        journee_videe = datetime.date.today() + datetime.timedelta(days=3)
        while journee_videe.weekday() >= 5:      # la semaine type ouvre lun-ven
            journee_videe += datetime.timedelta(days=1)
        # ONZE personnes, comme lui, chacune avec son rendez-vous à sortir.
        lignes = []
        for rang in range(11):
            quand = datetime.datetime.combine(
                journee_videe,
                datetime.time(hour=8 + rang // 2,
                              minute=0 if rang % 2 == 0 else 30))
            numero = f"+33 6 00 00 00 {40 + rang:02d}"
            base.ajouter_client(f"M. Journee {rang:02d}", numero)
            lignes.append(f"M. Journee {rang:02d};{numero};"
                          f"{quand.isoformat(timespec='minutes')};Séance")
        # ⚠ ON RENVOIE CE QUE LA PAGE AFFICHE, comme le navigateur : c'est le
        # stock CALCULÉ qu'on mesure ensuite. Sans cela l'essai postait
        # « mardi 9h00, mercredi 14h30 » — sa propre invention — et n'éprouvait
        # plus rien du calcul.
        campagne_id = self._campagne("deplacement", lignes,
                                     reprendre_les_calculs=True)
        campagne = base.obtenir_campagne(campagne_id)
        contacts = base.contacts_de_campagne(campagne_id)
        self.assertEqual(len(contacts), 11, "les onze ne sont pas tous chargés")

        # ⚠ ET LE CHAMP DE L'ÉTAPE 2 LE MONTRE, LUI AUSSI. Sa question du
        # 17/08/2026, capture à l'appui : « est-ce simplement un problème
        # d'affichage ? » Oui — mais cet affichage est un CHAMP : s'il y touche,
        # les dates montrées deviennent la liste définitive. Un champ qui montre
        # faux invite à figer le faux.
        _, page = self._poster("/assistant/nature", {"nature": "deplacement"})
        b = self._brouillon(page)
        formulaire = {"b": b, "action": "continuer", "ordre": "liste"}
        formulaire.update(self.INFOS["deplacement"])
        for code in self.CHAMPS_CALCULES:      # comme le navigateur
            valeur = self._valeur_affichee(page, code)
            if valeur is not None:
                formulaire[code] = valeur
        self._poster("/assistant/message", formulaire)
        self._poster("/assistant/importer",
                     {"b": b, "mode": "collage", "liste": "\n".join(lignes)})
        # On REVIENT à l'étape 2, comme lui : les onze sont chargés.
        _, page = self._obtenir(f"/assistant/message?b={b}")
        vues = set(MOTIF_DATE_PARLEE.findall(page))
        self.assertGreaterEqual(
            len(vues), 11 * horaires.PAR_RENDEZVOUS_A_DEPLACER,
            f"l'étape 2 n'affiche que {len(vues)} dates")

        # ⚠ ET AUCUNE DATE NE TOMBE SUR LA JOURNÉE QU'ON VIDE (sa règle du
        # 17/08/2026) : « cela a sélectionné des créneaux durant la journée que
        # je veux annuler ». Le praticien n'est pas là ce jour-là : même les
        # trous de cette journée sont hors jeu, pas seulement les heures des
        # onze rendez-vous.
        journee = jour_parle(journee_videe)
        self.assertFalse([d for d in vues if journee in d],
                         f"des places du {journee} sont proposées")

        # LE CŒUR ① : le STOCK enregistré porte bien le nombre réel.
        configuration = assistant.configuration_campagne(campagne)
        stock = configuration["infos"]["creneaux_remplacement"]
        dates = MOTIF_DATE_PARLEE.findall(stock)
        self.assertFalse([d for d in dates if journee in d],
                         f"le stock contient des places du {journee}")
        attendu = 11 * horaires.PAR_RENDEZVOUS_A_DEPLACER
        self.assertGreaterEqual(
            len(set(dates)), attendu,
            f"le stock ne porte que {len(set(dates))} dates sur {attendu}")
        # Et elles restent étalées : plusieurs jours, matin ET après-midi.
        # ⚠ RELU PAR LE LECTEUR DU PRODUIT (`themes.lire_date`) : c'est lui
        # qui ramène au format du calendrier ce que l'agent rend au téléphone.
        # L'essai éprouve donc aussi que ce qu'on ÉCRIT, on sait le RELIRE.
        quand = [datetime.datetime.fromisoformat(themes.lire_date(d))
                 for d in set(dates)]
        self.assertGreaterEqual(len({q.date() for q in quand}), 7)
        self.assertTrue([q for q in quand
                         if q.hour < horaires.HEURE_BASCULE_MIDI])
        self.assertTrue([q for q in quand
                         if q.hour >= horaires.HEURE_BASCULE_MIDI])

        # LE CŒUR ② : le MESSAGE, lui, ne nomme QU'UNE date — sa règle du
        # 16/08. C'est ce contrôle-là qui manquait : sans lui, rien n'empêchait
        # le catalogue de revenir dans le message, et rien ne l'a empêché.
        annoncees = MOTIF_DATE_PARLEE.findall(campagne["mission"])
        self.assertEqual(
            len(annoncees), 1,
            f"le message d'ouverture récite {len(annoncees)} dates au lieu "
            "d'une seule")
        self.assertNotIn(journee, annoncees[0])
        # La date nommée est la PREMIÈRE du stock : on ouvre sur la plus
        # proche, pas sur une autre — deux calculs qui divergeraient feraient
        # dire à l'agent une date que le stock ne contient pas.
        self.assertEqual(annoncees[0], dates[0])
        # Et le stock n'entre PAS dans le message : il vit dans « ce que tu
        # sais » de la consigne, jamais dans ce qui est dit mot pour mot.
        self.assertNotIn(stock, campagne["mission"])
        contexte = assistant.construire_consigne(
            "deplacement", configuration["infos"], preferences,
            configuration["options"]).texte_contexte()
        self.assertIn(stock, contexte)

    def test_une_liste_de_creneaux_par_duree_de_rendez_vous(self):
        """⚠ SA RÈGLE DU 17/08/2026 : « on prévoit des créneaux de durée
        équivalente aux durées de rendez-vous que l'on souhaite annuler. Il faut
        donc faire plusieurs listes de proposition en fonction de la durée ».

        MESURÉ SUR SA JOURNÉE DU 18/08 : dix rendez-vous de 20 minutes et un de
        40. Un trou de 20 minutes ne peut pas recevoir une séance de 40 — le
        message n'annonçait que la liste des 20, et la personne de 40 s'entendait
        proposer des heures où son rendez-vous ne tient pas.
        """
        base, preferences = self.application.base, self.application.preferences
        horaires.definir_semaine(preferences,
                                 {jour: [(8 * 60, 12 * 60), (14 * 60, 18 * 60)]
                                  for jour in range(5)})
        pas = horaires.pas_minutes(preferences)
        jour = datetime.date.today() + datetime.timedelta(days=3)
        while jour.weekday() >= 5:
            jour += datetime.timedelta(days=1)
        # ⚠ ON VIDE LE JEU DE DÉMONSTRATION DE CETTE JOURNÉE : cet essai compte
        # des rendez-vous, et le jeu d'essai en pose déjà.
        for rdv in base.tous_les_rendezvous():
            if rdv["horaire"][:10] == jour.isoformat():
                base.mettre_a_jour_rendezvous(rdv["id"], statut="ignoré")
        # QUATRE de la durée simple, DEUX du double : deux listes attendues.
        attendus, rang = {1: 4, 2: 2}, 0
        for tranches, combien in attendus.items():
            for _ in range(combien):
                quand = datetime.datetime.combine(
                    jour, datetime.time(hour=8 + rang, minute=0))
                client = base.ajouter_client(f"M. Duree {rang:02d}",
                                             f"+33 6 00 00 00 {60 + rang:02d}")
                base.ajouter_rendezvous(
                    client, quand.isoformat(timespec="minutes"), "Séance",
                    duree_tranches=tranches)
                rang += 1
        # ⚠ SON GESTE, PAS UN COLLAGE. Une ligne collée n'est liée à AUCUN
        # rendez-vous : sa durée est donc illisible, et tous les contacts
        # ressortent à une tranche. Mon premier montage passait par là et ne
        # produisait qu'une seule liste — il n'éprouvait pas la règle.
        _, page = self._poster("/assistant/nature", {"nature": "deplacement"})
        b = self._brouillon(page)
        formulaire = {"b": b, "action": "continuer", "ordre": "liste"}
        formulaire.update(self.INFOS["deplacement"])
        for code in self.CHAMPS_CALCULES:      # comme le navigateur
            valeur = self._valeur_affichee(page, code)
            if valeur is not None:
                formulaire[code] = valeur
        self._poster("/assistant/message", formulaire)
        annee, semaine, _ = jour.isocalendar()
        self._poster("/assistant/importer",
                     {"b": b, "mode": "rendezvous", "source": "a_venir",
                      "annee": str(annee), "semaine": str(semaine),
                      "jour": jour.isoformat()})
        self.assertEqual(
            len(self.application.obtenir_brouillon_assistant(b)["contacts"]), 6,
            "les six rendez-vous de la journée ne sont pas tous chargés")
        self._poster("/assistant/liste", {"b": b, "action": "valider"})
        campagne = base.lister_campagnes()[0]
        # ⚠ LE STOCK, PAS LE MESSAGE — corrigé le 17/08/2026 au soir. Cet essai
        # cherchait ses deux listes dans le message d'ouverture, que sa règle
        # du 16/08 veut au contraire limité à UNE date (« pas la liste »). Il
        # ne passait que parce que le rafraîchissement écrasait « créneau le
        # plus proche » avec le stock. La règle éprouvée ici reste la sienne —
        # une liste par durée — mais elle se mesure là où le stock vit.
        stock = assistant.configuration_campagne(
            campagne)["infos"]["creneaux_remplacement"]

        # UNE ÉTIQUETTE PAR DURÉE, en minutes et en toutes lettres : c'est
        # l'agent qui lit ce texte, « 2 tranches » ne veut rien dire au
        # téléphone.
        for tranches, combien in attendus.items():
            etiquette = f"pour un rendez-vous de {tranches * pas} minutes : "
            self.assertIn(etiquette, stock)
            bloc = stock.split(etiquette, 1)[1].split(" ; ")[0]
            dates = set(MOTIF_DATE_PARLEE.findall(bloc))
            self.assertEqual(len(dates),
                             combien * horaires.PAR_RENDEZVOUS_A_DEPLACER,
                             f"la liste des {tranches * pas} minutes est fausse")
            # ⚠ ET CHAQUE DATE TIENT VRAIMENT CETTE DURÉE. Compter ne suffit
            # pas : une liste du bon nombre mais des mauvaises heures serait
            # exactement le défaut qu'on corrige.
            tiennent = set(horaires.places_negociables(
                base, preferences, tranches=tranches,
                a_deplacer=combien, sauf_jours=(jour.isoformat(),)))
            for date in dates:
                # ⚠ RELU PAR LE LECTEUR DU PRODUIT : ce qu'on ÉCRIT, on doit
                # savoir le RELIRE — c'est tout l'objet de `lire_date`.
                self.assertIn(themes.lire_date(date), tiennent,
                              f"{date} ne tient pas {tranches * pas} minutes")
        # Et le message, lui, ne récite aucune de ces listes : une seule date.
        annoncees = MOTIF_DATE_PARLEE.findall(campagne["mission"])
        self.assertEqual(len(annoncees), 1)
        # ⚠ ET C'EST LA DURÉE LA PLUS LONGUE QUI COMMANDE cette date : une
        # place qui reçoit une séance de 40 minutes en reçoit une de 20,
        # l'inverse est faux. Ouvrir sur une place trop courte, c'est promettre
        # au téléphone une heure où le rendez-vous ne tient pas.
        plus_longue = max(attendus)
        self.assertEqual(
            annoncees[0],
            horaires.creneau_le_plus_proche(
                base, preferences, tranches=plus_longue,
                sauf_jours=(jour.isoformat(),)),
            "la date d'ouverture ne tient pas la plus longue des durées")

    def test_le_panneau_avant_de_demarrer_annonce_ce_qui_sera_dit(self):
        """⚠ LE SEUL ÉCRAN FAIT POUR QU'IL VÉRIFIE — et il montrait faux.

        Mesuré le 17/08/2026 sur sa campagne du 18/08 : « Les premières places
        qu'il annoncera : le 18/08/2026 à 09h00, le 18/08/2026 à 09h40, le
        18/08/2026 à 10h20 » — trois places du jour même qu'il était en train
        de vider —, alors que le stock de la campagne commençait bien au 19/08.
        Deux calculs, deux vérités, sur l'écran qui lui demande justement de
        comparer ces dates à son vrai planning avant de laisser partir les
        appels.

        Le paragraphe du code promettait déjà « la MÊME source que les créneaux
        annoncés au téléphone, jamais un autre calcul » : la promesse était là,
        l'appel ne la tenait pas (ni les journées vidées, ni les places
        libérées, ni les durées).
        """
        base, preferences = self.application.base, self.application.preferences
        horaires.definir_semaine(preferences,
                                 {jour: [(8 * 60, 12 * 60), (14 * 60, 18 * 60)]
                                  for jour in range(5)})
        # ⚠ LA JOURNÉE VIDÉE EST LA PREMIÈRE PROPOSABLE — DEMAIN, comme son
        # 18/08. C'est ce qui donne sa force à l'essai : les places libres de
        # cette journée-là sont, par construction, les toutes premières de la
        # liste. Si le panneau les écarte vraiment, elles n'apparaissent pas ;
        # s'il ne les écarte pas, elles arrivent en tête. Une journée placée
        # plus loin laisserait les jours d'avant occuper les trois premières
        # places, et l'essai passerait au vert SANS le correctif — il ne
        # prouverait rien.
        journee_videe = datetime.date.today() + datetime.timedelta(days=1)
        while journee_videe.weekday() >= 5:      # la semaine type ouvre lun-ven
            journee_videe += datetime.timedelta(days=1)
        for rdv in base.tous_les_rendezvous():
            if rdv["horaire"][:10] == journee_videe.isoformat():
                base.mettre_a_jour_rendezvous(rdv["id"], statut="ignoré")
        lignes = []
        for rang in range(6):
            quand = datetime.datetime.combine(
                journee_videe, datetime.time(hour=8 + rang, minute=0))
            numero = f"+33 6 00 00 00 {40 + rang:02d}"
            client = base.ajouter_client(f"M. Videe {rang:02d}", numero)
            base.ajouter_rendezvous(client, quand.isoformat(timespec="minutes"),
                                    "Séance", statut="prévu")
            lignes.append(f"M. Videe {rang:02d};{numero};"
                          f"{quand.isoformat(timespec='minutes')};Séance")
        campagne_id = self._campagne("deplacement", lignes,
                                     reprendre_les_calculs=True)
        campagne = base.obtenir_campagne(campagne_id)
        faits = assistant.verification_agenda(base, preferences, campagne)

        # ① AUCUNE PLACE DE LA JOURNÉE QU'ON VIDE, ni dans les dates annoncées…
        journee = jour_parle(journee_videe)
        self.assertTrue(faits["prochaines"], "le panneau n'annonce rien")
        self.assertNotIn(journee, faits["prochaines"],
                         "le panneau annonce des places du jour qu'on vide")
        # … ni dans le compte qui les accompagne (« c'est là-dedans que l'agent
        # puisera » : une place qu'il ne puisera jamais n'a rien à y faire).
        proposables = horaires.creneaux_proposables(base, preferences)
        du_jour = [e for e in proposables
                   if not e["occupe"]
                   and e["horaire"][:10] == journee_videe.isoformat()]
        self.assertTrue(du_jour, "l'essai ne prouve rien : ce jour n'a "
                                 "aucune place libre à écarter")
        libres = len([e for e in proposables if not e["occupe"]])
        self.assertEqual(faits["places"], libres - len(du_jour))

        # ② ET CE SONT BIEN LES PREMIÈRES DU STOCK — le même calcul que le
        # message, pas un second qui pourrait diverger.
        stock = assistant.configuration_campagne(
            campagne)["infos"]["creneaux_remplacement"]
        premieres = MOTIF_DATE_PARLEE.findall(faits["prochaines"])
        self.assertTrue(premieres)
        for date in premieres:
            with self.subTest(date=date):
                self.assertIn(date, stock,
                              "le panneau annonce une date que la campagne "
                              "n'a pas en stock")

    def test_les_deux_facons_d_accepter_deplacent_la_ligne_de_la_meme_facon(self):
        """⚠ SON CONSTAT DU 17/08/2026, défaut n° 4 : « le premier rendez-vous
        n'a pas été annulé, mais on l'a bien ajouté pour le lendemain ».

        Au téléphone, un client peut accepter de DEUX manières : prendre le
        créneau qu'on lui propose (l'agent rend « confirmed »), ou convenir
        d'une autre date (« rescheduled »). L'écran écrit « ✅ accepté » dans les
        deux cas — mais l'agenda, lui, écrivait deux choses différentes : l'une
        déplaçait la ligne, l'autre la laissait sur la journée en « déplacé » et
        en créait une SECONDE ailleurs.

        MESURÉ SUR SA JOURNÉE DU 18/08 : sur onze personnes, quatre lignes
        partaient proprement et deux restaient. Sa journée ne se vidait qu'à
        moitié dans les archives et sur les fiches de ses clients.

        La règle éprouvée ici est la SIENNE, du 14/08/2026 : « tu déplaces un
        rendez-vous d'une date à une autre, c'est ultra simple ». Elle était
        déjà écrite dans deux chemins sur quatre — c'est la demi-correction qui
        la fait revenir sous un autre nom.
        """
        base, preferences = self.application.base, self.application.preferences
        horaires.definir_semaine(preferences,
                                 {jour: [(8 * 60, 12 * 60), (14 * 60, 18 * 60)]
                                  for jour in range(5)})
        journee = datetime.date.today() + datetime.timedelta(days=1)
        while journee.weekday() >= 5:
            journee += datetime.timedelta(days=1)
        for rdv in base.tous_les_rendezvous():
            if rdv["horaire"][:10] == journee.isoformat():
                base.mettre_a_jour_rendezvous(rdv["id"], statut="ignoré")
        # ONZE personnes, comme sa journée : assez pour que le simulateur joue
        # ses deux façons d'accepter.
        lignes, avant = [], {}
        for rang in range(11):
            quand = datetime.datetime.combine(
                journee, datetime.time(hour=8 + rang // 2,
                                       minute=0 if rang % 2 == 0 else 30))
            nom = f"M. Deux Facons {rang:02d}"
            numero = f"+33 6 00 00 00 {40 + rang:02d}"
            client = base.ajouter_client(nom, numero)
            base.ajouter_rendezvous(client, quand.isoformat(timespec="minutes"),
                                    "Séance", statut="prévu")
            avant[nom] = quand.isoformat(timespec="minutes")
            lignes.append(f"{nom};{numero};"
                          f"{quand.isoformat(timespec='minutes')};Séance")
        campagne_id = self._campagne("deplacement", lignes,
                                     reprendre_les_calculs=True)
        etats = self._derouler(campagne_id)

        # ⚠ D'ABORD : LES DEUX FAÇONS ONT-ELLES ÉTÉ JOUÉES ? Sans les deux,
        # l'essai ne compare rien et passerait au vert sans rien prouver.
        issues = collections.Counter(c["issue"] for c in etats.values())
        for facon in ("confirmed", "rescheduled"):
            self.assertTrue(issues[facon],
                            f"le simulateur n'a joué aucun « {facon} » : "
                            "cet essai ne compare rien")

        for nom, contact in etats.items():
            if contact["issue"] not in ("confirmed", "rescheduled"):
                continue
            with self.subTest(nom=nom, facon=contact["issue"]):
                siens = [r for r in base.tous_les_rendezvous()
                         if r["nom"] == nom]
                # UNE SEULE LIGNE, quelle que soit la façon d'accepter.
                self.assertEqual(len(siens), 1,
                                 f"{len(siens)} lignes pour un déplacement")
                # Elle a bougé, et elle porte l'accord obtenu.
                self.assertEqual(siens[0]["statut"], "confirmé")
                self.assertNotEqual(siens[0]["horaire"], avant[nom])
                # Et elle a quitté la journée qu'on vide.
                self.assertNotEqual(siens[0]["horaire"][:10],
                                    journee.isoformat())

        # ⚠ PLUS PERSONNE N'EST « déplacé » : ce mot désigne, partout ailleurs,
        # quelqu'un dont le rendez-vous a bougé SANS nouvelle date — donc qui
        # ATTEND qu'on lui en trouve une (db.STATUTS_A_RECASER, et
        # etats_clients : « déplacement en attente : lui trouver la nouvelle
        # date »). L'écrire sur quelqu'un qui VIENT d'obtenir une date le
        # rangeait parmi ceux à qui il faut en trouver une.
        restes = [r for r in base.tous_les_rendezvous()
                  if r["statut"] == "déplacé" and r["nom"].startswith("M. Deux")]
        self.assertEqual(restes, [])

        # ET LE CAHIER PORTE UNE SEULE LIGNE ↔ PAR PERSONNE DÉPLACÉE, avec les
        # deux dates : c'est LUI qui garde l'histoire de la journée.
        cahier = [c for c in base.changements_de_campagne(campagne_id)
                  if c["genre"] == "deplacement"]
        self.assertEqual(len(cahier),
                         issues["confirmed"] + issues["rescheduled"])
        for ligne in cahier:
            with self.subTest(qui=ligne["nom"]):
                self.assertEqual(ligne["ancienne_date"], avant[ligne["nom"]])
                self.assertTrue(ligne["nouvelle_date"])

    def test_une_place_liberee_sur_la_journee_videe_n_est_jamais_a_remplir(self):
        """⚠ SON DÉFAUT N° 6 DU 18/08/2026, mais pas pour la raison qu'il
        semblait avoir.

        Quand un client annule pendant l'appel, sa place se libère et RingBack
        PROPOSE une campagne « créneau libéré » pour la remplir — au-delà du
        seuil de remplacement (⚙ Réglages). Son seuil à lui étant réglé à 72 h,
        rien ne se proposait jamais sur une journée du lendemain, et le panneau
        répétait « trop tard pour organiser un remplacement ».

        MESURÉ EN ABAISSANT LE SEUIL sur une copie de sa base : RingBack
        proposait alors « 📞 Préparer la campagne créneau libéré » sur le 18/08
        à 10h00 et à 15h40 — deux places de la journée que la campagne était en
        train de VIDER. On aurait appelé des gens pour leur offrir un
        rendez-vous un jour où personne n'est là. Le seuil masquait le défaut,
        il ne le corrigeait pas.

        La règle est déjà écrite ailleurs (`assistant.jours_a_vider`, sa demande
        du 17/08) : « si le praticien n'est pas là ce jour-là, aucune heure de
        ce jour-là n'est proposable ». Elle valait pour les créneaux annoncés au
        téléphone ; ce panneau ne la tenait pas.
        """
        base, preferences = self.application.base, self.application.preferences
        horaires.definir_semaine(preferences,
                                 {jour: [(8 * 60, 12 * 60), (14 * 60, 18 * 60)]
                                  for jour in range(5)})
        # ⚠ SEUIL AU MINIMUM : sans cela, les annulations de la journée du
        # lendemain restent « annulé » et rien n'est proposé — l'essai passerait
        # au vert sans éprouver la règle. C'est exactement ce que son réglage à
        # 72 h faisait au produit.
        preferences.definir(horaires.CLE_SEUIL_REMPLACEMENT, "1")
        journee = datetime.date.today() + datetime.timedelta(days=1)
        while journee.weekday() >= 5:
            journee += datetime.timedelta(days=1)
        for rdv in base.tous_les_rendezvous():
            if rdv["horaire"][:10] == journee.isoformat():
                base.mettre_a_jour_rendezvous(rdv["id"], statut="ignoré")
        lignes = []
        for rang in range(11):
            quand = datetime.datetime.combine(
                journee, datetime.time(hour=8 + rang // 2,
                                       minute=0 if rang % 2 == 0 else 30))
            nom = f"M. Videur {rang:02d}"
            numero = f"+33 6 00 00 00 {40 + rang:02d}"
            client = base.ajouter_client(nom, numero)
            base.ajouter_rendezvous(client, quand.isoformat(timespec="minutes"),
                                    "Séance", statut="prévu")
            lignes.append(f"{nom};{numero};"
                          f"{quand.isoformat(timespec='minutes')};Séance")
        campagne_id = self._campagne("deplacement", lignes,
                                     reprendre_les_calculs=True)
        self._derouler(campagne_id)

        # ⚠ Y A-T-IL SEULEMENT UNE PLACE LIBÉRÉE SUR CETTE JOURNÉE ? Sans elle,
        # l'essai ne prouve rien : il faut qu'au moins un client ait annulé.
        liberees = [r for r in base.tous_les_rendezvous()
                    if r["horaire"][:10] == journee.isoformat()
                    and r["statut"] == db.STATUT_SUPPRIME]
        self.assertTrue(liberees, "aucune place libérée sur la journée vidée : "
                                  "cet essai ne prouve rien")

        _, page = self._obtenir(f"/campagne?id={campagne_id}")
        # LE CŒUR : aucune de ces places n'est proposée à remplir.
        proposees = set(re.findall(
            r'name="creneau" value="([^"]+)"', page))
        for place in liberees:
            with self.subTest(place=place["horaire"]):
                self.assertNotIn(
                    place["horaire"], proposees,
                    "RingBack propose de remplir une place de la journée "
                    "qu'il est en train de vider")
        # ⚠ ET IL LE DIT, plutôt que de faire disparaître le panneau en
        # silence : une place qui se libère est un fait, même quand il n'y a
        # rien à en faire.
        self.assertIn("que cette campagne est justement en train de vider",
                      page)

    def test_le_nom_de_la_campagne_dit_la_journee_qu_elle_traite(self):
        """⚠ SON DÉFAUT N° 8 DU 18/08/2026 : « Déplacement de rendez-vous
        (11 contact(s)) — 17/08 ». Le 17/08 est la date de CRÉATION, pas la
        journée traitée.

        Avec 91 campagnes terminées dans sa liste, rien ne permettait de
        retrouver « celle du 18/08 » — celle qui avait vidé sa journée. La règle
        existait pourtant, pour un seul thème : « Créneau libéré **du 03/08
        14h** — 28/07 » porte bien sa date concernée.

        Elle vaut pour TOUTES les campagnes nées d'une plage du planning : ce
        sont des rendez-vous datés qu'elles traitent. Une seule règle, sinon la
        moitié des campagnes reste introuvable.
        """
        base, preferences = self.application.base, self.application.preferences
        horaires.definir_semaine(preferences,
                                 {jour: [(8 * 60, 12 * 60), (14 * 60, 18 * 60)]
                                  for jour in range(5)})
        journee = datetime.date.today() + datetime.timedelta(days=1)
        while journee.weekday() >= 5:
            journee += datetime.timedelta(days=1)
        lignes = []
        for rang in range(3):
            quand = datetime.datetime.combine(
                journee, datetime.time(hour=9 + rang, minute=0))
            nom = f"M. Nomme {rang:02d}"
            numero = f"+33 6 00 00 00 {70 + rang:02d}"
            client = base.ajouter_client(nom, numero)
            base.ajouter_rendezvous(client, quand.isoformat(timespec="minutes"),
                                    "Séance", statut="prévu")
            lignes.append(f"{nom};{numero};"
                          f"{quand.isoformat(timespec='minutes')};Séance")
        attendu = f"{journee:%d/%m}"
        # LES TROIS NATURES QUI PARTENT D'UNE PLAGE, pas seulement celle du
        # défaut : corriger la seule signalée laisserait les deux autres
        # introuvables, et le même reproche reviendrait sous un autre nom.
        for nature in ("deplacement", "rappel_rdv", "confirmation"):
            with self.subTest(nature=nature):
                campagne_id = self._campagne(nature, lignes)
                nom = base.obtenir_campagne(campagne_id)["nom"]
                self.assertIn(f"du {attendu}", nom,
                              f"le nom ne dit pas la journée traitée : « {nom} »")
                # Et il dit toujours combien de personnes, et quand il l'a créée.
                self.assertIn("3 contact(s)", nom)
        # ⚠ ET UNE NATURE SANS RENDEZ-VOUS PAR CONTACT N'INVENTE AUCUNE DATE :
        # une prise de rendez-vous n'en a pas encore. Sans cette contre-épreuve,
        # une règle qui nommerait TOUJOURS une journée passerait au vert.
        colles = [f"Mme Sans Rdv {r};+33 6 00 00 00 8{r}" for r in range(2)]
        campagne_id = self._campagne("prise_rdv", colles)
        nom = base.obtenir_campagne(campagne_id)["nom"]
        self.assertNotIn(" du ", nom, f"une journée inventée : « {nom} »")

    def test_une_information_que_le_texte_retape_ne_dit_plus_est_annoncee(self):
        """⚠ SON DÉFAUT N° 10 DU 18/08/2026 — le plus sournois de la liste.

        SON GESTE, dans l'ordre où il l'a fait : retaper le message à l'étape 2,
        PUIS remplir la raison. La valeur est enregistrée dans la campagne,
        l'écran la montre remplie… et l'agent ne la dit jamais, parce qu'un
        message récrit à la main part mot pour mot. Rien ne le signalait.

        ⚠ ON NE RÉÉCRIT PAS SON TEXTE : y réinjecter la phrase serait pire que
        le silence — ce serait modifier ce qu'un humain a décidé de dire. On le
        DIT, à l'étape 2 ET sur la fiche de la campagne (il quitte l'étape 2
        sans y revenir : c'est devant ▶ Démarrer qu'il faut qu'il le voie).
        """
        base = self.application.base
        _, page = self._poster("/assistant/nature", {"nature": "deplacement"})
        b = self._brouillon(page)
        formulaire = {"b": b, "action": "continuer", "ordre": "liste"}
        formulaire.update(self.INFOS["deplacement"])
        for code in self.CHAMPS_CALCULES:
            valeur = self._valeur_affichee(page, code)
            if valeur is not None:
                formulaire[code] = valeur
        # ① IL RETAPE LE MESSAGE — sans la raison, qu'il n'a pas encore saisie.
        formulaire["info_raison"] = ""
        formulaire["mission"] = ("Bonjour [identite], ici le Cabinet Essai. "
                                 "Nous devons déplacer votre rendez-vous du "
                                 "[rdv_existant]. Cela vous irait-il ?")
        formulaire["mission_editee"] = "1"
        self._poster("/assistant/message", formulaire)
        # ② PUIS il remplit la raison, et revient à l'étape 2.
        formulaire["info_raison"] = "un imprévu dans notre planning"
        self._poster("/assistant/message", formulaire)
        _, etape2 = self._obtenir(f"/assistant/message?b={b}")

        # L'ÉCRAN LE DIT, et il nomme l'information et sa valeur.
        self.assertIn("ne dit pas cette information", etape2)
        self.assertIn("un imprévu dans notre planning", etape2)
        self.assertIn("PAS dite", etape2)
        # Et il dit quoi faire, sans rien réécrire à sa place.
        self.assertIn("part mot pour mot", etape2)

        # ⚠ ET SUR LA FICHE DE LA CAMPAGNE, l'écran d'avant ▶ Démarrer : c'est
        # celui-là qu'il regarde, l'étape 2 est déjà derrière lui.
        self._poster("/assistant/importer",
                     {"b": b, "mode": "collage",
                      "liste": "M. Un;+33 6 00 00 00 51;"
                               f"{DEMAIN};Séance"})
        self._poster("/assistant/liste", {"b": b, "action": "valider"})
        campagne_id = base.lister_campagnes()[0]["id"]
        _, fiche = self._obtenir(f"/campagne?id={campagne_id}")
        self.assertIn("ne dit pas cette information", fiche)
        self.assertIn("un imprévu dans notre planning", fiche)
        # La valeur EST bien enregistrée : c'est tout le sournois du défaut.
        configuration = assistant.configuration_campagne(
            base.obtenir_campagne(campagne_id))
        self.assertEqual(configuration["infos"]["raison"],
                         "un imprévu dans notre planning")
        self.assertNotIn("un imprévu dans notre planning",
                         base.obtenir_campagne(campagne_id)["mission"])

    def test_un_texte_qui_dit_tout_n_affiche_aucun_avertissement(self):
        """La contre-épreuve : sans elle, un avertissement affiché TOUJOURS
        passerait au vert lui aussi — et deviendrait un bruit qu'on n'lit plus."""
        _, page = self._poster("/assistant/nature", {"nature": "deplacement"})
        b = self._brouillon(page)
        formulaire = {"b": b, "action": "continuer", "ordre": "liste"}
        formulaire.update(self.INFOS["deplacement"])
        for code in self.CHAMPS_CALCULES:
            valeur = self._valeur_affichee(page, code)
            if valeur is not None:
                formulaire[code] = valeur
        self._poster("/assistant/message", formulaire)
        _, etape2 = self._obtenir(f"/assistant/message?b={b}")
        self.assertNotIn("ne dit pas cette information", etape2)
        self.assertNotIn("ne dit pas ces informations", etape2)

    def test_le_message_elide_devant_une_voyelle(self):
        """⚠ SON DÉFAUT N° 11 DU 18/08/2026, relevé mot pour mot dans une
        transcription : « En raison **de un** imprévu dans notre planning ».

        Le gabarit écrit « de [raison] », la valeur commence par une voyelle, et
        la substitution posait les deux bout à bout. C'est un texte qu'un agent
        LIT À VOIX HAUTE : une faute de liaison s'entend.
        """
        preferences = self.application.preferences
        pour = lambda raison: assistant.construire_mission(
            "deplacement", {"entreprise": "Cabinet Essai", "raison": raison},
            preferences, {})
        # Devant une voyelle : « de » s'élide.
        self.assertIn("En raison d'un imprévu",
                      pour("un imprévu dans notre planning"))
        self.assertIn("En raison d'une urgence", pour("une urgence"))
        self.assertNotIn("de un", pour("un imprévu dans notre planning"))
        # ⚠ DEVANT UNE CONSONNE, RIEN NE CHANGE : sans cette contre-épreuve,
        # une élision posée systématiquement dirait « d'travaux » et passerait
        # au vert sur le premier contrôle.
        self.assertIn("En raison de travaux", pour("travaux"))
        self.assertIn("En raison de la maladie", pour("la maladie du praticien"))
        # ⚠ ET LE « h » N'EST PAS ÉLIDÉ, volontairement : le français en a deux
        # (muet « d'homme », aspiré « de haricot ») et rien dans une valeur
        # saisie ne dit lequel. On ne devine pas.
        self.assertIn("En raison de haute saison", pour("haute saison"))

    def test_l_elision_ne_coupe_pas_un_mot_qui_finit_par_de(self):
        """La borne à gauche : « une grande [raison] » ne doit pas devenir
        « une grand'urgence ». Le mot élidé doit être un mot ENTIER."""
        self.assertEqual(
            assistant._elider("une grande [raison] ici", "raison", "urgence"),
            "une grande urgence ici")
        # Et en tête de texte, où il n'y a pas d'espace devant.
        self.assertEqual(
            assistant._elider("De [raison] nous parlons", "raison", "une urgence"),
            "D'une urgence nous parlons")

    def _relance_sur_un_rendezvous(self, heure_rdv):
        """Un non-joint dont le rendez-vous est demain à cette heure-là.

        Le créneau de rappel est réglé 12h00-14h00 et l'appel a lieu ce soir :
        l'échéance calculée tombe donc DEMAIN À 12h00, quelle que soit l'heure
        du rendez-vous. C'est ce qui permet de mettre les deux côtés de la
        règle l'un à côté de l'autre.
        """
        base = self.application.base
        preferences = self.application.preferences
        horaires.definir_semaine(preferences,
                                 {jour: [(8 * 60, 19 * 60)] for jour in range(7)})
        preferences.definir(themes.CLE_PLAGE_DEBUT, "08:00")
        preferences.definir(themes.CLE_PLAGE_FIN, "19:00")
        demain = datetime.date.today() + datetime.timedelta(days=1)
        quand = datetime.datetime.combine(demain, heure_rdv)
        client = base.ajouter_client("Mme Relance", "+33 6 00 00 00 53")
        rdv = base.ajouter_rendezvous(client, quand.isoformat(timespec="minutes"),
                                      "Séance", statut="prévu")
        campagne = base.creer_campagne("Essai relance", "deplacement",
                                       mission="Bonjour.")
        contact = base.ajouter_contact_campagne(
            campagne, 1, "Mme Relance", "+33 6 00 00 00 53", rendezvous_id=rdv)
        assistant._apres_non_joint(
            base, preferences, base.obtenir_campagne(campagne),
            {"recontacter": True, "relance_mode": "creneau",
             "relance_creneau_debut": "12:00", "relance_creneau_fin": "14:00",
             "relance_max": 3},
            contact, "no_answer",
            maintenant=datetime.datetime.combine(datetime.date.today(),
                                                 datetime.time(18, 0)))
        return (base.obtenir_contact_campagne(contact),
                base.relances_de_campagne(campagne), campagne, quand)

    def test_aucune_relance_ne_sonne_apres_le_rendez_vous(self):
        """⚠ SON DÉFAUT N° 12 DU 18/08/2026, mesuré dans sa vraie forme.

        L'échéance d'une relance se calcule depuis MAINTENANT — délai en heures
        ouvrées, ou créneau de rappel quotidien — sans jamais regarder la date
        dont on veut parler à la personne.

        REPRODUIT : rendez-vous demain à 08h00, appel sans réponse ce soir,
        créneau de rappel 12h00-14h00 → relance programmée demain à 12h00,
        QUATRE HEURES APRÈS le rendez-vous. RingBack aurait appelé quelqu'un
        pour déplacer un rendez-vous déjà passé — ou qu'il venait de manquer.
        C'est le cas courant d'une campagne qui vide le lendemain.
        """
        contact, relances, campagne, quand = self._relance_sur_un_rendezvous(
            datetime.time(8, 0))
        self.assertEqual(relances, [], "une relance sonnerait après le rendez-vous")
        # Il RESTE quelque chose à faire, et seule une personne peut le faire à
        # temps : le contact part vers un humain, avec la raison en clair.
        self.assertEqual(contact["etat"], "à rappeler par un humain")
        self.assertIn("AUCUNE relance", contact["detail"])
        self.assertIn("trop tard", contact["detail"])
        self.assertIn(f"{quand:%d/%m/%Y}", contact["detail"])
        # Et le cahier le porte : c'est un travail à faire, pas un silence.
        genres = [c["genre"] for c in
                  self.application.base.changements_de_campagne(campagne)]
        self.assertIn("humain", genres)

    def test_une_relance_utile_reste_programmee(self):
        """⚠ LA CONTRE-ÉPREUVE, et elle compte : son cas réel du 18/08 était
        une relance à 12h00 pour un rendez-vous à 15h40 — elle SERT, et elle
        doit rester. Sans ce contrôle, un garde-fou qui supprimerait toutes les
        relances passerait au vert."""
        contact, relances, _, quand = self._relance_sur_un_rendezvous(
            datetime.time(15, 40))
        self.assertEqual(len(relances), 1)
        self.assertLess(relances[0]["echeance"],
                        quand.isoformat(timespec="minutes"))
        self.assertEqual(contact["etat"], "à recontacter")

    def test_un_rendez_vous_deja_passe_garde_sa_relance(self):
        """⚠ LA SECONDE CONDITION, celle que le banc m'a arrachée.

        Il ne suffit pas que l'échéance tombe après le rendez-vous : encore
        faut-il que ce rendez-vous soit ENCORE DEVANT NOUS. Une campagne de
        « rappel de rendez-vous MANQUÉS » travaille par construction sur des
        dates passées — la relance n'y est pas trop tard, elle EST le suivi.
        Ma première version envoyait vers un humain tous les rappels de manqués
        du produit : onze contrôles du banc l'ont arrêtée.
        """
        base = self.application.base
        preferences = self.application.preferences
        horaires.definir_semaine(preferences,
                                 {jour: [(8 * 60, 19 * 60)] for jour in range(7)})
        preferences.definir(themes.CLE_PLAGE_DEBUT, "08:00")
        preferences.definir(themes.CLE_PLAGE_FIN, "19:00")
        passe = (datetime.datetime.now()
                 - datetime.timedelta(days=10)).replace(hour=9, minute=0,
                                                        second=0, microsecond=0)
        client = base.ajouter_client("M. Manque", "+33 6 00 00 00 53")
        rdv = base.ajouter_rendezvous(client, passe.isoformat(timespec="minutes"),
                                      "Séance", statut="manqué")
        campagne = base.creer_campagne("Rappel manqué", "rappel_rdv",
                                       mission="Bonjour.")
        contact = base.ajouter_contact_campagne(
            campagne, 1, "M. Manque", "+33 6 00 00 00 53", rendezvous_id=rdv)
        assistant._apres_non_joint(
            base, preferences, base.obtenir_campagne(campagne),
            {"recontacter": True, "relance_mode": "creneau",
             "relance_creneau_debut": "12:00", "relance_creneau_fin": "14:00",
             "relance_max": 3},
            contact, "no_answer",
            maintenant=datetime.datetime.combine(datetime.date.today(),
                                                 datetime.time(18, 0)))
        # LA RELANCE RESTE : c'est tout l'objet d'un rappel de manqué.
        self.assertEqual(len(base.relances_de_campagne(campagne)), 1)
        self.assertEqual(base.obtenir_contact_campagne(contact)["etat"],
                         "à recontacter")

    def test_un_champ_de_creneaux_par_duree_a_replacer(self):
        """⚠ SA DEMANDE DU 18/08/2026, mot pour mot : « il faut un champ texte
        pour les rendez-vous possibles pour toutes les longueurs de rendez-vous
        que l'on retrouve dans le déplacement, 1 créneau, 2 créneaux etc. »

        Le stock portait bien ses deux listes, mais COLLÉES DANS UN SEUL
        CHAMP : impossible d'en corriger une sans toucher l'autre, et
        l'intitulé ne disait pas laquelle était laquelle.
        """
        base, preferences = self.application.base, self.application.preferences
        horaires.definir_semaine(preferences,
                                 {jour: [(8 * 60, 12 * 60), (14 * 60, 18 * 60)]
                                  for jour in range(5)})
        pas = horaires.pas_minutes(preferences)
        jour = datetime.date.today() + datetime.timedelta(days=3)
        while jour.weekday() >= 5:
            jour += datetime.timedelta(days=1)
        for rdv in base.tous_les_rendezvous():
            if rdv["horaire"][:10] == jour.isoformat():
                base.mettre_a_jour_rendezvous(rdv["id"], statut="ignoré")
        # DEUX DURÉES : trois rendez-vous d'un créneau, deux de deux créneaux.
        attendus, rang = {1: 3, 2: 2}, 0
        for tranches, combien in attendus.items():
            for _ in range(combien):
                quand = datetime.datetime.combine(
                    jour, datetime.time(hour=8 + rang, minute=0))
                client = base.ajouter_client(f"M. Duree {rang:02d}",
                                             f"+33 6 00 00 00 {60 + rang:02d}")
                base.ajouter_rendezvous(
                    client, quand.isoformat(timespec="minutes"), "Séance",
                    duree_tranches=tranches)
                rang += 1
        _, page = self._poster("/assistant/nature", {"nature": "deplacement"})
        b = self._brouillon(page)
        formulaire = {"b": b, "action": "continuer", "ordre": "liste"}
        formulaire.update(self.INFOS["deplacement"])
        for code in self.CHAMPS_CALCULES:
            valeur = self._valeur_affichee(page, code)
            if valeur is not None:
                formulaire[code] = valeur
        self._poster("/assistant/message", formulaire)
        annee, semaine, _ = jour.isocalendar()
        self._poster("/assistant/importer",
                     {"b": b, "mode": "rendezvous", "source": "a_venir",
                      "annee": str(annee), "semaine": str(semaine),
                      "jour": jour.isoformat()})
        _, etape2 = self._obtenir(f"/assistant/message?b={b}")

        # UN CHAMP PAR DURÉE, chacun avec son intitulé et son compte.
        zones = re.findall(
            r'<textarea name="info_creneaux_remplacement"[^>]*>(.*?)</textarea>',
            etape2, re.S)
        self.assertEqual(len(zones), 2, "les listes sont encore dans un seul champ")
        for tranches, combien in attendus.items():
            with self.subTest(tranches=tranches):
                self.assertIn(f"pour un rendez-vous de {tranches * pas} minutes",
                              etape2)
                self.assertIn(f"{combien} rendez-vous de cette durée", etape2)
        # ⚠ ET CHAQUE CHAMP PORTE LES PLACES DE SA DURÉE, pas celles de
        # l'autre : un champ bien étiqueté qui montre la mauvaise liste serait
        # pire que le champ unique.
        for indice, tranches in enumerate(sorted(attendus)):
            tiennent = set(horaires.places_negociables(
                base, preferences, tranches=tranches,
                a_deplacer=attendus[tranches],
                sauf_jours=(jour.isoformat(),)))
            for date in MOTIF_DATE_PARLEE.findall(
                    html.unescape(zones[indice])):
                self.assertIn(themes.lire_date(date), tiennent,
                              f"{date} ne tient pas {tranches * pas} minutes")

        # ⚠ ET CE QU'IL TAPE DANS CHAQUE CHAMP REVIENT À SA DURÉE. Sans ce
        # contrôle, une recomposition qui inverserait les deux listes passerait
        # au vert : l'aller marche, c'est le RETOUR qui se casse en silence.
        formulaire["info_creneaux_remplacement"] = ["le 01/01/2027 à 09h00",
                                                    "le 02/01/2027 à 10h00"]
        self._poster("/assistant/message", formulaire)
        infos = self.application.obtenir_brouillon_assistant(b)["infos"]
        stock = infos["creneaux_remplacement"]
        listes = assistant.listes_par_duree(preferences, stock, attendus)
        self.assertEqual(listes[1], "le 01/01/2027 à 09h00")
        self.assertEqual(listes[2], "le 02/01/2027 à 10h00")

    def test_une_seule_duree_garde_un_seul_champ(self):
        """La contre-épreuve : quand tout le monde a la même durée, un second
        champ vide n'apporterait rien — il ferait douter."""
        _, page = self._poster("/assistant/nature", {"nature": "deplacement"})
        b = self._brouillon(page)
