    # ------------------------------------------------- ① LA NON-RÉGRESSION
    def test_un_echec_du_contact_se_comporte_exactement_comme_avant(self):
        """CE QUI NE DOIT PAS BOUGER : le contact qui ne décroche pas.

        Tentative comptée, relance programmée, campagne terminée — le
        comportement d'origine, à la lettre. C'est la moitié qui compte le
        plus de la distinction : on n'a pas « adouci » les vrais échecs.
        """
        self.faux.etats[:] = [{"status": "no_answer"}]   # personne ne décroche
        campagne_id = self._campagne_de_trois()
        campagne, contacts = self._derouler_en_reel(campagne_id)
        base = self.application.base
        self.assertEqual(campagne["statut"], "terminée")
        self.assertIsNone(campagne["raison_pause"])
        self.assertEqual(len(self.faux.creations), 3)    # les trois appelés
        for contact in contacts:
            self.assertEqual(contact["etat"], "à recontacter")
            self.assertEqual(contact["issue"], "no_answer")
            self.assertEqual(len(base.appels_du_contact_campagne(contact["id"])),
                             1)                          # LA tentative comptée
        planifiees = [r for r in base.relances_de_campagne(campagne_id)
                      if r["statut"] == "planifiée"]
        self.assertEqual(len(planifiees), 3)             # relances programmées
        self.assertEqual(self._lignes_audit()[0]["statut"], "pas de réponse")

