    def _au_dela_du_plafond(self, campagne_id, plafond="1"):
        """Un contact qui a DÉJÀ épuisé son plafond de rappels."""
        base = self.application.base
        campagne = base.obtenir_campagne(campagne_id)
        configuration = assistant.configuration_campagne(campagne)
        configuration["options"]["relance_max"] = plafond
        base.definir_configuration_campagne(campagne_id,
                                            json.dumps(configuration))
        contact = base.contacts_de_campagne(campagne_id)[0]
        for tentative in range(int(plafond) + 1):
            base.ajouter_appel_campagne(campagne_id, contact["id"], tentative,
                                        issue="no_answer")
        return (base.obtenir_campagne(campagne_id), contact,
                assistant.configuration_campagne(
                    base.obtenir_campagne(campagne_id))["options"])

    def test_le_maximum_de_rappels_s_applique_en_simulation_aussi(self):
        """⚠ SA DÉCISION DU 21/08/2026, qui remplace celle du 18/08.

        Le 18/08 il avait demandé l'inverse — « en mode simulation, il ne faut
        pas faire la finalité du plafond atteint » — et c'était pour une bonne
        raison : ses campagnes d'essai s'arrêtaient là sans qu'il voie la suite.
        Deux choses ont changé depuis :

        · CE QUI LE GÊNAIT EST RÉGLÉ AUTREMENT : au maximum de rappels, une
          campagne de déplacement annule désormais le rendez-vous et renvoie la
          personne vers un rappel humain (20/08). Ce n'est plus un cul-de-sac.

        · LA LEVÉE N'AVAIT AUCUNE BORNE, et c'est un essai qui l'a montré :
          maximum réglé à 3, TREIZE rappels armés en douze tours, sans fin. Une
          simulation qui se comporte autrement que le réel ne prédit plus rien.

        On mesure la règle à son point de passage — `_apres_non_joint`, par où
        passe TOUT non-joint, de quelque campagne que ce soit.
        """
        base = self.application.base
        campagne_id = self._campagne_de_trois()
        campagne, contact, options = self._au_dela_du_plafond(campagne_id)
        # Les appels sont SIMULÉS ici — et cela ne change plus rien.
        self.assertIsInstance(self.application.planif.client_appels,
                              calle_client.AppelSimule)
        assistant._apres_non_joint(base, self.application.preferences,
                                   campagne, options, contact["id"],
                                   "no_answer")
        fiche = base.obtenir_contact_campagne(contact["id"])
        self.assertEqual(fiche["etat"], "injoignable")
        self.assertIn("maximum de rappels atteint", fiche["detail"])
        # Et plus aucun rappel n'est armé : la chaîne s'arrête pour de bon.
        self.assertEqual(
            [r for r in base.relances_de_campagne(campagne_id)
             if r["statut"] == "planifiée" and r["contact_id"] == contact["id"]],
            [])

    def test_la_chaine_de_rappels_a_donc_une_fin_en_simulation(self):
        """⚠ LE FAIT MESURÉ QUI A FAIT CHANGER LA RÈGLE : sans maximum, les
        rappels s'enchaînaient SANS FIN en simulation. Ici on les lance jusqu'au
        bout — le numéro se termine par 53, personne ne décroche jamais — et la
        chaîne doit s'arrêter d'elle-même, sans qu'on ait à clore la campagne."""
        base = self.application.base
        horaire = (datetime.datetime.now() + datetime.timedelta(days=3)
                   ).replace(hour=9, minute=0, second=0,
                             microsecond=0).isoformat(timespec="minutes")
        campagne_id = self._campagne(
            "confirmation",
            [f"M. Jamais Là;+33 6 00 00 00 53;{horaire};Séance"],
            relance_max="2", relance_mode="delai", relance_delai="0")
        assistant.executer_campagne(self.application, campagne_id)
        tours = 0
        while [r for r in base.relances_de_campagne(campagne_id)
               if r["statut"] == "planifiée"]:
            tours += 1
            self.assertLess(tours, 8, "la chaîne de rappels ne s'arrête pas")
            campagnes.executer_relances_dues(base, self.application.planif,
                                             self.application.preferences)
        fiche = base.contacts_de_campagne(campagne_id)[0]
        self.assertEqual(fiche["etat"], "injoignable")
        self.assertIn("maximum de rappels atteint", fiche["detail"])
        # Le compte des tentatives ne dépasse pas ce qu'il a réglé.
        self.assertLessEqual(
            len(base.appels_du_contact_campagne(fiche["id"])), 3)

    def test_pour_de_vrais_appels_la_regle_est_la_meme(self):
        """⚠ CE QUI COMPTE LE PLUS : simulation et réel se comportent PAREIL.
        C'est tout l'intérêt d'une simulation — elle ne vaut que si elle
        prédit ce qui se passera pour de vrai."""
        base = self.application.base
